def _json_default(value):
    if isinstance(value, (date, datetime)):
        return value.isoformat()
    if isinstance(value, Decimal):
        return str(value)
    if isinstance(value, UUID):
        return str(value)
    return str(value)


def _safe_json(value):
    if isinstance(value, dict):
        return {str(key): _safe_json(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_safe_json(item) for item in value]
    if isinstance(value, (date, datetime, Decimal, UUID)):
        return _json_default(value)
    try:
        json.dumps(value)
        return value
    except TypeError:
        return str(value)


def _normalise_openai_model_name(value: str | None) -> str:
    text = str(value or "").strip().strip("\"'")
    if not text:
        return OPENAI_MODEL_FALLBACKS[0]
    return re.sub(r"[\s_]+", "-", text).lower()


def _openai_model_candidates(value: str | None) -> list[str]:
    preferred = _normalise_openai_model_name(value)
    candidates = [preferred, *OPENAI_MODEL_FALLBACKS]
    return list(dict.fromkeys(candidate for candidate in candidates if candidate))


def _openai_error_detail(response: httpx.Response) -> tuple[str, str]:
    try:
        payload = response.json()
    except ValueError:
        return response.text[:500], ""
    error = payload.get("error") if isinstance(payload, dict) else None
    if isinstance(error, dict):
        return str(error.get("message") or payload)[:500], str(error.get("code") or "")
    return str(payload)[:500], ""


async def _post_openai_responses(
    request_body: dict,
    purpose: str,
    preferred_model: str | None = None,
    timeout_seconds: float | None = None,
    user_id: str | None = None,
    feature: str | None = None,
    page: str | None = None,
) -> dict:
    settings = get_settings()
    attempted: list[str] = []
    last_message = ""
    requested_model = preferred_model if str(preferred_model or "").strip() else settings.openai_model
    timeout = float(timeout_seconds or OPENAI_INSIGHTS_TIMEOUT_SECONDS)
    inferred_feature, inferred_page = infer_openai_feature_page(purpose)
    feature_name = str(feature or inferred_feature or "openai-core")
    page_name = str(page or inferred_page or "settings")
    request_bytes = len(json.dumps(request_body, default=_json_default))
    async with httpx.AsyncClient(timeout=timeout) as client:
        for model_name in _openai_model_candidates(requested_model):
            attempted.append(model_name)
            started = time.monotonic()
            try:
                response = await client.post(
                    "https://api.openai.com/v1/responses",
                    headers={"Authorization": f"Bearer {settings.openai_api_key}", "Content-Type": "application/json"},
                    json={**request_body, "model": model_name},
                )
            except httpx.TimeoutException as exc:
                elapsed_ms = int((time.monotonic() - started) * 1000)
                record_usage_event(
                    provider="openai",
                    user_id=user_id,
                    feature=feature_name,
                    page=page_name,
                    operation=purpose,
                    endpoint="/v1/responses",
                    model=model_name,
                    request_bytes=request_bytes,
                    response_bytes=0,
                    status_code=504,
                    success=False,
                    error_code="timeout",
                    error_message=str(exc),
                    duration_ms=elapsed_ms,
                )
                raise HTTPException(
                    status_code=status.HTTP_504_GATEWAY_TIMEOUT,
                    detail=(
                        f"OpenAI {purpose} timed out after {int(timeout)} seconds. "
                        "This usually means the uploaded report is very large or complex. "
                        "Retry will continue in staged mode for ME Report spreadsheets."
                    ),
                ) from exc
            except httpx.HTTPError as exc:
                elapsed_ms = int((time.monotonic() - started) * 1000)
                record_usage_event(
                    provider="openai",
                    user_id=user_id,
                    feature=feature_name,
                    page=page_name,
                    operation=purpose,
                    endpoint="/v1/responses",
                    model=model_name,
                    request_bytes=request_bytes,
                    response_bytes=0,
                    status_code=502,
                    success=False,
                    error_code="network_error",
                    error_message=str(exc),
                    duration_ms=elapsed_ms,
                )
                raise HTTPException(
                    status_code=status.HTTP_502_BAD_GATEWAY,
                    detail=f"OpenAI {purpose} failed due to a network error: {exc}",
                ) from exc
            elapsed_ms = int((time.monotonic() - started) * 1000)
            response_bytes = len(response.content or b"")
            if not response.is_error:
                payload = response.json()
                input_tokens, output_tokens, total_tokens = parse_openai_usage_tokens(payload)
                estimated_cost = estimate_openai_cost_usd(model_name, input_tokens, output_tokens)
                record_usage_event(
                    provider="openai",
                    user_id=user_id,
                    feature=feature_name,
                    page=page_name,
                    operation=purpose,
                    endpoint="/v1/responses",
                    model=model_name,
                    request_bytes=request_bytes,
                    response_bytes=response_bytes,
                    input_tokens=input_tokens,
                    output_tokens=output_tokens,
                    total_tokens=total_tokens,
                    estimated_cost_usd=estimated_cost,
                    status_code=response.status_code,
                    success=True,
                    duration_ms=elapsed_ms,
                )
                return payload
            message, code = _openai_error_detail(response)
            last_message = message
            record_usage_event(
                provider="openai",
                user_id=user_id,
                feature=feature_name,
                page=page_name,
                operation=purpose,
                endpoint="/v1/responses",
                model=model_name,
                request_bytes=request_bytes,
                response_bytes=response_bytes,
                status_code=response.status_code,
                success=False,
                error_code=code or "api_error",
                error_message=message,
                duration_ms=elapsed_ms,
            )
            lowered = message.lower()
            missing_model = code == "model_not_found" or "model" in lowered and "does not exist" in lowered
            if missing_model:
                continue
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail=f"OpenAI {purpose} failed with status {response.status_code}: {message}",
            )
    raise HTTPException(
        status_code=status.HTTP_502_BAD_GATEWAY,
        detail=(
            f"OpenAI {purpose} failed because none of the configured model names are available. "
            f"Tried: {', '.join(attempted)}. Last error: {last_message}"
        ),
    )


def _with_jenius_signature(message: str) -> str:
    text = str(message or "").strip()
    if not text:
        return JENIUS_NOTE_SIGNATURE
    if text.lower().endswith(JENIUS_NOTE_SIGNATURE.lower()):
        return text
    return f"{text} {JENIUS_NOTE_SIGNATURE}"


def record_audit_event(entity_type: str, entity_id: str, event_type: str, payload: dict, user_id: str | None) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO audit_events (entity_type, entity_id, event_type, payload, user_id)
                VALUES (%s, %s, %s, %s::jsonb, %s)
                """,
                (entity_type, entity_id, event_type, json.dumps(payload, default=_json_default), user_id),
            )
        connection.commit()


def _normalised_tenant_name(value: str | None) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").strip().lower()).strip()


def _tenant_name_matches(candidate_name: str | None, target_name: str | None) -> bool:
    candidate = _normalised_tenant_name(candidate_name)
    target = _normalised_tenant_name(target_name)
    if not candidate or not target:
        return False
    if candidate == target:
        return True
    return target in candidate or candidate in target


def _is_preferred_xero_tenant(connection_row: dict, preferred_tenant_name: str | None) -> bool:
    tenant_name = connection_row.get("tenant_name")
    preferred_names = [str(preferred_tenant_name or "").strip(), *MASTER_XERO_TENANT_HINTS]
    return any(_tenant_name_matches(tenant_name, preferred_name) for preferred_name in preferred_names if preferred_name)


def _xero_connection_sort_key(connection_row: dict, preferred_tenant_name: str | None = None) -> tuple[int, int, datetime, datetime]:
    preferred = 1 if _is_preferred_xero_tenant(connection_row, preferred_tenant_name) else 0
    tenant_type = str(connection_row.get("tenant_type") or "").upper()
    accounting_tenant = 1 if tenant_type == "ORGANISATION" else 0
    updated_at = connection_row.get("updated_at") or datetime.min.replace(tzinfo=timezone.utc)
    created_at = connection_row.get("created_at") or datetime.min.replace(tzinfo=timezone.utc)
    return preferred, accounting_tenant, updated_at, created_at


def list_xero_connections_for_user(user_id: str, include_fallback: bool = True) -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM xero_connections
                WHERE user_id = %s
                ORDER BY updated_at DESC NULLS LAST, created_at DESC
                """,
                (user_id,),
            )
            rows = cursor.fetchall() or []
            if rows or not include_fallback:
                connection.commit()
                return rows
            cursor.execute(
                """
                SELECT *
                FROM xero_connections
                ORDER BY updated_at DESC NULLS LAST, created_at DESC
                LIMIT 1
                """
            )
            fallback_row = cursor.fetchone()
        connection.commit()
    return [fallback_row] if fallback_row else []


def get_xero_connection_for_user(user_id: str) -> dict:
    rows = list_xero_connections_for_user(user_id, include_fallback=True)
    if not rows:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="User has not linked Xero yet.")
    preferred_tenant_name = get_settings().xero_primary_tenant_name
    return max(rows, key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name))


def get_master_xero_connection_for_user(user_id: str) -> dict:
    rows = list_xero_connections_for_user(user_id, include_fallback=False)
    if not rows:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="User has not linked Xero yet.")
    preferred_tenant_name = get_settings().xero_primary_tenant_name
    matching_rows = [row for row in rows if _is_preferred_xero_tenant(row, preferred_tenant_name)]
    if not matching_rows:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                f"Master Xero tenant '{preferred_tenant_name or 'jaccountancy'}' is not connected. "
                "Connect the Jaccountancy tenant before using Debtors, LPC, or Bad Debt."
            ),
        )
    return max(matching_rows, key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name))


def xero_connection_for_user_tenant(user: dict, tenant_id: str | None = None, include_fallback: bool = True) -> dict:
    requested_tenant_id = str(tenant_id or "").strip()
    if not requested_tenant_id:
        return get_xero_connection_for_user(user["id"])
    rows = list_xero_connections_for_user(user["id"], include_fallback=include_fallback)
    row = next((item for item in rows if str(item.get("tenant_id") or "").strip() == requested_tenant_id), None)
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Selected Xero connection is unavailable.")
    return row


def barclays_configured() -> bool:
    settings = get_settings()
    return all(
        [
            str(settings.barclays_client_id or "").strip(),
            str(settings.barclays_client_secret or "").strip(),
            str(settings.barclays_redirect_uri or "").strip(),
            str(settings.barclays_authorize_url or "").strip(),
            str(settings.barclays_token_url or "").strip(),
            str(settings.barclays_pisp_base_url or "").strip(),
        ]
    )


def barclays_connect_status_payload(user: dict) -> dict:
    settings = get_settings()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM barclays_connections WHERE user_id = %s", (user["id"],))
            row = cursor.fetchone()
        connection.commit()
    now = utcnow()
    expires_at = row.get("expires_at") if row else None
    connected = bool(row and str(row.get("access_token") or "").strip() and (expires_at is None or expires_at > now))
    return {
        "configured": barclays_configured(),
        "connected": connected,
        "status": str((row or {}).get("status") or ("connected" if connected else "disconnected")),
        "expiresAt": _iso(expires_at) if expires_at else "",
        "consentId": str((row or {}).get("consent_id") or "").strip(),
        "consentStatus": str((row or {}).get("consent_status") or "").strip(),
        "pispBaseUrl": str(settings.barclays_pisp_base_url or "").strip(),
    }


def build_barclays_authorize_url(user: dict, redirect_to: str) -> str:
    settings = get_settings()
    if not barclays_configured():
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Barclays Open Banking is not configured.")
    state = start_oauth_state(
        redirect_to=redirect_to,
        user_id=user["id"],
        provider="barclays",
    )
    query = urlencode(
        {
            "response_type": "code",
            "client_id": str(settings.barclays_client_id or "").strip(),
            "redirect_uri": str(settings.barclays_redirect_uri or "").strip(),
            "scope": str(settings.barclays_scope or "payments").strip(),
            "state": state,
        }
    )
    return f"{str(settings.barclays_authorize_url).rstrip('?')}?{query}"


async def _barclays_exchange_code_for_tokens(code: str) -> dict:
    settings = get_settings()
    payload = {
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": str(settings.barclays_redirect_uri or "").strip(),
        "client_id": str(settings.barclays_client_id or "").strip(),
        "client_secret": str(settings.barclays_client_secret or "").strip(),
    }
    async with httpx.AsyncClient(timeout=45) as client:
        try:
            response = await client.post(
                str(settings.barclays_token_url or "").strip(),
                data=payload,
                headers={"Accept": "application/json"},
            )
        except httpx.RequestError as exc:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Barclays token request failed: {exc}") from exc
    if response.is_error:
        try:
            details = response.json()
        except ValueError:
            details = response.text[:400]
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Barclays token exchange failed: {details}")
    try:
        return response.json()
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail="Invalid Barclays token response.") from exc


def store_barclays_connection(user: dict, token_payload: dict, consent_id: str = "", consent_status: str = "") -> dict:
    now = utcnow()
    expires_in = int(token_payload.get("expires_in") or 3600)
    expires_at = now + timedelta(seconds=max(60, expires_in))
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO barclays_connections (
                    user_id, status, access_token, refresh_token, token_type, scope,
                    expires_at, consent_id, consent_status, connected_at, created_at, updated_at
                )
                VALUES (%s, 'connected', %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (user_id) DO UPDATE
                SET status = 'connected',
                    access_token = EXCLUDED.access_token,
                    refresh_token = CASE
                        WHEN COALESCE(EXCLUDED.refresh_token, '') <> '' THEN EXCLUDED.refresh_token
                        ELSE barclays_connections.refresh_token
                    END,
                    token_type = EXCLUDED.token_type,
                    scope = EXCLUDED.scope,
                    expires_at = EXCLUDED.expires_at,
                    consent_id = CASE
                        WHEN COALESCE(EXCLUDED.consent_id, '') <> '' THEN EXCLUDED.consent_id
                        ELSE barclays_connections.consent_id
                    END,
                    consent_status = CASE
                        WHEN COALESCE(EXCLUDED.consent_status, '') <> '' THEN EXCLUDED.consent_status
                        ELSE barclays_connections.consent_status
                    END,
                    updated_at = EXCLUDED.updated_at
                RETURNING *
                """,
                (
                    user["id"],
                    str(token_payload.get("access_token") or "").strip(),
                    str(token_payload.get("refresh_token") or "").strip(),
                    str(token_payload.get("token_type") or "Bearer").strip(),
                    str(token_payload.get("scope") or "").strip(),
                    expires_at,
                    str(consent_id or "").strip(),
                    str(consent_status or "").strip(),
                    now,
                    now,
                    now,
                ),
            )
            row = cursor.fetchone() or {}
        connection.commit()
    return row


async def complete_barclays_oauth_callback(user: dict, code: str) -> dict:
    token_payload = await _barclays_exchange_code_for_tokens(code)
    return store_barclays_connection(user, token_payload)


async def _barclays_refresh_connection_if_required(connection_row: dict) -> dict:
    refresh_token = str(connection_row.get("refresh_token") or "").strip()
    expires_at = connection_row.get("expires_at")
    if expires_at and expires_at > (utcnow() + timedelta(minutes=2)):
        return connection_row
    if not refresh_token:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Barclays connection has expired. Reconnect Barclays.")
    settings = get_settings()
    payload = {
        "grant_type": "refresh_token",
        "refresh_token": refresh_token,
        "client_id": str(settings.barclays_client_id or "").strip(),
        "client_secret": str(settings.barclays_client_secret or "").strip(),
    }
    async with httpx.AsyncClient(timeout=45) as client:
        try:
            response = await client.post(
                str(settings.barclays_token_url or "").strip(),
                data=payload,
                headers={"Accept": "application/json"},
            )
        except httpx.RequestError as exc:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Unable to refresh Barclays token: {exc}") from exc
    if response.is_error:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unable to refresh Barclays token. Reconnect Barclays.")
    token_payload = response.json() if response.content else {}
    user = {"id": connection_row.get("user_id")}
    return store_barclays_connection(user, token_payload, connection_row.get("consent_id") or "", connection_row.get("consent_status") or "")


async def _barclays_connected_row_for_user(user: dict) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM barclays_connections WHERE user_id = %s", (user["id"],))
            row = cursor.fetchone()
        connection.commit()
    if not row or not str(row.get("access_token") or "").strip():
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Barclays is not connected.")
    return await _barclays_refresh_connection_if_required(row)


async def _barclays_api_request(user: dict, method: str, path: str, payload: dict | None = None, idempotency_key: str | None = None) -> dict:
    settings = get_settings()
    connection_row = await _barclays_connected_row_for_user(user)
    headers = {
        "Authorization": f"Bearer {str(connection_row.get('access_token') or '').strip()}",
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    financial_id = str(settings.barclays_financial_id or "").strip()
    if financial_id:
        headers["x-fapi-financial-id"] = financial_id
    headers["x-idempotency-key"] = str(idempotency_key or uuid4())
    url = f"{str(settings.barclays_pisp_base_url or '').rstrip('/')}/{str(path).lstrip('/')}"
    async with httpx.AsyncClient(timeout=60) as client:
        try:
            response = await client.request(method.upper(), url, headers=headers, json=payload if payload is not None else None)
        except httpx.RequestError as exc:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Barclays API request failed: {exc}") from exc
    if response.is_error:
        try:
            detail_payload = response.json()
        except ValueError:
            detail_payload = response.text[:800]
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Barclays API {path} failed: {detail_payload}")
    if not response.content:
        return {}
    try:
        return response.json()
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Barclays API {path} returned invalid JSON.") from exc


def _month_start(value: date | datetime | None = None) -> date:
    if isinstance(value, datetime):
        value = value.date()
    value = value or utcnow().date()
    return value.replace(day=1)


def _parse_any_date(value) -> date | None:
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value or "").strip()
    if not text:
        return None
    iso_candidate = text[:10]
    try:
        return date.fromisoformat(iso_candidate)
    except ValueError:
        pass
    match = re.search(r"/Date\((\d+)", text)
    if match:
        try:
            millis = int(match.group(1))
            return datetime.fromtimestamp(millis / 1000, tz=timezone.utc).date()
        except (TypeError, ValueError, OSError):
            return None
    for fmt in (
        "%d %b %Y",
        "%d %B %Y",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%Y/%m/%d",
        "%Y-%m-%d",
    ):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    return None


def _payroll_headcount_employee_is_active(employee: dict) -> bool:
    status_value = str(
        employee.get("EmployeeStatus")
        or employee.get("Status")
        or employee.get("status")
        or ""
    ).strip().lower()
    if status_value in {"terminated", "inactive", "deleted", "archived"}:
        return False
    termination_date = (
        _parse_any_date(employee.get("TerminationDate"))
        or _parse_any_date(employee.get("EndDate"))
        or _parse_any_date(employee.get("DateOfLeaving"))
        or _parse_any_date(employee.get("TerminationDateUTC"))
        or _parse_any_date(employee.get("DateOfLeavingUTC"))
        or _parse_any_date(employee.get("LeaveDate"))
    )
    # Some payroll datasets use sentinel zero/min dates to indicate no termination.
    if termination_date and termination_date <= date(1970, 1, 2):
        termination_date = None
    if termination_date and termination_date < utcnow().date():
        return False
    return True


def _payroll_headcount_payrun_date(payrun: dict) -> date | None:
    return (
        _parse_any_date(payrun.get("PaymentDate"))
        or _parse_any_date(payrun.get("paymentDate"))
        or _parse_any_date(payrun.get("PayDate"))
        or _parse_any_date(payrun.get("PayRunPeriodEndDate"))
        or _parse_any_date(payrun.get("payRunPeriodEndDate"))
        or _parse_any_date(payrun.get("PayPeriodEndDate"))
        or _parse_any_date(payrun.get("payPeriodEndDate"))
        or _parse_any_date(payrun.get("PeriodEndDate"))
        or _parse_any_date(payrun.get("periodEndDate"))
        or _parse_any_date(payrun.get("PayRunPeriodStartDate"))
        or _parse_any_date(payrun.get("payRunPeriodStartDate"))
        or _parse_any_date(payrun.get("PayPeriodStartDate"))
        or _parse_any_date(payrun.get("payPeriodStartDate"))
        or _parse_any_date(payrun.get("PeriodStartDate"))
        or _parse_any_date(payrun.get("periodStartDate"))
        or _parse_any_date(payrun.get("Date"))
        or _parse_any_date(payrun.get("date"))
    )


