def _payroll_headcount_month_start_iso(value) -> str:
    parsed_date = _parse_any_date(value)
    if parsed_date:
        return parsed_date.isoformat()
    text = str(value or "").strip()
    return text[:10] if text else ""


def _payroll_headcount_from_payrun_details(payrun_details_payload: dict) -> int:
    if not isinstance(payrun_details_payload, dict):
        return 0
    payruns = payrun_details_payload.get("PayRuns")
    if isinstance(payruns, list) and payruns:
        payrun = payruns[0] if isinstance(payruns[0], dict) else {}
    elif isinstance(payruns, dict):
        payrun = payruns
    else:
        payrun = payrun_details_payload if isinstance(payrun_details_payload, dict) else {}
    payslips = payrun.get("Payslips") if isinstance(payrun, dict) else []
    if not isinstance(payslips, list):
        return 0
    return sum(
        1
        for payslip in payslips
        if isinstance(payslip, dict)
        and str(payslip.get("NetPay") if payslip.get("NetPay") is not None else "").strip() != ""
    )


def _payroll_headcount_effective_count(active_employee_count: int, latest_payrun_headcount: int | None) -> int:
    base_count = max(0, int(active_employee_count or 0))
    payrun_count = int(latest_payrun_headcount) if latest_payrun_headcount is not None else 0
    if payrun_count <= 0:
        return base_count
    return max(base_count, payrun_count)


def _payroll_headcount_rows(payload: dict, plural_key: str, singular_key: str) -> list[dict]:
    if not isinstance(payload, dict):
        return []
    plural_camel = f"{plural_key[:1].lower()}{plural_key[1:]}" if plural_key else ""
    singular_camel = f"{singular_key[:1].lower()}{singular_key[1:]}" if singular_key else ""
    candidate_keys = [
        plural_key,
        plural_key.lower(),
        plural_camel,
        singular_key,
        singular_key.lower(),
        singular_camel,
    ]
    candidate = (
        next((payload.get(key) for key in candidate_keys if key and payload.get(key) not in (None, "")), None)
        or []
    )
    if isinstance(candidate, list):
        return [row for row in candidate if isinstance(row, dict)]
    if isinstance(candidate, dict):
        for nested in (candidate.get(key) for key in candidate_keys if key):
            if isinstance(nested, list):
                return [row for row in nested if isinstance(row, dict)]
            if isinstance(nested, dict) and any(
                key in nested
                for key in (
                    "EmployeeID",
                    "employeeID",
                    "EmployeeId",
                    "employeeId",
                    "PayRunID",
                    "payRunID",
                    "PayRunId",
                    "payRunId",
                    "EmployeeStatus",
                    "employeeStatus",
                )
            ):
                return [nested]
        if any(
            key in candidate
            for key in (
                "EmployeeID",
                "employeeID",
                "EmployeeId",
                "employeeId",
                "PayRunID",
                "payRunID",
                "PayRunId",
                "payRunId",
                "EmployeeStatus",
                "employeeStatus",
            )
        ):
            return [candidate]
    return []


def _payroll_overview_decimal(value) -> Decimal:
    if value in (None, ""):
        return Decimal("0")
    try:
        return Decimal(str(value))
    except Exception:
        return Decimal("0")


def _payroll_overview_numeric_decimal(value) -> Decimal:
    if isinstance(value, Decimal):
        return value
    if isinstance(value, (int, float)):
        return Decimal(str(value))
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if not text:
            return Decimal("0")
        text = re.sub(r"[^0-9\.\-]", "", text)
        if not text or text in {"-", ".", "-."}:
            return Decimal("0")
        try:
            return Decimal(text)
        except Exception:
            return Decimal("0")
    return Decimal("0")


def _payroll_overview_normalise_key(value) -> str:
    return re.sub(r"[^a-z0-9]", "", str(value or "").strip().lower())


def _payroll_overview_find_numeric_value(payload, candidate_keys: list[str]) -> Decimal:
    wanted = {_payroll_overview_normalise_key(key) for key in candidate_keys if str(key or "").strip()}
    if not wanted:
        return Decimal("0")
    queue = [payload]
    visited: set[int] = set()
    while queue:
        node = queue.pop(0)
        if isinstance(node, list):
            queue.extend(node)
            continue
        if not isinstance(node, dict):
            continue
        marker = id(node)
        if marker in visited:
            continue
        visited.add(marker)
        for key, value in node.items():
            normalised = _payroll_overview_normalise_key(key)
            if normalised in wanted:
                numeric = _payroll_overview_numeric_decimal(value)
                if numeric != Decimal("0"):
                    return abs(numeric)
            if isinstance(value, (dict, list)):
                queue.append(value)
    return Decimal("0")


def _payroll_overview_sum_numeric_values(payload, candidate_keys: list[str]) -> Decimal:
    wanted = {_payroll_overview_normalise_key(key) for key in candidate_keys if str(key or "").strip()}
    if not wanted:
        return Decimal("0")
    queue = [payload]
    visited: set[int] = set()
    total = Decimal("0")
    while queue:
        node = queue.pop(0)
        if isinstance(node, list):
            queue.extend(node)
            continue
        if not isinstance(node, dict):
            continue
        marker = id(node)
        if marker in visited:
            continue
        visited.add(marker)
        for key, value in node.items():
            normalised = _payroll_overview_normalise_key(key)
            if normalised in wanted:
                total += abs(_payroll_overview_numeric_decimal(value))
            if isinstance(value, (dict, list)):
                queue.append(value)
    return total


def _payroll_overview_find_numeric_value_by_hints(
    payload,
    include_hints: list[str],
    exclude_hints: list[str] | None = None,
) -> Decimal:
    include = [_payroll_overview_normalise_key(item) for item in include_hints if str(item or "").strip()]
    exclude = {_payroll_overview_normalise_key(item) for item in (exclude_hints or []) if str(item or "").strip()}
    if not include:
        return Decimal("0")
    queue = [payload]
    visited: set[int] = set()
    best = Decimal("0")
    while queue:
        node = queue.pop(0)
        if isinstance(node, list):
            queue.extend(node)
            continue
        if not isinstance(node, dict):
            continue
        marker = id(node)
        if marker in visited:
            continue
        visited.add(marker)
        for key, value in node.items():
            normalised = _payroll_overview_normalise_key(key)
            if normalised:
                has_include = any(token in normalised for token in include)
                has_exclude = any(token and token in normalised for token in exclude)
                if has_include and not has_exclude:
                    numeric = abs(_payroll_overview_numeric_decimal(value))
                    if numeric > best:
                        best = numeric
            if isinstance(value, (dict, list)):
                queue.append(value)
    return best


