def _payroll_overview_payslip_rows(payload: dict) -> list[dict]:
    if not isinstance(payload, dict):
        return []
    keys = ("PaySlips", "Payslips", "paySlips", "payslips", "PaySlip", "Payslip", "paySlip", "payslip")
    for key in keys:
        candidate = payload.get(key)
        if isinstance(candidate, list):
            return [row for row in candidate if isinstance(row, dict)]
        if isinstance(candidate, dict):
            return [candidate]
    return []


def _payroll_overview_payslip_ids(payrun: dict) -> list[str]:
    if not isinstance(payrun, dict):
        return []
    rows = (
        payrun.get("Payslips")
        or payrun.get("PaySlips")
        or payrun.get("payslips")
        or payrun.get("paySlips")
        or []
    )
    if not isinstance(rows, list):
        rows = []
    seen: set[str] = set()
    ordered_ids: list[str] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        payslip_id = _payroll_overview_text(
            row.get("PayslipID")
            or row.get("PaySlipID")
            or row.get("payslipID")
            or row.get("paySlipID")
            or row.get("PayslipId")
            or row.get("PaySlipId")
            or row.get("payslipId")
            or row.get("paySlipId")
            or row.get("id")
            or row.get("ID")
        )
        if not payslip_id or payslip_id in seen:
            continue
        seen.add(payslip_id)
        ordered_ids.append(payslip_id)
    return ordered_ids


def _payroll_overview_employee_name(employee: dict) -> str:
    first = _payroll_overview_text(employee.get("FirstName"))
    last = _payroll_overview_text(employee.get("LastName"))
    full = " ".join(part for part in (first, last) if part).strip()
    if full:
        return full
    return (
        _payroll_overview_text(employee.get("FullName"))
        or _payroll_overview_text(employee.get("Name"))
        or _payroll_overview_text(employee.get("EmployeeID"))
        or "Employee"
    )


def _payroll_overview_status(payrun: dict) -> str:
    return _payroll_overview_text(
        payrun.get("PayRunStatus")
        or payrun.get("payRunStatus")
        or payrun.get("Status")
        or payrun.get("status")
        or payrun.get("state")
    ).upper() or "UNKNOWN"


def _payroll_overview_payrun_count(payrun: dict) -> int:
    for key in (
        "PayslipCount",
        "PayslipsCount",
        "PaySlipsCount",
        "payslipCount",
        "payslipsCount",
        "paySlipsCount",
        "EmployeeCount",
        "employeeCount",
    ):
        raw = payrun.get(key)
        if raw in (None, ""):
            continue
        try:
            return max(0, int(float(raw)))
        except Exception:
            continue
    return 0


def _payroll_overview_account_is_tax_liability(account: dict) -> bool:
    code = _payroll_overview_text(account.get("Code") or account.get("code")).lower()
    name = _payroll_overview_text(account.get("Name") or account.get("name")).lower()
    combined = f"{code} {name}"
    keywords = (
        "paye payable",
        "paye",
        "paye/nic",
        "payroll payable",
        "hmrc payroll",
        "nic payable",
        "national insurance payable",
    )
    if any(keyword in combined for keyword in keywords):
        return True
    account_type = _payroll_overview_text(account.get("Type") or account.get("type")).upper()
    account_class = _payroll_overview_text(account.get("Class") or account.get("class")).upper()
    if account_type in {"CURRLIAB", "LIABILITY"} and account_class in {"LIABILITY", "EQUITY", ""}:
        return "payroll" in combined or "hmrc" in combined or "tax" in combined
    return False


def _payroll_overview_account_is_pension_liability(account: dict) -> bool:
    code = _payroll_overview_text(account.get("Code") or account.get("code")).lower()
    name = _payroll_overview_text(account.get("Name") or account.get("name")).lower()
    combined = f"{code} {name}"
    keywords = (
        "pension payable",
        "workplace pension",
        "nest payable",
        "pension creditor",
        "auto enrolment pension",
        "auto-enrolment pension",
    )
    if any(keyword in combined for keyword in keywords):
        return True
    account_type = _payroll_overview_text(account.get("Type") or account.get("type")).upper()
    if account_type not in {"CURRLIAB", "LIABILITY"}:
        return False
    return "pension" in combined and ("payable" in combined or "creditor" in combined or "liability" in combined)


def _payroll_overview_account_balance(account: dict) -> Decimal:
    for key in (
        "CurrentBalance",
        "currentBalance",
        "Balance",
        "balance",
        "YTDBalance",
        "ytdBalance",
        "CurrentNetBalance",
        "currentNetBalance",
        "ClosingBalance",
        "closingBalance",
    ):
        raw = account.get(key)
        if raw in (None, ""):
            continue
        return _payroll_overview_decimal(raw)
    return Decimal("0")


def _payroll_overview_journal_line_credit_amount(line: dict) -> Decimal:
    if not isinstance(line, dict):
        return Decimal("0")
    debit_amount = Decimal("0")
    for key in ("Debit", "debit", "debit_amount", "DebitAmount", "debitAmount"):
        amount = _payroll_overview_numeric_decimal(line.get(key))
        if amount > Decimal("0"):
            debit_amount = amount
            break
    for key in ("Credit", "credit", "credit_amount", "CreditAmount", "creditAmount"):
        amount = _payroll_overview_numeric_decimal(line.get(key))
        if amount > Decimal("0"):
            return amount
    if debit_amount > Decimal("0"):
        return Decimal("0")
    for key in ("NetAmount", "netAmount", "net_amount", "LineAmount", "lineAmount", "line_amount", "Amount", "amount", "GrossAmount", "grossAmount", "gross_amount"):
        amount = _payroll_overview_decimal(line.get(key))
        if amount < Decimal("0"):
            return abs(amount)
    return Decimal("0")


def _payroll_overview_journal_line_debit_amount(line: dict) -> Decimal:
    if not isinstance(line, dict):
        return Decimal("0")
    credit_amount = Decimal("0")
    for key in ("Credit", "credit", "credit_amount", "CreditAmount", "creditAmount"):
        amount = _payroll_overview_numeric_decimal(line.get(key))
        if amount > Decimal("0"):
            credit_amount = amount
            break
    for key in ("Debit", "debit", "debit_amount", "DebitAmount", "debitAmount"):
        amount = _payroll_overview_numeric_decimal(line.get(key))
        if amount > Decimal("0"):
            return amount
    if credit_amount > Decimal("0"):
        return Decimal("0")
    for key in ("NetAmount", "netAmount", "net_amount", "LineAmount", "lineAmount", "line_amount", "Amount", "amount", "GrossAmount", "grossAmount", "gross_amount"):
        amount = _payroll_overview_decimal(line.get(key))
        if amount > Decimal("0"):
            return amount
    return Decimal("0")


def _payroll_overview_journal_line_is_tax_liability(line: dict, account: dict) -> bool:
    if _payroll_overview_account_is_tax_liability(account):
        return True
    description = _payroll_overview_normalise_key(
        _payroll_overview_text(line.get("Description") or line.get("description"))
    )
    if not description:
        return False
    if "pension" in description:
        return False
    return any(token in description for token in ("paye", "nic", "national insurance", "hmrc", "tax"))


def _payroll_overview_journal_line_is_pension_liability(line: dict, account: dict) -> bool:
    if _payroll_overview_account_is_pension_liability(account):
        return True
    description = _payroll_overview_normalise_key(
        _payroll_overview_text(line.get("Description") or line.get("description"))
    )
    if not description:
        return False
    return any(token in description for token in ("pension", "workplace pension", "nest", "auto enrolment", "autoenrolment"))


async def _payroll_overview_extract_posted_journal_payables(
    journals: list[dict],
    accounts: list[dict],
    reference_payrun: dict | None,
    *,
    user_id: str | None = None,
) -> tuple[Decimal, Decimal, dict]:
    def _canonical_account_id(value) -> str:
        raw = _payroll_overview_text(value)
        if not raw:
            return ""
        return raw.strip().strip("{}").lower()

    def _canonical_account_code(value) -> str:
        raw = _payroll_overview_text(value)
        if not raw:
            return ""
        token_match = re.match(r"[A-Za-z0-9]+", raw)
        token = token_match.group(0) if token_match else raw
        return _payroll_overview_normalise_key(token)

    reference_payment_date = (
        _parse_any_date((reference_payrun or {}).get("paymentDate"))
        or _parse_any_date((reference_payrun or {}).get("payRunPeriodEndDate"))
        or _parse_any_date((reference_payrun or {}).get("payRunPeriodStartDate"))
    )
    reference_payrun_id = _payroll_overview_text((reference_payrun or {}).get("payRunId"))
    reference_period_start = _parse_any_date((reference_payrun or {}).get("payRunPeriodStartDate"))
    reference_period_end = _parse_any_date((reference_payrun or {}).get("payRunPeriodEndDate")) or reference_payment_date

    diagnostics = {
        "fetchedJournalCount": len(journals or []),
        "candidateJournalCount": 0,
        "usedPayrollSourceHint": False,
        "matchedCreditLines": 0,
    }
    if not journals:
        return Decimal("0"), Decimal("0"), diagnostics

    account_by_id: dict[str, dict] = {}
    account_by_code: dict[str, dict] = {}
    account_by_name: dict[str, dict] = {}
    tax_liability_account_ids: set[str] = set()
    pension_liability_account_ids: set[str] = set()
    tax_liability_account_codes: set[str] = set()
    pension_liability_account_codes: set[str] = set()
    explicit_paye_payable_account_ids: set[str] = set()
    explicit_pension_payable_account_ids: set[str] = set()
    explicit_paye_payable_account_codes: set[str] = set()
    explicit_pension_payable_account_codes: set[str] = set()
    for account in accounts or []:
        if not isinstance(account, dict):
            continue
        account_id = _payroll_overview_text(account.get("AccountID") or account.get("ID") or account.get("accountId"))
        account_id_key = _canonical_account_id(account_id)
        if account_id_key:
            account_by_id[account_id_key] = account
        if _payroll_overview_account_is_tax_liability(account):
            if account_id_key:
                tax_liability_account_ids.add(account_id_key)
        if _payroll_overview_account_is_pension_liability(account):
            if account_id_key:
                pension_liability_account_ids.add(account_id_key)
        account_code = _payroll_overview_text(account.get("Code") or account.get("code"))
        if account_code:
            account_by_code[_payroll_overview_normalise_key(account_code)] = account
            canonical_code = _canonical_account_code(account_code)
            if canonical_code:
                account_name_norm = _payroll_overview_normalise_key(account.get("Name") or account.get("name"))
                if "payepayable" in account_name_norm or "payenicpayable" in account_name_norm:
                    explicit_paye_payable_account_codes.add(canonical_code)
                    if account_id_key:
                        explicit_paye_payable_account_ids.add(account_id_key)
                if "pensionpayable" in account_name_norm or "pensionspayable" in account_name_norm:
                    explicit_pension_payable_account_codes.add(canonical_code)
                    if account_id_key:
                        explicit_pension_payable_account_ids.add(account_id_key)
                if _payroll_overview_account_is_tax_liability(account):
                    tax_liability_account_codes.add(canonical_code)
                if _payroll_overview_account_is_pension_liability(account):
                    pension_liability_account_codes.add(canonical_code)
        account_name = _payroll_overview_text(account.get("Name") or account.get("name"))
        if account_name:
            account_by_name[_payroll_overview_normalise_key(account_name)] = account
    diagnostics["nominalCodeSelectionEngine"] = "rules"
    diagnostics["payePayableNominalCodes"] = sorted(explicit_paye_payable_account_codes) if explicit_paye_payable_account_codes else sorted(tax_liability_account_codes)
    diagnostics["pensionPayableNominalCodes"] = sorted(explicit_pension_payable_account_codes) if explicit_pension_payable_account_codes else sorted(pension_liability_account_codes)

    def _resolve_line_account(line: dict) -> dict:
        account_id = _payroll_overview_text(
            line.get("AccountID")
            or line.get("accountID")
            or line.get("accountId")
            or line.get("account_id")
        )
        account_id_key = _canonical_account_id(account_id)
        if account_id_key and account_id_key in account_by_id:
            return account_by_id[account_id_key]
        account_code = _payroll_overview_text(
            line.get("AccountCode")
            or line.get("accountCode")
            or line.get("account_code")
            or line.get("Code")
            or line.get("code")
        )
        code_key = _payroll_overview_normalise_key(account_code)
        if code_key and code_key in account_by_code:
            return account_by_code[code_key]
        account_name = _payroll_overview_text(
            line.get("AccountName")
            or line.get("accountName")
            or line.get("account_name")
            or line.get("Name")
            or line.get("name")
        )
        name_key = _payroll_overview_normalise_key(account_name)
        if name_key and name_key in account_by_name:
            return account_by_name[name_key]
        return {
            "Code": account_code,
            "Name": account_name,
            "Type": _payroll_overview_text(line.get("AccountType") or line.get("accountType") or line.get("account_type")),
            "Class": _payroll_overview_text(line.get("AccountClass") or line.get("accountClass") or line.get("account_class")),
        }

    def _is_payroll_journal(journal: dict) -> bool:
        source_text = _payroll_overview_normalise_key(
            _payroll_overview_text(journal.get("SourceType") or journal.get("sourceType"))
        )
        reference_text = _payroll_overview_normalise_key(
            _payroll_overview_text(journal.get("Reference") or journal.get("Narration") or journal.get("reference"))
        )
        payroll_tokens = ("payroll", "payrun", "pay run", "payslip", "wages")
        return any(token in source_text for token in payroll_tokens) or any(token in reference_text for token in payroll_tokens)

    def _journal_source_id(journal: dict) -> str:
        return _payroll_overview_text(
            journal.get("SourceID")
            or journal.get("sourceID")
            or journal.get("sourceId")
            or journal.get("source_id")
            or journal.get("SourceId")
        )

    strict_candidates: list[dict] = []
    loose_candidates: list[dict] = []
    for journal in journals:
        if not isinstance(journal, dict):
            continue
        journal_date = _parse_any_date(journal.get("JournalDate") or journal.get("Date") or journal.get("DateString"))
        if journal_date is None:
            continue
        if _is_payroll_journal(journal):
            strict_candidates.append(journal)
        else:
            loose_candidates.append(journal)

    candidate_journals = strict_candidates if strict_candidates else loose_candidates
    diagnostics["candidateJournalCount"] = len(candidate_journals)
    diagnostics["usedPayrollSourceHint"] = bool(strict_candidates)
    if not candidate_journals:
        return Decimal("0"), Decimal("0"), diagnostics

    def _journal_liability_totals(journal: dict) -> tuple[Decimal, Decimal, int, list[dict]]:
        lines = journal.get("JournalLines") if isinstance(journal.get("JournalLines"), list) else []
        p32_credit_total = Decimal("0")
        pension_credit_total = Decimal("0")
        matched_credit_lines = 0
        journal_line_rows: list[dict] = []
        for line_index, line in enumerate(lines):
            if not isinstance(line, dict):
                continue
            credit_amount = _payroll_overview_journal_line_credit_amount(line)
            debit_amount = _payroll_overview_journal_line_debit_amount(line)
            account = _resolve_line_account(line)
            account_code = _payroll_overview_text(
                account.get("Code")
                or line.get("AccountCode")
                or line.get("accountCode")
                or line.get("account_code")
                or line.get("code")
            )
            account_name = _payroll_overview_text(
                account.get("Name")
                or line.get("AccountName")
                or line.get("accountName")
                or line.get("account_name")
                or line.get("name")
            )
            line_account_id = _payroll_overview_text(
                line.get("AccountID")
                or line.get("accountID")
                or line.get("accountId")
                or line.get("account_id")
            )
            line_account_id_key = _canonical_account_id(line_account_id)
            canonical_line_code = _canonical_account_code(account_code)
            description = _payroll_overview_text(line.get("Description") or line.get("description") or line.get("line_description"))
            net_amount = _payroll_overview_numeric_decimal(
                line.get("NetAmount")
                or line.get("netAmount")
                or line.get("net_amount")
                or line.get("LineAmount")
                or line.get("lineAmount")
                or line.get("line_amount")
                or line.get("Amount")
                or line.get("amount")
            )
            journal_line_rows.append(
                {
                    "lineIndex": line_index + 1,
                    "accountCode": account_code,
                    "accountName": account_name,
                    "description": description,
                    "creditAmount": float(credit_amount),
                    "debitAmount": float(debit_amount),
                    "netAmount": float(net_amount),
                }
            )
            if credit_amount <= Decimal("0"):
                continue
            heuristic_tax_liability = _payroll_overview_journal_line_is_tax_liability(line, account) or (
                bool(line_account_id_key) and line_account_id_key in tax_liability_account_ids
            ) or (
                bool(canonical_line_code) and canonical_line_code in tax_liability_account_codes
            )
            heuristic_pension_liability = _payroll_overview_journal_line_is_pension_liability(line, account) or (
                bool(line_account_id_key) and line_account_id_key in pension_liability_account_ids
            ) or (
                bool(canonical_line_code) and canonical_line_code in pension_liability_account_codes
            )
            explicit_tax_liability = (
                (bool(line_account_id_key) and line_account_id_key in explicit_paye_payable_account_ids)
                or (bool(canonical_line_code) and canonical_line_code in explicit_paye_payable_account_codes)
            )
            explicit_pension_liability = (
                (bool(line_account_id_key) and line_account_id_key in explicit_pension_payable_account_ids)
                or (bool(canonical_line_code) and canonical_line_code in explicit_pension_payable_account_codes)
            )
            # Keep explicit nominal-code matching as a strong signal, but do not suppress
            # heuristic matching when explicit sets are incomplete or formatted differently.
            is_tax_liability = explicit_tax_liability or heuristic_tax_liability
            is_pension_liability = explicit_pension_liability or heuristic_pension_liability
            if is_tax_liability:
                p32_credit_total += credit_amount
                matched_credit_lines += 1
                continue
            if is_pension_liability:
                pension_credit_total += credit_amount
                matched_credit_lines += 1
        return p32_credit_total, pension_credit_total, matched_credit_lines, journal_line_rows

    best_candidate = None
    for journal in candidate_journals:
        journal_date = _parse_any_date(journal.get("JournalDate") or journal.get("Date") or journal.get("DateString")) or date.min
        (
            p32_credit_total,
            pension_credit_total,
            matched_credit_lines,
            journal_line_rows,
        ) = _journal_liability_totals(journal)
        combined_credit_total = p32_credit_total + pension_credit_total
        in_reference_window = (
            bool(reference_payment_date and journal_date == reference_payment_date)
            or bool(reference_period_start and reference_period_end and reference_period_start <= journal_date <= reference_period_end)
            or bool(not reference_period_start and reference_period_end and journal_date == reference_period_end)
        )
        journal_source_id = _journal_source_id(journal)
        source_id_matches_reference_payrun = bool(reference_payrun_id) and journal_source_id == reference_payrun_id
        score = (
            1 if source_id_matches_reference_payrun else 0,
            1 if _is_payroll_journal(journal) else 0,
            journal_date.toordinal(),
            1 if in_reference_window else 0,
            1 if matched_credit_lines > 0 else 0,
            matched_credit_lines,
            float(combined_credit_total),
            _payroll_overview_text(journal.get("JournalNumber") or journal.get("JournalID") or journal.get("Id")),
        )
        if best_candidate is None or score > best_candidate["score"]:
            best_candidate = {
                "journal": journal,
                "score": score,
                "p32_credit_total": p32_credit_total,
                "pension_credit_total": pension_credit_total,
                "matched_credit_lines": matched_credit_lines,
                "journal_line_rows": journal_line_rows,
                "journal_date": journal_date,
                "journal_source_id": journal_source_id,
                "source_id_matches_reference_payrun": source_id_matches_reference_payrun,
            }

    selected_journal = (best_candidate or {}).get("journal") if isinstance(best_candidate, dict) else {}
    selected_journal_id = _payroll_overview_text(
        selected_journal.get("JournalID") or selected_journal.get("JournalNumber") or selected_journal.get("Id")
    )
    selected_journal_date = (best_candidate or {}).get("journal_date")
    diagnostics["selectedJournalId"] = selected_journal_id
    diagnostics["selectedJournalDate"] = selected_journal_date.isoformat() if isinstance(selected_journal_date, date) else ""
    diagnostics["selectedJournalReference"] = _payroll_overview_text(
        selected_journal.get("Reference") or selected_journal.get("Narration")
    )
    diagnostics["selectedJournalSourceId"] = _payroll_overview_text((best_candidate or {}).get("journal_source_id"))
    diagnostics["selectedJournalSourceIdMatchesPayrun"] = bool((best_candidate or {}).get("source_id_matches_reference_payrun"))

    p32_credit_total = (best_candidate or {}).get("p32_credit_total") if isinstance(best_candidate, dict) else Decimal("0")
    pension_credit_total = (best_candidate or {}).get("pension_credit_total") if isinstance(best_candidate, dict) else Decimal("0")
    matched_credit_lines = int((best_candidate or {}).get("matched_credit_lines") or 0)
    journal_line_rows = (best_candidate or {}).get("journal_line_rows") if isinstance(best_candidate, dict) else []
    if not isinstance(journal_line_rows, list):
        journal_line_rows = []
    diagnostics["matchedCreditLines"] = matched_credit_lines
    diagnostics["selectedJournalLines"] = journal_line_rows[:30]

    deterministic_paye = abs(p32_credit_total)
    deterministic_pension = abs(pension_credit_total)
    diagnostics["deterministicPaye"] = float(deterministic_paye)
    diagnostics["deterministicPension"] = float(deterministic_pension)
    diagnostics["journalTaxLineTotal"] = float(abs(p32_credit_total))
    diagnostics["journalPensionLineTotal"] = float(abs(pension_credit_total))
    diagnostics["journalTaxPeakLine"] = 0.0
    diagnostics["journalPensionPeakLine"] = 0.0

    diagnostics["engine"] = "rules"
    return deterministic_paye, deterministic_pension, diagnostics


async def _payroll_overview_openai_liability_inference(
    *,
    reference_payrun: dict | None,
    payrun_rows: list[dict],
    payroll_api_context: dict | None,
    nominal_transaction_context: dict | None,
    journal_payable_diagnostics: dict,
    trial_balance_report_date: date | None,
    trial_balance_comparison_date: date | None,
    trial_balance_delta_p32_tax: Decimal,
    trial_balance_delta_pension_payable: Decimal,
    user_id: str | None = None,
) -> tuple[Decimal, Decimal, dict]:
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip():
        return Decimal("0"), Decimal("0"), {"engine": "disabled", "used": False, "reason": "openai_not_configured"}

    reference = reference_payrun if isinstance(reference_payrun, dict) else {}
    recent_runs = []
    for row in (payrun_rows or [])[:8]:
        if not isinstance(row, dict):
            continue
        recent_runs.append(
            {
                "payRunId": _payroll_overview_text(row.get("payRunId")),
                "status": _payroll_overview_text(row.get("status")),
                "periodStart": _payroll_overview_text(row.get("payRunPeriodStartDate")),
                "periodEnd": _payroll_overview_text(row.get("payRunPeriodEndDate")),
                "paymentDate": _payroll_overview_text(row.get("paymentDate")),
                "estimatedP32Tax": float(_payroll_overview_numeric_decimal(row.get("estimatedP32Tax"))),
                "estimatedPensionPayable": float(_payroll_overview_numeric_decimal(row.get("estimatedPensionPayable"))),
                "payslipCount": int(row.get("payslipCount") or 0),
            }
        )

    nominal_context = nominal_transaction_context if isinstance(nominal_transaction_context, dict) else {}
    tax_account_rows = nominal_context.get("taxAccountTransactions") if isinstance(nominal_context.get("taxAccountTransactions"), list) else []
    pension_account_rows = nominal_context.get("pensionAccountTransactions") if isinstance(nominal_context.get("pensionAccountTransactions"), list) else []

    def _flatten_all_lines(rows: list[dict]) -> list[dict]:
        lines: list[dict] = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            account_code = _payroll_overview_text(row.get("code"))
            account_name = _payroll_overview_text(row.get("name"))
            raw_lines = row.get("allTransactionLines") if isinstance(row.get("allTransactionLines"), list) else []
            for line in raw_lines:
                if not isinstance(line, dict):
                    continue
                lines.append(
                    {
                        "accountCode": account_code,
                        "accountName": account_name,
                        "date": _payroll_overview_text(line.get("date")),
                        "source": _payroll_overview_text(line.get("source")),
                        "description": _payroll_overview_text(line.get("description")),
                        "reference": _payroll_overview_text(line.get("reference")),
                        "debit": float(_money(line.get("debit"))),
                        "credit": float(_money(line.get("credit"))),
                        "net": float(_money(line.get("net"))),
                    }
                )
        return lines

    full_tax_lines = _flatten_all_lines(tax_account_rows)
    full_pension_lines = _flatten_all_lines(pension_account_rows)

    ai_context = {
        "selectedPayrun": {
            "payRunId": _payroll_overview_text(reference.get("payRunId")),
            "status": _payroll_overview_text(reference.get("status")),
            "periodStart": _payroll_overview_text(reference.get("payRunPeriodStartDate")),
            "periodEnd": _payroll_overview_text(reference.get("payRunPeriodEndDate")),
            "paymentDate": _payroll_overview_text(reference.get("paymentDate")),
            "estimatedP32Tax": float(_payroll_overview_numeric_decimal(reference.get("estimatedP32Tax"))),
            "estimatedPensionPayable": float(_payroll_overview_numeric_decimal(reference.get("estimatedPensionPayable"))),
        },
        "recentPayruns": recent_runs,
        "payrollApiContext": payroll_api_context if isinstance(payroll_api_context, dict) else {},
        "nominalTransactionContext": nominal_context,
        "fullNominalTransactionLines": {
            "taxAccountLines": full_tax_lines,
            "pensionAccountLines": full_pension_lines,
            "taxLineCount": len(full_tax_lines),
            "pensionLineCount": len(full_pension_lines),
        },
        "journalDiagnostics": {
            "selectedJournalId": _payroll_overview_text((journal_payable_diagnostics or {}).get("selectedJournalId")),
            "selectedJournalDate": _payroll_overview_text((journal_payable_diagnostics or {}).get("selectedJournalDate")),
            "selectedJournalReference": _payroll_overview_text((journal_payable_diagnostics or {}).get("selectedJournalReference")),
            "matchedCreditLines": int((journal_payable_diagnostics or {}).get("matchedCreditLines") or 0),
            "selectedJournalLines": (journal_payable_diagnostics or {}).get("selectedJournalLines")
            if isinstance((journal_payable_diagnostics or {}).get("selectedJournalLines"), list)
            else [],
            "journalTaxLineTotal": float(_payroll_overview_numeric_decimal((journal_payable_diagnostics or {}).get("journalTaxLineTotal"))),
            "journalPensionLineTotal": float(_payroll_overview_numeric_decimal((journal_payable_diagnostics or {}).get("journalPensionLineTotal"))),
        },
        "trialBalance": {
            "reportDate": trial_balance_report_date.isoformat() if isinstance(trial_balance_report_date, date) else "",
            "comparisonDate": trial_balance_comparison_date.isoformat() if isinstance(trial_balance_comparison_date, date) else "",
            "taxDeltaFromPreviousDay": float(trial_balance_delta_p32_tax),
            "pensionDeltaFromPreviousDay": float(trial_balance_delta_pension_payable),
        },
    }

    request_body = {
        "input": [
            {
                "role": "system",
                "content": (
                    "You are a UK payroll accounting analyst. Determine PAYE/NIC and pension liabilities generated for "
                    "the current payroll month by analysing nominal account-transaction evidence first (PAYE payable and "
                    "pension payable), then payroll API data, then trial-balance deltas. "
                    "Return conservative numeric estimates and short notes."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"Context JSON: {json.dumps(ai_context, default=_json_default)}\n"
                    "Return only JSON matching the schema."
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "payroll_journal_figures",
                "schema": PAYROLL_JOURNAL_FIGURES_AI_SCHEMA,
                "strict": True,
            }
        },
    }
    try:
        payload = await _post_openai_responses(
            request_body,
            "payroll liability inference",
            preferred_model=settings.openai_model,
            timeout_seconds=PAYROLL_JOURNAL_EXTRACTION_OPENAI_TIMEOUT_SECONDS,
            user_id=user_id,
            feature="openai-core",
            page="payroll-headcount",
        )
        parsed = _load_openai_json_response(payload, "OpenAI returned invalid payroll liability extraction JSON.")
        paye = abs(_payroll_overview_numeric_decimal(parsed.get("payePayable")))
        pension = abs(_payroll_overview_numeric_decimal(parsed.get("pensionPayable")))
        confidence = float(parsed.get("confidence") or 0)
        diagnostics = {
            "engine": "openai",
            "used": False,
            "confidence": confidence,
            "notes": str(parsed.get("notes") or "").strip(),
            "periodDate": str(parsed.get("periodDate") or "").strip(),
            "payePayable": float(paye),
            "pensionPayable": float(pension),
        }
        return paye, pension, diagnostics
    except Exception as exc:
        logger.exception("Payroll liability OpenAI inference failed: %s", exc)
        return Decimal("0"), Decimal("0"), {"engine": "openai_error", "used": False, "reason": _sync_error_message(exc)}


def _payroll_overview_trial_balance_pension_rows(trial_balance_payload: dict) -> list[dict]:
    lines = _xero_report_lines(trial_balance_payload if isinstance(trial_balance_payload, dict) else {})
    rows: list[dict] = []
    seen_labels: set[str] = set()
    for line in lines:
        label = str(line.get("label") or "").strip()
        if not label:
            continue
        label_norm = _payroll_overview_normalise_key(label)
        if not label_norm or label_norm in {"total", "totals"}:
            continue
        includes_pension = ("pension" in label_norm) or ("nest" in label_norm)
        includes_liability_hint = any(
            token in label_norm
            for token in ("payable", "creditor", "liability", "workplace", "autoenrolment", "autoenrollment")
        )
        if not includes_pension or not includes_liability_hint:
            continue
        amounts = [item for item in (line.get("amounts") or []) if isinstance(item, Decimal)]
        if not amounts:
            continue
        balance = abs(_money(amounts[-1]))
        if balance <= Decimal("0.00"):
            continue
        if label_norm in seen_labels:
            continue
        seen_labels.add(label_norm)
        rows.append(
            {
                "accountId": "",
                "code": "",
                "name": label,
                "type": "REPORT",
                "status": "",
                "balance": float(balance),
                "isPayable": True,
                "source": "Xero Trial Balance",
            }
        )
    rows.sort(key=lambda row: abs(float(row.get("balance") or 0)), reverse=True)
    return rows


def _payroll_overview_trial_balance_line_balance_map(trial_balance_payload: dict) -> dict[str, Decimal]:
    lines = _xero_report_lines(trial_balance_payload if isinstance(trial_balance_payload, dict) else {})
    balances: dict[str, Decimal] = {}
    for line in lines:
        label = str(line.get("label") or "").strip()
        label_norm = _payroll_overview_normalise_key(label)
        if not label_norm or label_norm in {"total", "totals"}:
            continue
        amounts = [item for item in (line.get("amounts") or []) if isinstance(item, Decimal)]
        if not amounts:
            continue
        balances[label_norm] = _money(amounts[-1])
    return balances


def _payroll_overview_previous_month_end(value: date) -> date:
    month_start = value.replace(day=1)
    return month_start - timedelta(days=1)


def _payroll_overview_trial_balance_code_balance_map(trial_balance_payload: dict) -> dict[str, Decimal]:
    lines = _xero_report_lines(trial_balance_payload if isinstance(trial_balance_payload, dict) else {})
    balances: dict[str, Decimal] = {}
    for line in lines:
        label = str(line.get("label") or "").strip()
        if not label:
            continue
        code_match = re.match(r"^\s*([A-Za-z0-9]+)\b", label)
        if not code_match:
            continue
        code_key = _payroll_overview_normalise_key(code_match.group(1))
        if not code_key:
            continue
        amounts = [item for item in (line.get("amounts") or []) if isinstance(item, Decimal)]
        if not amounts:
            continue
        balances[code_key] = _money(amounts[-1])
    return balances


def _payroll_overview_trial_balance_code_delta(
    current_payload: dict,
    previous_payload: dict,
    accounts: list[dict],
) -> tuple[Decimal, Decimal, dict]:
    current_map = _payroll_overview_trial_balance_code_balance_map(current_payload)
    previous_map = _payroll_overview_trial_balance_code_balance_map(previous_payload)
    tax_codes: set[str] = set()
    pension_codes: set[str] = set()
    for account in accounts or []:
        if not isinstance(account, dict):
            continue
        raw_code = _payroll_overview_text(account.get("Code") or account.get("code"))
        if not raw_code:
            continue
        code_match = re.match(r"[A-Za-z0-9]+", raw_code)
        code_key = _payroll_overview_normalise_key(code_match.group(0) if code_match else raw_code)
        if not code_key:
            continue
        if _payroll_overview_account_is_tax_liability(account):
            tax_codes.add(code_key)
        if _payroll_overview_account_is_pension_liability(account):
            pension_codes.add(code_key)
    tax_delta = Decimal("0")
    pension_delta = Decimal("0")
    matched_tax_codes: list[str] = []
    matched_pension_codes: list[str] = []
    for code in sorted(tax_codes):
        if code not in current_map and code not in previous_map:
            continue
        tax_delta += abs(_money(current_map.get(code, Decimal("0")) - previous_map.get(code, Decimal("0"))))
        matched_tax_codes.append(code)
    for code in sorted(pension_codes):
        if code not in current_map and code not in previous_map:
            continue
        pension_delta += abs(_money(current_map.get(code, Decimal("0")) - previous_map.get(code, Decimal("0"))))
        matched_pension_codes.append(code)
    diagnostics = {
        "taxCodes": sorted(tax_codes),
        "pensionCodes": sorted(pension_codes),
        "matchedTaxCodes": matched_tax_codes,
        "matchedPensionCodes": matched_pension_codes,
        "taxDelta": float(abs(tax_delta)),
        "pensionDelta": float(abs(pension_delta)),
    }
    return abs(tax_delta), abs(pension_delta), diagnostics


def _payroll_overview_trial_balance_label_is_tax_liability(label_norm: str) -> bool:
    if not label_norm:
        return False
    if "pension" in label_norm or "nest" in label_norm:
        return False
    # Keep fallback strict: only PAYE/NIC payable liability labels should qualify.
    return any(
        token in label_norm
        for token in (
            "payepayable",
            "payenicpayable",
            "paye/payable",
            "payeandnicpayable",
            "payeni payable".replace(" ", ""),
        )
    )


def _payroll_overview_trial_balance_label_is_pension_liability(label_norm: str) -> bool:
    if not label_norm:
        return False
    includes_pension = ("pension" in label_norm) or ("nest" in label_norm) or ("autoenrolment" in label_norm)
    includes_liability_hint = any(token in label_norm for token in ("payable", "liability", "creditor"))
    return includes_pension and (includes_liability_hint or "pensionpayable" in label_norm)


def _payroll_overview_trial_balance_liability_delta(
    current_payload: dict,
    previous_payload: dict,
) -> tuple[Decimal, Decimal, dict]:
    current = _payroll_overview_trial_balance_line_balance_map(current_payload)
    previous = _payroll_overview_trial_balance_line_balance_map(previous_payload)
    keys = set(current.keys()) | set(previous.keys())
    tax_delta = Decimal("0")
    pension_delta = Decimal("0")
    tax_labels: list[str] = []
    pension_labels: list[str] = []
    for key in sorted(keys):
        current_value = _money(current.get(key, Decimal("0")))
        previous_value = _money(previous.get(key, Decimal("0")))
        delta = _money(current_value - previous_value)
        if delta == Decimal("0"):
            continue
        if _payroll_overview_trial_balance_label_is_tax_liability(key):
            tax_delta += abs(delta)
            tax_labels.append(key)
            continue
        if _payroll_overview_trial_balance_label_is_pension_liability(key):
            pension_delta += abs(delta)
            pension_labels.append(key)
    diagnostics = {
        "taxDelta": float(abs(tax_delta)),
        "pensionDelta": float(abs(pension_delta)),
        "taxLabels": tax_labels[:20],
        "pensionLabels": pension_labels[:20],
    }
    return abs(tax_delta), abs(pension_delta), diagnostics


def _payroll_overview_payslip_tax_from_payload(payroll_payload: dict) -> Decimal:
    rows = _payroll_overview_payslip_rows(payroll_payload if isinstance(payroll_payload, dict) else {})
    if not rows:
        return Decimal("0")
    total = Decimal("0")
    for row in rows:
        row_total = _payroll_overview_sum_numeric_values(
            row,
            [
                "Tax",
                "PayeAmount",
                "PAYE",
                "TotalEmployerTaxes",
                "EmployerTax",
                "EmployeeTax",
                "NationalInsurance",
                "NicAmount",
                "EmployeeNIC",
                "EmployerNIC",
                "StudentLoan",
                "PostGraduateLoan",
            ],
        )
        if row_total <= Decimal("0"):
            row_total = _payroll_overview_sum_described_amounts(
                row,
                include_hints=["paye", "nic", "national insurance", "tax", "hmrc", "student loan", "postgraduate loan"],
                exclude_hints=["ytd", "rate", "percentage", "code", "period"],
            )
        if row_total > Decimal("0"):
            total += row_total
    return _money(total)


def _payroll_overview_payslip_pension_from_payload(payroll_payload: dict) -> Decimal:
    rows = _payroll_overview_payslip_rows(payroll_payload if isinstance(payroll_payload, dict) else {})
    if not rows:
        return Decimal("0")
    total = Decimal("0")
    for row in rows:
        row_total = _payroll_overview_sum_numeric_values(
            row,
            [
                "EmployerPensionContribution",
                "PensionEmployerContribution",
                "EmployerSuperannuation",
                "EmployerRetirementContribution",
                "KiwiSaverEmployerContribution",
                "PensionPayable",
                "PensionLiability",
            ],
        )
        if row_total <= Decimal("0"):
            row_total = _payroll_overview_sum_described_amounts(
                row,
                include_hints=["pension", "nest", "auto enrolment", "workplace pension", "superannuation", "retirement"],
                exclude_hints=["employee", "ytd", "rate", "percentage", "code"],
            )
        if row_total <= Decimal("0"):
            row_total = _payroll_overview_estimate_pension(row)
        if row_total > Decimal("0"):
            total += row_total
    return _money(total)


def _payroll_overview_nominal_accounts(accounts: list[dict]) -> tuple[list[dict], list[dict]]:
    explicit_paye_accounts: list[dict] = []
    tax_accounts: list[dict] = []
    pension_accounts: list[dict] = []
    for account in accounts or []:
        if not isinstance(account, dict):
            continue
        account_id = _payroll_overview_text(account.get("AccountID") or account.get("ID"))
        code = _payroll_overview_text(account.get("Code"))
        name = _payroll_overview_text(account.get("Name"))
        if not account_id and not code and not name:
            continue
        account_name_norm = _payroll_overview_normalise_key(name)
        entry = {
            "accountId": account_id,
            "code": code,
            "name": name,
        }
        if "payepayable" in account_name_norm or "payenicpayable" in account_name_norm:
            explicit_paye_accounts.append(entry)
        if _payroll_overview_account_is_tax_liability(account):
            tax_accounts.append(entry)
        if _payroll_overview_account_is_pension_liability(account):
            pension_accounts.append(entry)
    selected_tax_accounts = explicit_paye_accounts if explicit_paye_accounts else tax_accounts
    selected_tax_accounts.sort(key=lambda row: (_payroll_overview_normalise_key(row.get("code")), _payroll_overview_normalise_key(row.get("name"))))
    pension_accounts.sort(key=lambda row: (_payroll_overview_normalise_key(row.get("code")), _payroll_overview_normalise_key(row.get("name"))))
    return selected_tax_accounts[:6], pension_accounts[:6]


async def _payroll_overview_openai_nominal_account_selection(
    *,
    accounts: list[dict],
    period_start: date,
    period_end: date,
    reference_payrun: dict | None = None,
    user_id: str | None = None,
) -> tuple[list[dict], list[dict], dict]:
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip():
        return [], [], {"engine": "disabled", "reason": "openai_not_configured"}

    account_catalog: list[dict] = []
    for account in accounts or []:
        if not isinstance(account, dict):
            continue
        account_id = _payroll_overview_text(account.get("AccountID") or account.get("ID"))
        code = _payroll_overview_text(account.get("Code"))
        name = _payroll_overview_text(account.get("Name"))
        if not account_id and not code and not name:
            continue
        account_catalog.append(
            {
                "accountId": account_id,
                "code": code,
                "name": name,
                "type": _payroll_overview_text(account.get("Type")),
                "status": _payroll_overview_text(account.get("Status")),
            }
        )
    account_catalog = account_catalog[:400]

    candidate_tax_accounts = [
        row
        for row in account_catalog
        if _payroll_overview_account_is_tax_liability(
            {
                "Code": row.get("code"),
                "Name": row.get("name"),
                "Type": row.get("type"),
                "Class": "",
            }
        )
    ][:40]
    candidate_pension_accounts = [
        row
        for row in account_catalog
        if _payroll_overview_account_is_pension_liability(
            {
                "Code": row.get("code"),
                "Name": row.get("name"),
                "Type": row.get("type"),
                "Class": "",
            }
        )
    ][:40]

    context_payload = {
        "periodStart": period_start.isoformat() if isinstance(period_start, date) else "",
        "periodEnd": period_end.isoformat() if isinstance(period_end, date) else "",
        "selectedPayrun": {
            "payRunId": _payroll_overview_text((reference_payrun or {}).get("payRunId")),
            "periodStart": _payroll_overview_text((reference_payrun or {}).get("payRunPeriodStartDate")),
            "periodEnd": _payroll_overview_text((reference_payrun or {}).get("payRunPeriodEndDate")),
            "paymentDate": _payroll_overview_text((reference_payrun or {}).get("paymentDate")),
            "status": _payroll_overview_text((reference_payrun or {}).get("status")),
        },
        "accounts": account_catalog,
    }

    request_body = {
        "input": [
            {
                "role": "system",
                "content": (
                    "You are a UK payroll accounting analyst. From chart-of-accounts entries, choose liability nominal "
                    "accounts for PAYE/NIC payable and workplace pension payable for the provided payroll period. "
                    "Prefer current liability/control accounts, not payroll expense accounts."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"Context JSON: {json.dumps(context_payload, default=_json_default)}\n"
                    "Return only JSON matching the schema."
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "payroll_nominal_account_selection",
                "schema": PAYROLL_NOMINAL_ACCOUNT_SELECTION_AI_SCHEMA,
                "strict": True,
            }
        },
    }

    try:
        payload = await _post_openai_responses(
            request_body,
            "payroll nominal account selection",
            preferred_model=settings.openai_model,
            timeout_seconds=PAYROLL_JOURNAL_EXTRACTION_OPENAI_TIMEOUT_SECONDS,
            user_id=user_id,
            feature="openai-core",
            page="payroll-headcount",
        )
        parsed = _load_openai_json_response(payload, "OpenAI returned invalid payroll nominal account selection JSON.")
        tax_ids = {_payroll_overview_text(value) for value in (parsed.get("taxAccountIds") or []) if str(value or "").strip()}
        pension_ids = {_payroll_overview_text(value) for value in (parsed.get("pensionAccountIds") or []) if str(value or "").strip()}
        tax_codes = {
            _payroll_overview_normalise_key(str(value or ""))
            for value in (parsed.get("taxAccountCodes") or [])
            if str(value or "").strip()
        }
        pension_codes = {
            _payroll_overview_normalise_key(str(value or ""))
            for value in (parsed.get("pensionAccountCodes") or [])
            if str(value or "").strip()
        }

        def _match_selected(selection_ids: set[str], selection_codes: set[str]) -> list[dict]:
            matched: list[dict] = []
            for row in account_catalog:
                account_id = _payroll_overview_text(row.get("accountId"))
                code_key = _payroll_overview_normalise_key(row.get("code"))
                if (account_id and account_id in selection_ids) or (code_key and code_key in selection_codes):
                    matched.append(
                        {
                            "accountId": account_id,
                            "code": _payroll_overview_text(row.get("code")),
                            "name": _payroll_overview_text(row.get("name")),
                        }
                    )
            return matched

        tax_accounts = _match_selected(tax_ids, tax_codes)
        pension_accounts = _match_selected(pension_ids, pension_codes)
        diagnostics = {
            "engine": "openai_nominal_account_selection",
            "used": True,
            "confidence": float(parsed.get("confidence") or 0),
            "notes": str(parsed.get("notes") or "").strip(),
            "taxAccountIds": sorted(tax_ids),
            "taxAccountCodes": sorted(tax_codes),
            "pensionAccountIds": sorted(pension_ids),
            "pensionAccountCodes": sorted(pension_codes),
            "matchedTaxAccounts": tax_accounts,
            "matchedPensionAccounts": pension_accounts,
            "candidateTaxAccounts": candidate_tax_accounts,
            "candidatePensionAccounts": candidate_pension_accounts,
            "requiresUserSelection": not bool(tax_accounts and pension_accounts),
        }
        return tax_accounts, pension_accounts, diagnostics
    except Exception as exc:
        logger.exception("Payroll nominal account selection OpenAI inference failed: %s", exc)
        return [], [], {
            "engine": "openai_nominal_account_selection_error",
            "reason": _sync_error_message(exc),
            "candidateTaxAccounts": candidate_tax_accounts,
            "candidatePensionAccounts": candidate_pension_accounts,
            "requiresUserSelection": True,
        }


def _payroll_overview_account_transaction_lines(payload: dict) -> list[dict]:
    lines = _xero_report_lines(payload if isinstance(payload, dict) else {})
    rows: list[dict] = []
    for line in lines:
        if not isinstance(line, dict):
            continue
        label = _payroll_overview_text(line.get("label"))
        amounts = [item for item in (line.get("amounts") or []) if isinstance(item, Decimal)]
        if not label and not amounts:
            continue
        rows.append(
            {
                "label": label,
                "amounts": [float(_money(value)) for value in amounts[:6]],
            }
        )
    return rows


def _payroll_overview_account_transaction_entries(payload: dict) -> list[dict]:
    if not isinstance(payload, dict):
        return []

    reports = payload.get("Reports") or payload.get("reports") or []
    if not isinstance(reports, list) or not reports:
        return []
    report = reports[0] if isinstance(reports[0], dict) else {}
    root_rows = report.get("Rows") or report.get("rows") or []
    if not isinstance(root_rows, list):
        return []

    current_account = ""
    header_map: dict[str, int] = {}
    entries: list[dict] = []

    def _cell_value(cell) -> str:
        if not isinstance(cell, dict):
            return ""
        return str(cell.get("Value") or cell.get("value") or "").strip()

    def _normalise_header(value: str) -> str:
        return _payroll_overview_normalise_key(value).replace(" ", "")

    def _header_index(candidates: tuple[str, ...], *, required: bool = False) -> int | None:
        for candidate in candidates:
            idx = header_map.get(candidate)
            if idx is not None:
                return idx
        for key, idx in header_map.items():
            if any(key.startswith(candidate) or candidate in key for candidate in candidates):
                return idx
        return None if not required else -1

    def _walk(rows: list[dict]) -> None:
        nonlocal current_account, header_map
        for row in rows:
            if not isinstance(row, dict):
                continue
            row_type = str(row.get("RowType") or row.get("rowType") or "").strip().lower()
            cells = row.get("Cells") or row.get("cells") or []
            values = [_cell_value(cell) for cell in cells] if isinstance(cells, list) else []
            first_value = values[0] if values else ""

            if row_type == "header":
                header_map = {
                    _normalise_header(value): idx
                    for idx, value in enumerate(values)
                    if str(value or "").strip()
                }
            elif row_type != "header":
                if len(values) == 1 and first_value and first_value.lower() not in {"opening balance", "closing balance"} and not first_value.lower().startswith("total "):
                    current_account = first_value
                else:
                    date_idx = _header_index(("date",), required=True)
                    source_idx = _header_index(("source",))
                    desc_idx = _header_index(("description", "details", "narrative"))
                    ref_idx = _header_index(("reference", "ref"))
                    debit_idx = _header_index(("debit",), required=True)
                    credit_idx = _header_index(("credit",), required=True)
                    if date_idx is not None and debit_idx is not None and credit_idx is not None and min(date_idx, debit_idx, credit_idx) >= 0:
                        date_text = values[date_idx] if date_idx < len(values) else ""
                        debit = _money(_money_from_report_cell(values[debit_idx] if debit_idx < len(values) else ""))
                        credit = _money(_money_from_report_cell(values[credit_idx] if credit_idx < len(values) else ""))
                        source_text = values[source_idx] if source_idx is not None and source_idx < len(values) else ""
                        description_text = values[desc_idx] if desc_idx is not None and desc_idx < len(values) else ""
                        reference_text = values[ref_idx] if ref_idx is not None and ref_idx < len(values) else ""
                        first_col_date = _parse_any_date(date_text)
                        first_value_date = _parse_any_date(first_value)
                        effective_date = date_text if isinstance(first_col_date, date) else (first_value if isinstance(first_value_date, date) else "")
                        is_balance_row = str((description_text or first_value or "")).strip().lower() in {"opening balance", "closing balance"}
                        is_total_row = str((description_text or first_value or "")).strip().lower().startswith("total ")
                        if effective_date and not is_balance_row and not is_total_row and (debit != Decimal("0.00") or credit != Decimal("0.00")):
                            entries.append(
                                {
                                    "accountName": current_account,
                                    "date": effective_date,
                                    "source": source_text,
                                    "description": description_text,
                                    "reference": reference_text,
                                    "debit": debit,
                                    "credit": credit,
                                    "net": _money(credit - debit),
                                }
                            )

            nested_rows = row.get("Rows") or row.get("rows") or []
            if isinstance(nested_rows, list) and nested_rows:
                _walk(nested_rows)

    _walk(root_rows)
    return entries


def _payroll_overview_account_transaction_net(entries: list[dict]) -> Decimal:
    total = Decimal("0")
    for entry in entries or []:
        if not isinstance(entry, dict):
            continue
        total += _money(entry.get("credit")) - _money(entry.get("debit"))
    return _money(total)


async def _payroll_overview_nominal_transaction_context(
    *,
    fetcher,
    accounts: list[dict],
    period_start: date,
    period_end: date,
    reference_payrun: dict | None = None,
    user_id: str | None = None,
    tax_code_overrides: list[str] | None = None,
    pension_code_overrides: list[str] | None = None,
) -> dict:
    heuristic_tax_accounts, heuristic_pension_accounts = _payroll_overview_nominal_accounts(accounts)
    ai_tax_accounts, ai_pension_accounts, account_selection_diagnostics = await _payroll_overview_openai_nominal_account_selection(
        accounts=accounts,
        period_start=period_start,
        period_end=period_end,
        reference_payrun=reference_payrun,
        user_id=user_id,
    )
    override_tax_keys = {
        _payroll_overview_normalise_key(code)
        for code in (tax_code_overrides or [])
        if str(code or "").strip()
    }
    override_pension_keys = {
        _payroll_overview_normalise_key(code)
        for code in (pension_code_overrides or [])
        if str(code or "").strip()
    }

    def _match_overrides(keys: set[str]) -> list[dict]:
        if not keys:
            return []
        matches: list[dict] = []
        for account in accounts or []:
            if not isinstance(account, dict):
                continue
            code = _payroll_overview_text(account.get("Code") or account.get("code"))
            code_key = _payroll_overview_normalise_key(code)
            if not code_key or code_key not in keys:
                continue
            matches.append(
                {
                    "accountId": _payroll_overview_text(account.get("AccountID") or account.get("ID")),
                    "code": code,
                    "name": _payroll_overview_text(account.get("Name") or account.get("name")),
                }
            )
        return matches

    override_tax_accounts = _match_overrides(override_tax_keys)
    override_pension_accounts = _match_overrides(override_pension_keys)
    using_manual_selection = bool(override_tax_accounts or override_pension_accounts)

    tax_accounts = (
        override_tax_accounts
        if override_tax_accounts
        else ai_tax_accounts
        if ai_tax_accounts
        else heuristic_tax_accounts
    )
    pension_accounts = (
        override_pension_accounts
        if override_pension_accounts
        else ai_pension_accounts
        if ai_pension_accounts
        else heuristic_pension_accounts
    )
    context = {
        "engine": "nominal_account_transactions",
        "periodStart": period_start.isoformat() if isinstance(period_start, date) else "",
        "periodEnd": period_end.isoformat() if isinstance(period_end, date) else "",
        "taxAccounts": tax_accounts,
        "pensionAccounts": pension_accounts,
        "accountSelectionDiagnostics": account_selection_diagnostics if isinstance(account_selection_diagnostics, dict) else {},
        "taxAccountTransactions": [],
        "pensionAccountTransactions": [],
        "taxPayrollExpenseNet": 0.0,
        "pensionPayrollExpenseNet": 0.0,
        "pensionApplicableNet": 0.0,
        "payeRunReferences": [],
        "payeRunDates": [],
    }
    if isinstance(context.get("accountSelectionDiagnostics"), dict):
        context["accountSelectionDiagnostics"]["selectionSource"] = (
            "manual_user_override"
            if using_manual_selection
            else "openai"
            if ai_tax_accounts or ai_pension_accounts
            else "heuristic_fallback"
        )
        context["accountSelectionDiagnostics"]["selectedTaxAccounts"] = tax_accounts
        context["accountSelectionDiagnostics"]["selectedPensionAccounts"] = pension_accounts
        context["accountSelectionDiagnostics"]["requiresUserSelection"] = bool(not tax_accounts or not pension_accounts)

    paye_run_reference_keys: set[str] = set()
    paye_run_dates: set[str] = set()

    def _reference_key(value: str) -> str:
        return _payroll_overview_normalise_key(str(value or "").strip())

    def _is_payroll_expense_journal_entry(row: dict) -> bool:
        reference_norm = _reference_key(row.get("reference"))
        source_norm = _reference_key(row.get("source"))
        description_norm = _reference_key(row.get("description"))
        return (
            "payrollexpensejournal" in reference_norm
            or "payrollexpensejournal" in description_norm
            or "payrollexpense" in source_norm
        )

    async def _collect(account_rows: list[dict], bucket: list[dict], label_prefix: str) -> None:
        bucket_total = Decimal("0")
        applicable_total = Decimal("0")
        def _filter_entries_to_period(entries: list[dict]) -> list[dict]:
            filtered: list[dict] = []
            for item in entries or []:
                if not isinstance(item, dict):
                    continue
                entry_date = _parse_any_date(item.get("date"))
                if not isinstance(entry_date, date):
                    continue
                if period_start <= entry_date <= period_end:
                    filtered.append(item)
            return filtered
        for account in account_rows:
            if not isinstance(account, dict):
                continue
            account_id = _payroll_overview_text(account.get("accountId"))
            if not account_id:
                continue
            payload = await fetcher(
                XERO_REPORTS_ACCOUNT_TRANSACTIONS_URL,
                f"{label_prefix} {account.get('code') or account_id} transactions",
                {
                    "accountID": account_id,
                    "fromDate": period_start.isoformat(),
                    "toDate": period_end.isoformat(),
                },
            )
            rows = _payroll_overview_account_transaction_lines(payload)
            transaction_entries = _payroll_overview_account_transaction_entries(payload)
            if not transaction_entries:
                # Some tenants intermittently return empty account-transaction rows when
                # range params are supplied. Retry without range and filter locally.
                fallback_payload = await fetcher(
                    XERO_REPORTS_ACCOUNT_TRANSACTIONS_URL,
                    f"{label_prefix} {account.get('code') or account_id} transactions (fallback all)",
                    {
                        "accountID": account_id,
                    },
                )
                fallback_rows = _payroll_overview_account_transaction_lines(fallback_payload)
                fallback_entries = _payroll_overview_account_transaction_entries(fallback_payload)
                filtered_entries = _filter_entries_to_period(fallback_entries)
                if filtered_entries:
                    rows = fallback_rows
                    transaction_entries = filtered_entries
            all_transaction_net = _payroll_overview_account_transaction_net(transaction_entries)
            payroll_expense_entries = [
                row
                for row in transaction_entries
                if _is_payroll_expense_journal_entry(row)
            ]
            if str(label_prefix).strip().lower() == "tax":
                for row in payroll_expense_entries:
                    reference_key = _reference_key(row.get("reference"))
                    if reference_key:
                        paye_run_reference_keys.add(reference_key)
                    date_key = _payroll_overview_text(row.get("date"))
                    if date_key:
                        paye_run_dates.add(date_key)

            if str(label_prefix).strip().lower() == "pension":
                matched_reference_entries = [
                    row
                    for row in transaction_entries
                    if _reference_key(row.get("reference")) in paye_run_reference_keys
                ] if paye_run_reference_keys else []
                matched_date_entries = [
                    row
                    for row in transaction_entries
                    if _payroll_overview_text(row.get("date")) in paye_run_dates
                ] if paye_run_dates else []
                # Pension postings do not always carry the exact same reference
                # as PAYE lines, so include either matching references or dates.
                applicable_entries = []
                seen_applicable_keys: set[tuple[str, str, str, str, str, str]] = set()
                for row in matched_reference_entries + matched_date_entries + payroll_expense_entries:
                    key = (
                        _payroll_overview_text(row.get("date")),
                        _payroll_overview_text(row.get("source")),
                        _payroll_overview_text(row.get("description")),
                        _payroll_overview_text(row.get("reference")),
                        str(_money(row.get("debit"))),
                        str(_money(row.get("credit"))),
                    )
                    if key in seen_applicable_keys:
                        continue
                    seen_applicable_keys.add(key)
                    applicable_entries.append(row)
            else:
                applicable_entries = payroll_expense_entries
            payroll_expense_net = _payroll_overview_account_transaction_net(payroll_expense_entries)
            applicable_net = _payroll_overview_account_transaction_net(applicable_entries)
            bucket_total += payroll_expense_net
            applicable_total += applicable_net
            bucket.append(
                {
                    "accountId": account_id,
                    "code": _payroll_overview_text(account.get("code")),
                    "name": _payroll_overview_text(account.get("name")),
                    "lineCount": len(rows),
                    "lines": rows[:80],
                    "allTransactionLineCount": len(transaction_entries),
                    "allTransactionNet": float(all_transaction_net),
                    "allTransactionLines": [
                        {
                            "date": _payroll_overview_text(line.get("date")),
                            "source": _payroll_overview_text(line.get("source")),
                            "description": _payroll_overview_text(line.get("description")),
                            "reference": _payroll_overview_text(line.get("reference")),
                            "debit": float(_money(line.get("debit"))),
                            "credit": float(_money(line.get("credit"))),
                            "net": float(_money(line.get("net"))),
                        }
                        for line in transaction_entries
                    ],
                    "payrollExpenseLineCount": len(payroll_expense_entries),
                    "payrollExpenseNet": float(payroll_expense_net),
                    "applicableLineCount": len(applicable_entries),
                    "applicableNet": float(applicable_net),
                    "payrollExpenseLines": [
                        {
                            "date": _payroll_overview_text(line.get("date")),
                            "source": _payroll_overview_text(line.get("source")),
                            "description": _payroll_overview_text(line.get("description")),
                            "reference": _payroll_overview_text(line.get("reference")),
                            "debit": float(_money(line.get("debit"))),
                            "credit": float(_money(line.get("credit"))),
                            "net": float(_money(line.get("net"))),
                        }
                        for line in payroll_expense_entries[:40]
                    ],
                    "applicableLines": [
                        {
                            "date": _payroll_overview_text(line.get("date")),
                            "source": _payroll_overview_text(line.get("source")),
                            "description": _payroll_overview_text(line.get("description")),
                            "reference": _payroll_overview_text(line.get("reference")),
                            "debit": float(_money(line.get("debit"))),
                            "credit": float(_money(line.get("credit"))),
                            "net": float(_money(line.get("net"))),
                        }
                        for line in applicable_entries[:40]
                    ],
                }
            )
        return bucket_total, applicable_total
    tax_payroll_total, _ = await _collect(tax_accounts, context["taxAccountTransactions"], "Tax")
    pension_payroll_total, pension_applicable_total = await _collect(pension_accounts, context["pensionAccountTransactions"], "Pension")
    tax_transaction_count = sum(
        int(item.get("allTransactionLineCount") or 0)
        for item in context["taxAccountTransactions"]
        if isinstance(item, dict)
    )
    pension_transaction_count = sum(
        int(item.get("allTransactionLineCount") or 0)
        for item in context["pensionAccountTransactions"]
        if isinstance(item, dict)
    )
    context["taxPayrollExpenseNet"] = float(tax_payroll_total)
    context["pensionPayrollExpenseNet"] = float(pension_payroll_total)
    context["pensionApplicableNet"] = float(pension_applicable_total)
    context["taxNominalTransactionCount"] = int(tax_transaction_count)
    context["pensionNominalTransactionCount"] = int(pension_transaction_count)
    context["hasNominalTransactions"] = bool(tax_transaction_count > 0 or pension_transaction_count > 0)
    context["payeRunReferences"] = sorted(paye_run_reference_keys)
    context["payeRunDates"] = sorted(paye_run_dates)
    if isinstance(context.get("accountSelectionDiagnostics"), dict):
        missing_nominal_transactions = (tax_transaction_count <= 0) or (pension_transaction_count <= 0)
        context["accountSelectionDiagnostics"]["requiresUserSelection"] = bool(
            context["accountSelectionDiagnostics"].get("requiresUserSelection")
            or missing_nominal_transactions
        )
        if missing_nominal_transactions:
            context["accountSelectionDiagnostics"]["selectionIssue"] = "no_nominal_transactions_for_selected_codes"
    return context


def _payroll_overview_payrun_tax_from_payload(payrun_payload: dict) -> Decimal:
    if not isinstance(payrun_payload, dict):
        return Decimal("0")
    rows = _payroll_headcount_rows(payrun_payload, "PayRuns", "PayRun")
    payrun = rows[0] if rows else {}
    if not isinstance(payrun, dict):
        return Decimal("0")
    direct = _payroll_overview_find_numeric_value(
        payrun,
        [
            "TotalTax",
            "TotalTaxAmount",
            "TaxPayable",
            "P32TaxAmount",
            "PayeNicAmount",
            "PayeAmount",
            "NicAmount",
            "NationalInsurance",
            "EmployeeTax",
            "EmployerTax",
        ],
    )
    described = _payroll_overview_sum_described_amounts(
        payrun,
        include_hints=["paye", "nic", "national insurance", "tax", "hmrc", "student loan", "postgraduate loan"],
        exclude_hints=["ytd", "rate", "percentage", "code", "period"],
    )
    estimated = _payroll_overview_estimate_p32_tax(payrun)
    return _money(max(direct, described, estimated))


def _payroll_overview_payrun_pension_from_payload(payrun_payload: dict) -> Decimal:
    if not isinstance(payrun_payload, dict):
        return Decimal("0")
    rows = _payroll_headcount_rows(payrun_payload, "PayRuns", "PayRun")
    payrun = rows[0] if rows else {}
    if not isinstance(payrun, dict):
        return Decimal("0")
    direct = _payroll_overview_sum_numeric_values(
        payrun,
        [
            "EmployerPensionContribution",
            "PensionEmployerContribution",
            "EmployerSuperannuation",
            "EmployerRetirementContribution",
            "KiwiSaverEmployerContribution",
            "PensionPayable",
            "PensionLiability",
            "TotalPension",
            "TotalPensionAmount",
        ],
    )
    described = _payroll_overview_sum_described_amounts(
        payrun,
        include_hints=["pension", "nest", "auto enrolment", "workplace pension", "superannuation", "retirement"],
        exclude_hints=["employee", "ytd", "rate", "percentage", "code"],
    )
    estimated = _payroll_overview_estimate_pension(payrun)
    return _money(max(direct, described, estimated))


async def payroll_tenant_overview_payload(
    user: dict,
    tenant_id: str,
    tax_code_overrides: list[str] | None = None,
    pension_code_overrides: list[str] | None = None,
) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    if not clean_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant id is required.")

    connection_row = xero_connection_for_user_tenant(user, clean_tenant_id, include_fallback=False)

    errors: list[str] = []
    fetch_diagnostics: dict[str, dict] = {}

    def _register_fetch_diagnostic(label: str, *, url: str = "") -> dict:
        key = _payroll_overview_normalise_key(label) or "unknown"
        diagnostics = fetch_diagnostics.get(key)
        if isinstance(diagnostics, dict):
            return diagnostics
        diagnostics = {
            "label": label,
            "url": url,
            "attempted": False,
            "statusCode": None,
            "elapsedMs": 0,
            "ok": False,
            "error": "",
        }
        fetch_diagnostics[key] = diagnostics
        return diagnostics

    async def _fetch(url: str, label: str, params: dict | None = None) -> dict:
        diagnostics = _register_fetch_diagnostic(label, url=url)
        diagnostics["attempted"] = True
        response_meta: dict = {}
        def _on_response(meta: dict):
            if isinstance(meta, dict):
                response_meta.update(meta)
        try:
            payload = await xero_api_get(connection_row, url, params=params, on_response=_on_response)
            diagnostics["statusCode"] = response_meta.get("status_code")
            diagnostics["elapsedMs"] = int(response_meta.get("elapsed_ms") or 0)
            diagnostics["ok"] = True
            return payload if isinstance(payload, dict) else {}
        except Exception as exc:
            diagnostics["statusCode"] = response_meta.get("status_code")
            diagnostics["elapsedMs"] = int(response_meta.get("elapsed_ms") or 0)
            diagnostics["ok"] = False
            diagnostics["error"] = _sync_error_message(exc)
            errors.append(f"{label}: {diagnostics['error']}")
            return {}

    accounts_payload = await _fetch(ACCOUNTS_URL, "Chart of accounts")
    employees_payload, payruns_payload = await asyncio.gather(
        _fetch(XERO_PAYROLL_EMPLOYEES_URL, "Employees"),
        _fetch(XERO_PAYROLL_PAYRUNS_URL, "Pay runs"),
    )

    employees = _payroll_headcount_rows(employees_payload, "Employees", "Employee")
    payruns = _payroll_headcount_rows(payruns_payload, "PayRuns", "PayRun")
    accounts_candidate = (
        accounts_payload.get("Accounts")
        or accounts_payload.get("accounts")
        or accounts_payload.get("Account")
        or accounts_payload.get("account")
        or []
    )
    if isinstance(accounts_candidate, dict):
        accounts_candidate = (
            accounts_candidate.get("Accounts")
            or accounts_candidate.get("accounts")
            or accounts_candidate.get("Account")
            or accounts_candidate.get("account")
            or []
        )
    accounts = [account for account in accounts_candidate if isinstance(account, dict)] if isinstance(accounts_candidate, list) else []

    active_employees = [row for row in employees if _payroll_headcount_employee_is_active(row)]
    employee_rows = sorted(
        [
            {
                "employeeId": _payroll_overview_text(row.get("EmployeeID")),
                "name": _payroll_overview_employee_name(row),
                "status": _payroll_overview_text(row.get("EmployeeStatus") or row.get("Status")) or "Unknown",
                "email": _payroll_overview_text(row.get("Email")),
                "startDate": (
                    _parse_any_date(row.get("StartDate"))
                    or _parse_any_date(row.get("DateOfJoining"))
                    or _parse_any_date(row.get("CreatedDateUTC"))
                    or _parse_any_date(row.get("CreatedDate"))
                ),
            }
            for row in active_employees
        ],
        key=lambda row: str(row.get("name") or "").lower(),
    )
    for row in employee_rows:
        row["startDate"] = row["startDate"].isoformat() if isinstance(row.get("startDate"), date) else ""

    payrun_rows = []
    for row in payruns:
        run_date = _payroll_headcount_payrun_date(row)
        run_status = _payroll_overview_status(row)
        p32_estimate = _payroll_overview_estimate_p32_tax(row)
        pension_estimate = _payroll_overview_estimate_pension(row)
        payrun_rows.append(
            {
                "payRunId": _payroll_headcount_payrun_id(row),
                "status": run_status,
                "payRunPeriodStartDate": (
                    _parse_any_date(row.get("PayRunPeriodStartDate"))
                    or _parse_any_date(row.get("payRunPeriodStartDate"))
                    or _parse_any_date(row.get("PayPeriodStartDate"))
                    or _parse_any_date(row.get("payPeriodStartDate"))
                    or _parse_any_date(row.get("PeriodStartDate"))
                    or _parse_any_date(row.get("periodStartDate"))
                ),
                "payRunPeriodEndDate": (
                    _parse_any_date(row.get("PayRunPeriodEndDate"))
                    or _parse_any_date(row.get("payRunPeriodEndDate"))
                    or _parse_any_date(row.get("PayPeriodEndDate"))
                    or _parse_any_date(row.get("payPeriodEndDate"))
                    or _parse_any_date(row.get("PeriodEndDate"))
                    or _parse_any_date(row.get("periodEndDate"))
                ),
                "paymentDate": run_date,
                "updatedDateUtc": _parse_any_date(row.get("UpdatedDateUTC")) or _parse_any_date(row.get("UpdatedDate")),
                "payslipCount": _payroll_overview_payrun_count(row),
                "wages": float(
                    _payroll_overview_decimal(
                        row.get("Wages")
                        or row.get("wages")
                        or row.get("TotalWages")
                        or row.get("totalWages")
                    )
                ),
                "estimatedP32Tax": float(p32_estimate),
                "estimatedPensionPayable": float(pension_estimate),
            }
        )
    payrun_rows.sort(
        key=lambda item: (
            item.get("paymentDate") or date.min,
            item.get("payRunPeriodEndDate") or date.min,
            item.get("updatedDateUtc") or date.min,
        ),
        reverse=True,
    )
    for item in payrun_rows:
        for key in ("payRunPeriodStartDate", "payRunPeriodEndDate", "paymentDate", "updatedDateUtc"):
            item[key] = item[key].isoformat() if isinstance(item.get(key), date) else ""

    details_fetch_attempted = 0
    details_fetch_succeeded = 0

    async def _apply_payrun_detail_estimates(target_row: dict) -> None:
        nonlocal details_fetch_attempted, details_fetch_succeeded
        payrun_id = _payroll_overview_text(target_row.get("payRunId"))
        if not payrun_id:
            return
        details_fetch_attempted += 1
        details_url = XERO_PAYROLL_PAYRUN_DETAILS_URL.format(payrun_id=quote(payrun_id, safe=""))
        payrun_details_payload = await xero_api_get(connection_row, details_url)
        detail_rows = _payroll_headcount_rows(payrun_details_payload, "PayRuns", "PayRun")
        detail_payrun = detail_rows[0] if detail_rows else {}
        if not detail_payrun:
            return
        details_fetch_succeeded += 1
        detailed_p32_estimate = _payroll_overview_estimate_p32_tax(detail_payrun)
        detailed_pension_estimate = _payroll_overview_estimate_pension(detail_payrun)
        if detailed_p32_estimate > Decimal("0"):
            target_row["estimatedP32Tax"] = float(detailed_p32_estimate)
        if detailed_pension_estimate > Decimal("0"):
            target_row["estimatedPensionPayable"] = float(detailed_pension_estimate)
            return
        # Payroll workflow now relies on posted journal and account liabilities.
        # Do not call payslip-detail endpoints as a fallback.
        return

    draft_statuses = {"DRAFT", "POSTED"}
    draft_payruns = [row for row in payrun_rows if str(row.get("status") or "").upper() in draft_statuses]
    submitted_statuses = {"POSTED", "PAID", "SUBMITTED", "COMPLETED", "PROCESSED"}
    submitted_payrun = next(
        (row for row in payrun_rows if str(row.get("status") or "").upper() in submitted_statuses),
        None,
    )
    reference_payrun = submitted_payrun or (payrun_rows[0] if payrun_rows else None)
    if not isinstance(reference_payrun, dict):
        today_date = utcnow().date()
        synthetic_period_end = today_date.replace(day=1) - timedelta(days=1)
        synthetic_period_start = synthetic_period_end.replace(day=1)
        reference_payrun = {
            "payRunId": "",
            "status": "POSTED",
            "payRunPeriodStartDate": synthetic_period_start.isoformat(),
            "payRunPeriodEndDate": synthetic_period_end.isoformat(),
            "paymentDate": synthetic_period_end.isoformat(),
            "estimatedP32Tax": 0.0,
            "estimatedPensionPayable": 0.0,
        }
    payrun_rows_by_id = {
        _payroll_overview_text(item.get("payRunId")): item
        for item in payrun_rows
        if _payroll_overview_text(item.get("payRunId"))
    }
    detail_candidates = []
    if reference_payrun:
        detail_candidates.append(reference_payrun)
    for item in payrun_rows:
        if len(detail_candidates) >= 3:
            break
        if item in detail_candidates:
            continue
        if float(_payroll_overview_numeric_decimal(item.get("estimatedP32Tax"))) > 0 and float(_payroll_overview_numeric_decimal(item.get("estimatedPensionPayable"))) > 0:
            continue
        detail_candidates.append(item)
    for candidate in detail_candidates:
        try:
            await _apply_payrun_detail_estimates(candidate)
        except Exception as exc:
            errors.append(f"Pay run details: {_sync_error_message(exc)}")

    journal_payable_diagnostics: dict = {"engine": "disabled", "reason": "nominal_required_mode"}
    payroll_api_p32_tax = Decimal("0")
    payroll_api_pension_payable = Decimal("0")
    payroll_api_p32_tax_from_payslips = Decimal("0")
    payroll_api_pension_payable_from_payslips = Decimal("0")
    payroll_api_p32_tax_from_payrun_details = Decimal("0")
    payroll_api_pension_payable_from_payrun_details = Decimal("0")
    payroll_api_diagnostics: dict = {}
    selected_payrun_details_payload: dict = {}
    selected_payrun_payslips_payload: dict = {}
    selected_payrun_id = _payroll_overview_text((reference_payrun or {}).get("payRunId"))
    if selected_payrun_id:
        try:
            selected_payrun_details_payload = await _fetch(
                XERO_PAYROLL_PAYRUN_DETAILS_URL.format(payrun_id=quote(selected_payrun_id, safe="")),
                "Selected pay run details",
            )
        except Exception as exc:
            errors.append(f"Selected pay run details: {_sync_error_message(exc)}")
            selected_payrun_details_payload = {}
        try:
            selected_payrun_payslips_payload = await _fetch(
                XERO_PAYROLL_PAYSLIPS_BY_PAYRUN_URL,
                "Pay slips by pay run",
                {"PayRunID": selected_payrun_id},
            )
        except Exception as exc:
            errors.append(f"Pay slips by pay run: {_sync_error_message(exc)}")
            selected_payrun_payslips_payload = {}
        payroll_api_p32_tax_from_payslips = _payroll_overview_payslip_tax_from_payload(selected_payrun_payslips_payload)
        payroll_api_pension_payable_from_payslips = _payroll_overview_payslip_pension_from_payload(selected_payrun_payslips_payload)
        payroll_api_p32_tax_from_payrun_details = _payroll_overview_payrun_tax_from_payload(selected_payrun_details_payload)
        payroll_api_pension_payable_from_payrun_details = _payroll_overview_payrun_pension_from_payload(selected_payrun_details_payload)
        payroll_api_p32_tax = payroll_api_p32_tax_from_payslips
        payroll_api_pension_payable = payroll_api_pension_payable_from_payslips
        if payroll_api_p32_tax_from_payrun_details > payroll_api_p32_tax:
            payroll_api_p32_tax = payroll_api_p32_tax_from_payrun_details
        if payroll_api_pension_payable_from_payrun_details > payroll_api_pension_payable:
            payroll_api_pension_payable = payroll_api_pension_payable_from_payrun_details
        if payroll_api_p32_tax <= Decimal("0"):
            payroll_api_p32_tax = payroll_api_p32_tax_from_payrun_details
        if payroll_api_pension_payable <= Decimal("0"):
            payroll_api_pension_payable = payroll_api_pension_payable_from_payrun_details
        payslip_rows = _payroll_overview_payslip_rows(selected_payrun_payslips_payload)
        payroll_api_diagnostics = {
            "engine": "payroll_api",
            "selectedPayRunId": selected_payrun_id,
            "payslipCount": len(payslip_rows),
            "p32FromPayrollApi": float(payroll_api_p32_tax),
            "pensionFromPayrollApi": float(payroll_api_pension_payable),
            "p32FromPayrunDetails": float(payroll_api_p32_tax_from_payrun_details),
            "pensionFromPayrunDetails": float(payroll_api_pension_payable_from_payrun_details),
        }
        journal_payable_diagnostics = {"engine": "disabled", "reason": "nominal_required_mode"}
    else:
        payroll_api_diagnostics = {"engine": "payroll_api", "selectedPayRunId": "", "reason": "no_selected_payrun"}

    today_date = utcnow().date()
    previous_month_end = today_date.replace(day=1) - timedelta(days=1)
    trial_balance_report_date = (
        _parse_any_date((reference_payrun or {}).get("paymentDate"))
        or _parse_any_date((reference_payrun or {}).get("payRunPeriodEndDate"))
        or _parse_any_date((reference_payrun or {}).get("payRunPeriodStartDate"))
        or previous_month_end
    )
    trial_balance_payload = await _fetch(
        XERO_REPORTS_TRIAL_BALANCE_URL,
        "Trial balance",
        {"date": trial_balance_report_date.isoformat()},
    )
    trial_balance_previous_date = _payroll_overview_previous_month_end(trial_balance_report_date)
    trial_balance_previous_payload = await _fetch(
        XERO_REPORTS_TRIAL_BALANCE_URL,
        "Trial balance previous month end",
        {"date": trial_balance_previous_date.isoformat()},
    )
    trial_balance_delta_p32_tax = Decimal("0")
    trial_balance_delta_pension_payable = Decimal("0")
    trial_balance_delta_diagnostics: dict = {}
    (
        code_delta_tax,
        code_delta_pension,
        code_delta_diag,
    ) = _payroll_overview_trial_balance_code_delta(
        trial_balance_payload,
        trial_balance_previous_payload,
        accounts,
    )
    (
        label_delta_tax,
        label_delta_pension,
        label_delta_diag,
    ) = _payroll_overview_trial_balance_liability_delta(
        trial_balance_payload,
        trial_balance_previous_payload,
    )
    if code_delta_tax > Decimal("0") or code_delta_pension > Decimal("0"):
        trial_balance_delta_p32_tax = code_delta_tax
        trial_balance_delta_pension_payable = code_delta_pension
        trial_balance_delta_diagnostics = {
            "engine": "nominal_code_delta",
            "codeDelta": code_delta_diag if isinstance(code_delta_diag, dict) else {},
            "labelDelta": label_delta_diag if isinstance(label_delta_diag, dict) else {},
        }
    else:
        trial_balance_delta_p32_tax = label_delta_tax
        trial_balance_delta_pension_payable = label_delta_pension
        trial_balance_delta_diagnostics = {
            "engine": "nominal_label_delta",
            "codeDelta": code_delta_diag if isinstance(code_delta_diag, dict) else {},
            "labelDelta": label_delta_diag if isinstance(label_delta_diag, dict) else {},
        }
    trial_balance_pension_rows = _payroll_overview_trial_balance_pension_rows(trial_balance_payload)
    trial_balance_pension_payable_balance = float(
        sum(abs(_payroll_overview_decimal(row.get("balance"))) for row in trial_balance_pension_rows)
    )
    nominal_transaction_context: dict = {
        "engine": "trial_balance_delta",
        "taxDelta": float(trial_balance_delta_p32_tax),
        "pensionDelta": float(trial_balance_delta_pension_payable),
        "diagnostics": trial_balance_delta_diagnostics if isinstance(trial_balance_delta_diagnostics, dict) else {},
    }
    nominal_tx_p32_tax = Decimal("0")
    nominal_tx_pension_payable = Decimal("0")
    nominal_transaction_fetch_errors: list[str] = []
    nominal_period_start = (
        _parse_any_date((reference_payrun or {}).get("payRunPeriodStartDate"))
        or _parse_any_date((reference_payrun or {}).get("paymentDate"))
        or trial_balance_previous_date + timedelta(days=1)
    )
    nominal_period_end = (
        _parse_any_date((reference_payrun or {}).get("payRunPeriodEndDate"))
        or _parse_any_date((reference_payrun or {}).get("paymentDate"))
        or trial_balance_report_date
    )
    # Payroll liabilities are fixed to PAYE nominal 825 and pension nominal 858.
    # Keep these defaults enforced even when no explicit overrides are passed.
    effective_tax_code_overrides = ["825"]
    effective_pension_code_overrides = ["858"]
    if isinstance(nominal_period_start, date) and isinstance(nominal_period_end, date):
        try:
            nominal_transaction_context = await _payroll_overview_nominal_transaction_context(
                fetcher=_fetch,
                accounts=accounts,
                period_start=nominal_period_start,
                period_end=nominal_period_end,
                reference_payrun=reference_payrun,
                user_id=str(user.get("id") or "").strip() or None,
                tax_code_overrides=effective_tax_code_overrides,
                pension_code_overrides=effective_pension_code_overrides,
            )
            nominal_transaction_fetch_errors = [
                message
                for message in errors
                if isinstance(message, str)
                and "transactions:" in message.lower()
                and (
                    message.lower().startswith("tax ")
                    or message.lower().startswith("pension ")
                )
            ]
            if nominal_transaction_fetch_errors:
                nominal_transaction_context = {
                    **(nominal_transaction_context if isinstance(nominal_transaction_context, dict) else {}),
                    "degraded": True,
                    "degradedReason": "partial_account_transaction_fetch_failure",
                    "errors": nominal_transaction_fetch_errors[:12],
                }
            tax_account_rows = (
                nominal_transaction_context.get("taxAccountTransactions")
                if isinstance(nominal_transaction_context, dict)
                else []
            )
            pension_account_rows = (
                nominal_transaction_context.get("pensionAccountTransactions")
                if isinstance(nominal_transaction_context, dict)
                else []
            )
            if not isinstance(tax_account_rows, list):
                tax_account_rows = []
            if not isinstance(pension_account_rows, list):
                pension_account_rows = []
            nominal_tx_p32_tax = abs(
                sum(
                    _payroll_overview_numeric_decimal(
                        row.get("applicableNet")
                        if row.get("applicableNet") not in (None, "")
                        else row.get("payrollExpenseNet")
                        if row.get("payrollExpenseNet") not in (None, "")
                        else row.get("allTransactionNet")
                    )
                    for row in tax_account_rows
                    if isinstance(row, dict)
                )
            )
            nominal_tx_pension_payable = abs(
                sum(
                    _payroll_overview_numeric_decimal(
                        row.get("applicableNet")
                        if row.get("applicableNet") not in (None, "")
                        else row.get("payrollExpenseNet")
                        if row.get("payrollExpenseNet") not in (None, "")
                        else row.get("allTransactionNet")
                    )
                    for row in pension_account_rows
                    if isinstance(row, dict)
                )
            )
        except Exception as exc:
            nominal_transaction_context = {
                "engine": "nominal_account_transactions",
                "error": _sync_error_message(exc),
                "periodStart": nominal_period_start.isoformat(),
                "periodEnd": nominal_period_end.isoformat(),
            }
    openai_p32_tax = Decimal("0")
    openai_pension_payable = Decimal("0")
    openai_payable_diagnostics: dict = {"engine": "disabled", "reason": "nominal_context_unavailable"}
    nominal_context_ready_for_ai = (
        isinstance(nominal_transaction_context, dict)
        and str(nominal_transaction_context.get("engine") or "").strip() == "nominal_account_transactions"
        and not str(nominal_transaction_context.get("error") or "").strip()
        and bool(nominal_transaction_context.get("hasNominalTransactions"))
    )
    if nominal_context_ready_for_ai:
        openai_p32_tax, openai_pension_payable, openai_payable_diagnostics = await _payroll_overview_openai_liability_inference(
            reference_payrun=reference_payrun,
            payrun_rows=payrun_rows,
            payroll_api_context=payroll_api_diagnostics,
            nominal_transaction_context=nominal_transaction_context,
            journal_payable_diagnostics=journal_payable_diagnostics if isinstance(journal_payable_diagnostics, dict) else {},
            trial_balance_report_date=trial_balance_report_date if isinstance(trial_balance_report_date, date) else None,
            trial_balance_comparison_date=trial_balance_previous_date if isinstance(trial_balance_previous_date, date) else None,
            trial_balance_delta_p32_tax=trial_balance_delta_p32_tax,
            trial_balance_delta_pension_payable=trial_balance_delta_pension_payable,
            user_id=str(user.get("id") or "").strip() or None,
        )

    logger.info(
        "payroll_overview_fetch_diagnostics user_id=%s tenant_id=%s employees_attempted=%s employees_status=%s employees_ok=%s payruns_attempted=%s payruns_status=%s payruns_ok=%s accounts_attempted=%s accounts_status=%s accounts_ok=%s payruns_returned=%s errors=%s",
        user.get("id"),
        clean_tenant_id,
        bool((fetch_diagnostics.get("employees") or {}).get("attempted")),
        (fetch_diagnostics.get("employees") or {}).get("statusCode"),
        bool((fetch_diagnostics.get("employees") or {}).get("ok")),
        bool((fetch_diagnostics.get("payruns") or {}).get("attempted")),
        (fetch_diagnostics.get("payruns") or {}).get("statusCode"),
        bool((fetch_diagnostics.get("payruns") or {}).get("ok")),
        bool((fetch_diagnostics.get("chartofaccounts") or {}).get("attempted")),
        (fetch_diagnostics.get("chartofaccounts") or {}).get("statusCode"),
        bool((fetch_diagnostics.get("chartofaccounts") or {}).get("ok")),
        len(payrun_rows),
        "; ".join(errors[:4]),
    )

    reference_payrun_id = _payroll_overview_text(reference_payrun.get("payRunId")) if reference_payrun else ""

    today = utcnow().date()
    next_due = None
    for run in sorted(payrun_rows, key=lambda row: _parse_any_date(row.get("paymentDate")) or date.max):
        payment_date = _parse_any_date(run.get("paymentDate"))
        if payment_date and payment_date >= today:
            next_due = payment_date
            break

    tax_rows = []
    for account in accounts:
        if not _payroll_overview_account_is_tax_liability(account):
            continue
        balance = _payroll_overview_account_balance(account)
        if abs(balance) < Decimal("0.005"):
            continue
        tax_rows.append(
            {
                "accountId": _payroll_overview_text(account.get("AccountID") or account.get("ID")),
                "code": _payroll_overview_text(account.get("Code")),
                "name": _payroll_overview_text(account.get("Name")) or "Payroll tax account",
                "type": _payroll_overview_text(account.get("Type")),
                "status": _payroll_overview_text(account.get("Status")),
                "balance": float(balance),
                "isPayable": balance > 0,
            }
        )
    tax_rows.sort(key=lambda row: abs(float(row.get("balance") or 0)), reverse=True)

    pension_rows = []
    for account in accounts:
        if not _payroll_overview_account_is_pension_liability(account):
            continue
        balance = _payroll_overview_account_balance(account)
        if abs(balance) < Decimal("0.005"):
            continue
        pension_rows.append(
            {
                "accountId": _payroll_overview_text(account.get("AccountID") or account.get("ID")),
                "code": _payroll_overview_text(account.get("Code")),
                "name": _payroll_overview_text(account.get("Name")) or "Pension payable account",
                "type": _payroll_overview_text(account.get("Type")),
                "status": _payroll_overview_text(account.get("Status")),
                "balance": float(balance),
                "isPayable": balance > 0,
            }
        )
    pension_rows.sort(key=lambda row: abs(float(row.get("balance") or 0)), reverse=True)

    # Liability balances can be positive or negative in Xero depending on account setup.
    # Use absolute balances so payable fallbacks still populate when sign conventions differ.
    outstanding_tax_balance = float(
        sum(abs(_payroll_overview_decimal(row.get("balance"))) for row in tax_rows)
    )
    pension_payable_balance = float(
        sum(abs(_payroll_overview_decimal(row.get("balance"))) for row in pension_rows)
    )
    latest_payrun_date = ""
    if reference_payrun:
        latest_payrun_date = str(
            reference_payrun.get("paymentDate")
            or reference_payrun.get("payRunPeriodEndDate")
            or reference_payrun.get("payRunPeriodStartDate")
            or ""
        ).strip()
    estimated_p32_tax_balance = float(
        _payroll_overview_numeric_decimal(reference_payrun.get("estimatedP32Tax")) if reference_payrun else Decimal("0")
    )
    estimated_pension_payable_balance = float(
        _payroll_overview_numeric_decimal(reference_payrun.get("estimatedPensionPayable")) if reference_payrun else Decimal("0")
    )
    latest_payrun_with_p32 = next(
        (
            row
            for row in payrun_rows
            if float(_payroll_overview_numeric_decimal(row.get("estimatedP32Tax"))) > 0
        ),
        None,
    )
    latest_payrun_with_pension = next(
        (
            row
            for row in payrun_rows
            if float(_payroll_overview_numeric_decimal(row.get("estimatedPensionPayable"))) > 0
        ),
        None,
    )
    latest_payrun_p32_balance = float(
        _payroll_overview_numeric_decimal((latest_payrun_with_p32 or {}).get("estimatedP32Tax"))
    )
    latest_payrun_pension_balance = float(
        _payroll_overview_numeric_decimal((latest_payrun_with_pension or {}).get("estimatedPensionPayable"))
    )
    pay_slips_diag = fetch_diagnostics.get("payslipsbypayrun") or {}
    selected_details_diag = fetch_diagnostics.get("selectedpayrundetails") or {}
    tax_nominal_count = int((nominal_transaction_context or {}).get("taxNominalTransactionCount") or 0) if isinstance(nominal_transaction_context, dict) else 0
    pension_nominal_count = int((nominal_transaction_context or {}).get("pensionNominalTransactionCount") or 0) if isinstance(nominal_transaction_context, dict) else 0
    has_tax_nominal_evidence = tax_nominal_count > 0
    has_pension_nominal_evidence = pension_nominal_count > 0
    def _is_permission_block_message(message: str) -> bool:
        text = str(message or "").strip().lower()
        if not text:
            return False
        return (
            ("permission" in text and "scope" in text)
            or "permissions need updating" in text
            or "forbidden" in text
            or "invalid_scope" in text
            or "reconnect xero" in text
        )

    nominal_context_errors = (
        nominal_transaction_context.get("errors")
        if isinstance(nominal_transaction_context, dict) and isinstance(nominal_transaction_context.get("errors"), list)
        else []
    )
    nominal_permission_blocked = any(
        _is_permission_block_message(message)
        for message in (
            list(nominal_transaction_fetch_errors)
            + list(nominal_context_errors)
            + list(errors)
        )
    )
    nominal_strict_ready = has_tax_nominal_evidence and has_pension_nominal_evidence

    p32_candidates: list[tuple[str, float]] = [
        ("openai_nominal_inference", float(openai_p32_tax)),
        ("nominal_account_transactions", float(nominal_tx_p32_tax)),
        ("payroll_api_payslips", float(payroll_api_p32_tax_from_payslips)),
        ("payroll_api_payslips", float(payroll_api_p32_tax_from_payrun_details)),
        ("payrun_estimate", latest_payrun_p32_balance),
        ("nominal_trial_balance_delta", float(trial_balance_delta_p32_tax)),
    ]
    pension_candidates: list[tuple[str, float]] = [
        ("openai_nominal_inference", float(openai_pension_payable)),
        ("nominal_account_transactions", float(nominal_tx_pension_payable)),
        ("payroll_api_payslips", float(payroll_api_pension_payable_from_payslips)),
        ("payroll_api_payslips", float(payroll_api_pension_payable_from_payrun_details)),
        ("payrun_estimate", latest_payrun_pension_balance),
    ]

    p32_source = "none"
    pension_source = "none"
    for source_name, value in p32_candidates:
        if value > 0:
            estimated_p32_tax_balance = value
            p32_source = source_name
            break
    for source_name, value in pension_candidates:
        if value > 0:
            estimated_pension_payable_balance = value
            pension_source = source_name
            break

    if nominal_permission_blocked:
        errors.append(
            "Nominal transaction permissions appear incomplete. Reconnect Xero and approve required accounting/journal/report scopes."
        )
    if selected_payrun_id and (estimated_p32_tax_balance <= 0 or estimated_pension_payable_balance <= 0):
        payslips_status = int(pay_slips_diag.get("statusCode") or 0)
        details_status = int(selected_details_diag.get("statusCode") or 0)
        if payslips_status in (401, 403) or details_status in (401, 403):
            errors.append(
                "Exact payroll liability extraction unavailable: missing required Xero permissions."
            )
        elif not bool(pay_slips_diag.get("ok")) and not bool(selected_details_diag.get("ok")):
            errors.append(
                "Exact payroll liability extraction unavailable: Xero payroll endpoints returned no usable data for the selected pay run."
            )
        elif estimated_p32_tax_balance <= 0:
            errors.append(
                "Exact payroll liability extraction unavailable: could not read PAYE/NIC liability from Xero payroll data."
            )
        elif estimated_pension_payable_balance <= 0:
            errors.append(
                "Exact payroll liability extraction unavailable: could not read pension payable from Xero payroll data."
            )
    if isinstance(openai_payable_diagnostics, dict):
        openai_payable_diagnostics["used"] = bool(
            openai_p32_tax > Decimal("0") or openai_pension_payable > Decimal("0")
        )
    estimated_balances_source = {
        "p32Tax": p32_source,
        "pensionPayable": pension_source,
    }
    if details_fetch_attempted:
        logger.info(
            "payroll_overview_detail_fetch user_id=%s tenant_id=%s attempted=%s succeeded=%s reference_payrun_id=%s p32_source=%s pension_source=%s p32_value=%.2f pension_value=%.2f",
            user.get("id"),
            clean_tenant_id,
            details_fetch_attempted,
            details_fetch_succeeded,
            reference_payrun_id,
            estimated_balances_source["p32Tax"],
            estimated_balances_source["pensionPayable"],
            estimated_p32_tax_balance,
            estimated_pension_payable_balance,
        )

    deduped_errors: list[str] = []
    seen_error_keys: set[str] = set()
    for message in errors:
        text = str(message or "").strip()
        if not text:
            continue
        key = re.sub(r"\s+", " ", text).strip().lower()
        if key in seen_error_keys:
            continue
        seen_error_keys.add(key)
        deduped_errors.append(text)

    return {
        "tenantId": clean_tenant_id,
        "tenantName": str(connection_row.get("tenant_name") or clean_tenant_id),
        "generatedAt": _iso(utcnow()) or "",
        "summary": {
            "employeeCount": len(employees),
            "activeEmployeeCount": len(active_employees),
            "payRunCount": len(payrun_rows),
            "draftPayRunCount": len(draft_payruns),
            "latestPayRunDate": latest_payrun_date,
            "nextPayRunDate": next_due.isoformat() if isinstance(next_due, date) else "",
            "outstandingTaxBalance": outstanding_tax_balance,
            "estimatedP32TaxBalance": estimated_p32_tax_balance,
            "pensionPayableBalance": estimated_pension_payable_balance,
            "figureSources": estimated_balances_source,
            "trialBalanceReportDate": trial_balance_report_date.isoformat() if isinstance(trial_balance_report_date, date) else "",
            "trialBalancePreviousReportDate": trial_balance_previous_date.isoformat() if isinstance(trial_balance_previous_date, date) else "",
            "trialBalanceDeltaP32Tax": float(trial_balance_delta_p32_tax),
            "trialBalanceDeltaPensionPayable": float(trial_balance_delta_pension_payable),
            "trialBalanceDeltaDiagnostics": trial_balance_delta_diagnostics if isinstance(trial_balance_delta_diagnostics, dict) else {},
            "trialBalancePensionPayableBalance": trial_balance_pension_payable_balance,
            "payrollApiDiagnostics": payroll_api_diagnostics if isinstance(payroll_api_diagnostics, dict) else {},
            "nominalTransactionDiagnostics": nominal_transaction_context if isinstance(nominal_transaction_context, dict) else {},
            "openAiPayrollInferenceDiagnostics": openai_payable_diagnostics if isinstance(openai_payable_diagnostics, dict) else {},
            "payrunDetailDiagnostics": {
                "attempted": details_fetch_attempted,
                "succeeded": details_fetch_succeeded,
                "referencePayRunId": reference_payrun_id,
                "payRunIds": [
                    pay_run_id
                    for pay_run_id in list(payrun_rows_by_id.keys())[:12]
                ],
            },
            "journalPayableDiagnostics": journal_payable_diagnostics if isinstance(journal_payable_diagnostics, dict) else {},
            "fetchDiagnostics": {
                "employees": fetch_diagnostics.get("employees") or {},
                "payRuns": fetch_diagnostics.get("payruns") or {},
                "accounts": fetch_diagnostics.get("chartofaccounts") or {},
                "selectedPayRunDetails": fetch_diagnostics.get("selectedpayrundetails") or {},
                "paySlipsByPayRun": fetch_diagnostics.get("payslipsbypayrun") or {},
                "trialBalance": fetch_diagnostics.get("trialbalance") or {},
                "trialBalancePreviousMonthEnd": fetch_diagnostics.get("trialbalancepreviousmonthend") or {},
                "trialBalancePreviousDay": fetch_diagnostics.get("trialbalancepreviousday") or {},
            },
        },
        "payRuns": payrun_rows[:12],
        "draftPayRuns": draft_payruns[:6],
        "employees": employee_rows[:60],
        "outstandingTaxes": tax_rows[:20],
        "outstandingPensions": pension_rows[:20],
        "outstandingPensionsFromTrialBalance": trial_balance_pension_rows[:20],
        "errors": deduped_errors,
    }


def _payroll_headcount_workspace_row_payload(row: dict, snapshots: list[dict] | None = None) -> dict:
    latest = None
    if snapshots:
        latest = snapshots[0]
    return {
        "id": str(row.get("id") or ""),
        "tenantId": str(row.get("tenant_id") or ""),
        "tenantName": str(row.get("tenant_name") or ""),
        "workspaceName": str(row.get("workspace_name") or ""),
        "wizardCompleted": bool(row.get("wizard_completed")),
        "ignitionPlanName": str(row.get("ignition_plan_name") or ""),
        "ignitionClientName": str(row.get("ignition_client_name") or ""),
        "ignitionProposalName": str(row.get("ignition_proposal_name") or ""),
        "ignitionMatchedAt": _iso(row.get("ignition_matched_at")) or "",
        "createdAt": _iso(row.get("created_at")) or "",
        "updatedAt": _iso(row.get("updated_at")) or "",
        "latestSnapshot": latest,
        "monthlySnapshots": snapshots or [],
    }


def payroll_headcount_payload(user: dict) -> dict:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT id,
                               tenant_id,
                               tenant_name,
                               workspace_name,
                               wizard_completed,
                               ignition_plan_name,
                               ignition_client_name,
                               ignition_proposal_name,
                               ignition_matched_at,
                               created_at,
                               updated_at
                        FROM payroll_headcount_workspaces
                        WHERE user_id = %s
                        ORDER BY LOWER(COALESCE(tenant_name, tenant_id)), created_at ASC
                        """,
                        (user["id"],),
                    )
                    workspace_rows = cursor.fetchall() or []
                    workspace_ids = [str(row.get("id") or "") for row in workspace_rows if row.get("id")]
                    snapshots_by_workspace_id: dict[str, list[dict]] = {}
                    if workspace_ids:
                        cursor.execute(
                            """
                            SELECT DISTINCT ON (workspace_id, month_start)
                                   workspace_id,
                                   month_start,
                                   headcount,
                                   payroll_count,
                                   source,
                                   fetched_at,
                                   created_at,
                                   updated_at
                            FROM payroll_headcount_monthly_snapshots
                            WHERE workspace_id = ANY(%s)
                            ORDER BY workspace_id, month_start DESC, fetched_at DESC, updated_at DESC
                            """,
                            (workspace_ids,),
                        )
                        snapshot_rows = cursor.fetchall() or []
                        for snapshot_row in snapshot_rows:
                            workspace_id = str(snapshot_row.get("workspace_id") or "")
                            if not workspace_id:
                                continue
                            snapshots_by_workspace_id.setdefault(workspace_id, []).append(
                                {
                                    "monthStart": _payroll_headcount_month_start_iso(snapshot_row.get("month_start")),
                                    "headcount": int(snapshot_row.get("headcount") or 0),
                                    "payrollCount": int(snapshot_row.get("payroll_count") or 0),
                                    "source": str(snapshot_row.get("source") or ""),
                                    "fetchedAt": _iso(snapshot_row.get("fetched_at")) or "",
                                    "createdAt": _iso(snapshot_row.get("created_at")) or "",
                                    "updatedAt": _iso(snapshot_row.get("updated_at")) or "",
                                }
                            )
                connection.commit()

            workspaces = [
                _payroll_headcount_workspace_row_payload(
                    row,
                    snapshots=snapshots_by_workspace_id.get(str(row.get("id") or ""), []),
                )
                for row in workspace_rows
            ]
            return {
                "workspaces": workspaces,
                "summary": {
                    "workspaceCount": len(workspaces),
                    "configuredCount": sum(1 for row in workspaces if row.get("wizardCompleted")),
                    "snapshotCount": sum(len(row.get("monthlySnapshots") or []) for row in workspaces),
                },
            }
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True
            logger.warning(
                "payroll_headcount_payload_schema_repaired user_id=%s",
                user.get("id"),
            )


def _juk_equity_previous_month_ends(month_count: int = 12, today: date | None = None) -> list[date]:
    count = max(1, int(month_count or 12))
    pivot = today or utcnow().date()
    cursor = _month_start(pivot) - timedelta(days=1)
    month_ends: list[date] = []
    for _ in range(count):
        month_ends.append(cursor)
        cursor = _month_start(cursor) - timedelta(days=1)
    month_ends.reverse()
    return month_ends


async def juk_equity_payload(user: dict) -> dict:
    connection_row = get_xero_connection_for_user(user["id"])
    month_ends = _juk_equity_previous_month_ends(12)
    rows: list[dict] = []

    for month_end in month_ends:
        row = {
            "monthEnd": month_end.isoformat(),
            "monthLabel": month_end.strftime("%b %Y"),
            "netAssets": None,
            "missing": True,
            "error": "",
        }
        try:
            report_payload = await xero_api_get(
                connection_row,
                "https://api.xero.com/api.xro/2.0/Reports/BalanceSheet",
                {"date": month_end.isoformat()},
            )
            report_lines = _xero_report_lines(report_payload if isinstance(report_payload, dict) else {})
            header_dates = _xero_report_header_dates(report_payload if isinstance(report_payload, dict) else {})
            net_assets, _, _ = _code_breaker_xero_net_assets_with_diagnostics(
                report_lines,
                as_at_date=month_end,
                header_dates=header_dates,
            )
            if net_assets is None:
                row["error"] = "Net assets value was not present in the Balance Sheet response."
            else:
                row["netAssets"] = float(net_assets)
                row["missing"] = False
        except HTTPException as exc:
            detail = exc.detail
            row["error"] = str(detail.get("message") if isinstance(detail, dict) else detail or "Unable to fetch Xero balance sheet.")
        except Exception as exc:
            row["error"] = _sync_error_message(exc)
        rows.append(row)

    available_rows = [row for row in rows if row.get("netAssets") is not None]
    latest_row = available_rows[-1] if available_rows else None
    oldest_row = available_rows[0] if available_rows else None
    highest_row = max(available_rows, key=lambda row: row.get("netAssets") or float("-inf")) if available_rows else None
    twelve_month_change = None
    if latest_row and oldest_row:
        twelve_month_change = _money(Decimal(str(latest_row["netAssets"])) - Decimal(str(oldest_row["netAssets"])))

    return {
        "generatedAt": _iso(utcnow()) or "",
        "organisationName": str(connection_row.get("tenant_name") or connection_row.get("tenant_id") or "Jaccountancy").strip(),
        "latestCompletedMonthEnd": month_ends[-1].isoformat() if month_ends else "",
        "series": rows,
        "latestNetAssets": latest_row.get("netAssets") if latest_row else None,
        "twelveMonthChange": float(twelve_month_change) if twelve_month_change is not None else None,
        "highestMonth": {
            "monthEnd": highest_row.get("monthEnd"),
            "monthLabel": highest_row.get("monthLabel"),
            "netAssets": highest_row.get("netAssets"),
        } if highest_row else None,
        "missingMonths": [row for row in rows if row.get("missing")],
    }


def upsert_payroll_headcount_workspace(user: dict, tenant_id: str) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    if not clean_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant id is required.")
    connection_row = xero_connection_for_user_tenant(user, clean_tenant_id, include_fallback=False)
    tenant_name = str(connection_row.get("tenant_name") or clean_tenant_id).strip()
    workspace_name = f"{tenant_name} Headcount Workspace"
    schema_repaired = False
    while True:
        now = utcnow()
        try:
            with get_connection() as connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute(
                            """
                            INSERT INTO payroll_headcount_workspaces (
                                user_id,
                                tenant_id,
                                tenant_name,
                                workspace_name,
                                wizard_completed,
                                ignition_plan_name,
                                ignition_client_name,
                                ignition_proposal_name,
                                ignition_matched_at,
                                created_at,
                                updated_at
                            )
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                            ON CONFLICT (user_id, tenant_id)
                            DO UPDATE
                            SET tenant_name = EXCLUDED.tenant_name,
                                workspace_name = EXCLUDED.workspace_name,
                                wizard_completed = TRUE,
                                updated_at = EXCLUDED.updated_at
                            RETURNING id,
                                      tenant_id,
                                      tenant_name,
                                      workspace_name,
                                      wizard_completed,
                                      ignition_plan_name,
                                      ignition_client_name,
                                      ignition_proposal_name,
                                      ignition_matched_at,
                                      created_at,
                                      updated_at
                            """,
                            (
                                user["id"],
                                clean_tenant_id,
                                tenant_name,
                                workspace_name,
                                True,
                                "",
                                "",
                                "",
                                None,
                                now,
                                now,
                            ),
                        )
                        row = cursor.fetchone() or {}
                except pg_errors.InvalidColumnReference:
                    # Older deployments may miss the unique constraint required by ON CONFLICT.
                    connection.rollback()
                    logger.warning(
                        "payroll_headcount_workspace_upsert_legacy_schema user_id=%s tenant_id=%s",
                        user.get("id"),
                        clean_tenant_id,
                    )
                    with connection.cursor() as cursor:
                        cursor.execute(
                            """
                            UPDATE payroll_headcount_workspaces
                            SET tenant_name = %s,
                                workspace_name = %s,
                                wizard_completed = TRUE,
                                updated_at = %s
                            WHERE user_id = %s
                              AND tenant_id = %s
                            RETURNING id,
                                      tenant_id,
                                      tenant_name,
                                      workspace_name,
                                      wizard_completed,
                                      ignition_plan_name,
                                      ignition_client_name,
                                      ignition_proposal_name,
                                      ignition_matched_at,
                                      created_at,
                                      updated_at
                            """,
                            (
                                tenant_name,
                                workspace_name,
                                now,
                                user["id"],
                                clean_tenant_id,
                            ),
                        )
                        row = cursor.fetchone() or {}
                        if not row:
                            cursor.execute(
                                """
                                INSERT INTO payroll_headcount_workspaces (
                                    user_id,
                                    tenant_id,
                                    tenant_name,
                                    workspace_name,
                                    wizard_completed,
                                    ignition_plan_name,
                                    ignition_client_name,
                                    ignition_proposal_name,
                                    ignition_matched_at,
                                    created_at,
                                    updated_at
                                )
                                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                                RETURNING id,
                                          tenant_id,
                                          tenant_name,
                                          workspace_name,
                                          wizard_completed,
                                          ignition_plan_name,
                                          ignition_client_name,
                                          ignition_proposal_name,
                                          ignition_matched_at,
                                          created_at,
                                          updated_at
                                """,
                                (
                                    user["id"],
                                    clean_tenant_id,
                                    tenant_name,
                                    workspace_name,
                                    True,
                                    "",
                                    "",
                                    "",
                                    None,
                                    now,
                                    now,
                                ),
                            )
                            row = cursor.fetchone() or {}
                connection.commit()
            return _payroll_headcount_workspace_row_payload(row, snapshots=[])
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True
            logger.warning(
                "payroll_headcount_workspace_schema_repaired user_id=%s tenant_id=%s",
                user.get("id"),
                clean_tenant_id,
            )


async def sync_payroll_headcount_workspace(user: dict, tenant_id: str) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    if not clean_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant id is required.")

    schema_repaired = False

    def _repair_schema_once() -> bool:
        nonlocal schema_repaired
        if schema_repaired:
            return False
        ensure_schema()
        schema_repaired = True
        logger.warning(
            "payroll_headcount_schema_repaired user_id=%s tenant_id=%s",
            user.get("id"),
            clean_tenant_id,
        )
        return True

    while True:
        try:
            workspace = upsert_payroll_headcount_workspace(user, clean_tenant_id)
            break
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if not _repair_schema_once():
                raise
        except HTTPException:
            raise
        except Exception as exc:
            logger.exception(
                "payroll_headcount_workspace_upsert_failed user_id=%s tenant_id=%s phase=workspace_upsert",
                user.get("id"),
                clean_tenant_id,
            )
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail={
                    "message": "Payroll headcount sync failed while creating or updating the workspace.",
                    "phase": "workspace_upsert",
                    "error": _sync_error_message(exc),
                    "tenantId": clean_tenant_id,
                    "hint": "Check the payroll_headcount_workspaces schema and constraints in the database.",
                },
            ) from exc

    workspace_id = str(workspace.get("id") or "").strip()
    if not workspace_id:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Payroll workspace sync failed because the workspace id could not be resolved.",
        )

    try:
        connection_row = xero_connection_for_user_tenant(user, clean_tenant_id, include_fallback=False)
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception(
            "payroll_headcount_connection_resolve_failed user_id=%s tenant_id=%s phase=connection_resolve",
            user.get("id"),
            clean_tenant_id,
        )
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail={
                "message": "Payroll headcount sync failed while resolving the Xero tenant connection.",
                "phase": "connection_resolve",
                "error": _sync_error_message(exc),
                "tenantId": clean_tenant_id,
            },
        ) from exc

    errors: list[str] = []

    async def _fetch_payroll_dataset(url: str, label: str) -> dict:
        try:
            payload = await xero_api_get(connection_row, url)
            return payload if isinstance(payload, dict) else {}
        except Exception as exc:
            error_message = _sync_error_message(exc)
            errors.append(f"{label} sync failed: {error_message}")
            logger.warning(
                "payroll_headcount_xero_fetch_failed user_id=%s tenant_id=%s phase=xero_fetch dataset=%s error=%s",
                user.get("id"),
                clean_tenant_id,
                label,
                error_message,
            )
            return {}

    employees_payload, payruns_payload = await asyncio.gather(
        _fetch_payroll_dataset(XERO_PAYROLL_EMPLOYEES_URL, "Employees"),
        _fetch_payroll_dataset(XERO_PAYROLL_PAYRUNS_URL, "Pay runs"),
    )

    employees = _payroll_headcount_rows(employees_payload, "Employees", "Employee")
    payruns = _payroll_headcount_rows(payruns_payload, "PayRuns", "PayRun")

    if not employees and not payruns and errors:
        reconnect_hint = (
            "/auth/xero/start?force=1&include_payroll=1"
            f"&xero_target=payroll-headcount&redirect_to=%2F%23credit-control-payroll-headcount"
        )
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "message": "Unable to read Payroll data from Xero for this tenant.",
                "errors": errors,
                "hint": "Reconnect with Payroll scopes and confirm this tenant has Payroll enabled.",
                "reconnectUrl": reconnect_hint,
            },
        )

    month_start = _month_start()
    monthly_payruns = [
        payrun
        for payrun in payruns
        if (_payroll_headcount_payrun_date(payrun) or month_start).replace(day=1) == month_start
    ]
    current_month_payrun_count = sum(
        1
        for payrun in monthly_payruns
        if isinstance(payrun, dict)
    )
    payroll_count = current_month_payrun_count if payruns else 0

    active_headcount = sum(1 for employee in employees if _payroll_headcount_employee_is_active(employee))
    if active_headcount == 0 and employees:
        active_headcount = sum(
            1
            for employee in employees
            if str(employee.get("EmployeeStatus") or employee.get("Status") or employee.get("status") or "").strip().lower()
            not in {"terminated", "inactive", "deleted", "archived"}
        )
    latest_payrun_headcount: int | None = None
    if monthly_payruns:
        latest_payrun = max(
            monthly_payruns,
            key=lambda row: _payroll_headcount_payrun_date(row) or date.min,
        )
        latest_payrun_id = _payroll_headcount_payrun_id(latest_payrun)
        if latest_payrun_id:
            try:
                details_url = XERO_PAYROLL_PAYRUN_DETAILS_URL.format(payrun_id=quote(latest_payrun_id, safe=""))
                payrun_details_payload = await xero_api_get(connection_row, details_url)
                latest_payrun_headcount = _payroll_headcount_from_payrun_details(payrun_details_payload)
            except Exception as exc:
                errors.append(f"Pay run details sync failed: {_sync_error_message(exc)}")
    active_headcount = _payroll_headcount_effective_count(active_headcount, latest_payrun_headcount)

    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    now = utcnow()
                    raw_payload = json.dumps(
                        {
                            "employeeCount": len(employees),
                            "activeEmployeeCount": active_headcount,
                            "latestPayrunHeadcount": latest_payrun_headcount,
                            "payRunCount": len(payruns),
                            "errors": errors,
                        },
                        default=_json_default,
                    )
                    try:
                        cursor.execute(
                            """
                            INSERT INTO payroll_headcount_monthly_snapshots (
                                workspace_id,
                                month_start,
                                headcount,
                                payroll_count,
                                source,
                                fetched_at,
                                raw_payload,
                                created_at,
                                updated_at
                            )
                            VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                            ON CONFLICT (workspace_id, month_start)
                            DO UPDATE
                            SET headcount = EXCLUDED.headcount,
                                payroll_count = EXCLUDED.payroll_count,
                                source = EXCLUDED.source,
                                fetched_at = EXCLUDED.fetched_at,
                                raw_payload = EXCLUDED.raw_payload,
                                updated_at = EXCLUDED.updated_at
                            RETURNING month_start,
                                      headcount,
                                      payroll_count,
                                      source,
                                      fetched_at,
                                      created_at,
                                      updated_at
                            """,
                            (
                                workspace_id,
                                month_start,
                                active_headcount,
                                payroll_count,
                                "xero-payroll",
                                now,
                                raw_payload,
                                now,
                                now,
                            ),
                        )
                        snapshot_row = cursor.fetchone() or {}
                    except pg_errors.InvalidColumnReference:
                        # Legacy deployments may miss the unique constraint required by ON CONFLICT.
                        connection.rollback()
                        logger.warning(
                            "payroll_headcount_snapshot_upsert_legacy_schema user_id=%s tenant_id=%s workspace_id=%s",
                            user.get("id"),
                            clean_tenant_id,
                            workspace_id,
                        )
                        with connection.cursor() as legacy_cursor:
                            legacy_cursor.execute(
                                """
                                UPDATE payroll_headcount_monthly_snapshots
                                SET headcount = %s,
                                    payroll_count = %s,
                                    source = %s,
                                    fetched_at = %s,
                                    raw_payload = %s::jsonb,
                                    updated_at = %s
                                WHERE workspace_id = %s
                                  AND month_start = %s
                                RETURNING month_start,
                                          headcount,
                                          payroll_count,
                                          source,
                                          fetched_at,
                                          created_at,
                                          updated_at
                                """,
                                (
                                    active_headcount,
                                    payroll_count,
                                    "xero-payroll",
                                    now,
                                    raw_payload,
                                    now,
                                    workspace_id,
                                    month_start,
                                ),
                            )
                            snapshot_row = legacy_cursor.fetchone() or {}
                            if not snapshot_row:
                                legacy_cursor.execute(
                                    """
                                    INSERT INTO payroll_headcount_monthly_snapshots (
                                        workspace_id,
                                        month_start,
                                        headcount,
                                        payroll_count,
                                        source,
                                        fetched_at,
                                        raw_payload,
                                        created_at,
                                        updated_at
                                    )
                                    VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                                    RETURNING month_start,
                                              headcount,
                                              payroll_count,
                                              source,
                                              fetched_at,
                                              created_at,
                                              updated_at
                                    """,
                                    (
                                        workspace_id,
                                        month_start,
                                        active_headcount,
                                        payroll_count,
                                        "xero-payroll",
                                        now,
                                        raw_payload,
                                        now,
                                        now,
                                    ),
                                )
                                snapshot_row = legacy_cursor.fetchone() or {}
                    cursor.execute(
                        """
                        UPDATE payroll_headcount_workspaces
                        SET wizard_completed = TRUE,
                            updated_at = %s
                        WHERE id = %s
                        """,
                        (utcnow(), workspace_id),
                    )
                connection.commit()
            break
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if not _repair_schema_once():
                raise
        except HTTPException:
            raise
        except Exception as exc:
            logger.exception(
                "payroll_headcount_snapshot_write_failed user_id=%s tenant_id=%s workspace_id=%s phase=snapshot_upsert active_headcount=%s payroll_count=%s employee_rows=%s payrun_rows=%s",
                user.get("id"),
                clean_tenant_id,
                workspace_id,
                active_headcount,
                payroll_count,
                len(employees),
                len(payruns),
            )
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail={
                    "message": "Payroll headcount sync failed while saving the monthly snapshot.",
                    "phase": "snapshot_upsert",
                    "error": _sync_error_message(exc),
                    "tenantId": clean_tenant_id,
                    "workspaceId": workspace_id,
                    "hint": "Check payroll_headcount_monthly_snapshots table schema and unique constraint on (workspace_id, month_start).",
                },
            ) from exc

    snapshot = {
        "monthStart": _payroll_headcount_month_start_iso(snapshot_row.get("month_start")),
        "headcount": int(snapshot_row.get("headcount") or 0),
        "payrollCount": int(snapshot_row.get("payroll_count") or 0),
        "source": str(snapshot_row.get("source") or ""),
        "fetchedAt": _iso(snapshot_row.get("fetched_at")) or "",
        "createdAt": _iso(snapshot_row.get("created_at")) or "",
        "updatedAt": _iso(snapshot_row.get("updated_at")) or "",
    }

    try:
        while True:
            try:
                payload = payroll_headcount_payload(user)
                break
            except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
                if not _repair_schema_once():
                    raise
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception(
            "payroll_headcount_payload_failed user_id=%s tenant_id=%s phase=payload_build",
            user.get("id"),
            clean_tenant_id,
        )
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail={
                "message": "Payroll headcount sync saved data but failed while rebuilding the dashboard payload.",
                "phase": "payload_build",
                "error": _sync_error_message(exc),
                "tenantId": clean_tenant_id,
                "workspaceId": workspace_id,
            },
        ) from exc
    return {
        "workspace": next(
            (
                row
                for row in payload.get("workspaces") or []
                if str(row.get("tenantId") or "").strip() == clean_tenant_id
            ),
            workspace,
        ),
        "snapshot": snapshot,
        "errors": errors,
        "payrollHeadcount": payload,
    }


def sync_payroll_headcount_with_ignition(user: dict) -> dict:
    allowed_plan_labels = {"Micro", "Starter", "Standard", "Premium", "Ultimate"}
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, tenant_id, tenant_name
                FROM payroll_headcount_workspaces
                WHERE user_id = %s
                ORDER BY created_at ASC
                """,
                (user["id"],),
            )
            workspace_rows = cursor.fetchall() or []
            cursor.execute(
                """
                SELECT payload,
                       COALESCE(source_updated_at, source_created_at, created_at) AS ranked_at
                FROM ignition_reporting_records
                WHERE user_id = %s
                  AND dataset = 'proposals'
                ORDER BY COALESCE(source_updated_at, source_created_at, created_at) DESC
                LIMIT 20000
                """,
                (user["id"],),
            )
            proposal_rows = cursor.fetchall() or []
        connection.commit()

    active_ignition_by_key: dict[str, dict] = {}
    for row in proposal_rows:
        proposal = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        if not proposal:
            continue
        if not _is_accepted_ignition_proposal(proposal):
            continue
        if not _ignition_proposal_client_is_active(proposal):
            continue
        service_name = _ignition_proposal_service_name(proposal)
        plan_label = _plan_label_for_text(
            " ".join(
                [
                    service_name,
                    str(proposal.get("name") or ""),
                    str(proposal.get("reference_number") or ""),
                ]
            ).strip()
        )
        if plan_label not in allowed_plan_labels:
            continue
        client_name = _ignition_proposal_client_name(proposal)
        if not client_name:
            continue
        candidate = {
            "planName": plan_label,
            "clientName": client_name,
            "proposalName": str(proposal.get("name") or proposal.get("reference_number") or "").strip(),
            "rankedAt": row.get("ranked_at"),
        }
        for key in _ignition_name_match_keys(client_name):
            if not key:
                continue
            existing = active_ignition_by_key.get(key)
            existing_rank = existing.get("rankedAt") if isinstance(existing, dict) else None
            incoming_rank = candidate.get("rankedAt")
            if existing is None or (incoming_rank and (existing_rank is None or incoming_rank >= existing_rank)):
                active_ignition_by_key[key] = candidate

    updates: list[dict] = []
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            for workspace in workspace_rows:
                workspace_id = str(workspace.get("id") or "").strip()
                tenant_name = str(workspace.get("tenant_name") or "").strip()
                if not workspace_id:
                    continue
                matched = None
                tenant_name_for_match = tenant_name.replace("Headcount Workspace", "").strip()
                for key in _ignition_name_match_keys(tenant_name_for_match):
                    if key and key in active_ignition_by_key:
                        matched = active_ignition_by_key[key]
                        break
                ignition_plan_name = str((matched or {}).get("planName") or "").strip()
                ignition_client_name = str((matched or {}).get("clientName") or "").strip()
                ignition_proposal_name = str((matched or {}).get("proposalName") or "").strip()
                ignition_matched_at = now if matched else None
                cursor.execute(
                    """
                    UPDATE payroll_headcount_workspaces
                    SET ignition_plan_name = %s,
                        ignition_client_name = %s,
                        ignition_proposal_name = %s,
                        ignition_matched_at = %s,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    (
                        ignition_plan_name,
                        ignition_client_name,
                        ignition_proposal_name,
                        ignition_matched_at,
                        now,
                        workspace_id,
                    ),
                )
                updates.append(
                    {
                        "workspaceId": workspace_id,
                        "tenantId": str(workspace.get("tenant_id") or "").strip(),
                        "tenantName": tenant_name,
                        "planName": ignition_plan_name,
                        "clientName": ignition_client_name,
                        "proposalName": ignition_proposal_name,
                        "matched": bool(matched),
                    }
                )
        connection.commit()

    payload = payroll_headcount_payload(user)
    return {
        "updatedCount": len(updates),
        "matchedCount": sum(1 for item in updates if item.get("matched")),
        "unmatchedCount": sum(1 for item in updates if not item.get("matched")),
        "matches": updates,
        "payrollHeadcount": payload,
    }


