def _pi_record_sync_job_finish(
    *,
    job_id: str,
    status_value: str,
    error_code: str = "",
    error_message: str = "",
    metadata: dict | None = None,
) -> None:
    clean_job_id = str(job_id or "").strip()
    if not clean_job_id:
        return
    now = utcnow()
    metadata_payload = metadata if isinstance(metadata, dict) else {}
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE pi_clearing_sync_jobs
                SET status = %s,
                    error_code = %s,
                    error_message = %s,
                    metadata = %s::jsonb,
                    completed_at = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (
                    str(status_value or "completed").strip().lower() or "completed",
                    str(error_code or "").strip(),
                    str(error_message or "").strip(),
                    json.dumps(metadata_payload, default=_json_default),
                    now,
                    now,
                    clean_job_id,
                ),
            )
        connection.commit()


async def _pi_resolve_selected_pi_account(connection_row: dict, candidate_value: str) -> str:
    raw_value = str(candidate_value or "").strip()
    if not raw_value:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Select a PI nominal account before posting the adjustment.",
        )
    accounts = await _fetch_xero_chart_of_accounts(connection_row)
    account_by_code = {str(account.get("code") or "").strip().lower(): account for account in accounts}
    account_by_name = {str(account.get("name") or "").strip().lower(): account for account in accounts}
    selected_account = account_by_code.get(raw_value.lower())
    if selected_account is None:
        selected_account = account_by_name.get(raw_value.lower())
    if selected_account is None and "·" in raw_value:
        code_hint = raw_value.split("·", 1)[0].strip().lower()
        if code_hint:
            selected_account = account_by_code.get(code_hint)
    if selected_account is None:
        fuzzy = [
            account for account in accounts
            if raw_value.lower() in str(account.get("code") or "").strip().lower()
            or raw_value.lower() in str(account.get("name") or "").strip().lower()
        ]
        if len(fuzzy) == 1:
            selected_account = fuzzy[0]
    if selected_account is None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=f"PI nominal '{raw_value}' is not in the connected Xero chart of accounts. Re-select the PI nominal in Batch setup.",
        )
    return str(selected_account.get("code") or "").strip()


def _pi_close_predicate_checks(
    cursor,
    *,
    user: dict,
    tenant_id: str,
    run_row: dict,
    summary: dict,
) -> dict:
    month_start = run_row.get("month_start")
    month_end = run_row.get("month_end")
    if not isinstance(month_start, date) or not isinstance(month_end, date):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Run month bounds are missing.")
    expected_day_count = (month_end - month_start).days + 1
    cursor.execute(
        """
        SELECT *
        FROM pi_clearing_run_rows
        WHERE run_id = %s
          AND user_id = %s
        ORDER BY created_at ASC
        """,
        (run_row.get("id"), user["id"]),
    )
    persisted_rows = cursor.fetchall() or []
    xero_rows_from_persisted: list[dict] = []
    ignition_rows_from_persisted: list[dict] = []
    for row in persisted_rows:
        raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
        raw_xero_rows = raw_payload.get("xeroRows") if isinstance(raw_payload.get("xeroRows"), list) else []
        raw_ignition_rows = raw_payload.get("ignitionRows") if isinstance(raw_payload.get("ignitionRows"), list) else []
        for item in raw_xero_rows:
            if isinstance(item, dict):
                xero_rows_from_persisted.append(item)
        for item in raw_ignition_rows:
            if isinstance(item, dict):
                ignition_rows_from_persisted.append(item)
    recomputed_day_evidence = _pi_daily_evidence_rows(
        month_start=month_start,
        month_end=month_end,
        xero_rows=xero_rows_from_persisted,
        ignition_rows=ignition_rows_from_persisted,
    )
    day_evidence = recomputed_day_evidence
    xero_debit_total = sum((_money(item.get("xeroDebitTotal")) for item in day_evidence), start=Decimal("0.00"))
    xero_credit_total = sum((_money(item.get("xeroCreditTotal")) for item in day_evidence), start=Decimal("0.00"))
    finalisation = _pi_finalisation_state(
        xero_debit_total=xero_debit_total,
        xero_credit_total=xero_credit_total,
        xero_step1=summary.get("xeroStep1") if isinstance(summary.get("xeroStep1"), dict) else {},
    )
    difference_count = sum(1 for row in persisted_rows if _money(row.get("difference_total")).copy_abs() > Decimal("0.005"))
    allowed_day_statuses = {"balanced", "no_activity_confirmed"}
    complete_day_count = sum(
        1
        for item in day_evidence
        if isinstance(item, dict) and str(item.get("status") or "").strip().lower() in allowed_day_statuses
    )
    all_days_have_hashes = all(
        isinstance(item, dict) and str(item.get("sourceHash") or "").strip()
        for item in day_evidence
    ) if day_evidence else False

    cursor.execute(
        """
        SELECT COUNT(*) AS unresolved_count
        FROM pi_clearing_run_rows
        WHERE run_id = %s
          AND user_id = %s
          AND COALESCE(resolution_status, 'pending') NOT IN ('credit_note_created', 'balanced_by_existing_credit_note')
          AND ABS(difference_total) > 0.005
        """,
        (run_row.get("id"), user["id"]),
    )
    unresolved_count = int((cursor.fetchone() or {}).get("unresolved_count") or 0)
    cursor.execute(
        """
        SELECT COUNT(*) AS pending_actions
        FROM pi_clearing_credit_notes
        WHERE run_id = %s
          AND user_id = %s
          AND COALESCE(status, 'created') NOT IN ('created', 'voided')
        """,
        (run_row.get("id"), user["id"]),
    )
    pending_action_count = int((cursor.fetchone() or {}).get("pending_actions") or 0)
    cursor.execute(
        """
        SELECT MAX(updated_at) AS source_updated_at
        FROM payments
        WHERE tenant_id = %s
          AND payment_date >= %s
          AND payment_date <= %s
        """,
        (tenant_id, month_start, month_end),
    )
    payments_updated_at = (cursor.fetchone() or {}).get("source_updated_at")
    cursor.execute(
        """
        SELECT MAX(COALESCE(source_updated_at, updated_at, created_at)) AS source_updated_at
        FROM ignition_reporting_records
        WHERE user_id = %s
        """,
        (user["id"],),
    )
    ignition_updated_at = (cursor.fetchone() or {}).get("source_updated_at")
    source_updated_candidates = [item for item in (payments_updated_at, ignition_updated_at) if isinstance(item, datetime)]
    source_updated_at = max(source_updated_candidates) if source_updated_candidates else None
    run_updated_at = run_row.get("updated_at")
    source_unchanged_since_run = (
        not isinstance(source_updated_at, datetime)
        or not isinstance(run_updated_at, datetime)
        or source_updated_at <= run_updated_at
    )
    account_code = str(run_row.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE).strip() or PI_CLEARING_DEFAULT_ACCOUNT_CODE
    fresh_xero_rows, _fresh_tenant_id, _fresh_last_refreshed_at = _pi_load_xero_payments(user, month_start, month_end, account_code)
    fresh_xero_step1 = _pi_step1_xero_credit_debit_check(fresh_xero_rows)
    fresh_xero_debit_total = sum((_money(item.get("amount")) for item in fresh_xero_rows if _money(item.get("amount")) > Decimal("0.00")), start=Decimal("0.00"))
    fresh_xero_credit_total = sum((_money(item.get("amount")).copy_abs() for item in fresh_xero_rows if _money(item.get("amount")) < Decimal("0.00")), start=Decimal("0.00"))
    fresh_finalisation = _pi_finalisation_state(
        xero_debit_total=fresh_xero_debit_total,
        xero_credit_total=fresh_xero_credit_total,
        xero_step1=fresh_xero_step1,
    )
    absolute_closing_variance = sum((_money(row.get("difference_total")) for row in persisted_rows), start=Decimal("0.00")).copy_abs()
    debit_credit_delta = _money(finalisation.get("debitCreditDifference")).copy_abs()
    checks = [
        {
            "code": "FOUNDATION_MONTH",
            "label": "Foundation month is on/after 2026-01",
            "passed": _pi_month_start(month_start) >= _pi_month_start(PI_CLEARING_BATCH_HARD_START),
            "evidence": {"month": _pi_month_key(month_start), "foundationMonth": _pi_month_key(PI_CLEARING_BATCH_HARD_START)},
        },
        {
            "code": "DAILY_COVERAGE",
            "label": "Every calendar day has durable evidence",
            "passed": len(day_evidence) == expected_day_count and complete_day_count == expected_day_count and all_days_have_hashes,
            "evidence": {
                "expectedDayCount": expected_day_count,
                "storedDayCount": len(day_evidence),
                "completeDayCount": complete_day_count,
                "allDaysHaveSourceHash": all_days_have_hashes,
            },
        },
        {
            "code": "UNRESOLVED_DIFFERENCES",
            "label": "No unresolved difference rows remain",
            "passed": difference_count == 0 and unresolved_count == 0,
            "evidence": {
                "summaryDifferenceCount": difference_count,
                "unresolvedDifferenceRows": unresolved_count,
            },
        },
        {
            "code": "PENDING_ACTIONS",
            "label": "No pending/failed remediation actions remain",
            "passed": pending_action_count == 0,
            "evidence": {"pendingActionCount": pending_action_count},
        },
        {
            "code": "AGGREGATE_NIL",
            "label": "Aggregate PI closing variance is within one penny",
            "passed": absolute_closing_variance <= Decimal("0.01") and debit_credit_delta <= Decimal("0.01"),
            "evidence": {
                "differenceTotal": float(_money(absolute_closing_variance)),
                "debitCreditDifference": float(_money(finalisation.get("debitCreditDifference"))),
            },
        },
        {
            "code": "STEP1_CLEAR",
            "label": "Step 1 debit/credit gate is fully clear",
            "passed": bool(finalisation.get("canFinalise")) and int(finalisation.get("missingCreditCount") or 0) == 0,
            "evidence": finalisation,
        },
        {
            "code": "SOURCE_UNCHANGED",
            "label": "No source change since final run snapshot",
            "passed": source_unchanged_since_run,
            "evidence": {"runUpdatedAt": _iso(run_updated_at), "sourceUpdatedAt": _iso(source_updated_at)},
        },
        {
            "code": "XERO_MONTH_END_DIRECT_NIL",
            "label": "Direct Xero month-end PI control re-read is nil",
            "passed": bool(fresh_finalisation.get("canFinalise")) and _money(fresh_finalisation.get("debitCreditDifference")).copy_abs() <= Decimal("0.01"),
            "evidence": {
                "accountCode": account_code,
                "xeroRowCount": len(fresh_xero_rows),
                "xeroDebitTotal": float(_money(fresh_xero_debit_total)),
                "xeroCreditTotal": float(_money(fresh_xero_credit_total)),
                "debitCreditDifference": float(_money(fresh_finalisation.get("debitCreditDifference"))),
                "missingCreditCount": int(fresh_finalisation.get("missingCreditCount") or 0),
            },
        },
    ]
    failures = [item for item in checks if not item.get("passed")]
    return {"canClose": not failures, "checks": checks, "failures": failures}


def _pi_step2_ledger_rows(xero_rows: list[dict]) -> list[dict]:
    rows: list[dict] = []
    for row in xero_rows or []:
        amount = _money(row.get("amount"))
        debit = amount if amount > Decimal("0.00") else Decimal("0.00")
        credit = amount.copy_abs() if amount < Decimal("0.00") else Decimal("0.00")
        rows.append(
            {
                "paymentId": str(row.get("paymentId") or "").strip(),
                "date": str(row.get("paidOn") or "").strip()[:10],
                "contact": str(row.get("clientName") or "Unknown client").strip() or "Unknown client",
                "description": str(((row.get("raw") or {}) if isinstance(row.get("raw"), dict) else {}).get("Reference") or row.get("reference") or "").strip(),
                "source": "Receive Money" if credit > Decimal("0.00") else "Receivable Payment",
                "debit": float(_money(debit)),
                "credit": float(_money(credit)),
            }
        )
    rows.sort(key=lambda item: (str(item.get("date") or ""), str(item.get("contact") or "")))
    return rows


def _pi_local_step2_reconciliation(ledger_rows: list[dict]) -> dict:
    tolerance = Decimal("0.01")
    by_date: dict[str, dict] = {}
    for row in ledger_rows or []:
        date_key = str(row.get("date") or "").strip()
        bucket = by_date.setdefault(date_key, {"debits": [], "credits": []})
        debit = _money(row.get("debit"))
        credit = _money(row.get("credit"))
        if debit > Decimal("0.00"):
            bucket["debits"].append(row)
        if credit > Decimal("0.00"):
            bucket["credits"].append(row)

    def _find_same_date_combo(target: Decimal, debits: list[dict], debit_used: list[bool]) -> tuple[list[int], Decimal]:
        available = [
            (index, _money(item.get("debit")))
            for index, item in enumerate(debits)
            if not debit_used[index] and _money(item.get("debit")) > Decimal("0.00")
        ]
        available.sort(key=lambda item: item[1], reverse=True)
        available = available[:24]
        if not available:
            return [], Decimal("0.00")

        best: tuple[tuple[Decimal, int], list[int], Decimal] | None = None
        max_depth = 6
        max_nodes = 3000
        visited = 0

        def _dfs(start: int, picked: list[int], running_total: Decimal) -> None:
            nonlocal best, visited
            visited += 1
            if visited > max_nodes:
                return
            if picked:
                delta = abs(running_total - target)
                if delta <= tolerance:
                    score = (delta, len(picked))
                    if best is None or score < best[0]:
                        best = (score, list(picked), running_total)
                        if delta == Decimal("0.00") and len(picked) == 1:
                            return
            if len(picked) >= max_depth or start >= len(available):
                return
            if running_total > target + tolerance:
                return
            for cursor in range(start, len(available)):
                debit_index, amount = available[cursor]
                _dfs(cursor + 1, picked + [debit_index], running_total + amount)

        _dfs(0, [], Decimal("0.00"))
        if not best:
            return [], Decimal("0.00")
        return best[1], best[2]

    unmatched_rows: list[dict] = []
    hidden_pair_count = 0
    unmatched_total = Decimal("0.00")
    for date_key in sorted(by_date.keys()):
        bucket = by_date.get(date_key) or {}
        debits = sorted((bucket.get("debits") or []), key=lambda item: _money(item.get("debit")), reverse=True)
        credits = sorted((bucket.get("credits") or []), key=lambda item: _money(item.get("credit")), reverse=True)
        debit_used = [False] * len(debits)
        for credit_row in credits:
            credit_amount = _money(credit_row.get("credit"))
            matched_indexes, matched_total = _find_same_date_combo(credit_amount, debits, debit_used)
            if matched_indexes and abs(matched_total - credit_amount) <= tolerance:
                for index in matched_indexes:
                    debit_used[index] = True
                hidden_pair_count += 1
                continue
            unmatched_total += credit_amount
            combo_hint = "No same-date debit combination balances this credit."
            if matched_total > Decimal("0.00"):
                combo_hint = (
                    f"Same-date debit combination reached £{matched_total:.2f} versus credit £{credit_amount:.2f}."
                )
            unmatched_rows.append(
                {
                    "date": date_key,
                    "contact": str(credit_row.get("contact") or "Unknown client"),
                    "description": str(credit_row.get("description") or "").strip() or "--",
                    "source": str(credit_row.get("source") or "").strip() or "--",
                    "credit": float(credit_amount),
                    "matchingDebitTotal": float(_money(matched_total)),
                    "unmatchedAmount": float(_money(max(Decimal("0.00"), credit_amount - matched_total))),
                    "aiStatus": "Needs review",
                    "aiHint": combo_hint,
                }
            )
    return {
        "summary": (
            f"Hid {hidden_pair_count} same-date debit/credit pair(s). "
            f"Flagged {len(unmatched_rows)} unmatched credit entr{'y' if len(unmatched_rows) == 1 else 'ies'} "
            f"totalling £{_money(unmatched_total):.2f}."
        ),
        "engine": "local",
        "confidence": 0.0,
        "hiddenPairCount": hidden_pair_count,
        "unmatchedCreditCount": len(unmatched_rows),
        "unmatchedCreditTotal": float(_money(unmatched_total)),
        "rows": unmatched_rows,
    }


async def _pi_ai_step2_reconciliation(month_label: str, ledger_rows: list[dict], user_id: str | None = None) -> dict:
    local = _pi_local_step2_reconciliation(ledger_rows)
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip() or not ledger_rows:
        return local

    request_rows = [
        {
            "paymentId": str(row.get("paymentId") or ""),
            "date": str(row.get("date") or ""),
            "contact": str(row.get("contact") or ""),
            "description": str(row.get("description") or ""),
            "source": str(row.get("source") or ""),
            "debit": float(_money(row.get("debit"))),
            "credit": float(_money(row.get("credit"))),
        }
        for row in (ledger_rows or [])[:420]
    ]
    request_body = {
        "input": [
            {
                "role": "system",
                "content": (
                    "You reconcile PI clearing ledger lines. Use only same-date matching. "
                    "A debit can be used once. A credit is fully matched when one or more unused same-date debits sum to that credit within 0.01. "
                    "You may use split combinations (for example 100 = 50 + 50) and include refunds where signed amounts net correctly. "
                    "Hide fully matched pairs and return only unmatched credits. "
                    "Set matchingDebitTotal to the debit sum used for each unmatched credit."
                ),
            },
            {
                "role": "user",
                "content": (
                    f"Month: {month_label}\n"
                    f"LedgerRows: {json.dumps(request_rows, default=_json_default)}\n"
                    "Return strict JSON only."
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "pi_clearing_step2_reconciliation",
                "schema": PI_CLEARING_STEP2_RECONCILIATION_SCHEMA,
                "strict": True,
            }
        },
    }
    try:
        payload = await _post_openai_responses(
            request_body,
            "PI Clearing Step 2 reconciliation",
            preferred_model=settings.openai_model,
            user_id=user_id,
            feature="openai-core",
            page="practice-tools",
        )
        parsed = _load_openai_json_response(payload, "OpenAI returned invalid PI Clearing Step 2 reconciliation JSON.")
        ai_rows = []
        for item in (parsed.get("rows") or []):
            if not isinstance(item, dict):
                continue
            credit = _money(item.get("credit"))
            unmatched = _money(item.get("unmatchedAmount"))
            ai_rows.append(
                {
                    "date": str(item.get("date") or "").strip(),
                    "contact": str(item.get("contact") or "Unknown client").strip() or "Unknown client",
                    "description": str(item.get("description") or "").strip() or "--",
                    "source": str(item.get("source") or "").strip() or "--",
                    "credit": float(credit if credit > Decimal("0.00") else Decimal("0.00")),
                    "matchingDebitTotal": float(_money(item.get("matchingDebitTotal"))),
                    "unmatchedAmount": float(unmatched if unmatched > Decimal("0.00") else Decimal("0.00")),
                    "aiStatus": str(item.get("aiStatus") or "Needs review").strip() or "Needs review",
                    "aiHint": str(item.get("aiHint") or "").strip() or "Review this unmatched credit entry.",
                }
            )
        unmatched_total = sum((_money(item.get("unmatchedAmount")) for item in ai_rows), start=Decimal("0.00"))
        return {
            "summary": str(parsed.get("summary") or "").strip() or str(local.get("summary") or ""),
            "engine": "openai",
            "confidence": float(parsed.get("confidence") or 0),
            "hiddenPairCount": int(parsed.get("hiddenPairCount") or 0),
            "unmatchedCreditCount": int(parsed.get("unmatchedCreditCount") or len(ai_rows)),
            "unmatchedCreditTotal": float(_money(parsed.get("unmatchedCreditTotal") or unmatched_total)),
            "rows": ai_rows,
        }
    except Exception as exc:
        logger.exception("PI clearing Step 2 AI reconciliation failed: %s", exc)
        fallback = dict(local)
        fallback["engine"] = "local_error"
        fallback["summary"] = f"{local.get('summary') or ''} AI reconciliation failed; using local fallback."
        return fallback


def _pi_payout_batches_from_ignition_rows(ignition_rows: list[dict]) -> list[dict]:
    grouped: dict[str, dict] = {}
    for row in ignition_rows or []:
        paid_on = str(row.get("paidOn") or "").strip()
        payout_id = str(row.get("payoutId") or row.get("paymentId") or "").strip() or "unlabeled-batch"
        key = f"{paid_on}|{payout_id}"
        bucket = grouped.setdefault(
            key,
            {
                "key": key,
                "paidOn": paid_on,
                "payoutId": payout_id,
                "netPayout": Decimal("0.00"),
                "grossCollections": Decimal("0.00"),
                "reversals": Decimal("0.00"),
            },
        )
        amount = _money(row.get("amount"))
        bucket["netPayout"] += amount
        if amount < Decimal("0.00"):
            bucket["reversals"] += amount.copy_abs()
        else:
            bucket["grossCollections"] += amount
    return list(grouped.values())


def _pi_xero_credit_rows(xero_rows: list[dict]) -> list[dict]:
    items: list[dict] = []
    for row in xero_rows or []:
        amount = _money(row.get("amount"))
        if amount >= Decimal("0.00"):
            continue
        items.append(
            {
                "paymentId": str(row.get("paymentId") or "").strip(),
                "paidOn": str(row.get("paidOn") or "").strip(),
                "creditAmount": amount.copy_abs(),
                "reference": str(row.get("reference") or "").strip(),
            }
        )
    return items


def _pi_easter_sunday(year: int) -> date:
    """Return Easter Sunday for Gregorian calendar years."""
    a = year % 19
    b = year // 100
    c = year % 100
    d = b // 4
    e = b % 4
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i = c // 4
    k = c % 4
    l = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l) // 451
    month = (h + l - 7 * m + 114) // 31
    day = ((h + l - 7 * m + 114) % 31) + 1
    return date(year, month, day)


def _pi_first_weekday_of_month(year: int, month: int, weekday: int) -> date:
    current = date(year, month, 1)
    offset = (weekday - current.weekday()) % 7
    return current + timedelta(days=offset)


def _pi_last_weekday_of_month(year: int, month: int, weekday: int) -> date:
    last_day = date(year, month, monthrange(year, month)[1])
    offset = (last_day.weekday() - weekday) % 7
    return last_day - timedelta(days=offset)


def _pi_observed_bank_holiday(day_value: date) -> date:
    if day_value.weekday() == 5:
        return day_value + timedelta(days=2)
    if day_value.weekday() == 6:
        return day_value + timedelta(days=1)
    return day_value


def _pi_uk_bank_holidays(year: int) -> set[date]:
    easter = _pi_easter_sunday(year)
    new_year_observed = _pi_observed_bank_holiday(date(year, 1, 1))
    christmas_observed = _pi_observed_bank_holiday(date(year, 12, 25))
    boxing_observed = _pi_observed_bank_holiday(date(year, 12, 26))
    if boxing_observed == christmas_observed:
        boxing_observed += timedelta(days=1)
    return {
        new_year_observed,
        easter - timedelta(days=2),  # Good Friday
        easter + timedelta(days=1),  # Easter Monday
        _pi_first_weekday_of_month(year, 5, 0),  # Early May bank holiday
        _pi_last_weekday_of_month(year, 5, 0),  # Spring bank holiday
        _pi_last_weekday_of_month(year, 8, 0),  # Summer bank holiday
        christmas_observed,
        boxing_observed,
    }


def _pi_is_non_processing_day(day_value: date | None) -> bool:
    if day_value is None:
        return False
    if day_value.weekday() >= 5:
        return True
    return day_value in _pi_uk_bank_holidays(day_value.year)


def _pi_match_ignition_payouts_to_xero_credits(ignition_rows: list[dict], xero_rows: list[dict]) -> dict:
    payouts = sorted(
        _pi_payout_batches_from_ignition_rows(ignition_rows),
        key=lambda item: (
            _parse_optional_iso_date(str(item.get("paidOn") or "")) or date.min,
            str(item.get("payoutId") or ""),
        ),
    )
    credits = sorted(
        _pi_xero_credit_rows(xero_rows),
        key=lambda item: _parse_optional_iso_date(str(item.get("paidOn") or "")) or date.min,
    )
    used_credit_indexes: set[int] = set()
    tolerance = Decimal("0.01")
    max_days = 7
    matched = 0
    missing: list[dict] = []
    rows: list[dict] = []

    for payout in payouts:
        net_amount = _money(payout.get("netPayout"))
        if net_amount <= Decimal("0.00"):
            continue
        payout_date = _parse_optional_iso_date(str(payout.get("paidOn") or ""))
        best_index: int | None = None
        best_distance: tuple[int, Decimal] | None = None
        for index, credit in enumerate(credits):
            if index in used_credit_indexes:
                continue
            credit_amount = _money(credit.get("creditAmount"))
            if abs(credit_amount - net_amount) > tolerance:
                continue
            credit_date = _parse_optional_iso_date(str(credit.get("paidOn") or ""))
            day_delta = abs((credit_date - payout_date).days) if credit_date and payout_date else 0
            if day_delta > max_days:
                continue
            ranking = (day_delta, abs(credit_amount - net_amount))
            if best_distance is None or ranking < best_distance:
                best_distance = ranking
                best_index = index
        if best_index is None:
            if _pi_is_non_processing_day(payout_date):
                matched += 1
                rows.append(
                    {
                        "payoutId": str(payout.get("payoutId") or "unlabeled-batch"),
                        "paidOn": str(payout.get("paidOn") or ""),
                        "ignitionNetPayout": float(net_amount),
                        "matched": True,
                        "matchReason": "non_processing_day",
                        "xeroCreditPaymentId": "",
                        "xeroCreditPaidOn": "",
                        "xeroCreditAmount": 0.0,
                    }
                )
                continue
            missing_item = {
                "payoutId": str(payout.get("payoutId") or "unlabeled-batch"),
                "paidOn": str(payout.get("paidOn") or ""),
                "amount": float(net_amount),
            }
            missing.append(missing_item)
            rows.append(
                {
                    "payoutId": missing_item["payoutId"],
                    "paidOn": missing_item["paidOn"],
                    "ignitionNetPayout": float(net_amount),
                    "matched": False,
                    "matchReason": "missing_xero_credit",
                    "xeroCreditPaymentId": "",
                    "xeroCreditPaidOn": "",
                    "xeroCreditAmount": 0.0,
                }
            )
            continue
        used_credit_indexes.add(best_index)
        credit = credits[best_index]
        matched += 1
        rows.append(
            {
                "payoutId": str(payout.get("payoutId") or "unlabeled-batch"),
                "paidOn": str(payout.get("paidOn") or ""),
                "ignitionNetPayout": float(net_amount),
                "matched": True,
                "matchReason": "xero_credit_matched",
                "xeroCreditPaymentId": str(credit.get("paymentId") or ""),
                "xeroCreditPaidOn": str(credit.get("paidOn") or ""),
                "xeroCreditAmount": float(_money(credit.get("creditAmount"))),
            }
        )
    return {
        "payoutCount": len(rows),
        "matchedCount": matched,
        "missingCount": len(missing),
        "missing": missing,
        "rows": rows,
    }


def _pi_run_payload(run_row: dict, rows: list[dict], credit_notes: list[dict]) -> dict:
    return {
        "id": str(run_row.get("id") or ""),
        "tenantId": str(run_row.get("tenant_id") or ""),
        "batchNumber": str(run_row.get("batch_number") or ""),
        "monthStart": run_row.get("month_start").isoformat() if run_row.get("month_start") else "",
        "monthEnd": run_row.get("month_end").isoformat() if run_row.get("month_end") else "",
        "accountCode": str(run_row.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE),
        "status": str(run_row.get("status") or "draft"),
        "summary": run_row.get("summary") if isinstance(run_row.get("summary"), dict) else {},
        "analysis": run_row.get("ai_analysis") if isinstance(run_row.get("ai_analysis"), dict) else {},
        "rows": rows,
        "creditNotes": credit_notes,
        "createdAt": _iso(run_row.get("created_at")) or "",
        "updatedAt": _iso(run_row.get("updated_at")) or "",
    }


def _pi_parse_batch_number(label: str) -> int | None:
    match = re.fullmatch(rf"{PI_CLEARING_BATCH_NUMBER_PREFIX}-(\d+)", str(label or "").strip().upper())
    if not match:
        return None
    return int(match.group(1))


def _pi_backfill_missing_batch_numbers(cursor, user_id: str) -> None:
    cursor.execute(
        """
        SELECT id, tenant_id, batch_number, month_start, created_at
        FROM pi_clearing_runs
        WHERE user_id = %s
        ORDER BY tenant_id ASC, month_start ASC, created_at ASC
        """,
        (user_id,),
    )
    rows = cursor.fetchall() or []
    if not rows:
        return

    max_by_tenant: dict[str, int] = {}
    for row in rows:
        tenant_id = str(row.get("tenant_id") or "").strip()
        parsed = _pi_parse_batch_number(str(row.get("batch_number") or ""))
        if parsed is None:
            continue
        max_by_tenant[tenant_id] = max(max_by_tenant.get(tenant_id, 0), parsed)

    for row in rows:
        current_label = str(row.get("batch_number") or "").strip()
        if current_label:
            continue
        tenant_id = str(row.get("tenant_id") or "").strip()
        next_number = max_by_tenant.get(tenant_id, 0) + 1
        batch_number = f"{PI_CLEARING_BATCH_NUMBER_PREFIX}-{next_number:03d}"
        cursor.execute(
            """
            UPDATE pi_clearing_runs
            SET batch_number = %s
            WHERE id = %s
              AND user_id = %s
            """,
            (batch_number, row.get("id"), user_id),
        )
        max_by_tenant[tenant_id] = next_number


def pi_clearing_payload(user: dict) -> dict:
    period_gate_payload = {
        "foundationMonth": _pi_month_key(PI_CLEARING_BATCH_HARD_START),
        "openMonth": _pi_month_key(PI_CLEARING_BATCH_HARD_START),
        "openStatus": PI_CLEARING_MONTH_STATUS_OPEN,
        "months": [],
    }
    gate_tenant_id = ""
    try:
        connection_row = get_master_xero_connection_for_user(user["id"])
        gate_tenant_id = str(connection_row.get("tenant_id") or "").strip()
    except HTTPException:
        gate_tenant_id = ""

    with get_connection() as connection:
        with connection.cursor() as cursor:
            close_rows: list[dict] = []
            deferred_events_summary = {"deferredCount": 0, "readyCount": 0, "latestDeferredAt": ""}
            _pi_backfill_missing_batch_numbers(cursor, user["id"])
            if gate_tenant_id:
                gate = _pi_apply_period_gate(cursor, user["id"], gate_tenant_id)
                period_gate_payload = {
                    "foundationMonth": str(gate.get("foundationMonth") or _pi_month_key(PI_CLEARING_BATCH_HARD_START)),
                    "openMonth": str(gate.get("openMonth") or _pi_month_key(PI_CLEARING_BATCH_HARD_START)),
                    "openStatus": str(gate.get("openStatus") or PI_CLEARING_MONTH_STATUS_OPEN),
                    "months": gate.get("months") if isinstance(gate.get("months"), list) else [],
                }
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_runs
                WHERE user_id = %s
                ORDER BY month_start DESC, updated_at DESC
                LIMIT 24
                """,
                (user["id"],),
            )
            run_rows = cursor.fetchall() or []
            run_ids = [str(row.get("id") or "") for row in run_rows if row.get("id")]
            rows_by_run: dict[str, list[dict]] = {}
            notes_by_run: dict[str, list[dict]] = {}
            approvals_by_run: dict[str, list[dict]] = {}
            latest_approval_by_row: dict[str, dict] = {}
            active_note_totals_by_run_row: dict[str, dict[str, Decimal]] = {}
            active_note_totals_by_run_contact: dict[str, dict[str, Decimal]] = {}
            if run_ids:
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_run_rows
                    WHERE run_id = ANY(%s)
                    ORDER BY ABS(difference_total) DESC, client_name ASC
                    """,
                    (run_ids,),
                )
                for row in cursor.fetchall() or []:
                    run_id = str(row.get("run_id") or "")
                    raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
                    raw_xero_rows = raw_payload.get("xeroRows") if isinstance(raw_payload.get("xeroRows"), list) else []
                    recalculated_xero_total = sum(
                        (
                            _money(item.get("amount")).copy_abs()
                            for item in raw_xero_rows
                            if isinstance(item, dict) and _money(item.get("amount")) < Decimal("0.00")
                        ),
                        start=Decimal("0.00"),
                    )
                    stored_xero_total = _money(row.get("xero_total"))
                    xero_total = recalculated_xero_total if raw_xero_rows else stored_xero_total
                    ignition_total = _money(row.get("ignition_total"))
                    existing_credit_note_total = _money(raw_payload.get("existingCreditNoteTotal"))
                    raw_difference = (xero_total - ignition_total).quantize(Decimal("0.01"))
                    difference_total = (raw_difference - existing_credit_note_total).quantize(Decimal("0.01"))
                    rows_by_run.setdefault(run_id, []).append(
                        {
                            "id": str(row.get("id") or ""),
                            "rowType": str(row.get("row_type") or "difference"),
                            "clientName": str(row.get("client_name") or ""),
                            "xeroContactId": str(row.get("xero_contact_id") or ""),
                            "xeroPaymentIds": row.get("xero_payment_ids") if isinstance(row.get("xero_payment_ids"), list) else [],
                            "ignitionPaymentIds": row.get("ignition_payment_ids") if isinstance(row.get("ignition_payment_ids"), list) else [],
                            "currencyCode": str(row.get("currency_code") or "GBP"),
                            "xeroTotal": float(_money(xero_total)),
                            "ignitionTotal": float(_money(ignition_total)),
                            "ignitionGrossTotal": float(_money(raw_payload.get("ignitionGrossTotal"))),
                            "ignitionReversalTotal": float(_money(raw_payload.get("ignitionReversalTotal"))),
                            "rawDifference": float(_money(raw_difference)),
                            "existingCreditNoteTotal": float(_money(existing_credit_note_total)),
                            "riskLevel": str(raw_payload.get("riskLevel") or "low"),
                            "riskScore": int(raw_payload.get("riskScore") or 0),
                            "explainer": str(raw_payload.get("explainer") or ""),
                            "payoutDate": str(raw_payload.get("payoutDate") or ""),
                            "step1MissingDebitTotal": float(_money(raw_payload.get("step1MissingDebitTotal"))),
                            "differenceTotal": float(_money(difference_total)),
                            "recommendation": str(row.get("recommendation") or ""),
                            "resolutionStatus": str(row.get("resolution_status") or "pending"),
                            "raw": raw_payload,
                        }
                    )
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_credit_notes
                    WHERE run_id = ANY(%s)
                    ORDER BY created_at DESC
                    """,
                    (run_ids,),
                )
                for note in cursor.fetchall() or []:
                    run_id = str(note.get("run_id") or "")
                    note_raw_payload = note.get("raw_payload") if isinstance(note.get("raw_payload"), dict) else {}
                    note_status = str(note.get("status") or "created").strip().lower()
                    note_amount = _money(note.get("amount"))
                    run_row_id = str(note.get("run_row_id") or "").strip()
                    contact_id = str(note.get("xero_contact_id") or "").strip()
                    notes_by_run.setdefault(run_id, []).append(
                        {
                            "id": str(note.get("id") or ""),
                            "runRowId": run_row_id,
                            "documentType": str(note_raw_payload.get("documentType") or "credit_note"),
                            "xeroContactId": contact_id,
                            "xeroCreditNoteId": str(note.get("xero_credit_note_id") or ""),
                            "xeroCreditNoteNumber": str(note.get("xero_credit_note_number") or ""),
                            "creditNoteDate": note.get("credit_note_date").isoformat() if note.get("credit_note_date") else "",
                            "amount": float(note_amount),
                            "currencyCode": str(note.get("currency_code") or "GBP"),
                            "accountCode": str(note.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE),
                            "businessActionKey": str(note.get("business_action_key") or ""),
                            "idempotencyKey": str(note.get("idempotency_key") or ""),
                            "payloadHash": str(note.get("payload_hash") or ""),
                            "status": str(note.get("status") or "created"),
                            "createdAt": _iso(note.get("created_at")) or "",
                        }
                    )
                    if note_status != "created":
                        continue
                    if run_row_id:
                        row_totals = active_note_totals_by_run_row.setdefault(run_id, {})
                        row_totals[run_row_id] = (row_totals.get(run_row_id) or Decimal("0.00")) + note_amount
                    elif contact_id:
                        contact_totals = active_note_totals_by_run_contact.setdefault(run_id, {})
                        contact_totals[contact_id] = (contact_totals.get(contact_id) or Decimal("0.00")) + note_amount
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_action_approvals
                    WHERE run_id = ANY(%s)
                    ORDER BY created_at DESC
                    """,
                    (run_ids,),
                )
                for approval in cursor.fetchall() or []:
                    run_id = str(approval.get("run_id") or "")
                    run_row_id = str(approval.get("run_row_id") or "")
                    approval_payload = {
                        "id": str(approval.get("id") or ""),
                        "runRowId": run_row_id,
                        "businessActionKey": str(approval.get("business_action_key") or ""),
                        "payloadHash": str(approval.get("payload_hash") or ""),
                        "sourceSnapshotHash": str(approval.get("source_snapshot_hash") or ""),
                        "status": str(approval.get("status") or ""),
                        "notes": str(approval.get("notes") or ""),
                        "approvedByUserId": str(approval.get("approved_by_user_id") or ""),
                        "approvedAt": _iso(approval.get("approved_at")) or "",
                        "postedAt": _iso(approval.get("posted_at")) or "",
                        "verifiedAt": _iso(approval.get("verified_at")) or "",
                        "createdAt": _iso(approval.get("created_at")) or "",
                        "updatedAt": _iso(approval.get("updated_at")) or "",
                    }
                    approvals_by_run.setdefault(run_id, []).append(approval_payload)
                    if run_row_id and run_row_id not in latest_approval_by_row:
                        latest_approval_by_row[run_row_id] = approval_payload
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_month_closes
                WHERE user_id = %s
                ORDER BY month_start DESC, close_sequence DESC
                LIMIT 24
                """,
                (user["id"],),
            )
            close_rows = cursor.fetchall() or []
            if gate_tenant_id:
                cursor.execute(
                    """
                    SELECT
                        SUM(CASE WHEN status = 'deferred' THEN 1 ELSE 0 END) AS deferred_count,
                        SUM(CASE WHEN status = 'ready' THEN 1 ELSE 0 END) AS ready_count,
                        MAX(CASE WHEN status = 'deferred' THEN updated_at ELSE NULL END) AS latest_deferred_at
                    FROM pi_clearing_deferred_events
                    WHERE user_id = %s
                      AND tenant_id = %s
                    """,
                    (user["id"], gate_tenant_id),
                )
                deferred_row = cursor.fetchone() or {}
                deferred_events_summary = {
                    "deferredCount": int(deferred_row.get("deferred_count") or 0),
                    "readyCount": int(deferred_row.get("ready_count") or 0),
                    "latestDeferredAt": _iso(deferred_row.get("latest_deferred_at")) or "",
                }
        connection.commit()
    runs: list[dict] = []
    for row in run_rows:
        run_id = str(row.get("id") or "")
        run_rows_payload = rows_by_run.get(run_id, [])
        run_credit_notes = notes_by_run.get(run_id, [])
        active_row_totals = active_note_totals_by_run_row.get(run_id, {})
        active_contact_totals = active_note_totals_by_run_contact.get(run_id, {})
        for item in run_rows_payload:
            row_id = str(item.get("id") or "").strip()
            contact_id = str(item.get("xeroContactId") or "").strip()
            row_total = _money(active_row_totals.get(row_id))
            contact_total = _money(active_contact_totals.get(contact_id)) if contact_id else Decimal("0.00")
            existing_credit_total = row_total if row_total > Decimal("0.00") else contact_total
            raw_difference = _money(item.get("rawDifference"))
            item["existingCreditNoteTotal"] = float(_money(existing_credit_total))
            item["differenceTotal"] = float(_money(raw_difference - existing_credit_total))
            latest_approval = latest_approval_by_row.get(row_id)
            if latest_approval:
                item["actionApprovalStatus"] = str(latest_approval.get("status") or "")
                item["actionBusinessKey"] = str(latest_approval.get("businessActionKey") or "")
                item["actionApprovalUpdatedAt"] = str(latest_approval.get("updatedAt") or "")
                item["actionApprovalNotes"] = str(latest_approval.get("notes") or "")
        payload = _pi_run_payload(row, run_rows_payload, run_credit_notes)
        payload["actionApprovals"] = approvals_by_run.get(run_id, [])
        summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
        recalculated_xero_total = sum((_money(item.get("xeroTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_ignition_total = sum((_money(item.get("ignitionTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_ignition_gross_total = sum((_money(item.get("ignitionGrossTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_ignition_reversal_total = sum((_money(item.get("ignitionReversalTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_existing_cn_total = sum((_money(item.get("existingCreditNoteTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_difference_total = sum((_money(item.get("differenceTotal")) for item in run_rows_payload), start=Decimal("0.00"))
        recalculated_difference_count = sum(1 for item in run_rows_payload if _money(item.get("differenceTotal")).copy_abs() > Decimal("0.005"))
        recalculated_credit_note_candidate_count = sum(
            1 for item in run_rows_payload
            if _money(item.get("differenceTotal")) > Decimal("0.00") and str(item.get("xeroContactId") or "").strip()
        )
        xero_net_total = Decimal("0.00")
        xero_debit_total = Decimal("0.00")
        xero_credit_total = Decimal("0.00")
        for item in run_rows_payload:
            raw_payload = item.get("raw") if isinstance(item.get("raw"), dict) else {}
            raw_xero_rows = raw_payload.get("xeroRows") if isinstance(raw_payload.get("xeroRows"), list) else []
            for xero_row in raw_xero_rows:
                if not isinstance(xero_row, dict):
                    continue
                amount = _money(xero_row.get("amount"))
                xero_net_total += amount
                if amount > Decimal("0.00"):
                    xero_debit_total += amount
                elif amount < Decimal("0.00"):
                    xero_credit_total += amount.copy_abs()
        payload["summary"] = {
            **summary,
            "xeroTotal": float(_money(recalculated_xero_total)),
            "xeroNetTotal": float(_money(xero_net_total)),
            "xeroDebitTotal": float(_money(xero_debit_total)),
            "xeroCreditTotal": float(_money(xero_credit_total or recalculated_xero_total)),
            "ignitionTotal": float(_money(recalculated_ignition_total)),
            "ignitionGrossTotal": float(_money(recalculated_ignition_gross_total)),
            "ignitionReversalTotal": float(_money(recalculated_ignition_reversal_total)),
            "existingCreditNoteTotal": float(_money(recalculated_existing_cn_total)),
            "differenceTotal": float(_money(recalculated_difference_total)),
            "differenceCount": int(recalculated_difference_count),
            "creditNoteCandidateCount": int(recalculated_credit_note_candidate_count),
        }
        runs.append(payload)
    close_records = [
        {
            "id": str(row.get("id") or ""),
            "tenantId": str(row.get("tenant_id") or ""),
            "monthStart": row.get("month_start").isoformat() if row.get("month_start") else "",
            "monthEnd": row.get("month_end").isoformat() if row.get("month_end") else "",
            "closeRunId": str(row.get("close_run_id") or ""),
            "closeSequence": int(row.get("close_sequence") or 1),
            "approvedByUserId": str(row.get("approved_by_user_id") or ""),
            "approvedAt": _iso(row.get("approved_at")) or "",
            "closedAt": _iso(row.get("closed_at")) or "",
            "invalidatedAt": _iso(row.get("invalidated_at")) or "",
            "invalidatedReason": str(row.get("invalidated_reason") or ""),
            "snapshotHash": str(row.get("snapshot_hash") or ""),
            "checks": (row.get("check_results") or {}).get("checks") if isinstance(row.get("check_results"), dict) else [],
        }
        for row in close_rows
    ]
    return {
        "runs": runs,
        "periodGate": period_gate_payload,
        "closeRecords": close_records,
        "deferredEvents": deferred_events_summary,
    }


async def delete_pi_clearing_run(user: dict, run_id: str, payload: dict | None = None) -> dict:
    requested_run_id = str(run_id or "").strip()
    if not requested_run_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PI Clearing run id is required.")
    # Batch delete is intentionally local-only.
    # Posted Xero documents are left untouched.
    run_row = None
    resolved_run_id = requested_run_id
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_runs
                WHERE id::text = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (requested_run_id, user["id"]),
            )
            run_row = cursor.fetchone()
            if not run_row:
                updated = pi_clearing_payload(user)
                return {"deletedRunId": requested_run_id, "alreadyDeleted": True, "runs": updated.get("runs") or []}
            tenant_id = str(run_row.get("tenant_id") or "").strip()
            month_start = run_row.get("month_start")
            month_end = run_row.get("month_end")
            if tenant_id and isinstance(month_start, date) and isinstance(month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=tenant_id,
                    requested_start=_pi_month_start(month_start),
                    requested_end=month_end,
                )
            resolved_run_id = str(run_row.get("id") or requested_run_id).strip()
        connection.commit()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM pi_clearing_runs
                WHERE id::text = %s
                  AND user_id = %s
                """,
                (resolved_run_id, user["id"]),
            )
        connection.commit()
    updated = pi_clearing_payload(user)
    return {
        "deletedRunId": resolved_run_id,
        "runs": updated.get("runs") or [],
    }


async def save_pi_clearing_step1_fix(user: dict, run_id: str, run_row_id: str, payload: dict | None = None) -> dict:
    clean_run_id = str(run_id or "").strip()
    clean_row_id = str(run_row_id or "").strip()
    safe_payload = payload if isinstance(payload, dict) else {}
    fix_payload = safe_payload.get("fix") if isinstance(safe_payload.get("fix"), dict) else {}
    if not clean_run_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PI Clearing run id is required.")
    if not clean_row_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PI Clearing row id is required.")
    if not fix_payload:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Fix payload is required.")
    try:
        line_count = int(fix_payload.get("lineCount") or 0)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Fix lineCount must be numeric.") from exc
    try:
        missing_debit_amount = float(_money(fix_payload.get("missingDebitAmount")))
    except Exception as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Fix missingDebitAmount must be numeric.") from exc

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT rr.id, rr.raw_payload, run.month_start, run.month_end, run.tenant_id
                FROM pi_clearing_run_rows AS rr
                JOIN pi_clearing_runs AS run ON run.id = rr.run_id
                WHERE run.id = %s
                  AND rr.id = %s
                  AND run.user_id = %s
                LIMIT 1
                """,
                (clean_run_id, clean_row_id, user["id"]),
            )
            row = cursor.fetchone()
            if not row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing row not found for this run.")
            tenant_id = str(row.get("tenant_id") or "").strip()
            month_start = row.get("month_start")
            month_end = row.get("month_end")
            if tenant_id and isinstance(month_start, date) and isinstance(month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=tenant_id,
                    requested_start=_pi_month_start(month_start),
                    requested_end=month_end,
                )

            raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
            step1_fix = {
                "savedAt": _iso(utcnow()) or "",
                "step1RowKey": str(fix_payload.get("step1RowKey") or "").strip(),
                "targetDate": str(fix_payload.get("targetDate") or "").strip(),
                "missingDebitAmount": missing_debit_amount,
                "payoutId": str(fix_payload.get("payoutId") or "").strip(),
                "lineCount": line_count,
                "clientName": str(fix_payload.get("clientName") or "").strip(),
                "xeroContactId": str(fix_payload.get("xeroContactId") or "").strip(),
                "runRowId": clean_row_id,
            }
            next_raw = dict(raw_payload)
            next_raw["step1AiFix"] = step1_fix

            cursor.execute(
                """
                UPDATE pi_clearing_run_rows
                SET raw_payload = %s::jsonb,
                    updated_at = NOW()
                WHERE id = %s
                """,
                (json.dumps(next_raw, default=_json_default), clean_row_id),
            )
            cursor.execute(
                """
                UPDATE pi_clearing_runs
                SET updated_at = NOW()
                WHERE id = %s
                  AND user_id = %s
                """,
                (clean_run_id, user["id"]),
            )
        connection.commit()
    return {"saved": True, "runId": clean_run_id, "rowId": clean_row_id}


def _pi_clearing_account_code_for_user(user: dict, payload: dict | None = None) -> str:
    requested = str((payload or {}).get("accountCode") or "").strip()
    configured = ""
    locked = False
    try:
        connection_row = get_master_xero_connection_for_user(user["id"])
        settings = posting_settings_for_tenant(connection_row.get("tenant_id"))
        configured = str(settings.get("piClearingAccountCode") or "").strip()
        locked = bool(settings.get("piClearingAccountLocked"))
    except HTTPException:
        configured = ""
        locked = False
    if locked and configured:
        # Defensive: honour the saved locked code even if older clients send a stale accountCode.
        return configured
    if requested:
        return requested
    return configured or PI_CLEARING_DEFAULT_ACCOUNT_CODE


def _pi_assert_writes_enabled_for_tenant(tenant_id: str) -> None:
    settings = posting_settings_for_tenant(tenant_id)
    if not bool(settings.get("piClearingWritesEnabled", True)):
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "code": "PI_CLEARING_WRITES_DISABLED",
                "message": "PI Clearing write actions are disabled for this tenant. Enable writes in PI setup before posting or voiding.",
            },
        )


def _pi_next_batch_number(cursor, user_id: str, tenant_id: str) -> str:
    cursor.execute(
        """
        SELECT batch_number
        FROM pi_clearing_runs
        WHERE user_id = %s
          AND tenant_id = %s
        """,
        (user_id, tenant_id),
    )
    rows = cursor.fetchall() or []
    max_number = 0
    for row in rows:
        parsed = _pi_parse_batch_number(str(row.get("batch_number") or ""))
        if parsed is None:
            continue
        max_number = max(max_number, parsed)
    return f"{PI_CLEARING_BATCH_NUMBER_PREFIX}-{max_number + 1:03d}"


async def run_pi_clearing_workflow(user: dict, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    month_start, month_end = _pi_batch_bounds(safe_payload)
    month_label = f"{month_start.isoformat()} to {month_end.isoformat()}"
    account_code = _pi_clearing_account_code_for_user(user, safe_payload)
    gate_connection_row = get_master_xero_connection_for_user(user["id"])
    gate_tenant_id = str(gate_connection_row.get("tenant_id") or "").strip()
    if not gate_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Xero tenant is not connected for PI Clearing.")
    sync_job_id = _pi_record_sync_job_start(
        user_id=str(user.get("id") or ""),
        tenant_id=gate_tenant_id,
        month_start=month_start,
        month_end=month_end,
        metadata={"trigger": "manual_run"},
    )
    with get_connection() as connection:
        with connection.cursor() as cursor:
            _pi_assert_requested_open_month(
                cursor,
                user_id=user["id"],
                tenant_id=gate_tenant_id,
                requested_start=month_start,
                requested_end=month_end,
            )
            cursor.execute(
                """
                UPDATE pi_clearing_deferred_events
                SET status = %s,
                    updated_at = NOW()
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND event_month = %s
                  AND status = %s
                """,
                ("ready", user["id"], gate_tenant_id, month_start, "deferred"),
            )
        connection.commit()
    force_refresh_xero = bool(safe_payload.get("refreshXero"))
    include_ignition = bool(safe_payload.get("includeIgnition"))
    include_ai = bool(safe_payload.get("includeAI")) and include_ignition
    force_refresh_ignition = bool(safe_payload.get("refreshIgnition")) and include_ignition

    # Prefer cached historical data already stored in the database.
    xero_rows, tenant_id, xero_last_refreshed_at = _pi_load_xero_payments(user, month_start, month_end, account_code)
    if force_refresh_xero or not xero_rows:
        xero_refresh = await _pi_refresh_xero_payments_for_month(user, month_start, month_end)
        xero_rows, tenant_id, xero_last_refreshed_at = _pi_load_xero_payments(user, month_start, month_end, account_code)
    else:
        xero_refresh = {
            "tenantId": tenant_id,
            "fetched": 0,
            "processed": 0,
            "stored": 0,
            "cachedRows": len(xero_rows),
            "skippedRefresh": True,
            "source": "cache",
            "message": "Using cached historical Xero payments from local database.",
            "lastRefreshedAt": xero_last_refreshed_at,
        }
    if not force_refresh_xero and xero_rows and not any(_money(row.get("amount")) < Decimal("0.00") for row in xero_rows):
        # Backfill historical caches created before PI clearing ingested ACCPAY rows.
        xero_refresh = await _pi_refresh_xero_payments_for_month(user, month_start, month_end)
        xero_rows, tenant_id, xero_last_refreshed_at = _pi_load_xero_payments(user, month_start, month_end, account_code)
    if not str(xero_refresh.get("lastRefreshedAt") or "").strip():
        xero_refresh["lastRefreshedAt"] = xero_last_refreshed_at or str(xero_refresh.get("refreshedAt") or "")
    xero_step1 = _pi_step1_xero_credit_debit_check(xero_rows)
    if not force_refresh_xero and int(xero_step1.get("missingCreditCount") or 0) > 0:
        has_ledger_supporting_sources = any(
            str(row.get("source") or "").strip().lower() in {"journal_line", "invoice_line", "credit_note_line"}
            for row in xero_rows
        )
        if not has_ledger_supporting_sources:
            xero_refresh = await _pi_refresh_xero_payments_for_month(user, month_start, month_end)
            xero_rows, tenant_id, xero_last_refreshed_at = _pi_load_xero_payments(user, month_start, month_end, account_code)
            if not str(xero_refresh.get("lastRefreshedAt") or "").strip():
                xero_refresh["lastRefreshedAt"] = xero_last_refreshed_at or str(xero_refresh.get("refreshedAt") or "")
            xero_refresh["autoRefreshReason"] = (
                "Step 1 showed missing debit coverage with cached payment-only data; "
                "refreshed Xero and rebuilt PI ledger rows from invoices/credit notes/journals."
            )
            xero_step1 = _pi_step1_xero_credit_debit_check(xero_rows)
    missing_credit_payment_ids = {
        str(item).strip()
        for item in (xero_step1.get("missingCreditPaymentIds") or [])
        if str(item).strip()
    }

    if include_ignition:
        ignition_rows = _pi_load_ignition_payments(user, month_start, month_end)
        if force_refresh_ignition or not ignition_rows:
            ignition_refresh = await _pi_refresh_ignition_payment_datasets(user)
            ignition_rows = _pi_load_ignition_payments(user, month_start, month_end)
        else:
            ignition_refresh = {
                "connected": True,
                "fetched": 0,
                "changed": 0,
                "cachedRows": len(ignition_rows),
                "skippedRefresh": True,
                "source": "cache",
                "message": "Using cached Ignition payments from local database.",
                "datasets": {},
            }
    else:
        ignition_rows = []
        ignition_refresh = {
            "connected": True,
            "fetched": 0,
            "changed": 0,
            "cachedRows": 0,
            "skippedRefresh": True,
            "deferred": True,
            "source": "deferred",
            "message": "Ignition loading deferred until Step 2.",
            "datasets": {},
        }

    existing_credit_note_totals = _pi_existing_credit_note_totals(user, month_start, month_end, account_code)

    grouped: dict[str, dict] = {}
    for row in xero_rows:
        key = str(row.get("clientKey") or "").strip() or f"xero:{row.get('paymentId')}"
        group = grouped.setdefault(
            key,
            {
                "clientName": row.get("clientName") or "Unknown client",
                "xeroContactId": row.get("xeroContactId") or "",
                "currencyCode": row.get("currencyCode") or "GBP",
                "xeroTotal": Decimal("0.00"),
                "xeroNetTotal": Decimal("0.00"),
                "ignitionTotal": Decimal("0.00"),
                "ignitionGrossTotal": Decimal("0.00"),
                "ignitionReversalTotal": Decimal("0.00"),
                "xeroPaymentIds": [],
                "ignitionPaymentIds": [],
                "xeroRows": [],
                "ignitionRows": [],
            },
        )
        signed_amount = _money(row.get("amount"))
        # Reconciliation is against payout credits (money out), not net movement.
        # Keep xeroTotal as payout-credit total so row/summary Difference is like-for-like with Ignition net payouts.
        group["xeroNetTotal"] += signed_amount
        if signed_amount < Decimal("0.00"):
            group["xeroTotal"] += signed_amount.copy_abs()
        group["xeroPaymentIds"].append(str(row.get("paymentId") or ""))
        group["xeroRows"].append(row)
        if not group.get("xeroContactId") and row.get("xeroContactId"):
            group["xeroContactId"] = str(row.get("xeroContactId") or "")
    for row in ignition_rows:
        key = str(row.get("clientKey") or "").strip() or f"ignition:{row.get('paymentId')}"
        group = grouped.setdefault(
            key,
            {
                "clientName": row.get("clientName") or "Unknown client",
                "xeroContactId": "",
                "currencyCode": row.get("currencyCode") or "GBP",
                "xeroTotal": Decimal("0.00"),
                "xeroNetTotal": Decimal("0.00"),
                "ignitionTotal": Decimal("0.00"),
                "ignitionGrossTotal": Decimal("0.00"),
                "ignitionReversalTotal": Decimal("0.00"),
                "xeroPaymentIds": [],
                "ignitionPaymentIds": [],
                "xeroRows": [],
                "ignitionRows": [],
            },
        )
        signed_amount = _money(row.get("amount"))
        group["ignitionTotal"] += signed_amount
        if bool(row.get("isReversal")) or signed_amount < 0:
            group["ignitionReversalTotal"] += signed_amount.copy_abs()
        else:
            group["ignitionGrossTotal"] += signed_amount
        group["ignitionPaymentIds"].append(str(row.get("paymentId") or ""))
        group["ignitionRows"].append(row)

    rows_to_store: list[dict] = []
    for key, group in grouped.items():
        existing_credit_note_total = Decimal("0.00")
        contact_id = str(group.get("xeroContactId") or "").strip()
        if contact_id:
            existing_credit_note_total = _money(existing_credit_note_totals.get(contact_id))
        raw_difference = (group["xeroTotal"] - group["ignitionTotal"]).quantize(Decimal("0.01"))
        difference = (raw_difference - existing_credit_note_total).quantize(Decimal("0.01"))
        payout_date = _pi_group_effective_date(group.get("ignitionRows") or [], group.get("xeroRows") or [], month_end)
        step1_missing_debit_total = sum(
            (
                _money(item.get("amount")).copy_abs()
                for item in (group.get("xeroRows") or [])
                if _money(item.get("amount")) < Decimal("0.00")
                and str(item.get("paymentId") or "").strip() in missing_credit_payment_ids
            ),
            start=Decimal("0.00"),
        )
        risk_level, risk_score, explainer = _pi_row_risk_and_explainer(
            difference=difference,
            raw_difference=raw_difference,
            existing_credit_note_total=existing_credit_note_total,
            ignition_reversal_total=_money(group.get("ignitionReversalTotal")),
            has_contact=bool(contact_id),
        )
        recommendation = "No action required."
        resolution_status = "pending"
        if existing_credit_note_total > 0 and difference <= 0:
            recommendation = "Difference appears already covered by prior PI Clearing credit note(s)."
            resolution_status = "balanced_by_existing_credit_note"
        if difference > 0:
            if _money(group.get("ignitionReversalTotal")) > 0:
                recommendation = "Ignition reversal/refund detected. Create PI Clearing invoice in Xero for the residual variance."
            else:
                recommendation = "Create PI Clearing credit note in Xero for the variance."
            resolution_status = "pending"
        elif difference < 0:
            recommendation = "Investigate Ignition payout with no matching Xero payment."
            resolution_status = "investigate"
        if step1_missing_debit_total > Decimal("0.00"):
            recommendation = "Step 1 detected Xero payout credit(s) with missing same-date debit entries. Investigate Xero posting sequence before credit note creation."
            resolution_status = "step1_xero_check_required"
        rows_to_store.append(
            {
                "matchKey": key,
                "clientName": str(group.get("clientName") or "Unknown client"),
                "xeroContactId": str(group.get("xeroContactId") or ""),
                "currencyCode": str(group.get("currencyCode") or "GBP"),
                "xeroTotal": group["xeroTotal"],
                "xeroNetTotal": group["xeroNetTotal"],
                "ignitionTotal": group["ignitionTotal"],
                "ignitionGrossTotal": group["ignitionGrossTotal"],
                "ignitionReversalTotal": group["ignitionReversalTotal"],
                "rawDifference": raw_difference,
                "existingCreditNoteTotal": existing_credit_note_total,
                "difference": difference,
                "recommendation": recommendation,
                "resolutionStatus": resolution_status,
                "riskLevel": risk_level,
                "riskScore": risk_score,
                "explainer": explainer,
                "payoutDate": payout_date,
                "step1MissingDebitTotal": step1_missing_debit_total,
                "xeroPaymentIds": [item for item in group.get("xeroPaymentIds") or [] if item],
                "ignitionPaymentIds": [item for item in group.get("ignitionPaymentIds") or [] if item],
                "raw": {
                    "xeroRows": group.get("xeroRows") or [],
                    "ignitionRows": group.get("ignitionRows") or [],
                    "xeroNetTotal": float(_money(group.get("xeroNetTotal"))),
                    "ignitionGrossTotal": float(_money(group.get("ignitionGrossTotal"))),
                    "ignitionReversalTotal": float(_money(group.get("ignitionReversalTotal"))),
                    "rawDifference": float(_money(raw_difference)),
                    "existingCreditNoteTotal": float(_money(existing_credit_note_total)),
                    "riskLevel": risk_level,
                    "riskScore": risk_score,
                    "explainer": explainer,
                    "payoutDate": payout_date.isoformat(),
                    "step1MissingDebitTotal": float(_money(step1_missing_debit_total)),
                },
            }
        )
    rows_to_store.sort(key=lambda row: abs(float(row.get("difference") or 0)), reverse=True)

    payout_matching = _pi_match_ignition_payouts_to_xero_credits(ignition_rows, xero_rows)
    daily_balance = _pi_daily_balance_analysis(xero_rows)
    step2_ledger_rows = _pi_step2_ledger_rows(xero_rows)
    step2_reconciliation = (
        await _pi_ai_step2_reconciliation(
            month_label,
            step2_ledger_rows,
            user_id=str(user.get("id") or ""),
        )
        if include_ignition and include_ai
        else _pi_local_step2_reconciliation(step2_ledger_rows)
    )

    if include_ai:
        ai_analysis = await _pi_ai_analysis(
            month_label,
            [
                {
                    "clientName": row.get("clientName"),
                    "xeroTotal": float(row.get("xeroTotal") or 0),
                    "xeroNetTotal": float(row.get("xeroNetTotal") or 0),
                    "ignitionTotal": float(row.get("ignitionTotal") or 0),
                    "ignitionGrossTotal": float(row.get("ignitionGrossTotal") or 0),
                    "ignitionReversalTotal": float(row.get("ignitionReversalTotal") or 0),
                    "existingCreditNoteTotal": float(row.get("existingCreditNoteTotal") or 0),
                    "rawDifference": float(row.get("rawDifference") or 0),
                    "difference": float(row.get("difference") or 0),
                    "riskLevel": str(row.get("riskLevel") or "low"),
                    "riskScore": int(row.get("riskScore") or 0),
                    "explainer": str(row.get("explainer") or ""),
                    "hasContact": bool(row.get("xeroContactId")),
                }
                for row in rows_to_store
            ],
            {
                "payoutMatching": payout_matching,
                "dailyBalance": daily_balance,
                "xeroStep1": xero_step1,
            },
            step2_reconciliation=step2_reconciliation,
            user_id=str(user.get("id") or ""),
        )
    else:
        ai_analysis = {
            "summary": "AI analysis deferred. Review Step 1 transactions first, then continue to Step 2.",
            "findings": [],
            "actions": [],
            "confidence": 0.0,
            "engine": "local_deferred",
            "step2Reconciliation": step2_reconciliation,
        }
    xero_debit_total = sum((_money(row.get("amount")) for row in xero_rows if _money(row.get("amount")) > 0), start=Decimal("0.00"))
    xero_credit_total = sum((_money(row.get("amount")).copy_abs() for row in xero_rows if _money(row.get("amount")) < 0), start=Decimal("0.00"))
    finalisation = _pi_finalisation_state(
        xero_debit_total=xero_debit_total,
        xero_credit_total=xero_credit_total,
        xero_step1=xero_step1,
    )
    day_evidence = _pi_daily_evidence_rows(
        month_start=month_start,
        month_end=month_end,
        xero_rows=xero_rows,
        ignition_rows=ignition_rows,
    )
    day_complete_count = sum(
        1
        for item in day_evidence
        if str(item.get("status") or "").strip().lower() in {"balanced", "no_activity_confirmed"}
    )
    fee_treatment = str(
        posting_settings_for_tenant(tenant_id).get("piClearingFeeTreatment") or PI_CLEARING_FEE_TREATMENT_EXCLUDE
    ).strip().lower() or PI_CLEARING_FEE_TREATMENT_EXCLUDE
    summary = {
        "refresh": {
            "xero": xero_refresh,
            "ignition": ignition_refresh,
        },
        "ruleVersion": PI_CLEARING_RULE_VERSION,
        "postingMode": PI_CLEARING_POSTING_MODE_REVIEW,
        "feePolicy": {
            "treatment": fee_treatment,
            "appliedToPiEquation": fee_treatment == PI_CLEARING_FEE_TREATMENT_INCLUDE,
            "note": (
                "Ignition fees are included in the PI Clearing control equation."
                if fee_treatment == PI_CLEARING_FEE_TREATMENT_INCLUDE
                else "Ignition fees are intentionally excluded from the PI Clearing control equation until finance approves treatment."
            ),
        },
        "workflowMode": "full" if include_ignition else "transactions_only",
        "xeroCount": len(xero_rows),
        "ignitionCount": len(ignition_rows),
        "differenceCount": sum(1 for row in rows_to_store if _money(row.get("difference")) != 0),
        "creditNoteCandidateCount": sum(1 for row in rows_to_store if _money(row.get("difference")) > 0 and str(row.get("xeroContactId") or "").strip()),
        "xeroTotal": float(xero_credit_total),
        "xeroNetTotal": float(sum((_money(row.get("amount")) for row in xero_rows), start=Decimal("0.00"))),
        "xeroDebitTotal": float(xero_debit_total),
        "xeroCreditTotal": float(xero_credit_total),
        "ignitionTotal": float(sum((_money(row.get("amount")) for row in ignition_rows), start=Decimal("0.00"))),
        "ignitionGrossTotal": float(sum((_money(row.get("amount")) for row in ignition_rows if _money(row.get("amount")) > 0), start=Decimal("0.00"))),
        "ignitionReversalTotal": float(sum((_money(row.get("amount")).copy_abs() for row in ignition_rows if _money(row.get("amount")) < 0), start=Decimal("0.00"))),
        "existingCreditNoteTotal": float(sum((_money(row.get("existingCreditNoteTotal")) for row in rows_to_store), start=Decimal("0.00"))),
        "differenceTotal": float(sum((_money(row.get("difference")) for row in rows_to_store), start=Decimal("0.00"))),
        "payoutMatching": payout_matching,
        "dailyBalance": daily_balance,
        "xeroStep1": xero_step1,
        "step2Reconciliation": step2_reconciliation,
        "dayEvidence": day_evidence,
        "expectedDayCount": len(day_evidence),
        "completedDayCount": day_complete_count,
        "finalisation": finalisation,
    }
    has_any_xero_rows = len(xero_rows) > 0
    status_value = "completed" if finalisation.get("canFinalise") else ("ready" if has_any_xero_rows else "empty")
    now = utcnow()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO pi_clearing_runs (
                    user_id, tenant_id, batch_number, month_start, month_end, account_code, status, summary, ai_analysis, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb, %s, %s)
                ON CONFLICT (user_id, tenant_id, month_start)
                DO UPDATE
                SET month_end = EXCLUDED.month_end,
                    batch_number = CASE
                        WHEN COALESCE(pi_clearing_runs.batch_number, '') = '' THEN EXCLUDED.batch_number
                        ELSE pi_clearing_runs.batch_number
                    END,
                    account_code = EXCLUDED.account_code,
                    status = EXCLUDED.status,
                    summary = EXCLUDED.summary,
                    ai_analysis = EXCLUDED.ai_analysis,
                    updated_at = EXCLUDED.updated_at
                RETURNING *
                """,
                (
                    user["id"],
                    tenant_id,
                    _pi_next_batch_number(cursor, user["id"], tenant_id),
                    month_start,
                    month_end,
                    account_code,
                    status_value,
                    json.dumps(summary, default=_json_default),
                    json.dumps(ai_analysis, default=_json_default),
                    now,
                    now,
                ),
            )
            run_row = cursor.fetchone() or {}
            run_id = str(run_row.get("id") or "")
            _pi_update_month_state_from_run_summary(
                cursor,
                user_id=user["id"],
                tenant_id=tenant_id or gate_tenant_id,
                month_start=month_start,
                month_end=month_end,
                summary=summary,
            )
            cursor.execute("DELETE FROM pi_clearing_run_rows WHERE run_id = %s", (run_id,))
            for row in rows_to_store:
                cursor.execute(
                    """
                    INSERT INTO pi_clearing_run_rows (
                        run_id, user_id, month_start, month_end, row_type, match_key, client_name, xero_contact_id,
                        xero_payment_ids, ignition_payment_ids, currency_code, xero_total, ignition_total, difference_total,
                        recommendation, resolution_status, raw_payload, created_at, updated_at
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                    """,
                    (
                        run_id,
                        user["id"],
                        month_start,
                        month_end,
                        "difference",
                        row.get("matchKey"),
                        row.get("clientName"),
                        row.get("xeroContactId"),
                        json.dumps(row.get("xeroPaymentIds") or [], default=_json_default),
                        json.dumps(row.get("ignitionPaymentIds") or [], default=_json_default),
                        row.get("currencyCode") or "GBP",
                        row.get("xeroTotal"),
                        row.get("ignitionTotal"),
                        row.get("difference"),
                        row.get("recommendation") or "",
                        row.get("resolutionStatus") or "pending",
                        json.dumps(row.get("raw") or {}, default=_json_default),
                        now,
                        now,
                    ),
                )
        connection.commit()
    payload = pi_clearing_payload(user)
    current_run = next((item for item in payload.get("runs") or [] if str(item.get("id") or "") == run_id), None)
    _pi_record_sync_job_finish(
        job_id=sync_job_id,
        status_value="completed",
        metadata={
            "runId": run_id,
            "rowCount": len(rows_to_store),
            "differenceCount": int(summary.get("differenceCount") or 0),
            "workflowMode": "full" if include_ignition else "transactions_only",
        },
    )
    return {"run": current_run or {}}


async def close_pi_clearing_month(user: dict, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    connection_row = get_master_xero_connection_for_user(user["id"])
    tenant_id = str(connection_row.get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Xero tenant is not connected for PI Clearing.")

    requested_month = str(safe_payload.get("month") or "").strip()
    requested_start_raw = str(safe_payload.get("monthStart") or "").strip()
    requested_start = None
    if requested_month:
        try:
            requested_start = _pi_month_start(date.fromisoformat(f"{requested_month}-01"))
        except Exception as exc:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Month must use YYYY-MM format.") from exc
    elif requested_start_raw:
        requested_start = _parse_any_date(requested_start_raw)
        if requested_start:
            requested_start = _pi_month_start(requested_start)
    now = utcnow()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            gate = _pi_apply_period_gate(cursor, user["id"], tenant_id)
            open_month_start = gate.get("openMonthStart")
            open_month_end = gate.get("openMonthEnd")
            if not isinstance(open_month_start, date) or not isinstance(open_month_end, date):
                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="PI Clearing period gate is unavailable.")
            if requested_start is None:
                requested_start = open_month_start
            requested_end = _pi_month_end(requested_start)
            _pi_assert_requested_open_month(
                cursor,
                user_id=user["id"],
                tenant_id=tenant_id,
                requested_start=requested_start,
                requested_end=requested_end,
            )
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_runs
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                ORDER BY updated_at DESC
                LIMIT 1
                """,
                (user["id"], tenant_id, requested_start),
            )
            run_row = cursor.fetchone() or {}
            if not run_row:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"No PI Clearing run exists for {requested_start.strftime('%Y-%m')}. Run the workflow first.",
                )
            summary = run_row.get("summary") if isinstance(run_row.get("summary"), dict) else {}
            close_checks = _pi_close_predicate_checks(
                cursor,
                user=user,
                tenant_id=tenant_id,
                run_row=run_row,
                summary=summary,
            )
            if not close_checks.get("canClose"):
                failures = close_checks.get("failures") if isinstance(close_checks.get("failures"), list) else []
                failed_codes = ", ".join(str(item.get("code") or "UNKNOWN") for item in failures)
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail={
                        "message": "This month is not ready to close.",
                        "failedChecks": failures,
                        "failedCodes": failed_codes,
                    },
                )
            snapshot_hash = _pi_payload_hash(
                {
                    "summary": summary,
                    "checks": close_checks.get("checks") or [],
                    "runId": str(run_row.get("id") or ""),
                    "monthStart": requested_start.isoformat(),
                    "monthEnd": requested_end.isoformat(),
                }
            )
            cursor.execute(
                """
                SELECT COALESCE(MAX(close_sequence), 0) AS max_sequence
                FROM pi_clearing_month_closes
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                """,
                (user["id"], tenant_id, requested_start),
            )
            close_sequence = int((cursor.fetchone() or {}).get("max_sequence") or 0) + 1
            cursor.execute(
                """
                INSERT INTO pi_clearing_month_closes (
                    user_id, tenant_id, month_start, month_end, close_run_id, close_sequence,
                    approved_by_user_id, approved_at, closed_at, snapshot_hash, summary, check_results, created_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb, %s)
                """,
                (
                    user["id"],
                    tenant_id,
                    requested_start,
                    requested_end,
                    run_row.get("id"),
                    close_sequence,
                    user["id"],
                    now,
                    now,
                    snapshot_hash,
                    json.dumps(summary, default=_json_default),
                    json.dumps(close_checks, default=_json_default),
                    now,
                ),
            )
            record_audit_event(
                "pi_clearing_month",
                f"{tenant_id}:{_pi_month_key(requested_start)}",
                "MONTH_CLOSED",
                {"tenantId": tenant_id, "month": _pi_month_key(requested_start), "runId": str(run_row.get("id") or "")},
                user["id"],
            )
            cursor.execute(
                """
                UPDATE pi_clearing_month_states
                SET status = %s,
                    close_run_id = %s,
                    closed_at = %s,
                    updated_at = %s
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                """,
                (
                    PI_CLEARING_MONTH_STATUS_CLOSED,
                    run_row.get("id"),
                    now,
                    now,
                    user["id"],
                    tenant_id,
                    requested_start,
                ),
            )
            next_month_start = _pi_add_months(requested_start, 1)
            cursor.execute(
                """
                INSERT INTO pi_clearing_month_states (
                    user_id, tenant_id, month_start, month_end, status, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (user_id, tenant_id, month_start) DO UPDATE
                SET status = CASE
                    WHEN pi_clearing_month_states.status = %s THEN %s
                    ELSE pi_clearing_month_states.status
                END,
                    updated_at = EXCLUDED.updated_at
                """,
                (
                    user["id"],
                    tenant_id,
                    next_month_start,
                    _pi_month_end(next_month_start),
                    PI_CLEARING_MONTH_STATUS_OPEN,
                    now,
                    now,
                    PI_CLEARING_MONTH_STATUS_LOCKED,
                    PI_CLEARING_MONTH_STATUS_OPEN,
                ),
            )
            record_audit_event(
                "pi_clearing_month",
                f"{tenant_id}:{_pi_month_key(next_month_start)}",
                "NEXT_MONTH_UNLOCKED",
                {"tenantId": tenant_id, "month": _pi_month_key(next_month_start)},
                user["id"],
            )
            cursor.execute(
                """
                UPDATE pi_clearing_runs
                SET status = %s,
                    updated_at = %s
                WHERE id = %s
                  AND user_id = %s
                """,
                ("closed", now, run_row.get("id"), user["id"]),
            )
            gate_after_close = _pi_apply_period_gate(cursor, user["id"], tenant_id)
        connection.commit()

    updated = pi_clearing_payload(user)
    return {
        "closed": True,
        "closedMonth": _pi_month_key(requested_start),
        "nextOpenMonth": str(gate_after_close.get("openMonth") or ""),
        "closeChecks": close_checks.get("checks") if isinstance(close_checks.get("checks"), list) else [],
        "periodGate": updated.get("periodGate") if isinstance(updated.get("periodGate"), dict) else {},
        "runs": updated.get("runs") or [],
    }


async def reopen_pi_clearing_month(user: dict, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    connection_row = get_master_xero_connection_for_user(user["id"])
    tenant_id = str(connection_row.get("tenant_id") or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Xero tenant is not connected for PI Clearing.")
    requested_month = str(safe_payload.get("month") or "").strip()
    reopen_reason = str(safe_payload.get("reason") or "manual_reopen").strip() or "manual_reopen"
    if not requested_month:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Month must use YYYY-MM format.")
    try:
        requested_start = _pi_month_start(date.fromisoformat(f"{requested_month}-01"))
    except Exception as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Month must use YYYY-MM format.") from exc
    now = utcnow()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_month_states
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                LIMIT 1
                """,
                (user["id"], tenant_id, requested_start),
            )
            month_row = cursor.fetchone() or {}
            if not month_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"Month {requested_month} is not initialised.")
            status_value = str(month_row.get("status") or "").strip().lower()
            if status_value not in {PI_CLEARING_MONTH_STATUS_CLOSED, PI_CLEARING_MONTH_STATUS_REOPENED}:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"Month {requested_month} cannot be reopened from status '{status_value or 'unknown'}'.",
                )
            cursor.execute(
                """
                UPDATE pi_clearing_month_states
                SET status = %s,
                    reopened_at = %s,
                    reopen_reason = %s,
                    updated_at = %s
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                """,
                (
                    PI_CLEARING_MONTH_STATUS_REOPENED,
                    now,
                    reopen_reason,
                    now,
                    user["id"],
                    tenant_id,
                    requested_start,
                ),
            )
            cursor.execute(
                """
                UPDATE pi_clearing_month_closes
                SET invalidated_at = %s,
                    invalidated_reason = %s
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start = %s
                  AND invalidated_at IS NULL
                """,
                (now, reopen_reason, user["id"], tenant_id, requested_start),
            )
            cursor.execute(
                """
                UPDATE pi_clearing_month_states
                SET status = %s,
                    updated_at = %s
                WHERE user_id = %s
                  AND tenant_id = %s
                  AND month_start > %s
                  AND status <> %s
                """,
                (
                    PI_CLEARING_MONTH_STATUS_LOCKED,
                    now,
                    user["id"],
                    tenant_id,
                    requested_start,
                    PI_CLEARING_MONTH_STATUS_CLOSED,
                ),
            )
            record_audit_event(
                "pi_clearing_month",
                f"{tenant_id}:{requested_month}",
                "MONTH_REOPENED",
                {"tenantId": tenant_id, "month": requested_month, "reason": reopen_reason},
                user["id"],
            )
            record_audit_event(
                "pi_clearing_month",
                f"{tenant_id}:{requested_month}",
                "NEXT_MONTH_RELOCKED",
                {"tenantId": tenant_id, "fromMonth": requested_month},
                user["id"],
            )
            gate = _pi_apply_period_gate(cursor, user["id"], tenant_id)
        connection.commit()
    updated = pi_clearing_payload(user)
    return {
        "reopened": True,
        "month": requested_month,
        "reason": reopen_reason,
        "nextOpenMonth": str(gate.get("openMonth") or ""),
        "periodGate": updated.get("periodGate") if isinstance(updated.get("periodGate"), dict) else {},
        "runs": updated.get("runs") or [],
    }


def pi_clearing_dry_run_pdf(
    user: dict,
    run_id: str,
    row_ids: list[str] | None = None,
) -> tuple[bytes, str]:
    selected = [str(item).strip() for item in (row_ids or []) if str(item).strip()]
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_runs
                WHERE id = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (run_id, user["id"]),
            )
            run_row = cursor.fetchone() or {}
            if not run_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing run not found.")
            tenant_id = str(run_row.get("tenant_id") or "").strip()
            month_start = run_row.get("month_start")
            month_end = run_row.get("month_end")
            if tenant_id and isinstance(month_start, date) and isinstance(month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=tenant_id,
                    requested_start=_pi_month_start(month_start),
                    requested_end=month_end,
                )
            query = """
                SELECT *
                FROM pi_clearing_run_rows
                WHERE run_id = %s
                  AND user_id = %s
                  AND ABS(difference_total) > 0.005
                  AND COALESCE(resolution_status, 'pending') NOT IN ('credit_note_created', 'balanced_by_existing_credit_note', 'step1_xero_check_required')
            """
            params: list = [run_id, user["id"]]
            if selected:
                query += " AND id = ANY(%s)"
                params.append(selected)
            query += " ORDER BY ABS(difference_total) DESC, client_name ASC"
            cursor.execute(query, tuple(params))
            rows = cursor.fetchall() or []
        connection.commit()
    if not rows:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="No eligible rows available for PI dry-run report.")

    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except Exception as exc:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="ReportLab is required to export PI Clearing dry-run PDFs.",
        ) from exc

    period_start = run_row.get("month_start")
    period_end = run_row.get("month_end")
    title_month = period_start.strftime("%B %Y") if isinstance(period_start, date) else "Selected month"
    account_code = str(run_row.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE)

    buffer = io.BytesIO()
    styles = getSampleStyleSheet()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        leftMargin=24,
        rightMargin=24,
        topMargin=28,
        bottomMargin=24,
    )
    story: list = []
    story.append(Paragraph("PI Clearing Dry-Run Credit Note Preview", styles["Title"]))
    story.append(Paragraph(f"Month: {title_month}", styles["Normal"]))
    story.append(Paragraph(f"Account code: {account_code}", styles["Normal"]))
    if isinstance(period_start, date) and isinstance(period_end, date):
        story.append(Paragraph(f"Period: {period_start.isoformat()} to {period_end.isoformat()}", styles["Normal"]))
    story.append(Spacer(1, 10))

    table_rows = [["Client", "Payout date", "Difference", "Risk", "Why mismatch"]]
    total_amount = Decimal("0.00")
    for row in rows:
        diff = _money(row.get("difference_total"))
        if diff <= 0:
            continue
        total_amount += diff
        raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
        risk_label = str(raw_payload.get("riskLevel") or "low").strip().title()
        explainer = str(raw_payload.get("explainer") or row.get("recommendation") or "").strip()
        payout_date = _parse_optional_iso_date(raw_payload.get("payoutDate")) or period_end or period_start or utcnow().date()
        table_rows.append(
            [
                str(row.get("client_name") or "Unknown client"),
                payout_date.isoformat(),
                f"£{diff:.2f}",
                risk_label,
                explainer[:160],
            ]
        )
    table_rows.append(["Total", "", f"£{_money(total_amount):.2f}", "", ""])

    table = Table(
        table_rows,
        repeatRows=1,
        colWidths=[122, 74, 64, 46, 216],
    )
    table.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#eef3ff")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#1f3f77")),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("FONTNAME", (0, 1), (-1, -1), "Helvetica"),
                ("FONTSIZE", (0, 0), (-1, -1), 9),
                ("GRID", (0, 0), (-1, -1), 0.3, colors.HexColor("#c8d6f0")),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [colors.white, colors.HexColor("#f9fbff")]),
                ("ALIGN", (2, 1), (3, -1), "RIGHT"),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ]
        )
    )
    story.append(table)
    doc.build(story)
    filename = f"pi-clearing-dry-run-{(period_start or utcnow().date()).strftime('%Y-%m')}.pdf"
    return buffer.getvalue(), filename


def pi_clearing_month_close_export(user: dict, close_id: str) -> tuple[bytes, str]:
    close_record_id = str(close_id or "").strip()
    if not close_record_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Month close id is required.")

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_month_closes
                WHERE id = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (close_record_id, user["id"]),
            )
            close_row = cursor.fetchone() or {}
            if not close_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing month close record not found.")
            close_summary = close_row.get("summary") if isinstance(close_row.get("summary"), dict) else {}
            close_checks = close_row.get("check_results") if isinstance(close_row.get("check_results"), dict) else {}
            run_id = str(close_row.get("close_run_id") or "").strip()
            run_rows: list[dict] = []
            credit_notes: list[dict] = []
            action_approvals: list[dict] = []
            run_row: dict = {}
            if run_id:
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_runs
                    WHERE id = %s
                      AND user_id = %s
                    LIMIT 1
                    """,
                    (run_id, user["id"]),
                )
                run_row = cursor.fetchone() or {}
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_run_rows
                    WHERE run_id = %s
                      AND user_id = %s
                    ORDER BY ABS(difference_total) DESC, client_name ASC
                    """,
                    (run_id, user["id"]),
                )
                run_rows = cursor.fetchall() or []
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_credit_notes
                    WHERE run_id = %s
                      AND user_id = %s
                    ORDER BY created_at DESC
                    """,
                    (run_id, user["id"]),
                )
                credit_notes = cursor.fetchall() or []
                cursor.execute(
                    """
                    SELECT *
                    FROM pi_clearing_action_approvals
                    WHERE run_id = %s
                      AND user_id = %s
                    ORDER BY created_at DESC
                    """,
                    (run_id, user["id"]),
                )
                action_approvals = cursor.fetchall() or []
        connection.commit()

    run_rows_payload = [
        {
            "id": str(row.get("id") or ""),
            "clientName": str(row.get("client_name") or ""),
            "xeroContactId": str(row.get("xero_contact_id") or ""),
            "xeroTotal": float(_money(row.get("xero_total"))),
            "ignitionTotal": float(_money(row.get("ignition_total"))),
            "differenceTotal": float(_money(row.get("difference_total"))),
            "recommendation": str(row.get("recommendation") or ""),
            "resolutionStatus": str(row.get("resolution_status") or ""),
            "raw": row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {},
            "createdAt": _iso(row.get("created_at")) or "",
            "updatedAt": _iso(row.get("updated_at")) or "",
        }
        for row in run_rows
    ]
    credit_notes_payload = [
        {
            "id": str(row.get("id") or ""),
            "runRowId": str(row.get("run_row_id") or ""),
            "xeroContactId": str(row.get("xero_contact_id") or ""),
            "xeroDocumentId": str(row.get("xero_credit_note_id") or ""),
            "xeroDocumentNumber": str(row.get("xero_credit_note_number") or ""),
            "documentType": str(((row.get("raw_payload") or {}).get("documentType") if isinstance(row.get("raw_payload"), dict) else "") or "invoice"),
            "amount": float(_money(row.get("amount"))),
            "currencyCode": str(row.get("currency_code") or "GBP"),
            "accountCode": str(row.get("account_code") or ""),
            "businessActionKey": str(row.get("business_action_key") or ""),
            "idempotencyKey": str(row.get("idempotency_key") or ""),
            "payloadHash": str(row.get("payload_hash") or ""),
            "status": str(row.get("status") or ""),
            "createdAt": _iso(row.get("created_at")) or "",
            "updatedAt": _iso(row.get("updated_at")) or "",
        }
        for row in credit_notes
    ]
    action_approvals_payload = [
        {
            "id": str(row.get("id") or ""),
            "runRowId": str(row.get("run_row_id") or ""),
            "businessActionKey": str(row.get("business_action_key") or ""),
            "payloadHash": str(row.get("payload_hash") or ""),
            "sourceSnapshotHash": str(row.get("source_snapshot_hash") or ""),
            "status": str(row.get("status") or ""),
            "notes": str(row.get("notes") or ""),
            "approvedByUserId": str(row.get("approved_by_user_id") or ""),
            "approvedAt": _iso(row.get("approved_at")) or "",
            "postedAt": _iso(row.get("posted_at")) or "",
            "verifiedAt": _iso(row.get("verified_at")) or "",
            "createdAt": _iso(row.get("created_at")) or "",
            "updatedAt": _iso(row.get("updated_at")) or "",
        }
        for row in action_approvals
    ]
    export_payload = {
        "closeRecord": {
            "id": str(close_row.get("id") or ""),
            "tenantId": str(close_row.get("tenant_id") or ""),
            "monthStart": close_row.get("month_start").isoformat() if close_row.get("month_start") else "",
            "monthEnd": close_row.get("month_end").isoformat() if close_row.get("month_end") else "",
            "closeRunId": run_id,
            "closeSequence": int(close_row.get("close_sequence") or 1),
            "approvedByUserId": str(close_row.get("approved_by_user_id") or ""),
            "approvedAt": _iso(close_row.get("approved_at")) or "",
            "closedAt": _iso(close_row.get("closed_at")) or "",
            "invalidatedAt": _iso(close_row.get("invalidated_at")) or "",
            "invalidatedReason": str(close_row.get("invalidated_reason") or ""),
            "snapshotHash": str(close_row.get("snapshot_hash") or ""),
            "checks": close_checks.get("checks") if isinstance(close_checks.get("checks"), list) else [],
            "failures": close_checks.get("failures") if isinstance(close_checks.get("failures"), list) else [],
        },
        "run": {
            "id": str(run_row.get("id") or ""),
            "batchNumber": str(run_row.get("batch_number") or ""),
            "status": str(run_row.get("status") or ""),
            "monthStart": run_row.get("month_start").isoformat() if run_row.get("month_start") else "",
            "monthEnd": run_row.get("month_end").isoformat() if run_row.get("month_end") else "",
            "accountCode": str(run_row.get("account_code") or ""),
            "summary": close_summary,
        },
        "dayEvidence": close_summary.get("dayEvidence") if isinstance(close_summary.get("dayEvidence"), list) else [],
        "runRows": run_rows_payload,
        "creditNotes": credit_notes_payload,
        "actionApprovals": action_approvals_payload,
        "exportedAt": _iso(utcnow()) or "",
        "exportedByUserId": str(user.get("id") or ""),
    }
    filename_month = close_row.get("month_start").strftime("%Y-%m") if close_row.get("month_start") else "month"
    filename = f"pi-clearing-close-export-{filename_month}-{close_record_id[:8]}.json"
    return json.dumps(export_payload, default=_json_default, indent=2).encode("utf-8"), filename


async def approve_pi_clearing_credit_notes(user: dict, run_id: str, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    selected_row_ids = [str(item).strip() for item in (safe_payload.get("rowIds") or []) if str(item).strip()]
    notes = str(safe_payload.get("notes") or "").strip()
    requested_account_code = str(safe_payload.get("accountCode") or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM pi_clearing_runs WHERE id = %s AND user_id = %s",
                (run_id, user["id"]),
            )
            run_row = cursor.fetchone() or {}
            if not run_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing run not found.")
            tenant_id = str(run_row.get("tenant_id") or "").strip()
            month_start = run_row.get("month_start")
            month_end = run_row.get("month_end")
            if tenant_id and isinstance(month_start, date) and isinstance(month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=tenant_id,
                    requested_start=_pi_month_start(month_start),
                    requested_end=month_end,
                )
            run_summary = run_row.get("summary") if isinstance(run_row.get("summary"), dict) else {}
            finalisation = _pi_finalisation_state_from_summary(run_summary)
            run_status_after_approval = "completed" if finalisation.get("canFinalise") else "ready_for_posting"
            account_code = requested_account_code or str(run_row.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE)
            query = """
                SELECT *
                FROM pi_clearing_run_rows
                WHERE run_id = %s
                  AND user_id = %s
                  AND ABS(difference_total) > 0.005
                  AND COALESCE(resolution_status, 'pending') NOT IN ('credit_note_created', 'balanced_by_existing_credit_note')
            """
            params: list = [run_id, user["id"]]
            if selected_row_ids:
                query += " AND id = ANY(%s)"
                params.append(selected_row_ids)
            query += " ORDER BY ABS(difference_total) DESC, client_name ASC"
            cursor.execute(query, tuple(params))
            target_rows = cursor.fetchall() or []
        connection.commit()
    if not target_rows:
        return {"approved": [], "skipped": [], "message": "No eligible rows were selected for approval."}

    connection_row = get_master_xero_connection_for_user(user["id"])
    account_code = await _pi_resolve_selected_pi_account(connection_row, account_code)
    approved: list[dict] = []
    skipped: list[dict] = []
    for row in target_rows:
        row_id = str(row.get("id") or "")
        contact_id = str(row.get("xero_contact_id") or "").strip()
        amount = _money(row.get("difference_total")).copy_abs()
        raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
        step1_fix = raw_payload.get("step1AiFix") if isinstance(raw_payload.get("step1AiFix"), dict) else {}
        has_refund = _money(raw_payload.get("ignitionReversalTotal")) > Decimal("0.00")
        document_type = "invoice" if has_refund else "credit_note"
        policy_allowed, policy_code, policy_reason, policy_meta = _pi_posting_policy_for_row(
            row,
            step1_fix,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
        )
        if not policy_allowed:
            skipped.append({"runRowId": row_id, "reason": policy_reason, "policyCode": policy_code})
            continue
        if not contact_id:
            skipped.append({"runRowId": row_id, "reason": "No Xero contact is mapped for this row.", "policyCode": "MISSING_CONTACT"})
            continue
        note_date = _parse_optional_iso_date(step1_fix.get("targetDate")) if step1_fix else None
        if note_date is None:
            note_date = _parse_optional_iso_date(raw_payload.get("payoutDate"))
        note_date = note_date or run_row.get("month_end") or run_row.get("month_start") or utcnow().date()
        collection_ids = [
            str(item).strip()
            for item in (
                step1_fix.get("ignitionPaymentIds")
                if isinstance(step1_fix.get("ignitionPaymentIds"), list)
                else row.get("ignition_payment_ids")
            ) or []
            if str(item).strip()
        ]
        if not collection_ids:
            collection_ids = [str(item).strip() for item in (raw_payload.get("ignitionPaymentIds") or []) if str(item).strip()]
        business_action_key = _pi_build_business_action_key(
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            run_id=run_id,
            run_row_id=row_id,
            action_type=PI_CLEARING_ALLOWED_POST_ACTION,
            payout_id=str(step1_fix.get("payoutId") or raw_payload.get("payoutId") or ""),
            collection_ids=collection_ids,
            xero_contact_id=contact_id,
            amount=amount,
            note_date=note_date,
        )
        adjustment_payload = {
            "Type": "ACCREC" if has_refund else "ACCRECCREDIT",
            "Contact": {"ContactID": contact_id},
            "Date": note_date.isoformat(),
            "LineAmountTypes": "NoTax",
            "Status": "AUTHORISED",
            "Reference": "PI Refund Adjustment" if has_refund else "Client Payment",
            "LineItems": [
                {
                    "Description": "PI Refund Adjustment through Jenius AI" if has_refund else "PI Adjustment through Jenius AI",
                    "Quantity": 1,
                    "UnitAmount": float(amount),
                    "AccountCode": account_code,
                    "TaxType": "NONE",
                }
            ],
            "CurrencyCode": str(row.get("currency_code") or "GBP"),
        }
        payload_hash = _pi_payload_hash(adjustment_payload)
        source_snapshot_hash = _pi_action_source_snapshot_hash(
            run_row_id=row_id,
            row=row,
            step1_fix=step1_fix,
            amount=amount,
            contact_id=contact_id,
            note_date=note_date,
            account_code=account_code,
            document_type=document_type,
        )
        _pi_record_action_approval(
            run_id=run_id,
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=payload_hash,
            source_snapshot_hash=source_snapshot_hash,
            status_value=PI_CLEARING_ACTION_STATUS_APPROVED,
            approved_by_user_id=str(user.get("id") or ""),
            notes=notes,
        )
        record_audit_event(
            "pi_clearing_action",
            business_action_key,
            "ACTION_APPROVED",
            {"runId": run_id, "runRowId": row_id, "policyCode": policy_code, "reasonCode": str(policy_meta.get("reasonCode") or "")},
            user["id"],
        )
        approved.append(
            {
                "runRowId": row_id,
                "businessActionKey": business_action_key,
                "payloadHash": payload_hash,
                "sourceSnapshotHash": source_snapshot_hash,
                "policyCode": policy_code,
                "reasonCode": str(policy_meta.get("reasonCode") or ""),
            }
        )

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE pi_clearing_runs
                SET status = %s,
                    updated_at = NOW()
                WHERE id = %s
                  AND user_id = %s
                """,
                (run_status_after_approval, run_id, user["id"]),
            )
        connection.commit()
    updated = pi_clearing_payload(user)
    return {"approved": approved, "skipped": skipped, "runs": updated.get("runs") or []}


async def apply_pi_clearing_credit_notes(user: dict, run_id: str, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    if not bool(safe_payload.get("confirmed")):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Confirm credit note creation before posting to Xero.")
    selected_row_ids = [str(item).strip() for item in (safe_payload.get("rowIds") or []) if str(item).strip()]
    requested_account_code = str(safe_payload.get("accountCode") or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM pi_clearing_runs WHERE id = %s AND user_id = %s",
                (run_id, user["id"]),
            )
            run_row = cursor.fetchone() or {}
            if not run_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing run not found.")
            tenant_id = str(run_row.get("tenant_id") or "").strip()
            month_start = run_row.get("month_start")
            month_end = run_row.get("month_end")
            if tenant_id and isinstance(month_start, date) and isinstance(month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=tenant_id,
                    requested_start=_pi_month_start(month_start),
                    requested_end=month_end,
                )
            run_summary = run_row.get("summary") if isinstance(run_row.get("summary"), dict) else {}
            finalisation = _pi_finalisation_state_from_summary(run_summary)
            run_status_after_credit_note = "completed" if finalisation.get("canFinalise") else "credit_notes_created"
            account_code = requested_account_code or str(run_row.get("account_code") or PI_CLEARING_DEFAULT_ACCOUNT_CODE)
            query = """
                SELECT *
                FROM pi_clearing_run_rows
                WHERE run_id = %s
                  AND user_id = %s
                  AND (
                        ABS(difference_total) > 0.005
                        OR (
                            id = ANY(%s)
                            AND COALESCE(NULLIF(raw_payload->'step1AiFix'->>'missingDebitAmount', '')::numeric, 0) > 0
                        )
                      )
                  AND COALESCE(resolution_status, 'pending') NOT IN ('credit_note_created', 'balanced_by_existing_credit_note')
            """
            params: list = [run_id, user["id"], selected_row_ids or []]
            if selected_row_ids:
                query += " AND id = ANY(%s)"
                params.append(selected_row_ids)
            query += " ORDER BY ABS(difference_total) DESC, client_name ASC"
            cursor.execute(query, tuple(params))
            target_rows = cursor.fetchall() or []
        connection.commit()
    if not target_rows:
        return {"created": [], "skipped": [], "message": "No eligible non-zero difference rows were selected."}
    _pi_assert_writes_enabled_for_tenant(str(run_row.get("tenant_id") or ""))

    connection_row = get_master_xero_connection_for_user(user["id"])
    account_code = await _pi_resolve_selected_pi_account(connection_row, account_code)
    created: list[dict] = []
    skipped: list[dict] = []
    for row in target_rows:
        row_id = str(row.get("id") or "")
        contact_id = str(row.get("xero_contact_id") or "").strip()
        amount = _money(row.get("difference_total")).copy_abs()
        currency_code = str(row.get("currency_code") or "GBP").strip() or "GBP"
        client_name = str(row.get("client_name") or "Unknown client")
        raw_payload = row.get("raw_payload") if isinstance(row.get("raw_payload"), dict) else {}
        step1_fix = raw_payload.get("step1AiFix") if isinstance(raw_payload.get("step1AiFix"), dict) else {}
        if _money(raw_payload.get("step1MissingDebitTotal")) > Decimal("0.00") and not step1_fix:
            skipped.append({"runRowId": row_id, "reason": "Step 1 failed: same-date Xero debit entries are missing for payout credit(s)."})
            continue
        fix_amount = _money(step1_fix.get("missingDebitAmount")) if step1_fix else Decimal("0.00")
        if fix_amount > Decimal("0.00"):
            amount = fix_amount.copy_abs()
        fix_client_name = str(step1_fix.get("clientName") or "").strip() if step1_fix else ""
        if fix_client_name:
            client_name = fix_client_name
        fix_contact_id = str(step1_fix.get("xeroContactId") or "").strip() if step1_fix else ""
        if fix_contact_id:
            contact_id = fix_contact_id
        has_refund = _money(raw_payload.get("ignitionReversalTotal")) > Decimal("0.00")
        document_type = "invoice" if has_refund else "credit_note"
        policy_allowed, policy_code, policy_reason, policy_meta = _pi_posting_policy_for_row(
            row,
            step1_fix,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
        )
        if not policy_allowed:
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": policy_reason,
                    "policyCode": policy_code,
                    "reasonCode": str(policy_meta.get("reasonCode") or ""),
                    "policyTreatment": str(policy_meta.get("treatment") or ""),
                }
            )
            continue
        payout_date = _parse_optional_iso_date(step1_fix.get("targetDate")) if step1_fix else None
        if payout_date is None:
            payout_date = _parse_optional_iso_date(raw_payload.get("payoutDate"))
        if not contact_id and client_name:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT xero_contact_id
                        FROM customers
                        WHERE tenant_id = %s
                          AND LOWER(TRIM(name)) = LOWER(TRIM(%s))
                          AND NULLIF(TRIM(COALESCE(xero_contact_id, '')), '') IS NOT NULL
                        LIMIT 1
                        """,
                        (run_row.get("tenant_id"), client_name),
                    )
                    mapped_contact_row = cursor.fetchone() or {}
                connection.commit()
            mapped_contact_id = str(mapped_contact_row.get("xero_contact_id") or "").strip()
            if mapped_contact_id:
                contact_id = mapped_contact_id
        if amount <= 0:
            skipped.append({"runRowId": row_id, "reason": "Row has no non-zero difference."})
            continue
        if not contact_id:
            skipped.append({"runRowId": row_id, "reason": "No Xero contact is mapped for this row."})
            continue
        if document_type != "invoice":
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Only allowlisted recovery invoices can be posted in this release.",
                    "policyCode": "RULE_NOT_ALLOWLISTED",
                }
            )
            continue
        note_date = payout_date or run_row.get("month_end") or run_row.get("month_start") or utcnow().date()
        line_description = str(step1_fix.get("description") or "").strip() if step1_fix else ""
        if not line_description:
            line_description = "PI Refund Adjustment through Jenius AI" if has_refund else "PI Adjustment through Jenius AI"
        payout_identifier = str(step1_fix.get("payoutId") or "").strip() if step1_fix else ""
        payout_line_client = str(step1_fix.get("clientName") or "").strip() if step1_fix else ""
        if payout_line_client and payout_line_client.lower() not in line_description.lower():
            line_description = f"{line_description} · {payout_line_client}"
        if payout_identifier and payout_identifier.lower() not in line_description.lower():
            line_description = f"{line_description} · {payout_identifier}"
        collection_ids = [
            str(item).strip()
            for item in (
                step1_fix.get("ignitionPaymentIds")
                if isinstance(step1_fix.get("ignitionPaymentIds"), list)
                else row.get("ignition_payment_ids")
            ) or []
            if str(item).strip()
        ]
        if not collection_ids:
            collection_ids = [str(item).strip() for item in (raw_payload.get("ignitionPaymentIds") or []) if str(item).strip()]
        business_action_key = _pi_build_business_action_key(
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            run_id=run_id,
            run_row_id=row_id,
            action_type=PI_CLEARING_ALLOWED_POST_ACTION,
            payout_id=payout_identifier or str(raw_payload.get("payoutId") or ""),
            collection_ids=collection_ids,
            xero_contact_id=contact_id,
            amount=amount,
            note_date=note_date,
        )
        idempotency_key = f"pi-clearing-{business_action_key[:32]}"
        adjustment_payload = {
            "Type": "ACCREC" if has_refund else "ACCRECCREDIT",
            "Contact": {"ContactID": contact_id},
            "Date": note_date.isoformat(),
            "LineAmountTypes": "NoTax",
            "Status": "AUTHORISED",
            "Reference": "PI Refund Adjustment" if has_refund else "Client Payment",
            "LineItems": [
                {
                    "Description": line_description,
                    "Quantity": 1,
                    "UnitAmount": float(amount),
                    "AccountCode": account_code,
                    "TaxType": "NONE",
                }
            ],
            "CurrencyCode": currency_code,
        }
        payload_hash = _pi_payload_hash(adjustment_payload)
        source_snapshot_hash = _pi_action_source_snapshot_hash(
            run_row_id=row_id,
            row=row,
            step1_fix=step1_fix,
            amount=amount,
            contact_id=contact_id,
            note_date=note_date,
            account_code=account_code,
            document_type=document_type,
        )
        approval_row = _pi_get_action_approval(
            user_id=str(user.get("id") or ""),
            business_action_key=business_action_key,
        )
        approval_status = str(approval_row.get("status") or "").strip().upper()
        if approval_status != PI_CLEARING_ACTION_STATUS_APPROVED:
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Approval is required before posting this action.",
                    "policyCode": "APPROVAL_REQUIRED",
                    "businessActionKey": business_action_key,
                }
            )
            continue
        approved_payload_hash = str(approval_row.get("payload_hash") or "").strip()
        approved_source_hash = str(approval_row.get("source_snapshot_hash") or "").strip()
        if approved_payload_hash and approved_payload_hash != payload_hash:
            _pi_record_action_approval(
                run_id=run_id,
                row_id=row_id,
                user_id=str(user.get("id") or ""),
                tenant_id=str(run_row.get("tenant_id") or ""),
                business_action_key=business_action_key,
                payload_hash=payload_hash,
                source_snapshot_hash=source_snapshot_hash,
                status_value=PI_CLEARING_ACTION_STATUS_SUPERSEDED,
                notes="Payload changed after approval. Re-approve before posting.",
            )
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Approved payload has changed. Re-approve before posting.",
                    "policyCode": "APPROVAL_SUPERSEDED",
                    "businessActionKey": business_action_key,
                }
            )
            continue
        if approved_source_hash and approved_source_hash != source_snapshot_hash:
            _pi_record_action_approval(
                run_id=run_id,
                row_id=row_id,
                user_id=str(user.get("id") or ""),
                tenant_id=str(run_row.get("tenant_id") or ""),
                business_action_key=business_action_key,
                payload_hash=payload_hash,
                source_snapshot_hash=source_snapshot_hash,
                status_value=PI_CLEARING_ACTION_STATUS_SUPERSEDED,
                notes="Source snapshot changed after approval. Re-approve before posting.",
            )
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Source snapshot changed after approval. Re-approve before posting.",
                    "policyCode": "APPROVAL_SUPERSEDED",
                    "businessActionKey": business_action_key,
                }
            )
            continue
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT id, xero_credit_note_id, xero_credit_note_number, status
                    FROM pi_clearing_credit_notes
                    WHERE user_id = %s
                      AND business_action_key = %s
                    LIMIT 1
                    """,
                    (user["id"], business_action_key),
                )
                existing_action = cursor.fetchone() or {}
            connection.commit()
        existing_action_id = str(existing_action.get("id") or "").strip()
        if existing_action_id:
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Duplicate action prevented by business action key.",
                    "policyCode": "DUPLICATE_ACTION",
                    "existingActionId": existing_action_id,
                    "existingDocumentId": str(existing_action.get("xero_credit_note_id") or "").strip(),
                    "existingDocumentNumber": str(existing_action.get("xero_credit_note_number") or "").strip(),
                    "existingStatus": str(existing_action.get("status") or "").strip(),
                }
            )
            continue
        _pi_record_action_approval(
            run_id=run_id,
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=payload_hash,
            source_snapshot_hash=source_snapshot_hash,
            status_value=PI_CLEARING_ACTION_STATUS_POSTING,
            notes="Posting request sent to Xero.",
        )
        record_audit_event(
            "pi_clearing_action",
            business_action_key,
            "ACTION_POST_STARTED",
            {"runId": run_id, "runRowId": row_id, "payloadHash": payload_hash},
            user["id"],
        )
        xero_response = (
            await create_sales_invoice(connection_row, adjustment_payload, idempotency_key=idempotency_key)
            if has_refund
            else await create_credit_note(connection_row, adjustment_payload, idempotency_key=idempotency_key)
        )
        created_row = ((xero_response or {}).get("Invoices") or [{}])[0] if has_refund else ((xero_response or {}).get("CreditNotes") or [{}])[0]
        xero_document_id = str(
            created_row.get("InvoiceID")
            or created_row.get("CreditNoteID")
            or created_row.get("ID")
            or ""
        ).strip()
        xero_document_number = str(created_row.get("InvoiceNumber") or created_row.get("CreditNoteNumber") or "").strip()
        if not xero_document_id:
            _pi_record_action_approval(
                run_id=run_id,
                row_id=row_id,
                user_id=str(user.get("id") or ""),
                tenant_id=str(run_row.get("tenant_id") or ""),
                business_action_key=business_action_key,
                payload_hash=payload_hash,
                source_snapshot_hash=source_snapshot_hash,
                status_value=PI_CLEARING_ACTION_STATUS_FAILED_RETRYABLE,
                notes="Xero response missing document id.",
            )
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Xero did not return a document id."
                    if has_refund
                    else "Xero did not return a credit note id.",
                }
            )
            continue
        _pi_record_action_approval(
            run_id=run_id,
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=payload_hash,
            source_snapshot_hash=source_snapshot_hash,
            status_value=PI_CLEARING_ACTION_STATUS_POSTED_UNVERIFIED,
            notes="Xero document created; awaiting independent verification.",
        )
        now = utcnow()
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        INSERT INTO pi_clearing_credit_notes (
                            run_id, run_row_id, user_id, xero_contact_id, xero_credit_note_id, xero_credit_note_number,
                            credit_note_date, amount, currency_code, account_code, business_action_key, idempotency_key,
                            payload_hash, status, raw_payload, created_at, updated_at
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                        """,
                        (
                            run_id,
                            row_id,
                            user["id"],
                            contact_id,
                            xero_document_id,
                            xero_document_number,
                            note_date,
                            amount,
                            currency_code,
                            account_code,
                            business_action_key,
                            idempotency_key,
                            payload_hash,
                            "created",
                            json.dumps(
                                {
                                    "documentType": document_type,
                                    "postingMode": PI_CLEARING_POSTING_MODE_REVIEW,
                                "policyCode": policy_code,
                                "reasonCode": str(policy_meta.get("reasonCode") or ""),
                                "policyTreatment": str(policy_meta.get("treatment") or ""),
                                "ruleVersion": PI_CLEARING_RULE_VERSION,
                                "businessActionKey": business_action_key,
                                "idempotencyKey": idempotency_key,
                                    "payloadHash": payload_hash,
                                    "payload": xero_response or {},
                                },
                                default=_json_default,
                            ),
                            now,
                            now,
                        ),
                    )
                    cursor.execute(
                        """
                        UPDATE pi_clearing_run_rows
                        SET resolution_status = %s,
                            updated_at = %s
                        WHERE id = %s
                        """,
                        ("credit_note_created", now, row_id),
                    )
                    cursor.execute(
                        """
                        UPDATE pi_clearing_runs
                        SET status = %s,
                            updated_at = %s
                        WHERE id = %s
                        """,
                        (run_status_after_credit_note, now, run_id),
                    )
                connection.commit()
        except pg_errors.UniqueViolation:
            _pi_record_action_approval(
                run_id=run_id,
                row_id=row_id,
                user_id=str(user.get("id") or ""),
                tenant_id=str(run_row.get("tenant_id") or ""),
                business_action_key=business_action_key,
                payload_hash=payload_hash,
                source_snapshot_hash=source_snapshot_hash,
                status_value=PI_CLEARING_ACTION_STATUS_VERIFIED,
                notes="Duplicate prevented by unique business key; existing action reused.",
            )
            existing_action = _pi_find_existing_credit_note_action(
                user_id=str(user.get("id") or ""),
                business_action_key=business_action_key,
                idempotency_key=idempotency_key,
            )
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Duplicate action prevented by unique key during concurrent processing.",
                    "policyCode": "DUPLICATE_ACTION",
                    "existingActionId": str(existing_action.get("id") or "").strip(),
                    "existingDocumentId": str(existing_action.get("xero_credit_note_id") or "").strip(),
                    "existingDocumentNumber": str(existing_action.get("xero_credit_note_number") or "").strip(),
                    "existingStatus": str(existing_action.get("status") or "").strip(),
                }
            )
            continue
        _pi_record_action_approval(
            run_id=run_id,
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(run_row.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=payload_hash,
            source_snapshot_hash=source_snapshot_hash,
            status_value=PI_CLEARING_ACTION_STATUS_VERIFIED,
            notes="Post stored and row marked resolved.",
        )
        record_audit_event(
            "pi_clearing_action",
            business_action_key,
            "VERIFY_RESULT",
            {"runId": run_id, "runRowId": row_id, "documentId": xero_document_id, "status": "VERIFIED"},
            user["id"],
        )
        created.append(
            {
                "runRowId": row_id,
                "documentType": document_type,
                "xeroCreditNoteId": xero_document_id,
                "xeroCreditNoteNumber": xero_document_number,
                "amount": float(amount),
                "currencyCode": currency_code,
                "accountCode": account_code,
                "description": line_description,
                "businessActionKey": business_action_key,
                "idempotencyKey": idempotency_key,
                "payloadHash": payload_hash,
                "policyCode": policy_code,
                "reasonCode": str(policy_meta.get("reasonCode") or ""),
                "policyTreatment": str(policy_meta.get("treatment") or ""),
            }
        )

    updated = pi_clearing_payload(user)
    return {"created": created, "skipped": skipped, "runs": updated.get("runs") or []}


async def retry_pi_clearing_credit_notes(user: dict, run_id: str, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    selected_row_ids = [str(item).strip() for item in (safe_payload.get("rowIds") or []) if str(item).strip()]
    if not selected_row_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one row to retry.")
    prepared: list[dict] = []
    skipped: list[dict] = []
    for row_id in selected_row_ids:
        approval = _pi_get_latest_action_approval_for_row(
            user_id=str(user.get("id") or ""),
            run_id=str(run_id or ""),
            run_row_id=row_id,
        )
        if not approval:
            skipped.append({"runRowId": row_id, "reason": "No prior action approval exists for this row."})
            continue
        current_status = str(approval.get("status") or "").strip().upper()
        if current_status != PI_CLEARING_ACTION_STATUS_FAILED_RETRYABLE:
            skipped.append(
                {
                    "runRowId": row_id,
                    "reason": "Only FAILED_RETRYABLE actions can be retried.",
                    "status": current_status,
                }
            )
            continue
        business_action_key = str(approval.get("business_action_key") or "").strip()
        payload_hash = str(approval.get("payload_hash") or "").strip()
        source_snapshot_hash = str(approval.get("source_snapshot_hash") or "").strip()
        _pi_record_action_approval(
            run_id=str(run_id or ""),
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(approval.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=payload_hash,
            source_snapshot_hash=source_snapshot_hash,
            status_value=PI_CLEARING_ACTION_STATUS_APPROVED,
            approved_by_user_id=str(user.get("id") or ""),
            notes="Manual retry requested from PI Clearing workspace.",
        )
        record_audit_event(
            "pi_clearing_action",
            business_action_key,
            "ACTION_RETRY_REQUESTED",
            {"runId": run_id, "runRowId": row_id},
            user["id"],
        )
        prepared.append({"runRowId": row_id, "businessActionKey": business_action_key})
    if not prepared:
        updated = pi_clearing_payload(user)
        return {"prepared": [], "created": [], "skipped": skipped, "runs": updated.get("runs") or []}
    apply_payload = {
        "confirmed": True,
        "rowIds": [item.get("runRowId") for item in prepared if str(item.get("runRowId") or "").strip()],
    }
    if "accountCode" in safe_payload:
        apply_payload["accountCode"] = str(safe_payload.get("accountCode") or "").strip()
    apply_result = await apply_pi_clearing_credit_notes(user, run_id, apply_payload)
    return {
        "prepared": prepared,
        "created": apply_result.get("created") or [],
        "skipped": [*skipped, *(apply_result.get("skipped") or [])],
        "runs": apply_result.get("runs") or [],
    }


async def mark_pi_clearing_credit_notes_failed_manual(user: dict, run_id: str, payload: dict | None = None) -> dict:
    safe_payload = payload if isinstance(payload, dict) else {}
    selected_row_ids = [str(item).strip() for item in (safe_payload.get("rowIds") or []) if str(item).strip()]
    if not selected_row_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one row to mark as manual failure.")
    notes = str(safe_payload.get("notes") or "").strip() or "Manual investigation required."
    updated_items: list[dict] = []
    skipped: list[dict] = []
    for row_id in selected_row_ids:
        approval = _pi_get_latest_action_approval_for_row(
            user_id=str(user.get("id") or ""),
            run_id=str(run_id or ""),
            run_row_id=row_id,
        )
        if not approval:
            skipped.append({"runRowId": row_id, "reason": "No action approval record exists for this row."})
            continue
        business_action_key = str(approval.get("business_action_key") or "").strip()
        _pi_record_action_approval(
            run_id=str(run_id or ""),
            row_id=row_id,
            user_id=str(user.get("id") or ""),
            tenant_id=str(approval.get("tenant_id") or ""),
            business_action_key=business_action_key,
            payload_hash=str(approval.get("payload_hash") or "").strip(),
            source_snapshot_hash=str(approval.get("source_snapshot_hash") or "").strip(),
            status_value=PI_CLEARING_ACTION_STATUS_FAILED_MANUAL,
            notes=notes,
        )
        record_audit_event(
            "pi_clearing_action",
            business_action_key,
            "ACTION_FAILED_MANUAL",
            {"runId": run_id, "runRowId": row_id, "notes": notes},
            user["id"],
        )
        updated_items.append({"runRowId": row_id, "businessActionKey": business_action_key, "status": PI_CLEARING_ACTION_STATUS_FAILED_MANUAL})
    updated = pi_clearing_payload(user)
    return {"updated": updated_items, "skipped": skipped, "runs": updated.get("runs") or []}


async def void_pi_clearing_credit_note(user: dict, run_id: str, credit_note_record_id: str) -> dict:
    record_id = str(credit_note_record_id or "").strip()
    if not record_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Credit note record id is required.")

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM pi_clearing_credit_notes
                WHERE id = %s
                  AND run_id = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (record_id, run_id, user["id"]),
            )
            note_row = cursor.fetchone() or {}
            if not note_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="PI Clearing credit note record not found.")
            cursor.execute(
                """
                SELECT summary, month_start, month_end, tenant_id
                FROM pi_clearing_runs
                WHERE id = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (run_id, user["id"]),
            )
            run_row = cursor.fetchone() or {}
            run_tenant_id = str(run_row.get("tenant_id") or "").strip()
            if run_tenant_id:
                _pi_assert_writes_enabled_for_tenant(run_tenant_id)
            run_month_start = run_row.get("month_start")
            run_month_end = run_row.get("month_end")
            if run_tenant_id and isinstance(run_month_start, date) and isinstance(run_month_end, date):
                _pi_assert_requested_open_month(
                    cursor,
                    user_id=user["id"],
                    tenant_id=run_tenant_id,
                    requested_start=_pi_month_start(run_month_start),
                    requested_end=run_month_end,
                )
            status_value = str(note_row.get("status") or "").strip().lower()
            if status_value in {"voided", "deleted"}:
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="This PI Clearing credit note is already voided.")
            run_row_id = str(note_row.get("run_row_id") or "").strip()
            xero_credit_note_id = str(note_row.get("xero_credit_note_id") or "").strip()
            if not xero_credit_note_id:
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Xero credit note id is missing for this record.")
            note_raw_payload = note_row.get("raw_payload") if isinstance(note_row.get("raw_payload"), dict) else {}
            document_type = str(note_raw_payload.get("documentType") or "credit_note").strip().lower() or "credit_note"
            run_summary = run_row.get("summary") if isinstance(run_row.get("summary"), dict) else {}
            finalisation = _pi_finalisation_state_from_summary(run_summary)
            run_status_after_void = "completed" if finalisation.get("canFinalise") else "ready"
        connection.commit()

    connection_row = get_master_xero_connection_for_user(user["id"])
    xero_response = (
        await update_invoice_status(connection_row, xero_credit_note_id, "VOIDED")
        if document_type == "invoice"
        else await update_credit_note_status(connection_row, xero_credit_note_id, "VOIDED")
    )
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE pi_clearing_credit_notes
                SET status = %s,
                    raw_payload = %s::jsonb,
                    updated_at = %s
                WHERE id = %s
                """,
                ("voided", json.dumps(xero_response or {}, default=_json_default), now, record_id),
            )
            if run_row_id:
                cursor.execute(
                    """
                    UPDATE pi_clearing_run_rows
                    SET resolution_status = %s,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    ("pending", now, run_row_id),
                )
            cursor.execute(
                """
                UPDATE pi_clearing_runs
                SET status = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (run_status_after_void, now, run_id),
            )
        connection.commit()
    updated = pi_clearing_payload(user)
    return {
        "voided": {"id": record_id, "documentType": document_type, "xeroCreditNoteId": xero_credit_note_id},
        "runs": updated.get("runs") or [],
    }


def disconnect_xero(user: dict, tenant_id: str | None = None, disconnect_all: bool = False) -> dict:
    tenant_id = str(tenant_id or "").strip()
    selected_tenant_id = ""
    fallback_connection_id = ""
    user_rows = list_xero_connections_for_user(user["id"], include_fallback=False)
    preferred_tenant_name = get_settings().xero_primary_tenant_name

    if disconnect_all:
        pass
    elif tenant_id:
        selected_tenant_id = tenant_id
    elif user_rows:
        selected = max(user_rows, key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name))
        selected_tenant_id = str(selected.get("tenant_id") or "").strip()
    else:
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT id, tenant_id
                    FROM xero_connections
                    ORDER BY updated_at DESC NULLS LAST, created_at DESC
                    LIMIT 1
                    """
                )
                fallback = cursor.fetchone() or {}
                cursor.execute("SELECT COUNT(*) AS count FROM xero_connections")
                total = int((cursor.fetchone() or {}).get("count") or 0)
            connection.commit()
        if total == 1 and fallback.get("id"):
            fallback_connection_id = str(fallback.get("id") or "").strip()
            selected_tenant_id = str(fallback.get("tenant_id") or "").strip()

    disconnected_tenant_names: list[str] = []
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if disconnect_all:
                cursor.execute(
                    """
                    DELETE FROM xero_connections
                    WHERE user_id = %s
                    RETURNING tenant_name
                    """,
                    (user["id"],),
                )
                disconnected_tenant_names = [str(row.get("tenant_name") or "") for row in cursor.fetchall() or []]
            elif fallback_connection_id:
                cursor.execute(
                    """
                    DELETE FROM xero_connections
                    WHERE id = %s
                    RETURNING tenant_name
                    """,
                    (fallback_connection_id,),
                )
                disconnected_tenant_names = [str(row.get("tenant_name") or "") for row in cursor.fetchall() or []]
            elif selected_tenant_id:
                cursor.execute(
                    """
                    DELETE FROM xero_connections
                    WHERE user_id = %s
                      AND tenant_id = %s
                    RETURNING tenant_name
                    """,
                    (user["id"], selected_tenant_id),
                )
                disconnected_tenant_names = [str(row.get("tenant_name") or "") for row in cursor.fetchall() or []]

            cursor.execute(
                """
                UPDATE sync_runs
                SET status = %s,
                    current_step = %s,
                    summary = %s,
                    error_message = %s,
                    failed_count = GREATEST(failed_count, 1),
                    completed_at = %s
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status IN ('queued', 'running')
                """,
                (
                    "failed",
                    "Sync stopped",
                    "A Xero tenant was disconnected before the sync completed.",
                    "Xero is disconnected. Reconnect Xero before syncing again.",
                    utcnow(),
                    "xero",
                    user["id"],
                ),
            )
        if not disconnected_tenant_names:
            connection.rollback()
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="No matching Xero tenant connection was found.")
        connection.commit()

    for tenant_name in disconnected_tenant_names:
        record_audit_event(
            "xero_connection",
            str(user["id"]),
            "xero.disconnected",
            {"tenant_name": tenant_name},
            user["id"],
        )

    return {
        "disconnected": True,
        "tenant_name": disconnected_tenant_names[0] if disconnected_tenant_names else None,
        "tenant_names": disconnected_tenant_names,
        "disconnected_count": len(disconnected_tenant_names),
    }


def _upsert_xero_lock_date_snapshot(
    tenant_id: str,
    period_lock_date: date | None,
    end_of_year_lock_date: date | None,
    base_currency: str,
    xero_error: str,
    synced_at: datetime,
) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO xero_lock_date_snapshots (
                    tenant_id, period_lock_date, end_of_year_lock_date, base_currency, xero_error, last_synced_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (tenant_id) DO UPDATE
                SET period_lock_date = EXCLUDED.period_lock_date,
                    end_of_year_lock_date = EXCLUDED.end_of_year_lock_date,
                    base_currency = EXCLUDED.base_currency,
                    xero_error = EXCLUDED.xero_error,
                    last_synced_at = EXCLUDED.last_synced_at,
                    updated_at = EXCLUDED.updated_at
                """,
                (tenant_id, period_lock_date, end_of_year_lock_date, base_currency, xero_error, synced_at, synced_at),
            )
        connection.commit()


def _default_posting_settings(tenant_id: str | None = None) -> dict:
    settings = get_settings()
    return {
        "tenantId": tenant_id or "",
        "latePaymentChargeAccountCode": str(settings.late_payment_charge_account_code or "1222").strip(),
        "latePaymentChargeAccountName": "",
        "latePaymentChargeTaxType": str(settings.late_payment_charge_tax_type or "OUTPUT2").strip(),
        "badDebtWriteOffAccountCode": str(settings.bad_debt_write_off_account_code or "402").strip(),
        "badDebtWriteOffAccountName": "",
        "piClearingAccountCode": PI_CLEARING_DEFAULT_ACCOUNT_CODE,
        "piClearingAccountLocked": False,
        "piClearingWritesEnabled": True,
        "piClearingFeeTreatment": PI_CLEARING_FEE_TREATMENT_EXCLUDE,
        "updatedAt": "",
    }


def _serialize_posting_settings(row: dict | None, tenant_id: str | None = None) -> dict:
    defaults = _default_posting_settings(tenant_id or (row or {}).get("tenant_id"))
    if not row:
        return defaults
    return {
        "tenantId": row.get("tenant_id") or defaults["tenantId"],
        "latePaymentChargeAccountCode": row.get("late_payment_charge_account_code") or defaults["latePaymentChargeAccountCode"],
        "latePaymentChargeAccountName": row.get("late_payment_charge_account_name") or "",
        "latePaymentChargeTaxType": row.get("late_payment_charge_tax_type") or defaults["latePaymentChargeTaxType"],
        "badDebtWriteOffAccountCode": row.get("bad_debt_write_off_account_code") or defaults["badDebtWriteOffAccountCode"],
        "badDebtWriteOffAccountName": row.get("bad_debt_write_off_account_name") or "",
        "piClearingAccountCode": row.get("pi_clearing_account_code") or defaults["piClearingAccountCode"],
        "piClearingAccountLocked": bool(row.get("pi_clearing_account_locked")),
        "piClearingWritesEnabled": bool(row.get("pi_clearing_writes_enabled")) if row.get("pi_clearing_writes_enabled") is not None else True,
        "piClearingFeeTreatment": str(row.get("pi_clearing_fee_treatment") or defaults["piClearingFeeTreatment"]).strip().lower() or defaults["piClearingFeeTreatment"],
        "updatedAt": _iso(row.get("updated_at")) or "",
    }


def _posting_settings_for_tenant_with_cursor(cursor, tenant_id: str | None) -> dict:
    tenant_id = str(tenant_id or "").strip()
    if not tenant_id:
        return _default_posting_settings()
    cursor.execute("SELECT * FROM xero_posting_settings WHERE tenant_id = %s", (tenant_id,))
    return _serialize_posting_settings(cursor.fetchone(), tenant_id)


def posting_settings_for_tenant(tenant_id: str | None) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            settings = _posting_settings_for_tenant_with_cursor(cursor, tenant_id)
        connection.commit()
    return settings


def _account_sort_key(account: dict) -> tuple:
    code = str(account.get("code") or "").strip()
    if code.isdigit():
        return (0, int(code), account.get("name") or "")
    return (1, code.lower(), account.get("name") or "")


def _normalise_xero_account(account: dict) -> dict | None:
    status_value = str(account.get("Status") or "ACTIVE").strip().upper()
    if status_value and status_value != "ACTIVE":
        return None
    code = str(account.get("Code") or "").strip()
    if not code:
        return None
    return {
        "id": str(account.get("AccountID") or account.get("ID") or ""),
        "code": code,
        "name": str(account.get("Name") or "").strip(),
        "type": str(account.get("Type") or "").strip(),
        "taxType": str(account.get("TaxType") or "").strip(),
        "class": str(account.get("Class") or "").strip(),
        "status": status_value or "ACTIVE",
    }


async def _fetch_xero_chart_of_accounts(connection_row: dict) -> list[dict]:
    payload = await xero_api_get(connection_row, ACCOUNTS_URL)
    accounts = [
        normalised
        for normalised in (_normalise_xero_account(account) for account in payload.get("Accounts", []))
        if normalised
    ]
    return sorted(accounts, key=_account_sort_key)


async def xero_chart_of_accounts_payload(user: dict) -> dict:
    connection_row = get_xero_connection_for_user(user["id"])
    accounts = await _fetch_xero_chart_of_accounts(connection_row)
    return {
        "postingSettings": posting_settings_for_tenant(connection_row.get("tenant_id")),
        "xeroAccounts": accounts,
    }


def _parse_xero_lock_date(value: str | None) -> date | None:
    text = str(value or "").strip()
    if not text:
        return None
    if text.startswith("/Date("):
        match = re.search(r"/Date\((-?\d+)", text)
        if not match:
            return None
        try:
            milliseconds = int(match.group(1))
        except ValueError:
            return None
        return datetime.fromtimestamp(milliseconds / 1000, tz=timezone.utc).date()
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError:
        return None


def _parse_date_value(value) -> date | None:
    if isinstance(value, date) and not isinstance(value, datetime):
        return value
    if isinstance(value, datetime):
        return value.date()
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError:
        return None


def _latest_accounts_filed_date(ch_row: dict | None) -> date | None:
    if not ch_row:
        return None
    latest = ch_row.get("last_filed_date")
    filing_history = ch_row.get("filing_history") or []
    if not isinstance(filing_history, list):
        filing_history = []
    for item in filing_history:
        if not isinstance(item, dict):
            continue
        filing_type = str(item.get("type") or "").strip().upper()
        description = str(item.get("description") or "").strip().lower()
        category = str(item.get("category") or "").strip().lower()
        is_accounts_filing = filing_type.startswith("AA") or "accounts" in description or category == "accounts"
        if not is_accounts_filing:
            continue
        filed_on = _parse_date_value(item.get("date"))
        if filed_on and (latest is None or filed_on > latest):
            latest = filed_on
    return latest


def _companies_house_accounts_filing_made_up_to(item: dict | None) -> date | None:
    if not isinstance(item, dict):
        return None
    for key in ("made_up_to", "madeUpTo", "made_up_to_date", "period_end_on", "period_end_date", "period_end", "periodEnd"):
        parsed = _parse_date_value(item.get(key))
        if parsed:
            return parsed
    description_values = item.get("description_values")
    if isinstance(description_values, dict):
        for key in ("made_up_date", "made_up_to", "period_end_on", "period_end", "period_end_date"):
            parsed = _parse_date_value(description_values.get(key))
            if parsed:
                return parsed
    return None


def _companies_house_year_end_date(ch_row: dict | None) -> date | None:
    if not ch_row:
        return None
    candidates: list[date] = []
    filing_history = ch_row.get("filing_history") or []
    if not isinstance(filing_history, list):
        filing_history = []
    for item in filing_history:
        if not isinstance(item, dict):
            continue
        filing_type = str(item.get("type") or "").strip().upper()
        description = str(item.get("description") or "").strip().lower()
        category = str(item.get("category") or "").strip().lower()
        is_accounts_filing = filing_type.startswith("AA") or "accounts" in description or category == "accounts"
        if not is_accounts_filing:
            continue
        made_up_to = _companies_house_accounts_filing_made_up_to(item)
        if made_up_to:
            candidates.append(made_up_to)
    if not candidates:
        return None
    return max(candidates)


def _serialise_tenant_mapping(mapping_row: dict | None, tenant_id: str) -> dict:
    mapping_row = mapping_row or {}
    return {
        "tenantId": tenant_id,
        "companyNumber": str(mapping_row.get("company_number") or "").strip().upper(),
        "clientName": str(mapping_row.get("client_name") or "").strip(),
        "companyName": str(mapping_row.get("company_name") or "").strip(),
        "notes": str(mapping_row.get("notes") or "").strip(),
        "updatedAt": _iso(mapping_row.get("updated_at")) or "",
    }


def save_xero_tenant_company_mapping(user: dict, tenant_id: str, payload: dict) -> dict:
    tenant_id = str(tenant_id or "").strip()
    if not tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant ID is required.")
    company_number = str(payload.get("companyNumber") or "").strip().upper()
    if company_number and not re.fullmatch(r"[A-Z0-9]{2,12}", company_number):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Company number format is invalid.")
    client_name = str(payload.get("clientName") or "").strip()
    company_name = str(payload.get("companyName") or "").strip()
    notes = str(payload.get("notes") or "").strip()
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO xero_tenant_company_mappings (
                    tenant_id, company_number, client_name, company_name, notes, updated_by_user_id, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (tenant_id) DO UPDATE
                SET company_number = EXCLUDED.company_number,
                    client_name = EXCLUDED.client_name,
                    company_name = EXCLUDED.company_name,
                    notes = EXCLUDED.notes,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = EXCLUDED.updated_at
                RETURNING *
                """,
                (tenant_id, company_number, client_name, company_name, notes, user.get("id"), now, now),
            )
            mapping_row = cursor.fetchone()
        connection.commit()
    return _serialise_tenant_mapping(mapping_row, tenant_id)


def _is_xero_lock_date_manual_only_error(exc: HTTPException) -> bool:
    if int(exc.status_code or 0) != status.HTTP_502_BAD_GATEWAY:
        return False
    detail = exc.detail if isinstance(exc.detail, dict) else {}
    upstream_status = detail.get("status_code")
    try:
        upstream_status_code = int(upstream_status)
    except (TypeError, ValueError):
        upstream_status_code = None
    message = str(detail.get("message") or "").lower()
    return (
        upstream_status_code in (status.HTTP_404_NOT_FOUND, status.HTTP_405_METHOD_NOT_ALLOWED)
        and "lock date update" in message
    )


async def fix_xero_lock_date_mismatch(user: dict, tenant_id: str) -> dict:
    safe_tenant_id = str(tenant_id or "").strip()
    if not safe_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant ID is required.")

    connection_rows = list_xero_connections_for_user(user["id"], include_fallback=True)
    connection_row = next(
        (row for row in connection_rows if str(row.get("tenant_id") or "").strip() == safe_tenant_id),
        None,
    )
    if connection_row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Xero tenant connection not found.")

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT m.company_number, ch.company_name, ch.client_name, ch.last_filed_date, ch.filing_history
                FROM xero_tenant_company_mappings m
                LEFT JOIN ch_companies ch ON UPPER(ch.company_number) = UPPER(m.company_number)
                WHERE m.tenant_id = %s
                """,
                (safe_tenant_id,),
            )
            ch_mapping_row = cursor.fetchone() or {}
            cursor.execute(
                """
                SELECT period_lock_date, end_of_year_lock_date, base_currency
                FROM xero_lock_date_snapshots
                WHERE tenant_id = %s
                """,
                (safe_tenant_id,),
            )
            snapshot_row = cursor.fetchone() or {}
        connection.commit()

    mapped_company_number = str(ch_mapping_row.get("company_number") or "").strip().upper()
    if not mapped_company_number:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Map this tenant to a Companies House company number first.",
        )

    accounts_year_end_date = _companies_house_year_end_date(ch_mapping_row)
    accounts_filed_date = _latest_accounts_filed_date(ch_mapping_row)
    target_lock_date = accounts_year_end_date or accounts_filed_date
    if target_lock_date is None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No submitted Companies House accounts date is available for this mapped company yet.",
        )

    existing_period_lock_date = _parse_date_value(snapshot_row.get("period_lock_date"))
    existing_end_of_year_lock_date = _parse_date_value(snapshot_row.get("end_of_year_lock_date"))
    existing_effective_lock_date = max(
        [item for item in (existing_period_lock_date, existing_end_of_year_lock_date) if item],
        default=None,
    )
    if existing_effective_lock_date and existing_effective_lock_date >= target_lock_date:
        return {
            "tenantId": safe_tenant_id,
            "tenantName": str(connection_row.get("tenant_name") or ""),
            "companyNumber": mapped_company_number,
            "targetLockDate": target_lock_date.isoformat(),
            "periodLockDate": existing_period_lock_date.isoformat() if existing_period_lock_date else "",
            "endOfYearLockDate": existing_end_of_year_lock_date.isoformat() if existing_end_of_year_lock_date else "",
            "updated": False,
            "message": "Xero lock date already covers the latest filed Companies House accounts period.",
        }

    try:
        updated_lock_dates = await update_organisation_period_lock_date(connection_row, target_lock_date)
    except HTTPException as exc:
        if _is_xero_lock_date_manual_only_error(exc):
            return {
                "tenantId": safe_tenant_id,
                "tenantName": str(connection_row.get("tenant_name") or ""),
                "companyNumber": mapped_company_number,
                "targetLockDate": target_lock_date.isoformat(),
                "periodLockDate": existing_period_lock_date.isoformat() if existing_period_lock_date else "",
                "endOfYearLockDate": existing_end_of_year_lock_date.isoformat() if existing_end_of_year_lock_date else "",
                "updated": False,
                "manualActionRequired": True,
                "message": "Xero lock dates cannot be updated via API for this tenant. Update the lock date in Xero settings, then rerun mismatch cleanup.",
            }
        raise
    period_lock_date = updated_lock_dates.get("period_lock_date") or target_lock_date
    end_of_year_lock_date = updated_lock_dates.get("end_of_year_lock_date")
    base_currency = str(updated_lock_dates.get("base_currency") or snapshot_row.get("base_currency") or "").strip()
    now = utcnow()
    _upsert_xero_lock_date_snapshot(
        safe_tenant_id,
        period_lock_date,
        end_of_year_lock_date,
        base_currency,
        "",
        now,
    )
    record_audit_event(
        "xero_connection",
        safe_tenant_id,
        "xero.lock_date_fixed",
        {
            "tenant_id": safe_tenant_id,
            "tenant_name": str(connection_row.get("tenant_name") or ""),
            "company_number": mapped_company_number,
            "target_lock_date": target_lock_date.isoformat(),
            "result_period_lock_date": period_lock_date.isoformat() if period_lock_date else "",
            "result_end_of_year_lock_date": end_of_year_lock_date.isoformat() if end_of_year_lock_date else "",
        },
        user.get("id"),
    )
    return {
        "tenantId": safe_tenant_id,
        "tenantName": str(connection_row.get("tenant_name") or ""),
        "companyNumber": mapped_company_number,
        "targetLockDate": target_lock_date.isoformat(),
        "periodLockDate": period_lock_date.isoformat() if period_lock_date else "",
        "endOfYearLockDate": end_of_year_lock_date.isoformat() if end_of_year_lock_date else "",
        "updated": True,
        "message": "Xero period lock date updated to match Companies House.",
    }


async def xero_lock_date_overview_payload(user: dict, force_refresh: bool = False) -> dict:
    preferred_tenant_name = get_settings().xero_primary_tenant_name
    connection_rows = list_xero_connections_for_user(user["id"], include_fallback=True)
    if not connection_rows:
        return {
            "mainTenantName": preferred_tenant_name,
            "rows": [],
            "meta": {
                "refreshedTenants": 0,
                "cachedTenants": 0,
                "forcedRefresh": force_refresh,
            },
        }

    with get_connection() as connection:
        with connection.cursor() as cursor:
            tenant_ids = [str(row.get("tenant_id") or "").strip() for row in connection_rows if row.get("tenant_id")]
            cursor.execute(
                """
                SELECT *
                FROM xero_tenant_company_mappings
                WHERE tenant_id = ANY(%s)
                """,
                (tenant_ids or [""],),
            )
            mapping_rows = cursor.fetchall() or []
            mapping_by_tenant = {str(row.get("tenant_id") or ""): row for row in mapping_rows}
            cursor.execute(
                """
                SELECT *
                FROM xero_lock_date_snapshots
                WHERE tenant_id = ANY(%s)
                """,
                (tenant_ids or [""],),
            )
            snapshot_rows = cursor.fetchall() or []
            snapshot_by_tenant = {str(row.get("tenant_id") or ""): row for row in snapshot_rows}
            company_numbers = [
                str(row.get("company_number") or "").strip().upper()
                for row in mapping_rows
                if str(row.get("company_number") or "").strip()
            ]
            ch_by_company_number: dict[str, dict] = {}
            if company_numbers:
                cursor.execute(
                    """
                    SELECT company_number, company_name, client_name, last_filed_date, next_made_up_to_date, next_due_date, filing_history
                    FROM ch_companies
                    WHERE UPPER(company_number) = ANY(%s)
                    """,
                    (company_numbers,),
                )
                for row in cursor.fetchall() or []:
                    ch_by_company_number[str(row.get("company_number") or "").strip().upper()] = row
        connection.commit()

    rows: list[dict] = []
    refreshed_tenants = 0
    cached_tenants = 0
    now = utcnow()
    for connection_row in sorted(
        connection_rows,
        key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name),
        reverse=True,
    ):
        tenant_id = str(connection_row.get("tenant_id") or "").strip()
        snapshot_row = snapshot_by_tenant.get(tenant_id) or {}
        mapping_row = mapping_by_tenant.get(tenant_id)
        mapping = _serialise_tenant_mapping(mapping_row, tenant_id)
        mapped_company_number = mapping.get("companyNumber") or ""
        ch_row = ch_by_company_number.get(mapped_company_number)
        period_lock_date = _parse_date_value(snapshot_row.get("period_lock_date"))
        end_of_year_lock_date = _parse_date_value(snapshot_row.get("end_of_year_lock_date"))
        currency = str(snapshot_row.get("base_currency") or "").strip()
        xero_error = str(snapshot_row.get("xero_error") or "").strip()
        snapshot_synced_at = snapshot_row.get("last_synced_at")
        connection_updated_at = connection_row.get("updated_at")
        refresh_due = force_refresh or snapshot_synced_at is None
        if not refresh_due and snapshot_synced_at:
            refresh_due = (now - snapshot_synced_at) >= XERO_LOCK_DATE_CACHE_TTL
        if not refresh_due and snapshot_synced_at and connection_updated_at:
            refresh_due = connection_updated_at > snapshot_synced_at
        data_source = "cache"

        if refresh_due:
            try:
                organisation_payload = await xero_api_get(connection_row, XERO_ORGANISATION_URL)
                organisations = organisation_payload.get("Organisations") or []
                organisation = organisations[0] if organisations else {}
                period_lock_date = _parse_xero_lock_date(organisation.get("PeriodLockDate"))
                end_of_year_lock_date = _parse_xero_lock_date(organisation.get("EndOfYearLockDate"))
                currency = str(organisation.get("BaseCurrency") or "").strip()
                xero_error = ""
                refreshed_tenants += 1
                data_source = "live"
                _upsert_xero_lock_date_snapshot(
                    tenant_id,
                    period_lock_date,
                    end_of_year_lock_date,
                    currency,
                    xero_error,
                    now,
                )
            except HTTPException as exc:
                detail = exc.detail
                if isinstance(detail, dict):
                    xero_error = str(detail.get("message") or detail)
                else:
                    xero_error = str(detail)
                data_source = "cache" if snapshot_row else "error"
                _upsert_xero_lock_date_snapshot(
                    tenant_id,
                    period_lock_date,
                    end_of_year_lock_date,
                    currency,
                    xero_error,
                    now,
                )
        else:
            cached_tenants += 1

        accounts_filed_date = _latest_accounts_filed_date(ch_row)
        accounts_year_end_date = _companies_house_year_end_date(ch_row)
        ch_next_due_date = _parse_date_value((ch_row or {}).get("next_due_date"))
        xero_effective_lock_date = max(
            [lock_date for lock_date in (period_lock_date, end_of_year_lock_date) if lock_date],
            default=None,
        )
        comparison_target = accounts_year_end_date or accounts_filed_date
        mapping_missing = not mapped_company_number
        insufficient_accounts_data = bool(mapped_company_number and not comparison_target)
        accounts_filed_not_locked = bool(
            comparison_target
            and (xero_effective_lock_date is None or xero_effective_lock_date < comparison_target)
        )
        rows.append(
            {
                "tenantId": tenant_id,
                "tenantName": str(connection_row.get("tenant_name") or ""),
                "tenantType": str(connection_row.get("tenant_type") or ""),
                "isMainTenant": _is_preferred_xero_tenant(connection_row, preferred_tenant_name),
                "xeroConnectionUpdatedAt": _iso(connection_row.get("updated_at")) or "",
                "periodLockDate": period_lock_date.isoformat() if period_lock_date else "",
                "endOfYearLockDate": end_of_year_lock_date.isoformat() if end_of_year_lock_date else "",
                "baseCurrency": currency,
                "mapping": mapping,
                "companiesHouse": {
                    "companyNumber": mapped_company_number,
                    "companyName": str((ch_row or {}).get("company_name") or ""),
                    "clientName": str((ch_row or {}).get("client_name") or ""),
                    "accountsFiledDate": accounts_filed_date.isoformat() if accounts_filed_date else "",
                    "yearEndDate": accounts_year_end_date.isoformat() if accounts_year_end_date else "",
                    "lastSubmittedDate": (
                        accounts_year_end_date.isoformat()
                        if accounts_year_end_date
                        else accounts_filed_date.isoformat() if accounts_filed_date else ""
                    ),
                    "nextDueDate": ch_next_due_date.isoformat() if ch_next_due_date else "",
                },
                "flags": {
                    "accountsFiledNotLocked": accounts_filed_not_locked,
                    "mappingMissing": mapping_missing,
                    "insufficientAccountsData": insufficient_accounts_data,
                },
                "dataSource": data_source,
                "lastSyncedAt": _iso(snapshot_row.get("last_synced_at")) or "",
                "xeroError": xero_error,
            }
        )

    rows.sort(
        key=lambda row: (
            1 if row.get("flags", {}).get("accountsFiledNotLocked") else 0,
            1 if row.get("isMainTenant") else 0,
            row.get("tenantName", "").lower(),
        ),
        reverse=True,
    )
    return {
        "mainTenantName": preferred_tenant_name,
        "rows": rows,
        "meta": {
            "refreshedTenants": refreshed_tenants,
            "cachedTenants": cached_tenants,
            "forcedRefresh": force_refresh,
        },
    }


def _xero_lock_date_mismatch_rows(overview_rows: list[dict]) -> list[dict]:
    rows: list[dict] = []
    for row in overview_rows or []:
        flags = row.get("flags") or {}
        if not bool(flags.get("accountsFiledNotLocked")):
            continue
        mapping = row.get("mapping") or {}
        companies_house = row.get("companiesHouse") or {}
        lock_date = row.get("periodLockDate") or row.get("endOfYearLockDate") or ""
        year_end_date = str(companies_house.get("yearEndDate") or "")
        filed_date = str(companies_house.get("accountsFiledDate") or "")
        reason = (
            "Accounts are filed at Companies House but Xero lock dates are missing or older than the Companies House year-end date."
            if year_end_date
            else "Accounts are filed at Companies House but Xero lock dates are missing or older than the filed date."
        )
        rows.append(
            {
                "tenantId": str(row.get("tenantId") or ""),
                "tenantName": str(row.get("tenantName") or ""),
                "companyNumber": str(mapping.get("companyNumber") or companies_house.get("companyNumber") or ""),
                "companyName": str(companies_house.get("companyName") or mapping.get("companyName") or ""),
                "clientName": str(companies_house.get("clientName") or mapping.get("clientName") or ""),
                "xeroLockDate": str(lock_date or ""),
                "accountsFiledDate": filed_date,
                "yearEndDate": year_end_date,
                "reason": reason,
            }
        )
    return rows


async def xero_lock_date_mismatch_payload(user: dict, force_refresh: bool = False) -> dict:
    overview = await xero_lock_date_overview_payload(user, force_refresh=force_refresh)
    mismatches = _xero_lock_date_mismatch_rows(overview.get("rows") or [])
    generated_at = utcnow().isoformat()
    return {
        "generatedAt": generated_at,
        "rows": mismatches,
        "summary": {
            "mismatchCount": len(mismatches),
            "tenantCount": len(overview.get("rows") or []),
        },
    }


def xero_lock_date_mismatch_pdf(rows: list[dict], generated_at: str) -> tuple[bytes, str]:
    lines = [
        "Xero Lock-Date Mismatches",
        f"Generated: {generated_at}",
        "",
    ]
    for row in rows or []:
        tenant = str(row.get("tenantName") or "Unknown tenant")
        company_name = str(row.get("companyName") or row.get("clientName") or "Unknown company")
        company_number = str(row.get("companyNumber") or "")
        lock_date = str(row.get("xeroLockDate") or "Not set")
        filed_date = str(row.get("accountsFiledDate") or "Unknown")
        label = f"{tenant} | {company_name}"
        if company_number:
            label = f"{label} ({company_number})"
        lines.append(f"- {label} | Lock: {lock_date} | Filed: {filed_date}")
    if len(lines) == 3:
        lines.append("No lock mismatches found.")

    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except Exception:
        return _minimal_me_report_pdf(lines), "xero-lock-date-mismatches.pdf"

    buffer = io.BytesIO()
    document = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        title="Xero Lock-Date Mismatches",
        author="Credit Control Console",
        leftMargin=32,
        rightMargin=32,
        topMargin=32,
        bottomMargin=32,
    )
    styles = getSampleStyleSheet()
    story = [
        Paragraph("Xero Lock-Date Mismatches", styles["Title"]),
        Paragraph(f"Generated: {generated_at}", styles["Normal"]),
        Spacer(1, 12),
    ]
    table_rows = [["Tenant", "Company", "CH Number", "Xero Lock Date", "CH Submitted Accounts"]]
    for row in rows or []:
        table_rows.append(
            [
                str(row.get("tenantName") or ""),
                str(row.get("companyName") or row.get("clientName") or ""),
                str(row.get("companyNumber") or ""),
                str(row.get("xeroLockDate") or "Not set"),
                str(row.get("accountsFiledDate") or "Unknown"),
            ]
        )
    if len(table_rows) == 1:
        table_rows.append(["-", "No lock mismatches found", "-", "-", "-"])
    table = Table(table_rows, repeatRows=1)
    table.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1d67f2")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("FONTNAME", (0, 1), (-1, -1), "Helvetica"),
                ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#d8dfef")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f5f8ff")]),
                ("FONTSIZE", (0, 0), (-1, -1), 8),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]
        )
    )
    story.append(table)
    document.build(story)
    return buffer.getvalue(), "xero-lock-date-mismatches.pdf"


async def save_posting_settings(user: dict, payload: dict) -> dict:
    connection_row = get_xero_connection_for_user(user["id"])
    accounts = await _fetch_xero_chart_of_accounts(connection_row)
    account_by_code = {str(account.get("code") or "").strip().lower(): account for account in accounts}
    late_payment_code = str(payload.get("latePaymentChargeAccountCode") or "").strip()
    bad_debt_code = str(payload.get("badDebtWriteOffAccountCode") or "").strip()
    if not late_payment_code or not bad_debt_code:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose both Xero posting accounts before saving.")
    late_payment_account = account_by_code.get(late_payment_code.lower())
    bad_debt_account = account_by_code.get(bad_debt_code.lower())
    if late_payment_account is None:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose a late payment charge account from the connected Xero chart of accounts.")
    if bad_debt_account is None:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose a bad debt write-off account from the connected Xero chart of accounts.")

    tenant_id = str(connection_row.get("tenant_id") or "").strip()
    tax_type = str(payload.get("latePaymentChargeTaxType") or get_settings().late_payment_charge_tax_type or "OUTPUT2").strip()
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO xero_posting_settings (
                    tenant_id,
                    late_payment_charge_account_code,
                    late_payment_charge_account_name,
                    late_payment_charge_tax_type,
                    bad_debt_write_off_account_code,
                    bad_debt_write_off_account_name,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (tenant_id) DO UPDATE
                SET late_payment_charge_account_code = EXCLUDED.late_payment_charge_account_code,
                    late_payment_charge_account_name = EXCLUDED.late_payment_charge_account_name,
                    late_payment_charge_tax_type = EXCLUDED.late_payment_charge_tax_type,
                    bad_debt_write_off_account_code = EXCLUDED.bad_debt_write_off_account_code,
                    bad_debt_write_off_account_name = EXCLUDED.bad_debt_write_off_account_name,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = EXCLUDED.updated_at
                """,
                (
                    tenant_id,
                    late_payment_account["code"],
                    late_payment_account.get("name") or "",
                    tax_type,
                    bad_debt_account["code"],
                    bad_debt_account.get("name") or "",
                    user["id"],
                    now,
                    now,
                ),
            )
            settings = _posting_settings_for_tenant_with_cursor(cursor, tenant_id)
        connection.commit()

    record_audit_event(
        "xero_posting_settings",
        tenant_id,
        "posting_settings.updated",
        {
            "late_payment_charge_account_code": late_payment_account["code"],
            "late_payment_charge_account_name": late_payment_account.get("name") or "",
            "late_payment_charge_tax_type": tax_type,
            "bad_debt_write_off_account_code": bad_debt_account["code"],
            "bad_debt_write_off_account_name": bad_debt_account.get("name") or "",
        },
        user["id"],
    )
    return {"postingSettings": settings, "xeroAccounts": accounts}


async def save_pi_clearing_account_setup(user: dict, payload: dict) -> dict:
    connection_row = get_master_xero_connection_for_user(user["id"])
    tenant_id = str(connection_row.get("tenant_id") or "").strip()
    selected_value = str(payload.get("piClearingAccountCode") or payload.get("accountCode") or "").strip()
    if not selected_value:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select a PI nominal account before starting the batch.")

    accounts = await _fetch_xero_chart_of_accounts(connection_row)
    account_by_code = {str(account.get("code") or "").strip().lower(): account for account in accounts}
    selected_account = account_by_code.get(selected_value.lower())
    if selected_account is None:
        selected_account = next(
            (
                account
                for account in accounts
                if str(account.get("name") or "").strip().lower() == selected_value.lower()
            ),
            None,
        )
    if selected_account is None and "·" in selected_value:
        selected_code_hint = selected_value.split("·", 1)[0].strip()
        if selected_code_hint:
            selected_account = account_by_code.get(selected_code_hint.lower())
    if selected_account is None:
        fuzzy = [
            account for account in accounts
            if selected_value.lower() in str(account.get("code") or "").strip().lower()
            or selected_value.lower() in str(account.get("name") or "").strip().lower()
        ]
        if len(fuzzy) == 1:
            selected_account = fuzzy[0]
    if selected_account is None:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select a PI nominal account from the connected Jaccountancy chart of accounts.")
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM xero_posting_settings WHERE tenant_id = %s", (tenant_id,))
            current_row = cursor.fetchone() or {}
            writes_enabled_input = payload.get("piClearingWritesEnabled") if "piClearingWritesEnabled" in payload else payload.get("writesEnabled")
            if writes_enabled_input is None:
                writes_enabled = bool(current_row.get("pi_clearing_writes_enabled")) if current_row else True
            else:
                writes_enabled = bool(writes_enabled_input)
            fee_treatment_input = payload.get("piClearingFeeTreatment") if "piClearingFeeTreatment" in payload else payload.get("feeTreatment")
            fee_treatment = str(
                fee_treatment_input
                if fee_treatment_input is not None
                else (current_row.get("pi_clearing_fee_treatment") if current_row else PI_CLEARING_FEE_TREATMENT_EXCLUDE)
            ).strip().lower() or PI_CLEARING_FEE_TREATMENT_EXCLUDE
            if fee_treatment not in PI_CLEARING_FEE_TREATMENTS:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"Fee treatment must be one of: {', '.join(sorted(PI_CLEARING_FEE_TREATMENTS))}.",
                )
            current_code = str(current_row.get("pi_clearing_account_code") or "").strip()
            is_locked = bool(current_row.get("pi_clearing_account_locked"))
            if is_locked and current_code and current_code.lower() != selected_account["code"].lower():
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"PI nominal is locked to {current_code}. It cannot be changed.",
                )
            cursor.execute(
                """
                INSERT INTO xero_posting_settings (
                    tenant_id,
                    pi_clearing_account_code,
                    pi_clearing_account_locked,
                    pi_clearing_writes_enabled,
                    pi_clearing_fee_treatment,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (tenant_id) DO UPDATE
                SET pi_clearing_account_code = EXCLUDED.pi_clearing_account_code,
                    pi_clearing_account_locked = CASE
                        WHEN xero_posting_settings.pi_clearing_account_locked THEN TRUE
                        ELSE EXCLUDED.pi_clearing_account_locked
                    END,
                    pi_clearing_writes_enabled = EXCLUDED.pi_clearing_writes_enabled,
                    pi_clearing_fee_treatment = EXCLUDED.pi_clearing_fee_treatment,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = EXCLUDED.updated_at
                """,
                (tenant_id, selected_account["code"], True, writes_enabled, fee_treatment, user["id"], now, now),
            )
            settings = _posting_settings_for_tenant_with_cursor(cursor, tenant_id)
        connection.commit()

    record_audit_event(
        "xero_posting_settings",
        tenant_id,
        "pi_clearing_account.locked",
        {
            "pi_clearing_account_code": selected_account["code"],
            "pi_clearing_account_name": selected_account.get("name") or "",
            "pi_clearing_writes_enabled": writes_enabled,
            "pi_clearing_fee_treatment": fee_treatment,
        },
        user["id"],
    )
    return {"postingSettings": settings, "xeroAccounts": accounts}


def factory_reset_console(user: dict) -> dict:
    tenant_id = None
    try:
        tenant_id = get_xero_connection_for_user(user["id"]).get("tenant_id")
    except HTTPException:
        tenant_id = None

    with get_connection() as connection:
        with connection.cursor() as cursor:
            if tenant_id:
                cursor.execute("DELETE FROM customers WHERE tenant_id = %s", (tenant_id,))
            else:
                cursor.execute("DELETE FROM customers")
            customers_deleted = cursor.rowcount
            cursor.execute(
                "DELETE FROM sync_runs WHERE provider = %s AND initiated_by_user_id = %s",
                ("xero", user["id"]),
            )
            sync_runs_deleted = cursor.rowcount
            cursor.execute("DELETE FROM audit_events")
        connection.commit()

    record_audit_event(
        "console",
        str(user["id"]),
        "factory_reset.completed",
        {
            "tenant_id": tenant_id,
            "customers_deleted": customers_deleted,
            "sync_runs_deleted": sync_runs_deleted,
        },
        user["id"],
    )
    return {
        "tenantId": tenant_id,
        "customersDeleted": customers_deleted,
        "syncRunsDeleted": sync_runs_deleted,
    }


def _sync_error_message(exc: Exception) -> str:
    if isinstance(exc, HTTPException):
        detail = exc.detail
        if isinstance(detail, dict):
            return str(detail.get("message") or detail)
        return str(detail)
    return str(exc) or exc.__class__.__name__


def _sync_error_payload(exc: Exception) -> dict:
    if isinstance(exc, HTTPException):
        return {
            "type": "HTTPException",
            "status_code": exc.status_code,
            "detail": exc.detail,
        }
    return {
        "type": exc.__class__.__name__,
        "message": str(exc),
    }


def _format_wait_seconds(seconds: int) -> str:
    seconds = max(int(seconds or 0), 0)
    if seconds < 60:
        return f"{seconds} seconds"
    minutes, remainder = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}m {remainder:02d}s"
    hours, minutes = divmod(minutes, 60)
    return f"{hours}h {minutes:02d}m"


def _xero_rate_limit_retry_seconds(exc: Exception) -> int | None:
    if not isinstance(exc, HTTPException) or not isinstance(exc.detail, dict):
        return None
    if exc.detail.get("status_code") != status.HTTP_429_TOO_MANY_REQUESTS:
        return None
    raw_delay = exc.detail.get("retry_after_seconds") or exc.detail.get("retry_after") or 0
    try:
        return max(0, int(raw_delay))
    except (TypeError, ValueError):
        return 0


def _active_xero_rate_limit(user_id: str) -> dict | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT rate_limit_until, retry_after_seconds, error_message
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND rate_limit_until IS NOT NULL
                  AND rate_limit_until > NOW()
                ORDER BY rate_limit_until DESC, completed_at DESC NULLS LAST, created_at DESC
                LIMIT 1
                """,
                ("xero", user_id),
            )
            row = cursor.fetchone()
            cursor.execute(
                """
                SELECT created_at, payload
                FROM audit_events
                WHERE user_id = %s
                  AND event_type = %s
                ORDER BY created_at DESC
                LIMIT 20
                """,
                (user_id, "sync.failed"),
            )
            audit_rows = cursor.fetchall()
        connection.commit()

    if row is not None:
        remaining_seconds = max(0, int((row["rate_limit_until"] - utcnow()).total_seconds()) + 1)
        return {
            "rate_limit_until": row["rate_limit_until"],
            "retry_after_seconds": remaining_seconds,
            "message": (
                f"Xero has rate-limited this connection. Wait about {_format_wait_seconds(remaining_seconds)} "
                "before starting another sync."
            ),
            "previous_error": row.get("error_message") or "",
        }

    for audit_row in audit_rows:
        payload = audit_row.get("payload") or {}
        if not isinstance(payload, dict):
            continue
        detail = payload.get("detail") if isinstance(payload.get("detail"), dict) else {}
        nested_detail = detail.get("detail") if isinstance(detail.get("detail"), dict) else {}
        message = str(payload.get("error") or nested_detail.get("message") or "")
        if "rate-limit" not in message.lower() or "contacts request" in message.lower():
            continue
        retry_after_seconds = nested_detail.get("retry_after_seconds") or nested_detail.get("retry_after") or 0
        try:
            retry_after_seconds = max(0, int(retry_after_seconds))
        except (TypeError, ValueError):
            continue
        rate_limit_until = audit_row["created_at"] + timedelta(seconds=retry_after_seconds)
        if rate_limit_until <= utcnow():
            continue
        remaining_seconds = max(0, int((rate_limit_until - utcnow()).total_seconds()) + 1)
        return {
            "rate_limit_until": rate_limit_until,
            "retry_after_seconds": remaining_seconds,
            "message": (
                f"Xero has rate-limited this connection. Wait about {_format_wait_seconds(remaining_seconds)} "
                "before starting another sync."
            ),
            "previous_error": message,
        }

    return None


def active_xero_rate_limit_for_user(user: dict | None) -> dict | None:
    if not user or not user.get("id"):
        return None
    return _active_xero_rate_limit(user["id"])


def serialize_xero_rate_limit(rate_limit: dict | None) -> dict | None:
    if not rate_limit:
        return None
    return {
        "rateLimitUntil": _iso(rate_limit.get("rate_limit_until")) or "",
        "retryAfterSeconds": int(rate_limit.get("retry_after_seconds") or 0),
        "message": rate_limit.get("message") or "",
        "previousError": rate_limit.get("previous_error") or "",
    }


def normalise_sync_options(options: dict | None = None) -> dict:
    options = options or {}
    invoice_scope = str(options.get("invoiceScope") or DEFAULT_SYNC_SCOPE)
    if invoice_scope not in SYNC_SCOPE_OPTIONS:
        invoice_scope = DEFAULT_SYNC_SCOPE
    scope = SYNC_SCOPE_OPTIONS[invoice_scope]
    raw_years = options.get("invoiceYears") or options.get("invoice_years") or []
    if not isinstance(raw_years, list):
        raw_years = [raw_years]
    current_year = utcnow().year
    invoice_years = sorted(
        {
            int(year)
            for year in raw_years
            if str(year).isdigit() and 2000 <= int(year) <= current_year + 1
        }
    )
    year_summary = "Years: all available invoice years." if not invoice_years else f"Years: {', '.join(str(year) for year in invoice_years)}."
    return {
        "invoice_scope": invoice_scope,
        "label": scope["label"],
        "paid_page_limit": scope["paid_page_limit"],
        "invoice_years": invoice_years,
        "year_label": "No years selected" if not invoice_years else ", ".join(str(year) for year in invoice_years),
        "summary": f"{scope['summary']} {year_summary}",
    }


def _sync_options_signature(sync_options: dict) -> str:
    return json.dumps(
        {
            "invoice_scope": sync_options.get("invoice_scope") or DEFAULT_SYNC_SCOPE,
            "invoice_years": sync_options.get("invoice_years") or [],
            "paid_page_limit": sync_options.get("paid_page_limit"),
        },
        sort_keys=True,
        separators=(",", ":"),
    )


def _upsert_sync_checkpoint(
    sync_run_id: str,
    user_id: str,
    tenant_id: str,
    sync_signature: str,
    phase: str,
    status_value: str,
    page_number: int = 0,
    records_seen: int = 0,
    records_stored: int = 0,
    payload: dict | None = None,
) -> dict | None:
    now = utcnow()
    completed_at = now if status_value == "completed" else None
    sync_run_key = str(sync_run_id)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO sync_checkpoints (
                    sync_run_id, provider, initiated_by_user_id, tenant_id, sync_signature,
                    phase, status, page_number, records_seen, records_stored, payload,
                    updated_at, completed_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                ON CONFLICT (sync_run_id, phase) DO UPDATE
                SET status = EXCLUDED.status,
                    page_number = EXCLUDED.page_number,
                    records_seen = EXCLUDED.records_seen,
                    records_stored = EXCLUDED.records_stored,
                    payload = EXCLUDED.payload,
                    updated_at = EXCLUDED.updated_at,
                    completed_at = EXCLUDED.completed_at
                RETURNING *
                """,
                (
                    sync_run_key,
                    "xero",
                    user_id,
                    tenant_id,
                    sync_signature,
                    phase,
                    status_value,
                    max(int(page_number or 0), 0),
                    max(int(records_seen or 0), 0),
                    max(int(records_stored or 0), 0),
                    json.dumps(payload or {}, default=_json_default),
                    now,
                    completed_at,
                ),
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def _latest_resumable_sync_state(user_id: str, tenant_id: str, sync_signature: str) -> dict | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT sync_runs.*
                FROM sync_runs
                WHERE sync_runs.provider = %s
                  AND sync_runs.initiated_by_user_id = %s
                  AND sync_runs.status = %s
                  AND EXISTS (
                      SELECT 1
                      FROM sync_checkpoints
                      WHERE sync_checkpoints.sync_run_id = sync_runs.id::text
                        AND sync_checkpoints.tenant_id = %s
                        AND sync_checkpoints.sync_signature = %s
                  )
                ORDER BY sync_runs.completed_at DESC NULLS LAST, sync_runs.created_at DESC
                LIMIT 1
                """,
                ("xero", user_id, "failed", tenant_id, sync_signature),
            )
            sync_run = cursor.fetchone()
            if sync_run is None:
                connection.commit()
                return None

            cursor.execute(
                """
                SELECT *
                FROM sync_checkpoints
                WHERE sync_run_id = %s
                  AND tenant_id = %s
                  AND sync_signature = %s
                """,
                (str(sync_run["id"]), tenant_id, sync_signature),
            )
            checkpoints = {row["phase"]: row for row in cursor.fetchall()}
        connection.commit()

    return {"sync_run": sync_run, "checkpoints": checkpoints}


def _checkpoint_completed(checkpoints: dict, phase: str) -> bool:
    checkpoint = checkpoints.get(phase)
    return bool(checkpoint and checkpoint.get("status") == "completed")


def _checkpoint_payload_count(checkpoint: dict | None, key: str, fallback: int = 0) -> int:
    payload = (checkpoint or {}).get("payload") or {}
    try:
        return int(payload.get(key, fallback) or 0)
    except (TypeError, ValueError):
        return fallback


def _invoice_year_sql_filter(invoice_years: list[int], column: str = "invoices.invoice_date") -> tuple[str, list]:
    if not invoice_years:
        return "", []
    return f" AND EXTRACT(YEAR FROM {column})::INT = ANY(%s)", [invoice_years]


def _local_resume_counts(tenant_id: str, invoice_years: list[int]) -> dict:
    year_filter, year_params = _invoice_year_sql_filter(invoice_years)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT COUNT(*) AS count FROM customers WHERE tenant_id = %s", (tenant_id,))
            customer_count = int((cursor.fetchone() or {}).get("count") or 0)
            cursor.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE customers.tenant_id = %s
                  AND invoices.status NOT IN ('VOIDED', 'DELETED', 'PAID')
                  {year_filter}
                """,
                (tenant_id, *year_params),
            )
            outstanding_count = int((cursor.fetchone() or {}).get("count") or 0)
            cursor.execute(
                f"""
                SELECT COUNT(*) AS count
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE customers.tenant_id = %s
                  AND invoices.status = 'PAID'
                  {year_filter}
                """,
                (tenant_id, *year_params),
            )
            paid_count = int((cursor.fetchone() or {}).get("count") or 0)
        connection.commit()

    return {"customers": customer_count, "outstanding_invoices": outstanding_count, "paid_invoices": paid_count}


def _xero_year_filter(invoice_years: list[int]) -> str:
    clauses = [
        f"(Date>=DateTime({year}, 1, 1)&&Date<DateTime({year + 1}, 1, 1))"
        for year in invoice_years
    ]
    return f"({'||'.join(clauses)})" if clauses else ""


def _with_invoice_year_filter(base_where: str, invoice_years: list[int]) -> str:
    year_filter = _xero_year_filter(invoice_years)
    return f"{base_where}&&{year_filter}" if year_filter else base_where


def _latest_completed_sync_started_at(user_id: str) -> datetime | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT COALESCE(started_at, created_at, completed_at) AS sync_started_at
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status = %s
                  AND completed_at IS NOT NULL
                ORDER BY completed_at DESC, created_at DESC
                LIMIT 1
                """,
                ("xero", user_id, "completed"),
            )
            row = cursor.fetchone()
        connection.commit()

    return row["sync_started_at"] if row and row.get("sync_started_at") else None


def _incremental_modified_since(user_id: str) -> datetime | None:
    latest_started_at = _latest_completed_sync_started_at(user_id)
    if latest_started_at is None:
        return None
    return latest_started_at - INCREMENTAL_SYNC_OVERLAP


def _local_cache_sync_state(tenant_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT COUNT(*) AS count, MAX(COALESCE(last_sync_at, updated_at)) AS latest_at FROM customers WHERE tenant_id = %s", (tenant_id,))
            customer_row = cursor.fetchone() or {}
            cursor.execute(
                """
                SELECT COUNT(*) AS count, MAX(COALESCE(invoices.synced_at, invoices.updated_at)) AS latest_at
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE customers.tenant_id = %s
                """,
                (tenant_id,),
            )
            invoice_row = cursor.fetchone() or {}
            cursor.execute("SELECT COUNT(*) AS count, MAX(COALESCE(synced_at, updated_at)) AS latest_at FROM payments WHERE tenant_id = %s", (tenant_id,))
            payment_row = cursor.fetchone() or {}
            cursor.execute("SELECT COUNT(*) AS count, MAX(COALESCE(synced_at, updated_at)) AS latest_at FROM customer_credits WHERE tenant_id = %s", (tenant_id,))
            credit_row = cursor.fetchone() or {}
        connection.commit()

    latest_candidates = [
        customer_row.get("latest_at"),
        invoice_row.get("latest_at"),
        payment_row.get("latest_at"),
        credit_row.get("latest_at"),
    ]
    latest_at = max((value for value in latest_candidates if value is not None), default=None)
    return {
        "customers": int(customer_row.get("count") or 0),
        "invoices": int(invoice_row.get("count") or 0),
        "payments": int(payment_row.get("count") or 0),
        "credits": int(credit_row.get("count") or 0),
        "latest_at": latest_at,
    }


def _local_cache_modified_since(tenant_id: str) -> datetime | None:
    cache_state = _local_cache_sync_state(tenant_id)
    if cache_state["customers"] <= 0 and cache_state["invoices"] <= 0:
        return None
    latest_at = cache_state.get("latest_at")
    if latest_at is None:
        return utcnow() - INCREMENTAL_SYNC_OVERLAP
    return latest_at - INCREMENTAL_SYNC_OVERLAP


def _local_invoice_years_cover(tenant_id: str, invoice_years: list[int]) -> bool:
    if not invoice_years:
        return False
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT DISTINCT EXTRACT(YEAR FROM invoices.invoice_date)::INT AS invoice_year
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE customers.tenant_id = %s
                  AND invoices.invoice_date IS NOT NULL
                """,
                (tenant_id,),
            )
            imported_years = {row["invoice_year"] for row in cursor.fetchall() if row.get("invoice_year")}
        connection.commit()
    return set(invoice_years).issubset(imported_years)


def _sync_scope_from_summary(summary: str) -> str | None:
    summary = summary.lower()
    for scope, option in SYNC_SCOPE_OPTIONS.items():
        if option["label"].lower() in summary:
            return scope
    if "outstanding sync complete" in summary or "outstanding invoices only" in summary:
        return "outstanding_only"
    return None


def _completed_sync_covers_scope(user_id: str, invoice_scope: str) -> bool:
    requested_rank = SYNC_SCOPE_RANK.get(invoice_scope, 0)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT summary, current_step
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status = %s
                  AND completed_at IS NOT NULL
                ORDER BY completed_at DESC, created_at DESC
                LIMIT 20
                """,
                ("xero", user_id, "completed"),
            )
            rows = cursor.fetchall()
        connection.commit()

    for row in rows:
        completed_scope = _sync_scope_from_summary(" ".join([row.get("summary") or "", row.get("current_step") or ""]))
        if completed_scope is not None and SYNC_SCOPE_RANK.get(completed_scope, 0) >= requested_rank:
            return True
    return False


def _refresh_customer_totals(cursor, tenant_id: str, updated_at: datetime) -> None:
    cursor.execute(
        """
        WITH invoice_totals AS (
            SELECT invoices.customer_id,
                   COALESCE(SUM(invoices.amount_due), 0) AS gross_total_due,
                   COALESCE(SUM(CASE WHEN invoices.due_date < CURRENT_DATE AND invoices.amount_due > 0 THEN invoices.amount_due ELSE 0 END), 0) AS overdue_amount
            FROM invoices
            JOIN customers AS invoice_customers ON invoice_customers.id = invoices.customer_id
            WHERE invoice_customers.tenant_id = %s
            GROUP BY invoices.customer_id
        ),
        credit_totals AS (
            SELECT customer_credits.customer_id,
                   COALESCE(SUM(customer_credits.remaining_credit), 0) AS credit_balance
            FROM customer_credits
            JOIN customers AS credit_customers ON credit_customers.id = customer_credits.customer_id
            WHERE credit_customers.tenant_id = %s
              AND customer_credits.remaining_credit > 0
            GROUP BY customer_credits.customer_id
        ),
        totals AS (
            SELECT invoice_totals.customer_id,
                   invoice_totals.gross_total_due,
                   invoice_totals.overdue_amount,
                   COALESCE(credit_totals.credit_balance, 0) AS credit_balance,
                   GREATEST(invoice_totals.gross_total_due - COALESCE(credit_totals.credit_balance, 0), 0) AS net_total_due
            FROM invoice_totals
            LEFT JOIN credit_totals ON credit_totals.customer_id = invoice_totals.customer_id
        )
        UPDATE customers
        SET total_due = totals.net_total_due,
            overdue_amount = LEAST(totals.overdue_amount, totals.net_total_due),
            updated_at = %s
        FROM totals
        WHERE customers.id = totals.customer_id
        """,
        (tenant_id, tenant_id, updated_at),
    )


async def _sync_xero_payments(
    connection_row: dict,
    now: datetime,
    modified_since: datetime | None = None,
    start_page: int = 1,
    already_processed: int = 0,
    already_synced: int = 0,
    on_page=None,
    on_retry=None,
    on_store=None,
    on_checkpoint=None,
    on_request=None,
) -> int:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, xero_contact_id FROM customers WHERE tenant_id = %s",
                (connection_row["tenant_id"],),
            )
            customer_lookup = {
                row["xero_contact_id"]: row["id"]
                for row in cursor.fetchall()
                if row.get("xero_contact_id")
            }
            cursor.execute(
                """
                SELECT invoices.id, invoices.xero_invoice_id, invoices.customer_id
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE customers.tenant_id = %s
                """,
                (connection_row["tenant_id"],),
            )
            invoice_lookup = {
                row["xero_invoice_id"]: {"id": row["id"], "customer_id": row["customer_id"]}
                for row in cursor.fetchall()
                if row.get("xero_invoice_id")
            }
        connection.commit()

    synced = max(int(already_synced or 0), 0)
    processed = max(int(already_processed or 0), 0)
    if on_store is not None:
        on_store(processed, processed, synced)

    def store_payment_page(page_number: int, raw_payments: list[dict], total_records: int) -> None:
        nonlocal processed, synced
        if not raw_payments:
            if on_store is not None:
                on_store(processed, total_records, synced)
            return

        page_processed = 0
        page_synced = 0
        with get_connection() as connection:
            with connection.cursor() as cursor:
                for raw_payment in raw_payments:
                    page_processed += 1
                    payment = normalise_payment(raw_payment)
                    if not payment.get("xero_payment_id"):
                        continue
                    if payment.get("invoice_type") and payment.get("invoice_type") != "ACCREC":
                        continue
                    invoice_match = invoice_lookup.get(payment.get("xero_invoice_id"))
                    customer_id = customer_lookup.get(payment.get("xero_contact_id")) or (invoice_match or {}).get("customer_id")
                    if customer_id is None:
                        continue
                    cursor.execute(
                        """
                        INSERT INTO payments (
                            tenant_id, customer_id, invoice_id, xero_payment_id, xero_invoice_id,
                            invoice_number, payment_date, amount, currency_code, reference,
                            status, account_name, raw, synced_at, updated_at
                        )
                        VALUES (
                            %(tenant_id)s, %(customer_id)s, %(invoice_id)s, %(xero_payment_id)s, %(xero_invoice_id)s,
                            %(invoice_number)s, %(payment_date)s, %(amount)s, %(currency_code)s, %(reference)s,
                            %(status)s, %(account_name)s, %(raw_json)s::jsonb, %(synced_at)s, %(updated_at)s
                        )
                        ON CONFLICT (xero_payment_id) DO UPDATE
                        SET customer_id = EXCLUDED.customer_id,
                            invoice_id = EXCLUDED.invoice_id,
                            xero_invoice_id = EXCLUDED.xero_invoice_id,
                            invoice_number = EXCLUDED.invoice_number,
                            payment_date = EXCLUDED.payment_date,
                            amount = EXCLUDED.amount,
                            currency_code = EXCLUDED.currency_code,
                            reference = EXCLUDED.reference,
                            status = EXCLUDED.status,
                            account_name = EXCLUDED.account_name,
                            raw = EXCLUDED.raw,
                            synced_at = EXCLUDED.synced_at,
                            updated_at = EXCLUDED.updated_at
                        """,
                        {
                            **payment,
                            "tenant_id": connection_row["tenant_id"],
                            "customer_id": customer_id,
                            "invoice_id": (invoice_match or {}).get("id"),
                            "raw_json": json.dumps(payment.get("raw") or {}, default=_json_default),
                            "synced_at": now,
                            "updated_at": now,
                        },
                    )
                    page_synced += 1
            connection.commit()

        processed += page_processed
        synced += page_synced
        if on_store is not None:
            on_store(processed, total_records, synced)
        if on_checkpoint is not None:
            on_checkpoint(page_number, processed, synced)

    def pause_for_daily_limit(page_number: int, total_records: int, remaining_calls: int) -> None:
        if on_checkpoint is not None:
            on_checkpoint(page_number, processed, synced)
        if on_store is not None:
            on_store(processed, total_records, synced)

    await fetch_paginated_collection(
        connection_row,
        PAYMENTS_URL,
        "Payments",
        start_page=start_page,
        on_page=on_page,
        on_batch=store_payment_page,
        on_retry=on_retry,
        on_request=on_request,
        modified_since=modified_since,
        collect_records=False,
        initial_records=processed,
        minimum_day_limit_remaining=XERO_DAILY_LIMIT_GUARD_REMAINING,
        on_day_limit_guard=pause_for_daily_limit,
    )
    return synced


def _credit_source_storage_type(source_type: str) -> str:
    return {
        "creditNote": "credit_note",
        "credit_note": "credit_note",
        "credit-note": "credit_note",
        "overpayment": "overpayment",
    }.get(str(source_type or ""), "")


def _credit_source_is_active(source_type: str, source: dict) -> bool:
    status_value = str(source.get("status") or "").upper()
    transaction_type = str(source.get("type") or "").upper()
    if status_value != AUTHORISED_CREDIT_STATUS:
        return False
    if source_type == "credit_note" and transaction_type and transaction_type != "ACCRECCREDIT":
        return False
    if source_type == "overpayment" and transaction_type and "RECEIVE" not in transaction_type:
        return False
    return _money(source.get("remainingCredit")) > 0


def _upsert_customer_credit_source(cursor, tenant_id: str, customer_id: str, source_type: str, source: dict, now: datetime) -> bool:
    storage_type = _credit_source_storage_type(source_type)
    source_id = str(source.get("id") or "").strip()
    if not storage_type or not source_id:
        return False

    if not _credit_source_is_active(storage_type, source):
        cursor.execute(
            """
            DELETE FROM customer_credits
            WHERE tenant_id = %s
              AND source_type = %s
              AND xero_credit_id = %s
            """,
            (tenant_id, storage_type, source_id),
        )
        return False

    cursor.execute(
        """
        INSERT INTO customer_credits (
            tenant_id, customer_id, source_type, xero_credit_id, number, reference,
            status, transaction_type, credit_date, currency_code, total,
            remaining_credit, applied_amount, line_items, allocations, synced_at, updated_at
        )
        VALUES (
            %(tenant_id)s, %(customer_id)s, %(source_type)s, %(xero_credit_id)s, %(number)s, %(reference)s,
            %(status)s, %(transaction_type)s, %(credit_date)s, %(currency_code)s, %(total)s,
            %(remaining_credit)s, %(applied_amount)s, %(line_items_json)s::jsonb, %(allocations_json)s::jsonb, %(synced_at)s, %(updated_at)s
        )
        ON CONFLICT (source_type, xero_credit_id) DO UPDATE
        SET tenant_id = EXCLUDED.tenant_id,
            customer_id = EXCLUDED.customer_id,
            number = EXCLUDED.number,
            reference = EXCLUDED.reference,
            status = EXCLUDED.status,
            transaction_type = EXCLUDED.transaction_type,
            credit_date = EXCLUDED.credit_date,
            currency_code = EXCLUDED.currency_code,
            total = EXCLUDED.total,
            remaining_credit = EXCLUDED.remaining_credit,
            applied_amount = EXCLUDED.applied_amount,
            line_items = EXCLUDED.line_items,
            allocations = EXCLUDED.allocations,
            synced_at = EXCLUDED.synced_at,
            updated_at = EXCLUDED.updated_at
        """,
        {
            "tenant_id": tenant_id,
            "customer_id": customer_id,
            "source_type": storage_type,
            "xero_credit_id": source_id,
            "number": source.get("number") or "",
            "reference": source.get("reference") or "",
            "status": source.get("status") or "",
            "transaction_type": source.get("type") or "",
            "credit_date": _parse_optional_iso_date(source.get("date")),
            "currency_code": source.get("currencyCode") or "GBP",
            "total": _money(source.get("total")),
            "remaining_credit": _money(source.get("remainingCredit")),
            "applied_amount": _money(source.get("appliedAmount")),
            "line_items_json": json.dumps(source.get("lineItems") or [], default=_json_default),
            "allocations_json": json.dumps(source.get("allocations") or [], default=_json_default),
            "synced_at": now,
            "updated_at": now,
        },
    )
    return True


def _replace_customer_credit_sources(cursor, tenant_id: str, customer_id: str, credit_sources: list[dict], now: datetime) -> int:
    cursor.execute(
        """
        DELETE FROM customer_credits
        WHERE tenant_id = %s
          AND customer_id = %s
        """,
        (tenant_id, customer_id),
    )
    stored = 0
    for source in credit_sources:
        stored += int(_upsert_customer_credit_source(cursor, tenant_id, customer_id, source.get("sourceType"), source, now))
    _refresh_customer_totals(cursor, tenant_id, now)
    return stored


async def _sync_xero_customer_credits(
    connection_row: dict,
    now: datetime,
    modified_since: datetime | None = None,
    on_credit_note_page=None,
    on_credit_note_retry=None,
    on_overpayment_page=None,
    on_overpayment_retry=None,
    on_request=None,
) -> int:
    credit_note_where = RECEIVABLE_CREDIT_NOTE_INCREMENTAL_WHERE if modified_since else RECEIVABLE_CREDIT_NOTE_WHERE
    raw_credit_notes = await fetch_paginated_collection(
        connection_row,
        CREDIT_NOTES_URL,
        "CreditNotes",
        params={"where": credit_note_where},
        modified_since=modified_since,
        on_page=on_credit_note_page,
        on_retry=on_credit_note_retry,
        on_request=on_request,
    )
    raw_overpayments = await fetch_paginated_collection(
        connection_row,
        OVERPAYMENTS_URL,
        "Overpayments",
        params=None if modified_since else {"where": f'Status=="{AUTHORISED_CREDIT_STATUS}"'},
        modified_since=modified_since,
        on_page=on_overpayment_page,
        on_retry=on_overpayment_retry,
        on_request=on_request,
    )

    if modified_since is not None and not raw_credit_notes and not raw_overpayments:
        return 0

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, xero_contact_id FROM customers WHERE tenant_id = %s",
                (connection_row["tenant_id"],),
            )
            customer_lookup = {
                str(row["xero_contact_id"]).lower(): row["id"]
                for row in cursor.fetchall()
                if row.get("xero_contact_id")
            }
            if modified_since is None:
                cursor.execute("DELETE FROM customer_credits WHERE tenant_id = %s", (connection_row["tenant_id"],))

            stored = 0
            for raw_credit_note in raw_credit_notes:
                source = _serialize_credit_note_transaction(raw_credit_note)
                customer_id = customer_lookup.get(source.get("contactId"))
                if customer_id is None:
                    continue
                stored += int(_upsert_customer_credit_source(cursor, connection_row["tenant_id"], customer_id, "credit_note", source, now))

            for raw_overpayment in raw_overpayments:
                source = _serialize_overpayment_transaction(raw_overpayment)
                customer_id = customer_lookup.get(source.get("contactId"))
                if customer_id is None:
                    continue
                stored += int(_upsert_customer_credit_source(cursor, connection_row["tenant_id"], customer_id, "overpayment", source, now))

            _refresh_customer_totals(cursor, connection_row["tenant_id"], now)
        connection.commit()
    return stored


async def _sync_xero_paid_invoice_backfill(
    connection_row: dict,
    user: dict,
    now: datetime,
    invoice_years: list[int],
    paid_page_limit: int | None,
    base_contact_count: int,
    base_invoice_count: int,
    start_page: int = 1,
    already_seen: int = 0,
    already_synced: int = 0,
    already_contacts_synced: int = 0,
    on_page=None,
    on_retry=None,
    on_store=None,
    on_checkpoint=None,
    on_request=None,
) -> dict:
    paid_synced = max(int(already_synced or 0), 0)
    paid_contacts_synced = max(int(already_contacts_synced or 0), 0)
    synced_invoices = base_invoice_count + paid_synced

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, xero_contact_id FROM customers WHERE tenant_id = %s",
                (connection_row["tenant_id"],),
            )
            customer_rows = cursor.fetchall()
        connection.commit()

    existing_contact_ids = {
        row["xero_contact_id"]
        for row in customer_rows
        if row.get("xero_contact_id")
    }
    customer_lookup = {
        row["xero_contact_id"]: row["id"]
        for row in customer_rows
        if row.get("xero_contact_id")
    }

    def store_paid_invoice_page(page_number: int, raw_invoices: list[dict], total_records: int) -> None:
        nonlocal paid_synced, paid_contacts_synced, synced_invoices, customer_lookup
        page_contacts_synced = 0
        page_paid_synced = 0

        with get_connection() as connection:
            with connection.cursor() as cursor:
                for raw_contact in _contacts_from_invoices(raw_invoices):
                    contact_id = raw_contact.get("ContactID")
                    if not contact_id or contact_id in existing_contact_ids:
                        continue
                    _upsert_xero_customer(cursor, raw_contact, connection_row["tenant_id"], now)
                    existing_contact_ids.add(contact_id)
                    page_contacts_synced += 1

                if page_contacts_synced:
                    cursor.execute(
                        "SELECT id, xero_contact_id FROM customers WHERE tenant_id = %s",
                        (connection_row["tenant_id"],),
                    )
                    customer_lookup = {
                        row["xero_contact_id"]: row["id"]
                        for row in cursor.fetchall()
                        if row.get("xero_contact_id")
                    }

                for raw_invoice in raw_invoices:
                    invoice = normalise_invoice(raw_invoice)
                    if not invoice["xero_contact_id"]:
                        continue

                    customer_id = customer_lookup.get(invoice["xero_contact_id"])
                    if customer_id is None:
                        continue

                    cursor.execute(
                        """
                        INSERT INTO invoices (
                            customer_id, xero_invoice_id, invoice_number, status, due_date, invoice_date,
                            description, line_items, currency_code, total, amount_due, amount_paid, xero_updated_at, synced_at, updated_at
                        )
                        VALUES (
                            %(customer_id)s, %(xero_invoice_id)s, %(invoice_number)s, %(status)s, %(due_date)s, %(invoice_date)s,
                            %(description)s, %(line_items_json)s::jsonb, %(currency_code)s, %(total)s, %(amount_due)s, %(amount_paid)s, %(xero_updated_at)s, %(synced_at)s, %(updated_at)s
                        )
                        ON CONFLICT (xero_invoice_id) DO UPDATE
                        SET customer_id = EXCLUDED.customer_id,
                            invoice_number = EXCLUDED.invoice_number,
                            status = EXCLUDED.status,
                            due_date = EXCLUDED.due_date,
                            invoice_date = EXCLUDED.invoice_date,
                            description = EXCLUDED.description,
                            line_items = EXCLUDED.line_items,
                            currency_code = EXCLUDED.currency_code,
                            total = EXCLUDED.total,
                            amount_due = EXCLUDED.amount_due,
                            amount_paid = EXCLUDED.amount_paid,
                            xero_updated_at = EXCLUDED.xero_updated_at,
                            synced_at = EXCLUDED.synced_at,
                            updated_at = EXCLUDED.updated_at
                        RETURNING id
                        """,
                        {
                            **invoice,
                            "line_items_json": json.dumps(invoice.get("line_items") or [], default=_json_default),
                            "customer_id": customer_id,
                            "synced_at": now,
                            "updated_at": now,
                        },
                    )
                    stored = cursor.fetchone()
                    synced_invoices += 1
                    page_paid_synced += 1

                    cursor.execute(
                        """
                        INSERT INTO invoice_status_history (invoice_id, status, note, changed_by_user_id)
                        SELECT %s, %s, %s, %s
                        WHERE NOT EXISTS (
                            SELECT 1 FROM invoice_status_history
                            WHERE invoice_id = %s AND status = %s
                        )
                        """,
                        (
                            stored["id"],
                            invoice["status"],
                            "Imported from Xero paid invoice backfill",
                            user["id"],
                            stored["id"],
                            invoice["status"],
                        ),
                    )

                paid_synced += page_paid_synced
                paid_contacts_synced += page_contacts_synced
                _refresh_customer_totals(cursor, connection_row["tenant_id"], now)
            connection.commit()

        if on_store is not None:
            on_store(
                page_number,
                total_records,
                paid_synced,
                paid_contacts_synced,
                synced_invoices,
            )
        if on_checkpoint is not None:
            on_checkpoint(
                page_number,
                total_records,
                paid_synced,
                paid_contacts_synced,
                synced_invoices,
            )

    await fetch_paginated_collection(
        connection_row,
        INVOICES_URL,
        "Invoices",
        params={"where": _with_invoice_year_filter(PAID_INVOICE_WHERE, invoice_years)},
        max_pages=paid_page_limit,
        start_page=start_page,
        on_page=on_page,
        on_batch=store_paid_invoice_page,
        on_retry=on_retry,
        on_request=on_request,
        collect_records=False,
        initial_records=already_seen,
    )

    return {
        "paid_synced": paid_synced,
        "paid_contacts_synced": paid_contacts_synced,
        "synced_invoices": synced_invoices,
        "total_contacts_synced": base_contact_count + paid_contacts_synced,
    }


def record_sync_start_failure(user: dict, exc: Exception) -> None:
    message = _sync_error_message(exc)
    try:
        record_audit_event(
            "sync_run",
            str(user.get("id") or "unknown"),
            "sync.start.failed",
            {"error": message, "detail": _sync_error_payload(exc)},
            user.get("id"),
        )
    except Exception:
        logger.exception("Unable to record sync start failure audit event")


def _mark_stale_sync_runs(user_id: str) -> None:
    now = utcnow()
    stale_before = now - SYNC_STALE_AFTER
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, current_step, summary, customers_synced, invoices_synced,
                       contacts_total, invoices_total, fetched_count, processed_count,
                       heartbeat_at, started_at, created_at
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status IN ('queued', 'running')
                  AND COALESCE(heartbeat_at, started_at, created_at) < %s
                """,
                ("xero", user_id, stale_before),
            )
            stalled_rows = cursor.fetchall()

            if stalled_rows:
                cursor.execute(
                    """
                    UPDATE sync_runs
                    SET status = %s,
                        current_step = %s,
                        summary = %s,
                        error_message = %s,
                        failed_count = GREATEST(failed_count, 1),
                        completed_at = %s
                    WHERE id = ANY(%s)
                    """,
                    (
                        "failed",
                        "Sync timed out",
                        "A previous Xero sync stopped responding.",
                        "The previous Xero sync stopped responding. Start a fresh sync.",
                        now,
                        [row["id"] for row in stalled_rows],
                    ),
                )
        connection.commit()

    for row in stalled_rows or []:
        last_heartbeat = row.get("heartbeat_at") or row.get("started_at") or row.get("created_at")
        elapsed_seconds = None
        if last_heartbeat is not None:
            elapsed_seconds = max(0, int((now - last_heartbeat).total_seconds()))
        try:
            record_audit_event(
                "sync_run",
                str(row["id"]),
                "sync.stalled",
                {
                    "message": (
                        f"Sync marked stale after {elapsed_seconds} seconds without a heartbeat"
                        if elapsed_seconds is not None
                        else "Sync marked stale (no heartbeat timestamp recorded)."
                    ),
                    "last_step": row.get("current_step") or "",
                    "last_summary": row.get("summary") or "",
                    "last_heartbeat_at": _iso(last_heartbeat),
                    "elapsed_seconds_since_heartbeat": elapsed_seconds,
                    "stale_threshold_seconds": int(SYNC_STALE_AFTER.total_seconds()),
                    "customers_synced": int(row.get("customers_synced") or 0),
                    "invoices_synced": int(row.get("invoices_synced") or 0),
                    "contacts_total": int(row.get("contacts_total") or 0),
                    "invoices_total": int(row.get("invoices_total") or 0),
                    "fetched_count": int(row.get("fetched_count") or 0),
                    "processed_count": int(row.get("processed_count") or 0),
                },
                user_id,
            )
        except Exception:
            logger.exception("Unable to record sync stall audit event")


def record_interrupted_sync_runs(signal_name: str = "SIGTERM") -> int:
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, initiated_by_user_id, current_step, summary,
                       customers_synced, invoices_synced, contacts_total, invoices_total,
                       fetched_count, processed_count, heartbeat_at, started_at, created_at
                FROM sync_runs
                WHERE provider = %s
                  AND status IN ('queued', 'running')
                """,
                ("xero",),
            )
            interrupted_rows = cursor.fetchall()

            if interrupted_rows:
                cursor.execute(
                    """
                    UPDATE sync_runs
                    SET status = %s,
                        current_step = %s,
                        summary = %s,
                        error_message = %s,
                        failed_count = GREATEST(failed_count, 1),
                        completed_at = %s
                    WHERE id = ANY(%s)
                    """,
                    (
                        "failed",
                        "Sync interrupted",
                        "Xero sync interrupted before it could complete.",
                        f"Process received {signal_name} while a Xero sync was active.",
                        now,
                        [row["id"] for row in interrupted_rows],
                    ),
                )
        connection.commit()

    for row in interrupted_rows or []:
        user_id = row.get("initiated_by_user_id")
        last_heartbeat = row.get("heartbeat_at") or row.get("started_at") or row.get("created_at")
        elapsed_seconds = None
        if last_heartbeat is not None:
            elapsed_seconds = max(0, int((now - last_heartbeat).total_seconds()))
        try:
            record_audit_event(
                "sync_run",
                str(row["id"]),
                "sync.interrupted",
                {
                    "message": f"Sync interrupted after process received {signal_name}.",
                    "signal": signal_name,
                    "last_step": row.get("current_step") or "",
                    "last_summary": row.get("summary") or "",
                    "last_heartbeat_at": _iso(last_heartbeat),
                    "elapsed_seconds_since_heartbeat": elapsed_seconds,
                    "customers_synced": int(row.get("customers_synced") or 0),
                    "invoices_synced": int(row.get("invoices_synced") or 0),
                    "contacts_total": int(row.get("contacts_total") or 0),
                    "invoices_total": int(row.get("invoices_total") or 0),
                    "fetched_count": int(row.get("fetched_count") or 0),
                    "processed_count": int(row.get("processed_count") or 0),
                    "runtime": runtime_diagnostics_payload(),
                },
                str(user_id) if user_id else None,
            )
        except Exception:
            logger.exception("Unable to record sync interruption audit event")

    return len(interrupted_rows or [])


def _sigterm_name(signum: int) -> str:
    try:
        return signal.Signals(signum).name
    except Exception:
        return f"signal {signum}"


def _record_process_start_event() -> None:
    global _PROCESS_START_EVENT_RECORDED
    if _PROCESS_START_EVENT_RECORDED:
        return
    try:
        record_audit_event(
            "sync_run",
            _PROCESS_BOOT_ID,
            "sync.process.started",
            {
                "message": "Backend process started and sync signal handlers are active.",
                "runtime": runtime_diagnostics_payload(),
            },
            None,
        )
        _PROCESS_START_EVENT_RECORDED = True
    except Exception:
        logger.exception("Unable to record backend process start event")


def _handle_sync_sigterm(signum, frame) -> None:
    signal_name = _sigterm_name(signum)
    try:
        interrupted_count = record_interrupted_sync_runs(signal_name)
        if interrupted_count:
            logger.warning("Marked %s active sync run(s) interrupted after %s", interrupted_count, signal_name)
    except Exception:
        logger.exception("Unable to mark active sync runs interrupted after %s", signal_name)

    previous_handler = _PREVIOUS_SIGTERM_HANDLER
    if callable(previous_handler) and previous_handler is not _handle_sync_sigterm:
        previous_handler(signum, frame)
        return
    if previous_handler == signal.SIG_IGN:
        return
    raise SystemExit(128 + int(signum))


def install_sync_signal_handlers() -> None:
    global _PREVIOUS_SIGTERM_HANDLER, _SYNC_SIGNAL_HANDLERS_INSTALLED
    if _SYNC_SIGNAL_HANDLERS_INSTALLED or not hasattr(signal, "SIGTERM"):
        return
    try:
        _PREVIOUS_SIGTERM_HANDLER = signal.getsignal(signal.SIGTERM)
        signal.signal(signal.SIGTERM, _handle_sync_sigterm)
        _SYNC_SIGNAL_HANDLERS_INSTALLED = True
        _record_process_start_event()
    except ValueError:
        logger.warning("Unable to install sync SIGTERM handler outside the main thread")


def _update_sync_run(sync_run_id: str, **fields) -> dict | None:
    if not fields:
        return None
    fields.setdefault("heartbeat_at", utcnow())

    assignments = ", ".join(f"{field} = %s" for field in fields)
    values = [*fields.values(), sync_run_id]
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                f"""
                UPDATE sync_runs
                SET {assignments}
                WHERE id = %s
                RETURNING *
                """,
                values,
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def request_sync_run(user: dict, sync_options: dict | None = None) -> tuple[dict, bool]:
    sync_options = normalise_sync_options(sync_options)
    connection_row = get_master_xero_connection_for_user(user["id"])
    _mark_stale_sync_runs(user["id"])
    rate_limit = _active_xero_rate_limit(user["id"])
    if rate_limit is not None:
        raise HTTPException(
            status_code=status.HTTP_429_TOO_MANY_REQUESTS,
            detail={
                "message": rate_limit["message"],
                "retry_after_seconds": rate_limit["retry_after_seconds"],
                "rate_limit_until": _iso(rate_limit["rate_limit_until"]),
                "previous_error": rate_limit["previous_error"],
            },
        )

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status IN ('queued', 'running')
                  AND created_at > NOW() - INTERVAL '2 hours'
                ORDER BY created_at DESC
                LIMIT 1
                """,
                ("xero", user["id"]),
            )
            active = cursor.fetchone()
            if active is not None:
                connection.commit()
                return active, False

            cursor.execute(
                """
                INSERT INTO sync_runs (
                    provider,
                    initiated_by_user_id,
                    tenant_id,
                    status,
                    current_step,
                    summary,
                    customers_synced,
                    invoices_synced,
                    fetched_count,
                    processed_count,
                    failed_count,
                    contacts_total,
                    invoices_total,
                    heartbeat_at,
                    created_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING *
                """,
                (
                    "xero",
                    user["id"],
                    connection_row.get("tenant_id"),
                    "queued",
                    "Queued",
                    f"Xero sync queued. {sync_options['summary']}",
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    utcnow(),
                    utcnow(),
                ),
            )
            sync_run = cursor.fetchone()
        connection.commit()

    return sync_run, True


def get_sync_run(user: dict, sync_run_id: str) -> dict:
    _mark_stale_sync_runs(user["id"])
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM sync_runs
                WHERE id = %s
                  AND initiated_by_user_id = %s
                  AND provider = %s
                """,
                (sync_run_id, user["id"], "xero"),
            )
            row = cursor.fetchone()
        connection.commit()

    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Sync run not found.")
    return row


def _sync_run_abort_reason(sync_run_id: str) -> str:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT status, summary, error_message FROM sync_runs WHERE id = %s", (sync_run_id,))
            row = cursor.fetchone() or {}
        connection.commit()
    status_value = str(row.get("status") or "").lower()
    if status_value in ACTIVE_SYNC_STATUSES:
        return ""
    return str(row.get("error_message") or row.get("summary") or "Xero sync stopped.") or "Xero sync stopped."


def cancel_sync_run(user: dict, sync_run_id: str) -> dict:
    sync_run = get_sync_run(user, sync_run_id)
    if str(sync_run.get("status") or "").lower() not in ACTIVE_SYNC_STATUSES:
        return sync_run
    cancelled = _update_sync_run(
        sync_run_id,
        status="failed",
        current_step="Sync cancelled",
        summary="Xero sync was cancelled by user.",
        error_message="Xero sync cancelled by user.",
        failed_count=max(1, int(sync_run.get("failed_count") or 0)),
        completed_at=utcnow(),
    )
    try:
        record_audit_event(
            "sync_run",
            str(sync_run_id),
            "sync.cancelled",
            {"summary": "Xero sync cancelled by user."},
            user["id"],
        )
    except Exception:
        logger.exception("Unable to record sync cancellation audit event")
    return cancelled or sync_run


def serialize_sync_run(sync_run: dict) -> dict:
    progress = 0
    if sync_run.get("status") == "completed":
        progress = 100
    elif sync_run.get("status") == "failed":
        progress = 100
    elif sync_run.get("status") == "queued":
        progress = 4
    else:
        contacts_total = int(sync_run.get("contacts_total") or 0)
        invoices_total = int(sync_run.get("invoices_total") or 0)
        customers_synced = int(sync_run.get("customers_synced") or 0)
        invoices_synced = int(sync_run.get("invoices_synced") or 0)
        if contacts_total or invoices_total:
            total = max(contacts_total + invoices_total, 1)
            progress = min(95, max(8, round(((customers_synced + invoices_synced) / total) * 100)))
        else:
            progress = 12

    return {
        "id": str(sync_run["id"]),
        "tenantId": sync_run.get("tenant_id") or "",
        "status": sync_run.get("status") or "",
        "currentStep": sync_run.get("current_step") or "",
        "summary": sync_run.get("summary") or "",
        "errorMessage": sync_run.get("error_message") or "",
        "customersSynced": int(sync_run.get("customers_synced") or 0),
        "invoicesSynced": int(sync_run.get("invoices_synced") or 0),
        "contactsTotal": int(sync_run.get("contacts_total") or 0),
        "invoicesTotal": int(sync_run.get("invoices_total") or 0),
        "progress": progress,
        "createdAt": _iso(sync_run.get("created_at")) or "",
        "startedAt": _iso(sync_run.get("started_at")) or "",
        "heartbeatAt": _iso(sync_run.get("heartbeat_at")) or "",
        "completedAt": _iso(sync_run.get("completed_at")) or "",
        "rateLimitUntil": _iso(sync_run.get("rate_limit_until")) or "",
        "retryAfterSeconds": int(sync_run.get("retry_after_seconds") or 0),
        "isActive": sync_run.get("status") in ACTIVE_SYNC_STATUSES,
    }


OPERATION_LABELS = {
    "late_payment_charges": "Late payment charges",
    "bad_debt_write_offs": "Bad debt write-offs",
}


def _operation_payload(invoice_ids: list[str], options: dict | None = None) -> dict:
    return {
        "invoiceIds": [str(invoice_id) for invoice_id in invoice_ids],
        "options": options or {},
    }


def request_operation_run(user: dict, operation_type: str, invoice_ids: list[str], options: dict | None = None) -> dict:
    if operation_type not in OPERATION_LABELS:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Unsupported operation type.")
    clean_invoice_ids = [str(invoice_id).strip() for invoice_id in invoice_ids if str(invoice_id).strip()]
    if not clean_invoice_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one invoice.")

    label = OPERATION_LABELS[operation_type]
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO operation_runs (
                    operation_type, initiated_by_user_id, status, total_count,
                    processed_count, succeeded_count, failed_count, current_step,
                    summary, payload, created_at, heartbeat_at
                )
                VALUES (%s, %s, %s, %s, 0, 0, 0, %s, %s, %s::jsonb, %s, %s)
                RETURNING *
                """,
                (
                    operation_type,
                    user["id"],
                    "queued",
                    len(clean_invoice_ids),
                    "Queued",
                    f"{label} queued for {len(clean_invoice_ids)} invoice{'s' if len(clean_invoice_ids) != 1 else ''}.",
                    json.dumps(_operation_payload(clean_invoice_ids, options), default=_json_default),
                    now,
                    now,
                ),
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def get_operation_run(user: dict, operation_run_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM operation_runs
                WHERE id = %s
                  AND initiated_by_user_id = %s
                """,
                (operation_run_id, user["id"]),
            )
            row = cursor.fetchone()
        connection.commit()
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Operation run not found.")
    return row


def _operation_run_abort_reason(operation_run_id: str) -> str:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT status, summary, error_message FROM operation_runs WHERE id = %s", (operation_run_id,))
            row = cursor.fetchone() or {}
        connection.commit()
    status_value = str(row.get("status") or "").lower()
    if status_value in ACTIVE_SYNC_STATUSES:
        return ""
    return str(row.get("error_message") or row.get("summary") or "Operation stopped.") or "Operation stopped."


def cancel_operation_run(user: dict, operation_run_id: str) -> dict:
    operation_run = get_operation_run(user, operation_run_id)
    if str(operation_run.get("status") or "").lower() not in ACTIVE_SYNC_STATUSES:
        return operation_run
    label = OPERATION_LABELS.get(operation_run.get("operation_type"), "Xero operation")
    cancelled = _update_operation_run(
        operation_run_id,
        status="failed",
        current_step=f"{label} cancelled",
        summary=f"{label} was cancelled by user.",
        error_message=f"{label} cancelled by user.",
        failed_count=max(1, int(operation_run.get("failed_count") or 0)),
        completed_at=utcnow(),
    )
    try:
        record_audit_event(
            "operation_run",
            str(operation_run_id),
            "operation.cancelled",
            {"summary": f"{label} cancelled by user."},
            user["id"],
        )
    except Exception:
        logger.exception("Unable to record operation cancellation audit event")
    return cancelled


def serialize_operation_run(operation_run: dict) -> dict:
    total = int(operation_run.get("total_count") or 0)
    processed = int(operation_run.get("processed_count") or 0)
    if operation_run.get("status") in ("completed", "failed"):
        progress = 100
    elif operation_run.get("status") == "queued":
        progress = 4
    elif total:
        progress = min(98, max(8, round((processed / total) * 100)))
    else:
        progress = 12
    return {
        "id": str(operation_run["id"]),
        "operationType": operation_run.get("operation_type") or "",
        "label": OPERATION_LABELS.get(operation_run.get("operation_type"), "Xero operation"),
        "status": operation_run.get("status") or "",
        "currentStep": operation_run.get("current_step") or "",
        "summary": operation_run.get("summary") or "",
        "errorMessage": operation_run.get("error_message") or "",
        "totalCount": total,
        "processedCount": processed,
        "succeededCount": int(operation_run.get("succeeded_count") or 0),
        "failedCount": int(operation_run.get("failed_count") or 0),
        "progress": progress,
        "result": operation_run.get("result") or {},
        "createdAt": _iso(operation_run.get("created_at")) or "",
        "startedAt": _iso(operation_run.get("started_at")) or "",
        "heartbeatAt": _iso(operation_run.get("heartbeat_at")) or "",
        "completedAt": _iso(operation_run.get("completed_at")) or "",
        "isActive": operation_run.get("status") in ("queued", "running"),
    }


def _update_operation_run(operation_run_id: str, **fields) -> dict:
    if not fields:
        raise ValueError("No operation fields supplied.")
    fields.setdefault("heartbeat_at", utcnow())
    assignments = ", ".join(f"{key} = %s::jsonb" if key in {"payload", "result"} else f"{key} = %s" for key in fields)
    values = list(fields.values())
    values.append(operation_run_id)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                f"""
                UPDATE operation_runs
                SET {assignments}
                WHERE id = %s
                RETURNING *
                """,
                values,
            )
            row = cursor.fetchone()
        connection.commit()
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Operation run not found.")
    return row


def _invoice_operation_label(invoice_id: str) -> str:
    try:
        invoice_uuid = UUID(str(invoice_id))
    except ValueError:
        return str(invoice_id)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT invoices.invoice_number, customers.name AS customer_name
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE invoices.id = %s
                """,
                (invoice_uuid,),
            )
            row = cursor.fetchone()
        connection.commit()
    if not row:
        return str(invoice_id)
    invoice_number = row.get("invoice_number") or str(invoice_id)
    customer_name = row.get("customer_name") or "client"
    return f"{customer_name} · {invoice_number}"


async def run_invoice_operation_job(
    user: dict,
    operation_run_id: str,
    operation_type: str,
    invoice_ids: list[str],
    options: dict | None = None,
) -> None:
    label = OPERATION_LABELS.get(operation_type, "Xero operation")
    created: list[dict] = []
    skipped: list[dict] = []
    failed: list[dict] = []
    processed_count = 0
    succeeded_count = 0
    failed_count = 0
    clean_invoice_ids = [str(invoice_id).strip() for invoice_id in invoice_ids if str(invoice_id).strip()]
    _update_operation_run(
        operation_run_id,
        status="running",
        started_at=utcnow(),
        current_step=f"Starting {label.lower()}",
        summary=f"Starting {label.lower()} for {len(clean_invoice_ids)} invoice{'s' if len(clean_invoice_ids) != 1 else ''}.",
    )
    charge_selections = (options or {}).get("chargeSelections") or []
    charge_selection_by_id = {
        str(item.get("invoiceId") or "").strip(): item
        for item in charge_selections
        if str(item.get("invoiceId") or "").strip()
    }

    def ensure_operation_active() -> None:
        abort_reason = _operation_run_abort_reason(operation_run_id)
        if abort_reason:
            raise BackgroundRunCancelledError(abort_reason)

    try:
        for invoice_id in clean_invoice_ids:
            ensure_operation_active()
            invoice_label = _invoice_operation_label(invoice_id)
            action_text = "Raising late payment charge" if operation_type == "late_payment_charges" else "Raising and allocating bad debt credit note"
            _update_operation_run(
                operation_run_id,
                current_step=f"{action_text}: {invoice_label}",
                summary=f"Processed {processed_count} of {len(clean_invoice_ids)}. Working on {invoice_label}.",
            )
            try:
                if operation_type == "late_payment_charges":
                    selection = charge_selection_by_id.get(invoice_id) or {"invoiceId": invoice_id}
                    result = await create_late_payment_charges(user, [invoice_id], [selection])
                elif operation_type == "bad_debt_write_offs":
                    result = await create_bad_debt_write_offs(user, [invoice_id])
                else:
                    raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Unsupported operation type.")
                created_items = result.get("created") or []
                skipped_items = result.get("skipped") or []
                created.extend(created_items)
                skipped.extend(skipped_items)
                if created_items:
                    succeeded_count += len(created_items)
                if skipped_items:
                    failed_count += len(skipped_items)
            except Exception as exc:
                error = _sync_error_message(exc)
                failed_count += 1
                failed.append({"invoiceId": invoice_id, "reason": error})
                logger.exception("Unable to run %s for invoice %s", operation_type, invoice_id)

            processed_count += 1
            _update_operation_run(
                operation_run_id,
                processed_count=processed_count,
                succeeded_count=succeeded_count,
                failed_count=failed_count,
                current_step=f"{label}: {processed_count} of {len(clean_invoice_ids)} processed",
                summary=(
                    f"Processed {processed_count} of {len(clean_invoice_ids)} invoice"
                    f"{'' if len(clean_invoice_ids) == 1 else 's'}; "
                    f"{succeeded_count} succeeded, {failed_count} skipped or failed."
                ),
            )

        ensure_operation_active()
        result_payload = {"created": created, "skipped": [*skipped, *failed]}
        _update_operation_run(
            operation_run_id,
            status="completed",
            completed_at=utcnow(),
            current_step=f"{label} complete",
            summary=(
                f"{label} complete: {succeeded_count} succeeded, "
                f"{failed_count} skipped or failed."
            ),
            result=json.dumps(result_payload, default=_json_default),
        )
    except BackgroundRunCancelledError:
        return
    except Exception as exc:
        _update_operation_run(
            operation_run_id,
            status="failed",
            completed_at=utcnow(),
            current_step=f"{label} failed",
            summary=f"{label} stopped before completion.",
            error_message=_sync_error_message(exc),
            result=json.dumps({"created": created, "skipped": [*skipped, *failed]}, default=_json_default),
        )
        logger.exception("Operation run %s failed", operation_run_id)


PENDING_XERO_ACTION_STATUSES = ("pending", "processing", "failed")


def _pending_xero_action_invoice_ids(invoice_ids) -> list[str]:
    try:
        return list(dict.fromkeys(str(UUID(str(invoice_id).strip())) for invoice_id in invoice_ids if str(invoice_id).strip()))
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invalid invoice id in pending Xero action.") from exc


def _normalise_pending_xero_action_payload(action_type: str, invoice_ids: list[str], options: dict | None = None) -> tuple[list[str], dict]:
    if action_type not in OPERATION_LABELS:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Unsupported pending Xero action.")
    clean_invoice_ids = _pending_xero_action_invoice_ids(invoice_ids)
    if not clean_invoice_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one invoice.")

    options = dict(options or {})
    if action_type == "late_payment_charges":
        charge_lookup = _late_payment_charge_selection_lookup(
            clean_invoice_ids,
            options.get("chargeSelections") or options.get("charges") or [],
        )
        options["chargeSelections"] = [
            {"invoiceId": invoice_id, "baseAmount": float(charge_lookup[invoice_id])}
            for invoice_id in clean_invoice_ids
        ]
    else:
        options = {}
    return clean_invoice_ids, _operation_payload(clean_invoice_ids, options)


def _pending_xero_action_tenant_id(user: dict) -> str:
    try:
        return str(get_master_xero_connection_for_user(user["id"]).get("tenant_id") or "")
    except HTTPException:
        return ""


def _assert_invoices_belong_to_tenant(invoice_ids: list[str], tenant_id: str, detail: str) -> None:
    safe_tenant_id = str(tenant_id or "").strip()
    if not safe_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Master Xero tenant is not connected.")
    safe_invoice_ids: list[UUID] = []
    try:
        safe_invoice_ids = [UUID(str(invoice_id).strip()) for invoice_id in invoice_ids if str(invoice_id).strip()]
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invalid invoice id.") from exc
    if not safe_invoice_ids:
        return
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT COUNT(*) AS count
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE invoices.id = ANY(%s)
                  AND customers.tenant_id = %s
                """,
                (safe_invoice_ids, safe_tenant_id),
            )
            row = cursor.fetchone() or {}
        connection.commit()
    if int(row.get("count") or 0) != len(safe_invoice_ids):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=detail)


def queue_pending_xero_action(user: dict, action_type: str, invoice_ids: list[str], options: dict | None = None) -> dict:
    clean_invoice_ids, payload = _normalise_pending_xero_action_payload(action_type, invoice_ids, options)
    tenant_id = _pending_xero_action_tenant_id(user)
    _assert_invoices_belong_to_tenant(
        clean_invoice_ids,
        tenant_id,
        "Pending Xero actions for LPC/Bad Debt can only be queued for invoices in the master Jaccountancy tenant.",
    )
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO xero_pending_actions (
                    tenant_id, action_type, status, invoice_ids, payload,
                    created_by_user_id, created_at, updated_at
                )
                VALUES (%s, %s, 'pending', %s::jsonb, %s::jsonb, %s, %s, %s)
                RETURNING *
                """,
                (
                    tenant_id,
                    action_type,
                    json.dumps(clean_invoice_ids),
                    json.dumps(payload, default=_json_default),
                    user["id"],
                    now,
                    now,
                ),
            )
            row = cursor.fetchone()
        connection.commit()
    record_audit_event(
        "xero_pending_action",
        str(row["id"]),
        "xero_pending_action.queued",
        {"action_type": action_type, "invoice_ids": clean_invoice_ids, "payload": payload},
        user["id"],
    )
    return pending_xero_actions_payload(user)


def _pending_xero_action_amount(action: dict, invoice_lookup: dict[str, dict]) -> float:
    invoice_ids = [str(invoice_id) for invoice_id in action.get("invoice_ids") or []]
    payload = action.get("payload") or {}
    options = payload.get("options") or {}
    if action.get("action_type") == "late_payment_charges":
        try:
            charge_lookup = _late_payment_charge_selection_lookup(invoice_ids, options.get("chargeSelections") or [])
        except HTTPException:
            charge_lookup = {invoice_id: DEFAULT_LATE_PAYMENT_CHARGE_BASE_AMOUNT for invoice_id in invoice_ids}
        return float(sum(_late_payment_charge_gross_amount(charge_lookup[invoice_id]) for invoice_id in invoice_ids if invoice_id in charge_lookup))
    return float(sum(_money(invoice_lookup.get(invoice_id, {}).get("amount_due")) for invoice_id in invoice_ids))


def _serialize_pending_xero_action(action: dict, invoice_lookup: dict[str, dict]) -> dict:
    invoice_ids = [str(invoice_id) for invoice_id in action.get("invoice_ids") or []]
    invoices = []
    for invoice_id in invoice_ids:
        invoice = invoice_lookup.get(invoice_id)
        if not invoice:
            invoices.append({"id": invoice_id, "label": invoice_id, "amountDue": 0})
            continue
        invoices.append(
            {
                "id": invoice_id,
                "invoiceNumber": invoice.get("invoice_number") or "",
                "customerName": invoice.get("customer_name") or "Client",
                "label": f"{invoice.get('customer_name') or 'Client'} · {invoice.get('invoice_number') or invoice_id}",
                "amountDue": _float(invoice.get("amount_due")),
            }
        )
    return {
        "id": str(action["id"]),
        "actionType": action.get("action_type") or "",
        "label": OPERATION_LABELS.get(action.get("action_type"), "Xero change"),
        "status": action.get("status") or "pending",
        "invoiceCount": len(invoice_ids),
        "amount": _pending_xero_action_amount(action, invoice_lookup),
        "invoices": invoices,
        "payload": action.get("payload") or {},
        "result": action.get("result") or {},
        "errorMessage": action.get("error_message") or "",
        "createdAt": _iso(action.get("created_at")) or "",
        "updatedAt": _iso(action.get("updated_at")) or "",
        "processedAt": _iso(action.get("processed_at")) or "",
    }


def pending_xero_actions_payload(user: dict) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM xero_pending_actions
                WHERE created_by_user_id = %s
                  AND (status <> 'completed' OR processed_at > NOW() - INTERVAL '24 hours')
                ORDER BY
                    CASE status
                        WHEN 'processing' THEN 0
                        WHEN 'pending' THEN 1
                        WHEN 'failed' THEN 2
                        ELSE 3
                    END,
                    created_at DESC
                LIMIT 100
                """,
                (user["id"],),
            )
            actions = cursor.fetchall()
            invoice_ids = sorted({
                str(invoice_id)
                for action in actions
                for invoice_id in (action.get("invoice_ids") or [])
            })
            invoice_lookup = {}
            if invoice_ids:
                cursor.execute(
                    """
                    SELECT invoices.id,
                           invoices.invoice_number,
                           invoices.amount_due,
                           customers.name AS customer_name
                    FROM invoices
                    JOIN customers ON customers.id = invoices.customer_id
                    WHERE invoices.id = ANY(%s)
                    """,
                    ([UUID(invoice_id) for invoice_id in invoice_ids],),
                )
                invoice_lookup = {str(row["id"]): row for row in cursor.fetchall()}
        connection.commit()

    serialized = [_serialize_pending_xero_action(action, invoice_lookup) for action in actions]
    pending = [action for action in serialized if action["status"] == "pending"]
    failed = [action for action in serialized if action["status"] == "failed"]
    processing = [action for action in serialized if action["status"] == "processing"]
    return {
        "pendingActions": {
            "summary": {
                "pendingCount": len(pending),
                "failedCount": len(failed),
                "processingCount": len(processing),
                "pendingInvoiceCount": sum(action["invoiceCount"] for action in pending),
                "pendingAmount": round(sum(action["amount"] for action in pending), 2),
            },
            "actions": serialized,
        }
    }


async def process_pending_xero_actions(user: dict) -> dict:
    rate_limit = active_xero_rate_limit_for_user(user)
    if rate_limit:
        raise HTTPException(
            status_code=status.HTTP_429_TOO_MANY_REQUESTS,
            detail={
                "message": rate_limit.get("message") or "Xero daily limit is still active.",
                "rate_limit_until": _iso(rate_limit.get("rate_limit_until")) or "",
                "retry_after_seconds": int(rate_limit.get("retry_after_seconds") or 0),
            },
        )

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM xero_pending_actions
                WHERE created_by_user_id = %s
                  AND status = 'pending'
                ORDER BY created_at ASC
                LIMIT 50
                """,
                (user["id"],),
            )
            actions = cursor.fetchall()
        connection.commit()

    processed = []
    failed = []
    for action in actions:
        now = utcnow()
        action_id = str(action["id"])
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE xero_pending_actions
                    SET status = 'processing',
                        error_message = NULL,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    (now, action["id"]),
                )
            connection.commit()

        payload = action.get("payload") or {}
        invoice_ids = payload.get("invoiceIds") or action.get("invoice_ids") or []
        options = payload.get("options") or {}
        try:
            if action.get("action_type") == "late_payment_charges":
                result = await create_late_payment_charges(user, invoice_ids, options.get("chargeSelections") or [])
            elif action.get("action_type") == "bad_debt_write_offs":
                result = await create_bad_debt_write_offs(user, invoice_ids)
            else:
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Unsupported pending Xero action.")
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE xero_pending_actions
                        SET status = 'completed',
                            result = %s::jsonb,
                            error_message = NULL,
                            updated_at = %s,
                            processed_at = %s
                        WHERE id = %s
                        """,
                        (json.dumps(result, default=_json_default), utcnow(), utcnow(), action["id"]),
                    )
                connection.commit()
            processed.append({"id": action_id, "actionType": action.get("action_type"), **result})
        except Exception as exc:
            error = _sync_error_message(exc)
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE xero_pending_actions
                        SET status = 'failed',
                            error_message = %s,
                            result = %s::jsonb,
                            updated_at = %s
                        WHERE id = %s
                        """,
                        (error, json.dumps({"error": error, "detail": _sync_error_payload(exc)}, default=_json_default), utcnow(), action["id"]),
                    )
                connection.commit()
            failed.append({"id": action_id, "actionType": action.get("action_type"), "error": error})
            logger.exception("Unable to process pending Xero action %s", action_id)

    payload = pending_xero_actions_payload(user)
    payload["result"] = {
        "processedCount": len(processed),
        "failedCount": len(failed),
        "processed": processed,
        "failed": failed,
    }
    return payload


def sync_run_has_working_data(sync_run: dict) -> bool:
    customers_synced = int(sync_run.get("customers_synced") or 0)
    invoices_synced = int(sync_run.get("invoices_synced") or 0)
    processed_count = int(sync_run.get("processed_count") or 0)
    imported_invoice_rows_are_ready = (
        invoices_synced > 0
        and processed_count >= customers_synced + invoices_synced
    )
    return (
        sync_run.get("status") in (*ACTIVE_SYNC_STATUSES, "failed", "completed")
        and invoices_synced > 0
        and (
            sync_run.get("current_step") in WORKING_DATA_STEPS
            or imported_invoice_rows_are_ready
        )
    )


def active_sync_run_for_user(user: dict | None) -> dict | None:
    if not user or not user.get("id"):
        return None

    _mark_stale_sync_runs(user["id"])
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND status IN ('queued', 'running')
                ORDER BY COALESCE(heartbeat_at, started_at, created_at) DESC, created_at DESC
                LIMIT 1
                """,
                ("xero", user["id"]),
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def _developer_log_cutoff_for_user(user_id: str) -> datetime | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT created_at
                FROM audit_events
                WHERE user_id = %s
                  AND event_type = %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (user_id, DEVELOPER_LOG_CLEAR_EVENT_TYPE),
            )
            row = cursor.fetchone()
        connection.commit()
    return row.get("created_at") if row else None


def clear_developer_logs(user: dict) -> dict:
    previous_cutoff = _developer_log_cutoff_for_user(user["id"])
    cleared_at = utcnow()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT COUNT(*) AS count
                FROM audit_events
                WHERE (user_id = %s OR user_id IS NULL)
                  AND (
                      entity_type = 'sync_run'
                      OR entity_type = 'ignition_sync_run'
                      OR entity_type = 'xero_connection'
                      OR event_type LIKE 'sync.%%'
                      OR event_type LIKE 'xero.%%'
                      OR event_type LIKE 'ignition.%%'
                  )
                  AND (%s::timestamptz IS NULL OR created_at > %s::timestamptz)
                """,
                (user["id"], previous_cutoff, previous_cutoff),
            )
            audit_count = int((cursor.fetchone() or {}).get("count") or 0)
            cursor.execute(
                """
                SELECT COUNT(*) AS count
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND (%s::timestamptz IS NULL OR created_at > %s::timestamptz)
                """,
                ("xero", user["id"], previous_cutoff, previous_cutoff),
            )
            sync_run_count = int((cursor.fetchone() or {}).get("count") or 0)
            cursor.execute(
                """
                SELECT COUNT(*) AS count
                FROM ignition_sync_runs
                WHERE user_id = %s
                  AND (%s::timestamptz IS NULL OR created_at > %s::timestamptz)
                """,
                (user["id"], previous_cutoff, previous_cutoff),
            )
            ignition_sync_run_count = int((cursor.fetchone() or {}).get("count") or 0)
            cursor.execute(
                """
                INSERT INTO audit_events (entity_type, entity_id, event_type, payload, user_id, created_at)
                VALUES (%s, %s, %s, %s::jsonb, %s, %s)
                """,
                (
                    "developer_log",
                    str(user["id"]),
                    DEVELOPER_LOG_CLEAR_EVENT_TYPE,
                    json.dumps(
                        {
                            "previous_cutoff": _iso(previous_cutoff),
                            "cleared_at": _iso(cleared_at),
                            "audit_events": audit_count,
                            "sync_runs": sync_run_count,
                            "ignition_sync_runs": ignition_sync_run_count,
                        },
                        default=_json_default,
                    ),
                    user["id"],
                    cleared_at,
                ),
            )
        connection.commit()

    logs_cleared = audit_count + sync_run_count + ignition_sync_run_count
    return {
        "clearedAt": _iso(cleared_at),
        "logsCleared": logs_cleared,
        "breakdown": {
            "auditEvents": audit_count,
            "syncRuns": sync_run_count,
            "ignitionSyncRuns": ignition_sync_run_count,
        },
    }


def list_developer_logs(user: dict, limit: int = 120) -> list[dict]:
    bounded_limit = max(1, min(int(limit or 120), 300))
    cutoff = _developer_log_cutoff_for_user(user["id"])
    logs: list[dict] = []
    try:
        logs.extend(_list_audit_developer_logs(user, bounded_limit, cutoff))
    except Exception as exc:
        logger.exception("Unable to load audit developer logs")
        logs.append(_developer_log_error_entry("developer.log.query.failed", exc))
    try:
        logs.extend(_list_sync_run_developer_logs(user, bounded_limit, cutoff))
    except Exception as exc:
        logger.exception("Unable to load sync run developer logs")
        logs.append(_developer_log_error_entry("developer.log.sync_runs.failed", exc))
    try:
        logs.extend(_list_ignition_sync_run_developer_logs(user, bounded_limit, cutoff))
    except Exception as exc:
        logger.exception("Unable to load Ignition sync run developer logs")
        logs.append(_developer_log_error_entry("developer.log.ignition_sync_runs.failed", exc))

    logs.sort(key=lambda entry: entry.get("createdAt") or "", reverse=True)
    return logs[:bounded_limit]


def _list_audit_developer_logs(user: dict, limit: int, cutoff: datetime | None = None) -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT audit_events.*
                FROM audit_events
                WHERE (audit_events.user_id = %s OR audit_events.user_id IS NULL)
                  AND (
                      audit_events.entity_type = 'sync_run'
                      OR audit_events.entity_type = 'ignition_sync_run'
                      OR audit_events.entity_type = 'xero_connection'
                      OR audit_events.event_type LIKE 'sync.%%'
                      OR audit_events.event_type LIKE 'xero.%%'
                      OR audit_events.event_type LIKE 'ignition.%%'
                  )
                  AND (%s::timestamptz IS NULL OR audit_events.created_at > %s::timestamptz)
                ORDER BY audit_events.created_at DESC
                LIMIT %s
                """,
                (user["id"], cutoff, cutoff, limit),
            )
            rows = cursor.fetchall()
        connection.commit()

    return [
        {
            "id": str(row["id"]),
            "level": "error" if str(row.get("event_type") or "").endswith("failed") else "info",
            "source": "audit",
            "eventType": row.get("event_type") or "",
            "message": _developer_log_message(row),
            "payload": _safe_json(row.get("payload") or {}),
            "createdAt": _iso(row.get("created_at")) or "",
            "syncRunId": row.get("entity_id") if row.get("entity_type") in ("sync_run", "ignition_sync_run") else "",
            "syncStatus": "",
        }
        for row in rows
    ]


def _list_sync_run_developer_logs(user: dict, limit: int, cutoff: datetime | None = None) -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM sync_runs
                WHERE provider = %s
                  AND initiated_by_user_id = %s
                  AND (%s::timestamptz IS NULL OR created_at > %s::timestamptz)
                ORDER BY created_at DESC
                LIMIT %s
                """,
                ("xero", user["id"], cutoff, cutoff, limit),
            )
            rows = cursor.fetchall()
        connection.commit()

    logs = []
    for row in rows:
        status_value = row.get("status") or ""
        logs.append(
            {
                "id": str(row["id"]),
                "level": "error" if status_value == "failed" else "info",
                "source": "sync_runs",
                "eventType": f"sync.{status_value or 'unknown'}",
                "message": row.get("error_message") or row.get("summary") or row.get("current_step") or "Sync run",
                "payload": _safe_json(serialize_sync_run(row)),
                "createdAt": _iso(row.get("created_at")) or "",
                "syncRunId": str(row["id"]),
                "syncStatus": status_value,
            }
        )
    return logs


def _list_ignition_sync_run_developer_logs(user: dict, limit: int, cutoff: datetime | None = None) -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM ignition_sync_runs
                WHERE user_id = %s
                  AND (%s::timestamptz IS NULL OR created_at > %s::timestamptz)
                ORDER BY created_at DESC
                LIMIT %s
                """,
                (user["id"], cutoff, cutoff, limit),
            )
            rows = cursor.fetchall()
        connection.commit()

    logs = []
    for row in rows:
        status_value = row.get("status") or ""
        logs.append(
            {
                "id": str(row["id"]),
                "level": "error" if status_value == "failed" else "info",
                "source": "ignition_sync_runs",
                "eventType": f"ignition.sync.{status_value or 'unknown'}",
                "message": row.get("error_message") or row.get("summary") or row.get("current_step") or "Ignition sync run",
                "payload": _safe_json(serialize_ignition_sync_run(row)),
                "createdAt": _iso(row.get("created_at")) or "",
                "syncRunId": str(row["id"]),
                "syncStatus": status_value,
            }
        )
    return logs


def _developer_log_error_entry(event_type: str, exc: Exception) -> dict:
    return {
        "id": event_type,
        "level": "error",
        "source": "backend",
        "eventType": event_type,
        "message": str(exc) or exc.__class__.__name__,
        "payload": {"type": exc.__class__.__name__},
        "createdAt": utcnow().isoformat(),
        "syncRunId": "",
        "syncStatus": "",
    }


def _developer_log_message(row: dict) -> str:
    payload = row.get("payload") or {}
    if isinstance(payload, dict):
        return str(
            payload.get("summary")
            or payload.get("error")
            or payload.get("message")
            or row.get("event_type")
            or "Log event"
        )
    return str(payload or row.get("event_type") or "Log event")


def run_sync_job(user: dict, sync_run_id: str, sync_options: dict | None = None) -> None:
    try:
        asyncio.run(run_sync(user, sync_run_id, sync_options))
    except Exception as exc:
        logger.exception("Background Xero sync failed")
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute("SELECT status FROM sync_runs WHERE id = %s", (sync_run_id,))
                row = cursor.fetchone()
            connection.commit()
        if row and row.get("status") in ACTIVE_SYNC_STATUSES:
            message = _sync_error_message(exc)
            _update_sync_run(
                sync_run_id,
                status="failed",
                current_step="Sync failed",
                summary="Xero sync failed before it could complete.",
                error_message=message,
                failed_count=1,
                completed_at=utcnow(),
            )


def _contacts_from_invoices(invoices: list[dict]) -> list[dict]:
    contacts_by_id: dict[str, dict] = {}
    for invoice in invoices:
        contact = invoice.get("Contact") or {}
        contact_id = contact.get("ContactID")
        if not contact_id:
            continue
        existing = contacts_by_id.setdefault(contact_id, {"ContactID": contact_id})
        for key, value in contact.items():
            if value not in (None, "", [], {}) and not existing.get(key):
                existing[key] = value
    return list(contacts_by_id.values())


def _contact_receivable_amount(contact: dict, key: str) -> Decimal:
    receivable = ((contact.get("Balances") or {}).get("AccountsReceivable") or {})
    try:
        return Decimal(str(receivable.get(key) if receivable.get(key) is not None else 0))
    except Exception:
        return Decimal("0")


def _is_customer_contact(contact: dict, invoice_contact_ids: set[str]) -> bool:
    contact_id = contact.get("ContactID")
    if contact_id in invoice_contact_ids:
        return True
    if contact.get("IsCustomer") is True:
        return True
    return (
        _contact_receivable_amount(contact, "Outstanding") != 0
        or _contact_receivable_amount(contact, "Overdue") != 0
    )


def _customer_contacts_from_xero(raw_contacts: list[dict], invoices: list[dict]) -> list[dict]:
    invoice_contacts = _contacts_from_invoices(invoices)
    invoice_contact_ids = {
        contact.get("ContactID")
        for contact in invoice_contacts
        if contact.get("ContactID")
    }
    contacts_by_id = {
        contact["ContactID"]: contact
        for contact in raw_contacts
        if contact.get("ContactID") and _is_customer_contact(contact, invoice_contact_ids)
    }
    for contact in invoice_contacts:
        contact_id = contact.get("ContactID")
        if contact_id:
            contacts_by_id.setdefault(contact_id, contact)
    return list(contacts_by_id.values())


def _upsert_xero_customer(cursor, raw_contact: dict, tenant_id: str, synced_at: datetime) -> None:
    contact = normalise_contact(raw_contact, tenant_id)
    cursor.execute(
        """
        INSERT INTO customers (
            tenant_id, xero_contact_id, name, email, phone, account_number,
            primary_person, contact_people, addresses, total_due, overdue_amount, last_sync_at, updated_at
        )
        VALUES (
            %(tenant_id)s, %(xero_contact_id)s, %(name)s, %(email)s, %(phone)s, %(account_number)s,
            %(primary_person)s, %(contact_people_json)s::jsonb, %(addresses_json)s::jsonb, %(total_due)s, %(overdue_amount)s, %(last_sync_at)s, %(updated_at)s
        )
        ON CONFLICT (xero_contact_id) DO UPDATE
        SET tenant_id = EXCLUDED.tenant_id,
            name = EXCLUDED.name,
            email = EXCLUDED.email,
            phone = EXCLUDED.phone,
            account_number = EXCLUDED.account_number,
            primary_person = EXCLUDED.primary_person,
            contact_people = EXCLUDED.contact_people,
            addresses = EXCLUDED.addresses,
            total_due = EXCLUDED.total_due,
            overdue_amount = EXCLUDED.overdue_amount,
            last_sync_at = EXCLUDED.last_sync_at,
            updated_at = EXCLUDED.updated_at
        """,
        {
            **contact,
            "contact_people_json": json.dumps(contact.get("contact_people") or [], default=_json_default),
            "addresses_json": json.dumps(contact.get("addresses") or [], default=_json_default),
            "last_sync_at": synced_at,
            "updated_at": synced_at,
        },
    )


def _make_xero_request_tracer(sync_run_id: str, user_id: str, label: str):
    def trace(info: dict) -> None:
        try:
            payload = {"label": label, **(info or {})}
            outcome = str(payload.get("outcome") or "ok")
            event_type = {
                "ok": "sync.xero_request.ok",
                "timeout": "sync.xero_request.timeout",
                "rate_limited": "sync.xero_request.rate_limited",
                "daily_limit_guard": "sync.xero_request.daily_limit_guard",
                "error": "sync.xero_request.error",
            }.get(outcome, "sync.xero_request")
            record_audit_event(
                "sync_run",
                str(sync_run_id),
                event_type,
                payload,
                user_id,
            )
        except Exception:
            logger.exception("Unable to record Xero request audit event")
    return trace


async def run_sync(user: dict, sync_run_id: str, sync_options: dict | None = None) -> dict:
    sync_options = normalise_sync_options(sync_options)
    connection_row = get_master_xero_connection_for_user(user["id"])
    sync_signature = _sync_options_signature(sync_options)
    now = utcnow()
    completed_modified_since = _incremental_modified_since(user["id"])
    local_modified_since = _local_cache_modified_since(connection_row["tenant_id"])
    candidate_modified_since = completed_modified_since or local_modified_since
    local_cache_state = _local_cache_sync_state(connection_row["tenant_id"])
    has_local_invoice_cache = local_cache_state["invoices"] > 0
    scope_already_imported = (
        _completed_sync_covers_scope(user["id"], sync_options["invoice_scope"])
        if candidate_modified_since is not None
        else False
    )
    if has_local_invoice_cache and candidate_modified_since is not None:
        scope_already_imported = True
    years_are_already_imported = (
        True
        if not sync_options["invoice_years"] and (scope_already_imported or has_local_invoice_cache)
        else (
            _local_invoice_years_cover(connection_row["tenant_id"], sync_options["invoice_years"])
            if candidate_modified_since is not None
            else False
        )
    )
    modified_since = candidate_modified_since if scope_already_imported and years_are_already_imported else None
    is_incremental_sync = modified_since is not None
    needs_paid_backfill = False if is_incremental_sync else sync_options["paid_page_limit"] != 0 and not scope_already_imported
    resume_state = None if is_incremental_sync else _latest_resumable_sync_state(user["id"], connection_row["tenant_id"], sync_signature)
    resume_checkpoints = (resume_state or {}).get("checkpoints") or {}
    resume_source_run = (resume_state or {}).get("sync_run") or {}
    resume_started_at = resume_source_run.get("started_at") or resume_source_run.get("created_at")
    contact_fetch_label = "changed customer records" if is_incremental_sync else "customer records"
    invoice_fetch_label = "changed invoices" if is_incremental_sync else "outstanding invoices"
    contact_fetch_step = f"Fetching {contact_fetch_label} from Xero"
    invoice_fetch_step = f"Fetching {invoice_fetch_label} from Xero"
    invoice_where = _with_invoice_year_filter(
        ACCREC_INVOICE_WHERE if is_incremental_sync else OUTSTANDING_INVOICE_WHERE,
        sync_options["invoice_years"],
    )
    if is_incremental_sync:
        source = "last completed sync" if completed_modified_since is not None else "local cached ledger"
        sync_mode_summary = f"Incremental sync from {modified_since.isoformat()} using {source}."
    elif candidate_modified_since is not None:
        sync_mode_summary = "Full sync for a newly selected import scope or invoice year range."
    else:
        sync_mode_summary = "First full sync for the selected scope."
    if resume_state is not None:
        sync_mode_summary = f"Resuming interrupted sync {resume_source_run.get('id')}. {sync_mode_summary}"
    _update_sync_run(
        sync_run_id,
        tenant_id=connection_row["tenant_id"],
        status="running",
        current_step="Starting Xero sync",
        summary=f"Connecting to Xero. {sync_mode_summary}",
        started_at=resume_started_at or now,
        error_message=None,
    )
    if resume_state is not None:
        record_audit_event(
            "sync_run",
            str(sync_run_id),
            "sync.resumed",
            {
                "source_sync_run_id": str(resume_source_run.get("id") or ""),
                "source_started_at": _iso(resume_started_at),
                "phases": sorted(resume_checkpoints.keys()),
            },
            user["id"],
        )

    def ensure_sync_active() -> None:
        abort_reason = _sync_run_abort_reason(sync_run_id)
        if abort_reason:
            raise BackgroundRunCancelledError(abort_reason)

    try:
        ensure_sync_active()
        def rate_limit_progress(label: str):
            def progress(page: int, total_records: int, delay_seconds: int, retry_number: int) -> None:
                ensure_sync_active()
                _update_sync_run(
                    sync_run_id,
                    current_step="Waiting for Xero rate limit",
                    summary=(
                        f"Xero rate-limited {label} page {page}. Retrying in {delay_seconds} seconds "
                        f"({retry_number} of {XERO_RATE_LIMIT_RETRIES}). Fetched {total_records} records so far."
                    ),
                )

            return progress

        def contact_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step=contact_fetch_step,
                summary=f"Fetched {total_records} {contact_fetch_label} from Xero.",
                contacts_total=total_records,
            )

        def outstanding_invoice_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step=invoice_fetch_step,
                summary=f"Fetched {total_records} {invoice_fetch_label} from Xero.",
                invoices_synced=total_records,
                invoices_total=total_records,
            )

        def paid_invoice_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step="Fetching paid invoices from Xero",
                summary=f"Fetched {total_records} paid invoices from Xero.",
                invoices_total=len(outstanding_invoices) + total_records,
            )

        def payment_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step="Fetching payments from Xero",
                summary=f"Fetched {total_records} Xero payments.",
            )

        def payment_store_progress(processed_records: int, total_records: int, stored_records: int) -> None:
            _update_sync_run(
                sync_run_id,
                current_step="Importing payments from Xero",
                summary=(
                    f"Processed {processed_records} Xero payments so far; "
                    f"stored {stored_records} matching customer payments."
                ),
                fetched_count=len(contacts) + len(outstanding_invoices) + total_records,
                processed_count=len(contacts) + synced_invoices + processed_records,
            )

        def credit_note_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step="Fetching credit notes from Xero",
                summary=f"Fetched {total_records} Xero credit notes.",
            )

        def overpayment_progress(_, total_records: int, __) -> None:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step="Fetching overpayments from Xero",
                summary=f"Fetched {total_records} Xero overpayments.",
            )

        async def sync_payments_step() -> int:
            payment_checkpoint = resume_checkpoints.get(SYNC_PHASE_PAYMENTS)
            if _checkpoint_completed(resume_checkpoints, SYNC_PHASE_PAYMENTS):
                payments_synced = int(payment_checkpoint.get("records_stored") or 0)
                _upsert_sync_checkpoint(
                    sync_run_id,
                    user["id"],
                    connection_row["tenant_id"],
                    sync_signature,
                    SYNC_PHASE_PAYMENTS,
                    "completed",
                    page_number=int(payment_checkpoint.get("page_number") or 0),
                    records_seen=int(payment_checkpoint.get("records_seen") or 0),
                    records_stored=payments_synced,
                    payload={**(payment_checkpoint.get("payload") or {}), "resumed_from": str(resume_source_run.get("id") or "")},
                )
                _update_sync_run(
                    sync_run_id,
                    current_step="Payments imported from Xero",
                    summary=f"Reused {payments_synced} Xero payments from the interrupted sync. Checking customer credits.",
                )
                return payments_synced

            if not is_incremental_sync:
                _upsert_sync_checkpoint(
                    sync_run_id,
                    user["id"],
                    connection_row["tenant_id"],
                    sync_signature,
                    SYNC_PHASE_PAYMENTS,
                    "completed",
                    records_seen=0,
                    records_stored=0,
                    payload={
                        "skipped_full_payment_history": True,
                        "reason": "Full payment history is intentionally not pulled during full syncs to protect Xero daily API limits.",
                    },
                )
                _update_sync_run(
                    sync_run_id,
                    current_step="Payment history deferred",
                    summary=(
                        "Skipped full Xero payment-history import to protect the daily Xero API limit. "
                        "Future syncs will use changed-since payment imports from the cached ledger."
                    ),
                )
                return 0

            start_page = int((payment_checkpoint or {}).get("page_number") or 0) + 1
            already_processed = int((payment_checkpoint or {}).get("records_seen") or 0)
            already_synced = int((payment_checkpoint or {}).get("records_stored") or 0)
            _update_sync_run(
                sync_run_id,
                current_step="Fetching payments from Xero",
                summary=(
                    f"Resuming payments from Xero page {start_page}."
                    if payment_checkpoint
                    else "Pulling payments made against Xero invoices."
                ),
            )
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_PAYMENTS,
                "running",
                page_number=max(start_page - 1, 0),
                records_seen=already_processed,
                records_stored=already_synced,
                payload={"resumed_from": str(resume_source_run.get("id") or "")} if payment_checkpoint else {},
            )
            try:
                last_payment_page = max(start_page - 1, int((payment_checkpoint or {}).get("page_number") or 0))
                last_payment_seen = already_processed

                def payment_checkpoint_progress(page_number: int, processed_records: int, stored_records: int) -> None:
                    nonlocal last_payment_page, last_payment_seen
                    last_payment_page = page_number
                    last_payment_seen = processed_records
                    _upsert_sync_checkpoint(
                        sync_run_id,
                        user["id"],
                        connection_row["tenant_id"],
                        sync_signature,
                        SYNC_PHASE_PAYMENTS,
                        "running",
                        page_number=page_number,
                        records_seen=processed_records,
                        records_stored=stored_records,
                        payload={"resumed_from": str(resume_source_run.get("id") or "")} if payment_checkpoint else {},
                    )

                payments_synced = await _sync_xero_payments(
                    connection_row,
                    utcnow(),
                    modified_since=modified_since if is_incremental_sync else None,
                    start_page=start_page,
                    already_processed=already_processed,
                    already_synced=already_synced,
                    on_page=payment_progress,
                    on_retry=rate_limit_progress("payments"),
                    on_store=payment_store_progress,
                    on_checkpoint=payment_checkpoint_progress,
                    on_request=_make_xero_request_tracer(sync_run_id, user["id"], "payments"),
                )
                _upsert_sync_checkpoint(
                    sync_run_id,
                    user["id"],
                    connection_row["tenant_id"],
                    sync_signature,
                    SYNC_PHASE_PAYMENTS,
                    "completed",
                    page_number=last_payment_page,
                    records_seen=last_payment_seen,
                    records_stored=payments_synced,
                    payload={"resumed_from": str(resume_source_run.get("id") or "")} if payment_checkpoint else {},
                )
                _update_sync_run(
                    sync_run_id,
                    current_step="Payments imported from Xero",
                    summary=f"Stored {payments_synced} Xero payments. Checking customer credits.",
                )
                return payments_synced
            except Exception as exc:
                logger.exception("Unable to sync Xero payments")
                record_audit_event(
                    "sync_run",
                    str(sync_run_id),
                    "sync.payments.failed",
                    {"error": _sync_error_message(exc), "detail": _sync_error_payload(exc)},
                    user["id"],
                )
                return 0

        async def sync_credit_sources_step() -> int:
            credit_checkpoint = resume_checkpoints.get(SYNC_PHASE_CREDITS)
            if _checkpoint_completed(resume_checkpoints, SYNC_PHASE_CREDITS):
                credit_sources_synced = int(credit_checkpoint.get("records_stored") or 0)
                _upsert_sync_checkpoint(
                    sync_run_id,
                    user["id"],
                    connection_row["tenant_id"],
                    sync_signature,
                    SYNC_PHASE_CREDITS,
                    "completed",
                    records_seen=int(credit_checkpoint.get("records_seen") or 0),
                    records_stored=credit_sources_synced,
                    payload={**(credit_checkpoint.get("payload") or {}), "resumed_from": str(resume_source_run.get("id") or "")},
                )
                _update_sync_run(
                    sync_run_id,
                    current_step="Customer credits imported from Xero",
                    summary=f"Reused {credit_sources_synced} customer credits from the interrupted sync.",
                )
                return credit_sources_synced

            _update_sync_run(
                sync_run_id,
                current_step="Fetching customer credits from Xero",
                summary="Pulling credit notes and overpayments that reduce debtor balances.",
            )
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_CREDITS,
                "running",
            )
            credit_sources_synced = await _sync_xero_customer_credits(
                connection_row,
                utcnow(),
                modified_since=modified_since if is_incremental_sync else None,
                on_credit_note_page=credit_note_progress,
                on_credit_note_retry=rate_limit_progress("credit notes"),
                on_overpayment_page=overpayment_progress,
                on_overpayment_retry=rate_limit_progress("overpayments"),
                on_request=_make_xero_request_tracer(sync_run_id, user["id"], "credit_sources"),
            )
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_CREDITS,
                "completed",
                records_seen=credit_sources_synced,
                records_stored=credit_sources_synced,
            )
            return credit_sources_synced

        outstanding_checkpoint = resume_checkpoints.get(SYNC_PHASE_OUTSTANDING)
        reuse_outstanding_checkpoint = _checkpoint_completed(resume_checkpoints, SYNC_PHASE_OUTSTANDING)
        if reuse_outstanding_checkpoint:
            local_counts = _local_resume_counts(connection_row["tenant_id"], sync_options["invoice_years"])
            checkpoint_contacts = _checkpoint_payload_count(outstanding_checkpoint, "contacts_count", local_counts["customers"])
            checkpoint_outstanding = _checkpoint_payload_count(outstanding_checkpoint, "outstanding_count", local_counts["outstanding_invoices"])
            if local_counts["customers"] < checkpoint_contacts or local_counts["outstanding_invoices"] < checkpoint_outstanding:
                reuse_outstanding_checkpoint = False
                resume_checkpoints.pop(SYNC_PHASE_OUTSTANDING, None)
                record_audit_event(
                    "sync_run",
                    str(sync_run_id),
                    "sync.checkpoint.invalidated",
                    {
                        "phase": SYNC_PHASE_OUTSTANDING,
                        "reason": "Completed checkpoint had no matching saved ledger rows.",
                        "checkpoint_customers": checkpoint_contacts,
                        "checkpoint_outstanding_invoices": checkpoint_outstanding,
                        "stored_customers": local_counts["customers"],
                        "stored_outstanding_invoices": local_counts["outstanding_invoices"],
                    },
                    user["id"],
                )

        if reuse_outstanding_checkpoint:
            local_counts = _local_resume_counts(connection_row["tenant_id"], sync_options["invoice_years"])
            imported_contacts = _checkpoint_payload_count(outstanding_checkpoint, "contacts_count", local_counts["customers"])
            outstanding_synced = _checkpoint_payload_count(outstanding_checkpoint, "outstanding_count", local_counts["outstanding_invoices"])
            synced_invoices = _checkpoint_payload_count(outstanding_checkpoint, "synced_invoices", outstanding_synced)
            contacts = [{}] * imported_contacts
            outstanding_invoices = [{}] * outstanding_synced
            ready_step = "Finalising incremental sync" if is_incremental_sync and not needs_paid_backfill else OUTSTANDING_READY_STEP
            ready_summary = (
                f"Reused {imported_contacts} customers and {outstanding_synced} outstanding invoices from interrupted sync."
            )
            outstanding_ready = _update_sync_run(
                sync_run_id,
                status="running",
                current_step=ready_step,
                customers_synced=imported_contacts,
                invoices_synced=synced_invoices,
                fetched_count=imported_contacts + outstanding_synced,
                processed_count=imported_contacts + synced_invoices,
                failed_count=0,
                contacts_total=imported_contacts,
                invoices_total=outstanding_synced,
                summary=ready_summary,
                completed_at=None,
            )
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_OUTSTANDING,
                "completed",
                records_seen=imported_contacts + outstanding_synced,
                records_stored=imported_contacts + outstanding_synced,
                payload={
                    "contacts_count": imported_contacts,
                    "outstanding_count": outstanding_synced,
                    "synced_invoices": synced_invoices,
                    "invoice_years": sync_options["invoice_years"],
                    "resumed_from": str(resume_source_run.get("id") or ""),
                },
            )
        else:
            ensure_sync_active()
            _update_sync_run(
                sync_run_id,
                current_step=contact_fetch_step,
                summary=f"Fetching {contact_fetch_label} from Xero.",
            )
            raw_contacts: list[dict] = []
            contact_fetch_summary = ""
            try:
                raw_contacts = await fetch_paginated_collection(
                    connection_row,
                    CONTACTS_URL,
                    "Contacts",
                    on_page=contact_progress,
                    on_retry=rate_limit_progress(contact_fetch_label),
                    on_request=_make_xero_request_tracer(sync_run_id, user["id"], "contacts"),
                    modified_since=modified_since if is_incremental_sync else None,
                )
                contact_fetch_summary = f"Fetched {len(raw_contacts)} {contact_fetch_label}."
            except HTTPException as exc:
                retry_after_seconds = _xero_rate_limit_retry_seconds(exc)
                if retry_after_seconds is None:
                    raise
                contact_fetch_summary = (
                    f"Xero Contacts is rate-limited for about {_format_wait_seconds(retry_after_seconds)}. "
                    "Continuing with customer details embedded in invoices."
                )
                record_audit_event(
                    "sync_run",
                    str(sync_run_id),
                    "sync.contacts.rate_limited",
                    {
                        "summary": contact_fetch_summary,
                        "retry_after_seconds": retry_after_seconds,
                        "detail": _sync_error_payload(exc),
                    },
                    user["id"],
                )
            _update_sync_run(
                sync_run_id,
                current_step=invoice_fetch_step,
                summary=f"{contact_fetch_summary} Fetching {invoice_fetch_label}.",
                contacts_total=len(raw_contacts),
            )
            outstanding_invoices = await fetch_paginated_collection(
                connection_row,
                INVOICES_URL,
                "Invoices",
                params={"where": invoice_where},
                on_page=outstanding_invoice_progress,
                on_retry=rate_limit_progress(invoice_fetch_label),
                on_request=_make_xero_request_tracer(sync_run_id, user["id"], "outstanding_invoices"),
                modified_since=modified_since,
            )
            contacts = _customer_contacts_from_xero(raw_contacts, outstanding_invoices)
            _update_sync_run(
                sync_run_id,
                current_step=f"Importing {invoice_fetch_label}",
                summary=(
                    f"Fetched {len(outstanding_invoices)} {invoice_fetch_label}. "
                    f"Prepared {len(contacts)} customer records from Xero contacts and invoice contacts."
                ),
                contacts_total=len(contacts),
                invoices_total=len(outstanding_invoices),
                customers_synced=0,
                invoices_synced=0,
                fetched_count=len(contacts) + len(outstanding_invoices),
                processed_count=0,
                failed_count=0,
            )

            with get_connection() as connection:
                with connection.cursor() as cursor:
                    imported_contacts = 0

                    for raw_contact in contacts:
                        ensure_sync_active()
                        _upsert_xero_customer(cursor, raw_contact, connection_row["tenant_id"], now)
                        imported_contacts += 1
                        if imported_contacts % 100 == 0:
                            _update_sync_run(
                                sync_run_id,
                                current_step="Importing contacts",
                                summary=f"Imported {imported_contacts} of {len(contacts)} contacts.",
                                customers_synced=imported_contacts,
                                processed_count=imported_contacts,
                            )

                    cursor.execute(
                        "SELECT id, xero_contact_id FROM customers WHERE tenant_id = %s",
                        (connection_row["tenant_id"],),
                    )
                    customer_lookup = {
                        row["xero_contact_id"]: row["id"]
                        for row in cursor.fetchall()
                    }

                    customer_totals: dict[str, dict[str, Decimal]] = {}
                    synced_invoices = 0
                    _update_sync_run(
                        sync_run_id,
                        current_step=f"Importing {invoice_fetch_label}",
                        summary=f"Imported {imported_contacts} {contact_fetch_label}. Importing {invoice_fetch_label}.",
                        customers_synced=imported_contacts,
                        invoices_synced=0,
                        processed_count=imported_contacts,
                    )

                    def import_invoice_batch(raw_invoices: list[dict], phase_label: str, update_customer_totals: bool) -> int:
                        nonlocal synced_invoices
                        imported_batch = 0
                        for raw_invoice in raw_invoices:
                            ensure_sync_active()
                            invoice = normalise_invoice(raw_invoice)
                            if not invoice["xero_contact_id"]:
                                continue

                            customer_id = customer_lookup.get(invoice["xero_contact_id"])
                            if customer_id is None:
                                continue

                            cursor.execute(
                                """
                                INSERT INTO invoices (
                                    customer_id, xero_invoice_id, invoice_number, status, due_date, invoice_date,
                                    description, line_items, currency_code, total, amount_due, amount_paid, xero_updated_at, synced_at, updated_at
                                )
                                VALUES (
                                    %(customer_id)s, %(xero_invoice_id)s, %(invoice_number)s, %(status)s, %(due_date)s, %(invoice_date)s,
                                    %(description)s, %(line_items_json)s::jsonb, %(currency_code)s, %(total)s, %(amount_due)s, %(amount_paid)s, %(xero_updated_at)s, %(synced_at)s, %(updated_at)s
                                )
                                ON CONFLICT (xero_invoice_id) DO UPDATE
                                SET customer_id = EXCLUDED.customer_id,
                                    invoice_number = EXCLUDED.invoice_number,
                                    status = EXCLUDED.status,
                                    due_date = EXCLUDED.due_date,
                                    invoice_date = EXCLUDED.invoice_date,
                                    description = EXCLUDED.description,
                                    line_items = EXCLUDED.line_items,
                                    currency_code = EXCLUDED.currency_code,
                                    total = EXCLUDED.total,
                                    amount_due = EXCLUDED.amount_due,
                                    amount_paid = EXCLUDED.amount_paid,
                                    xero_updated_at = EXCLUDED.xero_updated_at,
                                    synced_at = EXCLUDED.synced_at,
                                    updated_at = EXCLUDED.updated_at
                                RETURNING id, control_status
                                """,
                                {
                                    **invoice,
                                    "line_items_json": json.dumps(invoice.get("line_items") or [], default=_json_default),
                                    "customer_id": customer_id,
                                    "synced_at": now,
                                    "updated_at": now,
                                },
                            )
                            stored = cursor.fetchone()
                            synced_invoices += 1
                            imported_batch += 1

                            cursor.execute(
                                """
                                INSERT INTO invoice_status_history (invoice_id, status, note, changed_by_user_id)
                                SELECT %s, %s, %s, %s
                                WHERE NOT EXISTS (
                                    SELECT 1 FROM invoice_status_history
                                    WHERE invoice_id = %s AND status = %s
                                )
                                """,
                                (
                                    stored["id"],
                                    invoice["status"],
                                    "Imported from Xero sync",
                                    user["id"],
                                    stored["id"],
                                    invoice["status"],
                                ),
                            )

                            if update_customer_totals:
                                totals = customer_totals.setdefault(
                                    customer_id,
                                    {"total_due": Decimal("0"), "overdue_amount": Decimal("0")},
                                )
                                amount_due = Decimal(str(invoice["amount_due"]))
                                totals["total_due"] += amount_due
                                if invoice["due_date"] and invoice["due_date"] < now.date() and amount_due > 0:
                                    totals["overdue_amount"] += amount_due

                            if synced_invoices % 100 == 0:
                                _update_sync_run(
                                    sync_run_id,
                                    current_step=f"Importing {phase_label} invoices",
                                    summary=f"Imported {synced_invoices} invoices from Xero.",
                                    customers_synced=imported_contacts,
                                    invoices_synced=synced_invoices,
                                    processed_count=imported_contacts + synced_invoices,
                                )
                        return imported_batch

                    outstanding_synced = import_invoice_batch(outstanding_invoices, invoice_fetch_label, True)

                    for customer_id, totals in customer_totals.items():
                        cursor.execute(
                            """
                            UPDATE customers
                            SET total_due = %s,
                                overdue_amount = %s,
                                updated_at = %s
                            WHERE id = %s
                            """,
                            (totals["total_due"], totals["overdue_amount"], now, customer_id),
                        )

                    _refresh_customer_totals(cursor, connection_row["tenant_id"], now)
                    ready_step = "Finalising incremental sync" if is_incremental_sync and not needs_paid_backfill else OUTSTANDING_READY_STEP
                    if is_incremental_sync and needs_paid_backfill:
                        ready_summary = (
                            f"Incremental changes ready: synced {imported_contacts} changed contacts and "
                            f"{outstanding_synced} changed invoices. Backfilling {sync_options['label'].lower()}."
                        )
                    elif is_incremental_sync:
                        ready_summary = (
                            f"Incremental changes ready: synced {imported_contacts} changed contacts and "
                            f"{outstanding_synced} changed invoices."
                        )
                    else:
                        ready_summary = (
                            f"Outstanding invoices ready: synced {outstanding_synced} outstanding invoices. "
                            "Backfilling paid invoices."
                        )
                    cursor.execute(
                        """
                        UPDATE sync_runs
                        SET status = %s,
                            current_step = %s,
                            customers_synced = %s,
                            invoices_synced = %s,
                            fetched_count = %s,
                            processed_count = %s,
                            failed_count = %s,
                            contacts_total = %s,
                            invoices_total = %s,
                            summary = %s,
                            completed_at = %s
                        WHERE id = %s
                        RETURNING *
                        """,
                        (
                            "running",
                            ready_step,
                            len(contacts),
                            synced_invoices,
                            len(contacts) + len(outstanding_invoices),
                            len(contacts) + synced_invoices,
                            0,
                            len(contacts),
                            len(outstanding_invoices),
                            ready_summary,
                            None,
                            sync_run_id,
                        ),
                    )
                    outstanding_ready = cursor.fetchone()
                connection.commit()

            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_OUTSTANDING,
                "completed",
                records_seen=len(contacts) + len(outstanding_invoices),
                records_stored=len(contacts) + outstanding_synced,
                payload={
                    "contacts_count": len(contacts),
                    "outstanding_count": outstanding_synced,
                    "synced_invoices": synced_invoices,
                    "invoice_years": sync_options["invoice_years"],
                },
            )

        record_audit_event(
            "sync_run",
            str(outstanding_ready["id"]),
            "sync.incremental_ready" if is_incremental_sync else "sync.outstanding_ready",
            {"summary": outstanding_ready["summary"]},
            user["id"],
        )
        ensure_sync_active()
        payments_synced = await sync_payments_step()
        ensure_sync_active()
        credit_sources_synced = await sync_credit_sources_step()

        if is_incremental_sync and not needs_paid_backfill:
            ensure_sync_active()
            completed = _update_sync_run(
                sync_run_id,
                status="completed",
                current_step="Incremental sync complete",
                summary=(
                    f"Incremental sync complete: refreshed changes since {modified_since.isoformat()}. "
                    f"Synced {imported_contacts} changed contacts and {outstanding_synced} changed invoices. "
                    f"Pulled through {payments_synced} payments and {credit_sources_synced} customer credits. Scope: {sync_options['label']}."
                ),
                customers_synced=len(contacts),
                invoices_synced=synced_invoices,
                fetched_count=len(contacts) + len(outstanding_invoices) + payments_synced + credit_sources_synced,
                processed_count=len(contacts) + synced_invoices + payments_synced + credit_sources_synced,
                failed_count=0,
                contacts_total=len(contacts),
                invoices_total=len(outstanding_invoices),
                completed_at=utcnow(),
            )
            record_audit_event("sync_run", str(completed["id"]), "sync.completed", {"summary": completed["summary"]}, user["id"])
            return completed

        paid_page_limit = sync_options["paid_page_limit"]
        if paid_page_limit == 0:
            completed = _update_sync_run(
                sync_run_id,
                status="completed",
                current_step="Outstanding sync complete",
                summary=(
                    f"Synced {len(contacts)} customers and {outstanding_synced} outstanding invoices. "
                    f"Pulled through {payments_synced} payments and {credit_sources_synced} customer credits. Paid invoice history was left for a later staged sync."
                ),
                customers_synced=len(contacts),
                invoices_synced=synced_invoices,
                fetched_count=len(contacts) + len(outstanding_invoices) + payments_synced + credit_sources_synced,
                processed_count=len(contacts) + synced_invoices + payments_synced + credit_sources_synced,
                failed_count=0,
                contacts_total=len(contacts),
                invoices_total=len(outstanding_invoices),
                completed_at=utcnow(),
            )
            record_audit_event("sync_run", str(completed["id"]), "sync.completed", {"summary": completed["summary"]}, user["id"])
            return completed

        paid_checkpoint = resume_checkpoints.get(SYNC_PHASE_PAID_INVOICES)
        if _checkpoint_completed(resume_checkpoints, SYNC_PHASE_PAID_INVOICES):
            local_counts = _local_resume_counts(connection_row["tenant_id"], sync_options["invoice_years"])
            checkpoint_paid = int((paid_checkpoint or {}).get("records_stored") or 0)
            if local_counts["paid_invoices"] < checkpoint_paid:
                resume_checkpoints.pop(SYNC_PHASE_PAID_INVOICES, None)
                paid_checkpoint = None
                record_audit_event(
                    "sync_run",
                    str(sync_run_id),
                    "sync.checkpoint.invalidated",
                    {
                        "phase": SYNC_PHASE_PAID_INVOICES,
                        "reason": "Completed paid-invoice checkpoint had no matching saved invoice rows.",
                        "checkpoint_paid_invoices": checkpoint_paid,
                        "stored_paid_invoices": local_counts["paid_invoices"],
                    },
                    user["id"],
                )
        paid_synced = 0
        paid_contacts_synced = 0
        paid_records_seen = 0
        if _checkpoint_completed(resume_checkpoints, SYNC_PHASE_PAID_INVOICES):
            paid_synced = int(paid_checkpoint.get("records_stored") or 0)
            paid_records_seen = int(paid_checkpoint.get("records_seen") or paid_synced)
            paid_contacts_synced = _checkpoint_payload_count(paid_checkpoint, "paid_contacts_synced", 0)
            synced_invoices += paid_synced
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_PAID_INVOICES,
                "completed",
                page_number=int(paid_checkpoint.get("page_number") or 0),
                records_seen=paid_records_seen,
                records_stored=paid_synced,
                payload={**(paid_checkpoint.get("payload") or {}), "resumed_from": str(resume_source_run.get("id") or "")},
            )
            _update_sync_run(
                sync_run_id,
                current_step="Paid invoices backfilled",
                summary=f"Reused {paid_synced} paid invoices from the interrupted sync.",
                invoices_synced=synced_invoices,
            )
        else:
            ensure_sync_active()
            start_page = int((paid_checkpoint or {}).get("page_number") or 0) + 1
            already_seen = int((paid_checkpoint or {}).get("records_seen") or 0)
            already_synced = int((paid_checkpoint or {}).get("records_stored") or 0)
            already_paid_contacts = _checkpoint_payload_count(paid_checkpoint, "paid_contacts_synced", 0)
            _update_sync_run(
                sync_run_id,
                current_step="Fetching paid invoices from Xero",
                summary=(
                    f"Resuming paid invoice backfill from Xero page {start_page}."
                    if paid_checkpoint
                    else (
                        f"Changed invoices are ready. Backfilling {sync_options['label'].lower()}."
                        if is_incremental_sync
                        else f"Outstanding invoices are ready. {sync_options['summary']}"
                    )
                ),
            )
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_PAID_INVOICES,
                "running",
                page_number=max(start_page - 1, 0),
                records_seen=already_seen,
                records_stored=already_synced,
                payload={
                    "paid_contacts_synced": already_paid_contacts,
                    "resumed_from": str(resume_source_run.get("id") or "") if paid_checkpoint else "",
                },
            )
            last_paid_page = max(start_page - 1, int((paid_checkpoint or {}).get("page_number") or 0))
            last_paid_seen = already_seen

            def paid_store_progress(
                page_number: int,
                total_records: int,
                stored_records: int,
                contact_records: int,
                invoice_records: int,
            ) -> None:
                ensure_sync_active()
                _update_sync_run(
                    sync_run_id,
                    current_step="Backfilling paid invoices",
                    summary=f"Backfilled {stored_records} of {total_records} paid invoices.",
                    customers_synced=len(contacts) + contact_records,
                    contacts_total=len(contacts) + contact_records,
                    invoices_synced=invoice_records,
                    invoices_total=len(outstanding_invoices) + total_records,
                    processed_count=len(contacts) + contact_records + invoice_records,
                )

            def paid_checkpoint_progress(
                page_number: int,
                total_records: int,
                stored_records: int,
                contact_records: int,
                invoice_records: int,
            ) -> None:
                nonlocal last_paid_page, last_paid_seen
                ensure_sync_active()
                last_paid_page = page_number
                last_paid_seen = total_records
                _upsert_sync_checkpoint(
                    sync_run_id,
                    user["id"],
                    connection_row["tenant_id"],
                    sync_signature,
                    SYNC_PHASE_PAID_INVOICES,
                    "running",
                    page_number=page_number,
                    records_seen=total_records,
                    records_stored=stored_records,
                    payload={
                        "paid_contacts_synced": contact_records,
                        "synced_invoices": invoice_records,
                        "resumed_from": str(resume_source_run.get("id") or "") if paid_checkpoint else "",
                    },
                )

            paid_result = await _sync_xero_paid_invoice_backfill(
                connection_row,
                user,
                utcnow(),
                sync_options["invoice_years"],
                paid_page_limit,
                base_contact_count=len(contacts),
                base_invoice_count=synced_invoices,
                start_page=start_page,
                already_seen=already_seen,
                already_synced=already_synced,
                already_contacts_synced=already_paid_contacts,
                on_page=paid_invoice_progress,
                on_retry=rate_limit_progress("paid invoices"),
                on_store=paid_store_progress,
                on_checkpoint=paid_checkpoint_progress,
                on_request=_make_xero_request_tracer(sync_run_id, user["id"], "paid_invoices"),
            )
            paid_synced = int(paid_result["paid_synced"])
            paid_contacts_synced = int(paid_result["paid_contacts_synced"])
            synced_invoices = int(paid_result["synced_invoices"])
            paid_records_seen = last_paid_seen
            _upsert_sync_checkpoint(
                sync_run_id,
                user["id"],
                connection_row["tenant_id"],
                sync_signature,
                SYNC_PHASE_PAID_INVOICES,
                "completed",
                page_number=last_paid_page,
                records_seen=paid_records_seen,
                records_stored=paid_synced,
                payload={
                    "paid_contacts_synced": paid_contacts_synced,
                    "synced_invoices": synced_invoices,
                    "resumed_from": str(resume_source_run.get("id") or "") if paid_checkpoint else "",
                },
            )

        total_contacts_synced = len(contacts) + paid_contacts_synced
        ensure_sync_active()
        completion_summary = (
            f"Incremental sync complete: refreshed {total_contacts_synced} customer contacts, "
            f"{outstanding_synced} changed invoices, and backfilled {paid_synced} paid invoices. "
            f"Pulled through {payments_synced} payments and {credit_sources_synced} customer credits. Scope: {sync_options['label']}."
            if is_incremental_sync
            else f"Synced {total_contacts_synced} customers, {outstanding_synced} outstanding invoices, {paid_synced} paid invoices, {payments_synced} payments, and {credit_sources_synced} customer credits from Xero. Scope: {sync_options['label']}."
        )
        completed = _update_sync_run(
            sync_run_id,
            status="completed",
            current_step="Sync complete",
            customers_synced=total_contacts_synced,
            invoices_synced=synced_invoices,
            fetched_count=total_contacts_synced + len(outstanding_invoices) + paid_records_seen + payments_synced + credit_sources_synced,
            processed_count=total_contacts_synced + synced_invoices + payments_synced + credit_sources_synced,
            failed_count=0,
            contacts_total=total_contacts_synced,
            invoices_total=len(outstanding_invoices) + paid_records_seen,
            summary=completion_summary,
            completed_at=utcnow(),
        )

        record_audit_event("sync_run", str(completed["id"]), "sync.completed", {"summary": completed["summary"]}, user["id"])
        return completed
    except BackgroundRunCancelledError:
        return get_sync_run(user, sync_run_id)
    except Exception as exc:
        message = _sync_error_message(exc)
        failure_fields = {
            "status": "failed",
            "current_step": "Sync failed",
            "summary": "Xero sync failed.",
            "error_message": message,
            "failed_count": 1,
            "completed_at": utcnow(),
        }
        retry_after_seconds = _xero_rate_limit_retry_seconds(exc)
        if retry_after_seconds is not None:
            failure_fields["rate_limit_until"] = utcnow() + timedelta(seconds=retry_after_seconds)
            failure_fields["retry_after_seconds"] = retry_after_seconds
        _update_sync_run(sync_run_id, **failure_fields)
        try:
            record_audit_event(
                "sync_run",
                str(sync_run_id),
                "sync.failed",
                {"error": message, "detail": _sync_error_payload(exc)},
                user["id"],
            )
        except Exception:
            logger.exception("Unable to record failed sync audit event")
        raise


def _late_payment_breakdown(amount_due: float, overdue_days: int) -> dict:
    rate = get_settings().statutory_interest_rate
    interest = round(amount_due * rate * max(overdue_days, 0) / 365, 2)

    if amount_due <= 300:
        court_cost = 35
    elif amount_due <= 500:
        court_cost = 50
    elif amount_due <= 1000:
        court_cost = 70
    elif amount_due <= 1500:
        court_cost = 80
    elif amount_due <= 3000:
        court_cost = 115
    elif amount_due <= 5000:
        court_cost = 205
    else:
        court_cost = 455

    return {"interest": interest, "court_cost": court_cost}


def dashboard_payload(tenant_id: str | None = None) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT
                    MAX(synced_at) AS as_of,
                    COUNT(*) FILTER (WHERE amount_due > 0) AS invoice_count,
                    COALESCE(SUM(CASE WHEN due_date >= CURRENT_DATE - INTERVAL '30 days' AND due_date < CURRENT_DATE THEN amount_due ELSE 0 END), 0) AS overdue_1_30,
                    COALESCE(SUM(CASE WHEN due_date >= CURRENT_DATE - INTERVAL '60 days' AND due_date < CURRENT_DATE - INTERVAL '30 days' THEN amount_due ELSE 0 END), 0) AS overdue_31_60,
                    COALESCE(SUM(CASE WHEN due_date >= CURRENT_DATE - INTERVAL '90 days' AND due_date < CURRENT_DATE - INTERVAL '60 days' THEN amount_due ELSE 0 END), 0) AS overdue_61_90,
                    COALESCE(SUM(CASE WHEN due_date < CURRENT_DATE - INTERVAL '90 days' THEN amount_due ELSE 0 END), 0) AS overdue_90_plus
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE (%s::text IS NULL OR customers.tenant_id = %s::text)
                """,
                (tenant_id, tenant_id),
            )
            summary = cursor.fetchone()
            cursor.execute(
                """
                SELECT
                    COALESCE(SUM(total_due), 0) AS total_receivables,
                    COALESCE(SUM(overdue_amount), 0) AS total_overdue,
                    COALESCE(SUM(credits.credit_balance), 0) AS credit_balance,
                    COUNT(*) FILTER (WHERE overdue_amount > 0) AS accounts_needing_action
                FROM customers
                LEFT JOIN (
                    SELECT customer_id, COALESCE(SUM(remaining_credit), 0) AS credit_balance
                    FROM customer_credits
                    WHERE remaining_credit > 0
                    GROUP BY customer_id
                ) AS credits ON credits.customer_id = customers.id
                WHERE (%s::text IS NULL OR customers.tenant_id = %s::text)
                """,
                (tenant_id, tenant_id),
            )
            customer_summary = cursor.fetchone()
            cursor.execute(
                """
                SELECT customers.name,
                       customers.total_due AS amount_due,
                       MIN(invoices.due_date) FILTER (WHERE invoices.amount_due > 0) AS due_date
                FROM customers
                LEFT JOIN invoices ON invoices.customer_id = customers.id
                WHERE customers.total_due > 0
                  AND (%s::text IS NULL OR customers.tenant_id = %s::text)
                GROUP BY customers.id, customers.name, customers.total_due
                ORDER BY customers.total_due DESC, due_date ASC NULLS LAST
                LIMIT 5
                """,
                (tenant_id, tenant_id),
            )
            risks = cursor.fetchall()
            cursor.execute(
                """
                SELECT completed_at
                FROM sync_runs
                WHERE provider = %s
                  AND status = %s
                  AND (%s::text IS NULL OR tenant_id = %s::text OR tenant_id IS NULL OR tenant_id = '')
                ORDER BY completed_at DESC NULLS LAST, created_at DESC
                LIMIT 1
                """,
                ("xero", "completed", tenant_id, tenant_id),
            )
            latest_sync = cursor.fetchone()
        connection.commit()

    latest_invoice_sync = summary["as_of"]
    latest_completed_sync = (latest_sync or {}).get("completed_at")
    if latest_completed_sync and (latest_invoice_sync is None or latest_completed_sync > latest_invoice_sync):
        latest_invoice_sync = latest_completed_sync

    return {
        "as_of": latest_invoice_sync,
        "invoice_count": summary["invoice_count"] or 0,
        "total_receivables": float(customer_summary["total_receivables"] or 0),
        "total_overdue": float(customer_summary["total_overdue"] or 0),
        "credit_balance": float(customer_summary["credit_balance"] or 0),
        "overdue_1_30": float(summary["overdue_1_30"] or 0),
        "overdue_31_60": float(summary["overdue_31_60"] or 0),
        "overdue_61_90": float(summary["overdue_61_90"] or 0),
        "overdue_90_plus": float(summary["overdue_90_plus"] or 0),
        "accounts_needing_action": customer_summary["accounts_needing_action"] or 0,
        "top_risk_accounts": [
            {
                "name": row["name"],
                "amount_due": float(row["amount_due"]),
                "due_date": row["due_date"],
            }
            for row in risks
        ],
    }


def _iso(value):
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return value


def _float(value) -> float:
    return float(value or 0)


def _invoice_panel_category(invoice: dict) -> str:
    category = str(invoice.get("panel_category") or invoice.get("category") or "").strip().lower()
    if category in {"paid", "outstanding", "query", "overdue", "court", "bad-debt"}:
        return category
    control = str(invoice.get("control_status") or invoice.get("status") or "").lower()
    amount_due = _float(invoice.get("amount_due"))
    due_date = invoice.get("due_date") or invoice.get("invoice_date")
    today = utcnow().date()
    if amount_due <= 0 or "paid" in control:
        return "paid"
    if "bad debt" in control or "bad-debt" in control or "bad_debt" in control:
        return "bad-debt"
    if "court" in control or "legal" in control:
        return "court"
    if "query" in control or "queried" in control or "dispute" in control or "disputed" in control:
        return "query"
    if due_date and due_date < today:
        return "overdue"
    return "outstanding"


def _serialize_timeline_items(rows: list[dict], title_key: str, body_key: str, stamp_key: str = "created_at") -> list[dict]:
    items = []
    for row in rows:
        items.append(
            {
                "id": row.get("id"),
                "title": row.get(title_key) or "Update",
                "body": row.get(body_key) or "",
                "stamp": _iso(row.get(stamp_key)) or "",
            }
        )
    return items


def _serialize_invoice(invoice: dict, detail: dict | None = None) -> dict:
    effective_due_date = invoice.get("due_date") or invoice.get("invoice_date")
    payload = {
        "id": invoice["id"],
        "xeroInvoiceId": invoice.get("xero_invoice_id") or "",
        "invoiceNumber": invoice.get("invoice_number") or "",
        "status": invoice.get("status") or "",
        "controlStatus": invoice.get("control_status") or invoice.get("status") or "New",
        "dueDate": _iso(effective_due_date),
        "invoiceDate": _iso(invoice.get("invoice_date")),
        "description": invoice.get("description") or "",
        "lineItems": invoice.get("line_items") or [],
        "currencyCode": invoice.get("currency_code") or "GBP",
        "total": _float(invoice.get("total")),
        "amountDue": _float(invoice.get("amount_due")),
        "amountPaid": _float(invoice.get("amount_paid")),
        "promisedDate": _iso(invoice.get("promised_date")),
        "promiseStatus": invoice.get("promise_status") or "",
        "lastChasedAt": _iso(invoice.get("last_chased_at")),
        "overdueDays": invoice.get("overdue_days") or 0,
        "latePayment": invoice.get("late_payment") or {"interest": 0, "court_cost": 35},
        "latePaymentChargeRaisedAt": _iso(invoice.get("late_payment_charge_raised_at")),
        "latePaymentChargeInvoiceId": invoice.get("late_payment_charge_invoice_id") or "",
        "latePaymentChargeInvoiceNumber": invoice.get("late_payment_charge_invoice_number") or "",
        "latePaymentChargeAmount": _float(invoice.get("late_payment_charge_amount")),
        "badDebtWriteOffAt": _iso(invoice.get("bad_debt_write_off_at")),
        "badDebtCreditNoteId": invoice.get("bad_debt_credit_note_id") or "",
        "badDebtCreditNoteNumber": invoice.get("bad_debt_credit_note_number") or "",
        "badDebtCreditNoteAmount": _float(invoice.get("bad_debt_credit_note_amount")),
        "category": _invoice_panel_category(invoice),
    }
    if detail:
        payload["notes"] = _serialize_timeline_items(detail["notes"], "full_name", "body")
        payload["promises"] = [
            {
                "id": row.get("id"),
                "title": f"Promise for £{_float(row.get('promised_amount')):,.2f}",
                "body": row.get("note") or "",
                "stamp": _iso(row.get("promised_date")) or "",
                "status": row.get("status") or "",
            }
            for row in detail["promises"]
        ]
        payload["statuses"] = [
            {
                "id": row.get("id"),
                "title": row.get("status") or "Status updated",
                "body": row.get("note") or "",
                "stamp": _iso(row.get("created_at")) or "",
            }
            for row in detail["statuses"]
        ]
        payload["audit"] = [
            {
                "id": row.get("id"),
                "entityType": row.get("entity_type") or "",
                "entityId": row.get("entity_id") or "",
                "title": row.get("event_type") or "Audit event",
                "body": row.get("payload") if isinstance(row.get("payload"), str) else __import__("json").dumps(row.get("payload") or {}),
                "stamp": _iso(row.get("created_at")) or "",
            }
            for row in detail["audit"]
        ]
    return payload


def _serialize_payment(payment: dict) -> dict:
    return {
        "id": payment.get("id"),
        "xeroPaymentId": payment.get("xero_payment_id") or "",
        "invoiceId": payment.get("invoice_id") or "",
        "xeroInvoiceId": payment.get("xero_invoice_id") or "",
        "invoiceNumber": payment.get("invoice_number") or "",
        "date": _iso(payment.get("payment_date")),
        "amount": _float(payment.get("amount")),
        "currencyCode": payment.get("currency_code") or "GBP",
        "reference": payment.get("reference") or "",
        "status": payment.get("status") or "",
        "accountName": payment.get("account_name") or "",
    }


def _tenant_panel_counts(cursor, tenant_id: str | None) -> dict:
    if not tenant_id:
        return {"customer_count": 0, "invoice_count": 0, "has_customer_balance": False}
    cursor.execute(
        """
        SELECT COUNT(DISTINCT customers.id) AS customer_count,
               COUNT(invoices.id) AS invoice_count,
               BOOL_OR(customers.total_due > 0 OR customers.overdue_amount > 0) AS has_customer_balance
        FROM customers
        LEFT JOIN invoices ON invoices.customer_id = customers.id
        WHERE customers.tenant_id = %s
        """,
        (tenant_id,),
    )
    row = cursor.fetchone() or {}
    return {
        "customer_count": _metric_int(row.get("customer_count")),
        "invoice_count": _metric_int(row.get("invoice_count")),
        "has_customer_balance": bool(row.get("has_customer_balance")),
    }


def _tenant_has_display_data(counts: dict) -> bool:
    return _metric_int(counts.get("invoice_count")) > 0 or bool(counts.get("has_customer_balance"))


def _latest_synced_tenant_for_user(cursor, user_id: str, preferred_tenant_id: str | None = None) -> str | None:
    cursor.execute(
        """
        SELECT tenant_id
        FROM xero_connections
        WHERE user_id = %s
          AND tenant_id IS NOT NULL
          AND tenant_id <> ''
        ORDER BY updated_at DESC NULLS LAST, created_at DESC
        """,
        (user_id,),
    )
    connected_tenant_ids = [
        str(row.get("tenant_id") or "").strip()
        for row in (cursor.fetchall() or [])
        if str(row.get("tenant_id") or "").strip()
    ]
    connected_tenant_id_set = set(connected_tenant_ids)

    fallback_tenant_id = None
    if preferred_tenant_id and (not connected_tenant_id_set or preferred_tenant_id in connected_tenant_id_set):
        preferred_counts = _tenant_panel_counts(cursor, preferred_tenant_id)
        if _tenant_has_display_data(preferred_counts):
            return preferred_tenant_id
        if preferred_counts["customer_count"]:
            fallback_tenant_id = preferred_tenant_id

    cursor.execute(
        """
        SELECT tenant_id
        FROM sync_runs
        WHERE provider = 'xero'
          AND initiated_by_user_id = %s
          AND tenant_id IS NOT NULL
          AND tenant_id <> ''
          AND status IN ('completed', 'failed', 'running')
        ORDER BY completed_at DESC NULLS LAST, created_at DESC
        LIMIT 20
        """,
        (user_id,),
    )
    for row in cursor.fetchall():
        tenant_id = row.get("tenant_id")
        if not tenant_id:
            continue
        if connected_tenant_id_set and tenant_id not in connected_tenant_id_set:
            continue
        tenant_counts = _tenant_panel_counts(cursor, tenant_id)
        if _tenant_has_display_data(tenant_counts):
            return tenant_id
        if tenant_counts["customer_count"] and fallback_tenant_id is None:
            fallback_tenant_id = tenant_id
    if connected_tenant_ids:
        cursor.execute(
            """
            SELECT customers.tenant_id,
                   COUNT(DISTINCT customers.id) AS customer_count,
                   COUNT(invoices.id) AS invoice_count,
                   BOOL_OR(customers.total_due > 0 OR customers.overdue_amount > 0) AS has_customer_balance,
                   MAX(COALESCE(invoices.synced_at, customers.updated_at)) AS latest_sync
            FROM customers
            LEFT JOIN invoices ON invoices.customer_id = customers.id
            WHERE customers.tenant_id = ANY(%s)
            GROUP BY customers.tenant_id
            ORDER BY
                CASE
                    WHEN COUNT(invoices.id) > 0 OR BOOL_OR(customers.total_due > 0 OR customers.overdue_amount > 0) THEN 0
                    ELSE 1
                END,
                latest_sync DESC NULLS LAST,
                customer_count DESC
            LIMIT 1
            """,
            (connected_tenant_ids,),
        )
    else:
        cursor.execute(
            """
            SELECT customers.tenant_id,
                   COUNT(DISTINCT customers.id) AS customer_count,
                   COUNT(invoices.id) AS invoice_count,
                   BOOL_OR(customers.total_due > 0 OR customers.overdue_amount > 0) AS has_customer_balance,
                   MAX(COALESCE(invoices.synced_at, customers.updated_at)) AS latest_sync
            FROM customers
            LEFT JOIN invoices ON invoices.customer_id = customers.id
            WHERE customers.tenant_id IS NOT NULL AND customers.tenant_id <> ''
            GROUP BY customers.tenant_id
            ORDER BY
                CASE
                    WHEN COUNT(invoices.id) > 0 OR BOOL_OR(customers.total_due > 0 OR customers.overdue_amount > 0) THEN 0
                    ELSE 1
                END,
                latest_sync DESC NULLS LAST,
                customer_count DESC
            LIMIT 1
            """
        )
    row = cursor.fetchone()
    if row and row.get("tenant_id") and (not connected_tenant_id_set or row.get("tenant_id") in connected_tenant_id_set):
        return row["tenant_id"]
    return fallback_tenant_id


def _xero_cache_status(cursor, user_id: str | None, tenant_id: str | None, stored_customers: int, stored_invoices: int) -> dict:
    if not user_id:
        return {
            "hasMissingLedgerRows": False,
            "message": "",
            "storedCustomers": stored_customers,
            "storedInvoices": stored_invoices,
        }
    cursor.execute(
        """
        SELECT customers_synced,
               invoices_synced,
               contacts_total,
               invoices_total,
               status,
               current_step,
               summary,
               tenant_id,
               completed_at,
               created_at
        FROM sync_runs
        WHERE provider = 'xero'
          AND initiated_by_user_id = %s
          AND (customers_synced > 0 OR invoices_synced > 0 OR contacts_total > 0 OR invoices_total > 0)
          AND (%s::text IS NULL OR tenant_id = %s::text OR tenant_id IS NULL OR tenant_id = '')
        ORDER BY COALESCE(completed_at, created_at) DESC
        LIMIT 1
        """,
        (user_id, tenant_id, tenant_id),
    )
    row = cursor.fetchone()
    reported_customers = int((row or {}).get("customers_synced") or (row or {}).get("contacts_total") or 0)
    reported_invoices = int((row or {}).get("invoices_synced") or (row or {}).get("invoices_total") or 0)
    missing_rows = (
        bool(row)
        and (reported_customers > stored_customers or reported_invoices > stored_invoices)
        and (reported_customers > 0 or reported_invoices > 0)
    )
    message = ""
    if missing_rows:
        message = (
            "The last Xero sync recorded "
            f"{reported_customers:,} customers and {reported_invoices:,} invoices, "
            f"but the saved ledger currently has {stored_customers:,} customers and {stored_invoices:,} invoices. "
            "The next sync will rebuild the cache instead of reusing the broken checkpoint."
        )
    return {
        "hasMissingLedgerRows": missing_rows,
        "message": message,
        "storedCustomers": stored_customers,
        "storedInvoices": stored_invoices,
        "reportedCustomers": reported_customers,
        "reportedInvoices": reported_invoices,
        "lastSyncStatus": (row or {}).get("status") or "",
        "lastSyncStep": (row or {}).get("current_step") or "",
        "lastSyncSummary": (row or {}).get("summary") or "",
    }


def _metric_int(value) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _metric_size_label(value) -> str:
    bytes_value = max(0, _metric_int(value))
    units = ("B", "KB", "MB", "GB", "TB")
    size = float(bytes_value)
    unit_index = 0
    while size >= 1024 and unit_index < len(units) - 1:
        size /= 1024
        unit_index += 1
    if unit_index == 0:
        return f"{bytes_value} B"
    return f"{size:.1f} {units[unit_index]}"


def _seconds_since(moment: datetime | None) -> int:
    if not isinstance(moment, datetime):
        return -1
    return max(0, int((utcnow() - moment).total_seconds()))


def _database_hotspot_summary(alerts: list[dict]) -> dict:
    critical = sum(1 for alert in alerts if str(alert.get("severity") or "").lower() == "critical")
    warning = sum(1 for alert in alerts if str(alert.get("severity") or "").lower() == "warning")
    return {"total": len(alerts), "critical": critical, "warning": warning}


def _database_metrics(cursor, tenant_id: str | None = None, user_id: str | None = None) -> dict:
    cache_key = f"{tenant_id or '*'}::{user_id or '*'}"
    now = utcnow()
    with _DATABASE_METRICS_CACHE_LOCK:
        cached = _DATABASE_METRICS_CACHE_BY_SCOPE.get(cache_key)
        if cached:
            generated_at = cached.get("generated_at")
            if isinstance(generated_at, datetime) and now - generated_at <= DATABASE_METRICS_CACHE_TTL:
                return dict(cached.get("payload") or {})

    table_names = list(DATABASE_METRIC_TABLES)
    cursor.execute(
        """
        SELECT current_database() AS database_name,
               pg_database_size(current_database()) AS database_size_bytes
        """
    )
    database_row = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT relname AS table_name,
               pg_total_relation_size(oid) AS size_bytes
        FROM pg_class
        WHERE relnamespace = 'public'::regnamespace
          AND relkind IN ('r', 'p')
          AND relname = ANY(%s::text[])
        ORDER BY array_position(%s::text[], relname)
        """,
        (table_names, table_names),
    )
    size_lookup = {
        row["table_name"]: _metric_int(row.get("size_bytes"))
        for row in cursor.fetchall()
    }
    table_metrics = []
    total_records = 0
    for table_name in table_names:
        if table_name not in size_lookup:
            continue
        cursor.execute(f'SELECT COUNT(*) AS record_count FROM "{table_name}"')
        record_count = _metric_int((cursor.fetchone() or {}).get("record_count"))
        total_records += record_count
        table_metrics.append(
            {
                "name": table_name,
                "label": DATABASE_METRIC_TABLES.get(table_name, table_name),
                "records": record_count,
                "sizeBytes": size_lookup.get(table_name, 0),
            }
        )

    cursor.execute(
        """
        SELECT COUNT(*) AS customers,
               COUNT(*) FILTER (WHERE total_due > 0) AS customers_with_balance,
               COUNT(DISTINCT tenant_id) AS tenants,
               COALESCE(SUM(total_due), 0) AS total_due,
               COALESCE(SUM(overdue_amount), 0) AS overdue_amount,
               MAX(updated_at) AS latest_customer_update
        FROM customers
        WHERE (%s::text IS NULL OR tenant_id = %s::text)
        """,
        (tenant_id, tenant_id),
    )
    customer_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) AS invoices,
               COUNT(*) FILTER (WHERE invoices.amount_due > 0) AS outstanding_invoices,
               COUNT(*) FILTER (WHERE invoices.amount_due <= 0) AS settled_invoices,
               COALESCE(SUM(invoices.amount_due) FILTER (WHERE invoices.amount_due > 0), 0) AS outstanding_amount,
               COALESCE(SUM(invoices.total), 0) AS invoiced_amount,
               MAX(invoices.synced_at) AS latest_invoice_sync
        FROM invoices
        JOIN customers ON customers.id = invoices.customer_id
        WHERE (%s::text IS NULL OR customers.tenant_id = %s::text)
        """,
        (tenant_id, tenant_id),
    )
    invoice_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE status = 'pending') AS pending_actions,
               COUNT(*) FILTER (WHERE status = 'processing') AS processing_actions,
               COUNT(*) FILTER (WHERE status = 'failed') AS failed_actions,
               COUNT(*) FILTER (WHERE status = 'completed') AS completed_actions
        FROM xero_pending_actions
        WHERE (%s::text IS NULL OR tenant_id = %s::text OR tenant_id IS NULL)
        """,
        (tenant_id, tenant_id),
    )
    action_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT customers.tenant_id,
               COALESCE(MAX(xero_connections.tenant_name), '') AS tenant_name,
               COUNT(DISTINCT customers.id) AS customer_count,
               COUNT(invoices.id) AS invoice_count,
               COUNT(invoices.id) FILTER (WHERE invoices.amount_due > 0) AS outstanding_invoice_count,
               COALESCE(SUM(invoices.amount_due) FILTER (WHERE invoices.amount_due > 0), 0) AS outstanding_amount,
               MAX(COALESCE(invoices.synced_at, customers.updated_at)) AS latest_sync
        FROM customers
        LEFT JOIN invoices ON invoices.customer_id = customers.id
        LEFT JOIN xero_connections ON xero_connections.tenant_id = customers.tenant_id
        GROUP BY customers.tenant_id
        ORDER BY latest_sync DESC NULLS LAST, customer_count DESC
        LIMIT 10
        """
    )
    tenant_rows = cursor.fetchall()
    cursor.execute(
        """
        SELECT tenant_name, tenant_id, expires_at, updated_at, created_at
        FROM xero_connections
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
          AND (%s::text IS NULL OR tenant_id = %s::text)
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (user_id, user_id, tenant_id, tenant_id),
    )
    xero_connection = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT status, current_step, summary, error_message, customers_synced, invoices_synced,
               fetched_count, processed_count, failed_count, contacts_total, invoices_total,
               rate_limit_until, retry_after_seconds, started_at, heartbeat_at, completed_at, created_at
        FROM sync_runs
        WHERE provider = 'xero'
          AND (%s::uuid IS NULL OR initiated_by_user_id = %s::uuid)
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (user_id, user_id),
    )
    xero_sync = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT status, current_step, summary, error_message, fetched_count, processed_count,
               failed_count, heartbeat_at, completed_at, created_at
        FROM ignition_sync_runs
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (user_id, user_id),
    )
    ignition_sync = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT status, practice_name, practice_id, expires_at, last_sync_at, error_message, updated_at
        FROM ignition_connections
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (user_id, user_id),
    )
    ignition_connection = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT dataset, COUNT(*) AS record_count, MAX(synced_at) AS latest_sync
        FROM ignition_reporting_records
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        GROUP BY dataset
        ORDER BY dataset ASC
        """,
        (user_id, user_id),
    )
    ignition_dataset_rows = cursor.fetchall()
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE status IN ('queued', 'processing')) AS active_uploads,
               COUNT(*) FILTER (WHERE status = 'failed') AS failed_uploads,
               COUNT(*) FILTER (WHERE status = 'completed') AS completed_uploads,
               MAX(created_at) AS latest_upload_at,
               MAX(completed_at) AS latest_completed_at
        FROM bank_statement_uploads
        WHERE (%s::text IS NULL OR bank_account_id IN (
            SELECT accounts.id
            FROM bank_statement_accounts AS accounts
            JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
            WHERE clients.tenant_id = %s
        ))
        """,
        (tenant_id, tenant_id),
    )
    bank_upload_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE status IN ('queued', 'running')) AS active_me_syncs,
               COUNT(*) FILTER (WHERE status = 'failed') AS failed_me_syncs,
               MAX(completed_at) AS latest_me_completed_at,
               MAX(heartbeat_at) AS latest_me_heartbeat_at
        FROM me_report_sync_runs
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        """,
        (user_id, user_id),
    )
    me_sync_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE status = 'active') AS active_loans,
               COUNT(*) AS total_loans,
               MAX(updated_at) AS latest_loan_update
        FROM jashflow_loans
        WHERE (%s::text IS NULL OR tenant_id = %s::text)
        """,
        (tenant_id, tenant_id),
    )
    jashflow_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT status, gmail_email, token_expires_at, updated_at, created_at
        FROM gmail_connections
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (user_id, user_id),
    )
    gmail_connection = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT email_provider, updated_at
        FROM me_report_settings
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        ORDER BY updated_at DESC
        LIMIT 1
        """,
        (user_id, user_id),
    )
    me_report_settings = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT environment, auto_sync_enabled, api_key_encrypted, presenter_id, presenter_auth_encrypted, updated_at
        FROM ch_settings
        WHERE singleton_id = 1
        LIMIT 1
        """
    )
    ch_settings = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) AS companies_tracked,
               COUNT(*) FILTER (WHERE next_due_date IS NOT NULL AND next_due_date <= CURRENT_DATE + INTERVAL '30 days') AS due_soon_count,
               MAX(last_synced_at) AS latest_sync_at
        FROM ch_companies
        """
    )
    ch_company_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE status IN ('submitted', 'pending', 'processing', 'in_progress')) AS active_submissions,
               COUNT(*) FILTER (WHERE status IN ('rejected', 'failed', 'error')) AS failed_submissions,
               COUNT(*) FILTER (WHERE status IN ('accepted', 'completed', 'filed')) AS completed_submissions
        FROM ch_submissions
        """
    )
    ch_submission_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT status, rejection_reason, submitted_at, completed_at, created_at
        FROM ch_submissions
        ORDER BY COALESCE(submitted_at, created_at) DESC
        LIMIT 1
        """
    )
    ch_latest_submission = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) FILTER (WHERE expires_at > NOW()) AS active_sessions,
               MAX(last_seen_at) AS latest_seen_at
        FROM sessions
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        """,
        (user_id, user_id),
    )
    session_summary = cursor.fetchone() or {}
    cursor.execute(
        """
        SELECT COUNT(*) AS log_count, MAX(created_at) AS latest_event_at
        FROM audit_events
        WHERE (%s::uuid IS NULL OR user_id = %s::uuid)
        """,
        (user_id, user_id),
    )
    audit_summary = cursor.fetchone() or {}
    settings = get_settings()
    gmail_configured = gmail_oauth_configured()
    gmail_connected = bool(gmail_connection)
    gmail_status = "connected" if gmail_connected else ("not_connected" if gmail_configured else "not_configured")
    ch_api_configured = bool(str(ch_settings.get("api_key_encrypted") or "").strip())
    ch_gateway_configured = bool(str(ch_settings.get("presenter_id") or "").strip() and str(ch_settings.get("presenter_auth_encrypted") or "").strip())
    ch_latest_status = str(ch_latest_submission.get("status") or "").strip().lower()
    if ch_latest_status in {"submitted", "pending", "processing", "in_progress"}:
        ch_connection_status = "running"
    elif ch_latest_status in {"rejected", "failed", "error"}:
        ch_connection_status = "failed"
    elif ch_latest_status in {"accepted", "completed", "filed"}:
        ch_connection_status = "completed"
    else:
        ch_connection_status = "connected" if ch_api_configured else "not_configured"
    ledger_payload = {
        "tenants": _metric_int(customer_summary.get("tenants")),
        "customers": _metric_int(customer_summary.get("customers")),
        "customersWithBalance": _metric_int(customer_summary.get("customers_with_balance")),
        "totalDue": _float(customer_summary.get("total_due")),
        "overdueAmount": _float(customer_summary.get("overdue_amount")),
        "latestCustomerUpdate": _iso(customer_summary.get("latest_customer_update")),
        "invoices": _metric_int(invoice_summary.get("invoices")),
        "outstandingInvoices": _metric_int(invoice_summary.get("outstanding_invoices")),
        "settledInvoices": _metric_int(invoice_summary.get("settled_invoices")),
        "outstandingAmount": _float(invoice_summary.get("outstanding_amount")),
        "invoicedAmount": _float(invoice_summary.get("invoiced_amount")),
        "latestInvoiceSync": _iso(invoice_summary.get("latest_invoice_sync")),
        "pendingActions": _metric_int(action_summary.get("pending_actions")),
        "processingActions": _metric_int(action_summary.get("processing_actions")),
        "failedActions": _metric_int(action_summary.get("failed_actions")),
        "completedActions": _metric_int(action_summary.get("completed_actions")),
    }
    health_payload = {
        "environment": settings.app_env,
        "baseUrlConfigured": bool(settings.base_url),
        "openAiConfigured": bool(settings.openai_api_key),
        "openAiModel": settings.openai_model,
        "xero": {
            "connected": bool(xero_connection),
            "tenantName": xero_connection.get("tenant_name") or "",
            "tenantId": xero_connection.get("tenant_id") or tenant_id or "",
            "tokenExpiresAt": _iso(xero_connection.get("expires_at")) or "",
            "lastConnectionUpdate": _iso(xero_connection.get("updated_at") or xero_connection.get("created_at")) or "",
            "latestSyncStatus": xero_sync.get("status") or "",
            "latestSyncStep": xero_sync.get("current_step") or "",
            "latestSyncSummary": xero_sync.get("error_message") or xero_sync.get("summary") or "",
            "latestSyncCreatedAt": _iso(xero_sync.get("created_at")) or "",
            "latestSyncHeartbeatAt": _iso(xero_sync.get("heartbeat_at")) or "",
            "latestSyncCompletedAt": _iso(xero_sync.get("completed_at")) or "",
            "rateLimitUntil": _iso(xero_sync.get("rate_limit_until")) or "",
            "retryAfterSeconds": _metric_int(xero_sync.get("retry_after_seconds")),
            "customersSynced": _metric_int(xero_sync.get("customers_synced")),
            "invoicesSynced": _metric_int(xero_sync.get("invoices_synced")),
            "failedCount": _metric_int(xero_sync.get("failed_count")),
        },
        "ignition": {
            "connected": bool(ignition_connection),
            "status": ignition_connection.get("status") or "not_connected",
            "practiceName": ignition_connection.get("practice_name") or "",
            "practiceId": ignition_connection.get("practice_id") or "",
            "tokenExpiresAt": _iso(ignition_connection.get("expires_at")) or "",
            "lastSyncAt": _iso(ignition_connection.get("last_sync_at")) or "",
            "errorMessage": ignition_connection.get("error_message") or "",
            "latestSyncStatus": ignition_sync.get("status") or "",
            "latestSyncStep": ignition_sync.get("current_step") or "",
            "latestSyncSummary": ignition_sync.get("error_message") or ignition_sync.get("summary") or "",
            "latestSyncCreatedAt": _iso(ignition_sync.get("created_at")) or "",
            "latestSyncHeartbeatAt": _iso(ignition_sync.get("heartbeat_at")) or "",
            "latestSyncCompletedAt": _iso(ignition_sync.get("completed_at")) or "",
            "fetchedCount": _metric_int(ignition_sync.get("fetched_count")),
            "processedCount": _metric_int(ignition_sync.get("processed_count")),
            "failedCount": _metric_int(ignition_sync.get("failed_count")),
            "datasets": [
                {
                    "name": row.get("dataset") or "",
                    "records": _metric_int(row.get("record_count")),
                    "latestSync": _iso(row.get("latest_sync")) or "",
                }
                for row in ignition_dataset_rows
            ],
        },
        "bankStatements": {
            "activeUploads": _metric_int(bank_upload_summary.get("active_uploads")),
            "failedUploads": _metric_int(bank_upload_summary.get("failed_uploads")),
            "completedUploads": _metric_int(bank_upload_summary.get("completed_uploads")),
            "latestUploadAt": _iso(bank_upload_summary.get("latest_upload_at")) or "",
            "latestCompletedAt": _iso(bank_upload_summary.get("latest_completed_at")) or "",
        },
        "meReport": {
            "activeSyncs": _metric_int(me_sync_summary.get("active_me_syncs")),
            "failedSyncs": _metric_int(me_sync_summary.get("failed_me_syncs")),
            "latestCompletedAt": _iso(me_sync_summary.get("latest_me_completed_at")) or "",
            "latestHeartbeatAt": _iso(me_sync_summary.get("latest_me_heartbeat_at")) or "",
        },
        "jashflow": {
            "activeLoans": _metric_int(jashflow_summary.get("active_loans")),
            "totalLoans": _metric_int(jashflow_summary.get("total_loans")),
            "latestLoanUpdate": _iso(jashflow_summary.get("latest_loan_update")) or "",
        },
        "companiesHouse": {
            "status": ch_connection_status,
            "environment": str(ch_settings.get("environment") or "sandbox").strip().lower(),
            "autoSyncEnabled": bool(ch_settings.get("auto_sync_enabled")),
            "apiConfigured": ch_api_configured,
            "gatewayConfigured": ch_gateway_configured,
            "settingsUpdatedAt": _iso(ch_settings.get("updated_at")) or "",
            "companiesTracked": _metric_int(ch_company_summary.get("companies_tracked")),
            "dueSoonCount": _metric_int(ch_company_summary.get("due_soon_count")),
            "latestSyncAt": _iso(ch_company_summary.get("latest_sync_at")) or "",
            "latestSubmissionStatus": ch_latest_submission.get("status") or "",
            "latestSubmissionReason": ch_latest_submission.get("rejection_reason") or "",
            "latestSubmissionAt": _iso(
                ch_latest_submission.get("submitted_at")
                or ch_latest_submission.get("completed_at")
                or ch_latest_submission.get("created_at")
            ) or "",
            "activeSubmissions": _metric_int(ch_submission_summary.get("active_submissions")),
            "failedSubmissions": _metric_int(ch_submission_summary.get("failed_submissions")),
            "completedSubmissions": _metric_int(ch_submission_summary.get("completed_submissions")),
        },
        "gmail": {
            "status": gmail_status,
            "configured": gmail_configured,
            "connected": gmail_connected,
            "email": gmail_connection.get("gmail_email") or "",
            "tokenExpiresAt": _iso(gmail_connection.get("token_expires_at")) or "",
            "lastConnectionUpdate": _iso(gmail_connection.get("updated_at") or gmail_connection.get("created_at")) or "",
            "meReportProvider": me_report_settings.get("email_provider") or "smtp",
        },
        "smtp": {
            "configured": bool(settings.smtp_host and settings.smtp_from_email),
            "host": settings.smtp_host or "",
            "port": settings.smtp_port,
            "fromEmail": settings.smtp_from_email or "",
            "fromName": settings.smtp_from_name or "",
            "useTls": bool(settings.smtp_use_tls),
        },
        "sessions": {
            "activeSessions": _metric_int(session_summary.get("active_sessions")),
            "latestSeenAt": _iso(session_summary.get("latest_seen_at")) or "",
        },
        "audit": {
            "events": _metric_int(audit_summary.get("log_count")),
            "latestEventAt": _iso(audit_summary.get("latest_event_at")) or "",
        },
    }
    alerts: list[dict] = []
    for table in sorted(table_metrics, key=lambda item: (item.get("sizeBytes") or 0), reverse=True)[:5]:
        table_size = _metric_int(table.get("sizeBytes"))
        table_records = _metric_int(table.get("records"))
        if table_size >= DATABASE_HOT_TABLE_SIZE_BYTES or table_records >= DATABASE_HOT_TABLE_RECORDS:
            severity = "critical" if table_size >= DATABASE_HOT_TABLE_SIZE_BYTES * 2 or table_records >= DATABASE_HOT_TABLE_RECORDS * 2 else "warning"
            alerts.append(
                {
                    "severity": severity,
                    "source": "database_table",
                    "title": f"Heavy table: {table.get('label') or table.get('name')}",
                    "detail": f"{table_records:,} rows · {_metric_size_label(table_size)}",
                    "recommendation": "Review retention and add archival for historical rows in this table.",
                }
            )
    queue_backlog = _metric_int(ledger_payload.get("pendingActions")) + _metric_int(ledger_payload.get("processingActions"))
    failed_actions = _metric_int(ledger_payload.get("failedActions"))
    if queue_backlog >= DATABASE_QUEUE_WARNING_THRESHOLD or failed_actions >= DATABASE_FAILED_ACTION_WARNING_THRESHOLD:
        severity = (
            "critical"
            if queue_backlog >= DATABASE_QUEUE_CRITICAL_THRESHOLD or failed_actions >= DATABASE_FAILED_ACTION_CRITICAL_THRESHOLD
            else "warning"
        )
        alerts.append(
            {
                "severity": severity,
                "source": "xero_outbox",
                "title": "Xero outbox pressure is high",
                "detail": (
                    f"{queue_backlog:,} queued/processing actions · "
                    f"{failed_actions:,} failed actions"
                ),
                "recommendation": "Reduce batch size, retry failed rows, and delay non-urgent sync runs until backlog clears.",
            }
        )
    xero_status = str((xero_sync or {}).get("status") or "").strip().lower()
    xero_heartbeat_age = _seconds_since((xero_sync or {}).get("heartbeat_at"))
    if xero_status in ACTIVE_SYNC_STATUSES and xero_heartbeat_age >= DATABASE_HEARTBEAT_STALE_WARNING_SECONDS:
        alerts.append(
            {
                "severity": "critical" if xero_heartbeat_age >= DATABASE_HEARTBEAT_STALE_CRITICAL_SECONDS else "warning",
                "source": "xero_sync",
                "title": "Xero sync heartbeat is stale",
                "detail": f"No heartbeat for {xero_heartbeat_age}s while sync status is {xero_status}.",
                "recommendation": "Check worker logs for stuck API pagination or rate-limit loops before starting another sync.",
            }
        )
    ignition_status = str((ignition_sync or {}).get("status") or "").strip().lower()
    ignition_heartbeat_age = _seconds_since((ignition_sync or {}).get("heartbeat_at"))
    if ignition_status in ACTIVE_SYNC_STATUSES and ignition_heartbeat_age >= DATABASE_HEARTBEAT_STALE_WARNING_SECONDS:
        alerts.append(
            {
                "severity": "critical" if ignition_heartbeat_age >= DATABASE_HEARTBEAT_STALE_CRITICAL_SECONDS else "warning",
                "source": "ignition_sync",
                "title": "Ignition sync heartbeat is stale",
                "detail": f"No heartbeat for {ignition_heartbeat_age}s while sync status is {ignition_status}.",
                "recommendation": "Pause new Ignition runs and inspect the active job for API throttling or stalled processing.",
            }
        )
    me_active_syncs = _metric_int((me_sync_summary or {}).get("active_me_syncs"))
    me_failed_syncs = _metric_int((me_sync_summary or {}).get("failed_me_syncs"))
    if me_active_syncs >= DATABASE_ACTIVE_ME_SYNC_WARNING_THRESHOLD or me_failed_syncs > 0:
        alerts.append(
            {
                "severity": (
                    "critical"
                    if me_active_syncs >= DATABASE_ACTIVE_ME_SYNC_CRITICAL_THRESHOLD or me_failed_syncs >= 3
                    else "warning"
                ),
                "source": "me_report",
                "title": "ME Report sync queue needs attention",
                "detail": f"{me_active_syncs:,} active syncs · {me_failed_syncs:,} failed syncs",
                "recommendation": "Run fewer concurrent submissions and resolve failed reports before queueing another bulk run.",
            }
        )
    bank_active_uploads = _metric_int((bank_upload_summary or {}).get("active_uploads"))
    bank_failed_uploads = _metric_int((bank_upload_summary or {}).get("failed_uploads"))
    if bank_active_uploads >= DATABASE_ACTIVE_UPLOAD_WARNING_THRESHOLD or bank_failed_uploads > 0:
        alerts.append(
            {
                "severity": (
                    "critical"
                    if bank_active_uploads >= DATABASE_ACTIVE_UPLOAD_CRITICAL_THRESHOLD or bank_failed_uploads >= 5
                    else "warning"
                ),
                "source": "bank_statements",
                "title": "Bank extraction queue is elevated",
                "detail": f"{bank_active_uploads:,} active uploads · {bank_failed_uploads:,} failed",
                "recommendation": "Process large PDF uploads in smaller batches and retry failed statements outside peak sync hours.",
            }
        )
    metrics_payload = {
        "generatedAt": _iso(now),
        "databaseName": database_row.get("database_name") or "",
        "databaseSizeBytes": _metric_int(database_row.get("database_size_bytes")),
        "totalRecords": total_records,
        "visibleTenantId": tenant_id or "",
        "tables": table_metrics,
        "ledger": ledger_payload,
        "tenants": [
            {
                "tenantId": row.get("tenant_id") or "",
                "tenantName": row.get("tenant_name") or "",
                "customers": _metric_int(row.get("customer_count")),
                "invoices": _metric_int(row.get("invoice_count")),
                "outstandingInvoices": _metric_int(row.get("outstanding_invoice_count")),
                "outstandingAmount": _float(row.get("outstanding_amount")),
                "latestSync": _iso(row.get("latest_sync")),
            }
            for row in tenant_rows
        ],
        "health": health_payload,
        "hotspots": alerts,
        "hotspotSummary": _database_hotspot_summary(alerts),
    }
    with _DATABASE_METRICS_CACHE_LOCK:
        _DATABASE_METRICS_CACHE_BY_SCOPE[cache_key] = {"generated_at": now, "payload": metrics_payload}
    return metrics_payload


def _database_metrics_unavailable(error: Exception | None = None) -> dict:
    return {
        "generatedAt": _iso(utcnow()),
        "databaseName": "",
        "databaseSizeBytes": 0,
        "totalRecords": 0,
        "visibleTenantId": "",
        "tables": [],
        "ledger": {},
        "tenants": [],
        "health": {},
        "hotspots": [],
        "hotspotSummary": {"total": 0, "critical": 0, "warning": 0},
        "error": str(error or "") or "Database metrics are unavailable.",
    }


def _customer_primary_address(row: dict) -> str:
    addresses = row.get("addresses") if isinstance(row.get("addresses"), list) else []
    for item in addresses:
        if not isinstance(item, dict):
            continue
        parts = [
            item.get("address_line_1"),
            item.get("address_line_2"),
            item.get("city"),
            item.get("region"),
            item.get("postal_code"),
            item.get("country"),
        ]
        text = ", ".join(str(part or "").strip() for part in parts if str(part or "").strip())
        if text:
            return text
    return ""


def _clean_text(value: object, *, max_length: int) -> str:
    return str(value or "").strip()[:max_length]


def _normalise_customer_profile(row: dict) -> dict:
    profile = row.get("client_profile") if isinstance(row.get("client_profile"), dict) else {}
    return {
        "clientName": _clean_text(profile.get("clientName") or row.get("name"), max_length=250),
        "clientManager": _clean_text(profile.get("clientManager"), max_length=120),
        "clientId": _clean_text(profile.get("clientId"), max_length=80),
        "clientType": _clean_text(profile.get("clientType"), max_length=120),
        "companyNumber": _clean_text(profile.get("companyNumber"), max_length=32),
        "companyStatus": _clean_text(profile.get("companyStatus") or row.get("status"), max_length=120),
        "companyUtr": _clean_text(profile.get("companyUtr"), max_length=32),
        "vatNumber": _clean_text(profile.get("vatNumber"), max_length=32),
        "email": _clean_text(profile.get("email") or row.get("email"), max_length=250),
        "phone": _clean_text(profile.get("phone") or row.get("phone"), max_length=80),
        "authCode": _clean_text(profile.get("authCode"), max_length=24),
        "address": _clean_text(profile.get("address") or _customer_primary_address(row), max_length=1000),
    }


def _normalise_customer_structure(value: object) -> dict:
    source = value if isinstance(value, dict) else {}

    def _people(items: object, *, role_key: str) -> list[dict]:
        rows = items if isinstance(items, list) else []
        output: list[dict] = []
        for item in rows:
            if not isinstance(item, dict):
                continue
            name = _clean_text(item.get("name"), max_length=250)
            if not name:
                continue
            output.append(
                {
                    "name": name,
                    role_key: _clean_text(item.get(role_key), max_length=120),
                }
            )
        return output[:20]

    return {
        "source": _clean_text(source.get("source"), max_length=60),
        "companyNumber": _clean_text(source.get("companyNumber"), max_length=32),
        "directors": _people(source.get("directors"), role_key="role"),
        "shareholders": _people(source.get("shareholders"), role_key="holding"),
        "pscs": _people(source.get("pscs"), role_key="kind"),
        "syncedAt": _clean_text(source.get("syncedAt"), max_length=80),
    }


def _structure_from_ch_company(row: dict, company_number: str) -> dict:
    officers = row.get("officers") if isinstance(row.get("officers"), list) else []
    pscs = row.get("pscs") if isinstance(row.get("pscs"), list) else []
    share_capital = row.get("share_capital") if isinstance(row.get("share_capital"), dict) else {}

    directors: list[dict] = []
    for officer in officers:
        if not isinstance(officer, dict):
            continue
        name = _clean_text(officer.get("name"), max_length=250)
        if not name:
            continue
        directors.append({"name": name, "role": _clean_text(officer.get("role"), max_length=120)})

    psc_group: list[dict] = []
    for psc in pscs:
        if not isinstance(psc, dict):
            continue
        name = _clean_text(psc.get("name"), max_length=250)
        if not name:
            continue
        psc_group.append({"name": name, "kind": _clean_text(psc.get("kind"), max_length=120)})

    shareholders: list[dict] = []
    shareholdings = share_capital.get("shareholdings") if isinstance(share_capital.get("shareholdings"), list) else []
    for holding in shareholdings:
        if not isinstance(holding, dict):
            continue
        share_class = _clean_text(holding.get("shareClass"), max_length=80)
        row_holders = holding.get("shareholders") if isinstance(holding.get("shareholders"), list) else []
        for holder in row_holders:
            if not isinstance(holder, dict):
                continue
            name = _clean_text(holder.get("name") or holder.get("fullName"), max_length=250)
            if not name:
                continue
            shareholders.append(
                {
                    "name": name,
                    "holding": _clean_text(share_class or holder.get("shares"), max_length=120),
                }
            )

    if not shareholders:
        confirmation = (
            share_capital.get("confirmationStatement")
            if isinstance(share_capital.get("confirmationStatement"), dict)
            else {}
        )
        count_raw = confirmation.get("numberOfShareholders")
        try:
            holder_count = max(0, int(str(count_raw or "").strip()))
        except (TypeError, ValueError):
            holder_count = 0
        for index in range(min(holder_count, 6)):
            shareholders.append({"name": f"Shareholder {index + 1}", "holding": "On register"})

    synced_at = row.get("last_synced_at")
    return _normalise_customer_structure(
        {
            "source": "companies_house",
            "companyNumber": company_number,
            "directors": directors,
            "shareholders": shareholders,
            "pscs": psc_group,
            "syncedAt": _iso(synced_at),
        }
    )


def panel_payload(user: dict | None = None) -> dict:
    customers = []
    selected_invoice = None
    xero_connected = False
    xero_connection = None
    tenant_id = None
    if user and user.get("id"):
        try:
            xero_connection = get_master_xero_connection_for_user(user["id"])
            tenant_id = xero_connection.get("tenant_id")
            xero_connected = True
        except HTTPException:
            xero_connected = False

    tenant_scope = str(tenant_id or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM customers
                WHERE (%s::text IS NULL OR tenant_id = %s::text)
                ORDER BY overdue_amount DESC, total_due DESC, name ASC
                """,
                (tenant_scope, tenant_scope),
            )
            customer_rows = cursor.fetchall()
            cursor.execute(
                """
                SELECT invoices.*
                FROM invoices
                JOIN customers ON customers.id = invoices.customer_id
                WHERE (%s::text IS NULL OR customers.tenant_id = %s::text)
                ORDER BY due_date ASC NULLS LAST, invoice_number ASC
                """,
                (tenant_scope, tenant_scope),
            )
            invoice_rows = cursor.fetchall()
            if user and user.get("id"):
                cursor.execute(
                    """
                    SELECT *
                    FROM audit_events
                    WHERE user_id = %s OR user_id IS NULL
                    ORDER BY created_at DESC
                    LIMIT %s
                    """,
                    (user["id"], PANEL_AUDIT_LIMIT),
                )
            else:
                cursor.execute(
                    """
                    SELECT *
                    FROM audit_events
                    ORDER BY created_at DESC
                    LIMIT %s
                    """,
                    (PANEL_AUDIT_LIMIT,),
                )
            audit_rows = cursor.fetchall()
            cursor.execute(
                """
                WITH ranked_customer_notes AS (
                    SELECT customer_notes.*,
                           users.full_name,
                           ROW_NUMBER() OVER (
                               PARTITION BY customer_notes.customer_id
                               ORDER BY customer_notes.created_at DESC
                           ) AS note_rank
                    FROM customer_notes
                    JOIN customers ON customers.id = customer_notes.customer_id
                    LEFT JOIN users ON users.id = customer_notes.user_id
                    WHERE (%s::text IS NULL OR customers.tenant_id = %s::text)
                )
                SELECT *
                FROM ranked_customer_notes
                WHERE note_rank <= %s
                ORDER BY created_at DESC
                """,
                (tenant_scope, tenant_scope, PANEL_CUSTOMER_NOTE_LIMIT_PER_CUSTOMER),
            )
            customer_note_rows = cursor.fetchall()
            invoice_ids = [row["id"] for row in invoice_rows]
            note_rows = []
            promise_rows = []
            status_rows = []
            payment_rows = []
            credit_total_rows = []
            if invoice_ids:
                cursor.execute(
                    """
                    WITH ranked_notes AS (
                        SELECT notes.*,
                               users.full_name,
                               ROW_NUMBER() OVER (
                                   PARTITION BY notes.invoice_id
                                   ORDER BY notes.created_at DESC
                               ) AS note_rank
                        FROM notes
                        LEFT JOIN users ON users.id = notes.user_id
                        WHERE notes.invoice_id = ANY(%s)
                    )
                    SELECT *
                    FROM ranked_notes
                    WHERE note_rank <= %s
                    ORDER BY created_at DESC
                    """,
                    (invoice_ids, PANEL_TIMELINE_LIMIT_PER_INVOICE),
                )
                note_rows = cursor.fetchall()
                cursor.execute(
                    """
                    WITH ranked_promises AS (
                        SELECT payment_promises.*,
                               users.full_name,
                               ROW_NUMBER() OVER (
                                   PARTITION BY payment_promises.invoice_id
                                   ORDER BY payment_promises.created_at DESC
                               ) AS promise_rank
                        FROM payment_promises
                        LEFT JOIN users ON users.id = payment_promises.created_by_user_id
                        WHERE payment_promises.invoice_id = ANY(%s)
                    )
                    SELECT *
                    FROM ranked_promises
                    WHERE promise_rank <= %s
                    ORDER BY created_at DESC
                    """,
                    (invoice_ids, PANEL_TIMELINE_LIMIT_PER_INVOICE),
                )
                promise_rows = cursor.fetchall()
                cursor.execute(
                    """
                    WITH ranked_statuses AS (
                        SELECT invoice_status_history.*,
                               users.full_name,
                               ROW_NUMBER() OVER (
                                   PARTITION BY invoice_status_history.invoice_id
                                   ORDER BY invoice_status_history.created_at DESC
                               ) AS status_rank
                        FROM invoice_status_history
                        LEFT JOIN users ON users.id = invoice_status_history.changed_by_user_id
                        WHERE invoice_status_history.invoice_id = ANY(%s)
                    )
                    SELECT *
                    FROM ranked_statuses
                    WHERE status_rank <= %s
                    ORDER BY created_at DESC
                    """,
                    (invoice_ids, PANEL_TIMELINE_LIMIT_PER_INVOICE),
                )
                status_rows = cursor.fetchall()
            cursor.execute(
                """
                SELECT *
                FROM payments
                WHERE (%s::text IS NULL OR customer_id IN (
                    SELECT id FROM customers WHERE tenant_id = %s
                ))
                ORDER BY payment_date DESC NULLS LAST, created_at DESC
                LIMIT %s
                """,
                (tenant_scope, tenant_scope, PANEL_PAYMENT_LIMIT),
            )
            payment_rows = cursor.fetchall()
            cursor.execute(
                """
                SELECT customer_id,
                       COALESCE(SUM(remaining_credit), 0) AS credit_balance,
                       COUNT(*) AS credit_count
                FROM customer_credits
                WHERE remaining_credit > 0
                  AND (%s::text IS NULL OR customer_id IN (
                      SELECT id FROM customers WHERE tenant_id = %s
                  ))
                GROUP BY customer_id
                """,
                (tenant_scope, tenant_scope),
            )
            credit_total_rows = cursor.fetchall()
            cache_status = _xero_cache_status(
                cursor,
                user["id"] if user and user.get("id") else None,
                tenant_scope,
                len(customer_rows),
                len(invoice_rows),
            )
            posting_settings = _posting_settings_for_tenant_with_cursor(cursor, tenant_scope)
            try:
                database_metrics = _database_metrics(cursor, tenant_scope, user["id"] if user and user.get("id") else None)
            except Exception as exc:
                logger.exception("Unable to build database metrics")
                connection.rollback()
                database_metrics = _database_metrics_unavailable(exc)
        connection.commit()

    invoices_by_customer: dict[str, list[dict]] = {}
    notes_by_customer: dict[str, list[dict]] = {}
    notes_by_invoice: dict[str, list[dict]] = defaultdict(list)
    promises_by_invoice: dict[str, list[dict]] = defaultdict(list)
    statuses_by_invoice: dict[str, list[dict]] = defaultdict(list)
    payments_by_customer: dict[str, list[dict]] = defaultdict(list)
    credit_totals_by_customer = {row["customer_id"]: row for row in credit_total_rows}
    panel_summary_counts = {
        "all": 0,
        "paid": 0,
        "query": 0,
        "overdue": 0,
        "court": 0,
        "badDebt": 0,
    }
    panel_summary_totals = {
        "all": 0.0,
        "paid": 0.0,
        "query": 0.0,
        "overdue": 0.0,
        "court": 0.0,
        "badDebt": 0.0,
    }
    for note in customer_note_rows:
        notes_by_customer.setdefault(note["customer_id"], []).append(note)
    for note in note_rows:
        notes_by_invoice[note["invoice_id"]].append(note)
    for promise in promise_rows:
        promises_by_invoice[promise["invoice_id"]].append(promise)
    for status_row in status_rows:
        statuses_by_invoice[status_row["invoice_id"]].append(status_row)
    for payment in payment_rows:
        if payment.get("customer_id"):
            payments_by_customer[payment["customer_id"]].append(payment)

    today = utcnow().date()
    for invoice in invoice_rows:
        due_date = invoice["due_date"] or invoice["invoice_date"]
        overdue_days = 0 if due_date is None else max((today - due_date).days, 0)
        invoice["late_payment"] = _late_payment_breakdown(float(invoice["amount_due"]), overdue_days)
        invoice["overdue_days"] = overdue_days
        category = _invoice_panel_category(invoice)
        invoice["panel_category"] = category
        amount_due_value = _float(invoice.get("amount_due"))
        panel_summary_counts["all"] += 1
        panel_summary_totals["all"] += amount_due_value
        if category == "paid":
            panel_summary_counts["paid"] += 1
            panel_summary_totals["paid"] += _float(invoice.get("total"))
        elif category == "query":
            panel_summary_counts["query"] += 1
            panel_summary_totals["query"] += amount_due_value
        elif category == "overdue":
            panel_summary_counts["overdue"] += 1
            panel_summary_totals["overdue"] += amount_due_value
        elif category == "court":
            panel_summary_counts["court"] += 1
            panel_summary_totals["court"] += amount_due_value
        elif category == "bad-debt":
            panel_summary_counts["badDebt"] += 1
            panel_summary_totals["badDebt"] += amount_due_value
        invoices_by_customer.setdefault(invoice["customer_id"], []).append(invoice)

    for customer_row in customer_rows:
        detail_invoices = invoices_by_customer.get(customer_row["id"], [])
        invoices = []
        for invoice in detail_invoices:
            invoice_payload = _serialize_invoice(
                invoice,
                {
                    "notes": notes_by_invoice.get(invoice["id"], []),
                    "promises": promises_by_invoice.get(invoice["id"], []),
                    "statuses": statuses_by_invoice.get(invoice["id"], []),
                    "audit": [],
                },
            )
            invoices.append(invoice_payload)
            if selected_invoice is None:
                selected_invoice = invoice_payload

        open_invoices = sum(1 for invoice in detail_invoices if _float(invoice.get("amount_due")) > 0)
        gross_total_due = sum(_float(invoice.get("amount_due")) for invoice in detail_invoices)
        credit_totals = credit_totals_by_customer.get(customer_row["id"], {})
        credit_balance = _float(credit_totals.get("credit_balance"))
        customers.append(
            {
                "id": customer_row["id"],
                "xeroContactId": customer_row.get("xero_contact_id") or "",
                "name": customer_row.get("name") or "",
                "email": customer_row.get("email") or "",
                "phone": customer_row.get("phone") or "",
                "accountNumber": customer_row.get("account_number") or "",
                "latePaymentChargeBaseAmount": (
                    float(customer_row["late_payment_charge_base_amount"])
                    if customer_row.get("late_payment_charge_base_amount") is not None
                    else None
                ),
                "primaryPerson": customer_row.get("primary_person") or "",
                "contactPeople": customer_row.get("contact_people") or [],
                "addresses": customer_row.get("addresses") or [],
                "contact": customer_row.get("email") or customer_row.get("phone") or "",
                "status": customer_row.get("status") or ("Action needed" if _float(customer_row.get("overdue_amount")) > 0 else "Current"),
                "clientProfile": _normalise_customer_profile(customer_row),
                "companyStructure": _normalise_customer_structure(customer_row.get("company_structure")),
                "companyStructureSyncedAt": _iso(customer_row.get("company_structure_synced_at")),
                "openInvoices": open_invoices,
                "totalDue": _float(customer_row.get("total_due")),
                "overdue": _float(customer_row.get("overdue_amount")),
                "clientNotes": _serialize_timeline_items(notes_by_customer.get(customer_row["id"], []), "full_name", "body"),
                "payments": [_serialize_payment(payment) for payment in payments_by_customer.get(customer_row["id"], [])],
                "invoices": invoices,
            }
        )

    dashboard = dashboard_payload(tenant_scope)
    has_cached_xero_data = bool(customers or dashboard["invoice_count"] or dashboard["as_of"])
    last_sync_label = f'Last sync {dashboard["as_of"]}' if dashboard["as_of"] else "Waiting for first sync"
    if not xero_connected and dashboard["as_of"]:
        last_sync_label = f'Cached ledger from {dashboard["as_of"]}'
    return {
        "organisation": {
            "name": (
                xero_connection.get("tenant_name", "Xero Organisation")
                if xero_connected and xero_connection
                else ("Cached Xero ledger" if has_cached_xero_data else "")
            ),
            "status": "Connected" if xero_connected else ("Cached ledger available" if has_cached_xero_data else "Awaiting live connection"),
            "lastSync": last_sync_label,
            "xeroConnected": xero_connected,
        },
        "dashboard": {
            "totalReceivables": dashboard["total_receivables"],
            "totalOverdue": dashboard["total_overdue"],
            "openInvoices": dashboard["invoice_count"],
            "accountsNeedingAction": dashboard["accounts_needing_action"],
            "potentialInterest": round(
                sum((invoice.get("late_payment") or {}).get("interest", 0) for customer in customers for invoice in customer["invoices"]),
                2,
            ),
        },
        "panelSummary": {
            "counts": panel_summary_counts,
            "totals": {
                "all": round(panel_summary_totals["all"], 2),
                "paid": round(panel_summary_totals["paid"], 2),
                "query": round(panel_summary_totals["query"], 2),
                "overdue": round(panel_summary_totals["overdue"], 2),
                "court": round(panel_summary_totals["court"], 2),
                "badDebt": round(panel_summary_totals["badDebt"], 2),
            },
        },
        "customers": customers,
        "cacheStatus": cache_status,
        "postingSettings": posting_settings,
        "databaseMetrics": database_metrics,
        "audit": [
            {
                "id": row.get("id"),
                "entityType": row.get("entity_type") or "",
                "entityId": row.get("entity_id") or "",
                "title": row.get("event_type") or "Audit event",
                "body": row.get("payload") if isinstance(row.get("payload"), str) else __import__("json").dumps(row.get("payload") or {}),
                "stamp": _iso(row.get("created_at")) or "",
            }
            for row in audit_rows
        ],
        "selectedInvoice": selected_invoice,
    }


def _money(value) -> Decimal:
    try:
        return Decimal(str(value if value is not None else 0)).quantize(Decimal("0.01"))
    except Exception:
        return Decimal("0.00")


def _parse_iso_date(value, field_name: str) -> date:
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    try:
        return date.fromisoformat(str(value or "")[:10])
    except ValueError as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"{field_name} must be a valid date.") from exc


def _positive_money(value, field_name: str) -> Decimal:
    amount = _money(value)
    if amount <= 0:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"{field_name} must be greater than zero.")
    return amount


def _non_negative_money(value, field_name: str) -> Decimal:
    amount = _money(value)
    if amount < 0:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"{field_name} cannot be negative.")
    return amount


def _rate_percent(value, field_name: str = "Interest rate") -> Decimal:
    try:
        rate = Decimal(str(value if value is not None else 0)).quantize(Decimal("0.000001"))
    except Exception as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"{field_name} must be a valid percentage.") from exc
    if rate < 0:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"{field_name} cannot be negative.")
    return rate


def _jashflow_tenant_id(user: dict) -> str:
    return str(get_xero_connection_for_user(user["id"]).get("tenant_id") or "")


JASHFLOW_HISTORY_EVENT_TITLES = {
    "jashflow.loan_created": "Loan created",
    "jashflow.loan_updated": "Loan updated",
    "jashflow.loan_recalculated": "Loan recalculated",
    "jashflow.loan_deleted": "Loan deleted",
    "jashflow.payment_added": "Payment added",
    "jashflow.charge_added": "Charge added",
}

JASHFLOW_LEGACY_HISTORY_FIELDS = (
    ("principal_amount", "Loan amount", "currency"),
    ("arrangement_fee", "Arrangement fee", "currency"),
    ("annual_interest_rate", "Compound interest", "percentage"),
    ("duration_months", "Term", "months"),
    ("start_date", "Start date", "date"),
    ("status", "Status", "text"),
    ("notes", "Loan notes", "text"),
)


def _jashflow_change_entry(field: str, label: str, before, after, value_format: str = "text") -> dict:
    return {
        "field": field,
        "label": label,
        "from": _safe_json(before),
        "to": _safe_json(after),
        "format": value_format,
    }


def _jashflow_audit_payload(value) -> dict:
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {"description": value}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _jashflow_legacy_history_changes(event_type: str, payload: dict) -> list[dict]:
    changes = []
    if event_type in {"jashflow.loan_created", "jashflow.loan_updated"}:
        customer_label = payload.get("customer_name") or payload.get("customer_id")
        if customer_label:
            changes.append({
                "field": "customer",
                "label": "Client",
                "to": _safe_json(customer_label),
                "format": "text",
            })
        for field, label, value_format in JASHFLOW_LEGACY_HISTORY_FIELDS:
            if field in payload:
                if field == "notes" and not payload.get(field):
                    continue
                changes.append({
                    "field": field,
                    "label": label,
                    "to": _safe_json(payload.get(field)),
                    "format": value_format,
                })
    elif event_type == "jashflow.payment_added":
        for field, label, value_format in (
            ("payment_date", "Payment date", "date"),
            ("amount", "Payment amount", "currency"),
            ("description", "Reference", "text"),
        ):
            if field in payload:
                changes.append({
                    "field": field,
                    "label": label,
                    "to": _safe_json(payload.get(field)),
                    "format": value_format,
                })
    elif event_type == "jashflow.charge_added":
        for field, label, value_format in (
            ("charge_date", "Charge date", "date"),
            ("amount", "Charge amount", "currency"),
            ("description", "Description", "text"),
        ):
            if field in payload:
                changes.append({
                    "field": field,
                    "label": label,
                    "to": _safe_json(payload.get(field)),
                    "format": value_format,
                })
    return changes


def _serialize_jashflow_history_event(row: dict) -> dict:
    event_type = row.get("event_type") or ""
    payload = _jashflow_audit_payload(row.get("payload"))
    changes = payload.get("changes") if isinstance(payload.get("changes"), list) else []
    if not changes:
        changes = _jashflow_legacy_history_changes(event_type, payload)
    description = str(payload.get("description") or payload.get("message") or "").strip()
    return {
        "id": str(row.get("id") or ""),
        "eventType": event_type,
        "title": JASHFLOW_HISTORY_EVENT_TITLES.get(event_type, event_type or "Loan event"),
        "description": description,
        "stamp": _iso(row.get("created_at")) or "",
        "userName": row.get("full_name") or row.get("email") or "",
        "userEmail": row.get("email") or "",
        "changes": [_safe_json(change) for change in changes if isinstance(change, dict)],
    }


def _jashflow_transaction_sort_key(item: dict) -> tuple:
    transaction_date = item.get("transaction_date") or item.get("date") or date.min
    if isinstance(transaction_date, datetime):
        transaction_date = transaction_date.date()
    if not isinstance(transaction_date, date):
        transaction_date = _parse_iso_date(transaction_date, "Transaction date")
    return (transaction_date, item.get("created_at") or datetime.min.replace(tzinfo=timezone.utc))


def _jashflow_signed_amount(row: dict) -> Decimal:
    amount = _money(row.get("amount"))
    return -amount if row.get("transaction_type") == "payment" else amount


def _jashflow_interest_summary(loan: dict, transactions: list[dict] | None = None, as_of: date | None = None) -> dict:
    as_of = as_of or utcnow().date()
    start_date = loan.get("start_date") or as_of
    if isinstance(start_date, datetime):
        start_date = start_date.date()
    if not isinstance(start_date, date):
        start_date = _parse_iso_date(start_date, "Start date")

    principal = _money(loan.get("principal_amount"))
    fee = _money(loan.get("arrangement_fee"))
    base = principal + fee
    annual_rate_percent = _rate_percent(loan.get("annual_interest_rate"))
    annual_rate = max(0.0, float(annual_rate_percent) / 100)
    daily_rate = (1 + annual_rate) ** (1 / 365) - 1 if annual_rate else 0
    monthly_rate = (1 + annual_rate) ** (1 / 12) - 1 if annual_rate else 0
    elapsed_days = max((as_of - start_date).days, 0)
    actual_transactions = [
        row for row in (transactions or [])
        if row.get("transaction_type") not in ("scheduled_repayment", "interest")
    ]
    if not actual_transactions:
        actual_transactions = [
            {"transaction_date": start_date, "transaction_type": "advance", "amount": principal, "created_at": datetime.min.replace(tzinfo=timezone.utc)},
        ]
        if fee > 0:
            actual_transactions.append({"transaction_date": start_date, "transaction_type": "fee", "amount": fee, "created_at": datetime.min.replace(tzinfo=timezone.utc)})

    balance_before_interest = Decimal("0.00")
    balance = Decimal("0.00")
    accrued_interest = Decimal("0.00")
    cursor_date = start_date
    payments_total = Decimal("0.00")
    charges_total = Decimal("0.00")

    def accrue_to(target_date: date) -> None:
        nonlocal balance, accrued_interest, cursor_date
        if target_date <= cursor_date:
            cursor_date = max(cursor_date, target_date)
            return
        days = max((target_date - cursor_date).days, 0)
        if daily_rate and balance > 0 and days > 0:
            interest = _money(float(balance) * (((1 + daily_rate) ** days) - 1))
            accrued_interest = _money(accrued_interest + interest)
            balance = _money(balance + interest)
        cursor_date = target_date

    for row in sorted(actual_transactions, key=_jashflow_transaction_sort_key):
        transaction_date = row.get("transaction_date") or start_date
        if isinstance(transaction_date, datetime):
            transaction_date = transaction_date.date()
        if not isinstance(transaction_date, date):
            transaction_date = _parse_iso_date(transaction_date, "Transaction date")
        if transaction_date > as_of:
            continue
        transaction_date = max(transaction_date, start_date)
        accrue_to(transaction_date)
        signed_amount = _jashflow_signed_amount(row)
        if row.get("transaction_type") == "payment":
            payments_total = _money(payments_total + abs(signed_amount))
        elif row.get("transaction_type") in ("fee", "charge"):
            charges_total = _money(charges_total + signed_amount)
        balance = _money(balance + signed_amount)
        balance_before_interest = _money(balance_before_interest + signed_amount)

    accrue_to(as_of)
    duration_months = max(1, int(loan.get("duration_months") or 1))
    if monthly_rate:
        monthly_repayment = _money(float(base) * (monthly_rate * ((1 + monthly_rate) ** duration_months)) / (((1 + monthly_rate) ** duration_months) - 1))
    else:
        monthly_repayment = _money(base / Decimal(duration_months))
    return {
        "daysAccrued": elapsed_days,
        "dailyInterestRate": daily_rate,
        "paymentsTotal": payments_total,
        "chargesTotal": charges_total,
        "accruedInterest": accrued_interest,
        "balance": balance,
        "balanceBeforeInterest": balance_before_interest,
        "monthlyRepayment": monthly_repayment,
    }


def _serialize_jashflow_loan(
    loan: dict,
    transactions: list[dict],
    invoiced_interest_total: Decimal | None = None,
    history: list[dict] | None = None,
) -> dict:
    invoiced_interest_total = _money(invoiced_interest_total)
    summary = _jashflow_interest_summary(loan, transactions)
    payments_total = _money(summary["paymentsTotal"])
    charges_total = _money(summary["chargesTotal"])
    uninvoiced_interest = max(Decimal("0.00"), _money(summary["accruedInterest"] - invoiced_interest_total))
    running_balance = Decimal("0.00")
    statement_rows = []
    for row in sorted(transactions, key=_jashflow_transaction_sort_key):
        signed_amount = _jashflow_signed_amount(row)
        running_balance = _money(running_balance + signed_amount)
        statement_rows.append({
            "id": str(row.get("id")),
            "date": _iso(row.get("transaction_date")) or "",
            "type": row.get("transaction_type") or "adjustment",
            "description": row.get("description") or "",
            "amount": float(signed_amount),
            "debit": float(signed_amount if signed_amount > 0 else Decimal("0.00")),
            "credit": float(abs(signed_amount) if signed_amount < 0 else Decimal("0.00")),
            "balance": float(running_balance),
            "createdAt": _iso(row.get("created_at")) or "",
            "isVirtual": False,
        })
    if summary["accruedInterest"] > 0:
        running_balance = _money(running_balance + summary["accruedInterest"])
        statement_rows.append({
            "id": f"{loan['id']}:interest",
            "date": utcnow().date().isoformat(),
            "type": "interest",
            "description": f"Daily compound interest accrued over {summary['daysAccrued']} day{'s' if summary['daysAccrued'] != 1 else ''}",
            "amount": float(summary["accruedInterest"]),
            "debit": float(summary["accruedInterest"]),
            "credit": 0,
            "balance": float(running_balance),
            "createdAt": "",
            "isVirtual": True,
        })

    return {
        "id": str(loan["id"]),
        "customerId": str(loan.get("customer_id")),
        "customerName": loan.get("customer_name") or "Unnamed client",
        "xeroContactId": loan.get("xero_contact_id") or "",
        "principalAmount": float(_money(loan.get("principal_amount"))),
        "arrangementFee": float(_money(loan.get("arrangement_fee"))),
        "annualInterestRate": float(_rate_percent(loan.get("annual_interest_rate"))),
        "durationMonths": int(loan.get("duration_months") or 0),
        "startDate": _iso(loan.get("start_date")) or "",
        "notes": loan.get("notes") or "",
        "status": loan.get("status") or "active",
        "createdAt": _iso(loan.get("created_at")) or "",
        "updatedAt": _iso(loan.get("updated_at")) or "",
        "daysAccrued": summary["daysAccrued"],
        "dailyInterestRate": summary["dailyInterestRate"],
        "accruedInterest": float(summary["accruedInterest"]),
        "invoicedInterest": float(invoiced_interest_total),
        "uninvoicedInterest": float(uninvoiced_interest),
        "paymentsTotal": float(payments_total),
        "chargesTotal": float(charges_total),
        "balance": float(summary["balance"]),
        "balanceBeforeInterest": float(summary["balanceBeforeInterest"]),
        "monthlyRepayment": float(summary["monthlyRepayment"]),
        "transactions": statement_rows,
        "history": [_serialize_jashflow_history_event(row) for row in (history or [])],
    }


def _jashflow_xero_account_options(cursor, user: dict, tenant_id: str) -> list[dict]:
    cursor.execute(
        """
        SELECT DISTINCT ON (mappings.account_code)
               mappings.account_code, mappings.account_name, mappings.account_type, mappings.updated_at,
               clients.last_sync_at
        FROM me_report_account_mappings AS mappings
        JOIN me_report_clients AS clients ON clients.id = mappings.client_id
        WHERE clients.user_id = %s
          AND (clients.xero_tenant_id = %s OR clients.xero_tenant_id IS NULL OR clients.xero_tenant_id = '')
          AND mappings.account_code <> ''
        ORDER BY mappings.account_code ASC, clients.last_sync_at DESC NULLS LAST, mappings.updated_at DESC
        """,
        (user["id"], tenant_id),
    )
    rows = cursor.fetchall()
    return [
        {
            "code": row.get("account_code") or "",
            "name": row.get("account_name") or "",
            "type": row.get("account_type") or "",
            "syncedAt": _iso(row.get("last_sync_at") or row.get("updated_at")) or "",
        }
        for row in rows
    ]


def jashflow_payload(user: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, name, email, xero_contact_id
                FROM customers
                WHERE tenant_id = %s
                ORDER BY name ASC
                """,
                (tenant_id,),
            )
            customers = cursor.fetchall()
            cursor.execute(
                """
                SELECT loans.*, customers.name AS customer_name, customers.xero_contact_id
                FROM jashflow_loans AS loans
                JOIN customers ON customers.id = loans.customer_id
                WHERE loans.tenant_id = %s
                ORDER BY loans.created_at DESC
                """,
                (tenant_id,),
            )
            loan_rows = cursor.fetchall()
            loan_ids = [row["id"] for row in loan_rows]
            loan_id_strings = [str(row["id"]) for row in loan_rows]
            transactions_by_loan = defaultdict(list)
            interest_posted_by_loan = defaultdict(lambda: Decimal("0.00"))
            history_by_loan = defaultdict(list)
            if loan_ids:
                cursor.execute(
                    """
                    SELECT *
                    FROM jashflow_transactions
                    WHERE loan_id = ANY(%s)
                    ORDER BY transaction_date ASC, created_at ASC
                    """,
                    (loan_ids,),
                )
                for row in cursor.fetchall():
                    transactions_by_loan[str(row["loan_id"])].append(row)
                cursor.execute(
                    """
                    SELECT lines.loan_id, COALESCE(SUM(lines.interest_amount), 0) AS posted_interest
                    FROM jashflow_interest_post_lines AS lines
                    JOIN jashflow_interest_post_batches AS batches ON batches.id = lines.batch_id
                    WHERE lines.loan_id = ANY(%s)
                      AND batches.status = 'completed'
                    GROUP BY lines.loan_id
                    """,
                    (loan_ids,),
                )
                for row in cursor.fetchall():
                    interest_posted_by_loan[str(row["loan_id"])] = _money(row.get("posted_interest"))
                cursor.execute(
                    """
                    SELECT audit_events.*, users.full_name, users.email
                    FROM audit_events
                    LEFT JOIN users ON users.id = audit_events.user_id
                    WHERE audit_events.entity_type = 'jashflow_loan'
                      AND audit_events.entity_id = ANY(%s)
                    ORDER BY audit_events.created_at DESC
                    """,
                    (loan_id_strings,),
                )
                for row in cursor.fetchall():
                    history_by_loan[str(row["entity_id"])].append(row)
            cursor.execute(
                """
                SELECT *
                FROM jashflow_settings
                WHERE tenant_id = %s
                """,
                (tenant_id,),
            )
            settings_row = cursor.fetchone() or {}
            cursor.execute(
                """
                SELECT *
                FROM jashflow_interest_post_batches
                WHERE tenant_id = %s
                  AND status = 'completed'
                ORDER BY created_at DESC
                LIMIT 10
                """,
                (tenant_id,),
            )
            interest_posts = cursor.fetchall()
            xero_accounts = _jashflow_xero_account_options(cursor, user, tenant_id)
        connection.commit()

    loans = [
        _serialize_jashflow_loan(
            row,
            transactions_by_loan.get(str(row["id"]), []),
            interest_posted_by_loan.get(str(row["id"]), Decimal("0.00")),
            history_by_loan.get(str(row["id"]), []),
        )
        for row in loan_rows
    ]
    active_loans = [loan for loan in loans if loan["status"] == "active"]
    return {
        "customers": [
            {
                "id": str(customer["id"]),
                "name": customer.get("name") or "Unnamed client",
                "email": customer.get("email") or "",
                "xeroContactId": customer.get("xero_contact_id") or "",
            }
            for customer in customers
        ],
        "loans": loans,
        "summary": {
            "activeLoans": len(active_loans),
            "principalTotal": round(sum(loan["principalAmount"] for loan in active_loans), 2),
            "accruedInterestTotal": round(sum(loan["accruedInterest"] for loan in active_loans), 2),
            "invoicedInterestTotal": round(sum(loan["invoicedInterest"] for loan in active_loans), 2),
            "uninvoicedInterestTotal": round(sum(loan["uninvoicedInterest"] for loan in active_loans), 2),
            "chargesTotal": round(sum(loan["chargesTotal"] for loan in active_loans), 2),
            "paymentsTotal": round(sum(loan["paymentsTotal"] for loan in active_loans), 2),
            "balanceTotal": round(sum(loan["balance"] for loan in active_loans), 2),
        },
        "settings": {
            "invoiceContactId": settings_row.get("invoice_contact_id") or "",
            "invoiceContactName": settings_row.get("invoice_contact_name") or "",
            "interestAccountCode": settings_row.get("interest_account_code") or "",
            "updatedAt": _iso(settings_row.get("updated_at")) or "",
        },
        "xeroAccounts": xero_accounts,
        "interestPosts": [
            {
                "id": str(row["id"]),
                "status": row.get("status") or "",
                "xeroInvoiceId": row.get("xero_invoice_id") or "",
                "xeroInvoiceNumber": row.get("xero_invoice_number") or "",
                "invoiceContactName": row.get("invoice_contact_name") or "",
                "interestAccountCode": row.get("interest_account_code") or "",
                "periodEndDate": _iso(row.get("period_end_date")) or "",
                "totalInterestAmount": float(_money(row.get("total_interest_amount"))),
                "attachmentFilename": row.get("attachment_filename") or "",
                "createdAt": _iso(row.get("created_at")) or "",
                "completedAt": _iso(row.get("completed_at")) or "",
            }
            for row in interest_posts
        ],
    }


def create_jashflow_loan(user: dict, payload: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    customer_id = str(payload.get("customerId") or "").strip()
    if not customer_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose a Xero customer for the loan.")
    principal = _positive_money(payload.get("principalAmount"), "Loan amount")
    arrangement_fee = _non_negative_money(payload.get("arrangementFee"), "Arrangement fee")
    annual_interest_rate = _rate_percent(payload.get("annualInterestRate"), "Compound interest rate")
    try:
        duration_months = int(payload.get("durationMonths") or 0)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Duration must be a number of months.") from exc
    if duration_months < 1 or duration_months > 240:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Duration must be between 1 and 240 months.")
    start_date = _parse_iso_date(payload.get("startDate"), "Start date")
    notes = str(payload.get("notes") or "").strip()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, name
                FROM customers
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (customer_id, tenant_id),
            )
            customer = cursor.fetchone()
            if customer is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Customer not found in this Xero tenant.")
            cursor.execute(
                """
                INSERT INTO jashflow_loans (
                    tenant_id, customer_id, principal_amount, arrangement_fee,
                    annual_interest_rate, duration_months, start_date, notes, status,
                    created_by_user_id, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 'active', %s, %s, %s)
                RETURNING id
                """,
                (tenant_id, customer_id, principal, arrangement_fee, annual_interest_rate, duration_months, start_date, notes, user["id"], utcnow(), utcnow()),
            )
            loan_id = cursor.fetchone()["id"]
            cursor.execute(
                """
                INSERT INTO jashflow_transactions (
                    loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                )
                VALUES (%s, %s, 'advance', %s, 'Loan advance', %s)
                """,
                (loan_id, start_date, principal, user["id"]),
            )
            if arrangement_fee > 0:
                cursor.execute(
                    """
                    INSERT INTO jashflow_transactions (
                        loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                    )
                    VALUES (%s, %s, 'fee', %s, 'Arrangement fee', %s)
                    """,
                    (loan_id, start_date, arrangement_fee, user["id"]),
                )
        connection.commit()

    record_audit_event(
        "jashflow_loan",
        str(loan_id),
        "jashflow.loan_created",
        {
            "customer_id": customer_id,
            "customer_name": customer.get("name") or "",
            "principal_amount": float(principal),
            "arrangement_fee": float(arrangement_fee),
            "annual_interest_rate": float(annual_interest_rate),
            "duration_months": duration_months,
            "start_date": start_date.isoformat(),
            "notes": notes,
        },
        user["id"],
    )
    return jashflow_payload(user)


def update_jashflow_loan(user: dict, loan_id: str, payload: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    customer_id = str(payload.get("customerId") or "").strip()
    if not customer_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose a Xero customer for the loan.")
    principal = _positive_money(payload.get("principalAmount"), "Loan amount")
    arrangement_fee = _non_negative_money(payload.get("arrangementFee"), "Arrangement fee")
    annual_interest_rate = _rate_percent(payload.get("annualInterestRate"), "Compound interest rate")
    try:
        duration_months = int(payload.get("durationMonths") or 0)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Duration must be a number of months.") from exc
    if duration_months < 1 or duration_months > 240:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Duration must be between 1 and 240 months.")
    start_date = _parse_iso_date(payload.get("startDate"), "Start date")
    status_value = str(payload.get("status") or "active").strip().lower()
    if status_value not in {"active", "closed"}:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Loan status must be active or closed.")
    notes = str(payload.get("notes") or "").strip()
    audit_action = str(payload.get("auditAction") or "").strip().lower()
    changes = []

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT loans.*, customers.name AS customer_name
                FROM jashflow_loans AS loans
                JOIN customers ON customers.id = loans.customer_id
                WHERE loans.id = %s
                  AND loans.tenant_id = %s
                """,
                (loan_id, tenant_id),
            )
            old_loan = cursor.fetchone()
            if old_loan is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Jashflow loan not found.")
            cursor.execute(
                """
                SELECT id, name
                FROM customers
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (customer_id, tenant_id),
            )
            new_customer = cursor.fetchone()
            if new_customer is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Customer not found in this Xero tenant.")
            if str(old_loan.get("customer_id")) != customer_id:
                changes.append(_jashflow_change_entry(
                    "customerId",
                    "Client",
                    old_loan.get("customer_name") or str(old_loan.get("customer_id")),
                    new_customer.get("name") or customer_id,
                ))
            old_principal = _money(old_loan.get("principal_amount"))
            if old_principal != principal:
                changes.append(_jashflow_change_entry("principalAmount", "Loan amount", float(old_principal), float(principal), "currency"))
            old_arrangement_fee = _money(old_loan.get("arrangement_fee"))
            if old_arrangement_fee != arrangement_fee:
                changes.append(_jashflow_change_entry("arrangementFee", "Arrangement fee", float(old_arrangement_fee), float(arrangement_fee), "currency"))
            old_annual_interest_rate = _rate_percent(old_loan.get("annual_interest_rate"))
            if old_annual_interest_rate != annual_interest_rate:
                changes.append(_jashflow_change_entry("annualInterestRate", "Compound interest", float(old_annual_interest_rate), float(annual_interest_rate), "percentage"))
            old_duration_months = int(old_loan.get("duration_months") or 0)
            if old_duration_months != duration_months:
                changes.append(_jashflow_change_entry("durationMonths", "Term", old_duration_months, duration_months, "months"))
            old_start_date = _iso(old_loan.get("start_date")) or ""
            if old_start_date != start_date.isoformat():
                changes.append(_jashflow_change_entry("startDate", "Start date", old_start_date, start_date.isoformat(), "date"))
            old_notes = str(old_loan.get("notes") or "").strip()
            if old_notes != notes:
                changes.append(_jashflow_change_entry("notes", "Loan notes", old_notes, notes, "text"))
            old_status = str(old_loan.get("status") or "active").strip().lower()
            if old_status != status_value:
                changes.append(_jashflow_change_entry("status", "Status", old_status, status_value))
            cursor.execute(
                """
                UPDATE jashflow_loans
                SET customer_id = %s,
                    principal_amount = %s,
                    arrangement_fee = %s,
                    annual_interest_rate = %s,
                    duration_months = %s,
                    start_date = %s,
                    notes = %s,
                    status = %s,
                    updated_at = %s
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (
                    customer_id,
                    principal,
                    arrangement_fee,
                    annual_interest_rate,
                    duration_months,
                    start_date,
                    notes,
                    status_value,
                    utcnow(),
                    loan_id,
                    tenant_id,
                ),
            )
            cursor.execute(
                """
                DELETE FROM jashflow_transactions
                WHERE loan_id = %s
                  AND transaction_type IN ('advance', 'fee')
                """,
                (loan_id,),
            )
            cursor.execute(
                """
                INSERT INTO jashflow_transactions (
                    loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                )
                VALUES (%s, %s, 'advance', %s, 'Loan advance', %s)
                """,
                (loan_id, start_date, principal, user["id"]),
            )
            if arrangement_fee > 0:
                cursor.execute(
                    """
                    INSERT INTO jashflow_transactions (
                        loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                    )
                    VALUES (%s, %s, 'fee', %s, 'Arrangement fee', %s)
                    """,
                    (loan_id, start_date, arrangement_fee, user["id"]),
                )
        connection.commit()

    if changes or audit_action == "recalculate":
        record_audit_event(
            "jashflow_loan",
            str(loan_id),
            "jashflow.loan_updated" if changes else "jashflow.loan_recalculated",
            {
                "customer_id": customer_id,
                "customer_name": new_customer.get("name") or "",
                "principal_amount": float(principal),
                "arrangement_fee": float(arrangement_fee),
                "annual_interest_rate": float(annual_interest_rate),
                "duration_months": duration_months,
                "start_date": start_date.isoformat(),
                "status": status_value,
                "notes": notes,
                "changes": changes,
                "message": "" if changes else "Interest recalculated from the loan start date.",
            },
            user["id"],
        )
    return jashflow_payload(user)


def delete_jashflow_loan(user: dict, loan_id: str) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT loans.*, customers.name AS customer_name
                FROM jashflow_loans AS loans
                JOIN customers ON customers.id = loans.customer_id
                WHERE loans.id = %s
                  AND loans.tenant_id = %s
                """,
                (loan_id, tenant_id),
            )
            loan = cursor.fetchone()
            if loan is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Jashflow loan not found.")
            cursor.execute(
                """
                DELETE FROM jashflow_loans
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (loan_id, tenant_id),
            )
        connection.commit()

    record_audit_event(
        "jashflow_loan",
        str(loan_id),
        "jashflow.loan_deleted",
        {
            "customer_id": str(loan.get("customer_id") or ""),
            "customer_name": loan.get("customer_name") or "",
            "principal_amount": float(_money(loan.get("principal_amount"))),
            "arrangement_fee": float(_money(loan.get("arrangement_fee"))),
            "annual_interest_rate": float(_rate_percent(loan.get("annual_interest_rate"))),
            "duration_months": int(loan.get("duration_months") or 0),
            "start_date": _iso(loan.get("start_date")) or "",
            "status": loan.get("status") or "active",
            "notes": loan.get("notes") or "",
            "deleted_at": _iso(utcnow()) or "",
        },
        user["id"],
    )
    return jashflow_payload(user)


def add_jashflow_charge(user: dict, loan_id: str, payload: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    amount = _positive_money(payload.get("amount"), "Charge amount")
    charge_date = _parse_iso_date(payload.get("chargeDate") or payload.get("transactionDate"), "Charge date")
    description = str(payload.get("description") or "Loan charge").strip()[:500]

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id
                FROM jashflow_loans
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (loan_id, tenant_id),
            )
            if cursor.fetchone() is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Jashflow loan not found.")
            cursor.execute(
                """
                INSERT INTO jashflow_transactions (
                    loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                )
                VALUES (%s, %s, 'charge', %s, %s, %s)
                RETURNING id
                """,
                (loan_id, charge_date, amount, description, user["id"]),
            )
            transaction_id = cursor.fetchone()["id"]
            cursor.execute(
                """
                UPDATE jashflow_loans
                SET updated_at = %s
                WHERE id = %s
                """,
                (utcnow(), loan_id),
            )
        connection.commit()

    record_audit_event(
        "jashflow_loan",
        str(loan_id),
        "jashflow.charge_added",
        {
            "transaction_id": str(transaction_id),
            "amount": float(amount),
            "charge_date": charge_date.isoformat(),
            "description": description,
        },
        user["id"],
    )
    return jashflow_payload(user)


def add_jashflow_payment(user: dict, loan_id: str, payload: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    amount = _positive_money(payload.get("amount"), "Payment amount")
    payment_date = _parse_iso_date(payload.get("paymentDate"), "Payment date")
    description = str(payload.get("description") or "Payment received").strip()[:500]

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id
                FROM jashflow_loans
                WHERE id = %s
                  AND tenant_id = %s
                """,
                (loan_id, tenant_id),
            )
            if cursor.fetchone() is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Jashflow loan not found.")
            cursor.execute(
                """
                INSERT INTO jashflow_transactions (
                    loan_id, transaction_date, transaction_type, amount, description, created_by_user_id
                )
                VALUES (%s, %s, 'payment', %s, %s, %s)
                RETURNING id
                """,
                (loan_id, payment_date, amount, description, user["id"]),
            )
            transaction_id = cursor.fetchone()["id"]
            cursor.execute(
                """
                UPDATE jashflow_loans
                SET updated_at = %s
                WHERE id = %s
                """,
                (utcnow(), loan_id),
            )
        connection.commit()

    record_audit_event(
        "jashflow_loan",
        str(loan_id),
        "jashflow.payment_added",
        {
            "transaction_id": str(transaction_id),
            "amount": float(amount),
            "payment_date": payment_date.isoformat(),
            "description": description,
        },
        user["id"],
    )
    return {
        "loanId": str(loan_id),
        "transactionId": str(transaction_id),
        "amount": float(amount),
        "paymentDate": payment_date.isoformat(),
        "description": description,
    }


def save_jashflow_settings(user: dict, payload: dict) -> dict:
    tenant_id = _jashflow_tenant_id(user)
    customer_id = str(payload.get("invoiceContactCustomerId") or payload.get("customerId") or "").strip()
    account_code = str(payload.get("interestAccountCode") or "").strip()
    if not account_code:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Enter the Xero interest received account code.")

    invoice_contact_id = ""
    invoice_contact_name = ""
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if customer_id:
                cursor.execute(
                    """
                    SELECT name, xero_contact_id
                    FROM customers
                    WHERE id = %s
                      AND tenant_id = %s
                    """,
                    (customer_id, tenant_id),
                )
                customer = cursor.fetchone()
                if customer is None:
                    raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Selected invoice contact was not found in this Xero tenant.")
                invoice_contact_id = customer.get("xero_contact_id") or ""
                invoice_contact_name = customer.get("name") or ""
            cursor.execute(
                """
                INSERT INTO jashflow_settings (
                    tenant_id, invoice_contact_id, invoice_contact_name,
                    interest_account_code, updated_by_user_id, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (tenant_id) DO UPDATE
                SET invoice_contact_id = EXCLUDED.invoice_contact_id,
                    invoice_contact_name = EXCLUDED.invoice_contact_name,
                    interest_account_code = EXCLUDED.interest_account_code,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = EXCLUDED.updated_at
                """,
                (tenant_id, invoice_contact_id, invoice_contact_name, account_code, user["id"], utcnow(), utcnow()),
            )
        connection.commit()

    record_audit_event(
        "jashflow_settings",
        tenant_id,
        "jashflow.settings_saved",
        {"invoice_contact_name": invoice_contact_name, "interest_account_code": account_code},
        user["id"],
    )
    return jashflow_payload(user)


def _xlsx_column_name(index: int) -> str:
    name = ""
    while index:
        index, remainder = divmod(index - 1, 26)
        name = chr(65 + remainder) + name
    return name


def _xlsx_cell(reference: str, value) -> str:
    if isinstance(value, (int, float, Decimal)):
        return f'<c r="{reference}"><v>{value}</v></c>'
    text = xml_escape(str(value if value is not None else ""))
    return f'<c r="{reference}" t="inlineStr"><is><t>{text}</t></is></c>'


def _build_simple_xlsx_workbook(rows: list[list], sheet_name: str = "Sheet1") -> bytes:
    sheet_rows = []
    for row_index, row in enumerate(rows, start=1):
        cells = [
            _xlsx_cell(f"{_xlsx_column_name(column_index)}{row_index}", value)
            for column_index, value in enumerate(row, start=1)
        ]
        sheet_rows.append(f'<row r="{row_index}">{"".join(cells)}</row>')
    safe_sheet_name = xml_escape(str(sheet_name or "Sheet1")[:31])
    worksheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        '<sheetData>'
        f'{"".join(sheet_rows)}'
        '</sheetData>'
        '</worksheet>'
    )
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as workbook:
        workbook.writestr(
            "[Content_Types].xml",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
            '<Default Extension="xml" ContentType="application/xml"/>'
            '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
            '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
            '</Types>',
        )
        workbook.writestr(
            "_rels/.rels",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
            '</Relationships>',
        )
        workbook.writestr(
            "xl/workbook.xml",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
            'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
            f'<sheets><sheet name="{safe_sheet_name}" sheetId="1" r:id="rId1"/></sheets>'
            '</workbook>',
        )
        workbook.writestr(
            "xl/_rels/workbook.xml.rels",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
            '</Relationships>',
        )
        workbook.writestr("xl/worksheets/sheet1.xml", worksheet_xml)
    return buffer.getvalue()


def _build_jashflow_interest_workbook(lines: list[dict], period_end: date, total: Decimal) -> bytes:
    rows = [
        ["Client", "Xero Contact ID", "Loan ID", "Period End", "Accrued Interest", "Previously Posted", "Posting Now", "Loan Balance"],
        *[
            [
                line["customerName"],
                line["xeroContactId"],
                line["loanId"],
                period_end.isoformat(),
                f"{line['accruedInterest']:.2f}",
                f"{line['previouslyPosted']:.2f}",
                f"{line['interestAmount']:.2f}",
                f"{line['balance']:.2f}",
            ]
            for line in lines
        ],
        ["", "", "", "Total", "", "", f"{total:.2f}", ""],
    ]
    sheet_rows = []
    for row_index, row in enumerate(rows, start=1):
        cells = [
            _xlsx_cell(f"{_xlsx_column_name(column_index)}{row_index}", value)
            for column_index, value in enumerate(row, start=1)
        ]
        sheet_rows.append(f'<row r="{row_index}">{"".join(cells)}</row>')
    worksheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
        '<sheetData>'
        f'{"".join(sheet_rows)}'
        '</sheetData>'
        '</worksheet>'
    )
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as workbook:
        workbook.writestr(
            "[Content_Types].xml",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
            '<Default Extension="xml" ContentType="application/xml"/>'
            '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
            '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
            '</Types>',
        )
        workbook.writestr(
            "_rels/.rels",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
            '</Relationships>',
        )
        workbook.writestr(
            "xl/workbook.xml",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
            'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
            '<sheets><sheet name="Interest" sheetId="1" r:id="rId1"/></sheets>'
            '</workbook>',
        )
        workbook.writestr(
            "xl/_rels/workbook.xml.rels",
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
            '</Relationships>',
        )
        workbook.writestr("xl/worksheets/sheet1.xml", worksheet_xml)
    return buffer.getvalue()


def _jashflow_interest_lines_for_period(
    user: dict,
    period_end: date,
    period_start: date | None = None,
) -> tuple[str, str, list[dict], dict]:
    tenant_id = _jashflow_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT loans.*, customers.name AS customer_name, customers.xero_contact_id
                FROM jashflow_loans AS loans
                JOIN customers ON customers.id = loans.customer_id
                WHERE loans.tenant_id = %s
                  AND loans.status = 'active'
                ORDER BY loans.created_at DESC
                """,
                (tenant_id,),
            )
            loan_rows = cursor.fetchall()
            loan_ids = [row["id"] for row in loan_rows]
            transactions_by_loan = defaultdict(list)
            posted_interest_to_end_by_loan = defaultdict(lambda: Decimal("0.00"))
            posted_interest_to_start_by_loan = defaultdict(lambda: Decimal("0.00"))
            last_posted_up_to_by_loan = {}
            cursor.execute(
                """
                SELECT MAX(period_end_date) AS last_posted_up_to
                FROM jashflow_interest_post_batches
                WHERE tenant_id = %s
                  AND status = 'completed'
                  AND period_end_date <= %s
                """,
                (tenant_id, period_end),
            )
            latest_posted_row = cursor.fetchone() or {}
            latest_posted_up_to = latest_posted_row.get("last_posted_up_to")
            effective_period_start = period_start or latest_posted_up_to
            if loan_ids:
                cursor.execute(
                    """
                    SELECT *
                    FROM jashflow_transactions
                    WHERE loan_id = ANY(%s)
                    ORDER BY transaction_date ASC, created_at ASC
                    """,
                    (loan_ids,),
                )
                for row in cursor.fetchall():
                    transactions_by_loan[str(row["loan_id"])].append(row)
                cursor.execute(
                    """
                    SELECT
                        lines.loan_id,
                        COALESCE(SUM(CASE WHEN lines.period_end_date <= %s THEN lines.interest_amount ELSE 0 END), 0) AS posted_interest_to_end,
                        COALESCE(SUM(CASE WHEN lines.period_end_date <= %s THEN lines.interest_amount ELSE 0 END), 0) AS posted_interest_to_start,
                        MAX(CASE WHEN lines.period_end_date <= %s THEN lines.period_end_date END) AS last_posted_up_to
                    FROM jashflow_interest_post_lines AS lines
                    JOIN jashflow_interest_post_batches AS batches ON batches.id = lines.batch_id
                    WHERE lines.loan_id = ANY(%s)
                      AND batches.status = 'completed'
                    GROUP BY lines.loan_id
                    """,
                    (
                        period_end,
                        effective_period_start or date.min,
                        period_end,
                        loan_ids,
                    ),
                )
                for row in cursor.fetchall():
                    loan_key = str(row["loan_id"])
                    posted_interest_to_end_by_loan[loan_key] = _money(row.get("posted_interest_to_end"))
                    posted_interest_to_start_by_loan[loan_key] = _money(row.get("posted_interest_to_start"))
                    last_posted_up_to_by_loan[loan_key] = row.get("last_posted_up_to")
            cursor.execute(
                """
                SELECT *
                FROM jashflow_settings
                WHERE tenant_id = %s
                """,
                (tenant_id,),
            )
            settings_row = cursor.fetchone() or {}
        connection.commit()

    account_code = str(settings_row.get("interest_account_code") or "").strip()
    lines = []
    effective_period_start = period_start or latest_posted_up_to
    for loan in loan_rows:
        loan_id = str(loan["id"])
        transactions = transactions_by_loan.get(loan_id, [])
        summary_to_end = _jashflow_interest_summary(loan, transactions, as_of=period_end)
        summary_to_start = _jashflow_interest_summary(loan, transactions, as_of=effective_period_start) if effective_period_start else None
        accrued_to_end = _money(summary_to_end["accruedInterest"])
        accrued_to_start = _money(summary_to_start["accruedInterest"]) if summary_to_start else Decimal("0.00")
        posted_to_end = posted_interest_to_end_by_loan.get(loan_id, Decimal("0.00"))
        posted_to_start = posted_interest_to_start_by_loan.get(loan_id, Decimal("0.00"))
        unposted_to_end = max(Decimal("0.00"), _money(accrued_to_end - posted_to_end))
        unposted_to_start = max(Decimal("0.00"), _money(accrued_to_start - posted_to_start))
        period_interest_amount = max(Decimal("0.00"), _money(unposted_to_end - unposted_to_start))
        catch_up_interest_amount = unposted_to_start
        interest_amount = _money(period_interest_amount + catch_up_interest_amount)
        if interest_amount < Decimal("0.01"):
            continue
        loan_start_date = loan.get("start_date")
        if isinstance(loan_start_date, datetime):
            loan_start_date = loan_start_date.date()
        elif loan_start_date and not isinstance(loan_start_date, date):
            loan_start_date = _parse_iso_date(loan_start_date, "Loan start date")
        catch_up_start = loan_start_date if catch_up_interest_amount >= Decimal("0.01") else None
        catch_up_end = effective_period_start if catch_up_interest_amount >= Decimal("0.01") else None
        last_posted_up_to = last_posted_up_to_by_loan.get(loan_id)
        lines.append(
            {
                "loanId": loan_id,
                "customerId": str(loan.get("customer_id") or ""),
                "customerName": loan.get("customer_name") or "Unnamed client",
                "xeroContactId": loan.get("xero_contact_id") or "",
                "loanStartDate": _iso(loan_start_date) or "",
                "periodStartDate": _iso(effective_period_start) or "",
                "periodEndDate": _iso(period_end) or "",
                "accruedInterest": _money(accrued_to_end),
                "accruedInterestToStart": _money(accrued_to_start),
                "previouslyPosted": _money(posted_to_end),
                "previouslyPostedToStart": _money(posted_to_start),
                "periodInterestAmount": _money(period_interest_amount),
                "catchUpInterestAmount": _money(catch_up_interest_amount),
                "catchUpRequired": bool(catch_up_interest_amount >= Decimal("0.01")),
                "catchUpStartDate": _iso(catch_up_start) or "",
                "catchUpEndDate": _iso(catch_up_end) or "",
                "lastPostedUpTo": _iso(last_posted_up_to) or "",
                "interestAmount": _money(interest_amount),
                "balance": _money(summary_to_end["balance"]),
                "daysAccrued": int(summary_to_end.get("daysAccrued") or 0),
            }
        )
    lines.sort(key=lambda item: (item["interestAmount"], item["customerName"]), reverse=True)
    metadata = {
        "periodStartDate": _iso(effective_period_start) or "",
        "periodEndDate": _iso(period_end) or "",
        "lastPostedUpTo": _iso(latest_posted_up_to) or "",
    }
    return tenant_id, account_code, lines, metadata


def jashflow_interest_preview(user: dict, payload: dict | None = None) -> dict:
    payload = payload or {}
    period_end = _parse_iso_date(payload.get("periodEndDate") or utcnow().date(), "Period end date")
    period_start = _parse_iso_date(payload.get("periodStartDate"), "Period start date") if payload.get("periodStartDate") else None
    _, account_code, lines, metadata = _jashflow_interest_lines_for_period(user, period_end, period_start=period_start)
    total = _money(sum((line["interestAmount"] for line in lines), Decimal("0.00")))
    catch_up_loan_count = sum(1 for line in lines if line.get("catchUpRequired"))
    catch_up_interest_total = _money(sum((line["catchUpInterestAmount"] for line in lines), Decimal("0.00")))
    period_interest_total = _money(sum((line["periodInterestAmount"] for line in lines), Decimal("0.00")))
    clients = {}
    for line in lines:
        key = line["customerId"] or line["customerName"]
        current = clients.get(key) or {"customerId": line["customerId"], "customerName": line["customerName"], "loanCount": 0, "interestAmount": Decimal("0.00")}
        current["loanCount"] += 1
        current["interestAmount"] = _money(current["interestAmount"] + line["interestAmount"])
        clients[key] = current
    return {
        "periodStartDate": metadata["periodStartDate"],
        "periodEndDate": metadata["periodEndDate"],
        "lastPostedUpTo": metadata["lastPostedUpTo"],
        "interestAccountCode": account_code,
        "lineCount": len(lines),
        "clientCount": len(clients),
        "totalInterestAmount": float(total),
        "periodInterestTotal": float(period_interest_total),
        "catchUpInterestTotal": float(catch_up_interest_total),
        "catchUpLoanCount": int(catch_up_loan_count),
        "clients": [
            {
                "customerId": row["customerId"],
                "customerName": row["customerName"],
                "loanCount": int(row["loanCount"]),
                "interestAmount": float(_money(row["interestAmount"])),
            }
            for row in sorted(clients.values(), key=lambda item: (item["interestAmount"], item["customerName"]), reverse=True)
        ],
        "loanRows": [
            {
                "loanId": line["loanId"],
                "customerId": line["customerId"],
                "customerName": line["customerName"],
                "loanStartDate": line["loanStartDate"],
                "periodStartDate": line["periodStartDate"],
                "periodEndDate": line["periodEndDate"],
                "accruedInterest": float(line["accruedInterest"]),
                "accruedInterestToStart": float(line["accruedInterestToStart"]),
                "previouslyPosted": float(line["previouslyPosted"]),
                "previouslyPostedToStart": float(line["previouslyPostedToStart"]),
                "periodInterestAmount": float(line["periodInterestAmount"]),
                "catchUpInterestAmount": float(line["catchUpInterestAmount"]),
                "catchUpRequired": bool(line["catchUpRequired"]),
                "catchUpStartDate": line["catchUpStartDate"],
                "catchUpEndDate": line["catchUpEndDate"],
                "lastPostedUpTo": line["lastPostedUpTo"],
                "interestAmount": float(line["interestAmount"]),
                "balance": float(line["balance"]),
                "daysAccrued": line["daysAccrued"],
            }
            for line in lines
        ],
    }


async def post_jashflow_interest_invoice(user: dict, payload: dict | None = None) -> dict:
    payload = payload or {}
    period_end = _parse_iso_date(payload.get("periodEndDate") or utcnow().date(), "Period end date")
    period_start = _parse_iso_date(payload.get("periodStartDate"), "Period start date") if payload.get("periodStartDate") else None
    tenant_id, account_code, lines, metadata = _jashflow_interest_lines_for_period(user, period_end, period_start=period_start)
    if not account_code:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Save the Jashflow interest received account code before posting interest.")
    if not lines:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="There is no uninvoiced Jashflow interest to post.")

    total = sum((line["interestAmount"] for line in lines), Decimal("0.00")).quantize(Decimal("0.01"))
    connection_row = get_xero_connection_for_user(user["id"])
    created_invoices = []
    for line in lines:
        contact = {"ContactID": line["xeroContactId"]} if line.get("xeroContactId") else {"Name": line["customerName"]}
        invoice_payload = {
            "Type": "ACCREC",
            "Contact": contact,
            "Date": period_end.isoformat(),
            "DueDate": period_end.isoformat(),
            "Reference": f"Jashflow interest to {period_end.isoformat()}",
            "LineAmountTypes": "NoTax",
            "Status": "AUTHORISED",
            "LineItems": [
                {
                    "Description": (
                        f"Jashflow interest for {_invoice_date_description(period_start)} to {_invoice_date_description(period_end)} "
                        f"for {line['customerName']}."
                        if period_start
                        else f"Jashflow interest earned to {_invoice_date_description(period_end)} for {line['customerName']}."
                    ) + (
                        f" Catch-up included for {_invoice_date_description(_parse_iso_date(line['catchUpStartDate'], 'Catch-up start date'))}"
                        f" to {_invoice_date_description(_parse_iso_date(line['catchUpEndDate'], 'Catch-up end date'))}."
                        if line.get("catchUpRequired") and line.get("catchUpStartDate") and line.get("catchUpEndDate")
                        else ""
                    ),
                    "Quantity": 1,
                    "UnitAmount": float(line["interestAmount"]),
                    "AccountCode": account_code,
                    "TaxType": "NONE",
                }
            ],
        }
        idempotency_seed = json.dumps(
            {
                "periodStart": metadata.get("periodStartDate") or "",
                "periodEnd": period_end.isoformat(),
                "loanId": line["loanId"],
                "interestAmount": str(line["interestAmount"]),
            },
            sort_keys=True,
        )
        idempotency_key = f"jashflow-interest-{hashlib.sha256(idempotency_seed.encode()).hexdigest()[:32]}"
        xero_response = await create_sales_invoice(connection_row, invoice_payload, idempotency_key=idempotency_key)
        created_invoice = ((xero_response or {}).get("Invoices") or [{}])[0]
        invoice_id = created_invoice.get("InvoiceID") or created_invoice.get("ID") or ""
        invoice_number = created_invoice.get("InvoiceNumber") or ""
        if not invoice_id:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Xero created the Jashflow interest invoice for {line['customerName']} but did not return an invoice id.")
        created_invoices.append({
            "loanId": line["loanId"],
            "customerName": line["customerName"],
            "xeroInvoiceId": invoice_id,
            "xeroInvoiceNumber": invoice_number,
            "interestAmount": float(line["interestAmount"]),
        })

    invoice_id = ",".join(invoice["xeroInvoiceId"] for invoice in created_invoices)
    invoice_number = ", ".join(invoice["xeroInvoiceNumber"] or invoice["xeroInvoiceId"] for invoice in created_invoices)
    attachment_filename = ""
    attachment_error = ""

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO jashflow_interest_post_batches (
                    tenant_id, status, xero_invoice_id, xero_invoice_number,
                    invoice_contact_id, invoice_contact_name, interest_account_code,
                    period_end_date, total_interest_amount, attachment_filename,
                    error_message, created_by_user_id, created_at, completed_at
                )
                VALUES (%s, 'completed', %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING id
                """,
                (
                    tenant_id,
                    invoice_id,
                    invoice_number,
                    "multiple",
                    "Individual loan contacts",
                    account_code,
                    period_end,
                    total,
                    attachment_filename,
                    attachment_error,
                    user["id"],
                    utcnow(),
                    utcnow(),
                ),
            )
            batch_id = cursor.fetchone()["id"]
            for line in lines:
                cursor.execute(
                    """
                    INSERT INTO jashflow_interest_post_lines (
                        batch_id, loan_id, customer_id, period_end_date,
                        accrued_interest_amount, previously_posted_amount,
                        interest_amount, balance_after_interest, created_at
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    (
                        batch_id,
                        line["loanId"],
                        line["customerId"],
                        period_end,
                        line["accruedInterest"],
                        line["previouslyPosted"],
                        line["interestAmount"],
                        line["balance"],
                        utcnow(),
                    ),
                )
        connection.commit()

    record_audit_event(
        "jashflow_interest",
        str(batch_id),
        "jashflow.interest_posted",
        {
            "xero_invoice_id": invoice_id,
            "xero_invoice_number": invoice_number,
            "total_interest_amount": float(total),
            "line_count": len(lines),
            "invoice_count": len(created_invoices),
        },
        user["id"],
    )
    return {
        "interestPost": {
            "id": str(batch_id),
            "xeroInvoiceId": invoice_id,
            "xeroInvoiceNumber": invoice_number,
            "totalInterestAmount": float(total),
            "lineCount": len(lines),
            "invoiceCount": len(created_invoices),
            "invoices": created_invoices,
            "attachmentFilename": attachment_filename,
            "attachmentError": attachment_error,
        },
        "jashflow": jashflow_payload(user),
    }


