def _gmail_workspace_service_account_raw_value() -> str:
    settings = get_settings()
    return _gmail_oauth_secret_value(settings.gmail_workspace_service_account_json) or _gmail_env_alias_value(
        "GMAIL_WORKSPACE_SERVICE_ACCOUNT_JSON",
        "GOOGLE_WORKSPACE_SERVICE_ACCOUNT_JSON",
        "GMAIL_SERVICE_ACCOUNT_JSON",
    )


def _gmail_workspace_service_account_info() -> dict:
    raw_value = _gmail_workspace_service_account_raw_value()
    if not raw_value:
        return {}
    try:
        parsed = json.loads(raw_value)
    except Exception:
        try:
            parsed = json.loads(base64.b64decode(raw_value).decode("utf-8"))
        except Exception:
            return {}
    if not isinstance(parsed, dict):
        return {}
    client_email = str(parsed.get("client_email") or "").strip()
    private_key = str(parsed.get("private_key") or "").strip()
    token_uri = str(parsed.get("token_uri") or "https://oauth2.googleapis.com/token").strip()
    if not client_email or not private_key:
        return {}
    return {
        "client_email": client_email,
        "private_key": private_key,
        "token_uri": token_uri or "https://oauth2.googleapis.com/token",
        "project_id": str(parsed.get("project_id") or "").strip(),
    }


def gmail_workspace_delegation_configured() -> bool:
    info = _gmail_workspace_service_account_info()
    return bool(info.get("client_email") and info.get("private_key"))


def _base64url_no_padding(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _gmail_workspace_jwt_assertion(service_account: dict, mailbox_email: str, scopes: str) -> str:
    header_json = json.dumps({"alg": "RS256", "typ": "JWT"}, separators=(",", ":"), sort_keys=True).encode("utf-8")
    now_ts = int(time.time())
    payload = {
        "iss": str(service_account.get("client_email") or "").strip(),
        "scope": scopes,
        "aud": str(service_account.get("token_uri") or "https://oauth2.googleapis.com/token").strip(),
        "sub": mailbox_email,
        "iat": now_ts,
        "exp": now_ts + 3600,
    }
    payload_json = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    signing_input = f"{_base64url_no_padding(header_json)}.{_base64url_no_padding(payload_json)}".encode("ascii")
    private_key_raw = str(service_account.get("private_key") or "").encode("utf-8")
    private_key = serialization.load_pem_private_key(private_key_raw, password=None)
    signature = private_key.sign(signing_input, padding.PKCS1v15(), hashes.SHA256())
    return f"{signing_input.decode('ascii')}.{_base64url_no_padding(signature)}"


async def _gmail_workspace_access_token(mailbox_email: str) -> str:
    service_account = _gmail_workspace_service_account_info()
    if not service_account:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=(
                "Google Workspace delegation is not configured. "
                "Set GMAIL_WORKSPACE_SERVICE_ACCOUNT_JSON with a service account key "
                "that has domain-wide delegation enabled."
            ),
        )
    assertion = _gmail_workspace_jwt_assertion(
        service_account,
        mailbox_email,
        "https://www.googleapis.com/auth/gmail.readonly",
    )
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(
            str(service_account.get("token_uri") or "https://oauth2.googleapis.com/token"),
            data={
                "grant_type": "urn:ietf:params:oauth:grant-type:jwt-bearer",
                "assertion": assertion,
            },
        )
    if response.is_error:
        detail = response.text[:500]
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail=f"Workspace delegated token request failed for {mailbox_email}: {detail}",
        )
    token = str((response.json() or {}).get("access_token") or "").strip()
    if not token:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail=f"Workspace delegated token response did not include an access token for {mailbox_email}.",
        )
    return token


def _gmail_workspace_normalise_mailbox_email(value: object) -> str:
    email = str(value or "").strip().lower()
    if "@" not in email or "." not in email.split("@", 1)[1]:
        return ""
    return email[:250]


def _gmail_workspace_mailbox_row_payload(row: dict) -> dict:
    return {
        "id": str(row.get("id") or ""),
        "mailboxEmail": str(row.get("mailbox_email") or ""),
        "enabled": bool(row.get("enabled")),
        "allowDomainMatch": bool(row.get("allow_domain_match")),
        "lookbackMinutes": int(row.get("lookback_minutes") or 180),
        "lastSyncedAt": row.get("last_synced_at").isoformat() if row.get("last_synced_at") else "",
        "lastSyncStatus": str(row.get("last_sync_status") or "never"),
        "lastSyncError": str(row.get("last_sync_error") or ""),
        "lastSyncMessageCount": int(row.get("last_sync_message_count") or 0),
        "updatedAt": row.get("updated_at").isoformat() if row.get("updated_at") else "",
    }


def list_gmail_workspace_mailboxes() -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM gmail_workspace_mailboxes
                ORDER BY LOWER(mailbox_email) ASC
                """
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return {
        "delegationConfigured": gmail_workspace_delegation_configured(),
        "rows": [_gmail_workspace_mailbox_row_payload(row) for row in rows],
    }


def save_gmail_workspace_mailbox(user: dict, payload: dict | None = None) -> dict:
    body = payload if isinstance(payload, dict) else {}
    mailbox_email = _gmail_workspace_normalise_mailbox_email(body.get("mailboxEmail"))
    if not mailbox_email:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Enter a valid mailbox email.")
    enabled = bool(body.get("enabled", True))
    allow_domain_match = bool(body.get("allowDomainMatch", True))
    settings = get_settings()
    default_lookback = max(10, min(int(settings.gmail_workspace_default_lookback_minutes or 180), 60 * 24 * 14))
    try:
        lookback_minutes = int(body.get("lookbackMinutes", default_lookback))
    except Exception:
        lookback_minutes = default_lookback
    lookback_minutes = max(10, min(lookback_minutes, 60 * 24 * 14))
    user_id = str((user or {}).get("id") or "").strip() or None
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO gmail_workspace_mailboxes (
                    mailbox_email,
                    enabled,
                    allow_domain_match,
                    lookback_minutes,
                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, NOW(), NOW())
                ON CONFLICT (mailbox_email) DO UPDATE
                SET enabled = EXCLUDED.enabled,
                    allow_domain_match = EXCLUDED.allow_domain_match,
                    lookback_minutes = EXCLUDED.lookback_minutes,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = NOW()
                RETURNING *
                """,
                (mailbox_email, enabled, allow_domain_match, lookback_minutes, user_id, user_id),
            )
            saved_row = cursor.fetchone() or {}
        connection.commit()
    return {"row": _gmail_workspace_mailbox_row_payload(saved_row)}


def remove_gmail_workspace_mailbox(user: dict, mailbox_id: str) -> dict:
    safe_id = str(mailbox_id or "").strip()
    if not safe_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Mailbox id is required.")
    removed_row = {}
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM gmail_workspace_mailboxes
                WHERE id = %s
                RETURNING *
                """,
                (safe_id,),
            )
            removed_row = cursor.fetchone() or {}
            if removed_row:
                cursor.execute(
                    "DELETE FROM gmail_workspace_message_log WHERE mailbox_email = %s",
                    (str(removed_row.get("mailbox_email") or "").strip().lower(),),
                )
        connection.commit()
    if not removed_row:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Mailbox not found.")
    return {"removed": True, "row": _gmail_workspace_mailbox_row_payload(removed_row)}


def _gmail_workspace_message_list_url(mailbox_email: str) -> str:
    return f"https://gmail.googleapis.com/gmail/v1/users/{quote(mailbox_email, safe='')}/messages"


def _gmail_workspace_message_detail_url(mailbox_email: str, message_id: str) -> str:
    return f"https://gmail.googleapis.com/gmail/v1/users/{quote(mailbox_email, safe='')}/messages/{quote(message_id, safe='')}"


def _gmail_workspace_addresses(value: str) -> list[str]:
    parsed = getaddresses([value or ""])
    cleaned: list[str] = []
    seen: set[str] = set()
    for _, email_value in parsed:
        email_clean = _gmail_workspace_normalise_mailbox_email(email_value)
        if not email_clean or email_clean in seen:
            continue
        seen.add(email_clean)
        cleaned.append(email_clean)
    return cleaned


def _gmail_workspace_event_direction(mailbox_email: str, from_list: list[str]) -> str:
    mailbox = _gmail_workspace_normalise_mailbox_email(mailbox_email)
    return "sent" if mailbox and mailbox in from_list else "received"


def _gmail_workspace_message_ids_seen(mailbox_email: str, message_ids: list[str]) -> set[str]:
    if not message_ids:
        return set()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT gmail_message_id
                FROM gmail_workspace_message_log
                WHERE mailbox_email = %s
                  AND gmail_message_id = ANY(%s)
                """,
                (mailbox_email, message_ids),
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return {str(row.get("gmail_message_id") or "").strip() for row in rows if row.get("gmail_message_id")}


def _gmail_workspace_log_messages(mailbox_email: str, events: list[dict]) -> None:
    if not events:
        return
    with get_connection() as connection:
        with connection.cursor() as cursor:
            for item in events:
                message_id = str(item.get("messageId") or "").strip()
                if not message_id:
                    continue
                occurred_at_raw = str(item.get("occurredAt") or "").strip()
                occurred_at: datetime | None = None
                if occurred_at_raw:
                    try:
                        occurred_at = datetime.fromisoformat(occurred_at_raw.replace("Z", "+00:00"))
                    except Exception:
                        occurred_at = None
                cursor.execute(
                    """
                    INSERT INTO gmail_workspace_message_log (mailbox_email, gmail_message_id, received_at, created_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (mailbox_email, gmail_message_id) DO NOTHING
                    """,
                    (mailbox_email, message_id, occurred_at),
                )
        connection.commit()


def _gmail_workspace_update_mailbox_sync_status(
    mailbox_id: str,
    *,
    status_text: str,
    message_count: int,
    error_text: str = "",
) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE gmail_workspace_mailboxes
                SET last_synced_at = NOW(),
                    last_sync_status = %s,
                    last_sync_error = %s,
                    last_sync_message_count = %s,
                    updated_at = NOW()
                WHERE id = %s
                """,
                (status_text[:30], error_text[:600], max(0, int(message_count or 0)), mailbox_id),
            )
        connection.commit()


async def sync_gmail_workspace_mailboxes(user: dict, payload: dict | None = None) -> dict:
    body = payload if isinstance(payload, dict) else {}
    if not gmail_workspace_delegation_configured():
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Google Workspace delegation is not configured. Set GMAIL_WORKSPACE_SERVICE_ACCOUNT_JSON.",
        )
    mailbox_filter = _gmail_workspace_normalise_mailbox_email(body.get("mailboxEmail"))
    force_lookback = bool(body.get("forceLookback", False))
    settings = get_settings()
    default_lookback = max(10, min(int(settings.gmail_workspace_default_lookback_minutes or 180), 60 * 24 * 14))
    sync_max = max(10, min(int(settings.gmail_workspace_sync_max_per_mailbox or 120), 500))
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if mailbox_filter:
                cursor.execute(
                    """
                    SELECT *
                    FROM gmail_workspace_mailboxes
                    WHERE LOWER(mailbox_email) = %s
                    LIMIT 1
                    """,
                    (mailbox_filter,),
                )
                single_row = cursor.fetchone()
                rows = [single_row] if isinstance(single_row, dict) else []
            else:
                cursor.execute(
                    """
                    SELECT *
                    FROM gmail_workspace_mailboxes
                    WHERE enabled = TRUE
                    ORDER BY LOWER(mailbox_email) ASC
                    """
                )
                rows = cursor.fetchall() or []
        connection.commit()
    rows = [row for row in rows if isinstance(row, dict)]
    all_events: list[dict] = []
    mailbox_results: list[dict] = []

    for row in rows:
        mailbox_email = _gmail_workspace_normalise_mailbox_email(row.get("mailbox_email"))
        if not mailbox_email:
            continue
        mailbox_id = str(row.get("id") or "").strip()
        allow_domain_match = bool(row.get("allow_domain_match"))
        try:
            lookback_minutes = int(row.get("lookback_minutes") or default_lookback)
        except Exception:
            lookback_minutes = default_lookback
        lookback_minutes = max(10, min(lookback_minutes, 60 * 24 * 14))
        if isinstance(body.get("lookbackMinutes"), int):
            lookback_minutes = max(10, min(int(body.get("lookbackMinutes")), 60 * 24 * 14))
        since_dt = utcnow() - timedelta(minutes=lookback_minutes)
        last_synced = row.get("last_synced_at")
        if isinstance(last_synced, datetime) and not force_lookback:
            since_dt = min(since_dt, last_synced - timedelta(minutes=10))
        since_token = since_dt.date().strftime("%Y/%m/%d")
        mailbox_event_rows: list[dict] = []
        try:
            access_token = await _gmail_workspace_access_token(mailbox_email)
            headers = {"Authorization": f"Bearer {access_token}"}
            message_ids: list[str] = []
            page_token = ""
            max_pages = 6
            async with httpx.AsyncClient(timeout=30) as client:
                for _ in range(max_pages):
                    params = {
                        "q": f"after:{since_token}",
                        "includeSpamTrash": "false",
                        "maxResults": min(sync_max, 250),
                    }
                    if page_token:
                        params["pageToken"] = page_token
                    list_response = await client.get(
                        _gmail_workspace_message_list_url(mailbox_email),
                        headers=headers,
                        params=params,
                    )
                    if list_response.is_error:
                        raise HTTPException(
                            status_code=status.HTTP_502_BAD_GATEWAY,
                            detail=f"Gmail list failed for {mailbox_email}: {list_response.text[:260]}",
                        )
                    payload_json = list_response.json() if list_response.content else {}
                    rows_payload = payload_json.get("messages") if isinstance(payload_json, dict) else []
                    if not isinstance(rows_payload, list):
                        rows_payload = []
                    for item in rows_payload:
                        message_id = str((item or {}).get("id") or "").strip()
                        if message_id and message_id not in message_ids:
                            message_ids.append(message_id)
                        if len(message_ids) >= sync_max:
                            break
                    page_token = str(payload_json.get("nextPageToken") or "").strip() if isinstance(payload_json, dict) else ""
                    if not page_token or len(message_ids) >= sync_max:
                        break
                existing_ids = _gmail_workspace_message_ids_seen(mailbox_email, message_ids)
                new_message_ids = [message_id for message_id in message_ids if message_id not in existing_ids]
                for message_id in new_message_ids:
                    detail_response = await client.get(
                        _gmail_workspace_message_detail_url(mailbox_email, message_id),
                        headers=headers,
                        params={
                            "format": "metadata",
                            "metadataHeaders": ["Subject", "From", "To", "Cc", "Bcc", "Date"],
                        },
                    )
                    if detail_response.is_error:
                        continue
                    payload_json = detail_response.json() if detail_response.content else {}
                    if not isinstance(payload_json, dict):
                        continue
                    from_list = _gmail_workspace_addresses(_gmail_header_value(payload_json, "From"))
                    to_list = _gmail_workspace_addresses(_gmail_header_value(payload_json, "To"))
                    cc_list = _gmail_workspace_addresses(_gmail_header_value(payload_json, "Cc"))
                    bcc_list = _gmail_workspace_addresses(_gmail_header_value(payload_json, "Bcc"))
                    subject = _gmail_header_value(payload_json, "Subject")[:400]
                    occurred_at_dt = _gmail_received_at(payload_json)
                    occurred_at = occurred_at_dt.isoformat().replace("+00:00", "Z") if isinstance(occurred_at_dt, datetime) else ""
                    mailbox_event_rows.append(
                        {
                            "direction": _gmail_workspace_event_direction(mailbox_email, from_list),
                            "mailbox": mailbox_email,
                            "provider": "gmail_workspace",
                            "messageId": message_id,
                            "occurredAt": occurred_at,
                            "from": from_list,
                            "to": to_list,
                            "cc": cc_list,
                            "bcc": bcc_list,
                            "subject": subject,
                            "snippet": str(payload_json.get("snippet") or "")[:1200],
                            "allowDomainMatch": allow_domain_match,
                            "clientHints": {"allowDomainMatch": allow_domain_match, "largeClient": allow_domain_match},
                        }
                    )
            _gmail_workspace_log_messages(mailbox_email, mailbox_event_rows)
            _gmail_workspace_update_mailbox_sync_status(
                mailbox_id,
                status_text="ok",
                message_count=len(mailbox_event_rows),
                error_text="",
            )
            all_events.extend(mailbox_event_rows)
            mailbox_results.append(
                {
                    "mailboxEmail": mailbox_email,
                    "status": "ok",
                    "eventsCaptured": len(mailbox_event_rows),
                    "allowDomainMatch": allow_domain_match,
                }
            )
        except Exception as exc:
            error_text = str(getattr(exc, "detail", "") or str(exc) or "Sync failed").strip()
            if mailbox_id:
                _gmail_workspace_update_mailbox_sync_status(
                    mailbox_id,
                    status_text="error",
                    message_count=0,
                    error_text=error_text,
                )
            mailbox_results.append(
                {
                    "mailboxEmail": mailbox_email,
                    "status": "error",
                    "eventsCaptured": 0,
                    "error": error_text[:300],
                }
            )

    return {
        "delegationConfigured": gmail_workspace_delegation_configured(),
        "mailboxesProcessed": len(mailbox_results),
        "eventsCaptured": len(all_events),
        "mailboxes": mailbox_results,
        "events": all_events,
    }


async def maybe_auto_sync_gmail_workspace_timeline(user: dict, min_interval_minutes: int = 5) -> dict:
    global _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT
    if not gmail_workspace_delegation_configured():
        return {"triggered": False, "reason": "not_configured"}
    interval_minutes = max(1, min(int(min_interval_minutes or 5), 120))
    minimum_interval = timedelta(minutes=interval_minutes)
    now = utcnow()
    if _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT and (now - _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT) < minimum_interval:
        return {"triggered": False, "reason": "interval"}
    if _GMAIL_WORKSPACE_AUTO_SYNC_LOCK.locked():
        return {"triggered": False, "reason": "in_progress"}
    async with _GMAIL_WORKSPACE_AUTO_SYNC_LOCK:
        now = utcnow()
        if _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT and (now - _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT) < minimum_interval:
            return {"triggered": False, "reason": "interval"}
        try:
            sync_result = await sync_gmail_workspace_mailboxes(user, {"forceLookback": False})
            events = sync_result.get("events") if isinstance(sync_result.get("events"), list) else []
            if events:
                from .companies_house import log_auth_register_email_activity

                timeline_result = log_auth_register_email_activity(user, {"events": events})
            else:
                timeline_result = {"processedEvents": 0, "createdTimelineEvents": 0, "unmatchedEvents": 0}
            _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT = utcnow()
            return {
                "triggered": True,
                "sync": {
                    "mailboxesProcessed": int(sync_result.get("mailboxesProcessed") or 0),
                    "eventsCaptured": int(sync_result.get("eventsCaptured") or 0),
                },
                "timeline": {
                    "processedEvents": int(timeline_result.get("processedEvents") or 0),
                    "createdTimelineEvents": int(timeline_result.get("createdTimelineEvents") or 0),
                    "unmatchedEvents": int(timeline_result.get("unmatchedEvents") or 0),
                },
            }
        except Exception as exc:
            logger.warning("gmail_workspace_auto_sync_failed: %s", str(exc)[:300])
            _GMAIL_WORKSPACE_LAST_AUTO_SYNC_AT = utcnow()
            return {"triggered": False, "reason": "error", "error": str(exc)[:220]}


def _me_report_xero_connection(user: dict, client: dict | None = None) -> dict:
    if client and client.get("xero_connection_id"):
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    "SELECT * FROM xero_connections WHERE id = %s AND user_id = %s",
                    (client["xero_connection_id"], user["id"]),
                )
                row = cursor.fetchone()
            connection.commit()
        if row:
            return row
    return get_xero_connection_for_user(user["id"])


def _me_report_empty_summary() -> dict:
    return {
        "clientCount": 0,
        "green": 0,
        "amber": 0,
        "red": 0,
        "reportsGenerated": 0,
        "estimatedCorporationTax": 0,
        "dividendCapacity": 0,
        "dlaRedCount": 0,
    }


def _me_report_contact_email(row: dict) -> str:
    email = str(row.get("email") or "").strip()
    if email:
        return email
    people = row.get("contact_people") if isinstance(row.get("contact_people"), list) else []
    included = [person for person in people if person.get("includeInEmails") and person.get("email")]
    fallback = included[0] if included else next((person for person in people if person.get("email")), None)
    return str((fallback or {}).get("email") or "").strip()


def _me_report_contact_options(user: dict, tenant_id: str | None = None) -> list[dict]:
    requested_tenant_id = str(tenant_id or "").strip()
    try:
        if requested_tenant_id:
            source_rows = list_xero_connections_for_user(user["id"], include_fallback=True)
            connection_row = next((row for row in source_rows if str(row.get("tenant_id") or "").strip() == requested_tenant_id), None)
            if not connection_row:
                return []
        else:
            connection_row = get_xero_connection_for_user(user["id"])
    except HTTPException:
        return []
    active_tenant_id = str(connection_row.get("tenant_id") or "")
    active_tenant_name = str(connection_row.get("tenant_name") or "")
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, xero_contact_id, name, email, primary_person, contact_people
                FROM customers
                WHERE tenant_id = %s
                  AND status = 'active'
                ORDER BY LOWER(name) ASC
                LIMIT 2500
                """,
                (active_tenant_id,),
            )
            rows = cursor.fetchall()
        connection.commit()
    return [
        {
            "customerId": str(row.get("id") or ""),
            "xeroContactId": row.get("xero_contact_id") or "",
            "name": row.get("name") or "Unnamed Xero contact",
            "email": _me_report_contact_email(row),
            "tenantId": active_tenant_id,
            "tenantName": active_tenant_name,
            "primaryPerson": row.get("primary_person") or "",
            "contactPeople": row.get("contact_people") if isinstance(row.get("contact_people"), list) else [],
        }
        for row in rows
        if row.get("xero_contact_id")
    ]


def _me_report_contact_for_user(user: dict, xero_contact_id: str, tenant_id: str | None = None) -> dict | None:
    xero_contact_id = str(xero_contact_id or "").strip()
    if not xero_contact_id:
        return None
    try:
        requested_tenant_id = str(tenant_id or "").strip()
        if requested_tenant_id:
            source_rows = list_xero_connections_for_user(user["id"], include_fallback=True)
            connection_row = next((row for row in source_rows if str(row.get("tenant_id") or "").strip() == requested_tenant_id), None)
            if not connection_row:
                return None
        else:
            connection_row = get_xero_connection_for_user(user["id"])
    except HTTPException:
        return None
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, xero_contact_id, name, email, primary_person, contact_people
                FROM customers
                WHERE tenant_id = %s
                  AND xero_contact_id = %s
                LIMIT 1
                """,
                (connection_row.get("tenant_id"), xero_contact_id),
            )
            row = cursor.fetchone()
        connection.commit()
    if not row:
        return None
    return {
        "customerId": str(row.get("id") or ""),
        "xeroContactId": row.get("xero_contact_id") or "",
        "name": row.get("name") or "Unnamed Xero contact",
        "email": _me_report_contact_email(row),
        "tenantId": str(connection_row.get("tenant_id") or ""),
        "tenantName": str(connection_row.get("tenant_name") or ""),
        "primaryPerson": row.get("primary_person") or "",
        "contactPeople": row.get("contact_people") if isinstance(row.get("contact_people"), list) else [],
    }


def gmail_oauth_configured() -> bool:
    client_id = _gmail_client_id_value()
    client_secret = _gmail_client_secret_value()
    return bool(client_id and client_secret)


def _gmail_oauth_is_placeholder(value: str) -> bool:
    normalized = str(value or "").strip().strip("\"'").lower()
    placeholders = {
        "",
        "replace-me",
        "changeme",
        "change-me",
        "your-client-id",
        "your-client-secret",
    }
    return normalized in placeholders


def _gmail_oauth_secret_value(value: str | None) -> str:
    # Railway/env vars are sometimes pasted with wrapping quotes.
    cleaned = str(value or "").strip().strip("\"'")
    return "" if _gmail_oauth_is_placeholder(cleaned) else cleaned


def _gmail_env_alias_value(*keys: str) -> str:
    normalised_lookup: dict[str, str] = {}
    for env_key, env_value in os.environ.items():
        normalised_key = "".join(character for character in str(env_key).upper() if character.isalnum())
        if normalised_key and normalised_key not in normalised_lookup:
            normalised_lookup[normalised_key] = str(env_value or "")
    for key in keys:
        candidate = _gmail_oauth_secret_value(os.getenv(key))
        if candidate:
            return candidate
        normalised_key = "".join(character for character in str(key).upper() if character.isalnum())
        candidate = _gmail_oauth_secret_value(normalised_lookup.get(normalised_key))
        if candidate:
            return candidate
    return ""


def _gmail_client_id_value() -> str:
    settings = get_settings()
    return _gmail_oauth_secret_value(settings.gmail_client_id) or _gmail_env_alias_value(
        "GMAIL_CLIENT_ID",
        "GMAIL_OAUTH_CLIENT_ID",
        "GMAIL_CLIENTID",
        "GOOGLE_CLIENT_ID",
        "GOOGLE_OAUTH_CLIENT_ID",
        "GOOGLE_CLIENTID",
    )


def _gmail_client_secret_value() -> str:
    settings = get_settings()
    return _gmail_oauth_secret_value(settings.gmail_client_secret) or _gmail_env_alias_value(
        "GMAIL_CLIENT_SECRET",
        "GMAIL_OAUTH_CLIENT_SECRET",
        "GMAIL_CLIENTSECRET",
        "GOOGLE_CLIENT_SECRET",
        "GOOGLE_OAUTH_CLIENT_SECRET",
        "GOOGLE_CLIENTSECRET",
    )


def _gmail_scopes_value(value: str | None) -> str:
    configured = " ".join(str(value or "").replace(",", " ").split())
    scopes = {scope for scope in configured.split() if scope}
    # Ensure core scopes required across the app are always requested.
    scopes.update(
        {
            "openid",
            "email",
            "https://www.googleapis.com/auth/gmail.send",
            "https://www.googleapis.com/auth/gmail.readonly",
        }
    )
    return " ".join(sorted(scopes))


def gmail_redirect_uri() -> str:
    settings = get_settings()
    redirect_uri = _gmail_oauth_secret_value(settings.gmail_redirect_uri) or _gmail_env_alias_value(
        "GMAIL_REDIRECT_URI",
        "GMAIL_REDIRECT_URL",
        "GMAIL_OAUTH_REDIRECT_URI",
        "GOOGLE_REDIRECT_URI",
        "GOOGLE_REDIRECT_URL",
        "GOOGLE_OAUTH_REDIRECT_URI",
        "GOOGLE_OAUTH_REDIRECT_URL",
    )
    return redirect_uri or f"{settings.base_url.rstrip('/')}/auth/gmail/callback"


def gmail_authorize_url(state_token: str) -> str:
    client_id = _gmail_client_id_value()
    settings = get_settings()
    scopes = _gmail_scopes_value(settings.gmail_scopes)
    if not gmail_oauth_configured():
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Gmail OAuth is not configured. Add GMAIL_CLIENT_ID, GMAIL_CLIENT_SECRET and GMAIL_REDIRECT_URI.")
    query = urlencode(
        {
            "response_type": "code",
            "client_id": client_id,
            "redirect_uri": gmail_redirect_uri(),
            "scope": scopes,
            "state": state_token,
            "access_type": "offline",
            "prompt": "consent",
            "include_granted_scopes": "true",
        }
    )
    return f"{GMAIL_AUTHORIZE_URL}?{query}"


async def exchange_gmail_code_for_tokens(code: str) -> dict:
    client_id = _gmail_client_id_value()
    client_secret = _gmail_client_secret_value()
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(
            GMAIL_TOKEN_URL,
            data={
                "grant_type": "authorization_code",
                "code": code,
                "client_id": client_id,
                "client_secret": client_secret,
                "redirect_uri": gmail_redirect_uri(),
            },
        )
    if response.is_error:
        response_text = response.text[:500]
        if "invalid_client" in response_text.lower():
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail=(
                    "Gmail token exchange failed: invalid_client. "
                    "Check GMAIL_CLIENT_ID and GMAIL_CLIENT_SECRET in environment settings "
                    "(remove wrapping quotes/spaces and confirm the OAuth client still exists in Google Cloud)."
                ),
            )
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Gmail token exchange failed: {response_text}")
    return response.json()


async def fetch_gmail_profile(access_token: str) -> dict:
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.get(GMAIL_USERINFO_URL, headers={"Authorization": f"Bearer {access_token}"})
    if response.is_error:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Gmail profile fetch failed: {response.text[:500]}")
    return response.json()


def store_gmail_connection(user: dict, token_payload: dict, profile: dict) -> dict:
    expires_in = int(token_payload.get("expires_in") or 3600)
    expires_at = utcnow() + timedelta(seconds=max(60, expires_in - 60))
    gmail_email = profile.get("email") or user.get("email") or ""
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO gmail_connections (
                    user_id, gmail_email, access_token, refresh_token,
                    scope, token_expires_at, status, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, 'connected', %s, %s)
                ON CONFLICT (user_id) DO UPDATE
                SET gmail_email = EXCLUDED.gmail_email,
                    access_token = EXCLUDED.access_token,
                    refresh_token = COALESCE(NULLIF(EXCLUDED.refresh_token, ''), gmail_connections.refresh_token),
                    scope = EXCLUDED.scope,
                    token_expires_at = EXCLUDED.token_expires_at,
                    status = 'connected',
                    updated_at = EXCLUDED.updated_at
                RETURNING *
                """,
                (
                    user["id"],
                    gmail_email,
                    token_payload.get("access_token") or "",
                    token_payload.get("refresh_token") or "",
                    token_payload.get("scope") or "",
                    expires_at,
                    utcnow(),
                    utcnow(),
                ),
            )
            row = cursor.fetchone()
        connection.commit()
    record_audit_event("gmail_connection", str(row["id"]), "gmail.connected", {"gmail_email": gmail_email}, user["id"])
    return row


def disconnect_gmail_connection(user: dict) -> dict:
    removed = False
    previous_email = ""
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                DELETE FROM gmail_connections
                WHERE user_id = %s
                RETURNING gmail_email
                """,
                (user["id"],),
            )
            deleted = cursor.fetchone()
        connection.commit()
    if deleted:
        removed = True
        previous_email = str(deleted.get("gmail_email") or "").strip()
    record_audit_event(
        "gmail_connection",
        str(user["id"]),
        "gmail.disconnected",
        {"removed": removed, "previous_email": previous_email},
        user["id"],
    )
    return {
        "removed": removed,
        "previousEmail": previous_email,
        "settings": _serialize_me_report_settings(_me_report_settings_row(user)),
    }


def gmail_connection_for_user(user: dict | str) -> dict | None:
    user_id = user.get("id") if isinstance(user, dict) else user
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM gmail_connections WHERE user_id = %s AND status = 'connected'", (user_id,))
            row = cursor.fetchone()
        connection.commit()
    return row


async def refresh_gmail_connection(row: dict) -> dict:
    if row.get("token_expires_at") and row["token_expires_at"] > utcnow() + timedelta(minutes=2):
        return row
    if not row.get("refresh_token"):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Gmail needs to be reconnected before sending ME Report emails.")
    client_id = _gmail_client_id_value()
    client_secret = _gmail_client_secret_value()
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(
            GMAIL_TOKEN_URL,
            data={
                "grant_type": "refresh_token",
                "refresh_token": row["refresh_token"],
                "client_id": client_id,
                "client_secret": client_secret,
            },
        )
    if response.is_error:
        response_text = response.text[:500]
        if "invalid_client" in response_text.lower():
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail=(
                    "Gmail token refresh failed: invalid_client. "
                    "Reconnect Gmail after verifying GMAIL_CLIENT_ID and GMAIL_CLIENT_SECRET."
                ),
            )
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Gmail token refresh failed: {response_text}")
    payload = response.json()
    expires_at = utcnow() + timedelta(seconds=max(60, int(payload.get("expires_in") or 3600) - 60))
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE gmail_connections
                SET access_token = %s,
                    token_expires_at = %s,
                    updated_at = %s
                WHERE id = %s
                RETURNING *
                """,
                (payload.get("access_token") or "", expires_at, utcnow(), row["id"]),
            )
            updated = cursor.fetchone()
        connection.commit()
    return updated


def _calendar_scope_granted(scope_value: str | None) -> bool:
    scopes = set(_gmail_scopes_value(scope_value).split())
    return (
        "https://www.googleapis.com/auth/calendar.readonly" in scopes
        or "https://www.googleapis.com/auth/calendar" in scopes
    )


def _calendar_sort_key(value: str) -> datetime:
    raw = str(value or "").strip()
    if not raw:
        return datetime.max.replace(tzinfo=timezone.utc)
    if raw.endswith("Z"):
        raw = f"{raw[:-1]}+00:00"
    if "T" not in raw:
        raw = f"{raw}T00:00:00+00:00"
    try:
        parsed = datetime.fromisoformat(raw)
    except ValueError:
        return datetime.max.replace(tzinfo=timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _calendar_event_times(event: dict) -> tuple[str, str, bool]:
    start_raw = event.get("start") if isinstance(event.get("start"), dict) else {}
    end_raw = event.get("end") if isinstance(event.get("end"), dict) else {}
    start_value = str(start_raw.get("dateTime") or start_raw.get("date") or "").strip()
    end_value = str(end_raw.get("dateTime") or end_raw.get("date") or "").strip()
    all_day = bool(start_raw.get("date")) and not bool(start_raw.get("dateTime"))
    return start_value, end_value, all_day


async def company_calendar_payload(user: dict, days_ahead: int = 14, max_events: int = 20) -> dict:
    now = utcnow()
    response: dict = {
        "status": "not_connected",
        "checkedAt": now.isoformat(),
        "needsReconnect": False,
        "message": "Connect Gmail to read Google Workspace calendars.",
        "windowDays": max(1, min(days_ahead, 90)),
        "calendarCount": 0,
        "includedCalendarCount": 0,
        "upcomingCount": 0,
        "nextEventAt": "",
        "gmailEmail": "",
        "calendars": [],
        "events": [],
    }
    connection_row = gmail_connection_for_user(user)
    if not connection_row:
        return response
    response["gmailEmail"] = connection_row.get("gmail_email") or ""

    try:
        connection_row = await refresh_gmail_connection(connection_row)
    except HTTPException as exc:
        response.update(
            {
                "status": "reauth_required",
                "needsReconnect": True,
                "message": str(exc.detail or "Reconnect Gmail to refresh the calendar access token."),
            }
        )
        return response

    if not _calendar_scope_granted(connection_row.get("scope")):
        response.update(
            {
                "status": "reauth_required",
                "needsReconnect": True,
                "message": "Reconnect Gmail to grant Google Calendar read access.",
            }
        )
        return response

    time_min = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    time_max = (now + timedelta(days=max(1, min(days_ahead, 90)))).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    headers = {"Authorization": f"Bearer {connection_row.get('access_token') or ''}"}

    try:
        async with httpx.AsyncClient(timeout=30) as client:
            calendar_list_response = await client.get(
                GOOGLE_CALENDAR_LIST_URL,
                headers=headers,
                params={
                    "showHidden": "false",
                    "showDeleted": "false",
                    "minAccessRole": "reader",
                    "maxResults": 100,
                },
            )
            if calendar_list_response.is_error:
                detail = calendar_list_response.text[:300]
                if calendar_list_response.status_code in (401, 403):
                    response.update(
                        {
                            "status": "reauth_required",
                            "needsReconnect": True,
                            "message": "Google Calendar access is denied. Reconnect Gmail and include calendar permission.",
                        }
                    )
                    return response
                response.update(
                    {
                        "status": "error",
                        "message": f"Google Calendar list lookup failed ({calendar_list_response.status_code}): {detail or 'Unknown error'}",
                    }
                )
                return response
            calendar_payload = calendar_list_response.json()
            calendars = calendar_payload.get("items") if isinstance(calendar_payload, dict) else []
            if not isinstance(calendars, list):
                calendars = []
            visible_calendars = [
                row for row in calendars
                if isinstance(row, dict) and row.get("id") and not row.get("deleted")
            ]
            visible_calendars.sort(
                key=lambda row: (
                    0 if row.get("primary") else 1,
                    0 if row.get("selected", True) else 1,
                    str(row.get("summaryOverride") or row.get("summary") or "").lower(),
                )
            )
            included_calendars = visible_calendars[:8]

            async def _fetch_calendar_events(calendar: dict) -> tuple[dict, list[dict]]:
                calendar_id = str(calendar.get("id") or "")
                events_response = await client.get(
                    GOOGLE_CALENDAR_EVENTS_URL.format(calendar_id=quote(calendar_id, safe="")),
                    headers=headers,
                    params={
                        "timeMin": time_min,
                        "timeMax": time_max,
                        "singleEvents": "true",
                        "orderBy": "startTime",
                        "showDeleted": "false",
                        "maxResults": max(1, min(max_events, 200)),
                    },
                )
                if events_response.is_error:
                    return calendar, []
                payload = events_response.json()
                items = payload.get("items") if isinstance(payload, dict) else []
                if not isinstance(items, list):
                    items = []
                return calendar, [item for item in items if isinstance(item, dict) and item.get("id")]

            events_by_calendar = await asyncio.gather(*[_fetch_calendar_events(calendar) for calendar in included_calendars])
    except Exception as exc:
        response.update(
            {
                "status": "error",
                "message": f"Unable to read Google Calendar right now: {str(exc) or exc.__class__.__name__}",
            }
        )
        return response

    events: list[dict] = []
    calendar_rows: list[dict] = []
    for calendar, rows in events_by_calendar:
        calendar_id = str(calendar.get("id") or "")
        calendar_name = str(calendar.get("summaryOverride") or calendar.get("summary") or "Calendar").strip()
        calendar_rows.append(
            {
                "id": calendar_id,
                "name": calendar_name or "Calendar",
                "primary": bool(calendar.get("primary")),
                "selected": bool(calendar.get("selected", True)),
                "accessRole": str(calendar.get("accessRole") or ""),
                "timeZone": str(calendar.get("timeZone") or ""),
                "eventCount": len(rows),
            }
        )
        for row in rows:
            start_at, end_at, all_day = _calendar_event_times(row)
            if not start_at:
                continue
            events.append(
                {
                    "id": str(row.get("id") or ""),
                    "title": str(row.get("summary") or "Untitled event"),
                    "calendarId": calendar_id,
                    "calendarName": calendar_name or "Calendar",
                    "startAt": start_at,
                    "endAt": end_at,
                    "allDay": all_day,
                    "location": str(row.get("location") or ""),
                    "htmlLink": str(row.get("htmlLink") or ""),
                    "organizer": str((row.get("organizer") or {}).get("email") or ""),
                }
            )

    events.sort(key=lambda item: _calendar_sort_key(item.get("startAt") or ""))
    events = events[: max(1, min(max_events, 200))]
    response.update(
        {
            "status": "connected",
            "message": "Google Workspace calendars are syncing.",
            "calendarCount": len(calendar_rows),
            "includedCalendarCount": len(calendar_rows),
            "upcomingCount": len(events),
            "nextEventAt": events[0]["startAt"] if events else "",
            "calendars": calendar_rows,
            "events": events,
        }
    )
    return response


