def _gmail_decode_header_value(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        chunks = decode_header(text)
    except Exception:
        return text
    decoded_parts: list[str] = []
    for chunk, charset in chunks:
        if isinstance(chunk, bytes):
            encoding = (charset or "utf-8").strip() or "utf-8"
            try:
                decoded_parts.append(chunk.decode(encoding, errors="replace"))
            except Exception:
                decoded_parts.append(chunk.decode("utf-8", errors="replace"))
        else:
            decoded_parts.append(str(chunk))
    return "".join(decoded_parts).strip()


def _submitted_employee_forms_normalized_subject(subject: str) -> str:
    decoded = _gmail_decode_header_value(subject)
    compact = re.sub(r"\s+", " ", str(decoded or "").strip())
    if not compact:
        return ""
    # Remove common mail gateway labels prepended to subjects.
    compact = re.sub(r"^(?:\[[^\]]+\]\s*)+", "", compact).strip()
    # Ignore common thread prefixes that can appear in Gmail subjects.
    return re.sub(r"^(?:(?:re|fw|fwd)\s*:\s*)+", "", compact, flags=re.IGNORECASE).strip()


def _submitted_employee_forms_subject_matches(subject: str) -> bool:
    text = _submitted_employee_forms_normalized_subject(subject).lower()
    if not text:
        return False
    # Accept the expected prefix with optional punctuation/spacing variance.
    if text.startswith("new employee details"):
        return True
    # Some senders duplicate the prefix in a single subject line.
    return "new employee details:new employee details" in text


def _submitted_employee_forms_subject_suffix(subject: str) -> str:
    text = _submitted_employee_forms_normalized_subject(subject)
    return re.sub(r"^new\s+employee\s+details\s*:\s*", "", text, flags=re.IGNORECASE).strip()


def _gmail_read_scope_granted(scope_value: str | None) -> bool:
    scopes = set(_gmail_scopes_value(scope_value).split())
    return bool(
        {
            "https://www.googleapis.com/auth/gmail.readonly",
            "https://www.googleapis.com/auth/gmail.modify",
            "https://mail.google.com/",
        }.intersection(scopes)
    )


def _gmail_header_value(message_payload: dict, header_name: str) -> str:
    payload = message_payload.get("payload") if isinstance(message_payload.get("payload"), dict) else {}
    headers = payload.get("headers") if isinstance(payload.get("headers"), list) else []
    target = str(header_name or "").strip().lower()
    for header in headers:
        if not isinstance(header, dict):
            continue
        name = str(header.get("name") or "").strip().lower()
        if name == target:
            return str(header.get("value") or "").strip()
    return ""


def _gmail_decode_body_data(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    padding = "=" * ((4 - (len(raw) % 4)) % 4)
    try:
        decoded = base64.urlsafe_b64decode(f"{raw}{padding}".encode("utf-8"))
    except Exception:
        return ""
    try:
        return decoded.decode("utf-8")
    except UnicodeDecodeError:
        try:
            return decoded.decode("latin-1")
        except UnicodeDecodeError:
            return ""


def _gmail_decode_body_bytes(value: str) -> bytes:
    raw = str(value or "").strip()
    if not raw:
        return b""
    padding = "=" * ((4 - (len(raw) % 4)) % 4)
    try:
        return base64.urlsafe_b64decode(f"{raw}{padding}".encode("utf-8"))
    except Exception:
        return b""


def _hash_sha256_bytes(value: bytes) -> str:
    if not isinstance(value, (bytes, bytearray)) or not value:
        return ""
    return hashlib.sha256(bytes(value)).hexdigest()


def _submitted_employee_forms_normalise_field_value(field_key: str, raw_value: str) -> str:
    value = re.sub(r"\s+", " ", str(raw_value or "").strip())
    if not value:
        return ""
    key = str(field_key or "").strip()
    if key in {"startDate", "dateOfBirth"}:
        return _submitted_employee_forms_normalise_date(value) or value
    if key == "nationalInsuranceNumber":
        return re.sub(r"[^A-Za-z0-9]", "", value).upper()
    if key == "bankSortCode":
        digits = re.sub(r"[^0-9]", "", value)
        return digits[:6]
    if key == "bankAccountNumber":
        digits = re.sub(r"[^0-9]", "", value)
        return digits[:8]
    if key == "gender":
        return _submitted_employee_forms_normalise_gender(value) or value
    if key == "title":
        return _submitted_employee_forms_normalise_title(value) or value
    if key == "country":
        return _submitted_employee_forms_normalise_country_name(value) or value
    return value


def _submitted_employee_forms_parse_csv_bytes(file_bytes: bytes) -> tuple[dict, dict, list[dict]]:
    extracted: dict[str, str] = {}
    unmapped: dict[str, str] = {}
    raw_rows: list[dict] = []
    if not file_bytes:
        return extracted, unmapped, raw_rows
    text = file_bytes.decode("utf-8", errors="replace")
    reader = csv.reader(io.StringIO(text))
    for row in reader:
        if not isinstance(row, list) or len(row) < 2:
            continue
        raw_field = re.sub(r"\s+", " ", str(row[0] or "").strip())
        raw_value = re.sub(r"\s+", " ", str(row[1] or "").strip())
        if not raw_field:
            continue
        mapped_key = NEW_EMPLOYEE_FORMS_FIELD_MAP.get(raw_field)
        if mapped_key:
            normalised = _submitted_employee_forms_normalise_field_value(mapped_key, raw_value)
            extracted[mapped_key] = normalised
            raw_rows.append(
                {
                    "fieldName": raw_field,
                    "rawValue": raw_value,
                    "normalisedValue": normalised,
                }
            )
        else:
            unmapped[raw_field] = raw_value
            raw_rows.append(
                {
                    "fieldName": raw_field,
                    "rawValue": raw_value,
                    "normalisedValue": raw_value,
                }
            )
    return extracted, unmapped, raw_rows


def _submitted_employee_forms_split_name(value: str) -> tuple[str, str]:
    clean = re.sub(r"\s+", " ", str(value or "").strip())
    if not clean:
        return "", ""
    parts = clean.split(" ")
    if len(parts) == 1:
        return parts[0], ""
    return parts[0], " ".join(parts[1:])


def _gmail_collect_attachment_candidates(message_payload: dict) -> list[dict]:
    payload = message_payload.get("payload") if isinstance(message_payload.get("payload"), dict) else {}

    def _walk_parts(part: dict) -> list[dict]:
        if not isinstance(part, dict):
            return []
        outputs: list[dict] = []
        filename = str(part.get("filename") or "").strip()
        mime_type = str(part.get("mimeType") or "").strip().lower()
        body = part.get("body") if isinstance(part.get("body"), dict) else {}
        attachment_id = str(body.get("attachmentId") or "").strip()
        inline_data = str(body.get("data") or "").strip()
        if filename and (attachment_id or inline_data):
            outputs.append(
                {
                    "filename": filename[:200],
                    "mimeType": mime_type or "application/octet-stream",
                    "attachmentId": attachment_id,
                    "inlineData": inline_data,
                }
            )
        children = part.get("parts") if isinstance(part.get("parts"), list) else []
        for child in children:
            outputs.extend(_walk_parts(child if isinstance(child, dict) else {}))
        return outputs

    return _walk_parts(payload)


def _gmail_message_body_text(message_payload: dict) -> str:
    payload = message_payload.get("payload") if isinstance(message_payload.get("payload"), dict) else {}

    def _walk_parts(part: dict) -> list[str]:
        if not isinstance(part, dict):
            return []
        outputs: list[str] = []
        mime_type = str(part.get("mimeType") or "").strip().lower()
        body = part.get("body") if isinstance(part.get("body"), dict) else {}
        data = _gmail_decode_body_data(body.get("data") or "")
        if data and mime_type in {"text/plain", "text/html", ""}:
            outputs.append(data)
        children = part.get("parts") if isinstance(part.get("parts"), list) else []
        for child in children:
            outputs.extend(_walk_parts(child if isinstance(child, dict) else {}))
        return outputs

    texts = _walk_parts(payload)
    if not texts:
        return ""
    joined = "\n".join(texts)
    if "<" in joined and ">" in joined:
        joined = re.sub(r"<[^>]+>", " ", joined)
    joined = joined.replace("\r\n", "\n").replace("\r", "\n").replace("\u00a0", " ")
    joined = re.sub(r"[ \t]+", " ", joined)
    joined = re.sub(r"\n{3,}", "\n\n", joined)
    return joined.strip()


def _parse_email_contact(value: str) -> tuple[str, str]:
    raw = str(value or "").strip()
    if not raw:
        return "", ""
    match = re.search(r"<([^>]+)>", raw)
    if match:
        email_value = str(match.group(1) or "").strip().lower()
        name_value = raw.replace(match.group(0), "").strip().strip('"')
        return name_value, email_value
    if "@" in raw and " " not in raw:
        return "", raw.lower()
    return raw.strip('"'), ""


def _gmail_received_at(message_payload: dict) -> datetime | None:
    internal_ms = str(message_payload.get("internalDate") or "").strip()
    if internal_ms.isdigit():
        try:
            return datetime.fromtimestamp(int(internal_ms) / 1000, tz=timezone.utc)
        except Exception:
            pass
    date_header = _gmail_header_value(message_payload, "Date")
    if not date_header:
        return None
    try:
        parsed = parsedate_to_datetime(date_header)
    except Exception:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _extract_employee_identity(subject: str, snippet: str, body_text: str) -> dict:
    combined = "\n".join([str(subject or ""), str(snippet or ""), str(body_text or "")]).strip()
    lines = [line.strip() for line in str(body_text or "").splitlines() if line and line.strip()]

    def _normalise_label(value: str) -> str:
        cleaned = re.sub(r"[^a-z0-9]+", " ", str(value or "").lower())
        return re.sub(r"\s+", " ", cleaned).strip()

    def _next_line_after_label(label_candidates: list[str]) -> str:
        labels = [str(label or "").strip() for label in label_candidates if str(label or "").strip()]
        normalised_labels = [_normalise_label(label) for label in labels]
        for index, line in enumerate(lines):
            raw_line = str(line or "").strip()
            if not raw_line:
                continue
            for label in labels:
                escaped = re.escape(label)
                inline_with_separator = re.match(
                    rf"(?i)^\s*{escaped}\s*(?:\([^)]*\))?\s*\*?\s*[:\-]\s*(.+?)\s*$",
                    raw_line,
                )
                if inline_with_separator:
                    return str(inline_with_separator.group(1) or "").strip()
                inline_without_separator = re.match(
                    rf"(?i)^\s*{escaped}\s*(?:\([^)]*\))?\s*\*?\s+(.+?)\s*$",
                    raw_line,
                )
                if inline_without_separator:
                    return str(inline_without_separator.group(1) or "").strip()

            normalised_line = _normalise_label(raw_line)
            if normalised_line in normalised_labels:
                for next_index in range(index + 1, len(lines)):
                    next_line = str(lines[next_index] or "").strip()
                    if next_line:
                        return next_line
        return ""

    def _find(pattern: str) -> str:
        match = re.search(pattern, combined, flags=re.IGNORECASE)
        return str(match.group(1) or "").strip() if match else ""

    def _fallback_email_from_context(
        text: str,
        candidate_lines: list[str],
        *,
        name_parts: list[str],
    ) -> str:
        email_pattern = r"\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b"
        line_candidates: list[str] = []
        for line in candidate_lines:
            if not isinstance(line, str):
                continue
            if re.search(r"\b(employee|starter|new\s+joiner|new\s+employee|onboard)\b", line, flags=re.IGNORECASE):
                line_candidates.extend(re.findall(email_pattern, line, flags=re.IGNORECASE))
        if line_candidates:
            unique_line = list(dict.fromkeys(item.strip().lower() for item in line_candidates if str(item or "").strip()))
            if len(unique_line) == 1:
                return unique_line[0]

        all_matches = re.findall(email_pattern, text, flags=re.IGNORECASE)
        unique_matches = list(dict.fromkeys(item.strip().lower() for item in all_matches if str(item or "").strip()))
        if not unique_matches:
            return ""
        if len(unique_matches) == 1:
            return unique_matches[0]

        clean_tokens = [
            re.sub(r"[^a-z0-9]", "", str(token or "").strip().lower())
            for token in name_parts
        ]
        clean_tokens = [token for token in clean_tokens if len(token) >= 2]
        if not clean_tokens:
            return ""

        def _score(email_value: str) -> int:
            local = str(email_value.split("@", 1)[0] if "@" in email_value else email_value).lower()
            local_clean = re.sub(r"[^a-z0-9]", "", local)
            score = 0
            for token in clean_tokens:
                if token and token in local_clean:
                    score += 2
            if len(clean_tokens) >= 2 and all(token in local_clean for token in clean_tokens[:2]):
                score += 2
            return score

        scored = sorted(
            ((email, _score(email)) for email in unique_matches),
            key=lambda item: item[1],
            reverse=True,
        )
        best_email, best_score = scored[0]
        if best_score <= 0:
            return ""
        if len(scored) > 1 and scored[1][1] == best_score:
            return ""
        return best_email

    full_name = (
        _next_line_after_label(["Name", "Employee Name", "Full Name"])
        or _find(r"(?:employee\s*name|full\s*name)\s*[:\-]\s*([^\n,;]+)")
    )
    first_name = (
        _next_line_after_label(["First Name"])
        or _find(r"(?:first\s*name)\s*[:\-]\s*([^\n,;]+)")
    )
    last_name = (
        _next_line_after_label(["Last Name", "Surname"])
        or _find(r"(?:last\s*name|surname)\s*[:\-]\s*([^\n,;]+)")
    )
    email_value = (
        _next_line_after_label(["Email", "Employee Email", "Email Address"])
        or _find(r"(?:employee\s*email|email\s*address|email)\s*[:\-]\s*([^\s,;]+@[^\s,;]+)")
    )
    employer_name = (
        _next_line_after_label(["Employer", "Employer Name", "Company", "Company Name", "Business Name"])
        or _find(r"(?:employer(?:\s*name)?|company(?:\s*name)?|business(?:\s*name)?)\s*[:\-]\s*([^\n,;]+)")
    )
    employee_phone = (
        _next_line_after_label(["Phone", "Telephone", "Mobile", "Contact Number", "Phone Number"])
        or _find(r"(?:phone|telephone|mobile|contact\s*number|phone\s*number)\s*[:\-]\s*([^\n,;]+)")
    )
    title = (
        _next_line_after_label(["Title", "Employee Title"])
        or _find(r"(?:title|employee\s*title)\s*(?:\([^)]*\))?\s*\*?\s*[:\-]?\s*([^\n,;]+)")
    )
    gender = (
        _next_line_after_label(["Gender", "Gender (M/F)", "Sex"])
        or _find(r"(?:gender(?:\s*\(m\/f\))?|sex)\s*\*?\s*[:\-]?\s*([^\n,;]+)")
    )
    date_of_birth = (
        _next_line_after_label(["Date of Birth", "DOB", "Birth Date"])
        or _find(r"(?:date\s*of\s*birth|dob|birth\s*date)\s*[:\-]\s*([^\n,;]+)")
    )
    ni_number = (
        _next_line_after_label(["National Insurance Number", "National Insurance", "NI Number", "NINO"])
        or _find(r"(?:national\s*insurance(?:\s*number)?|ni\s*number|nino)\s*[:\-]\s*([A-Za-z0-9 ]{8,})")
    )
    start_date = (
        _next_line_after_label(["Start Date", "Employment Start Date"])
        or _find(r"(?:start\s*date|employment\s*start\s*date)\s*[:\-]\s*([^\n,;]+)")
    )
    job_title = (
        _next_line_after_label(["Job Title", "Role", "Position"])
        or _find(r"(?:job\s*title|role|position)\s*[:\-]\s*([^\n,;]+)")
    )
    department = (
        _next_line_after_label(["Department", "Team"])
        or _find(r"(?:department|team)\s*[:\-]\s*([^\n,;]+)")
    )
    payroll_number = (
        _next_line_after_label(["Payroll Number", "Employee Number", "Staff Number"])
        or _find(r"(?:payroll\s*number|employee\s*number|staff\s*number)\s*[:\-]\s*([^\n,;]+)")
    )
    tax_code = (
        _next_line_after_label(["Tax Code"])
        or _find(r"(?:tax\s*code)\s*[:\-]\s*([^\n,;]+)")
    )
    employment_type = (
        _next_line_after_label(["Employment Type", "Contract Type"])
        or _find(r"(?:employment\s*type|contract\s*type)\s*[:\-]\s*([^\n,;]+)")
    )
    hours_per_week = (
        _next_line_after_label(["Hours", "Hours Per Week"])
        or _find(r"(?:hours(?:\s*per\s*week)?)\s*[:\-]\s*([^\n,;]+)")
    )
    salary = (
        _next_line_after_label(["Salary", "Pay", "Annual Salary"])
        or _find(r"(?:salary|pay|annual\s*salary)\s*[:\-]\s*([^\n,;]+)")
    )
    address_line_1 = _next_line_after_label(["Address", "Address Line 1"]) or _find(r"(?:address(?:\s*line\s*1)?)\s*[:\-]\s*([^\n]+)")
    address_line_2 = _next_line_after_label(["Address Line 2"]) or _find(r"(?:address\s*line\s*2)\s*[:\-]\s*([^\n,;]+)")
    city = _next_line_after_label(["City", "Town"]) or _find(r"(?:city|town)\s*[:\-]\s*([^\n,;]+)")
    postcode = _next_line_after_label(["Postcode", "Postal Code"]) or _find(r"(?:postcode|postal\s*code)\s*[:\-]\s*([^\n,;]+)")
    country = _next_line_after_label(["Country"]) or _find(r"(?:country)\s*[:\-]\s*([^\n,;]+)")
    bank_account_name = _next_line_after_label(["Account Name", "Bank Account Name"]) or _find(r"(?:bank\s*account\s*name|account\s*name)\s*[:\-]\s*([^\n,;]+)")
    bank_account_number = _next_line_after_label(["Account Number", "Bank Account Number"]) or _find(r"(?:bank\s*account\s*number|account\s*number)\s*[:\-]\s*([A-Za-z0-9 ]+)")
    bank_sort_code = _next_line_after_label(["Sort Code", "Bank Sort Code"]) or _find(r"(?:sort\s*code|bank\s*sort\s*code)\s*[:\-]\s*([A-Za-z0-9\- ]+)")
    if not full_name and _submitted_employee_forms_subject_matches(subject):
        full_name = _submitted_employee_forms_subject_suffix(subject).strip().strip("-: ")

    full_name = re.sub(r"\s+", " ", str(full_name or "")).strip()
    first_name = re.sub(r"\s+", " ", str(first_name or "")).strip()
    last_name = re.sub(r"\s+", " ", str(last_name or "")).strip()

    if full_name and (not first_name or not last_name):
        parts = [part for part in re.split(r"\s+", full_name) if part]
        if parts and not first_name:
            first_name = parts[0]
        if len(parts) >= 2 and not last_name:
            last_name = " ".join(parts[1:])
    if not full_name and (first_name or last_name):
        full_name = " ".join(part for part in [first_name, last_name] if part).strip()
    if not email_value:
        email_value = _fallback_email_from_context(
            combined,
            lines,
            name_parts=[first_name, last_name, full_name],
        )

    return {
        "employeeFullName": full_name[:160],
        "employeeFirstName": first_name[:80],
        "employeeLastName": last_name[:120],
        "employeeEmail": email_value.lower()[:160],
        "employerName": re.sub(r"\s+", " ", str(employer_name or "")).strip()[:180],
        "title": _submitted_employee_forms_normalise_title(title),
        "gender": _submitted_employee_forms_normalise_gender(gender, title=title),
        "employeePhone": re.sub(r"\s+", " ", str(employee_phone or "")).strip()[:80],
        "dateOfBirth": re.sub(r"\s+", " ", str(date_of_birth or "")).strip()[:32],
        "nationalInsuranceNumber": re.sub(r"\s+", "", str(ni_number or "")).strip().upper()[:20],
        "startDate": re.sub(r"\s+", " ", str(start_date or "")).strip()[:32],
        "jobTitle": re.sub(r"\s+", " ", str(job_title or "")).strip()[:120],
        "department": re.sub(r"\s+", " ", str(department or "")).strip()[:120],
        "payrollNumber": re.sub(r"\s+", " ", str(payroll_number or "")).strip()[:64],
        "taxCode": re.sub(r"\s+", " ", str(tax_code or "")).strip()[:64],
        "employmentType": re.sub(r"\s+", " ", str(employment_type or "")).strip()[:64],
        "hoursPerWeek": re.sub(r"\s+", " ", str(hours_per_week or "")).strip()[:40],
        "salary": re.sub(r"\s+", " ", str(salary or "")).strip()[:64],
        "addressLine1": re.sub(r"\s+", " ", str(address_line_1 or "")).strip()[:160],
        "addressLine2": re.sub(r"\s+", " ", str(address_line_2 or "")).strip()[:160],
        "city": re.sub(r"\s+", " ", str(city or "")).strip()[:120],
        "postcode": re.sub(r"\s+", " ", str(postcode or "")).strip()[:32],
        "country": _submitted_employee_forms_normalise_country_name(country),
        "bankAccountName": re.sub(r"\s+", " ", str(bank_account_name or "")).strip()[:120],
        "bankAccountNumber": re.sub(r"\s+", "", str(bank_account_number or "")).strip()[:34],
        "bankSortCode": re.sub(r"[^0-9A-Za-z\-]", "", str(bank_sort_code or "")).strip()[:20],
    }


def _submitted_employee_forms_ai_request_text(subject: str, snippet: str, body_text: str) -> str:
    return (
        "Extract employee onboarding form fields from this email content. "
        "Use only explicit values present in the text. "
        "Attached files (if provided) are part of the same submission and should be used for extraction. "
        "Pay special attention to labels like 'Title *' and 'Gender (M/F) *' which may appear on separate lines from values. "
        "Set country to 'United Kingdom' when it is missing or listed as UK/GB/England/Scotland/Wales/Northern Ireland. "
        "Return empty strings where unknown.\n\n"
        f"Subject:\n{subject}\n\n"
        f"Gmail snippet:\n{snippet}\n\n"
        f"Body text:\n{body_text[:12000]}"
    )


async def _submitted_employee_forms_extract_with_openai(
    subject: str,
    snippet: str,
    body_text: str,
    *,
    attachment_inputs: list[dict] | None = None,
    user_id: str | None = None,
) -> dict:
    if not str(get_settings().openai_api_key or "").strip():
        return {}
    content_blocks: list[dict] = []
    for block in attachment_inputs or []:
        if not isinstance(block, dict):
            continue
        block_type = str(block.get("type") or "").strip()
        if block_type in {"input_file", "input_image"}:
            content_blocks.append(block)
    content_blocks.append(
        {
            "type": "input_text",
            "text": _submitted_employee_forms_ai_request_text(subject, snippet, body_text),
        }
    )
    request_body = {
        "input": [{"role": "user", "content": content_blocks}],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "submitted_employee_form_extraction",
                "schema": SUBMITTED_EMPLOYEE_FORMS_AI_EXTRACTION_SCHEMA,
                "strict": True,
            }
        },
        "max_output_tokens": 2400,
    }
    try:
        payload = await _post_openai_responses(
            request_body,
            "submitted employee form extraction",
            timeout_seconds=30,
            user_id=user_id,
            feature="submitted-employee-forms",
            page="submitted-employee-forms",
        )
        parsed = _load_openai_json_response(payload, "OpenAI returned invalid JSON for submitted employee form extraction.")
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        logger.exception("submitted_employee_forms_openai_extraction_failed")
        return {}


def _submitted_employee_forms_normalise_date(value: str) -> str:
    raw_value = re.sub(r"\s+", " ", str(value or "")).strip().strip("\"'")
    if not raw_value:
        return ""
    raw_value = re.sub(r"[\u2010\u2011\u2012\u2013\u2014\u2015\u2212\uFE58\uFE63\uFF0D]", "-", raw_value)
    raw_value = re.sub(r"[./]", "-", raw_value)
    raw_value = raw_value.strip()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw_value):
        return raw_value
    if re.fullmatch(r"\d{8}", raw_value):
        try:
            return datetime.strptime(raw_value, "%Y%m%d").date().isoformat()
        except Exception:
            pass
    iso_prefix = re.match(r"(\d{4}-\d{2}-\d{2})[T\s]", raw_value)
    if iso_prefix:
        return iso_prefix.group(1)
    cleaned = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", raw_value, flags=re.IGNORECASE)
    for fmt in (
        "%Y-%m-%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d.%m.%Y",
        "%d %b %Y",
        "%d %B %Y",
        "%b %d %Y",
        "%B %d %Y",
        "%d %b, %Y",
        "%d %B, %Y",
        "%b %d, %Y",
        "%B %d, %Y",
        "%Y/%m/%d",
        "%Y.%m.%d",
        "%d/%m/%y",
        "%d-%m-%y",
        "%m/%d/%Y",
        "%m-%d-%Y",
    ):
        try:
            return datetime.strptime(cleaned, fmt).date().isoformat()
        except Exception:
            continue
    return ""


def _submitted_employee_forms_normalise_title(value: str) -> str:
    clean_value = re.sub(r"\s+", " ", str(value or "")).strip().strip(".")
    if not clean_value:
        return ""
    normalised = clean_value.lower().replace(".", "")
    if normalised in {"mr", "mister"}:
        return "Mr"
    if normalised in {"mrs"}:
        return "Mrs"
    if normalised in {"ms"}:
        return "Ms"
    if normalised in {"miss"}:
        return "Miss"
    if normalised in {"mx"}:
        return "Mx"
    return clean_value[:35]


def _submitted_employee_forms_normalise_gender(value: str, *, title: str = "") -> str:
    clean_value = re.sub(r"\s+", " ", str(value or "")).strip().lower()
    if clean_value in {"m", "male", "man"}:
        return "M"
    if clean_value in {"f", "female", "woman"}:
        return "F"
    title_key = re.sub(r"\s+", "", str(title or "")).strip().lower().replace(".", "")
    if title_key in {"mr", "mister"}:
        return "M"
    if title_key in {"mrs", "ms", "miss"}:
        return "F"
    return ""


def _submitted_employee_forms_normalise_country_name(value: str) -> str:
    clean_value = re.sub(r"\s+", " ", str(value or "")).strip()
    if not clean_value:
        return ""
    key = clean_value.lower().replace(".", "")
    country_aliases = {
        "gb": "United Kingdom",
        "gbr": "United Kingdom",
        "uk": "United Kingdom",
        "england": "United Kingdom",
        "scotland": "United Kingdom",
        "wales": "United Kingdom",
        "northern ireland": "United Kingdom",
        "united kingdom": "United Kingdom",
        "united kingdom of great britain and northern ireland": "United Kingdom",
        "us": "United States",
        "usa": "United States",
        "united states": "United States",
        "united states of america": "United States",
    }
    return str(country_aliases.get(key) or clean_value)[:50]


def _submitted_employee_forms_merged_identity(local_identity: dict, ai_identity: dict) -> dict:
    merged: dict[str, str] = {}
    for key in SUBMITTED_EMPLOYEE_FORMS_AI_EXTRACTION_SCHEMA.get("required", []):
        ai_value = re.sub(r"\s+", " ", str((ai_identity or {}).get(key) or "")).strip()
        local_value = re.sub(r"\s+", " ", str((local_identity or {}).get(key) or "")).strip()
        merged[key] = ai_value or local_value
    if not merged.get("employeeFullName"):
        merged["employeeFullName"] = " ".join(
            part for part in [merged.get("employeeFirstName", ""), merged.get("employeeLastName", "")] if part
        ).strip()
    if not merged.get("employeeFirstName") and merged.get("employeeFullName"):
        parts = [part for part in re.split(r"\s+", merged["employeeFullName"]) if part]
        if parts:
            merged["employeeFirstName"] = parts[0]
        if len(parts) >= 2 and not merged.get("employeeLastName"):
            merged["employeeLastName"] = " ".join(parts[1:])
    merged["employeeEmail"] = str(merged.get("employeeEmail") or "").lower()
    merged["nationalInsuranceNumber"] = re.sub(r"\s+", "", str(merged.get("nationalInsuranceNumber") or "")).upper()
    merged["title"] = _submitted_employee_forms_normalise_title(str(merged.get("title") or ""))
    merged["gender"] = _submitted_employee_forms_normalise_gender(
        str(merged.get("gender") or ""),
        title=str(merged.get("title") or ""),
    )
    merged["country"] = "United Kingdom"
    for field_name in ("dateOfBirth", "startDate"):
        value = str(merged.get(field_name) or "").strip()
        normalised = _submitted_employee_forms_normalise_date(value)
        merged[field_name] = normalised or value
    missing = (ai_identity or {}).get("missingOrUnclear")
    merged["missingOrUnclear"] = [
        str(item).strip() for item in (missing if isinstance(missing, list) else []) if str(item).strip()
    ]
    return merged


def _xero_payroll_employee_identity(row: dict) -> tuple[str, str, str]:
    employee_id = str(
        row.get("EmployeeID")
        or row.get("employeeID")
        or row.get("EmployeeId")
        or row.get("employeeId")
        or ""
    ).strip()
    email_value = str(row.get("Email") or row.get("email") or "").strip().lower()
    first = str(row.get("FirstName") or row.get("firstName") or "").strip()
    last = str(row.get("LastName") or row.get("lastName") or "").strip()
    full_name = " ".join(part for part in [first, last] if part).strip().lower()
    if not full_name:
        full_name = str(row.get("Name") or row.get("name") or "").strip().lower()
    return employee_id, email_value, full_name


def _submitted_forms_normalized_employee_name(value: str | None) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).lower()


def _submitted_forms_normalized_ni(value: str | None) -> str:
    return re.sub(r"[^A-Za-z0-9]", "", str(value or "").strip()).upper()


def _submitted_forms_normalized_email(value: str | None) -> str:
    return re.sub(r"\s+", "", str(value or "").strip()).lower()


def _submitted_forms_normalized_dob(value: str | None) -> str:
    return _submitted_employee_forms_normalise_date(str(value or "")) or ""


def _submitted_forms_duplicate_evaluation(target_row: dict, existing_rows: list[dict]) -> dict:
    extracted = target_row.get("extracted_fields") if isinstance(target_row.get("extracted_fields"), dict) else {}
    target_id = str(target_row.get("id") or "").strip()
    target_ni = _submitted_forms_normalized_ni(extracted.get("nationalInsuranceNumber"))
    target_email = _submitted_forms_normalized_email(target_row.get("employee_email") or extracted.get("employeeEmail"))
    target_dob = _submitted_forms_normalized_dob(extracted.get("dateOfBirth"))
    target_name = _submitted_forms_normalized_employee_name(
        " ".join(
            part for part in [
                str(target_row.get("employee_first_name") or "").strip(),
                str(target_row.get("employee_last_name") or "").strip(),
            ] if part
        ) or target_row.get("employee_full_name")
    )
    target_start = _submitted_employee_forms_normalise_date(str(extracted.get("startDate") or "")) or ""

    strong_matches: list[dict] = []
    moderate_matches: list[dict] = []
    for row in existing_rows:
        row_id = str(row.get("id") or "").strip()
        if not row_id or row_id == target_id:
            continue
        row_extracted = row.get("extracted_fields") if isinstance(row.get("extracted_fields"), dict) else {}
        row_ni = _submitted_forms_normalized_ni(row_extracted.get("nationalInsuranceNumber"))
        row_email = _submitted_forms_normalized_email(row.get("employee_email") or row_extracted.get("employeeEmail"))
        row_dob = _submitted_forms_normalized_dob(row_extracted.get("dateOfBirth"))
        row_name = _submitted_forms_normalized_employee_name(
            " ".join(
                part for part in [
                    str(row.get("employee_first_name") or "").strip(),
                    str(row.get("employee_last_name") or "").strip(),
                ] if part
            ) or row.get("employee_full_name")
        )
        row_start = _submitted_employee_forms_normalise_date(str(row_extracted.get("startDate") or "")) or ""
        reasons: list[str] = []
        strength = "none"
        if target_ni and row_ni and target_ni == row_ni:
            reasons.append("NI exact match")
            strength = "strong"
        if target_email and row_email and target_email == row_email:
            reasons.append("Email exact match")
            if strength != "strong":
                strength = "strong"
        if target_name and target_dob and row_name and row_dob and target_name == row_name and target_dob == row_dob:
            reasons.append("Name + DOB match")
            if strength != "strong":
                strength = "strong"
        if target_name and target_start and row_name and row_start and target_name == row_name and target_start == row_start:
            reasons.append("Name + start-date match")
            if strength == "none":
                strength = "moderate"
        if not reasons:
            continue
        match = {
            "submissionId": row_id,
            "xeroStatus": str(row.get("xero_status") or ""),
            "employeeName": str(row.get("employee_full_name") or ""),
            "employeeEmail": str(row.get("employee_email") or ""),
            "reasons": reasons,
            "strength": strength,
        }
        if strength == "strong":
            strong_matches.append(match)
        else:
            moderate_matches.append(match)
    return {
        "strong": strong_matches,
        "moderate": moderate_matches,
        "blockPublish": bool(strong_matches),
    }


def _submitted_forms_xero_duplicate_evaluation(target_row: dict, xero_employees: list[dict]) -> dict:
    extracted = target_row.get("extracted_fields") if isinstance(target_row.get("extracted_fields"), dict) else {}
    target_ni = _submitted_forms_normalized_ni(extracted.get("nationalInsuranceNumber"))
    target_email = _submitted_forms_normalized_email(target_row.get("employee_email") or extracted.get("employeeEmail"))
    target_dob = _submitted_forms_normalized_dob(extracted.get("dateOfBirth"))
    target_name = _submitted_forms_normalized_employee_name(
        " ".join(
            part for part in [
                str(target_row.get("employee_first_name") or "").strip(),
                str(target_row.get("employee_last_name") or "").strip(),
            ] if part
        ) or target_row.get("employee_full_name")
    )
    target_start = _submitted_employee_forms_normalise_date(str(extracted.get("startDate") or "")) or ""
    strong_matches: list[dict] = []
    moderate_matches: list[dict] = []

    for employee in xero_employees:
        if not isinstance(employee, dict):
            continue
        employee_id = str(employee.get("EmployeeID") or employee.get("employeeID") or employee.get("employeeId") or "").strip()
        employee_email = _submitted_forms_normalized_email(employee.get("Email") or employee.get("email"))
        employee_ni = _submitted_forms_normalized_ni(employee.get("NationalInsuranceNumber") or employee.get("nationalInsuranceNumber"))
        employee_dob = _submitted_forms_normalized_dob(employee.get("DateOfBirth") or employee.get("dateOfBirth"))
        employee_name = _submitted_forms_normalized_employee_name(
            " ".join(
                part for part in [
                    str(employee.get("FirstName") or employee.get("firstName") or "").strip(),
                    str(employee.get("LastName") or employee.get("lastName") or "").strip(),
                ] if part
            )
        )
        employee_start = _submitted_employee_forms_normalise_date(str(employee.get("StartDate") or employee.get("DateOfJoining") or "")) or ""

        reasons: list[str] = []
        strength = "none"
        if target_ni and employee_ni and target_ni == employee_ni:
            reasons.append("Xero NI exact match")
            strength = "strong"
        if target_email and employee_email and target_email == employee_email:
            reasons.append("Xero email exact match")
            if strength != "strong":
                strength = "strong"
        if target_name and target_dob and employee_name and employee_dob and target_name == employee_name and target_dob == employee_dob:
            reasons.append("Xero name + DOB match")
            if strength != "strong":
                strength = "strong"
        if target_name and target_start and employee_name and employee_start and target_name == employee_name and target_start == employee_start:
            reasons.append("Xero name + start-date match")
            if strength == "none":
                strength = "moderate"
        if not reasons:
            continue
        payload = {
            "employeeId": employee_id,
            "employeeName": str(employee.get("FullName") or f"{employee.get('FirstName') or ''} {employee.get('LastName') or ''}").strip(),
            "employeeEmail": employee_email,
            "reasons": reasons,
            "strength": strength,
        }
        if strength == "strong":
            strong_matches.append(payload)
        else:
            moderate_matches.append(payload)
    return {
        "strong": strong_matches,
        "moderate": moderate_matches,
        "blockPublish": bool(strong_matches),
    }


def _submitted_forms_xero_employee_name_strict(row: dict) -> str:
    first = re.sub(r"\s+", " ", str(row.get("FirstName") or row.get("firstName") or "")).strip()
    last = re.sub(r"\s+", " ", str(row.get("LastName") or row.get("lastName") or "")).strip()
    return _submitted_forms_normalized_employee_name(" ".join(part for part in [first, last] if part))


def _canonical_xero_employee_id(value: str | None) -> str:
    return str(value or "").strip().strip("{}").lower()


def _submitted_employee_forms_summary(rows: list[dict]) -> dict:
    total = len(rows)
    created = sum(1 for row in rows if str(row.get("xero_status") or "").strip().lower() == "created")
    exists = sum(1 for row in rows if str(row.get("xero_status") or "").strip().lower() == "exists")
    pending = sum(1 for row in rows if str(row.get("xero_status") or "").strip().lower() in {"", "pending"})
    failed = sum(1 for row in rows if str(row.get("xero_status") or "").strip().lower() == "failed")
    review = sum(1 for row in rows if str(row.get("xero_status") or "").strip().lower() == "needs-review")
    workflow_counts: dict[str, int] = {}
    for row in rows:
        key = str(row.get("workflow_status") or "new").strip().lower() or "new"
        workflow_counts[key] = int(workflow_counts.get(key) or 0) + 1
    return {
        "total": total,
        "created": created,
        "exists": exists,
        "pending": pending,
        "failed": failed,
        "needsReview": review,
        "workflow": workflow_counts,
    }


def _submitted_employee_forms_rows_payload(rows: list[dict]) -> list[dict]:
    def _extracted_fields_payload(row: dict) -> dict:
        value = row.get("extracted_fields")
        if isinstance(value, dict):
            return value
        if isinstance(value, str) and value.strip():
            try:
                parsed = json.loads(value)
                return parsed if isinstance(parsed, dict) else {}
            except ValueError:
                return {}
        return {}

    return [
        {
            "id": str(row.get("id") or ""),
            "gmailMessageId": str(row.get("gmail_message_id") or ""),
            "gmailThreadId": str(row.get("gmail_thread_id") or ""),
            "subject": str(row.get("subject") or ""),
            "receivedAt": _iso(row.get("received_at")) or "",
            "fromName": str(row.get("from_name") or ""),
            "fromEmail": str(row.get("from_email") or ""),
            "employeeFullName": str(row.get("employee_full_name") or ""),
            "employeeFirstName": str(row.get("employee_first_name") or ""),
            "employeeLastName": str(row.get("employee_last_name") or ""),
            "employeeEmail": str(row.get("employee_email") or ""),
            "employerName": str(row.get("employer_name") or ""),
            "extractedFields": _extracted_fields_payload(row),
            "snippet": str(row.get("snippet") or ""),
            "xeroTenantId": str(row.get("xero_tenant_id") or ""),
            "xeroTenantName": str(row.get("xero_tenant_name") or ""),
            "clientManager": str(row.get("client_manager") or ""),
            "clientManagerUserIds": (
                [str(item).strip() for item in (row.get("client_manager_user_ids") if isinstance(row.get("client_manager_user_ids"), list) else []) if str(item).strip()]
            ),
            "xeroEmployeeId": str(row.get("xero_employee_id") or ""),
            "xeroStatus": str(row.get("xero_status") or "pending"),
            "xeroNote": str(row.get("xero_note") or ""),
            "workflowStatus": str(row.get("workflow_status") or "new"),
            "sectionStatus": row.get("section_status") if isinstance(row.get("section_status"), dict) else {},
            "employeeData": row.get("employee_data") if isinstance(row.get("employee_data"), list) else [],
            "unmappedFields": row.get("unmapped_fields") if isinstance(row.get("unmapped_fields"), dict) else {},
            "csvSha256": str(row.get("csv_sha256") or ""),
            "attemptHistory": (
                row.get("attempt_history")
                if isinstance(row.get("attempt_history"), list)
                else []
            ),
            "createdAt": _iso(row.get("created_at")) or "",
            "updatedAt": _iso(row.get("updated_at")) or "",
        }
        for row in rows
    ]


def _submitted_employee_forms_query_rows(user_id: str) -> list[dict]:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT *
                        FROM submitted_employee_forms
                        WHERE user_id = %s
                        ORDER BY COALESCE(received_at, created_at) DESC, created_at DESC
                        LIMIT 5000
                        """,
                        (user_id,),
                    )
                    rows = cursor.fetchall() or []
                connection.commit()
            return _attach_submitted_employee_forms_attempt_history(user_id, rows)
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _submitted_employee_form_attempts_by_row_ids(user_id: str, row_ids: list[str], limit_per_row: int = 20) -> dict[str, list[dict]]:
    clean_ids = [str(row_id or "").strip() for row_id in row_ids if str(row_id or "").strip()]
    if not clean_ids:
        return {}
    attempts_by_row_id: dict[str, list[dict]] = {row_id: [] for row_id in clean_ids}
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT *
                        FROM submitted_employee_form_attempts
                        WHERE user_id = %s
                          AND submitted_employee_form_id = ANY(%s)
                        ORDER BY created_at DESC
                        """,
                        (user_id, clean_ids),
                    )
                    attempt_rows = cursor.fetchall() or []
                connection.commit()
            for attempt in attempt_rows:
                row_id = str(attempt.get("submitted_employee_form_id") or "").strip()
                if not row_id:
                    continue
                target_list = attempts_by_row_id.setdefault(row_id, [])
                if len(target_list) >= max(1, int(limit_per_row or 20)):
                    continue
                target_list.append(
                    {
                        "id": str(attempt.get("id") or ""),
                        "attemptType": str(attempt.get("attempt_type") or "process"),
                        "xeroStatus": str(attempt.get("xero_status") or "pending"),
                        "xeroTenantId": str(attempt.get("xero_tenant_id") or ""),
                        "xeroTenantName": str(attempt.get("xero_tenant_name") or ""),
                        "xeroEmployeeId": str(attempt.get("xero_employee_id") or ""),
                        "note": str(attempt.get("note") or ""),
                        "createdAt": _iso(attempt.get("created_at")) or "",
                    }
                )
            return attempts_by_row_id
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _attach_submitted_employee_forms_attempt_history(user_id: str, rows: list[dict], limit_per_row: int = 20) -> list[dict]:
    if not rows:
        return rows
    row_ids = [str(row.get("id") or "").strip() for row in rows if str(row.get("id") or "").strip()]
    attempts_by_row_id = _submitted_employee_form_attempts_by_row_ids(user_id, row_ids, limit_per_row=limit_per_row)
    enriched_rows: list[dict] = []
    for row in rows:
        row_id = str(row.get("id") or "").strip()
        enriched = dict(row)
        enriched["attempt_history"] = attempts_by_row_id.get(row_id, [])
        enriched_rows.append(enriched)
    return enriched_rows


def _submitted_employee_forms_manager_directory() -> list[dict]:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT id, full_name, email, role, status
                        FROM users
                        WHERE COALESCE(status, 'active') = 'active'
                        ORDER BY COALESCE(NULLIF(full_name, ''), email) ASC, id ASC
                        """
                    )
                    user_rows = cursor.fetchall() or []
                connection.commit()
            directory: list[dict] = []
            for row in user_rows:
                user_id = str(row.get("id") or "").strip()
                full_name = str(row.get("full_name") or "").strip()
                email = str(row.get("email") or "").strip().lower()
                if not user_id or not (full_name or email):
                    continue
                directory.append(
                    {
                        "id": user_id,
                        "fullName": full_name or email,
                        "email": email,
                        "role": str(row.get("role") or "").strip().lower(),
                        "status": str(row.get("status") or "active").strip().lower() or "active",
                    }
                )
            return directory
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _submitted_employee_forms_attach_client_manager(rows: list[dict], manager_directory: list[dict]) -> list[dict]:
    if not rows:
        return rows
    schema_repaired = False
    manager_lookup: dict[str, str] = {}
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT client_name, company_name, client_manager, uploaded_at
                        FROM ch_auth_code_register
                        WHERE COALESCE(TRIM(client_manager), '') <> ''
                        ORDER BY uploaded_at DESC, id DESC
                        """
                    )
                    register_rows = cursor.fetchall() or []
                connection.commit()
            for register_row in register_rows:
                manager_name = re.sub(r"\s+", " ", str(register_row.get("client_manager") or "")).strip()
                if not manager_name:
                    continue
                for candidate_name in (register_row.get("client_name"), register_row.get("company_name")):
                    key = _bm_tasks_normalise_name_key(str(candidate_name or ""))
                    if key and key not in manager_lookup:
                        manager_lookup[key] = manager_name
            break
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True
    user_ids_by_name: dict[str, list[str]] = {}
    for item in manager_directory:
        user_id = str(item.get("id") or "").strip()
        name_key = _bm_tasks_normalise_name_key(str(item.get("fullName") or ""))
        if user_id and name_key:
            user_ids_by_name.setdefault(name_key, []).append(user_id)
    enriched_rows: list[dict] = []
    for row in rows:
        enriched = dict(row)
        client_manager = ""
        for candidate in (
            row.get("xero_tenant_name"),
            row.get("employer_name"),
            row.get("from_name"),
        ):
            key = _bm_tasks_normalise_name_key(str(candidate or ""))
            if key and key in manager_lookup:
                client_manager = manager_lookup[key]
                break
        manager_key = _bm_tasks_normalise_name_key(client_manager)
        enriched["client_manager"] = client_manager
        enriched["client_manager_user_ids"] = user_ids_by_name.get(manager_key, []) if manager_key else []
        enriched_rows.append(enriched)
    return enriched_rows


def submitted_employee_forms_payload(user: dict) -> dict:
    connection_row = gmail_connection_for_user(user)
    gmail_status = "not_connected"
    gmail_message = "Connect Gmail to read submitted employee forms."
    needs_reconnect = False
    gmail_email = ""
    if connection_row:
        gmail_email = str(connection_row.get("gmail_email") or "")
        if _gmail_read_scope_granted(connection_row.get("scope")):
            gmail_status = "connected"
            gmail_message = "Gmail is connected and ready to read submitted employee forms."
        else:
            gmail_status = "reauth_required"
            gmail_message = "Reconnect Gmail and include read access to load submitted employee forms."
            needs_reconnect = True

    warnings: list[str] = []
    manager_directory: list[dict] = []
    rows: list[dict] = []
    try:
        manager_directory = _submitted_employee_forms_manager_directory()
    except Exception as exc:
        logger.exception("submitted_employee_forms_manager_directory_failed")
        warnings.append(f"manager_directory_failed:{_sync_error_message(exc)}")
    try:
        rows = _submitted_employee_forms_query_rows(str(user.get("id") or ""))
    except Exception as exc:
        logger.exception("submitted_employee_forms_rows_query_failed")
        warnings.append(f"rows_query_failed:{_sync_error_message(exc)}")
        rows = []
    try:
        rows = _submitted_employee_forms_attach_client_manager(rows, manager_directory)
    except Exception as exc:
        logger.exception("submitted_employee_forms_attach_client_manager_failed")
        warnings.append(f"client_manager_attach_failed:{_sync_error_message(exc)}")
    return {
        "submittedEmployeeForms": {
            "gmail": {
                "status": gmail_status,
                "message": gmail_message,
                "needsReconnect": needs_reconnect,
                "gmailEmail": gmail_email,
            },
            "rows": _submitted_employee_forms_rows_payload(rows),
            "summary": _submitted_employee_forms_summary(rows),
            "subjectPrefix": SUBMITTED_EMPLOYEE_FORMS_SUBJECT_PREFIX,
            "managerDirectory": manager_directory,
            "degraded": bool(warnings),
            "warnings": warnings,
        }
    }


async def _gmail_fetch_submitted_employee_messages(user: dict, lookback_days: int = 28) -> tuple[list[dict], dict]:
    response_meta = {
        "status": "not_connected",
        "message": "Connect Gmail to read submitted employee forms.",
        "needsReconnect": False,
        "gmailEmail": "",
        "diagnostics": {
            "messageIdsCollected": 0,
            "messagesInspected": 0,
            "subjectMatched": 0,
            "withinWindow": 0,
            "sampleSubjects": [],
        },
    }
    connection_row = gmail_connection_for_user(user)
    if not connection_row:
        return [], response_meta

    response_meta["gmailEmail"] = str(connection_row.get("gmail_email") or "")
    try:
        connection_row = await refresh_gmail_connection(connection_row)
    except HTTPException as exc:
        response_meta.update(
            {
                "status": "reauth_required",
                "message": str(exc.detail or "Reconnect Gmail to refresh access."),
                "needsReconnect": True,
            }
        )
        return [], response_meta
    if not _gmail_read_scope_granted(connection_row.get("scope")):
        response_meta.update(
            {
                "status": "reauth_required",
                "message": "Reconnect Gmail and grant read access to fetch submitted employee forms.",
                "needsReconnect": True,
            }
        )
        return [], response_meta

    headers = {"Authorization": f"Bearer {connection_row.get('access_token') or ''}"}
    safe_lookback_days = max(1, min(int(lookback_days or 28), 180))
    after_date = (utcnow() - timedelta(days=safe_lookback_days)).date()
    after_token = after_date.strftime("%Y/%m/%d")
    query_candidates = [
        f'{SUBMITTED_EMPLOYEE_FORMS_GMAIL_QUERY} after:{after_token}',
        f'in:anywhere {SUBMITTED_EMPLOYEE_FORMS_GMAIL_QUERY} after:{after_token}',
        f'in:anywhere to:theteam@jaccountancy.co.uk subject:"New Employee Details:" after:{after_token}',
        f'in:anywhere subject:"New Employee Details" after:{after_token}',
        'in:anywhere to:theteam@jaccountancy.co.uk subject:"New Employee Details:" has:attachment',
        'in:anywhere subject:"New Employee Details"',
    ]

    async with httpx.AsyncClient(timeout=30) as client:
        async def _collect_message_ids(params: dict, limit: int = SUBMITTED_EMPLOYEE_FORMS_MAX_HISTORIC_FETCH, max_pages: int = 8) -> list[str]:
            collected: list[str] = []
            page_token = ""
            pages = 0
            while pages < max_pages and len(collected) < limit:
                request_params = dict(params)
                if page_token:
                    request_params["pageToken"] = page_token
                list_response = await client.get(
                    GMAIL_MESSAGES_LIST_URL,
                    headers=headers,
                    params=request_params,
                )
                if list_response.is_error:
                    break
                list_payload = list_response.json() if list_response.content else {}
                message_rows = list_payload.get("messages") if isinstance(list_payload, dict) else []
                if not isinstance(message_rows, list):
                    message_rows = []
                for row in message_rows:
                    if not isinstance(row, dict):
                        continue
                    message_id = str(row.get("id") or "").strip()
                    if not message_id or message_id in seen_ids:
                        continue
                    seen_ids.add(message_id)
                    collected.append(message_id)
                    if len(collected) >= limit:
                        break
                page_token = str(list_payload.get("nextPageToken") or "").strip() if isinstance(list_payload, dict) else ""
                pages += 1
                if not page_token:
                    break
            return collected

        message_ids: list[str] = []
        seen_ids: set[str] = set()
        first_error: HTTPException | None = None
        diagnostics = response_meta.get("diagnostics") if isinstance(response_meta.get("diagnostics"), dict) else {}
        sample_subjects: list[str] = []
        diagnostics.setdefault("listErrors", 0)

        def _diag_increment(field: str, amount: int = 1) -> None:
            diagnostics[field] = int(diagnostics.get(field) or 0) + amount
        for query in query_candidates:
            list_response = await client.get(
                GMAIL_MESSAGES_LIST_URL,
                headers=headers,
                params={
                    "q": query,
                    "maxResults": SUBMITTED_EMPLOYEE_FORMS_MAX_HISTORIC_FETCH,
                    "includeSpamTrash": "true",
                },
            )
            if list_response.is_error:
                detail = list_response.text[:300]
                diagnostics["listErrors"] = int(diagnostics.get("listErrors") or 0) + 1
                diagnostics["lastListErrorStatus"] = int(list_response.status_code or 0)
                diagnostics["lastListErrorDetail"] = detail
                if list_response.status_code in (401, 403):
                    lower_detail = detail.lower()
                    hint = "Reconnect Gmail with read scope."
                    if "insufficient permissions" in lower_detail or "insufficientpermission" in lower_detail:
                        hint = "Reconnect Gmail and accept all requested permissions."
                    elif "access not configured" in lower_detail or "has not been used in project" in lower_detail:
                        hint = "Enable the Gmail API in your Google Cloud project, then reconnect Gmail."
                    response_meta.update(
                        {
                            "status": "reauth_required",
                            "message": f"Gmail denied message read access ({list_response.status_code}). {hint}",
                            "needsReconnect": True,
                            "diagnostics": diagnostics,
                        }
                    )
                    return [], response_meta
                if first_error is None:
                    first_error = HTTPException(
                        status_code=status.HTTP_502_BAD_GATEWAY,
                        detail=f"Gmail message search failed ({list_response.status_code}): {detail or 'Unknown error'}",
                    )
                continue
            list_payload = list_response.json() if list_response.content else {}
            message_rows = list_payload.get("messages") if isinstance(list_payload, dict) else []
            if not isinstance(message_rows, list):
                message_rows = []
            for row in message_rows:
                if not isinstance(row, dict):
                    continue
                message_id = str(row.get("id") or "").strip()
                if not message_id or message_id in seen_ids:
                    continue
                seen_ids.add(message_id)
                message_ids.append(message_id)
            if len(message_ids) >= SUBMITTED_EMPLOYEE_FORMS_MAX_HISTORIC_FETCH:
                break
        if not message_ids:
            # Fallback: scan recent mailbox rows and filter subjects locally.
            message_ids.extend(
                await _collect_message_ids(
                    {
                        "q": f"in:anywhere newer_than:{max(1, safe_lookback_days // 7 + 1)}m",
                        "maxResults": 250,
                        "includeSpamTrash": "true",
                    },
                    limit=400,
                    max_pages=4,
                )
            )
        if not message_ids:
            # Final fallback: no query at all, inspect recent mailbox traffic directly.
            message_ids.extend(
                await _collect_message_ids(
                    {
                        "maxResults": 250,
                        "includeSpamTrash": "true",
                    },
                    limit=500,
                    max_pages=5,
                )
            )
        if not message_ids and first_error is not None:
            raise first_error
        diagnostics["messageIdsCollected"] = len(message_ids)

        semaphore = asyncio.Semaphore(8)
        extraction_semaphore = asyncio.Semaphore(3)
        attachment_semaphore = asyncio.Semaphore(4)

        async def _build_attachment_inputs(message_id: str, payload: dict) -> tuple[list[dict], dict, list[dict]]:
            candidates = _gmail_collect_attachment_candidates(payload)
            if not candidates:
                return [], {}, []
            attachment_records: list[dict] = []
            csv_candidate_data: dict = {}
            inputs: list[dict] = []
            for candidate in candidates:
                mime_type = str(candidate.get("mimeType") or "").strip().lower()
                file_bytes = b""
                inline_data = str(candidate.get("inlineData") or "").strip()
                if inline_data:
                    file_bytes = _gmail_decode_body_bytes(inline_data)
                attachment_id = str(candidate.get("attachmentId") or "").strip()
                if not file_bytes and attachment_id:
                    async with attachment_semaphore:
                        attachment_response = await client.get(
                            GMAIL_MESSAGE_ATTACHMENT_URL.format(
                                message_id=quote(message_id, safe=""),
                                attachment_id=quote(attachment_id, safe=""),
                            ),
                            headers=headers,
                        )
                    if attachment_response.is_error:
                        continue
                    attachment_payload = attachment_response.json() if attachment_response.content else {}
                    attachment_data = str(attachment_payload.get("data") or "").strip() if isinstance(attachment_payload, dict) else ""
                    file_bytes = _gmail_decode_body_bytes(attachment_data)
                if not file_bytes or len(file_bytes) > 8 * 1024 * 1024:
                    continue
                filename = str(candidate.get("filename") or "attachment").strip()[:120] or "attachment"
                attachment_sha = _hash_sha256_bytes(file_bytes)
                attachment_record = {
                    "filename": filename,
                    "mimeType": mime_type or "application/octet-stream",
                    "attachmentId": attachment_id,
                    "fileSize": len(file_bytes),
                    "sha256": attachment_sha,
                    "attachmentType": "OTHER",
                }
                lower_name = filename.lower()
                if lower_name.endswith(".csv") or mime_type in {"text/csv", "application/csv", "application/vnd.ms-excel"}:
                    attachment_record["attachmentType"] = "FORM_CSV"
                    should_use = not csv_candidate_data
                    if lower_name == "entry-details.csv":
                        should_use = True
                    if should_use:
                        extracted_map, unmapped_map, raw_rows = _submitted_employee_forms_parse_csv_bytes(file_bytes)
                        csv_candidate_data = {
                            "filename": filename,
                            "sha256": attachment_sha,
                            "fields": extracted_map,
                            "unmappedFields": unmapped_map,
                            "rawRows": raw_rows,
                        }
                elif mime_type.startswith("image/"):
                    attachment_record["attachmentType"] = "IDENTITY_DOCUMENT"
                elif "pdf" in mime_type:
                    attachment_record["attachmentType"] = "OTHER"

                attachment_records.append(attachment_record)

                if mime_type.startswith("image/") or mime_type == "application/pdf":
                    encoded = base64.b64encode(file_bytes).decode("ascii")
                    if mime_type.startswith("image/"):
                        inputs.append({"type": "input_image", "image_url": f"data:{mime_type};base64,{encoded}"})
                    else:
                        inputs.append(
                            {
                                "type": "input_file",
                                "filename": filename,
                                "file_data": f"data:{mime_type};base64,{encoded}",
                            }
                        )
                    if len(inputs) >= 3:
                        continue
            return inputs, csv_candidate_data, attachment_records

        async def _fetch_message(message_id: str) -> dict | None:
            async with semaphore:
                message_response = await client.get(
                    GMAIL_MESSAGE_DETAIL_URL.format(message_id=quote(message_id, safe="")),
                    headers=headers,
                    params={"format": "full"},
                )
            if message_response.is_error:
                return None
            payload = message_response.json() if message_response.content else {}
            if not isinstance(payload, dict):
                return None
            subject = _submitted_employee_forms_normalized_subject(_gmail_header_value(payload, "Subject"))
            _diag_increment("messagesInspected", 1)
            if subject and len(sample_subjects) < 20:
                sample_subjects.append(subject[:180])
            if not _submitted_employee_forms_subject_matches(subject):
                return None
            _diag_increment("subjectMatched", 1)
            from_header = _gmail_header_value(payload, "From")
            from_name, from_email = _parse_email_contact(from_header)
            body_text = _gmail_message_body_text(payload)
            snippet = str(payload.get("snippet") or "").strip()
            local_identity = _extract_employee_identity(subject, snippet, body_text)
            attachment_inputs, csv_candidate_data, attachment_records = await _build_attachment_inputs(message_id, payload)
            async with extraction_semaphore:
                ai_identity = await _submitted_employee_forms_extract_with_openai(
                    subject,
                    snippet,
                    body_text,
                    attachment_inputs=attachment_inputs,
                    user_id=str(user.get("id") or ""),
                )
            identity = _submitted_employee_forms_merged_identity(local_identity, ai_identity)
            csv_fields = csv_candidate_data.get("fields") if isinstance(csv_candidate_data.get("fields"), dict) else {}
            if csv_fields:
                merged = dict(identity)
                merged.update({key: value for key, value in csv_fields.items() if str(value or "").strip()})
                csv_full_name = str(csv_fields.get("employeeFullName") or "").strip()
                csv_first_name = str(csv_fields.get("employeeFirstName") or "").strip()
                csv_last_name = str(csv_fields.get("employeeLastName") or "").strip()
                if csv_full_name and (not csv_first_name or not csv_last_name):
                    parsed_first, parsed_last = _submitted_employee_forms_split_name(csv_full_name)
                    csv_first_name = csv_first_name or parsed_first
                    csv_last_name = csv_last_name or parsed_last
                if csv_first_name:
                    merged["employeeFirstName"] = csv_first_name
                if csv_last_name:
                    merged["employeeLastName"] = csv_last_name
                if csv_full_name:
                    merged["employeeFullName"] = csv_full_name
                identity = merged
            return {
                "gmailMessageId": str(payload.get("id") or message_id).strip(),
                "gmailThreadId": str(payload.get("threadId") or "").strip(),
                "gmailHistoryId": str(payload.get("historyId") or "").strip(),
                "subject": subject[:240],
                "subjectEmployeeName": _submitted_employee_forms_subject_suffix(subject)[:200],
                "receivedAt": _gmail_received_at(payload),
                "fromName": from_name[:160],
                "fromEmail": from_email[:160],
                "employeeFullName": str(identity.get("employeeFullName") or ""),
                "employeeFirstName": str(identity.get("employeeFirstName") or ""),
                "employeeLastName": str(identity.get("employeeLastName") or ""),
                "employeeEmail": str(identity.get("employeeEmail") or ""),
                "employerName": str(identity.get("employerName") or ""),
                "extractedFields": identity,
                "employeeData": csv_candidate_data.get("rawRows") if isinstance(csv_candidate_data.get("rawRows"), list) else [],
                "unmappedFields": csv_candidate_data.get("unmappedFields") if isinstance(csv_candidate_data.get("unmappedFields"), dict) else {},
                "csvSha256": str(csv_candidate_data.get("sha256") or ""),
                "attachmentRecords": attachment_records,
                "snippet": snippet[:3000],
                "rawPayload": payload,
            }

        fetched = await asyncio.gather(*[_fetch_message(message_id) for message_id in message_ids])
    minimum_received_at = datetime.combine(after_date, datetime.min.time(), tzinfo=timezone.utc)
    rows = [
        row
        for row in fetched
        if isinstance(row, dict)
        and row.get("gmailMessageId")
        and (
            not isinstance(row.get("receivedAt"), datetime)
            or row.get("receivedAt") >= minimum_received_at
        )
    ]
    diagnostics["withinWindow"] = len(rows)
    diagnostics["sampleSubjects"] = sample_subjects
    response_meta.update(
        {
            "status": "connected",
            "message": (
                f"Submitted employee forms fetched from Gmail for the last {safe_lookback_days} days. "
                f"Searched {len(message_ids)} recent message{'' if len(message_ids) == 1 else 's'}."
            ),
            "needsReconnect": False,
            "diagnostics": diagnostics,
        }
    )
    return rows, response_meta


def _upsert_submitted_employee_forms(user_id: str, rows: list[dict]) -> int:
    if not rows:
        return 0
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    for row in rows:
                        cursor.execute(
                            """
                            INSERT INTO submitted_employee_forms (
                                user_id,
                                gmail_message_id,
                                gmail_thread_id,
                                gmail_history_id,
                                subject,
                                subject_employee_name,
                                received_at,
                                from_name,
                                from_email,
                                employee_full_name,
                                employee_first_name,
                                employee_last_name,
                                employee_email,
                                employer_name,
                                extracted_fields,
                                employee_data,
                                unmapped_fields,
                                csv_sha256,
                                snippet,
                                raw_payload,
                                workflow_status,
                                section_status,
                                created_at,
                                updated_at
                            )
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb, %s::jsonb, %s, %s, %s::jsonb, %s, %s, %s)
                            ON CONFLICT (user_id, gmail_message_id)
                            DO UPDATE
                            SET gmail_thread_id = EXCLUDED.gmail_thread_id,
                                gmail_history_id = EXCLUDED.gmail_history_id,
                                subject = EXCLUDED.subject,
                                subject_employee_name = EXCLUDED.subject_employee_name,
                                received_at = EXCLUDED.received_at,
                                from_name = EXCLUDED.from_name,
                                from_email = EXCLUDED.from_email,
                                employee_full_name = EXCLUDED.employee_full_name,
                                employee_first_name = EXCLUDED.employee_first_name,
                                employee_last_name = EXCLUDED.employee_last_name,
                                employee_email = EXCLUDED.employee_email,
                                employer_name = EXCLUDED.employer_name,
                                extracted_fields = EXCLUDED.extracted_fields,
                                employee_data = EXCLUDED.employee_data,
                                unmapped_fields = EXCLUDED.unmapped_fields,
                                csv_sha256 = EXCLUDED.csv_sha256,
                                snippet = EXCLUDED.snippet,
                                raw_payload = EXCLUDED.raw_payload,
                                workflow_status = CASE
                                    WHEN submitted_employee_forms.workflow_status IN ('complete', 'archived') THEN submitted_employee_forms.workflow_status
                                    ELSE EXCLUDED.workflow_status
                                END,
                                section_status = CASE
                                    WHEN submitted_employee_forms.workflow_status IN ('complete', 'archived') THEN submitted_employee_forms.section_status
                                    ELSE EXCLUDED.section_status
                                END,
                                updated_at = EXCLUDED.updated_at
                            """,
                            (
                                user_id,
                                str(row.get("gmailMessageId") or ""),
                                str(row.get("gmailThreadId") or ""),
                                str(row.get("gmailHistoryId") or ""),
                                str(row.get("subject") or ""),
                                str(row.get("subjectEmployeeName") or ""),
                                row.get("receivedAt"),
                                str(row.get("fromName") or ""),
                                str(row.get("fromEmail") or ""),
                                str(row.get("employeeFullName") or ""),
                                str(row.get("employeeFirstName") or ""),
                                str(row.get("employeeLastName") or ""),
                                str(row.get("employeeEmail") or ""),
                                str(row.get("employerName") or ""),
                                json.dumps(row.get("extractedFields") if isinstance(row.get("extractedFields"), dict) else {}, default=_json_default),
                                json.dumps(row.get("employeeData") if isinstance(row.get("employeeData"), list) else [], default=_json_default),
                                json.dumps(row.get("unmappedFields") if isinstance(row.get("unmappedFields"), dict) else {}, default=_json_default),
                                str(row.get("csvSha256") or ""),
                                str(row.get("snippet") or ""),
                                json.dumps(row.get("rawPayload") if isinstance(row.get("rawPayload"), dict) else {}, default=_json_default),
                                "extracted",
                                json.dumps(
                                    {
                                        "personalDetails": "EXTRACTED",
                                        "employment": "NEW",
                                        "basePay": "NEW",
                                        "workingPattern": "NEW",
                                        "paymentMethod": "NEW",
                                        "tax": "NEW",
                                        "studentLoan": "NEW",
                                        "pension": "NEW",
                                        "finalVerification": "NEW",
                                    },
                                    default=_json_default,
                                ),
                                utcnow(),
                                utcnow(),
                            ),
                        )
                        saved_message_id = str(row.get("gmailMessageId") or "")
                        if saved_message_id:
                            cursor.execute(
                                "SELECT id FROM submitted_employee_forms WHERE user_id = %s AND gmail_message_id = %s",
                                (user_id, saved_message_id),
                            )
                            saved_row = cursor.fetchone() or {}
                            saved_submission_id = str(saved_row.get("id") or "").strip()
                            if saved_submission_id:
                                cursor.execute(
                                    "DELETE FROM employee_submission_attachments WHERE submission_id = %s",
                                    (saved_submission_id,),
                                )
                                attachment_records = row.get("attachmentRecords") if isinstance(row.get("attachmentRecords"), list) else []
                                for attachment in attachment_records:
                                    if not isinstance(attachment, dict):
                                        continue
                                    cursor.execute(
                                        """
                                        INSERT INTO employee_submission_attachments (
                                            submission_id,
                                            gmail_attachment_id,
                                            filename,
                                            mime_type,
                                            storage_key,
                                            sha256,
                                            file_size,
                                            attachment_type,
                                            created_at
                                        )
                                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                                        """,
                                        (
                                            saved_submission_id,
                                            str(attachment.get("attachmentId") or ""),
                                            str(attachment.get("filename") or "")[:255],
                                            str(attachment.get("mimeType") or "")[:160],
                                            "",
                                            str(attachment.get("sha256") or "")[:128],
                                            int(attachment.get("fileSize") or 0),
                                            str(attachment.get("attachmentType") or "OTHER")[:40],
                                            utcnow(),
                                        ),
                                    )
                connection.commit()
            return len(rows)
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


async def _xero_payroll_create_employee(connection_row: dict, payload: dict) -> dict:
    def _to_camel_payload(value):
        if isinstance(value, dict):
            transformed: dict = {}
            for key, item in value.items():
                key_text = str(key or "")
                if key_text:
                    camel_key = f"{key_text[:1].lower()}{key_text[1:]}"
                else:
                    camel_key = key_text
                transformed[camel_key] = _to_camel_payload(item)
            return transformed
        if isinstance(value, list):
            return [_to_camel_payload(item) for item in value]
        return value

    def _error_summary(response: httpx.Response) -> str:
        try:
            error_payload = response.json() if response.content else {}
        except ValueError:
            error_payload = {}

        messages: list[str] = []

        def add_message(raw_value) -> None:
            text = re.sub(r"\s+", " ", str(raw_value or "")).strip()
            if not text:
                return
            if text.lower() in {"badrequest", "a validation exception occurred"}:
                return
            if text not in messages:
                messages.append(text)

        def collect(value) -> None:
            if isinstance(value, dict):
                for key in ("message", "Message", "detail", "Detail", "title", "Title", "error", "Error", "error_description"):
                    add_message(value.get(key))
                invalid_fields = value.get("invalidFields") or value.get("InvalidFields")
                if isinstance(invalid_fields, list):
                    for field in invalid_fields:
                        if not isinstance(field, dict):
                            continue
                        field_name = re.sub(r"\s+", " ", str(field.get("name") or field.get("Name") or "")).strip()
                        reason = re.sub(r"\s+", " ", str(field.get("reason") or field.get("Reason") or "")).strip()
                        if field_name and reason:
                            add_message(f"{field_name}: {reason}")
                        elif reason:
                            add_message(reason)
                        elif field_name:
                            add_message(field_name)
                validations = value.get("ValidationErrors")
                if isinstance(validations, list):
                    for item in validations:
                        collect(item)
                elements = value.get("Elements")
                if isinstance(elements, list):
                    for item in elements:
                        collect(item)
                for nested_key in ("problem", "Problem"):
                    nested = value.get(nested_key)
                    if isinstance(nested, (dict, list)):
                        collect(nested)
            elif isinstance(value, list):
                for item in value:
                    collect(item)

        collect(error_payload)
        if messages:
            return "; ".join(messages[:4])[:400]
        return re.sub(r"\s+", " ", response.text or "").strip()[:400] or "Unknown error"

    source_employee_row = {}
    if isinstance(payload, dict):
        candidate_rows = payload.get("Employees")
        if isinstance(candidate_rows, list) and candidate_rows and isinstance(candidate_rows[0], dict):
            source_employee_row = dict(candidate_rows[0])
        elif any(key in payload for key in ("FirstName", "firstName", "LastName", "lastName")):
            source_employee_row = dict(payload)

    payload_variants: list[dict] = []
    if isinstance(payload, dict) and payload:
        payload_variants.append(payload)
    if source_employee_row:
        payload_variants.append(source_employee_row)
        payload_variants.append(_to_camel_payload(source_employee_row))

    deduped_variants: list[dict] = []
    seen_variant_keys: set[str] = set()
    for variant in payload_variants:
        try:
            variant_key = json.dumps(variant, sort_keys=True, default=_json_default)
        except Exception:
            variant_key = str(variant)
        if variant_key in seen_variant_keys:
            continue
        seen_variant_keys.add(variant_key)
        deduped_variants.append(variant)
    payload_variants = deduped_variants or [payload if isinstance(payload, dict) else {}]

    refreshed_connection = await refresh_connection(str(connection_row.get("id") or ""))
    headers = {
        "Authorization": f"Bearer {refreshed_connection.get('access_token') or ''}",
        "xero-tenant-id": str(refreshed_connection.get("tenant_id") or ""),
        "Accept": "application/json",
        "Content-Type": "application/json",
    }

    response: httpx.Response | None = None
    summary = ""
    async with httpx.AsyncClient(timeout=60) as client:
        for index, variant_payload in enumerate(payload_variants):
            response = await client.post(XERO_PAYROLL_EMPLOYEES_URL, headers=headers, json=variant_payload)
            if not response.is_error:
                break
            if response.status_code in (401, 403):
                raise HTTPException(
                    status_code=status.HTTP_409_CONFLICT,
                    detail="Xero Payroll access denied. Reconnect Xero with payroll scopes before creating employees.",
                )
            summary = _error_summary(response)
            should_retry_variant = response.status_code in (400, 404, 405, 415, 422) and index < len(payload_variants) - 1
            if not should_retry_variant:
                break

    if response is None:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="Xero Payroll employee creation failed (no response received).",
        )
    if response.is_error:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail=f"Xero Payroll employee creation failed ({response.status_code}): {summary or 'Unknown error'}",
        )
    response_payload = response.json() if response.content else {}
    employees = _payroll_headcount_rows(response_payload if isinstance(response_payload, dict) else {}, "Employees", "Employee")
    if not employees and isinstance(response_payload, dict):
        if any(key in response_payload for key in ("EmployeeID", "employeeID", "employeeId")):
            employees = [response_payload]
    first_row = employees[0] if employees else {}
    employee_id, _, _ = _xero_payroll_employee_identity(first_row if isinstance(first_row, dict) else {})
    return {
        "employeeId": employee_id,
        "status": str((first_row or {}).get("Status") or "").strip(),
        "httpStatusCode": int(response.status_code),
        "responseSummary": str((response_payload or {}).get("providerName") or "").strip(),
    }


def _submitted_forms_target_connection(user: dict, tenant_id: str | None = None) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    if clean_tenant_id:
        return xero_connection_for_user_tenant(user, clean_tenant_id, include_fallback=False)
    return get_xero_connection_for_user(user["id"])


def _submitted_forms_employer_name(form_row: dict) -> str:
    employer_name = re.sub(r"\s+", " ", str(form_row.get("employer_name") or "")).strip()
    if employer_name:
        return employer_name
    extracted_fields = form_row.get("extracted_fields") if isinstance(form_row.get("extracted_fields"), dict) else {}
    employer_name = re.sub(r"\s+", " ", str(extracted_fields.get("employerName") or "")).strip()
    if employer_name:
        return employer_name
    raw_payload = form_row.get("raw_payload") if isinstance(form_row.get("raw_payload"), dict) else {}
    if raw_payload:
        body_text = _gmail_message_body_text(raw_payload)
        identity = _extract_employee_identity(
            str(form_row.get("subject") or ""),
            str(form_row.get("snippet") or ""),
            body_text,
        )
        employer_name = re.sub(r"\s+", " ", str(identity.get("employerName") or "")).strip()
        if employer_name:
            return employer_name
    return re.sub(r"\s+", " ", str(form_row.get("from_name") or "")).strip()


def _submitted_forms_workspace_catalog(user: dict) -> list[dict]:
    preferred_tenant_name = get_settings().xero_primary_tenant_name
    source_rows = list_xero_connections_for_user(str(user.get("id") or ""), include_fallback=False)
    connection_rows = []
    for row in source_rows:
        tenant_id = str(row.get("tenant_id") or "").strip()
        if not tenant_id:
            continue
        tenant_type = str(row.get("tenant_type") or "").strip().upper()
        if tenant_type not in ("", "ORGANISATION", "ORGANIZATION"):
            continue
        connection_rows.append(row)
    if not connection_rows:
        return []
    connection_rows = sorted(
        connection_rows,
        key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name),
        reverse=True,
    )
    tenant_ids = [str(row.get("tenant_id") or "").strip() for row in connection_rows if str(row.get("tenant_id") or "").strip()]
    customer_names_by_tenant: dict[str, set[str]] = {}
    try:
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT tenant_id, name
                    FROM customers
                    WHERE tenant_id = ANY(%s)
                    """,
                    (tenant_ids,),
                )
                rows = cursor.fetchall() or []
            connection.commit()
        for row in rows:
            tenant_id = str(row.get("tenant_id") or "").strip()
            if not tenant_id:
                continue
            name_key = _bm_tasks_normalise_name_key(str(row.get("name") or ""))
            if not name_key:
                continue
            customer_names_by_tenant.setdefault(tenant_id, set()).add(name_key)
    except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
        ensure_schema()
    catalog: list[dict] = []
    for row in connection_rows:
        tenant_id = str(row.get("tenant_id") or "").strip()
        tenant_name = str(row.get("tenant_name") or tenant_id).strip()
        tenant_key = _bm_tasks_normalise_name_key(tenant_name)
        name_keys = set(customer_names_by_tenant.get(tenant_id) or set())
        if tenant_key:
            name_keys.add(tenant_key)
        catalog.append(
            {
                "connection": row,
                "tenantId": tenant_id,
                "tenantName": tenant_name,
                "tenantKey": tenant_key,
                "nameKeys": name_keys,
            }
        )
    return catalog


def _submitted_forms_match_workspace_by_employer(employer_name: str, workspace_catalog: list[dict]) -> dict | None:
    employer_key = _bm_tasks_normalise_name_key(employer_name)
    if not employer_key:
        return None
    for workspace in workspace_catalog:
        if employer_key in (workspace.get("nameKeys") or set()):
            return workspace
    if len(employer_key) < 4:
        return None
    for workspace in workspace_catalog:
        tenant_key = str(workspace.get("tenantKey") or "")
        if tenant_key and (employer_key in tenant_key or tenant_key in employer_key):
            return workspace
        for name_key in workspace.get("nameKeys") or set():
            if employer_key in name_key or name_key in employer_key:
                return workspace
    return None


async def _submitted_forms_match_workspace_with_openai(
    form_row: dict,
    employer_name: str,
    workspace_catalog: list[dict],
    *,
    user_id: str | None = None,
) -> tuple[dict | None, str, int]:
    if not workspace_catalog:
        return None, "", 0
    if len(workspace_catalog) == 1:
        return workspace_catalog[0], "Single connected workspace.", 100
    if not str(get_settings().openai_api_key or "").strip():
        return None, "", 0
    subject = str(form_row.get("subject") or "").strip()
    sender_name = str(form_row.get("from_name") or "").strip()
    sender_email = str(form_row.get("from_email") or "").strip().lower()
    employee_name = " ".join(
        part
        for part in [
            str(form_row.get("employee_first_name") or "").strip(),
            str(form_row.get("employee_last_name") or "").strip(),
        ]
        if part
    ).strip() or str(form_row.get("employee_full_name") or "").strip()
    employee_email = str(form_row.get("employee_email") or "").strip().lower()
    snippet = str(form_row.get("snippet") or "").strip()
    candidates = []
    for workspace in workspace_catalog:
        candidate_keys = sorted(list(workspace.get("nameKeys") or set()))
        candidates.append(
            {
                "tenantId": str(workspace.get("tenantId") or "").strip(),
                "tenantName": str(workspace.get("tenantName") or "").strip(),
                "nameHints": candidate_keys[:20],
            }
        )
    request_body = {
        "input": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "input_text",
                        "text": (
                            "Choose the best Xero client workspace for this employee form. "
                            "Use employer clues first, then sender and subject context. "
                            "Return tenantId only from candidates; empty tenantId if uncertain.\n\n"
                            f"Employer: {employer_name}\n"
                            f"Employee: {employee_name}\n"
                            f"Employee email: {employee_email}\n"
                            f"Sender name: {sender_name}\n"
                            f"Sender email: {sender_email}\n"
                            f"Subject: {subject}\n"
                            f"Snippet: {snippet[:1000]}\n\n"
                            f"Candidates JSON:\n{json.dumps(candidates, default=_json_default)}"
                        ),
                    }
                ],
            }
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "submitted_employee_form_workspace_match",
                "schema": SUBMITTED_EMPLOYEE_FORMS_AI_MATCH_SCHEMA,
                "strict": True,
            }
        },
        "max_output_tokens": 600,
    }
    try:
        payload = await _post_openai_responses(
            request_body,
            "submitted employee form workspace matching",
            timeout_seconds=20,
            user_id=user_id,
            feature="submitted-employee-forms",
            page="submitted-employee-forms",
        )
        parsed = _load_openai_json_response(payload, "OpenAI returned invalid JSON for submitted employee form workspace matching.")
        if not isinstance(parsed, dict):
            return None, "", 0
        tenant_id = str(parsed.get("tenantId") or "").strip()
        confidence = int(parsed.get("confidence") or 0)
        reason = str(parsed.get("reason") or "").strip()
        if not tenant_id:
            return None, reason, confidence
        workspace = next((item for item in workspace_catalog if str(item.get("tenantId") or "").strip() == tenant_id), None)
        return workspace, reason, confidence
    except Exception:
        logger.exception("submitted_employee_forms_openai_workspace_match_failed")
        return None, "", 0


def _submitted_employee_forms_query_rows_by_ids(user_id: str, row_ids: list[str]) -> list[dict]:
    ids = [str(row_id or "").strip() for row_id in row_ids if str(row_id or "").strip()]
    if not ids:
        return []
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT *
                        FROM submitted_employee_forms
                        WHERE user_id = %s
                          AND id = ANY(%s)
                        ORDER BY COALESCE(received_at, created_at) DESC, created_at DESC
                        """,
                        (user_id, ids),
                    )
                    rows = cursor.fetchall() or []
                connection.commit()
            return _attach_submitted_employee_forms_attempt_history(user_id, rows)
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _submitted_forms_employee_create_payload(form_row: dict) -> dict:
    first_name = str(form_row.get("employee_first_name") or "").strip()
    last_name = str(form_row.get("employee_last_name") or "").strip()
    full_name = str(form_row.get("employee_full_name") or "").strip()
    if not first_name and full_name:
        parts = [part for part in re.split(r"\s+", full_name) if part]
        if parts:
            first_name = parts[0]
        if len(parts) >= 2:
            last_name = " ".join(parts[1:])
    if not first_name:
        first_name = "Unknown"
    if not last_name:
        last_name = "Employee"
    email_value = str(form_row.get("employee_email") or "").strip().lower()
    employee_row = {
        "FirstName": first_name[:100],
        "LastName": last_name[:100],
    }
    if email_value:
        employee_row["Email"] = email_value[:160]
    extracted_fields = form_row.get("extracted_fields") if isinstance(form_row.get("extracted_fields"), dict) else {}
    date_of_birth_candidates = (
        extracted_fields.get("DateOfBirth"),
        extracted_fields.get("dateOfBirth"),
        extracted_fields.get("date_of_birth"),
        extracted_fields.get("dob"),
        extracted_fields.get("DOB"),
        extracted_fields.get("birthDate"),
        form_row.get("date_of_birth"),
        form_row.get("dateOfBirth"),
    )
    date_of_birth = ""
    for candidate in date_of_birth_candidates:
        normalised = _submitted_employee_forms_normalise_date(str(candidate or ""))
        if normalised:
            date_of_birth = normalised
            break
    if date_of_birth:
        employee_row["DateOfBirth"] = date_of_birth

    title_value = _submitted_employee_forms_normalise_title(str(extracted_fields.get("title") or ""))
    if title_value:
        employee_row["Title"] = title_value[:35]

    gender_value = _submitted_employee_forms_normalise_gender(
        str(extracted_fields.get("gender") or ""),
        title=title_value,
    )
    if gender_value:
        employee_row["Gender"] = gender_value
    extracted_fields = form_row.get("extracted_fields") if isinstance(form_row.get("extracted_fields"), dict) else {}
    employee_number_raw = re.sub(r"\s+", "", str(extracted_fields.get("payrollNumber") or "")).strip()
    if employee_number_raw:
        employee_row["EmployeeNumber"] = employee_number_raw[:35]
    address_line_1 = str(extracted_fields.get("addressLine1") or "").strip()
    city = str(extracted_fields.get("city") or "").strip()
    post_code = str(extracted_fields.get("postcode") or "").strip()
    if address_line_1 and city and post_code:
        address_payload = {
            "AddressLine1": address_line_1[:35],
            "City": city[:50],
            "PostCode": post_code[:8],
        }
        address_line_2 = str(extracted_fields.get("addressLine2") or "").strip()
        if address_line_2:
            address_payload["AddressLine2"] = address_line_2[:50]
        country_name = _submitted_employee_forms_normalise_country_name(str(extracted_fields.get("country") or ""))
        if not country_name:
            country_name = "United Kingdom"
        if country_name:
            address_payload["Country"] = country_name[:50]
            address_payload["CountryName"] = country_name[:50]
        employee_row["Address"] = address_payload
    return {"Employees": [employee_row]}


def _submitted_forms_employee_created_timeline_note(
    *,
    employee_name: str,
    tenant_name: str,
    xero_employee_id: str,
) -> str:
    clean_employee_name = re.sub(r"\s+", " ", str(employee_name or "").strip())
    clean_tenant_name = re.sub(r"\s+", " ", str(tenant_name or "").strip())
    note_body = (
        f"Employee {clean_employee_name or 'Unknown employee'} was created in Xero Payroll via Jenius AI"
        + (f" for {clean_tenant_name}" if clean_tenant_name else "")
        + "."
    )
    if str(xero_employee_id or "").strip():
        note_body = f"{note_body} Xero Employee ID: {str(xero_employee_id).strip()}."
    return _with_jenius_signature(note_body)


def _submitted_forms_add_customer_timeline_note(
    *,
    user_id: str,
    tenant_id: str,
    tenant_name: str,
    employer_name: str,
    employee_name: str,
    xero_employee_id: str,
) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    target_keys = [
        _bm_tasks_normalise_name_key(value)
        for value in (employer_name, tenant_name)
        if _bm_tasks_normalise_name_key(value)
    ]
    if not clean_tenant_id or not target_keys:
        return {"added": False, "customerId": "", "customerName": "", "reason": "insufficient-target-data"}

    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT id, name
                        FROM customers
                        WHERE tenant_id = %s
                        """,
                        (clean_tenant_id,),
                    )
                    rows = cursor.fetchall() or []
                    best_row = None
                    best_score = 0.0
                    for row in rows:
                        candidate_name = str(row.get("name") or "").strip()
                        candidate_key = _bm_tasks_normalise_name_key(candidate_name)
                        if not candidate_key:
                            continue
                        score = 0.0
                        for target_key in target_keys:
                            if candidate_key == target_key:
                                score = max(score, 1.0)
                            elif candidate_key in target_key or target_key in candidate_key:
                                score = max(score, 0.94)
                            else:
                                score = max(score, difflib.SequenceMatcher(None, candidate_key, target_key).ratio())
                        if score > best_score:
                            best_score = score
                            best_row = row if isinstance(row, dict) else None
                    if best_row is None or best_score < 0.74:
                        connection.commit()
                        return {"added": False, "customerId": "", "customerName": "", "reason": "customer-not-found"}
                    customer_id = str(best_row.get("id") or "").strip()
                    customer_name = str(best_row.get("name") or "").strip()
                    note_body = _submitted_forms_employee_created_timeline_note(
                        employee_name=employee_name,
                        tenant_name=tenant_name or customer_name,
                        xero_employee_id=xero_employee_id,
                    )
                    clean_user_id = str(user_id or "").strip() or None
                    cursor.execute(
                        "INSERT INTO customer_notes (customer_id, user_id, body) VALUES (%s, %s, %s)",
                        (customer_id, clean_user_id, note_body),
                    )
                connection.commit()
            record_audit_event(
                "customer",
                customer_id,
                "client.note.added",
                {
                    "body": note_body,
                    "source": "submitted-employee-forms",
                    "xero_employee_id": str(xero_employee_id or "").strip(),
                },
                str(user_id or "").strip() or None,
            )
            return {"added": True, "customerId": customer_id, "customerName": customer_name, "reason": ""}
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _submitted_forms_employee_number_as_int(value: str) -> int | None:
    clean_value = re.sub(r"\s+", "", str(value or "")).strip()
    if not clean_value or not clean_value.isdigit():
        return None
    try:
        parsed = int(clean_value)
    except ValueError:
        return None
    if parsed < 1:
        return None
    return parsed


def _submitted_forms_next_employee_number(existing_employees: list[dict]) -> int:
    highest = 0
    for employee in existing_employees:
        if not isinstance(employee, dict):
            continue
        candidate = _submitted_forms_employee_number_as_int(
            str(employee.get("EmployeeNumber") or employee.get("employeeNumber") or "")
        )
        if candidate and candidate > highest:
            highest = candidate
    return max(1, highest + 1)


def _submitted_forms_missing_xero_required_fields(form_row: dict) -> list[str]:
    extracted_fields = form_row.get("extracted_fields") if isinstance(form_row.get("extracted_fields"), dict) else {}
    missing: list[str] = []
    required_map = [
        ("employee_first_name", "First name"),
        ("employee_last_name", "Last name"),
        ("title", "Title"),
        ("gender", "Gender"),
        ("dateOfBirth", "Date of birth"),
        ("addressLine1", "Address line 1"),
        ("city", "City"),
        ("postcode", "Postcode"),
        ("country", "Country"),
        ("payrollNumber", "Payroll number"),
        ("taxCode", "Tax code"),
    ]
    for key, label in required_map:
        if key in ("employee_first_name", "employee_last_name"):
            value = str(form_row.get(key) or "").strip()
        else:
            value = str(extracted_fields.get(key) or "").strip()
        if not value:
            missing.append(label)
    date_of_birth_value = str(extracted_fields.get("dateOfBirth") or "").strip()
    if date_of_birth_value and not _submitted_employee_forms_normalise_date(date_of_birth_value):
        missing.append("Date of birth")
    normalised_title = _submitted_employee_forms_normalise_title(str(extracted_fields.get("title") or ""))
    if not normalised_title and "Title" not in missing:
        missing.append("Title")
    gender_value = str(extracted_fields.get("gender") or "").strip()
    normalised_gender = _submitted_employee_forms_normalise_gender(gender_value, title=normalised_title)
    if not normalised_gender and "Gender" not in missing:
        missing.append("Gender")
    normalised_country = _submitted_employee_forms_normalise_country_name(str(extracted_fields.get("country") or ""))
    if not normalised_country and "Country" not in missing:
        missing.append("Country")
    return missing


def _submitted_forms_debug_note(base_note: str, lines: list[str]) -> str:
    clean_base = str(base_note or "").strip()
    clean_lines = [re.sub(r"\s+", " ", str(line or "")).strip() for line in (lines or []) if str(line or "").strip()]
    if not clean_lines:
        return clean_base
    debug_block = "Debug: " + " | ".join(clean_lines)
    merged = f"{clean_base}\n{debug_block}" if clean_base else debug_block
    return merged[:3900]


def _submitted_employee_forms_apply_field_overrides(form_row: dict, field_overrides: dict | None) -> dict:
    if not isinstance(field_overrides, dict) or not field_overrides:
        return dict(form_row)
    row = dict(form_row)
    existing_extracted = row.get("extracted_fields") if isinstance(row.get("extracted_fields"), dict) else {}
    override_extracted = field_overrides.get("extractedFields") if isinstance(field_overrides.get("extractedFields"), dict) else {}
    merged_extracted = dict(existing_extracted)
    for key in SUBMITTED_EMPLOYEE_FORMS_AI_EXTRACTION_SCHEMA.get("required", []):
        if key == "missingOrUnclear":
            source = override_extracted.get(key, field_overrides.get(key))
            if isinstance(source, list):
                merged_extracted[key] = [str(item or "").strip() for item in source if str(item or "").strip()][:24]
            elif isinstance(source, str) and source.strip():
                merged_extracted[key] = [item.strip() for item in source.split(",") if item.strip()][:24]
            continue
        source = override_extracted.get(key, field_overrides.get(key))
        if source is None:
            continue
        merged_extracted[key] = re.sub(r"\s+", " ", str(source or "")).strip()
    for field_name in ("dateOfBirth", "startDate"):
        normalised = _submitted_employee_forms_normalise_date(str(merged_extracted.get(field_name) or ""))
        if normalised:
            merged_extracted[field_name] = normalised
    merged_extracted["title"] = _submitted_employee_forms_normalise_title(str(merged_extracted.get("title") or ""))
    merged_extracted["gender"] = _submitted_employee_forms_normalise_gender(
        str(merged_extracted.get("gender") or ""),
        title=str(merged_extracted.get("title") or ""),
    )
    merged_extracted["country"] = _submitted_employee_forms_normalise_country_name(
        str(merged_extracted.get("country") or "")
    )

    first_name = re.sub(r"\s+", " ", str(field_overrides.get("employeeFirstName") or merged_extracted.get("employeeFirstName") or row.get("employee_first_name") or "")).strip()
    last_name = re.sub(r"\s+", " ", str(field_overrides.get("employeeLastName") or merged_extracted.get("employeeLastName") or row.get("employee_last_name") or "")).strip()
    full_name = re.sub(r"\s+", " ", str(field_overrides.get("employeeFullName") or merged_extracted.get("employeeFullName") or "")).strip()
    original_full_name = re.sub(r"\s+", " ", str(row.get("employee_full_name") or "")).strip()
    if not full_name:
        full_name = " ".join(part for part in [first_name, last_name] if part).strip()
    if not full_name and original_full_name:
        full_name = original_full_name
    if full_name and (not first_name or not last_name):
        parts = [part for part in re.split(r"\s+", full_name) if part]
        if parts and not first_name:
            first_name = parts[0]
        if len(parts) >= 2 and not last_name:
            last_name = " ".join(parts[1:])
    email_value = str(
        field_overrides.get("employeeEmail")
        or merged_extracted.get("employeeEmail")
        or row.get("employee_email")
        or ""
    ).strip().lower()
    employer_name = re.sub(
        r"\s+",
        " ",
        str(field_overrides.get("employerName") or merged_extracted.get("employerName") or row.get("employer_name") or ""),
    ).strip()

    row["employee_first_name"] = first_name
    row["employee_last_name"] = last_name
    row["employee_full_name"] = full_name
    row["employee_email"] = email_value
    row["employer_name"] = employer_name
    row["extracted_fields"] = merged_extracted
    return row


