async def sync_submitted_employee_forms(
    user: dict,
    tenant_id: str | None = None,
    create_missing: bool = True,
    mode: str = "process",
    selected_form_ids: list[str] | None = None,
    field_overrides_by_row: dict | None = None,
    lookback_days: int = 28,
) -> dict:
    user_id = str(user.get("id") or "")
    clean_mode = str(mode or "process").strip().lower()
    if clean_mode not in {"fetch", "process"}:
        clean_mode = "process"

    if clean_mode == "fetch":
        gmail_rows, gmail_meta = await _gmail_fetch_submitted_employee_messages(user, lookback_days=lookback_days)
        imported_count = _upsert_submitted_employee_forms(user_id, gmail_rows)
        payload = submitted_employee_forms_payload(user)
        payload["sync"] = {
            "mode": "fetch",
            "imported": imported_count,
            "processed": 0,
            "created": 0,
            "existing": 0,
            "failed": 0,
            "needsReview": 0,
            "tenantId": "",
            "tenantName": "",
            "gmail": gmail_meta,
            "lookbackDays": max(1, min(int(lookback_days or 28), 180)),
        }
        return payload

    selected_ids = [str(row_id or "").strip() for row_id in (selected_form_ids or []) if str(row_id or "").strip()]
    if not selected_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one submitted employee form for Step 2.")

    rows = _submitted_employee_forms_query_rows_by_ids(user_id, selected_ids)
    if not rows:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="No selected submitted employee forms were found.")

    manual_connection = _submitted_forms_target_connection(user, tenant_id) if str(tenant_id or "").strip() else None
    workspace_catalog = _submitted_forms_workspace_catalog(user) if manual_connection is None else []
    if manual_connection is None and not workspace_catalog:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No connected Xero organisation workspaces are available for Step 2.",
        )

    processed = 0
    created = 0
    existing = 0
    failed = 0
    needs_review = 0
    last_tenant_id = ""
    last_tenant_name = ""
    employee_index_by_tenant: dict[str, dict] = {}

    row_overrides = field_overrides_by_row if isinstance(field_overrides_by_row, dict) else {}

    for row in rows:
        row_id = str(row.get("id") or "").strip()
        if not row_id:
            continue
        row = _submitted_employee_forms_apply_field_overrides(row, row_overrides.get(row_id))
        _update_submitted_employee_form_override_fields(
            row_id,
            user_id,
            employee_full_name=str(row.get("employee_full_name") or ""),
            employee_first_name=str(row.get("employee_first_name") or ""),
            employee_last_name=str(row.get("employee_last_name") or ""),
            employee_email=str(row.get("employee_email") or ""),
            employer_name=str(row.get("employer_name") or ""),
            extracted_fields=row.get("extracted_fields") if isinstance(row.get("extracted_fields"), dict) else {},
        )
        processed += 1
        employee_email = str(row.get("employee_email") or "").strip().lower()
        employee_name = " ".join(
            part for part in [
                str(row.get("employee_first_name") or "").strip(),
                str(row.get("employee_last_name") or "").strip(),
            ] if part
        ).strip().lower()
        if not employee_name:
            employee_name = str(row.get("employee_full_name") or "").strip().lower()
        row_debug_base = [
            f"rowId={row_id}",
            f"employeeEmail={employee_email or '-'}",
            f"employeeName={employee_name or '-'}",
        ]

        def update_row_state(
            *,
            tenant_id: str = "",
            tenant_name: str = "",
            xero_employee_id: str = "",
            xero_status: str = "pending",
            xero_note: str = "",
            debug_lines: list[str] | None = None,
        ) -> None:
            final_note = _submitted_forms_debug_note(xero_note, debug_lines or [])
            _update_submitted_employee_form_xero_status(
                row_id,
                tenant_id=tenant_id,
                tenant_name=tenant_name,
                xero_employee_id=xero_employee_id,
                xero_status=xero_status,
                xero_note=final_note,
            )
            _record_submitted_employee_form_attempt(
                row_id=row_id,
                user_id=user_id,
                attempt_type="process",
                xero_status=xero_status,
                tenant_id=tenant_id,
                tenant_name=tenant_name,
                xero_employee_id=xero_employee_id,
                note=final_note,
            )

        employer_name = _submitted_forms_employer_name(row)
        target_workspace = None
        ai_match_reason = ""
        ai_match_confidence = 0
        if manual_connection is not None:
            target_workspace = {
                "connection": manual_connection,
                "tenantId": str(manual_connection.get("tenant_id") or "").strip(),
                "tenantName": str(manual_connection.get("tenant_name") or manual_connection.get("tenant_id") or "").strip(),
            }
        else:
            target_workspace = _submitted_forms_match_workspace_by_employer(employer_name, workspace_catalog)
            ai_workspace, ai_reason, ai_confidence = await _submitted_forms_match_workspace_with_openai(
                row,
                employer_name,
                workspace_catalog,
                user_id=user_id,
            )
            if ai_workspace:
                target_workspace = ai_workspace
                ai_match_reason = ai_reason
                ai_match_confidence = ai_confidence
        if not target_workspace:
            needs_review += 1
            update_row_state(
                tenant_id="",
                tenant_name="",
                xero_status="needs-review",
                xero_note=(
                    f"No Xero-connected client workspace matched employer '{employer_name}'."
                    if employer_name
                    else "Employer name missing on submitted form; unable to match a client workspace."
                ),
                debug_lines=row_debug_base + [f"employerName={employer_name or '-'}", "workspaceMatch=none"],
            )
            continue
        connection_row = target_workspace.get("connection") or {}
        clean_tenant_id = str(target_workspace.get("tenantId") or connection_row.get("tenant_id") or "").strip()
        clean_tenant_name = str(target_workspace.get("tenantName") or connection_row.get("tenant_name") or clean_tenant_id).strip()
        if not clean_tenant_id:
            needs_review += 1
            update_row_state(
                tenant_id="",
                tenant_name="",
                xero_status="needs-review",
                xero_note=f"Matched employer '{employer_name or 'unknown'}' but workspace tenant ID is unavailable.",
                debug_lines=row_debug_base + [f"employerName={employer_name or '-'}", "workspaceMatch=missing-tenant-id"],
            )
            continue
        last_tenant_id = clean_tenant_id
        last_tenant_name = clean_tenant_name
        if clean_tenant_id not in employee_index_by_tenant:
            try:
                employees_payload = await xero_api_get(connection_row, XERO_PAYROLL_EMPLOYEES_URL)
            except Exception as exc:
                failed += 1
                error_message = _sync_error_message(exc)
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_status="failed",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        f"but could not load existing Xero Payroll employees: {error_message}"
                        f"{f' AI match confidence {ai_match_confidence}%: {ai_match_reason}.' if ai_match_reason else ''}"
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"tenantName={clean_tenant_name}",
                        f"workspaceMatchConfidence={ai_match_confidence}",
                        f"workspaceMatchReason={ai_match_reason or '-'}",
                        "stage=load-existing-employees",
                    ],
                )
                continue
            existing_employees = _payroll_headcount_rows(employees_payload, "Employees", "Employee")
            existing_by_email: dict[str, str] = {}
            inactive_by_email: dict[str, str] = {}
            existing_name_candidates: dict[str, set[str]] = {}
            inactive_name_candidates: dict[str, set[str]] = {}
            for employee in existing_employees:
                employee_id, indexed_employee_email, _ = _xero_payroll_employee_identity(employee)
                indexed_employee_name = _submitted_forms_xero_employee_name_strict(employee if isinstance(employee, dict) else {})
                employee_is_active = _payroll_headcount_employee_is_active(employee)
                if indexed_employee_email:
                    if employee_is_active:
                        if indexed_employee_email not in existing_by_email:
                            existing_by_email[indexed_employee_email] = employee_id
                    elif indexed_employee_email not in inactive_by_email:
                        inactive_by_email[indexed_employee_email] = employee_id
                if indexed_employee_name and employee_id:
                    if employee_is_active:
                        existing_name_candidates.setdefault(indexed_employee_name, set()).add(employee_id)
                    else:
                        inactive_name_candidates.setdefault(indexed_employee_name, set()).add(employee_id)
            existing_by_name_unique: dict[str, str] = {}
            duplicate_names: set[str] = set()
            for name_key, ids in existing_name_candidates.items():
                if len(ids) == 1:
                    existing_by_name_unique[name_key] = next(iter(ids))
                elif len(ids) > 1:
                    duplicate_names.add(name_key)
            inactive_by_name_unique: dict[str, str] = {}
            inactive_duplicate_names: set[str] = set()
            for name_key, ids in inactive_name_candidates.items():
                if len(ids) == 1:
                    inactive_by_name_unique[name_key] = next(iter(ids))
                elif len(ids) > 1:
                    inactive_duplicate_names.add(name_key)
            employee_index_by_tenant[clean_tenant_id] = {
                "byEmail": existing_by_email,
                "inactiveByEmail": inactive_by_email,
                "byNameUnique": existing_by_name_unique,
                "duplicateNames": duplicate_names,
                "inactiveByNameUnique": inactive_by_name_unique,
                "inactiveDuplicateNames": inactive_duplicate_names,
                "nextEmployeeNumber": _submitted_forms_next_employee_number(existing_employees),
            }
        tenant_employee_index = employee_index_by_tenant.get(clean_tenant_id) or {}
        existing_by_email = tenant_employee_index.get("byEmail") or {}
        inactive_by_email = tenant_employee_index.get("inactiveByEmail") or {}
        existing_by_name_unique = tenant_employee_index.get("byNameUnique") or {}
        duplicate_names = tenant_employee_index.get("duplicateNames") or set()
        inactive_by_name_unique = tenant_employee_index.get("inactiveByNameUnique") or {}
        inactive_duplicate_names = tenant_employee_index.get("inactiveDuplicateNames") or set()
        existing_employee_id = ""
        existing_match_method = ""
        if employee_name:
            if employee_name in duplicate_names:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "but multiple Xero Payroll employees share the same name and no employee email was parsed. "
                        "Open Preview, confirm email, then retry Step 2."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        "duplicateNameMatch=true",
                        "existingMatch=email-missing-name-ambiguous",
                    ],
                )
                continue
            if employee_name in inactive_duplicate_names:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "but multiple inactive Xero Payroll employees share the same name and no employee email was parsed. "
                        "Open Preview, confirm email, then retry Step 2."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        "inactiveDuplicateNameMatch=true",
                        "existingMatch=email-missing-name-inactive-ambiguous",
                    ],
                )
                continue
            inactive_employee_id = inactive_by_name_unique.get(employee_name) or ""
            if inactive_employee_id:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_employee_id=inactive_employee_id,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "and found an inactive Xero Payroll employee with the same name. "
                        "Open Xero Payroll and reactivate or confirm that employee before retrying Step 2."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"inactiveEmployeeId={inactive_employee_id}",
                        "existingMatchMethod=name-inactive",
                    ],
                )
                continue
            existing_employee_id = existing_by_name_unique.get(employee_name) or ""
            if existing_employee_id:
                existing_match_method = "name"
        elif employee_email:
            inactive_employee_id = inactive_by_email.get(employee_email) or ""
            if inactive_employee_id:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_employee_id=inactive_employee_id,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "and found an inactive Xero Payroll employee with the same email. "
                        "Open Xero Payroll and reactivate or confirm that employee before retrying Step 2."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"inactiveEmployeeId={inactive_employee_id}",
                        "existingMatchMethod=email-inactive",
                    ],
                )
                continue
            email_only_existing_id = existing_by_email.get(employee_email) or ""
            if email_only_existing_id:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_employee_id=email_only_existing_id,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "and found an existing Xero Payroll employee by email only. "
                        "Confirm employee first and last name in Preview before retrying Step 2."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"existingEmployeeId={email_only_existing_id}",
                        "existingMatchMethod=email-only-needs-review",
                    ],
                )
                continue

        if existing_employee_id:
            verify_existing_ok = True
            verify_existing_error = ""
            verify_existing_row: dict = {}
            verified_existing_id = ""
            verified_existing_email = ""
            verified_existing_name = ""
            verified_existing_status = ""
            verified_existing_active = False
            try:
                verify_existing_url = f"{XERO_PAYROLL_EMPLOYEES_URL}/{quote(existing_employee_id, safe='')}"
                verify_existing_payload = await xero_api_get(connection_row, verify_existing_url)
                verify_existing_rows = _payroll_headcount_rows(verify_existing_payload, "Employees", "Employee")
                verify_existing_row = verify_existing_rows[0] if verify_existing_rows else {}
                verify_existing_dict = verify_existing_row if isinstance(verify_existing_row, dict) else {}
                verified_existing_id, verified_existing_email, _ = _xero_payroll_employee_identity(verify_existing_dict)
                verified_existing_name = _submitted_forms_xero_employee_name_strict(verify_existing_dict)
                expected_employee_id = _canonical_xero_employee_id(existing_employee_id)
                actual_employee_id = _canonical_xero_employee_id(verified_existing_id)
                if not actual_employee_id or actual_employee_id != expected_employee_id:
                    raise ValueError(
                        "EmployeeID did not match verification response "
                        f"(expected={existing_employee_id}, actual={verified_existing_id or '-'})"
                    )
                verified_existing_status = str(
                    (verify_existing_row or {}).get("EmployeeStatus")
                    or (verify_existing_row or {}).get("Status")
                    or (verify_existing_row or {}).get("status")
                    or ""
                ).strip()
                verified_existing_active = _payroll_headcount_employee_is_active(
                    verify_existing_row if isinstance(verify_existing_row, dict) else {}
                )
                if not verified_existing_active:
                    raise ValueError(
                        "Matched EmployeeID is not active in payroll "
                        f"(employee_id={verified_existing_id or existing_employee_id})."
                    )
                if employee_email:
                    if not verified_existing_email:
                        raise ValueError(
                            "Matched EmployeeID email was missing during verification "
                            f"(expected={employee_email})."
                        )
                    if verified_existing_email != employee_email:
                        raise ValueError(
                            "Matched EmployeeID email did not match expected email "
                            f"(expected={employee_email}, actual={verified_existing_email})."
                        )
                if employee_name:
                    expected_employee_name = _submitted_forms_normalized_employee_name(employee_name)
                    actual_employee_name = _submitted_forms_normalized_employee_name(verified_existing_name)
                    if not actual_employee_name:
                        raise ValueError(
                            "Matched EmployeeID name was missing during verification "
                            f"(expected={employee_name})."
                        )
                    if actual_employee_name != expected_employee_name:
                        raise ValueError(
                            "Matched EmployeeID name did not match expected employee name "
                            f"(expected={employee_name}, actual={verified_existing_name})."
                        )
            except Exception as verify_existing_exc:
                verify_existing_ok = False
                verify_existing_error = _sync_error_message(verify_existing_exc)
            if not verify_existing_ok:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_employee_id=existing_employee_id,
                    xero_status="needs-review",
                    xero_note=(
                        f"Matched an existing employee candidate in {clean_tenant_name}, but verification failed. "
                        "Open Xero employee list and confirm manually."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"existingEmployeeId={existing_employee_id}",
                        f"existingMatchMethod={existing_match_method or 'identity'}",
                        f"verifiedEmployeeId={verified_existing_id or '-'}",
                        f"verifiedEmployeeName={verified_existing_name or '-'}",
                        f"verifiedEmployeeEmail={verified_existing_email or '-'}",
                        f"verifiedEmployeeStatus={verified_existing_status or '-'}",
                        f"verifiedEmployeeActive={str(bool(verified_existing_active)).lower()}",
                        f"verifyExistingError={verify_existing_error or '-'}",
                    ],
                )
                continue
            existing += 1
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_employee_id=verified_existing_id or existing_employee_id,
                xero_status="exists",
                xero_note=(
                    f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}. "
                    f"Employee already exists in Xero Payroll (matched by {existing_match_method or 'identity'})."
                    f"{f' AI match confidence {ai_match_confidence}%: {ai_match_reason}.' if ai_match_reason else ''}"
                ),
                debug_lines=row_debug_base + [
                    f"tenantId={clean_tenant_id}",
                    f"existingEmployeeId={verified_existing_id or existing_employee_id or '-'}",
                    f"existingMatchMethod={existing_match_method or 'identity'}",
                    f"verifiedEmployeeName={verified_existing_name or '-'}",
                    f"verifiedEmployeeEmail={verified_existing_email or '-'}",
                    f"verifiedEmployeeStatus={verified_existing_status or '-'}",
                    f"verifiedEmployeeActive={str(bool(verified_existing_active)).lower()}",
                ],
            )
            continue

        if not create_missing:
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_status="pending",
                xero_note=(
                    f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}. "
                    "Employee not found in Xero Payroll."
                    f"{f' AI match confidence {ai_match_confidence}%: {ai_match_reason}.' if ai_match_reason else ''}"
                ),
                debug_lines=row_debug_base + [f"tenantId={clean_tenant_id}", "createMissing=false"],
            )
            continue

        if not employee_email and not employee_name:
            needs_review += 1
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_status="needs-review",
                xero_note="Employee details missing from submitted form email.",
                debug_lines=row_debug_base + [f"tenantId={clean_tenant_id}", "identity=missing"],
            )
            continue

        extracted_fields = row.get("extracted_fields") if isinstance(row.get("extracted_fields"), dict) else {}
        extracted_fields = dict(extracted_fields)
        tax_code = re.sub(r"\s+", "", str(extracted_fields.get("taxCode") or "")).strip().upper()
        if not tax_code:
            tax_code = SUBMITTED_EMPLOYEE_FORMS_DEFAULT_TAX_CODE
        extracted_fields["taxCode"] = tax_code
        payroll_number = re.sub(r"\s+", "", str(extracted_fields.get("payrollNumber") or "")).strip()
        parsed_existing_number = _submitted_forms_employee_number_as_int(payroll_number)
        if parsed_existing_number is None:
            next_number = max(1, int(tenant_employee_index.get("nextEmployeeNumber") or 1))
            parsed_existing_number = next_number
            payroll_number = f"{next_number:05d}"
        else:
            payroll_number = f"{parsed_existing_number:05d}"
        tenant_employee_index["nextEmployeeNumber"] = max(
            int(tenant_employee_index.get("nextEmployeeNumber") or 1),
            parsed_existing_number + 1,
        )
        extracted_fields["payrollNumber"] = payroll_number
        row["extracted_fields"] = extracted_fields
        _update_submitted_employee_form_override_fields(
            row_id,
            user_id,
            employee_full_name=str(row.get("employee_full_name") or ""),
            employee_first_name=str(row.get("employee_first_name") or ""),
            employee_last_name=str(row.get("employee_last_name") or ""),
            employee_email=str(row.get("employee_email") or ""),
            employer_name=str(row.get("employer_name") or ""),
            extracted_fields=extracted_fields,
        )

        missing_required_fields = _submitted_forms_missing_xero_required_fields(row)
        if missing_required_fields:
            needs_review += 1
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_status="needs-review",
                xero_note=(
                    f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                    f"but missing Xero mandatory fields: {', '.join(missing_required_fields)}."
                ),
                debug_lines=row_debug_base + [
                    f"tenantId={clean_tenant_id}",
                    f"payrollNumber={payroll_number or '-'}",
                    f"taxCode={tax_code or '-'}",
                    f"title={str(extracted_fields.get('title') or '-')}",
                    f"gender={str(extracted_fields.get('gender') or '-')}",
                    f"country={str(extracted_fields.get('country') or '-')}",
                    f"missingMandatory={','.join(missing_required_fields)}",
                ],
            )
            continue

        create_payload = _submitted_forms_employee_create_payload(row)
        try:
            create_result = await _xero_payroll_create_employee(connection_row, create_payload)
            created_employee_id = str(create_result.get("employeeId") or "").strip()
            created_status = str(create_result.get("status") or "").strip()
            response_http_status = int(create_result.get("httpStatusCode") or 0)
            if not created_employee_id:
                failed += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_status="failed",
                    xero_note=(
                        f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                        "but Xero did not return an EmployeeID for the create request."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"xeroHttpStatus={response_http_status or '-'}",
                        f"requestedEmployeeNumber={payroll_number}",
                        f"requestedTaxCode={tax_code}",
                        f"requestedTitle={str(extracted_fields.get('title') or '-')}",
                        f"requestedGender={str(extracted_fields.get('gender') or '-')}",
                        f"requestedAddressLine1={str(extracted_fields.get('addressLine1') or '-')}",
                        f"requestedCity={str(extracted_fields.get('city') or '-')}",
                        f"requestedPostcode={str(extracted_fields.get('postcode') or '-')}",
                    ],
                )
                continue
            verify_url = f"{XERO_PAYROLL_EMPLOYEES_URL}/{quote(created_employee_id, safe='')}"
            try:
                verify_payload = await xero_api_get(connection_row, verify_url)
                verified_rows = _payroll_headcount_rows(verify_payload, "Employees", "Employee")
                verified_row = verified_rows[0] if verified_rows else {}
                verified_employee_id, _, _ = _xero_payroll_employee_identity(verified_row if isinstance(verified_row, dict) else {})
                if str(verified_employee_id or "").strip() != created_employee_id:
                    raise ValueError("Verification call returned no matching EmployeeID.")
            except Exception as verify_exc:
                needs_review += 1
                update_row_state(
                    tenant_id=clean_tenant_id,
                    tenant_name=clean_tenant_name,
                    xero_employee_id=created_employee_id,
                    xero_status="needs-review",
                    xero_note=(
                        f"Xero returned EmployeeID {created_employee_id}, but verification did not confirm it in "
                        f"{clean_tenant_name}. Review in Xero and retry if needed."
                    ),
                    debug_lines=row_debug_base + [
                        f"tenantId={clean_tenant_id}",
                        f"createdEmployeeId={created_employee_id}",
                        f"xeroHttpStatus={response_http_status or '-'}",
                        f"verifyError={_sync_error_message(verify_exc)}",
                    ],
                )
                continue
            created += 1
            if employee_email and created_employee_id:
                existing_by_email[employee_email] = created_employee_id
            if employee_name and created_employee_id:
                current_name_match = existing_by_name_unique.get(employee_name)
                if employee_name not in duplicate_names:
                    if current_name_match and current_name_match != created_employee_id:
                        duplicate_names.add(employee_name)
                        existing_by_name_unique.pop(employee_name, None)
                    else:
                        existing_by_name_unique[employee_name] = created_employee_id
            timeline_note_result = _submitted_forms_add_customer_timeline_note(
                user_id=user_id,
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                employer_name=employer_name,
                employee_name=employee_name,
                xero_employee_id=created_employee_id,
            )
            timeline_note_summary = (
                f" Client timeline note added for {timeline_note_result.get('customerName') or 'matched client'}."
                if timeline_note_result.get("added")
                else ""
            )
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_employee_id=created_employee_id,
                xero_status="created",
                xero_note=(
                    f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}. "
                    f"Employee created in Xero Payroll{f' ({created_status})' if created_status else ''}."
                    f"{timeline_note_summary}"
                    f"{f' AI match confidence {ai_match_confidence}%: {ai_match_reason}.' if ai_match_reason else ''}"
                ),
                debug_lines=row_debug_base + [
                    f"tenantId={clean_tenant_id}",
                    f"createdEmployeeId={created_employee_id}",
                    f"xeroHttpStatus={response_http_status or '-'}",
                    f"requestedEmployeeNumber={payroll_number}",
                    f"requestedTaxCode={tax_code}",
                    f"timelineNoteAdded={str(bool(timeline_note_result.get('added'))).lower()}",
                    f"timelineCustomerId={str(timeline_note_result.get('customerId') or '-')}",
                    f"timelineCustomerName={str(timeline_note_result.get('customerName') or '-')}",
                    f"timelineNoteReason={str(timeline_note_result.get('reason') or '-')}",
                    "verifyCreate=confirmed",
                ],
            )
        except Exception as exc:
            failed += 1
            error_message = _sync_error_message(exc)
            update_row_state(
                tenant_id=clean_tenant_id,
                tenant_name=clean_tenant_name,
                xero_status="failed",
                xero_note=(
                    f"Matched employer '{employer_name or clean_tenant_name}' to {clean_tenant_name}, "
                    f"but employee creation failed: {error_message}."
                    f"{f' AI match confidence {ai_match_confidence}%: {ai_match_reason}.' if ai_match_reason else ''}"
                ),
                debug_lines=row_debug_base + [
                    f"tenantId={clean_tenant_id}",
                    f"requestedEmployeeNumber={payroll_number}",
                    f"requestedTaxCode={tax_code}",
                    f"requestedTitle={str(extracted_fields.get('title') or '-')}",
                    f"requestedGender={str(extracted_fields.get('gender') or '-')}",
                    f"requestedDateOfBirth={str(extracted_fields.get('dateOfBirth') or '-')}",
                    f"requestedAddressLine1={str(extracted_fields.get('addressLine1') or '-')}",
                    f"requestedCity={str(extracted_fields.get('city') or '-')}",
                    f"requestedPostcode={str(extracted_fields.get('postcode') or '-')}",
                    "stage=create-employee",
                ],
            )

    try:
        payload = submitted_employee_forms_payload(user)
    except Exception as exc:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail=f"Setup run finished processing but failed while refreshing results: {_sync_error_message(exc)}",
        ) from exc
    payload["sync"] = {
        "mode": "process",
        "imported": 0,
        "processed": processed,
        "created": created,
        "existing": existing,
        "failed": failed,
        "needsReview": needs_review,
        "tenantId": last_tenant_id,
        "tenantName": last_tenant_name,
        "gmail": {},
        "selectedCount": len(selected_ids),
    }
    return payload


async def xero_payroll_diagnostic_payload(user: dict, tenant_id: str) -> dict:
    clean_tenant_id = str(tenant_id or "").strip()
    if not clean_tenant_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Tenant id is required.")
    connection_row = xero_connection_for_user_tenant(user, clean_tenant_id, include_fallback=False)

    diagnostics = {
        "tenantId": clean_tenant_id,
        "accountingApiConnected": False,
        "payrollApiConnected": False,
        "payrollSetupComplete": False,
        "payrollAdminAuthorised": False,
        "partnerPermissionAvailable": False,
        "errors": [],
        "checks": {},
    }

    async def _check(url: str, key: str) -> dict:
        response_meta: dict = {}
        def _on_response(meta: dict):
            if isinstance(meta, dict):
                response_meta.update(meta)
        try:
            payload = await xero_api_get(connection_row, url, on_response=_on_response)
            diagnostics["checks"][key] = {
                "ok": True,
                "statusCode": int(response_meta.get("status_code") or 200),
                "elapsedMs": int(response_meta.get("elapsed_ms") or 0),
            }
            return payload if isinstance(payload, dict) else {}
        except Exception as exc:
            message = _sync_error_message(exc)
            diagnostics["checks"][key] = {
                "ok": False,
                "statusCode": int(response_meta.get("status_code") or 0),
                "elapsedMs": int(response_meta.get("elapsed_ms") or 0),
                "error": message,
            }
            diagnostics["errors"].append(f"{key}:{message}")
            return {}

    await _check(ORGANISATION_URL, "organisation")
    employees_payload = await _check(XERO_PAYROLL_EMPLOYEES_URL, "employees")
    calendars_payload = await _check(XERO_PAYROLL_CALENDARS_URL, "payRunCalendars")
    working_payload = await _check(XERO_PAYROLL_WORKING_PATTERNS_URL, "workingPatterns")
    settings_payload = await _check(XERO_PAYROLL_SETTINGS_URL, "settings")

    diagnostics["accountingApiConnected"] = bool((diagnostics["checks"].get("organisation") or {}).get("ok"))
    payroll_check_keys = ("employees", "payRunCalendars", "workingPatterns", "settings")
    diagnostics["payrollApiConnected"] = all(bool((diagnostics["checks"].get(key) or {}).get("ok")) for key in payroll_check_keys)

    calendars = _payroll_headcount_rows(calendars_payload, "PayRunCalendars", "PayRunCalendar")
    working_patterns = _payroll_headcount_rows(working_payload, "WorkingPatterns", "WorkingPattern")
    settings_rows = _payroll_headcount_rows(settings_payload, "Settings", "Setting")
    diagnostics["payrollSetupComplete"] = bool(calendars or working_patterns or settings_rows)

    has_auth_error = any(
        "permission" in str(error).lower() or "forbidden" in str(error).lower() or "scope" in str(error).lower()
        for error in diagnostics["errors"]
    )
    diagnostics["payrollAdminAuthorised"] = diagnostics["payrollApiConnected"] and not has_auth_error
    diagnostics["partnerPermissionAvailable"] = diagnostics["payrollApiConnected"] and not any(
        "partner" in str(error).lower() and "permission" in str(error).lower()
        for error in diagnostics["errors"]
    )

    return diagnostics


def _submitted_forms_submission_row(user: dict, form_id: str) -> dict:
    clean_form_id = str(form_id or "").strip()
    if not clean_form_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="A submission id is required.")
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT *
                        FROM submitted_employee_forms
                        WHERE id = %s AND user_id = %s
                        """,
                        (clean_form_id, str(user.get("id") or "")),
                    )
                    row = cursor.fetchone()
                connection.commit()
            if not row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Submitted employee form not found.")
            return row
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _submitted_forms_update_workflow_status(
    submission_id: str,
    *,
    workflow_status: str,
    section_status: dict,
    xero_status: str | None = None,
    xero_note: str | None = None,
    xero_employee_id: str | None = None,
) -> None:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE submitted_employee_forms
                        SET workflow_status = %s,
                            section_status = %s::jsonb,
                            xero_status = COALESCE(%s, xero_status),
                            xero_note = COALESCE(%s, xero_note),
                            xero_employee_id = COALESCE(%s, xero_employee_id),
                            updated_at = %s
                        WHERE id = %s
                        """,
                        (
                            str(workflow_status or "new"),
                            json.dumps(section_status if isinstance(section_status, dict) else {}, default=_json_default),
                            xero_status,
                            xero_note,
                            xero_employee_id,
                            utcnow(),
                            str(submission_id or "").strip(),
                        ),
                    )
                connection.commit()
            return
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _employee_publication_start_run(
    *,
    submission_id: str,
    user_id: str,
    tenant_id: str,
    initiated_by: str,
    idempotency_key: str,
) -> str:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        INSERT INTO employee_publication_runs (
                            submission_id, user_id, xero_tenant_id, status, started_at, initiated_by,
                            idempotency_key, current_step, created_at, updated_at
                        )
                        VALUES (%s, %s, %s, 'VALIDATING', %s, %s, %s, 'VALIDATING', %s, %s)
                        ON CONFLICT (idempotency_key)
                        DO UPDATE SET updated_at = EXCLUDED.updated_at
                        RETURNING id
                        """,
                        (
                            submission_id,
                            user_id,
                            tenant_id,
                            utcnow(),
                            initiated_by or None,
                            idempotency_key,
                            utcnow(),
                            utcnow(),
                        ),
                    )
                    row = cursor.fetchone() or {}
                connection.commit()
            run_id = str(row.get("id") or "").strip()
            if not run_id:
                raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Unable to create publication run.")
            return run_id
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


def _employee_publication_update_run(
    run_id: str,
    *,
    status_value: str,
    current_step: str,
    xero_employee_id: str = "",
    failure_step: str = "",
    error_code: str = "",
    error_message: str = "",
    completed: bool = False,
) -> None:
    schema_repaired = False
    while True:
        try:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE employee_publication_runs
                        SET status = %s,
                            current_step = %s,
                            xero_employee_id = %s,
                            failure_step = %s,
                            error_code = %s,
                            error_message = %s,
                            completed_at = CASE WHEN %s THEN %s ELSE completed_at END,
                            updated_at = %s
                        WHERE id = %s
                        """,
                        (
                            status_value,
                            current_step,
                            xero_employee_id,
                            failure_step,
                            error_code,
                            error_message,
                            bool(completed),
                            utcnow(),
                            utcnow(),
                            run_id,
                        ),
                    )
                connection.commit()
            return
        except (pg_errors.UndefinedTable, pg_errors.UndefinedColumn):
            if schema_repaired:
                raise
            ensure_schema()
            schema_repaired = True


