def _mark_stale_me_report_submissions(user_id: str) -> None:
    now = utcnow()
    stale_before = now - ME_REPORT_SUBMISSION_STALE_AFTER
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT submissions.id,
                       submissions.client_id,
                       submissions.filename,
                       submissions.created_at
                FROM me_report_submissions AS submissions
                JOIN me_report_clients AS clients
                  ON clients.id = submissions.client_id
                WHERE clients.user_id = %s
                  AND submissions.status IN ('queued', 'processing', 'running', 'pending')
                  AND submissions.completed_at IS NULL
                  AND submissions.created_at < %s
                """,
                (user_id, stale_before),
            )
            stale_rows = cursor.fetchall()
            if stale_rows:
                cursor.execute(
                    """
                    UPDATE me_report_submissions
                    SET status = 'failed',
                        error_message = %s,
                        completed_at = %s
                    WHERE id = ANY(%s)
                    """,
                    (
                        "Upload processing timed out in the background. Please upload the report again.",
                        now,
                        [row["id"] for row in stale_rows],
                    ),
                )
        connection.commit()
    for row in stale_rows or []:
        try:
            age_seconds = max(0, int((now - row["created_at"]).total_seconds())) if row.get("created_at") else None
            record_audit_event(
                "me_report_submission",
                str(row["id"]),
                "me_report.submission_timed_out",
                {
                    "client_id": str(row.get("client_id") or ""),
                    "filename": row.get("filename") or "",
                    "created_at": _iso(row.get("created_at")),
                    "age_seconds": age_seconds,
                    "stale_threshold_seconds": int(ME_REPORT_SUBMISSION_STALE_AFTER.total_seconds()),
                },
                user_id,
            )
        except Exception:
            logger.exception("Unable to record stale ME Report submission audit event")


def _me_report_is_vat_registration_exception(item: dict) -> bool:
    title = str(item.get("title") or "").lower()
    detail = str(item.get("detail") or "").lower()
    return "vat registration threshold" in title or "vat registration threshold" in detail


def _me_report_summary_for_client(summary: dict, client: dict) -> dict:
    prepared = _me_report_apply_transfer_classification_overrides(
        _me_report_apply_brought_forward_loss(
            _me_report_apply_director_loan_account_overrides(summary if isinstance(summary, dict) else {}, client),
            client,
        ),
        client,
    )
    if client.get("brought_forward_trading_loss_updated_at"):
        prepared["broughtForwardTradingLossUpdatedAt"] = _iso(client.get("brought_forward_trading_loss_updated_at")) or ""
    if bool(client.get("vat_registered_confirmed")):
        prepared = {
            **prepared,
            "vatRegisteredConfirmed": True,
            "vatRegisteredConfirmedAt": _iso(client.get("vat_registered_confirmed_at")) or "",
            "vatWarningVisible": False,
        }
    return prepared


def _serialize_me_report_client(row: dict, mappings: list[dict], reviews: list[dict], exceptions: list[dict], reports: list[dict], submissions: list[dict]) -> dict:
    latest_review = reviews[0] if reviews else None
    review_summary = latest_review.get("summary") if latest_review else {}
    if isinstance(review_summary, str):
        try:
            review_summary = json.loads(review_summary)
        except ValueError:
            review_summary = {}
    review_summary = _me_report_summary_for_client(review_summary, row)
    vat_registered_confirmed = bool(row.get("vat_registered_confirmed"))
    visible_exceptions = [
        item
        for item in exceptions
        if not (vat_registered_confirmed and _me_report_is_vat_registration_exception(item))
    ]
    open_exceptions = [item for item in visible_exceptions if (item.get("status") or "open") == "open"]
    calculated_traffic_light = "red" if any((item.get("severity") or "") == "red" for item in open_exceptions) else ("amber" if open_exceptions else "green")
    traffic_light = (latest_review or {}).get("traffic_light") or calculated_traffic_light
    if vat_registered_confirmed and traffic_light == "amber" and not open_exceptions:
        traffic_light = calculated_traffic_light
        if str(review_summary.get("trafficLight") or "").lower() == "amber":
            review_summary = {**review_summary, "trafficLight": calculated_traffic_light}
    dismissed_warning_keys = row.get("dismissed_warning_keys") or []
    if isinstance(dismissed_warning_keys, str):
        try:
            dismissed_warning_keys = json.loads(dismissed_warning_keys)
        except ValueError:
            dismissed_warning_keys = []
    if not isinstance(dismissed_warning_keys, list):
        dismissed_warning_keys = []
    tax_adjustment_overrides = _normalise_me_report_tax_adjustment_overrides(row.get("tax_adjustment_overrides"))
    transfer_classification_overrides = _normalise_me_report_transfer_classification_overrides(row.get("transfer_classification_overrides"))
    director_loan_account_overrides = _normalise_me_report_director_loan_account_overrides(row.get("director_loan_account_overrides"))
    return {
        "id": str(row["id"]),
        "clientName": row.get("client_name") or "",
        "internalClientOwner": row.get("internal_client_owner") or "",
        "bookkeepingFrequency": row.get("bookkeeping_frequency") or "Monthly",
        "reportRecipientEmail": row.get("report_recipient_email") or "",
        "yearEndMonth": int(row.get("year_end_month") or 3),
        "broughtForwardTradingLoss": float(_money(row.get("brought_forward_trading_loss"))),
        "broughtForwardTradingLossUpdatedAt": _iso(row.get("brought_forward_trading_loss_updated_at")) or "",
        "xeroContactId": row.get("xero_contact_id") or "",
        "xeroContactName": row.get("xero_contact_name") or "",
        "xeroContactEmail": row.get("xero_contact_email") or "",
        "xeroConnectionStatus": row.get("xero_connection_status") or "not_connected",
        "tenantId": str(row.get("xero_tenant_id") or ""),
        "tenantName": str(row.get("xero_tenant_name") or row.get("xero_tenant_id") or ""),
        "xeroTenantId": str(row.get("xero_tenant_id") or ""),
        "xeroTenantName": row.get("xero_tenant_name") or "",
        "vatRegisteredConfirmed": vat_registered_confirmed,
        "vatRegisteredConfirmedAt": _iso(row.get("vat_registered_confirmed_at")) or "",
        "dismissedWarningKeys": [str(item) for item in dismissed_warning_keys if str(item).strip()][:200],
        "taxAdjustmentOverrides": tax_adjustment_overrides,
        "transferClassificationOverrides": transfer_classification_overrides,
        "directorLoanAccountOverrides": director_loan_account_overrides,
        "status": row.get("status") or "active",
        "lastSyncAt": _iso(row.get("last_sync_at")) or "",
        "lastCalculatedAt": _iso(row.get("last_calculated_at")) or "",
        "lastReportAt": _iso(row.get("last_report_at")) or "",
        "createdAt": _iso(row.get("created_at")) or "",
        "trafficLight": traffic_light,
        "summary": review_summary or {},
        "mappings": [
            {
                "id": str(mapping["id"]),
                "xeroAccountId": mapping.get("xero_account_id") or "",
                "accountCode": mapping.get("account_code") or "",
                "accountName": mapping.get("account_name") or "",
                "accountType": mapping.get("account_type") or "",
                "suggestedTreatment": mapping.get("suggested_treatment") or "",
                "taxTreatment": mapping.get("tax_treatment") or "",
                "category": mapping.get("category") or "",
                "confidence": int(mapping.get("confidence") or 0),
                "reviewRequired": bool(mapping.get("review_required")),
                "status": mapping.get("status") or "suggested",
                "note": mapping.get("note") or "",
                "reason": mapping.get("reason") or "",
            }
            for mapping in mappings
        ],
        "reviews": [
            {
                "id": str(review["id"]),
                "periodStart": _iso(review.get("period_start")) or "",
                "periodEnd": _iso(review.get("period_end")) or "",
                "status": review.get("status") or "",
                "trafficLight": review.get("traffic_light") or "amber",
                "summary": _me_report_summary_for_client(review.get("summary") if isinstance(review.get("summary"), dict) else {}, row),
                "createdAt": _iso(review.get("created_at")) or "",
            }
            for review in reviews
        ],
        "exceptions": [
            {
                "id": str(item["id"]),
                "reviewId": str(item.get("review_id") or ""),
                "severity": item.get("severity") or "amber",
                "title": item.get("title") or "",
                "detail": item.get("detail") or "",
                "suggestedAction": item.get("suggested_action") or "",
                "actionPayload": item.get("action_payload") if isinstance(item.get("action_payload"), dict) else {},
                "status": item.get("status") or "open",
                "note": item.get("note") or "",
                "createdAt": _iso(item.get("created_at")) or "",
            }
            for item in visible_exceptions
        ],
        "reports": [
            {
                "id": str(report["id"]),
                "reviewId": str(report.get("review_id") or ""),
                "status": report.get("status") or "draft",
                "recipientEmail": report.get("recipient_email") or "",
                "emailSubject": report.get("email_subject") or "",
                "bccEmail": report.get("bcc_email") or "",
                "commentary": report.get("commentary") or "",
                "createdAt": _iso(report.get("created_at")) or "",
                "approvedAt": _iso(report.get("approved_at")) or "",
                "sentAt": _iso(report.get("sent_at")) or "",
                "xeroHistoryNoteStatus": report.get("xero_history_note_status") or "not_sent",
                "xeroHistoryNoteError": report.get("xero_history_note_error") or "",
            }
            for report in reports
        ],
        "submissions": [_serialize_me_report_submission(submission) for submission in submissions],
    }


def _normalise_me_report_tax_adjustment_overrides(value) -> dict:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = {}
    if not isinstance(value, dict):
        value = {}
    allowed_keys = [
        "depreciation",
        "amortisation",
        "nonAllowable",
        "penalties",
        "entertaining",
        "capitalAllowances",
    ]
    result = {}
    for key in allowed_keys:
        raw_entry = value.get(key) if isinstance(value.get(key), dict) else {}
        entry = {}
        for direction in ("add", "remove"):
            raw_codes = raw_entry.get(direction)
            if not isinstance(raw_codes, list):
                raw_codes = []
            seen = set()
            codes = []
            for raw_code in raw_codes:
                code = str(raw_code or "").strip().upper()
                if code and code not in seen:
                    seen.add(code)
                    codes.append(code)
            entry[direction] = codes[:200]
        result[key] = entry
    return result


def _normalise_me_report_transfer_classification(value) -> str:
    text = re.sub(r"[^a-z]", "", str(value or "").strip().lower())
    aliases = {
        "dividend": "dividend",
        "dividends": "dividend",
        "directorloan": "directorLoan",
        "directorsloan": "directorLoan",
        "directorloanaccount": "directorLoan",
        "directorsloanaccount": "directorLoan",
        "dla": "directorLoan",
        "wage": "wages",
        "wages": "wages",
        "salary": "wages",
        "payroll": "wages",
        "ignore": "ignore",
        "ignored": "ignore",
        "exclude": "ignore",
        "excluded": "ignore",
    }
    return aliases.get(text, "")


def _me_report_transfer_rule_key(value) -> str:
    key = re.sub(r"[^a-z0-9]+", " ", str(value or "").strip().lower())
    return re.sub(r"\s+", " ", key).strip()[:180]


def _normalise_me_report_transfer_classification_overrides(value) -> dict:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = {}
    if not isinstance(value, dict):
        value = {}
    result = {}
    for raw_key, raw_classification in value.items():
        key = _me_report_transfer_rule_key(raw_key)
        classification = _normalise_me_report_transfer_classification(raw_classification)
        if key and classification in ME_REPORT_TRANSFER_CLASSIFICATIONS:
            result[key] = classification
            if len(result) >= 300:
                break
    return result


def _normalise_me_report_director_loan_account_overrides(value) -> dict:
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = {}
    if not isinstance(value, dict):
        value = {}
    result = {"include": [], "exclude": []}
    for direction in ("include", "exclude"):
        raw_codes = value.get(direction)
        if not isinstance(raw_codes, list):
            raw_codes = []
        seen = set()
        for raw_code in raw_codes:
            code = str(raw_code or "").strip().upper()
            if code and code not in seen:
                seen.add(code)
                result[direction].append(code[:80])
            if len(result[direction]) >= 200:
                break
    confirmed_at = str(value.get("confirmedAt") or value.get("setupConfirmedAt") or "").strip()
    if confirmed_at:
        result["confirmedAt"] = confirmed_at[:80]
    return result


def _me_report_client_row(user: dict, client_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT * FROM me_report_clients WHERE id = %s AND user_id = %s",
                (client_id, user["id"]),
            )
            row = cursor.fetchone()
        connection.commit()
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report client not found.")
    return row


def _me_report_client_payloads(user: dict) -> tuple[list[dict], dict | None, dict | None]:
    _mark_stale_me_report_submissions(user["id"])
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM me_report_clients
                WHERE user_id = %s
                ORDER BY created_at DESC
                """,
                (user["id"],),
            )
            client_rows = cursor.fetchall()
            client_ids = [row["id"] for row in client_rows]
            mappings_by_client = defaultdict(list)
            reviews_by_client = defaultdict(list)
            exceptions_by_client = defaultdict(list)
            reports_by_client = defaultdict(list)
            submissions_by_client = defaultdict(list)
            if client_ids:
                cursor.execute(
                    """
                    SELECT *
                    FROM me_report_account_mappings
                    WHERE client_id = ANY(%s)
                    ORDER BY account_code ASC, account_name ASC
                    """,
                    (client_ids,),
                )
                for row in cursor.fetchall():
                    mappings_by_client[row["client_id"]].append(row)
                cursor.execute(
                    """
                    SELECT *
                    FROM me_report_reviews
                    WHERE client_id = ANY(%s)
                    ORDER BY period_end DESC, created_at DESC
                    """,
                    (client_ids,),
                )
                for row in cursor.fetchall():
                    reviews_by_client[row["client_id"]].append(row)
                cursor.execute(
                    """
                    SELECT *
                    FROM me_report_exceptions
                    WHERE client_id = ANY(%s)
                    ORDER BY CASE severity WHEN 'red' THEN 0 WHEN 'amber' THEN 1 ELSE 2 END, created_at DESC
                    """,
                    (client_ids,),
                )
                for row in cursor.fetchall():
                    exceptions_by_client[row["client_id"]].append(row)
                cursor.execute(
                    """
                    SELECT *
                    FROM me_report_reports
                    WHERE client_id = ANY(%s)
                    ORDER BY created_at DESC
                    """,
                    (client_ids,),
                )
                for row in cursor.fetchall():
                    reports_by_client[row["client_id"]].append(row)
                cursor.execute(
                    """
                    SELECT
                        id,
                        client_id,
                        filename,
                        content_type,
                        status,
                        error_message,
                        summary,
                        estimated_corporation_tax,
                        dividend_capacity,
                        created_at,
                        completed_at,
                        extracted_payload -> 'calculationSummary' AS calculation_summary
                    FROM me_report_submissions
                    WHERE client_id = ANY(%s)
                    ORDER BY created_at DESC
                    """,
                    (client_ids,),
                )
                for row in cursor.fetchall():
                    submissions_by_client[row["client_id"]].append(row)
            cursor.execute(
                """
                SELECT *
                FROM me_report_sync_runs
                WHERE user_id = %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (user["id"],),
            )
            latest_run = cursor.fetchone()
            cursor.execute(
                """
                SELECT *
                FROM me_report_sync_runs
                WHERE user_id = %s
                  AND status IN ('queued', 'running')
                ORDER BY COALESCE(heartbeat_at, started_at, created_at) DESC
                LIMIT 1
                """,
                (user["id"],),
            )
            active_run = cursor.fetchone()
        connection.commit()
    clients: list[dict] = []
    for row in client_rows:
        try:
            clients.append(
                _serialize_me_report_client(
                    row,
                    mappings_by_client.get(row["id"], []),
                    reviews_by_client.get(row["id"], [])[:8],
                    exceptions_by_client.get(row["id"], [])[:50],
                    reports_by_client.get(row["id"], [])[:12],
                    submissions_by_client.get(row["id"], [])[:20],
                )
            )
        except Exception:
            logger.exception(
                "me_report_client_serialize_failed user_id=%s client_id=%s",
                user.get("id"),
                row.get("id"),
            )
    return clients, active_run, latest_run


def me_report_payload(user: dict) -> dict:
    clients, active_run, latest_run = _me_report_client_payloads(user)
    summary = _me_report_empty_summary()
    summary["clientCount"] = len(clients)
    for client in clients:
        light = client.get("trafficLight") or "amber"
        if light in summary:
            summary[light] += 1
        latest_summary = client.get("summary") or {}
        summary["estimatedCorporationTax"] += float(_money(latest_summary.get("estimatedCorporationTax")))
        summary["dividendCapacity"] += float(_money(latest_summary.get("dividendCapacity")))
        if str(latest_summary.get("dlaStatus") or "").lower() == "red":
            summary["dlaRedCount"] += 1
        summary["reportsGenerated"] += len(client.get("reports") or [])
    try:
        xero_connection = get_xero_connection_for_user(user["id"])
    except HTTPException:
        xero_connection = None
    settings_row = _me_report_settings_row(user)
    connection_rows = list_xero_connections_for_user(user["id"], include_fallback=True)
    preferred_tenant_name = get_settings().xero_primary_tenant_name
    connections = [
        {
            "tenantId": str(row.get("tenant_id") or ""),
            "tenantName": str(row.get("tenant_name") or ""),
            "tenantType": str(row.get("tenant_type") or ""),
            "updatedAt": _iso(row.get("updated_at")) or "",
            "createdAt": _iso(row.get("created_at")) or "",
        }
        for row in sorted(connection_rows, key=lambda row: _xero_connection_sort_key(row, preferred_tenant_name), reverse=True)
        if str(row.get("tenant_id") or "").strip()
    ]
    try:
        contact_options = _me_report_contact_options(user, xero_connection.get("tenant_id") if xero_connection else None)
    except Exception:
        logger.exception("me_report_contact_options_failed user_id=%s", user.get("id"))
        contact_options = []
    return {
        "summary": summary,
        "clients": clients,
        "settings": _serialize_me_report_settings(settings_row),
        "treatmentCategories": ME_REPORT_CATEGORIES,
        "xero": {
            "connected": bool(xero_connection),
            "tenantName": xero_connection.get("tenant_name") if xero_connection else "",
            "tenantId": xero_connection.get("tenant_id") if xero_connection else "",
            "contacts": contact_options,
            "connections": connections,
        },
        "syncRun": _serialize_me_report_sync_run(active_run or latest_run),
        "activeSyncRun": _serialize_me_report_sync_run(active_run),
    }


def create_me_report_client(user: dict, payload: dict) -> dict:
    requested_tenant_id = str(payload.get("tenantId") or "").strip()
    xero_contact_id = str(payload.get("xeroContactId") or "").strip()
    xero_contact = _me_report_contact_for_user(user, xero_contact_id, requested_tenant_id or None) if xero_contact_id else None
    if xero_contact_id and not xero_contact:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Choose a valid Xero contact from the ME Report client dropdown.")
    client_name = str(payload.get("clientName") or "").strip()
    if xero_contact:
        client_name = xero_contact["name"]
    if not client_name:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Client name is required. Sync Xero contacts, then choose a contact from the dropdown.")
    owner = str(payload.get("internalClientOwner") or "").strip()
    frequency = str(payload.get("bookkeepingFrequency") or "Monthly").strip() or "Monthly"
    recipient = str(payload.get("reportRecipientEmail") or (xero_contact or {}).get("email") or "").strip()
    brought_forward_trading_loss = _non_negative_money(payload.get("broughtForwardTradingLoss") or 0, "Brought forward trading loss")
    try:
        year_end_month = int(payload.get("yearEndMonth") or 3)
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Year end month must be a number from 1 to 12.") from exc
    year_end_month = min(12, max(1, year_end_month))
    try:
        connection_row = xero_connection_for_user_tenant(user, requested_tenant_id or None)
    except HTTPException:
        connection_row = {}
    resolved_tenant_id = str(connection_row.get("tenant_id") or requested_tenant_id or (xero_contact or {}).get("tenantId") or "").strip()
    resolved_tenant_name = str(
        connection_row.get("tenant_name")
        or (xero_contact or {}).get("tenantName")
        or ""
    ).strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO me_report_clients (
                    user_id, client_name, internal_client_owner,
                    bookkeeping_frequency, report_recipient_email,
                    year_end_month, brought_forward_trading_loss,
                    brought_forward_trading_loss_updated_at,
                    xero_contact_id, xero_contact_name,
                    xero_contact_email, xero_connection_id, xero_tenant_id,
                    xero_tenant_name, xero_connection_status, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING id
                """,
                (
                    user["id"],
                    client_name,
                    owner,
                    frequency,
                    recipient,
                    year_end_month,
                    brought_forward_trading_loss,
                    utcnow() if brought_forward_trading_loss else None,
                    xero_contact["xeroContactId"] if xero_contact else None,
                    xero_contact["name"] if xero_contact else "",
                    xero_contact["email"] if xero_contact else "",
                    connection_row.get("id"),
                    resolved_tenant_id,
                    resolved_tenant_name,
                    "connected" if resolved_tenant_id else "not_connected",
                    utcnow(),
                    utcnow(),
                ),
            )
            client_id = cursor.fetchone()["id"]
        connection.commit()
    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.client_created",
        {"client_name": client_name, "xero_contact_id": xero_contact_id},
        user["id"],
    )
    return me_report_payload(user)


def update_me_report_client(user: dict, client_id: str, payload: dict) -> dict:
    client = _me_report_client_row(user, client_id)
    now = utcnow()
    if "broughtForwardTradingLoss" in payload:
        brought_forward_trading_loss = _non_negative_money(payload.get("broughtForwardTradingLoss") or 0, "Brought forward trading loss")
        brought_forward_trading_loss_updated_at = now
    else:
        brought_forward_trading_loss = _money(client.get("brought_forward_trading_loss"))
        brought_forward_trading_loss_updated_at = client.get("brought_forward_trading_loss_updated_at")
    vat_registered_confirmed = bool(payload.get("vatRegisteredConfirmed")) if "vatRegisteredConfirmed" in payload else bool(client.get("vat_registered_confirmed"))
    if "vatRegisteredConfirmed" in payload:
        vat_registered_confirmed_at = now if vat_registered_confirmed else None
    else:
        vat_registered_confirmed_at = client.get("vat_registered_confirmed_at")
    existing_dismissed = client.get("dismissed_warning_keys") or []
    if isinstance(existing_dismissed, str):
        try:
            existing_dismissed = json.loads(existing_dismissed)
        except ValueError:
            existing_dismissed = []
    dismissed_warning_keys = existing_dismissed if isinstance(existing_dismissed, list) else []
    if isinstance(payload.get("dismissedWarningKeys"), list):
        dismissed_warning_keys = [
            str(item).strip()
            for item in payload.get("dismissedWarningKeys")
            if str(item).strip()
        ][:200]
    tax_adjustment_overrides = _normalise_me_report_tax_adjustment_overrides(client.get("tax_adjustment_overrides"))
    if "taxAdjustmentOverrides" in payload:
        tax_adjustment_overrides = _normalise_me_report_tax_adjustment_overrides(payload.get("taxAdjustmentOverrides"))
    transfer_classification_overrides = _normalise_me_report_transfer_classification_overrides(client.get("transfer_classification_overrides"))
    if "transferClassificationOverrides" in payload:
        transfer_classification_overrides = _normalise_me_report_transfer_classification_overrides(payload.get("transferClassificationOverrides"))
    director_loan_account_overrides = _normalise_me_report_director_loan_account_overrides(client.get("director_loan_account_overrides"))
    if "directorLoanAccountOverrides" in payload:
        director_loan_account_overrides = _normalise_me_report_director_loan_account_overrides(payload.get("directorLoanAccountOverrides"))
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE me_report_clients
                SET brought_forward_trading_loss = %s,
                    brought_forward_trading_loss_updated_at = %s,
                    vat_registered_confirmed = %s,
                    vat_registered_confirmed_at = %s,
                    dismissed_warning_keys = %s::jsonb,
                    tax_adjustment_overrides = %s::jsonb,
                    transfer_classification_overrides = %s::jsonb,
                    director_loan_account_overrides = %s::jsonb,
                    updated_at = %s
                WHERE id = %s
                  AND user_id = %s
                """,
                (
                    brought_forward_trading_loss,
                    brought_forward_trading_loss_updated_at,
                    vat_registered_confirmed,
                    vat_registered_confirmed_at,
                    json.dumps(dismissed_warning_keys, default=_json_default),
                    json.dumps(tax_adjustment_overrides, default=_json_default),
                    json.dumps(transfer_classification_overrides, default=_json_default),
                    json.dumps(director_loan_account_overrides, default=_json_default),
                    now,
                    client_id,
                    user["id"],
                ),
            )
            if vat_registered_confirmed:
                cursor.execute(
                    """
                    UPDATE me_report_exceptions
                    SET status = 'resolved',
                        note = CASE
                            WHEN COALESCE(note, '') = '' THEN 'Client confirmed VAT registered.'
                            ELSE note
                        END,
                        updated_at = %s
                    WHERE client_id = %s
                      AND status = 'open'
                      AND (
                          LOWER(COALESCE(title, '')) LIKE '%%vat registration threshold%%'
                          OR LOWER(COALESCE(detail, '')) LIKE '%%vat registration threshold%%'
                      )
                    """,
                    (now, client_id),
                )
        connection.commit()
    record_audit_event(
        "me_report_client",
        client_id,
        "me_report.client_updated",
        {
            "brought_forward_trading_loss": float(brought_forward_trading_loss),
            "brought_forward_trading_loss_updated_at": _iso(brought_forward_trading_loss_updated_at) or "",
            "vat_registered_confirmed": vat_registered_confirmed,
            "vat_registered_confirmed_at": _iso(vat_registered_confirmed_at) or "",
            "dismissed_warning_count": len(dismissed_warning_keys),
            "tax_adjustment_override_count": sum(
                len(entry.get("add") or []) + len(entry.get("remove") or [])
                for entry in tax_adjustment_overrides.values()
            ),
            "transfer_classification_override_count": len(transfer_classification_overrides),
            "director_loan_account_override_count": (
                len(director_loan_account_overrides.get("include") or [])
                + len(director_loan_account_overrides.get("exclude") or [])
            ),
        },
        user["id"],
    )
    return me_report_payload(user)


def update_me_report_client_status(user: dict, client_id: str, payload: dict) -> dict:
    requested_status = str(payload.get("status") or "").strip().lower()
    if requested_status not in {"active", "archived"}:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Client status must be active or archived.")
    _me_report_client_row(user, client_id)
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE me_report_clients
                SET status = %s,
                    updated_at = %s
                WHERE id = %s
                  AND user_id = %s
                """,
                (requested_status, now, client_id, user["id"]),
            )
        connection.commit()
    record_audit_event(
        "me_report_client",
        client_id,
        f"me_report.client_{requested_status}",
        {"status": requested_status},
        user["id"],
    )
    return me_report_payload(user)


def delete_me_report_client(user: dict, client_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT clients.id,
                       clients.client_name,
                       (
                           SELECT COUNT(*)
                           FROM me_report_submissions
                           WHERE client_id = clients.id
                       ) AS submission_count,
                       (
                           SELECT COUNT(*)
                           FROM me_report_reports
                           WHERE client_id = clients.id
                       ) AS report_count,
                       (
                           SELECT COUNT(*)
                           FROM me_report_sync_runs
                           WHERE client_id = clients.id
                             AND status IN ('queued', 'running')
                       ) AS active_sync_count
                FROM me_report_clients AS clients
                WHERE clients.id = %s
                  AND clients.user_id = %s
                """,
                (client_id, user["id"]),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report client not found.")
            if int(row.get("active_sync_count") or 0) > 0:
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Wait for the active ME Report sync to finish before deleting this client.")
            cursor.execute(
                """
                DELETE FROM me_report_clients
                WHERE id = %s
                  AND user_id = %s
                """,
                (client_id, user["id"]),
            )
        connection.commit()
    record_audit_event(
        "me_report_client",
        client_id,
        "me_report.client_deleted",
        {
            "client_name": row.get("client_name") or "",
            "submission_count": int(row.get("submission_count") or 0),
            "report_count": int(row.get("report_count") or 0),
        },
        user["id"],
    )
    return me_report_payload(user)


def connect_me_report_client_to_current_xero(user: dict, client_id: str) -> dict:
    _me_report_client_row(user, client_id)
    connection_row = get_xero_connection_for_user(user["id"])
    now = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE me_report_clients
                SET xero_connection_id = %s,
                    xero_tenant_id = %s,
                    xero_tenant_name = %s,
                    xero_connection_status = 'connected',
                    updated_at = %s
                WHERE id = %s
                  AND user_id = %s
                """,
                (
                    connection_row.get("id"),
                    connection_row.get("tenant_id"),
                    connection_row.get("tenant_name") or "Xero organisation",
                    now,
                    client_id,
                    user["id"],
                ),
            )
        connection.commit()
    record_audit_event(
        "me_report_client",
        client_id,
        "me_report.xero_connected",
        {"tenant_id": connection_row.get("tenant_id"), "tenant_name": connection_row.get("tenant_name")},
        user["id"],
    )
    return me_report_payload(user)


