async def upload_me_report_submission_pdf(user: dict, client_id: str, filename: str, content_type: str, file_bytes: bytes) -> tuple[str, dict]:
    client = _me_report_client_row(user, client_id)
    upload_kind = _me_report_upload_kind(filename, content_type)
    default_content_type = "application/pdf" if upload_kind == "pdf" else "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO me_report_submissions (
                    client_id, filename, content_type, status, created_by_user_id, created_at
                )
                VALUES (%s, %s, %s, 'processing', %s, %s)
                RETURNING id
                """,
                (client_id, filename, content_type or default_content_type, user["id"], utcnow()),
            )
            submission_id = cursor.fetchone()["id"]
        connection.commit()

    try:
        if upload_kind == "spreadsheet":
            extracted = await _extract_me_report_spreadsheet(file_bytes, filename, client)
            payload_source = "uploaded_spreadsheet"
            summary_fallback = "Management accounts spreadsheet processed by Jenius AI."
        else:
            extracted = await _extract_me_report_pdf(file_bytes, filename, client)
            payload_source = "uploaded_pdf"
            summary_fallback = "Management accounts PDF processed by Jenius AI."
        review_summary = _build_me_report_pdf_summary(extracted, client)
        estimated_ct = _money(review_summary.get("estimatedCorporationTax"))
        dividend_capacity = _money(review_summary.get("dividendCapacity"))
        period_end = _parse_optional_iso_date(review_summary.get("periodEnd") or extracted.get("periodEnd")) or utcnow().date()
        period_start = _parse_optional_iso_date(review_summary.get("periodStart") or extracted.get("periodStart")) or date(period_end.year, period_end.month, 1)
        traffic_light = str(review_summary.get("trafficLight") or "amber").lower()
        if traffic_light not in {"green", "amber", "red"}:
            traffic_light = "amber"
        summary_text = str(review_summary.get("commentary") or extracted.get("summary") or summary_fallback).strip()[:1200]
        enriched_payload = {
            **extracted,
            "calculationSummary": review_summary,
        }
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE me_report_submissions
                    SET status = 'completed',
                        summary = %s,
                        extracted_payload = %s::jsonb,
                        estimated_corporation_tax = %s,
                        dividend_capacity = %s,
                        completed_at = %s
                    WHERE id = %s
                    """,
                    (
                        summary_text,
                        json.dumps(enriched_payload, default=_json_default),
                        estimated_ct,
                        dividend_capacity,
                        utcnow(),
                        submission_id,
                    ),
                )
                cursor.execute(
                    """
                    INSERT INTO me_report_reviews (
                        client_id, period_start, period_end, status, traffic_light,
                        summary, raw_payload, created_by_user_id, created_at, updated_at
                    )
                    VALUES (%s, %s, %s, 'calculated', %s, %s::jsonb, %s::jsonb, %s, %s, %s)
                    """,
                    (
                        client_id,
                        period_start,
                        period_end,
                        traffic_light,
                        json.dumps(review_summary, default=_json_default),
                        json.dumps({"source": payload_source, "submissionId": str(submission_id), "extracted": enriched_payload}, default=_json_default),
                        user["id"],
                        utcnow(),
                        utcnow(),
                    ),
                )
                cursor.execute(
                    """
                    UPDATE me_report_clients
                    SET last_calculated_at = %s,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    (utcnow(), utcnow(), client_id),
                )
            connection.commit()
    except Exception as exc:
        error = _sync_error_message(exc)
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE me_report_submissions
                    SET status = 'failed',
                        error_message = %s,
                        completed_at = %s
                    WHERE id = %s
                    """,
                    (error, utcnow(), submission_id),
                )
            connection.commit()
        raise

    record_audit_event(
        "me_report_submission",
        str(submission_id),
        "me_report.submission_extracted",
        {"client_id": client_id, "filename": filename, "estimated_ct": str(estimated_ct), "dividend_capacity": str(dividend_capacity)},
        user["id"],
    )
    return str(submission_id), me_report_payload(user)


def delete_me_report_submission(user: dict, submission_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT submissions.id,
                       submissions.client_id,
                       submissions.filename,
                       clients.client_name
                FROM me_report_submissions AS submissions
                JOIN me_report_clients AS clients ON clients.id = submissions.client_id
                WHERE submissions.id = %s
                  AND clients.user_id = %s
                """,
                (submission_id, user["id"]),
            )
            submission = cursor.fetchone()
            if submission is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report submission not found.")
            cursor.execute(
                """
                SELECT id
                FROM me_report_reviews
                WHERE client_id = %s
                  AND raw_payload ->> 'submissionId' = %s
                """,
                (submission["client_id"], submission_id),
            )
            review_ids = [row["id"] for row in cursor.fetchall()]
            if review_ids:
                cursor.execute("DELETE FROM me_report_reports WHERE review_id = ANY(%s)", (review_ids,))
                cursor.execute("DELETE FROM me_report_reviews WHERE id = ANY(%s)", (review_ids,))
            cursor.execute("DELETE FROM me_report_submissions WHERE id = %s", (submission_id,))
            cursor.execute(
                """
                UPDATE me_report_clients
                SET last_calculated_at = (
                        SELECT MAX(created_at)
                        FROM me_report_reviews
                        WHERE client_id = %s
                    ),
                    updated_at = %s
                WHERE id = %s
                """,
                (submission["client_id"], utcnow(), submission["client_id"]),
            )
        connection.commit()
    record_audit_event(
        "me_report_submission",
        submission_id,
        "me_report.submission_deleted",
        {
            "client_id": str(submission["client_id"]),
            "client_name": submission.get("client_name") or "",
            "filename": submission.get("filename") or "",
            "review_count": len(review_ids),
        },
        user["id"],
    )
    return me_report_payload(user)


def _me_treatment_for_account(account: dict) -> dict:
    name = str(account.get("Name") or account.get("name") or "").lower()
    code = str(account.get("Code") or account.get("code") or "")
    account_type = str(account.get("Type") or account.get("type") or "")
    text = f"{code} {name} {account_type}".lower()
    rules = [
        (("client entertaining", "entertain"), ("Client entertaining", "Add back for CT", "Client entertaining", 99, True, "Entertainment is normally disallowable for corporation tax.")),
        (("fine", "penalt"), ("Fines and penalties", "Add back for CT", "Fines and penalties", 98, True, "Fines and penalties are normally disallowable.")),
        (("depreciation",), ("Depreciation", "Add back for CT", "Depreciation", 99, False, "Depreciation is added back before capital allowance claims.")),
        (("computer", "laptop", "equipment"), ("Computer equipment", "Review for capital allowances", "Computer equipment", 92, True, "Asset-style account name suggests a capital allowances review.")),
        (("director loan", "directors loan", "dla"), ("Director loan account", "Include in DLA engine", "Director loan account", 100, False, "Director loan account identified from account name.")),
        (("dividend",), ("Dividends", "Include in dividend engine", "Dividends", 100, False, "Dividend account identified from account name.")),
        (("corporation tax", "corp tax", "ct creditor"), ("Corporation tax creditor", "Compare provision to estimated CT", "Corporation tax creditor", 96, False, "Corporation tax account identified from account name.")),
        (("vat",), ("VAT", "Balance sheet tax creditor/debtor", "VAT", 95, False, "VAT balance sheet account identified.")),
        (("paye", "nic", "hmrc payroll"), ("PAYE/NIC", "Balance sheet tax creditor", "PAYE/NIC", 95, False, "Payroll tax creditor account identified.")),
        (("retained earnings", "profit and loss account"), ("Retained earnings", "Use in dividend capacity engine", "Retained earnings", 96, False, "Retained reserves account identified.")),
        (("motor", "vehicle", "fuel"), ("Motor Expenses", "Review if private use risk", "Private use items", 75, True, "Motor expenses can carry private use risk.")),
        (("legal",), ("Legal fees needing review", "Review deductibility", "Legal fees needing review", 72, True, "Legal fees can be allowable, capital or disallowable depending on the matter.")),
        (("sales", "revenue", "turnover"), ("Sales", "Taxable trading income", "Sales", 94, False, "Income account identified.")),
        (("bank interest", "interest received"), ("Bank interest", "Taxable income", "Bank interest", 90, False, "Interest income account identified.")),
        (("software", "subscription"), ("Software", "Allowable expense", "Software", 90, False, "Normal software or subscription cost.")),
        (("accountancy", "bookkeeping"), ("Accountancy fees", "Allowable expense", "Accountancy fees", 90, False, "Accountancy costs are normally allowable.")),
        (("wages", "salary", "payroll"), ("Staff wages", "Allowable expense", "Staff wages", 90, False, "Payroll cost account identified.")),
        (("bank charges",), ("Bank charges", "Allowable expense", "Bank charges", 90, False, "Bank charges are normally allowable.")),
        (("trade debtor", "accounts receivable", "debtors"), ("Trade debtors", "Balance sheet working capital", "Trade debtors", 90, False, "Debtor control account identified.")),
        (("trade creditor", "accounts payable", "creditors"), ("Trade creditors", "Balance sheet working capital", "Trade creditors", 90, False, "Creditor control account identified.")),
        (("bank", "current account"), ("Bank", "Bank balance", "Bank", 88, False, "Bank account identified.")),
    ]
    for needles, result in rules:
        if any(needle in text for needle in needles):
            treatment, tax_treatment, category, confidence, review_required, reason = result
            return {
                "suggestedTreatment": treatment,
                "taxTreatment": tax_treatment,
                "category": category,
                "confidence": confidence,
                "reviewRequired": review_required,
                "reason": reason,
            }
    if account_type.upper() in ("REVENUE", "SALES"):
        return {"suggestedTreatment": "Sales", "taxTreatment": "Taxable trading income", "category": "Sales", "confidence": 84, "reviewRequired": False, "reason": "Xero account type is revenue."}
    if account_type.upper() in ("EXPENSE", "DIRECTCOSTS", "OVERHEADS"):
        return {"suggestedTreatment": "Normal allowable expense", "taxTreatment": "Review standard deductibility", "category": "Office costs", "confidence": 68, "reviewRequired": True, "reason": "Expense account needs staff confirmation before tax treatment is relied on."}
    return {"suggestedTreatment": "Needs review", "taxTreatment": "Staff review required", "category": "Directors' income items needing review", "confidence": 50, "reviewRequired": True, "reason": "No confident Jaccountancy treatment rule matched this account."}


def _money_from_report_cell(value) -> Decimal | None:
    text = str(value if value is not None else "").strip()
    if not text:
        return None
    negative = text.startswith("(") and text.endswith(")")
    text = text.strip("()").replace(",", "").replace("£", "").replace("%", "").replace("\u00a0", " ").strip()
    if text.lower().endswith("cr"):
        text = text[:-2].strip()
    elif text.lower().endswith("dr"):
        text = text[:-2].strip()
    if text.endswith("-"):
        negative = True
        text = text[:-1].strip()
    if text in {"-", "—"}:
        return None
    try:
        amount = Decimal(text)
    except Exception:
        return None
    return _money(-amount if negative else amount)


def _xero_report_lines(report_payload: dict) -> list[dict]:
    lines = []

    def visit(rows):
        for row in rows or []:
            cells = row.get("Cells") or row.get("cells") or []
            values = [cell.get("Value") or cell.get("value") or "" for cell in cells if isinstance(cell, dict)]
            if values:
                label = str(values[0] or "").strip()
                amounts = [_money_from_report_cell(value) for value in values[1:]]
                row_type = str(row.get("RowType") or row.get("rowType") or "").strip()
                lines.append({"label": label, "amounts": amounts, "rowType": row_type, "raw": row})
            visit(row.get("Rows") or row.get("rows") or [])

    for report in report_payload.get("Reports") or report_payload.get("reports") or []:
        visit(report.get("Rows") or report.get("rows") or [])
    return lines


def _xero_report_header_dates(report_payload: dict) -> list[date | None]:
    def parse_header_date(value: object) -> date | None:
        text = str(value or "").strip()
        if not text:
            return None
        iso = _parse_optional_iso_date(text)
        if iso:
            return iso
        for fmt in ("%d %b %Y", "%d %B %Y", "%d/%m/%Y", "%d-%m-%Y", "%Y/%m/%d"):
            try:
                return datetime.strptime(text, fmt).date()
            except Exception:
                continue
        return None

    def visit(rows: object) -> list[date | None] | None:
        for row in rows if isinstance(rows, list) else []:
            if not isinstance(row, dict):
                continue
            row_type = str(row.get("RowType") or row.get("rowType") or "").strip().lower()
            cells = row.get("Cells") or row.get("cells") or []
            if row_type == "header" and isinstance(cells, list) and len(cells) > 1:
                parsed = [
                    parse_header_date((cell or {}).get("Value") if isinstance(cell, dict) else "")
                    for cell in cells[1:]
                ]
                if any(item is not None for item in parsed):
                    return parsed
            nested = visit(row.get("Rows") or row.get("rows") or [])
            if nested:
                return nested
        return None

    for report in report_payload.get("Reports") or report_payload.get("reports") or []:
        header_dates = visit(report.get("Rows") or report.get("rows") or [])
        if header_dates:
            return header_dates
    return []


def _report_amount(lines: list[dict], keywords: tuple[str, ...], fallback: Decimal = Decimal("0.00")) -> Decimal:
    for line in lines:
        label = (line.get("label") or "").lower()
        if all(keyword in label for keyword in keywords):
            amounts = [amount for amount in line.get("amounts") or [] if amount is not None]
            if amounts:
                return _money(amounts[-1])
    return fallback


def _me_report_trial_balance_payroll_control_warnings_from_accounts(trial_balance_accounts: list[dict]) -> list[dict]:
    warnings: list[dict] = []
    if not isinstance(trial_balance_accounts, list):
        return warnings
    patterns = [
        (("wages payable",), "Wages payable"),
        (("wage payable",), "Wages payable"),
        (("payroll payable",), "Payroll payable"),
        (("pension payable",), "Pension payable"),
    ]
    seen: set[str] = set()
    for account in trial_balance_accounts:
        if not isinstance(account, dict):
            continue
        label = " ".join([
            str(account.get("accountCode") or "").strip(),
            str(account.get("accountName") or "").strip(),
            str(account.get("accountType") or "").strip(),
        ]).strip()
        label_lower = label.lower()
        category = ""
        for terms, category_label in patterns:
            if all(term in label_lower for term in terms):
                category = category_label
                break
        if not category:
            continue
        amount = _money(account.get("amount"))
        if amount == Decimal("0.00"):
            amount = _money(_money(account.get("debitYTD")) - _money(account.get("creditYTD")))
        outstanding = abs(_money(amount))
        if outstanding <= Decimal("0.00"):
            continue
        key = f"{category}|{str(account.get('accountCode') or '').strip().lower()}|{str(account.get('accountName') or '').strip().lower()}"
        if key in seen:
            continue
        seen.add(key)
        warnings.append(
            {
                "accountCode": str(account.get("accountCode") or "").strip(),
                "accountName": str(account.get("accountName") or "").strip(),
                "category": category,
                "amount": float(_money(amount)),
                "outstandingAmount": float(outstanding),
                "source": str(account.get("source") or "").strip(),
            }
        )
    return warnings


def _me_report_trial_balance_payroll_control_warnings_from_report_payload(trial_balance_payload: dict) -> list[dict]:
    lines = _xero_report_lines(trial_balance_payload if isinstance(trial_balance_payload, dict) else {})
    warnings: list[dict] = []
    patterns = [
        (("wages payable",), "Wages payable"),
        (("wage payable",), "Wages payable"),
        (("payroll payable",), "Payroll payable"),
        (("pension payable",), "Pension payable"),
    ]
    seen: set[str] = set()
    for line in lines:
        label = str(line.get("label") or "").strip()
        label_lower = label.lower()
        if not label_lower or label_lower in {"total", "totals"}:
            continue
        category = ""
        for terms, category_label in patterns:
            if all(term in label_lower for term in terms):
                category = category_label
                break
        if not category:
            continue
        amounts = [item for item in (line.get("amounts") or []) if isinstance(item, Decimal)]
        if not amounts:
            continue
        amount = _money(amounts[-1])
        outstanding = abs(_money(amount))
        if outstanding <= Decimal("0.00"):
            continue
        key = f"{category}|{label_lower}"
        if key in seen:
            continue
        seen.add(key)
        warnings.append(
            {
                "accountCode": "",
                "accountName": label,
                "category": category,
                "amount": float(_money(amount)),
                "outstandingAmount": float(outstanding),
                "source": "Xero Trial Balance",
            }
        )
    return warnings


def _normalise_contact_match_name(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())


def _xero_contact_name(contact: dict) -> str:
    return str(contact.get("Name") or contact.get("name") or "").strip()


def _xero_contact_id(contact: dict) -> str:
    return str(contact.get("ContactID") or contact.get("contactID") or contact.get("ContactId") or "").strip()


def _find_duplicate_contact_candidates(contacts: list[dict]) -> list[dict]:
    grouped: dict[str, list[dict]] = defaultdict(list)
    for contact in contacts:
        name = _xero_contact_name(contact)
        contact_id = _xero_contact_id(contact)
        key = _normalise_contact_match_name(name)
        if key and contact_id:
            grouped[key].append({"name": name, "contactId": contact_id})
    candidates = []
    for rows in grouped.values():
        distinct_names = {row["name"].lower() for row in rows}
        distinct_ids = {row["contactId"] for row in rows}
        if len(distinct_names) > 1 and len(distinct_ids) > 1:
            keep = rows[0]
            for duplicate in rows[1:4]:
                candidates.append({
                    "keepContactId": keep["contactId"],
                    "keepName": keep["name"],
                    "mergeContactId": duplicate["contactId"],
                    "mergeName": duplicate["name"],
                })
    return candidates[:10]


def _xero_bank_transaction_amount(transaction: dict) -> Decimal:
    if transaction.get("Total") is not None:
        return abs(_money(transaction.get("Total")))
    return abs(sum(_money(item.get("LineAmount")) for item in transaction.get("LineItems") or []))


def _me_report_bank_transaction_date(transaction: dict) -> date | None:
    for key in ("Date", "DateString", "UpdatedDateUTC", "UpdatedDate", "CreatedDateUTC"):
        value = transaction.get(key)
        parsed_dt = _parse_optional_iso_datetime(value)
        if parsed_dt:
            return parsed_dt.date()
        parsed_date = _parse_optional_iso_date(value)
        if parsed_date:
            return parsed_date
    return None


def _me_report_bank_transaction_rows(
    bank_transactions_payload: dict,
    period_start: date,
    period_end: date,
) -> list[dict]:
    rows: list[dict] = []
    transactions = bank_transactions_payload.get("BankTransactions") or []
    for transaction in transactions:
        if not isinstance(transaction, dict):
            continue
        transaction_date = _me_report_bank_transaction_date(transaction)
        if transaction_date and (transaction_date < period_start or transaction_date > period_end):
            continue
        if transaction.get("Total") is not None:
            amount = _money(transaction.get("Total"))
        else:
            amount = _money(sum(_money(item.get("LineAmount")) for item in transaction.get("LineItems") or []))
        reference = str(transaction.get("Reference") or "").strip()
        narration = str(transaction.get("Narration") or "").strip()
        transaction_type = str(transaction.get("Type") or "").strip()
        contact = transaction.get("Contact") if isinstance(transaction.get("Contact"), dict) else {}
        contact_name = str(contact.get("Name") or "").strip()
        description_parts = [part for part in (reference, narration, transaction_type, contact_name) if part]
        description = " · ".join(description_parts) if description_parts else "Bank transaction"
        transaction_id = str(
            transaction.get("BankTransactionID")
            or transaction.get("BankTransactionId")
            or transaction.get("ID")
            or ""
        ).strip()
        status_text = str(transaction.get("Status") or "").strip()
        status_upper = status_text.upper()
        if transaction.get("IsReconciled") is None:
            is_reconciled = status_upper in {"RECONCILED", "MATCHED"}
        else:
            is_reconciled = bool(transaction.get("IsReconciled"))
        if status_upper == "UNRECONCILED":
            is_reconciled = False
        bank_account = transaction.get("BankAccount") if isinstance(transaction.get("BankAccount"), dict) else {}
        account_code = str(bank_account.get("Code") or "").strip() or "BANK"
        account_name = str(bank_account.get("Name") or "").strip() or "Bank transactions"
        rows.append(
            {
                "transactionId": transaction_id,
                "date": transaction_date.isoformat() if transaction_date else "",
                "description": description,
                "amount": float(amount),
                "source": "Xero BankTransactions API",
                "status": status_text,
                "isReconciled": is_reconciled,
                "accountCode": account_code,
                "accountName": account_name,
            }
        )
    return rows


def _me_report_trial_balance_accounts_from_bank_transactions(rows: list[dict]) -> list[dict]:
    grouped: dict[tuple[str, str], list[dict]] = defaultdict(list)
    for row in rows:
        if not isinstance(row, dict):
            continue
        account_code = str(row.get("accountCode") or "BANK").strip() or "BANK"
        account_name = str(row.get("accountName") or "Bank transactions").strip() or "Bank transactions"
        grouped[(account_code, account_name)].append(row)
    accounts: list[dict] = []
    for (account_code, account_name), account_rows in sorted(grouped.items(), key=lambda item: (item[0][1], item[0][0])):
        debit_total = Decimal("0.00")
        credit_total = Decimal("0.00")
        net_total = Decimal("0.00")
        transactions = []
        for row in account_rows:
            amount = _money(row.get("amount"))
            net_total += amount
            if amount >= 0:
                debit_total += amount
            else:
                credit_total += abs(amount)
            transactions.append(
                {
                    "transactionId": str(row.get("transactionId") or ""),
                    "date": str(row.get("date") or ""),
                    "description": str(row.get("description") or ""),
                    "amount": float(amount),
                    "source": str(row.get("source") or "Xero BankTransactions API"),
                    "status": str(row.get("status") or ""),
                    "isUnreconciled": not bool(row.get("isReconciled")),
                    "reconciled": bool(row.get("isReconciled")),
                    "bankTransactionId": str(row.get("transactionId") or ""),
                }
            )
        accounts.append(
            {
                "accountCode": account_code,
                "accountName": account_name,
                "accountType": "BANK",
                "debitYTD": float(_money(debit_total)),
                "creditYTD": float(_money(credit_total)),
                "amount": float(_money(net_total)),
                "source": "Xero BankTransactions API",
                "transactions": transactions[:1000],
            }
        )
    return accounts


def _me_report_unreconciled_bank_transactions(rows: list[dict]) -> list[dict]:
    results = []
    for row in rows:
        if bool(row.get("isReconciled")):
            continue
        transaction_id = str(row.get("transactionId") or "").strip()
        if not transaction_id:
            continue
        results.append(
            {
                "transactionId": transaction_id,
                "id": transaction_id,
                "bankTransactionId": transaction_id,
                "date": str(row.get("date") or ""),
                "description": str(row.get("description") or ""),
                "amount": float(_money(row.get("amount"))),
                "status": str(row.get("status") or "Unreconciled"),
                "isUnreconciled": True,
                "reconciled": False,
                "source": str(row.get("source") or "Xero BankTransactions API"),
            }
        )
    return results[:300]


def _xero_invoice_amount_due(invoice: dict) -> Decimal:
    return abs(_money(invoice.get("AmountDue") if invoice.get("AmountDue") is not None else invoice.get("Total")))


def _xero_invoice_contact_id(invoice: dict) -> str:
    contact = invoice.get("Contact") or {}
    return str(contact.get("ContactID") or contact.get("contactID") or "").strip()


def _find_duplicate_spend_bill_candidates(bank_transactions: list[dict], bills: list[dict]) -> list[dict]:
    candidates = []
    open_bills = [
        {
            "invoiceId": bill.get("InvoiceID") or bill.get("invoiceID") or "",
            "invoiceNumber": bill.get("InvoiceNumber") or bill.get("Reference") or "Bill",
            "contactId": _xero_invoice_contact_id(bill),
            "amountDue": _xero_invoice_amount_due(bill),
        }
        for bill in bills
        if _xero_invoice_amount_due(bill) > Decimal("0.00")
    ]
    for transaction in bank_transactions:
        transaction_type = str(transaction.get("Type") or "").upper()
        if transaction_type not in ("SPEND", "SPEND-MONEY", "SPEND MONEY"):
            continue
        amount = _xero_bank_transaction_amount(transaction)
        contact_id = _xero_invoice_contact_id({"Contact": transaction.get("Contact") or {}})
        for bill in open_bills:
            if bill["contactId"] and contact_id and bill["contactId"] != contact_id:
                continue
            if abs(bill["amountDue"] - amount) <= Decimal("1.00"):
                candidates.append({
                    "bankTransactionId": transaction.get("BankTransactionID") or "",
                    "bankTransactionReference": transaction.get("Reference") or transaction.get("Url") or "Spend money transaction",
                    "billId": bill["invoiceId"],
                    "billNumber": bill["invoiceNumber"],
                    "amount": float(amount),
                })
                break
    return candidates[:12]


def _asset_book_value(asset: dict) -> Decimal:
    for key in ("BookValue", "bookValue", "CurrentValue", "currentValue", "PurchasePrice", "purchasePrice"):
        if asset.get(key) is not None:
            return _money(asset.get(key))
    return Decimal("0.00")


def _asset_register_total(asset_payload: dict) -> Decimal | None:
    if asset_payload.get("_error"):
        return None
    rows = asset_payload.get("Items") or asset_payload.get("Assets") or asset_payload.get("assets") or []
    return sum((_asset_book_value(row) for row in rows), Decimal("0.00"))


def _balance_sheet_fixed_asset_total(lines: list[dict]) -> Decimal:
    fixed_asset_keywords = (("fixed", "asset"), ("plant",), ("equipment",), ("computer",), ("fixtures",), ("vehicle",), ("motor",))
    total = Decimal("0.00")
    for line in lines:
        label = (line.get("label") or "").lower()
        if any(all(keyword in label for keyword in keywords) for keywords in fixed_asset_keywords):
            amounts = line.get("amounts") or []
            if amounts:
                total += _money(amounts[-1])
    return abs(_money(total))


async def _me_xero_optional_get(connection_row: dict, url: str, params: dict | None = None) -> dict:
    try:
        return await xero_api_get(connection_row, url, params=params)
    except Exception as exc:
        return {"_error": _sync_error_message(exc), "_type": exc.__class__.__name__}


def _xero_connection_scope_set(connection_row: dict | None) -> set[str]:
    if not isinstance(connection_row, dict):
        return set()
    raw_scope_value = connection_row.get("scope")
    if isinstance(raw_scope_value, (list, tuple, set)):
        return {
            str(item).strip().lower()
            for item in raw_scope_value
            if str(item).strip()
        }
    raw_scope = str(raw_scope_value or "").strip()
    if not raw_scope or raw_scope.lower() in {"none", "null"}:
        return set()
    return {
        item.strip().lower()
        for item in re.split(r"[\s,]+", raw_scope)
        if item.strip()
    }


def _xero_connection_has_reports_scope(connection_row: dict | None) -> bool:
    scopes = _xero_connection_scope_set(connection_row)
    report_scopes = {
        "accounting.reports.read",
        "accounting.reports.aged.read",
        "accounting.reports.balancesheet.read",
        "accounting.reports.banksummary.read",
        "accounting.reports.budgetsummary.read",
        "accounting.reports.executivesummary.read",
        "accounting.reports.profitandloss.read",
        "accounting.reports.trialbalance.read",
        "accounting.reports.taxreports.read",
    }
    return any(scope in scopes for scope in report_scopes)


def _xero_connection_has_journal_scope(connection_row: dict | None) -> bool:
    scopes = _xero_connection_scope_set(connection_row)
    journal_scopes = {
        "accounting.journals.read",
        "accounting.journals",
        "accounting.transactions.read",
        "accounting.transactions",
        "accounting.manualjournals.read",
        "accounting.manualjournals",
    }
    return any(scope in scopes for scope in journal_scopes)


def _configured_xero_scope_requirements() -> tuple[bool, bool]:
    configured_scope_row = {"scope": get_settings().xero_scopes}
    configured_scopes = _xero_connection_scope_set(configured_scope_row)
    requires_reports = _xero_connection_has_reports_scope(configured_scope_row)
    requires_journals = any(
        scope in configured_scopes
        for scope in (
            "accounting.journals.read",
            "accounting.journals",
            "accounting.transactions",
            "accounting.transactions.read",
        )
    )
    return requires_reports, requires_journals


def _xero_connection_has_manual_journal_scope(connection_row: dict | None) -> bool:
    scopes = _xero_connection_scope_set(connection_row)
    return any(
        scope in scopes
        for scope in ("accounting.manualjournals.read", "accounting.manualjournals", "accounting.transactions.read", "accounting.transactions")
    )


XERO_SCOPE_AUDIT_BROAD_SCOPES = {
    "accounting.transactions",
    "accounting.reports.read",
    "accounting.settings",
    "accounting.contacts",
}
XERO_SCOPE_BROAD_SCOPES_RETIREMENT_DATE = "2027-09-30"


def _xero_scope_audit_row(connection_row: dict | None, requires_reports: bool = True, requires_journals: bool = True) -> dict:
    if not isinstance(connection_row, dict):
        missing_default_scopes: list[str] = []
        if requires_reports:
            missing_default_scopes.append("accounting.reports.balancesheet.read")
        if requires_journals:
            missing_default_scopes.append("accounting.journals.read")
        return {
            "tenantId": "",
            "tenantName": "",
            "tenantType": "",
            "connectionCreatedAt": "",
            "connectionUpdatedAt": "",
            "scopeRaw": "",
            "scopes": [],
            "hasReportsScope": False,
            "hasJournalScope": False,
            "missingRequiredScopes": missing_default_scopes,
            "usesBroadScopes": False,
            "broadScopesDetected": [],
            "requiresReconnect": bool(missing_default_scopes),
        }
    raw_scope_value = connection_row.get("scope")
    if isinstance(raw_scope_value, (list, tuple, set)):
        scope_raw = " ".join(str(item).strip() for item in raw_scope_value if str(item).strip())
    else:
        scope_raw = str(raw_scope_value or "").strip()
    scopes = sorted(_xero_connection_scope_set(connection_row))
    has_reports_scope = _xero_connection_has_reports_scope(connection_row)
    has_journal_scope = _xero_connection_has_journal_scope(connection_row)
    missing_required_scopes: list[str] = []
    if requires_reports and not has_reports_scope:
        missing_required_scopes.append("accounting.reports.balancesheet.read")
    if requires_journals and not has_journal_scope:
        missing_required_scopes.append("accounting.journals.read")
    broad_scopes_detected = sorted(scope for scope in scopes if scope in XERO_SCOPE_AUDIT_BROAD_SCOPES)
    return {
        "tenantId": str(connection_row.get("tenant_id") or ""),
        "tenantName": str(connection_row.get("tenant_name") or ""),
        "tenantType": str(connection_row.get("tenant_type") or ""),
        "connectionCreatedAt": _iso(connection_row.get("created_at")) or "",
        "connectionUpdatedAt": _iso(connection_row.get("updated_at")) or "",
        "scopeRaw": scope_raw,
        "scopes": scopes,
        "hasReportsScope": has_reports_scope,
        "hasJournalScope": has_journal_scope,
        "missingRequiredScopes": missing_required_scopes,
        "usesBroadScopes": bool(broad_scopes_detected),
        "broadScopesDetected": broad_scopes_detected,
        "requiresReconnect": bool(missing_required_scopes),
    }


def xero_scope_audit_payload(user: dict, tenant_id: str | None = None) -> dict:
    requested_tenant_id = str(tenant_id or "").strip()
    rows = list_xero_connections_for_user(user["id"], include_fallback=False)
    configured_requires_reports, configured_requires_journals = _configured_xero_scope_requirements()
    audits = [
        _xero_scope_audit_row(
            row,
            requires_reports=configured_requires_reports,
            requires_journals=configured_requires_journals,
        )
        for row in rows
    ]
    if requested_tenant_id:
        audits = [row for row in audits if str(row.get("tenantId") or "").strip() == requested_tenant_id]
    configured_scopes = sorted(_xero_connection_scope_set({"scope": get_settings().xero_scopes}))
    configured_has_reports_scope = _xero_connection_has_reports_scope({"scope": get_settings().xero_scopes})
    configured_has_journal_scope = _xero_connection_has_journal_scope({"scope": get_settings().xero_scopes})
    return {
        "generatedAt": _iso(utcnow()),
        "connections": audits,
        "summary": {
            "connectionsChecked": len(audits),
            "connectionsMissingRequiredScopes": sum(1 for row in audits if row.get("requiresReconnect")),
            "connectionsUsingBroadScopes": sum(1 for row in audits if row.get("usesBroadScopes")),
        },
        "configured": {
            "scopeRaw": str(get_settings().xero_scopes or "").strip(),
            "scopes": configured_scopes,
            "hasReportsScope": configured_has_reports_scope,
            "hasJournalScope": configured_has_journal_scope,
        },
        "migration": {
            "broadScopesRetireOn": XERO_SCOPE_BROAD_SCOPES_RETIREMENT_DATE,
            "note": (
                "Xero broad accounting scopes still work for existing apps, but granular scopes should be used before "
                "September 30, 2027."
            ),
        },
    }


def _update_me_report_sync_run(sync_run_id: str, **fields) -> None:
    if not fields:
        return
    assignments = ", ".join(f"{key} = %s" for key in fields)
    values = list(fields.values())
    values.append(sync_run_id)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(f"UPDATE me_report_sync_runs SET {assignments} WHERE id = %s", values)
        connection.commit()


def _me_report_sync_period_from_payload(payload: dict | None = None) -> tuple[date, date]:
    safe_payload = payload if isinstance(payload, dict) else {}
    today = utcnow().date()
    period_end_raw = str(safe_payload.get("periodEndDate") or safe_payload.get("periodEnd") or "").strip()
    period_start_raw = str(safe_payload.get("periodStartDate") or safe_payload.get("periodStart") or "").strip()
    period_end = _parse_optional_iso_date(period_end_raw) if period_end_raw else None
    period_start = _parse_optional_iso_date(period_start_raw) if period_start_raw else None
    period_end = period_end or today
    if period_end > today:
        period_end = today
    period_start = period_start or date(period_end.year, period_end.month, 1)
    if period_start > period_end:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Sync period start cannot be after period end.")
    return period_start, period_end


def request_me_report_sync_run(user: dict, client_id: str, payload: dict | None = None) -> tuple[dict, bool]:
    client = _me_report_client_row(user, client_id)
    if client.get("xero_connection_status") != "connected":
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Connect this ME Report client to Xero before syncing.")
    period_start, period_end = _me_report_sync_period_from_payload(payload)
    period_label = period_end.strftime("%B %Y")
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM me_report_sync_runs
                WHERE user_id = %s
                  AND client_id = %s
                  AND status IN ('queued', 'running')
                ORDER BY COALESCE(heartbeat_at, started_at, created_at) DESC
                LIMIT 1
                """,
                (user["id"], client_id),
            )
            active = cursor.fetchone()
            if active:
                connection.commit()
                return active, False
            cursor.execute(
                """
                INSERT INTO me_report_sync_runs (
                    client_id, user_id, period_start, period_end, status, current_step,
                    summary, progress, heartbeat_at, created_at
                )
                VALUES (%s, %s, %s, %s, 'queued', 'Queued', %s, 2, %s, %s)
                RETURNING *
                """,
                (
                    client_id,
                    user["id"],
                    period_start,
                    period_end,
                    f"ME Report Xero sync queued for {period_label}.",
                    utcnow(),
                    utcnow(),
                ),
            )
            row = cursor.fetchone()
        connection.commit()
    return row, True


def get_me_report_sync_run(user: dict, sync_run_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM me_report_sync_runs WHERE id = %s AND user_id = %s", (sync_run_id, user["id"]))
            row = cursor.fetchone()
        connection.commit()
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report sync run not found.")
    return row


def active_me_report_sync_run_for_user(user: dict | None) -> dict | None:
    if not user or not user.get("id"):
        return None
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM me_report_sync_runs
                WHERE user_id = %s
                  AND status IN ('queued', 'running')
                ORDER BY COALESCE(heartbeat_at, started_at, created_at) DESC
                LIMIT 1
                """,
                (user["id"],),
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def serialize_me_report_sync_run(row: dict | None) -> dict | None:
    return _serialize_me_report_sync_run(row)


def run_me_report_sync_job(user: dict, sync_run_id: str) -> None:
    try:
        asyncio.run(run_me_report_sync(user, sync_run_id))
    except Exception as exc:
        logger.exception("Background ME Report sync failed")
        _update_me_report_sync_run(
            sync_run_id,
            status="failed",
            current_step="ME Report sync failed",
            summary="ME Report sync failed before it could complete.",
            error_message=_sync_error_message(exc),
            progress=100,
            heartbeat_at=utcnow(),
            completed_at=utcnow(),
        )


async def run_me_report_sync(user: dict, sync_run_id: str) -> dict:
    sync_run = get_me_report_sync_run(user, sync_run_id)
    client = _me_report_client_row(user, str(sync_run["client_id"]))
    connection_row = _me_report_xero_connection(user, client)
    today = utcnow().date()
    period_start = sync_run.get("period_start")
    period_end = sync_run.get("period_end")
    if isinstance(period_start, datetime):
        period_start = period_start.date()
    if isinstance(period_end, datetime):
        period_end = period_end.date()
    if not isinstance(period_end, date):
        period_end = today
    if not isinstance(period_start, date):
        period_start = date(period_end.year, period_end.month, 1)
    now = utcnow()
    _update_me_report_sync_run(
        sync_run_id,
        status="running",
        current_step="Syncing chart of accounts",
        summary="Reading account codes and names from Xero.",
        progress=8,
        started_at=now,
        heartbeat_at=now,
    )
    accounts_payload = await xero_api_get(connection_row, "https://api.xero.com/api.xro/2.0/Accounts")
    accounts = accounts_payload.get("Accounts") or accounts_payload.get("accounts") or []
    with get_connection() as db:
        with db.cursor() as cursor:
            for account in accounts:
                suggestion = _me_treatment_for_account(account)
                xero_account_id = str(
                    account.get("AccountID")
                    or account.get("accountID")
                    or account.get("AccountId")
                    or account.get("id")
                    or ""
                ).strip()
                account_code = str(account.get("Code") or account.get("code") or "").strip()
                account_name = str(account.get("Name") or account.get("name") or "").strip()
                account_type = str(account.get("Type") or account.get("type") or "").strip()
                suggested_treatment = str(suggestion.get("suggestedTreatment") or "").strip()
                tax_treatment = str(suggestion.get("taxTreatment") or "").strip()
                category = str(suggestion.get("category") or "").strip()
                confidence = int(suggestion.get("confidence") or 0)
                review_required = bool(suggestion.get("reviewRequired"))
                reason = str(suggestion.get("reason") or "").strip()
                cursor.execute(
                    """
                    INSERT INTO me_report_account_mappings (
                        client_id, xero_account_id, account_code, account_name,
                        account_type, suggested_treatment, tax_treatment, category,
                        confidence, review_required, status, reason, created_at, updated_at
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'suggested', %s, %s, %s)
                    ON CONFLICT (client_id, account_code) DO UPDATE
                    SET xero_account_id = EXCLUDED.xero_account_id,
                        account_name = EXCLUDED.account_name,
                        account_type = EXCLUDED.account_type,
                        suggested_treatment = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.suggested_treatment
                            ELSE EXCLUDED.suggested_treatment
                        END,
                        tax_treatment = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.tax_treatment
                            ELSE EXCLUDED.tax_treatment
                        END,
                        category = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.category
                            ELSE EXCLUDED.category
                        END,
                        confidence = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.confidence
                            ELSE EXCLUDED.confidence
                        END,
                        review_required = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.review_required
                            ELSE EXCLUDED.review_required
                        END,
                        reason = CASE
                            WHEN me_report_account_mappings.status IN ('approved', 'amended') THEN me_report_account_mappings.reason
                            ELSE EXCLUDED.reason
                        END,
                        updated_at = EXCLUDED.updated_at
                    """,
                    (
                        client["id"],
                        xero_account_id,
                        account_code,
                        account_name,
                        account_type,
                        suggested_treatment,
                        tax_treatment,
                        category,
                        confidence,
                        review_required,
                        reason,
                        utcnow(),
                        utcnow(),
                    ),
                )
        db.commit()

    _update_me_report_sync_run(
        sync_run_id,
        current_step="Fetching financial reports",
        summary="Reading profit and loss, balance sheet, trial balance, bank transactions and journals.",
        progress=32,
        records_synced=len(accounts),
        heartbeat_at=utcnow(),
    )
    report_params = {"fromDate": period_start.isoformat(), "toDate": period_end.isoformat()}
    last_12_months_start = period_end - timedelta(days=365)
    year_end_month = int(client.get("year_end_month") or 3)
    ytd_start_month = 1 if year_end_month == 12 else year_end_month + 1
    ytd_year = period_end.year if period_end.month >= ytd_start_month else period_end.year - 1
    ytd_start = date(ytd_year, ytd_start_month, 1)
    profit_loss_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss", report_params)
    ytd_profit_loss_payload = await _me_xero_optional_get(
        connection_row,
        "https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss",
        {"fromDate": ytd_start.isoformat(), "toDate": period_end.isoformat()},
    )
    annual_profit_loss_payload = await _me_xero_optional_get(
        connection_row,
        "https://api.xero.com/api.xro/2.0/Reports/ProfitAndLoss",
        {"fromDate": last_12_months_start.isoformat(), "toDate": period_end.isoformat()},
    )
    balance_sheet_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/api.xro/2.0/Reports/BalanceSheet", {"date": period_end.isoformat()})
    trial_balance_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/api.xro/2.0/Reports/TrialBalance", {"date": period_end.isoformat()})
    bank_transactions_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/api.xro/2.0/BankTransactions", {"page": 1, "pageSize": 100})
    journals_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/api.xro/2.0/Journals", {"offset": 0})
    fixed_assets_payload = await _me_xero_optional_get(connection_row, "https://api.xero.com/assets.xro/1.0/Assets", {"page": 1})
    try:
        contacts = await fetch_paginated_collection(connection_row, CONTACTS_URL, "Contacts", max_pages=10)
        contacts_payload = {"Contacts": contacts}
    except Exception as exc:
        contacts = []
        contacts_payload = {"_error": _sync_error_message(exc)}
    try:
        outstanding_bills = await fetch_paginated_collection(
            connection_row,
            INVOICES_URL,
            "Invoices",
            params={"where": 'Type=="ACCPAY"&&Status!="VOIDED"&&Status!="DELETED"&&Status!="PAID"'},
            max_pages=5,
        )
        outstanding_bills_payload = {"Invoices": outstanding_bills}
    except Exception as exc:
        outstanding_bills = []
        outstanding_bills_payload = {"_error": _sync_error_message(exc)}

    _update_me_report_sync_run(
        sync_run_id,
        current_step="Calculating month-end review",
        summary="Applying Jaccountancy tax rules for CT estimate, dividend capacity and DLA risk.",
        progress=68,
        records_synced=len(accounts) + len(bank_transactions_payload.get("BankTransactions") or []) + len(contacts),
        heartbeat_at=utcnow(),
    )
    with get_connection() as db:
        with db.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM me_report_account_mappings
                WHERE client_id = %s
                ORDER BY account_code ASC
                """,
                (client["id"],),
            )
            mapping_rows = cursor.fetchall()
            cursor.execute(
                """
                SELECT summary, created_at
                FROM me_report_reviews
                WHERE client_id = %s
                ORDER BY created_at DESC
                LIMIT 6
                """,
                (client["id"],),
            )
            previous_review_rows = cursor.fetchall()
        db.commit()

    pl_lines = _xero_report_lines(profit_loss_payload)
    ytd_pl_lines = _xero_report_lines(ytd_profit_loss_payload)
    annual_pl_lines = _xero_report_lines(annual_profit_loss_payload)
    bs_lines = _xero_report_lines(balance_sheet_payload)
    monthly_sales = _report_amount(pl_lines, ("sales",), _report_amount(pl_lines, ("income",)))
    ytd_sales = _report_amount(ytd_pl_lines, ("sales",), _report_amount(ytd_pl_lines, ("income",), monthly_sales))
    annual_turnover = _report_amount(annual_pl_lines, ("sales",), _report_amount(annual_pl_lines, ("income",)))
    monthly_profit = _report_amount(pl_lines, ("net profit",), _report_amount(pl_lines, ("profit",)))
    ytd_profit = _report_amount(ytd_pl_lines, ("net profit",), _report_amount(ytd_pl_lines, ("profit",), monthly_profit))
    ytd_expenses = max(Decimal("0.00"), ytd_sales - ytd_profit)
    monthly_expenses = max(Decimal("0.00"), monthly_sales - monthly_profit)
    retained_earnings = _report_amount(bs_lines, ("retained",))
    dla_balance = _report_amount(bs_lines, ("director", "loan"))
    dividends_taken = abs(_report_amount(bs_lines, ("dividend",), _report_amount(ytd_pl_lines, ("dividend",), _report_amount(pl_lines, ("dividend",)))))
    disallowable_addbacks = sum(
        Decimal("100.00")
        for row in mapping_rows
        if row.get("category") in ("Client entertaining", "Fines and penalties", "Depreciation", "Non-business expenses", "Private use items")
    )
    capital_allowance_review = sum(1 for row in mapping_rows if row.get("category") in ("Computer equipment", "Plant and machinery", "Office equipment", "Assets needing review"))
    brought_forward_trading_loss = _money(client.get("brought_forward_trading_loss"))
    taxable_profit_before_losses = max(Decimal("0.00"), _money(ytd_profit + disallowable_addbacks))
    trading_loss_relief_used = min(brought_forward_trading_loss, taxable_profit_before_losses)
    taxable_profit = max(Decimal("0.00"), _money(taxable_profit_before_losses - trading_loss_relief_used))
    estimated_ct, effective_rate, ct_rate_band, corporation_tax_breakdown = _me_report_corporation_tax_detail(taxable_profit)
    post_tax_profit = _money(ytd_profit - estimated_ct)
    period_end_distributable_reserves = _money(retained_earnings + post_tax_profit - dividends_taken)
    dividend_capacity = max(Decimal("0.00"), period_end_distributable_reserves)
    total_extractable = _money(max(dla_balance, Decimal("0.00")) + dividend_capacity)
    tax_steps = [
        _me_report_step("Profit before tax YTD", ytd_profit, "Start", "Xero Profit and Loss - YTD"),
        _me_report_step("Estimated disallowable add-backs", disallowable_addbacks, "Add back", "Account treatment review"),
        *([
            _me_report_step("Brought-forward trading loss utilised", -trading_loss_relief_used, "Deduct", "Stored client setting")
        ] if brought_forward_trading_loss else []),
        _me_report_step("Estimated taxable profit YTD", taxable_profit, "Result", "Calculated"),
        _me_report_step("Corporation tax estimate", estimated_ct, ct_rate_band, "Calculated using current UK CT thresholds"),
    ]
    dividend_steps = [
        _me_report_step("Opening retained reserves", retained_earnings, "Start", "Xero Balance Sheet"),
        _me_report_step("YTD profit before tax", ytd_profit, "Add", "Xero Profit and Loss - YTD"),
        _me_report_step("Estimated corporation tax provision", -estimated_ct, "Deduct", "CT estimate"),
        _me_report_step("Post-tax YTD earnings", post_tax_profit, "Subtotal", "Calculated"),
        _me_report_step("Dividends declared YTD", -dividends_taken, "Deduct", "Xero Balance Sheet / Profit and Loss"),
        _me_report_step("Period-end distributable reserves", period_end_distributable_reserves, "Result", "Calculated"),
        _me_report_step("Further dividend availability", dividend_capacity, "Available", "Calculated"),
    ]
    low_confidence = [row for row in mapping_rows if int(row.get("confidence") or 0) < 80 or row.get("review_required")]
    reports_with_errors = [
        ("Profit and loss", profit_loss_payload.get("_error")),
        ("Year-to-date profit and loss", ytd_profit_loss_payload.get("_error")),
        ("12-month turnover report", annual_profit_loss_payload.get("_error")),
        ("Balance sheet", balance_sheet_payload.get("_error")),
        ("Trial balance", trial_balance_payload.get("_error")),
        ("Bank transactions", bank_transactions_payload.get("_error")),
        ("Journals", journals_payload.get("_error")),
        ("Contacts", contacts_payload.get("_error")),
        ("Accounts payable bills", outstanding_bills_payload.get("_error")),
    ]
    previous_vat_breach_at = None
    for previous_review in previous_review_rows:
        previous_summary = previous_review.get("summary") or {}
        if isinstance(previous_summary, str):
            try:
                previous_summary = json.loads(previous_summary)
            except ValueError:
                previous_summary = {}
        breach_value = previous_summary.get("vatThresholdFirstBreachedAt")
        if breach_value:
            previous_vat_breach_at = _parse_optional_iso_date(breach_value)
            break
    vat_threshold = Decimal("90000.00")
    vat_threshold_exceeded = annual_turnover > vat_threshold
    vat_registered_confirmed = bool(client.get("vat_registered_confirmed"))
    vat_threshold_first_breached_at = previous_vat_breach_at if vat_threshold_exceeded and previous_vat_breach_at else (period_end if vat_threshold_exceeded else previous_vat_breach_at)
    vat_warning_visible = bool(vat_threshold_exceeded or (vat_threshold_first_breached_at and (period_end - vat_threshold_first_breached_at).days <= 62)) and not vat_registered_confirmed
    asset_register_total = _asset_register_total(fixed_assets_payload)
    balance_sheet_fixed_assets = _balance_sheet_fixed_asset_total(bs_lines)
    fixed_asset_difference = None if asset_register_total is None else _money(asset_register_total - balance_sheet_fixed_assets)
    duplicate_spend_candidates = _find_duplicate_spend_bill_candidates(bank_transactions_payload.get("BankTransactions") or [], outstanding_bills)
    duplicate_contact_candidates = _find_duplicate_contact_candidates(contacts)
    payroll_control_warnings = _me_report_trial_balance_payroll_control_warnings_from_report_payload(trial_balance_payload)
    open_exceptions = []
    for label, error_message in reports_with_errors:
        if error_message:
            open_exceptions.append({
                "severity": "amber" if label in ("Bank transactions", "Journals", "Fixed asset register", "Contacts", "Accounts payable bills") else "red",
                "title": f"{label} could not be read from Xero",
                "detail": error_message,
                "suggested_action": "Review Xero OAuth scopes and reconnect Xero if required.",
            })
    if vat_warning_visible:
        open_exceptions.append({
            "severity": "amber",
            "title": "VAT registration threshold review",
            "detail": (
                f"Xero shows estimated rolling 12-month turnover of £{_money(annual_turnover):,.2f}. "
                f"The VAT registration threshold is £{vat_threshold:,.2f}. "
                f"This warning remains visible for two months after the first breach date."
            ),
            "suggested_action": "Review VAT registration position, confirm taxable turnover, and document the client advice.",
        })
    if asset_register_total is None:
        open_exceptions.append({
            "severity": "amber",
            "title": "Fixed asset register could not be reconciled",
            "detail": fixed_assets_payload.get("_error") or "Xero fixed asset data was not returned.",
            "suggested_action": "Confirm fixed asset API access and compare the fixed asset register to the Xero balance sheet manually.",
        })
    elif abs(fixed_asset_difference or Decimal("0.00")) > Decimal("1.00"):
        open_exceptions.append({
            "severity": "amber",
            "title": "Fixed asset register does not match balance sheet",
            "detail": (
                f"AI-assisted matching found fixed asset register value £{_money(asset_register_total):,.2f} "
                f"versus balance sheet fixed asset accounts £{_money(balance_sheet_fixed_assets):,.2f}."
            ),
            "suggested_action": "Review fixed asset account mapping, depreciation postings and disposals before report approval.",
        })
    for candidate in duplicate_spend_candidates:
        open_exceptions.append({
            "severity": "red",
            "title": "Possible duplicate bill payment posting",
            "detail": (
                f"Spend money transaction {candidate['bankTransactionReference']} for £{_money(candidate['amount']):,.2f} "
                f"matches outstanding bill {candidate['billNumber']}."
            ),
            "suggested_action": "Review whether the spend money transaction should be removed and the payment allocated to the bill.",
        })
    for candidate in duplicate_contact_candidates:
        open_exceptions.append({
            "severity": "amber",
            "title": "Possible duplicate Xero contact",
            "detail": f"{candidate['keepName']} and {candidate['mergeName']} look like the same contact.",
            "suggested_action": "Use Merge contact after staff review to combine the duplicate contact into the selected primary contact in Xero.",
            "action_payload": {"type": "duplicate_contact", **candidate},
        })
    for warning in payroll_control_warnings[:20]:
        label = " ".join(
            part
            for part in [str(warning.get("accountCode") or "").strip(), str(warning.get("accountName") or "").strip()]
            if part
        ) or "Payroll control account"
        open_exceptions.append({
            "severity": "amber",
            "title": f"{warning.get('category') or 'Payroll payable'} balance outstanding",
            "detail": f"{label} has an outstanding balance of £{_money(warning.get('outstandingAmount')):,.2f}.",
            "suggested_action": "Review payroll/pension liability postings and clear or reclassify balances before submitting for manager review.",
        })
    for mapping in low_confidence[:20]:
        open_exceptions.append({
            "severity": "amber",
            "title": f"{mapping.get('account_name') or mapping.get('account_code')} needs mapping review",
            "detail": mapping.get("reason") or "AI/rules confidence is below the approval threshold.",
            "suggested_action": "Approve, amend or mark the account as needs review before issuing the month-end report.",
        })
    if dla_balance < Decimal("0.00"):
        open_exceptions.append({
            "severity": "red",
            "title": "Director loan account appears overdrawn",
            "detail": f"Closing DLA balance appears to be £{abs(dla_balance):,.2f} overdrawn.",
            "suggested_action": "Review possible s455 tax and dividend legality before report issue.",
        })
    if period_end_distributable_reserves < Decimal("0.00") and dividends_taken > 0:
        open_exceptions.append({
            "severity": "red",
            "title": "Possible illegal dividend risk",
            "detail": "Dividends appear to exceed estimated distributable reserves after corporation tax.",
            "suggested_action": "Accountant review required before client commentary is approved.",
        })
    if not any("corporation tax" in (row.get("account_name") or "").lower() for row in mapping_rows):
        open_exceptions.append({
            "severity": "amber",
            "title": "No corporation tax provision account identified",
            "detail": "The account mapping did not identify a corporation tax creditor account.",
            "suggested_action": "Confirm where the CT provision should be posted or tracked.",
        })
    traffic_light = "red" if any(item["severity"] == "red" for item in open_exceptions) else ("amber" if open_exceptions else "green")
    dla_status = "red" if dla_balance < 0 else ("amber" if dla_balance == 0 else "green")
    bank_transaction_rows = _me_report_bank_transaction_rows(bank_transactions_payload, period_start, period_end)
    trial_balance_accounts = _me_report_trial_balance_accounts_from_bank_transactions(bank_transaction_rows)
    unreconciled_transactions = _me_report_unreconciled_bank_transactions(bank_transaction_rows)
    contact_rows = [
        {
            "xeroContactId": str(item.get("ContactID") or item.get("contactID") or ""),
            "name": str(item.get("Name") or item.get("name") or ""),
            "email": str(item.get("EmailAddress") or item.get("emailAddress") or ""),
        }
        for item in contacts
        if isinstance(item, dict)
    ][:1000]
    summary = {
        "periodStart": period_start.isoformat(),
        "periodEnd": period_end.isoformat(),
        "monthlySales": float(_money(monthly_sales)),
        "monthlyExpenses": float(_money(monthly_expenses)),
        "monthlyProfit": float(_money(monthly_profit)),
        "yearToDateSales": float(_money(ytd_sales)),
        "yearToDateExpenses": float(_money(ytd_expenses)),
        "yearToDateProfit": float(_money(ytd_profit)),
        "rolling12MonthTurnover": float(_money(annual_turnover)),
        "vatThreshold": float(vat_threshold),
        "vatThresholdExceeded": vat_threshold_exceeded,
        "vatThresholdFirstBreachedAt": _iso(vat_threshold_first_breached_at) or "",
        "vatRegisteredConfirmed": vat_registered_confirmed,
        "vatWarningVisible": vat_warning_visible,
        "accountingProfit": float(_money(ytd_profit)),
        "taxAdjustments": float(_money(disallowable_addbacks)),
        "taxableProfitBeforeLosses": float(taxable_profit_before_losses),
        "broughtForwardTradingLoss": float(brought_forward_trading_loss),
        "tradingLossReliefUsed": float(trading_loss_relief_used),
        "estimatedTaxableProfit": float(_money(taxable_profit)),
        "estimatedCorporationTax": float(estimated_ct),
        "effectiveTaxRate": float(effective_rate),
        "corporationTaxRateBand": ct_rate_band,
        "taxProvisionRequired": float(estimated_ct),
        "openingRetainedReserves": float(_money(retained_earnings)),
        "currentYearEarnings": float(_money(post_tax_profit)),
        "periodEndDistributableReserves": float(_money(period_end_distributable_reserves)),
        "dividendsTaken": float(_money(dividends_taken)),
        "dividendCapacity": float(_money(dividend_capacity)),
        "directorLoanCreditBalance": float(_money(max(dla_balance, Decimal("0.00")))),
        "totalPotentialExtraction": float(total_extractable),
        "dlaBalance": float(_money(dla_balance)),
        "dlaStatus": dla_status,
        "capitalAllowanceReviewCount": capital_allowance_review,
        "fixedAssetRegisterTotal": float(_money(asset_register_total or 0)),
        "balanceSheetFixedAssetTotal": float(_money(balance_sheet_fixed_assets)),
        "fixedAssetDifference": float(_money(fixed_asset_difference or 0)),
        "duplicateSpendBillCount": len(duplicate_spend_candidates),
        "duplicateContactCount": len(duplicate_contact_candidates),
        "payrollControlWarnings": payroll_control_warnings,
        "trialBalanceAccounts": trial_balance_accounts,
        "unreconciledTransactions": unreconciled_transactions,
        "unreconciledBankTransactionCount": len(unreconciled_transactions),
        "contacts": contact_rows,
        "xeroContacts": contact_rows,
        "mappingReviewCount": len(low_confidence),
        "exceptionCount": len(open_exceptions),
        "trafficLight": traffic_light,
        "corporationTaxBreakdown": corporation_tax_breakdown,
        "taxCalculationSteps": tax_steps,
        "dividendCalculationSteps": dividend_steps,
        "commentary": (
            f"This month shows estimated profit of £{_money(monthly_profit):,.2f}. "
            f"Year-to-date profit is £{_money(ytd_profit):,.2f}. "
            f"{'Brought-forward trading loss relief used is £' + format(trading_loss_relief_used, ',.2f') + '. ' if brought_forward_trading_loss else ''}"
            f"Estimated corporation tax is £{estimated_ct:,.2f}, subject to accountant review and final year-end adjustments. "
            f"Rolling 12-month turnover is £{_money(annual_turnover):,.2f}, "
            f"{'above' if vat_threshold_exceeded else 'below'} the £{vat_threshold:,.0f} VAT threshold. "
            f"The director loan account is {'in credit' if dla_balance >= 0 else 'overdrawn'}, and DLA repayment should be considered before dividends where credit is available."
        ),
        "warnings": [
            f"{item.get('category') or 'Payroll payable'} balance outstanding: £{_money(item.get('outstandingAmount')):,.2f} in {str(item.get('accountName') or item.get('accountCode') or 'payroll control account')}."
            for item in payroll_control_warnings
        ],
    }
    raw_payload = {
        "accounts": accounts,
        "profitAndLoss": profit_loss_payload,
        "yearToDateProfitAndLoss": ytd_profit_loss_payload,
        "annualProfitAndLoss": annual_profit_loss_payload,
        "balanceSheet": balance_sheet_payload,
        "trialBalance": trial_balance_payload,
        "bankTransactions": bank_transactions_payload,
        "journals": journals_payload,
        "fixedAssets": fixed_assets_payload,
        "contacts": contacts_payload,
        "outstandingBills": outstanding_bills_payload,
    }
    with get_connection() as db:
        with db.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO me_report_reviews (
                    client_id, period_start, period_end, status, traffic_light,
                    summary, raw_payload, created_by_user_id, created_at, updated_at
                )
                VALUES (%s, %s, %s, 'calculated', %s, %s::jsonb, %s::jsonb, %s, %s, %s)
                RETURNING id
                """,
                (
                    client["id"],
                    period_start,
                    period_end,
                    traffic_light,
                    json.dumps(summary, default=_json_default),
                    json.dumps(raw_payload, default=_json_default),
                    user["id"],
                    utcnow(),
                    utcnow(),
                ),
            )
            review_id = cursor.fetchone()["id"]
            cursor.execute(
                "UPDATE me_report_exceptions SET status = 'superseded', updated_at = %s WHERE client_id = %s AND status = 'open'",
                (utcnow(), client["id"]),
            )
            for item in open_exceptions:
                cursor.execute(
                    """
                    INSERT INTO me_report_exceptions (
                        client_id, review_id, severity, title, detail,
                        suggested_action, action_payload, status, created_at, updated_at
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, 'open', %s, %s)
                    """,
                    (
                        client["id"],
                        review_id,
                        item["severity"],
                        item["title"],
                        item["detail"],
                        item["suggested_action"],
                        json.dumps(item.get("action_payload") or {}, default=_json_default),
                        utcnow(),
                        utcnow(),
                    ),
                )
            cursor.execute(
                """
                UPDATE me_report_clients
                SET last_sync_at = %s,
                    last_calculated_at = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (utcnow(), utcnow(), utcnow(), client["id"]),
            )
        db.commit()
    _update_me_report_sync_run(
        sync_run_id,
        status="completed",
        current_step="ME Report calculation complete",
        summary=f"Calculated {client.get('client_name') or 'client'}: {traffic_light.upper()} status, {len(open_exceptions)} review point(s).",
        progress=100,
        records_synced=len(accounts),
        heartbeat_at=utcnow(),
        completed_at=utcnow(),
    )
    record_audit_event(
        "me_report_review",
        str(review_id),
        "me_report.review_calculated",
        {"client_id": str(client["id"]), "traffic_light": traffic_light, "exception_count": len(open_exceptions)},
        user["id"],
    )
    return me_report_payload(user)


def update_me_report_mapping(user: dict, mapping_id: str, payload: dict) -> dict:
    status_value = str(payload.get("status") or "approved").strip() or "approved"
    note = str(payload.get("note") or "").strip()
    suggested_treatment = str(payload.get("suggestedTreatment") or "").strip()
    tax_treatment = str(payload.get("taxTreatment") or "").strip()
    category = str(payload.get("category") or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT mappings.*, clients.user_id
                FROM me_report_account_mappings AS mappings
                JOIN me_report_clients AS clients ON clients.id = mappings.client_id
                WHERE mappings.id = %s
                  AND clients.user_id = %s
                """,
                (mapping_id, user["id"]),
            )
            mapping = cursor.fetchone()
            if not mapping:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report account mapping not found.")
            cursor.execute(
                """
                UPDATE me_report_account_mappings
                SET status = %s,
                    note = %s,
                    suggested_treatment = COALESCE(NULLIF(%s, ''), suggested_treatment),
                    tax_treatment = COALESCE(NULLIF(%s, ''), tax_treatment),
                    category = COALESCE(NULLIF(%s, ''), category),
                    review_required = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (status_value, note, suggested_treatment, tax_treatment, category, status_value != "approved", utcnow(), mapping_id),
            )
        connection.commit()
    record_audit_event("me_report_mapping", mapping_id, "me_report.mapping_updated", {"status": status_value, "note": note}, user["id"])
    return me_report_payload(user)


def update_me_report_exception(user: dict, exception_id: str, payload: dict) -> dict:
    status_value = str(payload.get("status") or "resolved").strip() or "resolved"
    note = str(payload.get("note") or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT exceptions.*, clients.user_id
                FROM me_report_exceptions AS exceptions
                JOIN me_report_clients AS clients ON clients.id = exceptions.client_id
                WHERE exceptions.id = %s
                  AND clients.user_id = %s
                """,
                (exception_id, user["id"]),
            )
            row = cursor.fetchone()
            if not row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report exception not found.")
            cursor.execute(
                """
                UPDATE me_report_exceptions
                SET status = %s,
                    note = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (status_value, note, utcnow(), exception_id),
            )
        connection.commit()
    record_audit_event("me_report_exception", exception_id, "me_report.exception_updated", {"status": status_value, "note": note}, user["id"])
    return me_report_payload(user)


async def merge_me_report_duplicate_contact(user: dict, exception_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT exceptions.*, clients.xero_connection_id, clients.user_id
                FROM me_report_exceptions AS exceptions
                JOIN me_report_clients AS clients ON clients.id = exceptions.client_id
                WHERE exceptions.id = %s
                  AND clients.user_id = %s
                """,
                (exception_id, user["id"]),
            )
            exception = cursor.fetchone()
        connection.commit()
    if not exception:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="ME Report duplicate contact exception not found.")
    action_payload = exception.get("action_payload") or {}
    if isinstance(action_payload, str):
        try:
            action_payload = json.loads(action_payload)
        except ValueError:
            action_payload = {}
    if action_payload.get("type") != "duplicate_contact":
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="This ME Report exception is not a duplicate contact merge action.")
    keep_contact_id = str(action_payload.get("keepContactId") or "").strip()
    merge_contact_id = str(action_payload.get("mergeContactId") or "").strip()
    if not keep_contact_id or not merge_contact_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Duplicate contact exception is missing Xero contact ids.")
    connection_row = _me_report_xero_connection(user, {"xero_connection_id": exception.get("xero_connection_id")})
    await merge_contacts(connection_row, keep_contact_id, merge_contact_id)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE me_report_exceptions
                SET status = 'resolved',
                    note = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (
                    f"Merged {action_payload.get('mergeName') or merge_contact_id} into {action_payload.get('keepName') or keep_contact_id} in Xero.",
                    utcnow(),
                    exception_id,
                ),
            )
        connection.commit()
    record_audit_event("me_report_exception", exception_id, "me_report.contact_merged", action_payload, user["id"])
    return me_report_payload(user)


def _me_report_xero_invoice(payload: dict) -> dict:
    if not isinstance(payload, dict):
        return {}
    invoices = payload.get("Invoices") or payload.get("invoices") or []
    if isinstance(invoices, list) and invoices:
        first = invoices[0]
        return first if isinstance(first, dict) else {}
    invoice = payload.get("Invoice") or payload.get("invoice")
    return invoice if isinstance(invoice, dict) else {}


def _me_report_xero_bank_transaction(payload: dict) -> dict:
    if not isinstance(payload, dict):
        return {}
    rows = payload.get("BankTransactions") or payload.get("bankTransactions") or []
    if isinstance(rows, list) and rows:
        first = rows[0]
        return first if isinstance(first, dict) else {}
    row = payload.get("BankTransaction") or payload.get("bankTransaction")
    return row if isinstance(row, dict) else {}


def _me_report_director_loan_account_code_for_client(client_id: str) -> str:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT account_code, account_name, category, suggested_treatment, confidence
                FROM me_report_account_mappings
                WHERE client_id = %s
                ORDER BY confidence DESC NULLS LAST, updated_at DESC
                """,
                (client_id,),
            )
            rows = cursor.fetchall()
        connection.commit()
    for row in rows:
        category = str(row.get("category") or "").lower()
        treatment = str(row.get("suggested_treatment") or "").lower()
        account_name = str(row.get("account_name") or "").lower()
        if (
            "director loan" in category
            or "director loan" in treatment
            or ("director" in account_name and "loan" in account_name)
        ):
            code = str(row.get("account_code") or "").strip()
            if code:
                return code
    return ""


async def merge_me_report_contacts(user: dict, client_id: str, payload: dict) -> dict:
    client = _me_report_client_row(user, client_id)
    keep_contact_id = str(
        payload.get("primaryContactId")
        or payload.get("keepContactId")
        or payload.get("keep_contact_id")
        or ""
    ).strip()
    merge_contact_id = str(
        payload.get("duplicateContactId")
        or payload.get("mergeContactId")
        or payload.get("merge_contact_id")
        or ""
    ).strip()
    if not keep_contact_id or not merge_contact_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Both primaryContactId and duplicateContactId are required.")
    if keep_contact_id == merge_contact_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Primary and duplicate contact ids cannot be the same.")
    connection_row = _me_report_xero_connection(user, client)
    await merge_contacts(connection_row, keep_contact_id, merge_contact_id)
    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.contacts_merged",
        {"primaryContactId": keep_contact_id, "duplicateContactId": merge_contact_id},
        user["id"],
    )
    return me_report_payload(user)


async def rename_me_report_nominal_account(user: dict, client_id: str, payload: dict) -> dict:
    client = _me_report_client_row(user, client_id)
    corrected_name = str(payload.get("correctedName") or payload.get("newName") or "").strip()
    account_id = str(payload.get("accountId") or payload.get("accountID") or "").strip()
    account_code = str(payload.get("accountCode") or "").strip()
    if not corrected_name:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="correctedName is required.")
    if not account_id and not account_code:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Provide accountId or accountCode.")

    connection_row = _me_report_xero_connection(user, client)
    account_payload = {}
    if account_id:
        account_payload = await xero_api_get(connection_row, f"{ACCOUNTS_URL}/{account_id}")
    elif account_code:
        safe_code = account_code.replace('"', "").strip()
        account_payload = await xero_api_get(connection_row, ACCOUNTS_URL, params={"where": f'Code=="{safe_code}"'})

    accounts = account_payload.get("Accounts") if isinstance(account_payload, dict) else []
    if not isinstance(accounts, list):
        accounts = []
    account = None
    if account_id:
        account = next((row for row in accounts if str(row.get("AccountID") or "").strip() == account_id), None)
    if account is None and account_code:
        account = next((row for row in accounts if str(row.get("Code") or "").strip().lower() == account_code.lower()), None)
    if account is None and accounts:
        account = accounts[0]
    if not account:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Nominal account was not found in Xero.")

    resolved_account_id = str(account.get("AccountID") or account_id or "").strip()
    resolved_account_code = str(account.get("Code") or account_code or "").strip()
    if not resolved_account_id or not resolved_account_code:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Unable to resolve target account details.")

    refreshed_connection = await refresh_connection(connection_row["id"])
    request_payload = {
        "Accounts": [{
            "AccountID": resolved_account_id,
            "Code": resolved_account_code,
            "Name": corrected_name,
        }]
    }
    async with httpx.AsyncClient(timeout=45.0) as http_client:
        response = await http_client.post(
            ACCOUNTS_URL,
            headers={
                "Authorization": f'Bearer {refreshed_connection["access_token"]}',
                "xero-tenant-id": refreshed_connection["tenant_id"],
                "Accept": "application/json",
                "Content-Type": "application/json",
                "Idempotency-Key": str(uuid4()),
            },
            json=request_payload,
        )
    if response.is_error:
        detail_text = ""
        try:
            detail_json = response.json()
            detail_text = detail_json.get("Detail") or detail_json.get("detail") or ""
        except ValueError:
            detail_text = str(response.text or "")[:500]
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail=detail_text or "Xero rejected the nominal account rename request.",
        )

    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.nominal_account_renamed",
        {
            "accountId": resolved_account_id,
            "accountCode": resolved_account_code,
            "correctedName": corrected_name,
        },
        user["id"],
    )
    return me_report_payload(user)


async def delete_me_report_draft_sales_invoice(user: dict, client_id: str, invoice_id: str) -> dict:
    client = _me_report_client_row(user, client_id)
    invoice_id = str(invoice_id or "").strip()
    if not invoice_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invoice id is required.")
    connection_row = _me_report_xero_connection(user, client)
    invoice_payload = await xero_api_get(connection_row, f"{INVOICES_URL}/{invoice_id}")
    invoice = _me_report_xero_invoice(invoice_payload)
    if not invoice:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Invoice not found in Xero.")
    invoice_type = str(invoice.get("Type") or "").upper()
    invoice_status = str(invoice.get("Status") or "").upper()
    if invoice_type != "ACCREC":
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Only sales invoices can be deleted from this action.")
    if invoice_status != "DRAFT":
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Only draft sales invoices can be deleted.")
    await update_invoice_status(connection_row, invoice_id, "DELETED")
    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.sales_invoice_deleted",
        {"invoiceId": invoice_id, "invoiceNumber": str(invoice.get("InvoiceNumber") or "")},
        user["id"],
    )
    return me_report_payload(user)


async def mark_me_report_purchases_paid_personally(user: dict, client_id: str, payload: dict) -> dict:
    client = _me_report_client_row(user, client_id)
    raw_ids = payload.get("invoiceIds") if isinstance(payload, dict) else []
    invoice_ids = []
    seen = set()
    for raw_id in raw_ids if isinstance(raw_ids, list) else []:
        invoice_id = str(raw_id or "").strip()
        if invoice_id and invoice_id not in seen:
            seen.add(invoice_id)
            invoice_ids.append(invoice_id)
    if not invoice_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Provide at least one purchase invoice id.")

    dla_account_code = _me_report_director_loan_account_code_for_client(str(client_id))
    if not dla_account_code:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No director loan nominal code is configured for this flow. Confirm a DLA account first.",
        )

    connection_row = _me_report_xero_connection(user, client)
    today = utcnow().date().isoformat()
    processed = []
    for invoice_id in invoice_ids:
        invoice_payload = await xero_api_get(connection_row, f"{INVOICES_URL}/{invoice_id}")
        invoice = _me_report_xero_invoice(invoice_payload)
        if not invoice:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"Purchase invoice {invoice_id} was not found in Xero.")
        invoice_type = str(invoice.get("Type") or "").upper()
        invoice_status = str(invoice.get("Status") or "").upper()
        if invoice_type != "ACCPAY":
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Invoice {invoice_id} is not a purchase invoice.")
        if invoice_status in {"PAID", "VOIDED", "DELETED"}:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Invoice {invoice_id} is not outstanding.")
        amount_due = abs(_money(invoice.get("AmountDue") if invoice.get("AmountDue") is not None else invoice.get("Total")))
        if amount_due <= Decimal("0.00"):
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Invoice {invoice_id} has no outstanding amount.")
        contact = invoice.get("Contact") or {}
        contact_id = str(contact.get("ContactID") or "").strip()
        if not contact_id:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Invoice {invoice_id} has no Xero contact id.")
        invoice_number = str(invoice.get("InvoiceNumber") or invoice_id).strip()
        currency_code = str(invoice.get("CurrencyCode") or "GBP").strip() or "GBP"
        credit_note_payload = {
            "Type": "ACCPAYCREDIT",
            "Contact": {"ContactID": contact_id},
            "Date": today,
            "LineAmountTypes": "NoTax",
            "Status": "AUTHORISED",
            "Reference": f"Director paid personally {invoice_number}",
            "LineItems": [
                {
                    "Description": (
                        f"Director paid personally for purchase invoice {invoice_number}. "
                        "Raised and allocated via Jenius Monthly Flows."
                    ),
                    "Quantity": 1,
                    "UnitAmount": float(amount_due),
                    "AccountCode": dla_account_code,
                    "TaxType": "NONE",
                }
            ],
            "CurrencyCode": currency_code,
        }
        credit_note_response = await create_credit_note(connection_row, credit_note_payload)
        created_credit_note = ((credit_note_response or {}).get("CreditNotes") or [{}])[0]
        credit_note_id = str(created_credit_note.get("CreditNoteID") or created_credit_note.get("ID") or "").strip()
        if not credit_note_id:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Xero did not return a credit note id for invoice {invoice_number}.")
        await allocate_credit_note(
            connection_row,
            credit_note_id,
            {
                "Invoice": {"InvoiceID": invoice_id},
                "Amount": float(amount_due),
                "Date": today,
            },
        )
        processed.append(
            {
                "invoiceId": invoice_id,
                "invoiceNumber": invoice_number,
                "creditNoteId": credit_note_id,
                "amount": float(amount_due),
            }
        )

    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.purchases_marked_paid_personally",
        {"count": len(processed), "invoiceIds": [row["invoiceId"] for row in processed], "dlaAccountCode": dla_account_code},
        user["id"],
    )
    return me_report_payload(user)


def _me_report_juk_invoice_text(value) -> str:
    return str(value or "").strip()


def _me_report_juk_invoice_key(value) -> str:
    text = re.sub(r"[^a-z0-9]+", "", str(value or "").lower())
    return text[:120]


def _me_report_juk_invoice_amount(payload: dict) -> Decimal:
    candidates = (
        payload.get("amount"),
        payload.get("total"),
        payload.get("total_amount"),
        payload.get("gross_amount"),
        payload.get("amount_due"),
        payload.get("balance"),
        payload.get("outstanding_amount"),
        payload.get("invoice_total"),
    )
    for candidate in candidates:
        amount = _money(candidate)
        if amount != Decimal("0.00"):
            return abs(amount)
    return Decimal("0.00")


def _me_report_juk_invoice_tax(payload: dict) -> Decimal:
    candidates = (
        payload.get("tax"),
        payload.get("tax_amount"),
        payload.get("total_tax"),
        payload.get("tax_total"),
    )
    for candidate in candidates:
        amount = _money(candidate)
        if amount != Decimal("0.00"):
            return abs(amount)
    return Decimal("0.00")


