def _me_report_juk_invoice_candidates(user: dict, client: dict) -> list[dict]:
    client_name = _me_report_juk_invoice_text(client.get("client_name"))
    if not client_name:
        return []
    target_keys = set(_ignition_name_match_keys(client_name))
    if not target_keys:
        return []
    director_keys = set()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT company_name, client_name, officers
                FROM ch_companies
                WHERE LOWER(TRIM(company_name)) = LOWER(TRIM(%s))
                   OR LOWER(TRIM(client_name)) = LOWER(TRIM(%s))
                LIMIT 40
                """,
                (client_name, client_name),
            )
            ch_rows = cursor.fetchall()
        connection.commit()
    for ch_row in ch_rows:
        officers = ch_row.get("officers") if isinstance(ch_row.get("officers"), list) else []
        for officer in officers:
            if not isinstance(officer, dict):
                continue
            name = _me_report_juk_invoice_text(officer.get("name"))
            for key in _ignition_name_match_keys(name):
                director_keys.add(key)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT external_id, payload, source_created_at, source_updated_at, created_at
                FROM ignition_reporting_records
                WHERE user_id = %s
                  AND dataset = 'invoices'
                ORDER BY COALESCE(source_updated_at, source_created_at, created_at) DESC
                LIMIT 4000
                """,
                (user["id"],),
            )
            records = cursor.fetchall()
        connection.commit()
    candidates = []
    seen = set()
    for record in records:
        payload = record.get("payload") or {}
        if not isinstance(payload, dict):
            continue
        status_text = _me_report_juk_invoice_status(payload)
        if status_text in {"void", "voided", "deleted", "cancelled", "canceled", "draft"}:
            continue
        row_client_name = _me_report_juk_invoice_client_name(payload)
        row_keys = set(_ignition_name_match_keys(row_client_name))
        matched_via_director = False
        if not row_keys.intersection(target_keys):
            if director_keys and row_keys.intersection(director_keys):
                matched_via_director = True
            else:
                continue
        if not row_keys.intersection(target_keys) and not matched_via_director:
            continue
        total_amount = _me_report_juk_invoice_amount(payload)
        if total_amount <= Decimal("0.00"):
            continue
        invoice_number = _me_report_juk_invoice_number(payload)
        reference = _me_report_juk_invoice_reference(payload)
        row_id = _me_report_juk_invoice_text(record.get("external_id")) or reference or invoice_number or str(uuid4())
        dedupe_key = "|".join((
            _me_report_juk_invoice_key(invoice_number),
            _me_report_juk_invoice_key(reference),
            f"{total_amount:.2f}",
            _me_report_juk_invoice_key(_me_report_juk_invoice_issue_date(payload)),
        ))
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        candidates.append({
            "ignitionInvoiceId": row_id[:120],
            "invoiceNumber": invoice_number[:120],
            "reference": reference[:160],
            "description": _me_report_juk_invoice_text(payload.get("description") or payload.get("memo") or payload.get("note"))[:240],
            "issueDate": _me_report_juk_invoice_issue_date(payload)[:40],
            "dueDate": _me_report_juk_invoice_due_date(payload)[:40],
            "currencyCode": _me_report_juk_invoice_text(payload.get("currency") or payload.get("currency_code") or payload.get("currencyCode") or "GBP")[:10] or "GBP",
            "total": float(_money(total_amount)),
            "taxAmount": float(_money(_me_report_juk_invoice_tax(payload))),
            "status": status_text or "open",
            "clientName": row_client_name[:180],
            "matchMethod": "director_fallback" if matched_via_director else "client",
        })
    return candidates[:600]


def _me_report_xero_bill_rows(invoices_payload: list[dict]) -> list[dict]:
    rows = []
    for invoice in invoices_payload:
        if not isinstance(invoice, dict):
            continue
        row_type = str(invoice.get("Type") or "").upper()
        row_status = str(invoice.get("Status") or "").upper()
        if row_type != "ACCPAY" or row_status in {"DELETED", "VOIDED"}:
            continue
        rows.append({
            "invoiceId": str(invoice.get("InvoiceID") or "").strip(),
            "invoiceNumber": str(invoice.get("InvoiceNumber") or "").strip(),
            "reference": str(invoice.get("Reference") or "").strip(),
            "date": str(invoice.get("DateString") or invoice.get("Date") or "").strip(),
            "total": abs(_money(invoice.get("Total"))),
            "status": row_status or "",
        })
    return rows


def _me_report_juk_match_xero_bill(ignition_invoice: dict, xero_bills: list[dict]) -> dict | None:
    ignition_number_key = _me_report_juk_invoice_key(ignition_invoice.get("invoiceNumber"))
    ignition_reference_key = _me_report_juk_invoice_key(ignition_invoice.get("reference"))
    ignition_amount = abs(_money(ignition_invoice.get("total")))
    for bill in xero_bills:
        number_key = _me_report_juk_invoice_key(bill.get("invoiceNumber"))
        reference_key = _me_report_juk_invoice_key(bill.get("reference"))
        if ignition_number_key and (ignition_number_key == number_key or ignition_number_key == reference_key):
            return bill
        if ignition_reference_key and (ignition_reference_key == number_key or ignition_reference_key == reference_key):
            return bill
    if ignition_amount > Decimal("0.00"):
        for bill in xero_bills:
            bill_amount = abs(_money(bill.get("total")))
            if abs(bill_amount - ignition_amount) <= Decimal("0.01"):
                return bill
    return None


def _me_report_juk_bank_transaction_candidate(bank_rows: list[dict], ignition_invoice: dict) -> tuple[str, str]:
    amount = abs(_money(ignition_invoice.get("total")))
    invoice_number = _me_report_juk_invoice_text(ignition_invoice.get("invoiceNumber"))
    reference = _me_report_juk_invoice_text(ignition_invoice.get("reference"))
    search_terms = [item.lower() for item in (invoice_number, reference) if item]
    for row in bank_rows:
        row_id = str(row.get("BankTransactionID") or "").strip()
        if not row_id:
            continue
        if bool(row.get("IsReconciled")):
            continue
        row_amount = _xero_bank_transaction_amount(row)
        if abs(row_amount - amount) > Decimal("0.01"):
            continue
        haystack = " ".join(
            str(row.get(key) or "")
            for key in ("Reference", "Type", "Status")
        ).lower()
        if search_terms and not any(term in haystack for term in search_terms):
            continue
        reason = "Unreconciled spend transaction with matching amount and reference text found."
        return row_id, reason
    for row in bank_rows:
        row_id = str(row.get("BankTransactionID") or "").strip()
        if not row_id:
            continue
        if bool(row.get("IsReconciled")):
            continue
        row_amount = _xero_bank_transaction_amount(row)
        if abs(row_amount - amount) <= Decimal("0.01"):
            return row_id, "Unreconciled spend transaction with matching amount found."
    for row in bank_rows:
        row_id = str(row.get("BankTransactionID") or "").strip()
        if not row_id:
            continue
        if not bool(row.get("IsReconciled")):
            continue
        row_amount = _xero_bank_transaction_amount(row)
        if abs(row_amount - amount) <= Decimal("0.01"):
            return row_id, "Reconciled spend transaction with matching amount found. Wizard will attempt to remove this posting before creating the bill."
    return "", ""


async def _me_report_juk_invoice_check_preview(user: dict, client: dict, connection_row: dict) -> dict:
    ignition_invoices = _me_report_juk_invoice_candidates(user, client)
    xero_invoices = await fetch_paginated_collection(
        connection_row,
        INVOICES_URL,
        "Invoices",
        params={"where": 'Type=="ACCPAY"&&Status!="DELETED"&&Status!="VOIDED"', "order": "Date DESC"},
        max_pages=12,
    )
    xero_bills = _me_report_xero_bill_rows(xero_invoices)
    try:
        bank_rows = await fetch_paginated_collection(
            connection_row,
            BANK_TRANSACTIONS_URL,
            "BankTransactions",
            params={"where": 'Type=="SPEND"&&Status!="DELETED"', "order": "Date DESC"},
            max_pages=8,
        )
    except Exception:
        bank_rows = []
    missing_rows = []
    matched_count = 0
    for invoice in ignition_invoices:
        matched = _me_report_juk_match_xero_bill(invoice, xero_bills)
        if matched:
            matched_count += 1
            continue
        suggested_transaction_id, suggested_transaction_reason = _me_report_juk_bank_transaction_candidate(bank_rows, invoice)
        missing_rows.append({
            **invoice,
            "suggestedDeleteTransactionId": suggested_transaction_id,
            "suggestedDeleteReason": suggested_transaction_reason,
        })
    missing_total = sum(_money(item.get("total")) for item in missing_rows)
    return {
        "clientId": str(client.get("id") or ""),
        "generatedAt": _iso(utcnow()) or "",
        "ignitionInvoiceCount": len(ignition_invoices),
        "xeroPurchaseInvoiceCount": len(xero_bills),
        "matchedCount": matched_count,
        "missingCount": len(missing_rows),
        "missingTotal": float(_money(missing_total)),
        "missingInvoices": missing_rows[:200],
    }


async def me_report_juk_invoice_check(user: dict, client_id: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    mode = str(payload.get("mode") or "preview").strip().lower() or "preview"
    client = _me_report_client_row(user, client_id)
    connection_row = _me_report_xero_connection(user, client)
    preview = await _me_report_juk_invoice_check_preview(user, client, connection_row)
    if mode != "apply":
        return {"check": preview}

    raw_invoices = payload.get("invoices")
    requested_rows = raw_invoices if isinstance(raw_invoices, list) else []
    selected_ids = {
        _me_report_juk_invoice_text(row.get("ignitionInvoiceId"))
        for row in requested_rows
        if isinstance(row, dict) and _me_report_juk_invoice_text(row.get("ignitionInvoiceId"))
    }
    if not selected_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one missing JUK invoice to post.")
    selected_map = {
        _me_report_juk_invoice_text(row.get("ignitionInvoiceId")): row
        for row in requested_rows
        if isinstance(row, dict)
    }
    supplier_name = _me_report_juk_invoice_text(payload.get("supplierName") or "Jaccountancy")[:120] or "Jaccountancy"
    account_code = _me_report_juk_invoice_text(payload.get("purchaseAccountCode") or "401")[:30] or "401"
    default_delete_nominal = bool(payload.get("deleteNominalPosting"))

    xero_invoices = await fetch_paginated_collection(
        connection_row,
        INVOICES_URL,
        "Invoices",
        params={"where": 'Type=="ACCPAY"&&Status!="DELETED"&&Status!="VOIDED"', "order": "Date DESC"},
        max_pages=12,
    )
    xero_bills = _me_report_xero_bill_rows(xero_invoices)
    missing_lookup = {
        _me_report_juk_invoice_text(item.get("ignitionInvoiceId")): item
        for item in preview.get("missingInvoices") or []
        if _me_report_juk_invoice_text(item.get("ignitionInvoiceId"))
    }
    created = []
    skipped_duplicates = []
    deleted_nominal = []
    errors = []

    for ignition_invoice_id in selected_ids:
        invoice = missing_lookup.get(ignition_invoice_id)
        if not invoice:
            errors.append({"ignitionInvoiceId": ignition_invoice_id, "message": "Invoice is no longer in the missing list."})
            continue
        duplicate_bill = _me_report_juk_match_xero_bill(invoice, xero_bills)
        if duplicate_bill:
            skipped_duplicates.append({
                "ignitionInvoiceId": ignition_invoice_id,
                "invoiceNumber": invoice.get("invoiceNumber") or "",
                "xeroInvoiceId": duplicate_bill.get("invoiceId") or "",
            })
            continue
        row_payload = selected_map.get(ignition_invoice_id) or {}
        delete_nominal = bool(row_payload.get("deleteNominalPosting")) if "deleteNominalPosting" in row_payload else default_delete_nominal
        suggested_transaction_id = _me_report_juk_invoice_text(row_payload.get("deleteTransactionId") or invoice.get("suggestedDeleteTransactionId"))
        if delete_nominal and suggested_transaction_id:
            try:
                transaction_payload = await xero_api_get(connection_row, f"{BANK_TRANSACTIONS_URL}/{suggested_transaction_id}")
                transaction = _me_report_xero_bank_transaction(transaction_payload)
                if transaction:
                    await update_bank_transaction_status(connection_row, suggested_transaction_id, "DELETED")
                    deleted_nominal.append({
                        "ignitionInvoiceId": ignition_invoice_id,
                        "transactionId": suggested_transaction_id,
                        "wasReconciled": bool(transaction.get("IsReconciled")),
                    })
            except Exception as exc:
                errors.append({
                    "ignitionInvoiceId": ignition_invoice_id,
                    "message": f"Could not delete nominal posting {suggested_transaction_id}: {_sync_error_message(exc)}",
                })
                continue
        total = abs(_money(invoice.get("total")))
        if total <= Decimal("0.00"):
            errors.append({"ignitionInvoiceId": ignition_invoice_id, "message": "Invoice total is zero and cannot be posted."})
            continue
        invoice_number = _me_report_juk_invoice_text(invoice.get("invoiceNumber") or invoice.get("reference") or ignition_invoice_id)[:120]
        reference = _me_report_juk_invoice_text(invoice.get("reference") or invoice_number)[:120]
        issue_date = _parse_optional_iso_date(invoice.get("issueDate")) or utcnow().date()
        due_date = _parse_optional_iso_date(invoice.get("dueDate")) or issue_date
        currency_code = _me_report_juk_invoice_text(invoice.get("currencyCode") or "GBP")[:10] or "GBP"
        description = _me_report_juk_invoice_text(invoice.get("description") or f"JUK invoice {invoice_number}")[:400] or f"JUK invoice {invoice_number}"
        invoice_payload = {
            "Type": "ACCPAY",
            "Contact": {"Name": supplier_name},
            "Date": issue_date.isoformat(),
            "DueDate": due_date.isoformat(),
            "InvoiceNumber": invoice_number,
            "Reference": reference,
            "Status": "AUTHORISED",
            "LineAmountTypes": "NoTax",
            "CurrencyCode": currency_code,
            "LineItems": [
                {
                    "Description": description,
                    "Quantity": 1,
                    "UnitAmount": float(total),
                    "AccountCode": account_code,
                    "TaxType": "NONE",
                }
            ],
        }
        try:
            created_payload = await create_sales_invoice(connection_row, invoice_payload)
            created_invoice = _me_report_xero_invoice(created_payload)
            created_row = {
                "ignitionInvoiceId": ignition_invoice_id,
                "invoiceNumber": invoice_number,
                "xeroInvoiceId": _me_report_juk_invoice_text(created_invoice.get("InvoiceID") or created_invoice.get("InvoiceId")),
                "total": float(_money(total)),
            }
            created.append(created_row)
            xero_bills.append({
                "invoiceId": created_row["xeroInvoiceId"],
                "invoiceNumber": invoice_number,
                "reference": reference,
                "date": issue_date.isoformat(),
                "total": _money(total),
                "status": "AUTHORISED",
            })
        except Exception as exc:
            errors.append({"ignitionInvoiceId": ignition_invoice_id, "message": _sync_error_message(exc)})

    result = {
        "createdCount": len(created),
        "created": created,
        "skippedDuplicateCount": len(skipped_duplicates),
        "skippedDuplicates": skipped_duplicates,
        "deletedNominalPostingCount": len(deleted_nominal),
        "deletedNominalPostings": deleted_nominal,
        "errorCount": len(errors),
        "errors": errors,
    }
    record_audit_event(
        "me_report_client",
        str(client_id),
        "me_report.juk_invoice_check_applied",
        {
            "created_count": result["createdCount"],
            "skipped_duplicate_count": result["skippedDuplicateCount"],
            "deleted_nominal_posting_count": result["deletedNominalPostingCount"],
            "error_count": result["errorCount"],
        },
        user["id"],
    )
    refreshed = await _me_report_juk_invoice_check_preview(user, client, connection_row)
    return {"check": refreshed, "result": result, "meReport": me_report_payload(user)}


def _juksib_normalise_name(value: str | None) -> str:
    raw = str(value or "").strip().lower()
    raw = re.sub(r"[^a-z0-9 ]+", " ", raw)
    raw = re.sub(r"\b(ltd|limited|uk|the|and)\b", " ", raw)
    return re.sub(r"\s+", " ", raw).strip()


def _juksib_similarity(left: str | None, right: str | None) -> Decimal:
    left_norm = _juksib_normalise_name(left)
    right_norm = _juksib_normalise_name(right)
    if not left_norm or not right_norm:
        return Decimal("0")
    if left_norm == right_norm:
        return Decimal("1")
    left_tokens = set(left_norm.split(" "))
    right_tokens = set(right_norm.split(" "))
    if not left_tokens or not right_tokens:
        return Decimal("0")
    intersection = len(left_tokens.intersection(right_tokens))
    token_score = Decimal(intersection) / Decimal(max(len(left_tokens), len(right_tokens), 1))
    sequence_score = Decimal(str(difflib.SequenceMatcher(None, left_norm, right_norm).ratio()))
    score = max(token_score, sequence_score)
    if left_norm.startswith(right_norm) or right_norm.startswith(left_norm):
        score = min(Decimal("1"), score + Decimal("0.15"))
    return score


def _juksib_decimal(value: object) -> Decimal:
    return _money(value or 0)


def _juksib_status_label(status_value: str) -> str:
    mapping = {
        "imported": "Imported",
        "duplicate": "Duplicate / already synced",
        "matched_saved_rule": "Matched by saved rule",
        "matched_openai": "Matched by OpenAI",
        "needs_review": "Needs review",
        "unmatched": "Unmatched",
        "approved": "Approved",
        "publishing": "Publishing",
        "published": "Published",
        "failed": "Failed",
        "skipped": "Skipped",
        "manually_excluded": "Manually excluded",
        "retry_pending": "Retry pending",
    }
    return mapping.get(str(status_value or "").strip(), str(status_value or "").strip())


def _juksib_build_summary(rows: list[dict]) -> dict:
    invoices = rows or []
    status_counts = defaultdict(int)
    matched_saved_rule = 0
    matched_openai = 0
    high_confidence = 0
    total_value = Decimal("0")
    for row in invoices:
        status_counts[str(row.get("status") or "imported").strip()] += 1
        source = str(row.get("match_source") or "").strip()
        if source == "saved_rule":
            matched_saved_rule += 1
        if source == "openai":
            matched_openai += 1
        confidence = _juksib_decimal(row.get("match_confidence"))
        if confidence >= JUKSIB_CONFIDENCE_HIGH:
            high_confidence += 1
        total_value += _juksib_decimal(row.get("total"))
    ready_to_publish = status_counts["approved"] + status_counts["retry_pending"]
    return {
        "totalImported": len(invoices),
        "duplicates": status_counts["duplicate"],
        "matchedBySavedRule": matched_saved_rule,
        "matchedByOpenAI": matched_openai,
        "highConfidence": high_confidence,
        "needsReview": status_counts["needs_review"],
        "unmatched": status_counts["unmatched"],
        "failed": status_counts["failed"],
        "readyToPublish": ready_to_publish,
        "published": status_counts["published"],
        "skipped": status_counts["skipped"] + status_counts["manually_excluded"],
        "totalValue": float(_money(total_value)),
    }


def _juksib_record_audit(
    *,
    user_id: str,
    batch_id: str | None,
    entity_type: str,
    entity_id: str,
    action: str,
    old_value: dict | None = None,
    new_value: dict | None = None,
    notes: str = "",
) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO juksib_audit_logs (user_id, batch_id, entity_type, entity_id, action, old_value, new_value, notes)
                VALUES (%s, NULLIF(%s, '')::uuid, %s, %s, %s, %s::jsonb, %s::jsonb, %s)
                """,
                (
                    user_id,
                    str(batch_id or ""),
                    entity_type,
                    entity_id,
                    action,
                    json.dumps(old_value or {}, default=_json_default),
                    json.dumps(new_value or {}, default=_json_default),
                    notes[:5000],
                ),
            )
        connection.commit()


def _juksib_next_batch_reference(user_id: str) -> str:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT batch_reference
                FROM juksib_batches
                WHERE user_id = %s
                  AND batch_reference LIKE %s
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (user_id, f"{JUKSIB_BATCH_PREFIX}%"),
            )
            row = cursor.fetchone() or {}
        connection.commit()
    latest = str(row.get("batch_reference") or "").strip().upper()
    if not latest.startswith(JUKSIB_BATCH_PREFIX):
        return f"{JUKSIB_BATCH_PREFIX}001"
    suffix = latest.replace(JUKSIB_BATCH_PREFIX, "", 1)
    number = int(suffix or "0") if suffix.isdigit() else 0
    return f"{JUKSIB_BATCH_PREFIX}{str(number + 1).zfill(3)}"


def _juksib_master_and_sub_connections(user: dict) -> tuple[dict, list[dict]]:
    master = get_master_xero_connection_for_user(user["id"])
    rows = list_xero_connections_for_user(user["id"], include_fallback=False)
    sub_rows = [
        row for row in rows
        if str(row.get("tenant_id") or "").strip() and str(row.get("tenant_id") or "").strip() != str(master.get("tenant_id") or "").strip()
    ]
    return master, sub_rows


def _juksib_serialise_invoice_row(row: dict) -> dict:
    return {
        "id": str(row.get("id") or ""),
        "batchId": str(row.get("batch_id") or ""),
        "jukXeroInvoiceId": str(row.get("juk_xero_invoice_id") or ""),
        "jukInvoiceNumber": str(row.get("juk_invoice_number") or ""),
        "jukContactId": str(row.get("juk_contact_id") or ""),
        "jukContactName": str(row.get("juk_contact_name") or ""),
        "invoiceDate": _iso(row.get("invoice_date")) or "",
        "dueDate": _iso(row.get("due_date")) or "",
        "subtotal": float(_juksib_decimal(row.get("subtotal"))),
        "vatTotal": float(_juksib_decimal(row.get("vat_total"))),
        "total": float(_juksib_decimal(row.get("total"))),
        "amountDue": float(_juksib_decimal(row.get("amount_due"))),
        "currency": str(row.get("currency") or "GBP"),
        "lineItems": row.get("line_items") if isinstance(row.get("line_items"), list) else [],
        "rawPayload": row.get("raw_xero_payload") if isinstance(row.get("raw_xero_payload"), dict) else {},
        "pdfFileReference": str(row.get("pdf_file_reference") or ""),
        "status": str(row.get("status") or "imported"),
        "statusLabel": _juksib_status_label(str(row.get("status") or "imported")),
        "duplicateFlag": bool(row.get("duplicate_flag")),
        "matchedClientId": str(row.get("matched_client_id") or ""),
        "matchedTenantId": str(row.get("matched_xero_tenant_id") or ""),
        "matchedTenantName": str(row.get("matched_xero_tenant_name") or ""),
        "matchSource": str(row.get("match_source") or ""),
        "matchConfidence": float(_juksib_decimal(row.get("match_confidence"))),
        "matchReason": str(row.get("match_reason") or ""),
        "alternatives": row.get("alternatives") if isinstance(row.get("alternatives"), list) else [],
        "publishedBillId": str(row.get("published_bill_id") or ""),
        "publishedAt": _iso(row.get("published_at")) or "",
        "errorMessage": str(row.get("error_message") or ""),
        "retryCount": int(row.get("retry_count") or 0),
    }


def _juksib_preview_vat_profile(
    *,
    client_name: str,
    matched_client_id: str,
    register_index: dict,
    run_cache: dict[str, dict],
) -> dict:
    contact_name = str(client_name or "").strip()
    normalised_client_name = _bm_tasks_normalise_name_key(contact_name) or _juksib_normalise_name(contact_name)
    if not normalised_client_name:
        return _juksib_default_vat_profile(contact_name, "empty_name", "Client name was empty; defaulted to no VAT.")
    if normalised_client_name in run_cache:
        return run_cache[normalised_client_name]

    register_rows = register_index.get("rows") if isinstance(register_index.get("rows"), list) else []
    by_client_id = register_index.get("byClientId") if isinstance(register_index.get("byClientId"), dict) else {}
    by_name = register_index.get("byName") if isinstance(register_index.get("byName"), dict) else {}

    matched_row = None
    lookup_source = "register_none"
    lookup_reason = "No client register row matched; defaulted to no VAT."
    lookup_confidence = Decimal("0")

    matched_client_id_key = str(matched_client_id or "").strip().lower()
    if matched_client_id_key and matched_client_id_key in by_client_id:
        matched_row = by_client_id.get(matched_client_id_key)
        lookup_source = "register_client_id"
        lookup_reason = "Matched using client id from the destination candidate."
        lookup_confidence = Decimal("1")
    if not matched_row:
        exact_name_row = by_name.get(normalised_client_name)
        if exact_name_row:
            matched_row = exact_name_row
            lookup_source = "register_exact"
            lookup_reason = "Exact client register name match."
            lookup_confidence = Decimal("0.99")
    if not matched_row and contact_name and register_rows:
        scored_rows = sorted(
            (
                {
                    "row": row,
                    "score": _juksib_similarity(contact_name, _juksib_register_display_name(row)),
                }
                for row in register_rows
                if _juksib_register_display_name(row)
            ),
            key=lambda item: item["score"],
            reverse=True,
        )
        if scored_rows:
            top = scored_rows[0]
            second = scored_rows[1] if len(scored_rows) > 1 else {"score": Decimal("0")}
            if top["score"] >= Decimal("0.82") and (top["score"] - second["score"]) >= Decimal("0.12"):
                matched_row = top["row"]
                lookup_source = "register_fuzzy"
                lookup_reason = "High-confidence fuzzy match against client register name."
                lookup_confidence = top["score"]

    if matched_row:
        vat_number = _juksib_clean_vat_number(matched_row.get("vat_number"))
        vat_registered = bool(vat_number)
        profile = {
            "clientName": contact_name,
            "vatRegistered": vat_registered,
            "vatNumber": vat_number,
            "taxType": JUKSIB_EXPENSES_VAT_TAX_TYPE if vat_registered else JUKSIB_NO_VAT_TAX_TYPE,
            "lookupSource": lookup_source,
            "lookupReason": lookup_reason,
            "lookupConfidence": float(lookup_confidence),
            "registerId": str(matched_row.get("id") or "").strip(),
            "registerName": _juksib_register_display_name(matched_row),
        }
    else:
        profile = _juksib_default_vat_profile(contact_name, lookup_source, lookup_reason)

    run_cache[normalised_client_name] = profile
    return profile


def _juksib_serialise_batch_row(batch_row: dict, invoices: list[dict]) -> dict:
    summary = _juksib_build_summary(invoices)
    metadata = batch_row.get("metadata") if isinstance(batch_row.get("metadata"), dict) else {}
    excluded_invoices = metadata.get("excludedInvoices") if isinstance(metadata.get("excludedInvoices"), list) else []
    return {
        "id": str(batch_row.get("id") or ""),
        "batchReference": str(batch_row.get("batch_reference") or ""),
        "createdAt": _iso(batch_row.get("created_at")) or "",
        "updatedAt": _iso(batch_row.get("updated_at")) or "",
        "sourceTenantId": str(batch_row.get("source_tenant_id") or ""),
        "sourceTenantName": str(batch_row.get("source_tenant_name") or ""),
        "invoiceDateFrom": _iso(batch_row.get("invoice_date_from")) or "",
        "invoiceDateTo": _iso(batch_row.get("invoice_date_to")) or "",
        "mode": str(batch_row.get("mode") or "test"),
        "status": str(batch_row.get("status") or "imported"),
        "excludedInvoiceCount": int(metadata.get("excludedInvoiceCount") or len(excluded_invoices) or 0),
        "excludedInvoices": excluded_invoices[:300],
        "summary": summary,
        "invoices": invoices,
    }


async def _juksib_openai_match_contact(
    *,
    user: dict,
    invoice_name: str,
    candidates: list[dict],
) -> dict | None:
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip() or not candidates:
        return None
    candidate_rows = [
        {
            "tenant_id": str(row.get("tenant_id") or ""),
            "tenant_name": str(row.get("tenant_name") or ""),
            "client_id": str(row.get("client_id") or ""),
            "client_name": str(row.get("client_name") or ""),
            "company_name": str(row.get("company_name") or ""),
            "company_number": str(row.get("company_number") or ""),
            "active": bool(row.get("active")),
            "aliases": row.get("aliases") if isinstance(row.get("aliases"), list) else [],
        }
        for row in candidates[:80]
    ]
    request_body = {
        "model": settings.openai_model,
        "input": [
            {
                "role": "system",
                "content": (
                    "You match invoice contact names to known Xero tenant names. "
                    "Return strict JSON only."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(
                    {
                        "invoice_contact_name": invoice_name,
                        "candidate_tenants": candidate_rows,
                        "instructions": {
                            "pick_best": True,
                            "confidence_scale": "0-1",
                            "return_empty_when_no_match": True,
                        },
                    },
                    default=_json_default,
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "juksib_match",
                "strict": True,
                "schema": JUKSIB_MATCH_RESPONSE_SCHEMA,
            }
        },
    }
    try:
        response_payload = await _post_openai_responses(
            request_body,
            purpose="JUKSIB invoice matching",
            feature="juksib",
            page="juk-invoices",
            user_id=user["id"],
            timeout_seconds=JUKSIB_OPENAI_MATCH_TIMEOUT_SECONDS,
        )
        return _load_openai_json_response(
            response_payload,
            "OpenAI returned invalid JSON for JUKSIB invoice matching.",
        )
    except Exception:
        logger.exception("JUKSIB: OpenAI match failed for invoice contact '%s'", invoice_name)
        return None


def _juksib_rule_match(contact_name: str, rules: list[dict]) -> dict | None:
    normalized = _juksib_normalise_name(contact_name)
    if not normalized:
        return None
    for rule in rules:
        if not bool(rule.get("active")):
            continue
        if str(rule.get("normalised_invoice_name") or "").strip() == normalized:
            return rule
    return None


async def _juksib_match_invoice(
    *,
    user: dict,
    contact_name: str,
    rules: list[dict],
    candidates: list[dict],
    allow_openai: bool = True,
) -> dict:
    if not str(contact_name or "").strip():
        return {
            "status": "unmatched",
            "duplicate_flag": False,
            "matched_rule_id": "",
            "matched_client_id": "",
            "matched_xero_tenant_id": "",
            "matched_xero_tenant_name": "",
            "match_source": "heuristic",
            "match_confidence": Decimal("0"),
            "match_reason": "Invoice contact name is empty.",
            "alternatives": [],
        }
    rule = _juksib_rule_match(contact_name, rules)
    if rule:
        rule_type = str(rule.get("match_type") or "manual_override")
        if rule_type == "exclude":
            return {
                "status": "manually_excluded",
                "duplicate_flag": False,
                "matched_rule_id": str(rule.get("id") or ""),
                "matched_client_id": "",
                "matched_xero_tenant_id": "",
                "matched_xero_tenant_name": "",
                "match_source": "saved_rule_exclusion",
                "match_confidence": Decimal("1"),
                "match_reason": "Excluded by saved manual rule.",
                "alternatives": [],
            }
        return {
            "status": "approved",
            "duplicate_flag": False,
            "matched_rule_id": str(rule.get("id") or ""),
            "matched_client_id": str(rule.get("client_id") or ""),
            "matched_xero_tenant_id": str(rule.get("xero_tenant_id") or ""),
            "matched_xero_tenant_name": str(rule.get("xero_tenant_name") or ""),
            "match_source": "saved_rule",
            "match_confidence": Decimal("0.99"),
            "match_reason": "Matched using saved manual rule.",
            "alternatives": [],
        }

    active_candidates = [candidate for candidate in candidates if bool(candidate.get("active", True))]
    scored = []
    for candidate in active_candidates:
        score = _juksib_similarity(contact_name, candidate.get("tenant_name"))
        aliases = candidate.get("aliases") if isinstance(candidate.get("aliases"), list) else []
        for alias in aliases:
            score = max(score, _juksib_similarity(contact_name, str(alias)))
        scored.append({**candidate, "score": score})
    scored.sort(key=lambda row: row["score"], reverse=True)
    top = scored[0] if scored else None
    top_confidence = _juksib_decimal(top.get("score")) if top else Decimal("0")

    if top and top_confidence >= Decimal("0.94"):
        return {
            "status": "approved",
            "duplicate_flag": False,
            "matched_rule_id": "",
            "matched_client_id": str(top.get("client_id") or ""),
            "matched_xero_tenant_id": str(top.get("tenant_id") or ""),
            "matched_xero_tenant_name": str(top.get("tenant_name") or ""),
            "match_source": "exact_tenant_match",
            "match_confidence": top_confidence,
            "match_reason": "Strong tenant name match against connected organisations.",
            "alternatives": [
                {
                    "tenant_id": str(item.get("tenant_id") or ""),
                    "tenant_name": str(item.get("tenant_name") or ""),
                    "confidence": float(_juksib_decimal(item.get("score"))),
                }
                for item in scored[1:4]
            ],
        }

    should_try_openai = bool(allow_openai) and (not top or top_confidence < JUKSIB_CONFIDENCE_HIGH)
    if should_try_openai:
        openai_match = await _juksib_openai_match_contact(user=user, invoice_name=contact_name, candidates=active_candidates)
        if openai_match:
            suggested_id = str(openai_match.get("suggested_tenant_id") or "").strip()
            suggested = next((row for row in active_candidates if str(row.get("tenant_id") or "").strip() == suggested_id), None)
            confidence = Decimal(str(openai_match.get("confidence") or "0"))
            if suggested and confidence > Decimal("0"):
                status_value = "approved" if confidence >= JUKSIB_CONFIDENCE_HIGH else ("needs_review" if confidence >= JUKSIB_CONFIDENCE_MEDIUM else "unmatched")
                return {
                    "status": status_value,
                    "duplicate_flag": False,
                    "matched_rule_id": "",
                    "matched_client_id": str(suggested.get("client_id") or ""),
                    "matched_xero_tenant_id": str(suggested.get("tenant_id") or ""),
                    "matched_xero_tenant_name": str(suggested.get("tenant_name") or ""),
                    "match_source": "openai",
                    "match_confidence": confidence,
                    "match_reason": str(openai_match.get("reason") or "OpenAI matched invoice contact to connected tenant."),
                    "alternatives": openai_match.get("alternatives") if isinstance(openai_match.get("alternatives"), list) else [],
                }

    if not top or _juksib_decimal(top.get("score")) < Decimal("0.55"):
        return {
            "status": "unmatched",
            "duplicate_flag": False,
            "matched_rule_id": "",
            "matched_client_id": "",
            "matched_xero_tenant_id": "",
            "matched_xero_tenant_name": "",
            "match_source": "heuristic",
            "match_confidence": Decimal("0"),
            "match_reason": "No connected tenant matched this invoice contact name.",
            "alternatives": [],
        }

    confidence = top_confidence
    status_value = "approved" if confidence >= JUKSIB_CONFIDENCE_HIGH else ("needs_review" if confidence >= JUKSIB_CONFIDENCE_MEDIUM else "unmatched")
    return {
        "status": status_value,
        "duplicate_flag": False,
        "matched_rule_id": "",
        "matched_client_id": str(top.get("client_id") or ""),
        "matched_xero_tenant_id": str(top.get("tenant_id") or ""),
        "matched_xero_tenant_name": str(top.get("tenant_name") or ""),
        "match_source": "heuristic",
        "match_confidence": confidence,
        "match_reason": "Heuristic name matching used against connected tenant aliases.",
        "alternatives": [
            {
                "tenant_id": str(item.get("tenant_id") or ""),
                "tenant_name": str(item.get("tenant_name") or ""),
                "confidence": float(_juksib_decimal(item.get("score"))),
            }
            for item in scored[1:4]
        ],
    }


def _juksib_source_invoice_rows(raw_invoices: list[dict], *, date_from: date | None = None, date_to: date | None = None) -> list[dict]:
    rows = []
    excluded_rows: list[dict] = []

    def self_assessment_reason(raw_invoice: dict, line_items: list[dict]) -> str:
        tokens = [
            str(raw_invoice.get("InvoiceNumber") or ""),
            str(raw_invoice.get("Reference") or ""),
            str(raw_invoice.get("BrandingThemeID") or ""),
            str(raw_invoice.get("Url") or ""),
        ]
        contact = raw_invoice.get("Contact") if isinstance(raw_invoice.get("Contact"), dict) else {}
        tokens.append(str(contact.get("Name") or ""))
        for line in line_items or []:
            if not isinstance(line, dict):
                continue
            tokens.append(str(line.get("Description") or line.get("ItemCode") or ""))
        haystack = " ".join(tokens).lower()
        patterns = [
            "self assessment",
            "self-assessment",
            "sa100",
            "tax return",
            "tax-return",
            "personal tax",
            "self employed tax",
        ]
        for pattern in patterns:
            if pattern in haystack:
                return f"Matched exclusion rule '{pattern}'."
        return ""

    for raw in raw_invoices or []:
        invoice_id = str(raw.get("InvoiceID") or raw.get("InvoiceId") or "").strip()
        if not invoice_id:
            continue
        status_value = str(raw.get("Status") or "").strip().upper()
        if status_value in {"VOIDED", "DELETED", "DRAFT", "SUBMITTED"}:
            continue
        invoice_date = _parse_optional_iso_date(raw.get("Date"))
        if date_from and invoice_date and invoice_date < date_from:
            continue
        if date_to and invoice_date and invoice_date > date_to:
            continue
        contact = raw.get("Contact") if isinstance(raw.get("Contact"), dict) else {}
        line_items = raw.get("LineItems") if isinstance(raw.get("LineItems"), list) else []
        subtotal = _juksib_decimal(raw.get("SubTotal"))
        total_tax = _juksib_decimal(raw.get("TotalTax"))
        total = _juksib_decimal(raw.get("Total"))
        amount_due = _juksib_decimal(raw.get("AmountDue"))
        due_date = _parse_optional_iso_date(raw.get("DueDate"))
        exclusion_reason = self_assessment_reason(raw, line_items)
        if exclusion_reason:
            excluded_rows.append(
                {
                    "juk_xero_invoice_id": invoice_id,
                    "juk_invoice_number": str(raw.get("InvoiceNumber") or "").strip(),
                    "juk_contact_id": str(contact.get("ContactID") or contact.get("ContactId") or "").strip(),
                    "juk_contact_name": str(contact.get("Name") or "").strip(),
                    "invoice_date": _iso(invoice_date) or "",
                    "due_date": _iso(due_date) or "",
                    "subtotal": float(_money(subtotal)),
                    "vat_total": float(_money(total_tax)),
                    "total": float(_money(total)),
                    "amount_due": float(_money(amount_due if amount_due > Decimal("0") else total)),
                    "currency": str(raw.get("CurrencyCode") or "GBP").strip() or "GBP",
                    "line_items": line_items,
                    "raw_xero_payload": raw,
                    "pdf_file_reference": f"/api/juksib/source-invoices/{invoice_id}/pdf",
                    "status": "excluded_self_assessment",
                    "exclude_reason": exclusion_reason,
                }
            )
            continue
        rows.append(
            {
                "juk_xero_invoice_id": invoice_id,
                "juk_invoice_number": str(raw.get("InvoiceNumber") or "").strip(),
                "juk_contact_id": str(contact.get("ContactID") or contact.get("ContactId") or "").strip(),
                "juk_contact_name": str(contact.get("Name") or "").strip(),
                "invoice_date": invoice_date,
                "due_date": due_date,
                "subtotal": subtotal,
                "vat_total": total_tax,
                "total": total,
                "amount_due": amount_due if amount_due > Decimal("0") else total,
                "currency": str(raw.get("CurrencyCode") or "GBP").strip() or "GBP",
                "line_items": line_items,
                "raw_xero_payload": raw,
                "pdf_file_reference": f"/api/juksib/source-invoices/{invoice_id}/pdf",
                "status": "imported",
            }
        )
    _juksib_source_invoice_rows.last_excluded_rows = excluded_rows
    return rows


async def juksib_import_batch(user: dict, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    mode = str(payload.get("mode") or "test").strip().lower() or "test"
    import_scope = str(payload.get("importScope") or "since-last").strip().lower() or "since-last"
    if import_scope not in {"since-last", "date-range", "recent"}:
        import_scope = "since-last"
    include_paid = bool(payload.get("includePaidInvoices"))
    include_imported = bool(payload.get("includeAlreadyImported"))
    date_from = _parse_optional_iso_date(payload.get("invoiceDateFrom"))
    date_to = _parse_optional_iso_date(payload.get("invoiceDateTo"))
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invoice Date From must be on or before Invoice Date To.")

    master_connection, sub_connections = _juksib_master_and_sub_connections(user)
    effective_date_from = date_from
    effective_date_to = date_to
    if import_scope == "since-last" and effective_date_from is None:
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT invoice_date_to
                    FROM juksib_batches
                    WHERE user_id = %s
                      AND status IN ('imported', 'published')
                    ORDER BY created_at DESC
                    LIMIT 1
                    """,
                    (user["id"],),
                )
                last_row = cursor.fetchone() or {}
            connection.commit()
        last_to = _parse_optional_iso_date(last_row.get("invoice_date_to"))
        if last_to is not None:
            effective_date_from = last_to + timedelta(days=1)
    elif import_scope == "recent" and effective_date_from is None and effective_date_to is None:
        effective_date_to = utcnow().date()
        effective_date_from = effective_date_to - timedelta(days=14)

    where_clauses = ['Type=="ACCREC"', 'Status!="VOIDED"', 'Status!="DELETED"']
    if not include_paid:
        where_clauses.append('Status!="PAID"')
    if effective_date_from is not None:
        where_clauses.append(f"Date>={_xero_datetime_where_literal(effective_date_from)}")
    if effective_date_to is not None:
        where_clauses.append(f"Date<{_xero_datetime_where_literal(effective_date_to + timedelta(days=1))}")
    where = "&&".join(where_clauses)
    max_pages = 3 if import_scope == "recent" else (8 if (effective_date_from or effective_date_to) else 10)
    raw_invoices = await fetch_paginated_collection(
        master_connection,
        INVOICES_URL,
        "Invoices",
        params={"where": where, "order": "Date DESC"},
        max_pages=max_pages,
    )
    source_rows = _juksib_source_invoice_rows(raw_invoices, date_from=effective_date_from, date_to=effective_date_to)[:JUKSIB_MAX_IMPORT_INVOICES]
    excluded_rows = list(getattr(_juksib_source_invoice_rows, "last_excluded_rows", []) or [])
    if source_rows and not include_imported:
        source_invoice_ids = [str(row.get("juk_xero_invoice_id") or "").strip() for row in source_rows if str(row.get("juk_xero_invoice_id") or "").strip()]
        seen_source_ids: set[str] = set()
        if source_invoice_ids:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT juk_xero_invoice_id
                        FROM juksib_batch_invoices
                        WHERE user_id = %s
                          AND juk_xero_invoice_id = ANY(%s::text[])
                        """,
                        (user["id"], source_invoice_ids),
                    )
                    for row in (cursor.fetchall() or []):
                        value = str(row.get("juk_xero_invoice_id") or "").strip()
                        if value:
                            seen_source_ids.add(value)
                    cursor.execute(
                        """
                        SELECT juk_xero_invoice_id
                        FROM juksib_sync_records
                        WHERE user_id = %s
                          AND juk_xero_invoice_id = ANY(%s::text[])
                        """,
                        (user["id"], source_invoice_ids),
                    )
                    for row in (cursor.fetchall() or []):
                        value = str(row.get("juk_xero_invoice_id") or "").strip()
                        if value:
                            seen_source_ids.add(value)
                connection.commit()
        if seen_source_ids:
            source_rows = [row for row in source_rows if str(row.get("juk_xero_invoice_id") or "").strip() not in seen_source_ids]
            excluded_rows = [row for row in excluded_rows if str(row.get("juk_xero_invoice_id") or "").strip() not in seen_source_ids]

    rules: list[dict] = []
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_match_rules
                WHERE user_id = %s
                  AND active = TRUE
                ORDER BY updated_at DESC, created_at DESC
                """,
                (user["id"],),
            )
            rules = cursor.fetchall() or []
        connection.commit()

    mappings_by_tenant: dict[str, dict] = {}
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM xero_tenant_company_mappings")
            for mapping in (cursor.fetchall() or []):
                tenant_key = str(mapping.get("tenant_id") or "").strip()
                if tenant_key:
                    mappings_by_tenant[tenant_key] = mapping
        connection.commit()

    candidates = []
    for row in sub_connections:
        tenant_id = str(row.get("tenant_id") or "").strip()
        if not tenant_id:
            continue
        tenant_name = str(row.get("tenant_name") or "").strip()
        mapping = mappings_by_tenant.get(tenant_id, {})
        company_name = str(mapping.get("company_name") or "").strip()
        client_name = str(mapping.get("client_name") or "").strip()
        company_number = str(mapping.get("company_number") or "").strip()
        aliases = [alias for alias in [tenant_name, company_name, client_name] if alias]
        active_state = str(row.get("status") or "").strip().lower() not in {"disconnected", "inactive"}
        candidates.append(
            {
                "tenant_id": tenant_id,
                "tenant_name": tenant_name,
                "client_id": str(row.get("client_id") or tenant_id).strip() or tenant_id,
                "client_name": client_name,
                "company_name": company_name,
                "company_number": company_number,
                "aliases": aliases,
                "active": active_state,
            }
        )

    batch_reference = _juksib_next_batch_reference(user["id"])
    batch_id = ""
    inserted_invoices = []
    openai_match_remaining = min(JUKSIB_OPENAI_MATCH_LIMIT, len(source_rows))
    openai_deadline_monotonic = time.monotonic() + JUKSIB_OPENAI_MATCH_BUDGET_SECONDS
    match_cache: dict[str, dict] = {}

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO juksib_batches (
                    user_id,
                    batch_reference,
                    source_tenant_id,
                    source_tenant_name,
                    invoice_date_from,
                    invoice_date_to,
                    mode,
                    status,
                    metadata,
                    created_by_user_id,
                    updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                RETURNING id
                """,
                (
                    user["id"],
                    batch_reference,
                    str(master_connection.get("tenant_id") or ""),
                    str(master_connection.get("tenant_name") or ""),
                    date_from,
                    date_to,
                    mode,
                    "imported",
                    json.dumps(
                        {
                            "importScope": import_scope,
                            "includePaidInvoices": include_paid,
                            "includeAlreadyImported": include_imported,
                            "effectiveDateFrom": _iso(effective_date_from),
                            "effectiveDateTo": _iso(effective_date_to),
                            "xeroFetchMaxPages": max_pages,
                            "candidateTenantCount": len(candidates),
                            "excludedInvoiceCount": len(excluded_rows),
                            "excludedInvoices": excluded_rows[:300],
                        },
                        default=_json_default,
                    ),
                    user["id"],
                    utcnow(),
                ),
            )
            batch_id = str((cursor.fetchone() or {}).get("id") or "")

        for row in source_rows:
            contact_name = str(row.get("juk_contact_name") or "").strip()
            cache_key = _juksib_normalise_name(contact_name) or contact_name.lower()
            if cache_key and cache_key in match_cache:
                match_row = dict(match_cache[cache_key])
            else:
                match_row = await _juksib_match_invoice(
                    user=user,
                    contact_name=contact_name,
                    rules=rules,
                    candidates=candidates,
                    allow_openai=(openai_match_remaining > 0 and time.monotonic() < openai_deadline_monotonic),
                )
                if cache_key:
                    match_cache[cache_key] = dict(match_row)
                if str(match_row.get("match_source") or "") == "openai" and openai_match_remaining > 0:
                    openai_match_remaining -= 1
            duplicate_flag = False
            if match_row.get("matched_xero_tenant_id"):
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        SELECT id
                        FROM juksib_sync_records
                        WHERE user_id = %s
                          AND source_tenant_id = %s
                          AND juk_xero_invoice_id = %s
                          AND destination_tenant_id = %s
                          AND sync_status = 'published'
                        LIMIT 1
                        """,
                        (
                            user["id"],
                            str(master_connection.get("tenant_id") or ""),
                            row["juk_xero_invoice_id"],
                            str(match_row.get("matched_xero_tenant_id") or ""),
                        ),
                    )
                    duplicate_flag = bool(cursor.fetchone())
            status_value = str(match_row.get("status") or "imported")
            if duplicate_flag:
                status_value = "duplicate"
            matched_rule_id = str(match_row.get("matched_rule_id") or "").strip()
            if matched_rule_id:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_match_rules
                        SET usage_count = usage_count + 1,
                            last_used_at = NOW(),
                            updated_at = NOW()
                        WHERE id = %s::uuid
                          AND user_id = %s
                        """,
                        (matched_rule_id, user["id"]),
                    )

            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO juksib_batch_invoices (
                        batch_id, user_id, juk_xero_invoice_id, juk_invoice_number, juk_contact_id, juk_contact_name,
                        invoice_date, due_date, subtotal, vat_total, total, amount_due, currency, line_items, raw_xero_payload,
                        pdf_file_reference, status, duplicate_flag, matched_client_id, matched_xero_tenant_id, matched_xero_tenant_name,
                        match_source, match_confidence, match_reason, alternatives, created_at, updated_at
                    )
                    VALUES (
                        %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb,
                        %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s, %s
                    )
                    RETURNING *
                    """,
                    (
                        batch_id,
                        user["id"],
                        row["juk_xero_invoice_id"],
                        row["juk_invoice_number"],
                        row["juk_contact_id"],
                        row["juk_contact_name"],
                        row["invoice_date"],
                        row["due_date"],
                        row["subtotal"],
                        row["vat_total"],
                        row["total"],
                        row["amount_due"],
                        row["currency"],
                        json.dumps(row.get("line_items") or [], default=_json_default),
                        json.dumps(row.get("raw_xero_payload") or {}, default=_json_default),
                        row["pdf_file_reference"],
                        status_value,
                        duplicate_flag,
                        str(match_row.get("matched_client_id") or ""),
                        str(match_row.get("matched_xero_tenant_id") or ""),
                        str(match_row.get("matched_xero_tenant_name") or ""),
                        str(match_row.get("match_source") or ""),
                        _juksib_decimal(match_row.get("match_confidence")),
                        str(match_row.get("match_reason") or ""),
                        json.dumps(match_row.get("alternatives") or [], default=_json_default),
                        utcnow(),
                        utcnow(),
                    ),
                )
                inserted_invoices.append(cursor.fetchone() or {})

        summary = _juksib_build_summary(inserted_invoices)
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE juksib_batches
                SET summary = %s::jsonb,
                    status = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (json.dumps(summary, default=_json_default), "imported", utcnow(), batch_id),
            )
        connection.commit()

    _juksib_record_audit(
        user_id=user["id"],
        batch_id=batch_id,
        entity_type="juksib_batch",
        entity_id=batch_id,
        action="batch_imported",
        new_value={"batchReference": batch_reference, "summary": summary},
        notes=f"Imported {summary.get('totalImported', 0)} invoices from master tenant.",
    )
    return await juksib_get_batch(user, batch_id)


async def juksib_get_batch(user: dict, batch_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batches
                WHERE id = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (batch_id, user["id"]),
            )
            batch_row = cursor.fetchone()
            if not batch_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="JUKSIB batch not found.")
            cursor.execute(
                """
                SELECT *
                FROM juksib_batch_invoices
                WHERE batch_id = %s
                  AND user_id = %s
                ORDER BY invoice_date DESC NULLS LAST, created_at DESC
                """,
                (batch_id, user["id"]),
            )
            invoice_rows = cursor.fetchall() or []
        connection.commit()
    serialised_invoices = [_juksib_serialise_invoice_row(row) for row in invoice_rows]
    register_index = _juksib_build_vat_register_index(_juksib_fetch_client_register_rows_for_vat())
    vat_preview_cache: dict[str, dict] = {}
    for invoice in serialised_invoices:
        vat_profile = _juksib_preview_vat_profile(
            client_name=str(invoice.get("jukContactName") or ""),
            matched_client_id=str(invoice.get("matchedClientId") or ""),
            register_index=register_index,
            run_cache=vat_preview_cache,
        )
        vat_registered = bool(vat_profile.get("vatRegistered"))
        invoice["vatPostingApplies"] = vat_registered
        invoice["vatPostingLabel"] = "VAT" if vat_registered else "No VAT"
        invoice["vatLookupSource"] = str(vat_profile.get("lookupSource") or "")
        invoice["vatLookupReason"] = str(vat_profile.get("lookupReason") or "")
        invoice["vatTaxType"] = str(vat_profile.get("taxType") or JUKSIB_NO_VAT_TAX_TYPE)
        invoice["vatClientName"] = str(vat_profile.get("registerName") or vat_profile.get("clientName") or invoice.get("jukContactName") or "").strip()
        invoice["vatClientId"] = str(vat_profile.get("registerId") or invoice.get("matchedClientId") or "").strip()
        invoice["vatNumber"] = str(vat_profile.get("vatNumber") or "").strip()
    return {"batch": _juksib_serialise_batch_row(batch_row, serialised_invoices)}


async def juksib_list_batches(user: dict, limit: int = 30) -> dict:
    batch_rows: list[dict] = []
    rules: list[dict] = []
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batches
                WHERE user_id = %s
                ORDER BY created_at DESC
                LIMIT %s
                """,
                (user["id"], max(1, min(int(limit or 30), 200))),
            )
            batch_rows = cursor.fetchall() or []
            try:
                cursor.execute(
                    """
                    SELECT *
                    FROM juksib_match_rules
                    WHERE user_id = %s
                    ORDER BY updated_at DESC NULLS LAST, created_at DESC
                    LIMIT 400
                    """,
                    (user["id"],),
                )
                rules = cursor.fetchall() or []
            except Exception:
                # Backward-compatibility guard for environments where updated_at/index migrations
                # have not landed yet. Keep batch listing available even when rules cannot be ordered by updated_at.
                logger.exception("JUKSIB: match rules query with updated_at failed, falling back to created_at ordering.")
                try:
                    cursor.execute(
                        """
                        SELECT *
                        FROM juksib_match_rules
                        WHERE user_id = %s
                        ORDER BY created_at DESC
                        LIMIT 400
                        """,
                        (user["id"],),
                    )
                    rules = cursor.fetchall() or []
                except Exception:
                    logger.exception("JUKSIB: match rules fallback query failed; returning batches without rules.")
                    rules = []
        connection.commit()
    batches = []
    for row in batch_rows:
        summary = row.get("summary") if isinstance(row.get("summary"), dict) else {}
        batches.append(
            {
                "id": str(row.get("id") or ""),
                "batchReference": str(row.get("batch_reference") or ""),
                "createdAt": _iso(row.get("created_at")) or "",
                "mode": str(row.get("mode") or "test"),
                "status": str(row.get("status") or "imported"),
                "summary": summary,
            }
        )
    return {
        "batches": batches,
        "rules": [
            {
                "id": str(rule.get("id") or ""),
                "normalisedInvoiceName": str(rule.get("normalised_invoice_name") or ""),
                "originalInvoiceName": str(rule.get("original_invoice_name") or ""),
                "clientId": str(rule.get("client_id") or ""),
                "tenantId": str(rule.get("xero_tenant_id") or ""),
                "tenantName": str(rule.get("xero_tenant_name") or ""),
                "matchType": str(rule.get("match_type") or "manual_override"),
                "confidenceOverride": float(_juksib_decimal(rule.get("confidence_override"))),
                "usageCount": int(rule.get("usage_count") or 0),
                "lastUsedAt": _iso(rule.get("last_used_at")) or "",
                "active": bool(rule.get("active")),
                "notes": str(rule.get("notes") or ""),
            }
            for rule in rules
            if isinstance(rule, dict)
        ],
    }


def _juksib_batch_is_lifecycle_completed(batch_row: dict | None) -> bool:
    row = batch_row if isinstance(batch_row, dict) else {}
    summary = row.get("summary") if isinstance(row.get("summary"), dict) else {}
    published = int(summary.get("published") or 0)
    failed = int(summary.get("failed") or 0)
    skipped = int(summary.get("skipped") or 0)
    batch_status = str(row.get("status") or "").strip().lower()
    if published > 0 and failed == 0:
        return True
    if published > 0 and failed > 0:
        return True
    if published == 0 and failed > 0:
        return True
    if published == 0 and failed == 0 and skipped > 0:
        return True
    return batch_status in {"completed", "published"}


async def juksib_delete_batch(user: dict, batch_id: str) -> dict:
    requested_batch_id = str(batch_id or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batches
                WHERE id::text = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (requested_batch_id, user["id"]),
            )
            batch_row = cursor.fetchone()
            if not batch_row:
                # Idempotent delete: stale client state or retries should not surface as hard failures.
                return {"deletedBatchId": requested_batch_id, "alreadyDeleted": True, **await juksib_list_batches(user, limit=30)}
            if _juksib_batch_is_lifecycle_completed(batch_row):
                raise HTTPException(
                    status_code=status.HTTP_409_CONFLICT,
                    detail="Only draft JUKSIB batches can be deleted.",
                )

            resolved_batch_id = str(batch_row.get("id") or requested_batch_id).strip()
            cursor.execute(
                """
                DELETE FROM juksib_batches
                WHERE id::text = %s
                  AND user_id = %s
                """,
                (resolved_batch_id, user["id"]),
            )
        connection.commit()

    batch_reference = str(batch_row.get("batch_reference") or "").strip()
    _juksib_record_audit(
        user_id=user["id"],
        # Batch row is deleted above; keep audit record detached from FK-linked batch_id.
        batch_id=None,
        entity_type="juksib_batch",
        entity_id=resolved_batch_id,
        action="batch_deleted",
        old_value={
            "batchReference": batch_reference,
            "status": str(batch_row.get("status") or ""),
            "summary": batch_row.get("summary") if isinstance(batch_row.get("summary"), dict) else {},
        },
        notes=f"Deleted batch {batch_reference or resolved_batch_id}.",
    )
    return {"deletedBatchId": resolved_batch_id, **await juksib_list_batches(user, limit=30)}


async def juksib_revert_batch_to_draft(user: dict, batch_id: str) -> dict:
    requested_batch_id = str(batch_id or "").strip()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batches
                WHERE id::text = %s
                  AND user_id = %s
                LIMIT 1
                """,
                (requested_batch_id, user["id"]),
            )
            batch_row = cursor.fetchone()
            if not batch_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="JUKSIB batch not found.")
            if not _juksib_batch_is_lifecycle_completed(batch_row):
                raise HTTPException(
                    status_code=status.HTTP_409_CONFLICT,
                    detail="Only completed JUKSIB batches can be reverted to draft.",
                )
            resolved_batch_id = str(batch_row.get("id") or requested_batch_id).strip()
            cursor.execute(
                """
                UPDATE juksib_batches
                SET status = 'draft',
                    updated_at = %s
                WHERE id::text = %s
                  AND user_id = %s
                """,
                (utcnow(), resolved_batch_id, user["id"]),
            )
        connection.commit()

    batch_reference = str(batch_row.get("batch_reference") or "").strip()
    _juksib_record_audit(
        user_id=user["id"],
        batch_id=resolved_batch_id,
        entity_type="juksib_batch",
        entity_id=resolved_batch_id,
        action="batch_reverted_to_draft",
        old_value={
            "batchReference": batch_reference,
            "status": str(batch_row.get("status") or ""),
            "summary": batch_row.get("summary") if isinstance(batch_row.get("summary"), dict) else {},
        },
        new_value={
            "status": "draft",
        },
        notes=f"Reverted batch {batch_reference or resolved_batch_id} to draft from settings.",
    )
    return {"revertedBatchId": resolved_batch_id, **await juksib_list_batches(user, limit=30)}


async def juksib_bulk_update_invoice_status(user: dict, batch_id: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    status_value = str(payload.get("status") or "").strip()
    if status_value not in {"approved", "skipped", "retry_pending", "needs_review", "manually_excluded"}:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invalid JUKSIB status update request.")
    invoice_ids = [str(item).strip() for item in (payload.get("invoiceIds") or []) if str(item).strip()]
    if not invoice_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one invoice.")
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE juksib_batch_invoices
                SET status = %s,
                    approved_by_user_id = CASE WHEN %s = 'approved' THEN %s ELSE approved_by_user_id END,
                    approved_at = CASE WHEN %s = 'approved' THEN NOW() ELSE approved_at END,
                    updated_at = NOW()
                WHERE batch_id = %s
                  AND user_id = %s
                  AND id = ANY(%s::uuid[])
                  AND status NOT IN ('published', 'duplicate')
                """,
                (status_value, status_value, user["id"], status_value, batch_id, user["id"], invoice_ids),
            )
            updated_count = cursor.rowcount or 0
        connection.commit()
    _juksib_record_audit(
        user_id=user["id"],
        batch_id=batch_id,
        entity_type="juksib_batch",
        entity_id=batch_id,
        action="bulk_status_update",
        new_value={"status": status_value, "invoiceCount": updated_count},
        notes=f"Updated {updated_count} invoice(s) to {status_value}.",
    )
    response = await juksib_get_batch(user, batch_id)
    response["updatedCount"] = updated_count
    return response


async def juksib_include_excluded_invoices(user: dict, batch_id: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    selected_invoice_ids = [str(item).strip() for item in (payload.get("invoiceIds") or []) if str(item).strip()]
    if not selected_invoice_ids:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Select at least one excluded invoice.")
    target_tenant_id = str(payload.get("tenantId") or "").strip()

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batches
                WHERE id = %s::uuid
                  AND user_id = %s::uuid
                LIMIT 1
                """,
                (batch_id, user["id"]),
            )
            batch_row = cursor.fetchone()
            if not batch_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="JUKSIB batch not found.")
            if _juksib_batch_is_lifecycle_completed(batch_row):
                raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="Completed batches are read-only.")
            metadata = batch_row.get("metadata") if isinstance(batch_row.get("metadata"), dict) else {}
            excluded_rows = metadata.get("excludedInvoices") if isinstance(metadata.get("excludedInvoices"), list) else []
            excluded_by_id = {
                str(row.get("juk_xero_invoice_id") or "").strip(): row
                for row in excluded_rows
                if isinstance(row, dict) and str(row.get("juk_xero_invoice_id") or "").strip()
            }
            selected_rows = [excluded_by_id.get(invoice_id) for invoice_id in selected_invoice_ids if excluded_by_id.get(invoice_id)]
            if not selected_rows:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Selected invoices are not available in exclusions.")
        connection.commit()

    _, sub_connections = _juksib_master_and_sub_connections(user)
    mappings_by_tenant: dict[str, dict] = {}
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute("SELECT * FROM xero_tenant_company_mappings")
            for mapping in (cursor.fetchall() or []):
                tenant_key = str(mapping.get("tenant_id") or "").strip()
                if tenant_key:
                    mappings_by_tenant[tenant_key] = mapping
        connection.commit()
    candidates = []
    for row in sub_connections:
        tenant_id = str(row.get("tenant_id") or "").strip()
        if not tenant_id:
            continue
        tenant_name = str(row.get("tenant_name") or "").strip()
        mapping = mappings_by_tenant.get(tenant_id, {})
        company_name = str(mapping.get("company_name") or "").strip()
        client_name = str(mapping.get("client_name") or "").strip()
        company_number = str(mapping.get("company_number") or "").strip()
        aliases = [alias for alias in [tenant_name, company_name, client_name] if alias]
        active_state = str(row.get("status") or "").strip().lower() not in {"disconnected", "inactive"}
        candidates.append(
            {
                "tenant_id": tenant_id,
                "tenant_name": tenant_name,
                "client_id": str(row.get("client_id") or tenant_id).strip() or tenant_id,
                "client_name": client_name,
                "company_name": company_name,
                "company_number": company_number,
                "aliases": aliases,
                "active": active_state,
            }
        )

    rules: list[dict] = []
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_match_rules
                WHERE user_id = %s
                  AND active = TRUE
                ORDER BY updated_at DESC, created_at DESC
                """,
                (user["id"],),
            )
            rules = cursor.fetchall() or []
        connection.commit()

    match_cache: dict[str, dict] = {}
    inserted_count = 0
    with get_connection() as connection:
        with connection.cursor() as cursor:
            for raw_row in selected_rows:
                row = raw_row if isinstance(raw_row, dict) else {}
                source_invoice_id = str(row.get("juk_xero_invoice_id") or "").strip()
                if not source_invoice_id:
                    continue
                cursor.execute(
                    """
                    SELECT id
                    FROM juksib_batch_invoices
                    WHERE batch_id = %s::uuid
                      AND user_id = %s::uuid
                      AND juk_xero_invoice_id = %s
                    LIMIT 1
                    """,
                    (batch_id, user["id"], source_invoice_id),
                )
                if cursor.fetchone():
                    continue

                if target_tenant_id:
                    target_connection = xero_connection_for_user_tenant(user, target_tenant_id, include_fallback=False)
                    match_row = {
                        "status": "approved",
                        "matched_rule_id": "",
                        "matched_client_id": target_tenant_id,
                        "matched_xero_tenant_id": target_tenant_id,
                        "matched_xero_tenant_name": str(target_connection.get("tenant_name") or "").strip(),
                        "match_source": "manual_include_exclusion",
                        "match_confidence": Decimal("1"),
                        "match_reason": "Included from excluded invoice list by user selection.",
                        "alternatives": [],
                    }
                else:
                    contact_name = str(row.get("juk_contact_name") or "").strip()
                    cache_key = _juksib_normalise_name(contact_name) or contact_name.lower()
                    if cache_key and cache_key in match_cache:
                        match_row = dict(match_cache[cache_key])
                    else:
                        match_row = await _juksib_match_invoice(
                            user=user,
                            contact_name=contact_name,
                            rules=rules,
                            candidates=candidates,
                            allow_openai=True,
                        )
                        if cache_key:
                            match_cache[cache_key] = dict(match_row)

                duplicate_flag = False
                if match_row.get("matched_xero_tenant_id"):
                    cursor.execute(
                        """
                        SELECT id
                        FROM juksib_sync_records
                        WHERE user_id = %s
                          AND juk_xero_invoice_id = %s
                          AND destination_tenant_id = %s
                          AND sync_status = 'published'
                        LIMIT 1
                        """,
                        (
                            user["id"],
                            source_invoice_id,
                            str(match_row.get("matched_xero_tenant_id") or ""),
                        ),
                    )
                    duplicate_flag = bool(cursor.fetchone())
                status_value = str(match_row.get("status") or "imported")
                if duplicate_flag:
                    status_value = "duplicate"

                cursor.execute(
                    """
                    INSERT INTO juksib_batch_invoices (
                        batch_id, user_id, juk_xero_invoice_id, juk_invoice_number, juk_contact_id, juk_contact_name,
                        invoice_date, due_date, subtotal, vat_total, total, amount_due, currency, line_items, raw_xero_payload,
                        pdf_file_reference, status, duplicate_flag, matched_client_id, matched_xero_tenant_id, matched_xero_tenant_name,
                        match_source, match_confidence, match_reason, alternatives, created_at, updated_at
                    )
                    VALUES (
                        %s::uuid, %s::uuid, %s, %s, %s, %s, %s::date, %s::date, %s, %s, %s, %s, %s, %s::jsonb, %s::jsonb,
                        %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, NOW(), NOW()
                    )
                    """,
                    (
                        batch_id,
                        user["id"],
                        source_invoice_id,
                        str(row.get("juk_invoice_number") or ""),
                        str(row.get("juk_contact_id") or ""),
                        str(row.get("juk_contact_name") or ""),
                        _parse_optional_iso_date(row.get("invoice_date")),
                        _parse_optional_iso_date(row.get("due_date")),
                        _juksib_decimal(row.get("subtotal")),
                        _juksib_decimal(row.get("vat_total")),
                        _juksib_decimal(row.get("total")),
                        _juksib_decimal(row.get("amount_due")),
                        str(row.get("currency") or "GBP"),
                        json.dumps(row.get("line_items") or [], default=_json_default),
                        json.dumps(row.get("raw_xero_payload") or {}, default=_json_default),
                        str(row.get("pdf_file_reference") or f"/api/juksib/source-invoices/{source_invoice_id}/pdf"),
                        status_value,
                        duplicate_flag,
                        str(match_row.get("matched_client_id") or ""),
                        str(match_row.get("matched_xero_tenant_id") or ""),
                        str(match_row.get("matched_xero_tenant_name") or ""),
                        str(match_row.get("match_source") or ""),
                        _juksib_decimal(match_row.get("match_confidence")),
                        str(match_row.get("match_reason") or "Included from excluded invoice list."),
                        json.dumps(match_row.get("alternatives") or [], default=_json_default),
                    ),
                )
                inserted_count += 1

            remaining_excluded = [
                row for row in excluded_rows
                if str((row or {}).get("juk_xero_invoice_id") or "").strip() not in set(selected_invoice_ids)
            ]
            cursor.execute(
                """
                SELECT *
                FROM juksib_batch_invoices
                WHERE batch_id = %s::uuid
                  AND user_id = %s::uuid
                """,
                (batch_id, user["id"]),
            )
            current_rows = cursor.fetchall() or []
            summary = _juksib_build_summary(current_rows)
            next_metadata = metadata if isinstance(metadata, dict) else {}
            next_metadata["excludedInvoices"] = remaining_excluded[:300]
            next_metadata["excludedInvoiceCount"] = len(remaining_excluded)
            cursor.execute(
                """
                UPDATE juksib_batches
                SET metadata = %s::jsonb,
                    summary = %s::jsonb,
                    updated_at = NOW()
                WHERE id = %s::uuid
                  AND user_id = %s::uuid
                """,
                (
                    json.dumps(next_metadata, default=_json_default),
                    json.dumps(summary, default=_json_default),
                    batch_id,
                    user["id"],
                ),
            )
        connection.commit()

    _juksib_record_audit(
        user_id=user["id"],
        batch_id=batch_id,
        entity_type="juksib_batch",
        entity_id=batch_id,
        action="included_excluded_invoices",
        new_value={"includedCount": inserted_count},
        notes=f"Included {inserted_count} invoice(s) from excluded list.",
    )
    response = await juksib_get_batch(user, batch_id)
    response["includedCount"] = inserted_count
    return response


async def juksib_apply_override(user: dict, batch_id: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    invoice_id = str(payload.get("invoiceId") or "").strip()
    tenant_id = str(payload.get("tenantId") or "").strip()
    save_rule = bool(payload.get("saveRule"))
    apply_similar = bool(payload.get("applySimilar"))
    exclude_only = bool(payload.get("excludeOnly"))
    notes = str(payload.get("note") or "").strip()
    if not invoice_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Invoice selection is required.")

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batch_invoices
                WHERE batch_id = %s
                  AND user_id = %s
                  AND id = %s::uuid
                LIMIT 1
                """,
                (batch_id, user["id"], invoice_id),
            )
            invoice_row = cursor.fetchone()
            if not invoice_row:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Invoice not found in selected batch.")
            normalized = _juksib_normalise_name(invoice_row.get("juk_contact_name"))
            target_tenant_name = ""
            if tenant_id:
                target_connection = xero_connection_for_user_tenant(user, tenant_id, include_fallback=False)
                target_tenant_name = str(target_connection.get("tenant_name") or "").strip()
            if exclude_only:
                cursor.execute(
                    """
                    UPDATE juksib_batch_invoices
                    SET status = 'manually_excluded',
                        match_source = 'manual_exclusion',
                        match_reason = %s,
                        matched_client_id = '',
                        matched_xero_tenant_id = '',
                        matched_xero_tenant_name = '',
                        alternatives = '[]'::jsonb,
                        updated_at = NOW()
                    WHERE batch_id = %s
                      AND user_id = %s
                      AND id = %s::uuid
                    """,
                    (notes or "Marked as not connected.", batch_id, user["id"], invoice_id),
                )
            else:
                if not tenant_id:
                    raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Destination tenant is required.")
                update_filter = """
                    batch_id = %s
                    AND user_id = %s
                    AND id = %s::uuid
                """
                params: list[object] = [batch_id, user["id"], invoice_id]
                if apply_similar and normalized:
                    update_filter = """
                        batch_id = %s
                        AND user_id = %s
                        AND (
                            id = %s::uuid
                            OR REGEXP_REPLACE(LOWER(juk_contact_name), '[^a-z0-9]+', ' ', 'g') = %s
                        )
                        AND status IN ('needs_review', 'unmatched', 'failed', 'retry_pending', 'imported')
                    """
                    params.append(normalized)
                cursor.execute(
                    f"""
                    UPDATE juksib_batch_invoices
                    SET status = 'approved',
                        matched_client_id = %s,
                        matched_xero_tenant_id = %s,
                        matched_xero_tenant_name = %s,
                        match_source = 'manual_override',
                        match_confidence = 1,
                        match_reason = %s,
                        approved_by_user_id = %s,
                        approved_at = NOW(),
                        error_message = '',
                        updated_at = NOW()
                    WHERE {update_filter}
                    """,
                    (
                        tenant_id,
                        tenant_id,
                        target_tenant_name,
                        notes or "Manual override applied.",
                        user["id"],
                        *params,
                    ),
                )

            if save_rule and normalized:
                rule_type = "exclude" if exclude_only else "manual_override"
                match_tenant_id = "" if exclude_only else tenant_id
                cursor.execute(
                    """
                    SELECT id
                    FROM juksib_match_rules
                    WHERE user_id = %s
                      AND normalised_invoice_name = %s
                      AND match_type = %s
                      AND xero_tenant_id = %s
                    LIMIT 1
                    """,
                    (user["id"], normalized, rule_type, match_tenant_id),
                )
                existing_rule = cursor.fetchone()
                if existing_rule:
                    cursor.execute(
                        """
                        UPDATE juksib_match_rules
                        SET original_invoice_name = %s,
                            client_id = %s,
                            xero_tenant_name = %s,
                            confidence_override = %s,
                            usage_count = usage_count + 1,
                            last_used_at = NOW(),
                            active = TRUE,
                            notes = %s,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                          AND user_id = %s
                        """,
                        (
                            str(invoice_row.get("juk_contact_name") or ""),
                            "" if exclude_only else tenant_id,
                            "" if exclude_only else target_tenant_name,
                            Decimal("1"),
                            notes,
                            str(existing_rule.get("id") or ""),
                            user["id"],
                        ),
                    )
                else:
                    cursor.execute(
                        """
                        INSERT INTO juksib_match_rules (
                            user_id,
                            normalised_invoice_name,
                            original_invoice_name,
                            client_id,
                            xero_tenant_id,
                            xero_tenant_name,
                            match_type,
                            confidence_override,
                            usage_count,
                            last_used_at,
                            active,
                            notes,
                            created_by_user_id,
                            updated_at
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 1, NOW(), TRUE, %s, %s, NOW())
                        """,
                        (
                            user["id"],
                            normalized,
                            str(invoice_row.get("juk_contact_name") or ""),
                            "" if exclude_only else tenant_id,
                            "" if exclude_only else tenant_id,
                            "" if exclude_only else target_tenant_name,
                            rule_type,
                            Decimal("1"),
                            notes,
                            user["id"],
                        ),
                    )
        connection.commit()

    _juksib_record_audit(
        user_id=user["id"],
        batch_id=batch_id,
        entity_type="juksib_invoice",
        entity_id=invoice_id,
        action="manual_override" if not exclude_only else "manual_exclusion",
        notes=notes,
    )
    return await juksib_get_batch(user, batch_id)


def _juksib_invoice_exists_in_destination(rows: list[dict], invoice_number: str) -> bool:
    target_number = str(invoice_number or "").strip().lower()
    if not target_number:
        return False
    for row in rows:
        number = str(row.get("InvoiceNumber") or row.get("InvoiceNumberFormatted") or "").strip().lower()
        if number == target_number:
            return True
    return False


def _juksib_destination_invoice_id(rows: list[dict], invoice_number: str) -> str:
    target_number = str(invoice_number or "").strip().lower()
    if not target_number:
        return ""
    for row in rows:
        number = str(row.get("InvoiceNumber") or row.get("InvoiceNumberFormatted") or "").strip().lower()
        if number == target_number:
            return str(row.get("InvoiceID") or row.get("InvoiceId") or "").strip()
    return ""


def _juksib_extract_created_bill_id(created_payload: dict | None) -> tuple[str, str]:
    payload = created_payload if isinstance(created_payload, dict) else {}
    invoice_row = {}
    invoices = payload.get("Invoices")
    if isinstance(invoices, list) and invoices:
        first_invoice = invoices[0]
        if isinstance(first_invoice, dict):
            invoice_row = first_invoice
    invoice_id = str(invoice_row.get("InvoiceID") or invoice_row.get("InvoiceId") or "").strip()
    has_errors = bool(payload.get("HasErrors")) or bool(invoice_row.get("HasErrors"))
    validation_messages: list[str] = []
    for key in ("ValidationErrors", "Warnings"):
        values = invoice_row.get(key)
        if not isinstance(values, list):
            continue
        for item in values:
            if not isinstance(item, dict):
                continue
            message = str(item.get("Message") or item.get("message") or "").strip()
            if message:
                validation_messages.append(message)
    for key in ("Message", "message"):
        value = str(invoice_row.get(key) or payload.get(key) or "").strip()
        if value:
            validation_messages.append(value)
    deduped_messages: list[str] = []
    for message in validation_messages:
        if message not in deduped_messages:
            deduped_messages.append(message)
    if has_errors:
        detail = ". ".join(deduped_messages[:3]).strip()
        return "", f"Xero rejected bill creation{': ' + detail if detail else '.'}"
    if not invoice_id:
        detail = ". ".join(deduped_messages[:3]).strip()
        return "", f"Xero did not return a created bill id{': ' + detail if detail else '.'}"
    return invoice_id, ""


def _juksib_is_purchase_account(account_row: dict) -> bool:
    account_type = str(account_row.get("Type") or "").strip().upper()
    if account_type in {"EXPENSE", "DIRECTCOSTS", "OVERHEADS"}:
        return True
    return False


def _juksib_account_name_score(name: str) -> Decimal:
    weighted_candidates = (
        ("audit and accountancy fees", Decimal("1.00")),
        ("accountancy fees", Decimal("0.95")),
        ("audit fees", Decimal("0.92")),
        ("professional fees", Decimal("0.86")),
        ("legal and professional fees", Decimal("0.84")),
        ("accounting fees", Decimal("0.90")),
    )
    return max((_juksib_similarity(name, candidate) * weight for candidate, weight in weighted_candidates), default=Decimal("0"))


async def _juksib_openai_pick_purchase_account(
    *,
    user: dict,
    destination_connection: dict,
    purchase_accounts: list[dict],
    fallback_code: str,
) -> dict | None:
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip() or not purchase_accounts:
        return None

    candidates: list[dict] = []
    for row in purchase_accounts[:120]:
        if not isinstance(row, dict):
            continue
        code = str(row.get("Code") or "").strip()
        if not code:
            continue
        candidates.append(
            {
                "code": code,
                "name": str(row.get("Name") or "").strip(),
                "type": str(row.get("Type") or "").strip().upper(),
                "class": str(row.get("Class") or "").strip().upper(),
                "description": str(row.get("Description") or "").strip(),
            }
        )
    if not candidates:
        return None

    request_body = {
        "model": settings.openai_model,
        "input": [
            {
                "role": "system",
                "content": (
                    "You choose the best Xero nominal account for supplier bills. "
                    "Prioritise accountancy/professional fees style expense accounts. "
                    "Return strict JSON only."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(
                    {
                        "task": "Select the best purchase account nominal code for posting accountancy invoices.",
                        "supplier_name": JUKSIB_DEFAULT_SUPPLIER_NAME,
                        "fallback_account_code": fallback_code,
                        "tenant_id": str(destination_connection.get("tenant_id") or ""),
                        "tenant_name": str(destination_connection.get("tenant_name") or ""),
                        "accounts": candidates,
                        "rules": {
                            "prefer": [
                                "accountancy fees",
                                "professional fees",
                                "legal and professional fees",
                                "audit fees",
                            ],
                            "must_return_code_from_list": True,
                            "use_fallback_if_unsure": True,
                        },
                    },
                    default=_json_default,
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "juksib_purchase_account_selection",
                "strict": True,
                "schema": JUKSIB_PURCHASE_ACCOUNT_SELECTION_RESPONSE_SCHEMA,
            }
        },
    }
    try:
        response_payload = await _post_openai_responses(
            request_body,
            purpose="JUKSIB purchase account selection",
            feature="juksib",
            page="juk-invoices",
            user_id=user["id"],
            timeout_seconds=JUKSIB_OPENAI_MATCH_TIMEOUT_SECONDS,
        )
        return _load_openai_json_response(
            response_payload,
            "OpenAI returned invalid JSON for JUKSIB purchase account selection.",
        )
    except Exception:
        logger.exception(
            "JUKSIB: OpenAI purchase account selection failed for tenant %s",
            destination_connection.get("tenant_id"),
        )
        return None


async def _juksib_resolve_purchase_account_code(
    user: dict,
    destination_connection: dict,
    fallback_code: str,
) -> tuple[str, str]:
    fallback = str(fallback_code or JUKSIB_DEFAULT_PURCHASE_ACCOUNT_CODE).strip() or JUKSIB_DEFAULT_PURCHASE_ACCOUNT_CODE
    try:
        accounts = await fetch_paginated_collection(
            destination_connection,
            ACCOUNTS_URL,
            "Accounts",
            params={"where": 'Status=="ACTIVE"', "order": "Code ASC"},
            max_pages=5,
        )
    except Exception:
        logger.exception("JUKSIB: Unable to fetch destination chart of accounts for tenant %s", destination_connection.get("tenant_id"))
        return fallback, ""

    purchase_accounts = [row for row in accounts if isinstance(row, dict) and _juksib_is_purchase_account(row)]
    if not purchase_accounts:
        return fallback, ""

    by_code: dict[str, dict] = {
        str(row.get("Code") or "").strip(): row
        for row in purchase_accounts
        if str(row.get("Code") or "").strip()
    }
    fallback_row = by_code.get(fallback)
    best = max(
        purchase_accounts,
        key=lambda row: (
            _juksib_account_name_score(str(row.get("Name") or "")),
            Decimal("1") if str(row.get("Code") or "").strip() == fallback else Decimal("0"),
        ),
    )
    best_code = str(best.get("Code") or "").strip() or fallback
    best_name = str(best.get("Name") or "").strip()
    best_score = _juksib_account_name_score(str(best.get("Name") or ""))
    should_ask_openai = bool(user) and (not fallback_row or best_score < Decimal("0.82"))
    if should_ask_openai:
        openai_selection = await _juksib_openai_pick_purchase_account(
            user=user,
            destination_connection=destination_connection,
            purchase_accounts=purchase_accounts,
            fallback_code=fallback,
        )
        if openai_selection:
            selected_code = str(openai_selection.get("suggested_account_code") or "").strip()
            selected_row = by_code.get(selected_code)
            if selected_row:
                selected_name = str(selected_row.get("Name") or "").strip()
                return selected_code, selected_name

    if best_code:
        return best_code, best_name
    if fallback_row:
        return fallback, str(fallback_row.get("Name") or "").strip()
    return fallback, ""


async def _juksib_resolve_supplier_contact_id(
    destination_connection: dict,
    supplier_name: str,
) -> str:
    def has_populated_address(contact_row: dict) -> bool:
        addresses = contact_row.get("Addresses")
        if not isinstance(addresses, list):
            return False
        for address in addresses:
            if not isinstance(address, dict):
                continue
            for key in ("AddressLine1", "AddressLine2", "AddressLine3", "City", "PostalCode"):
                if str(address.get(key) or "").strip():
                    return True
        return False

    supplier = str(supplier_name or "").strip()
    if not supplier:
        return ""
    try:
        contacts = await fetch_paginated_collection(
            destination_connection,
            CONTACTS_URL,
            "Contacts",
            params={"where": f'Name=="{supplier}"', "order": "Name ASC"},
            max_pages=2,
        )
    except Exception:
        logger.exception("JUKSIB: Unable to lookup supplier contact for tenant %s", destination_connection.get("tenant_id"))
        return ""
    for contact in contacts:
        if not isinstance(contact, dict):
            continue
        if str(contact.get("Name") or "").strip().lower() == supplier.lower():
            contact_id = str(contact.get("ContactID") or contact.get("ContactId") or "").strip()
            if contact_id and not has_populated_address(contact):
                try:
                    await upsert_contact(
                        destination_connection,
                        {
                            "ContactID": contact_id,
                            "Name": supplier,
                            "Addresses": [JUKSIB_DEFAULT_SUPPLIER_ADDRESS],
                        },
                        idempotency_key=f"juksib-supplier-address-{destination_connection.get('tenant_id')}-{contact_id}",
                    )
                except Exception:
                    logger.exception(
                        "JUKSIB: Unable to auto-populate supplier address for contact %s on tenant %s",
                        contact_id,
                        destination_connection.get("tenant_id"),
                    )
            return contact_id
    return ""


def _juksib_register_display_name(row: dict) -> str:
    return str(row.get("company_name") or row.get("client_name") or "").strip()


def _juksib_clean_vat_number(value: object) -> str:
    return re.sub(r"[^A-Za-z0-9]+", "", str(value or "").strip().upper())


def _juksib_default_vat_profile(client_name: str, lookup_source: str, lookup_reason: str) -> dict:
    return {
        "clientName": str(client_name or "").strip(),
        "vatRegistered": False,
        "vatNumber": "",
        "taxType": JUKSIB_NO_VAT_TAX_TYPE,
        "lookupSource": lookup_source,
        "lookupReason": lookup_reason,
        "lookupConfidence": 0.0,
        "registerId": "",
        "registerName": "",
    }


def _juksib_fetch_client_register_rows_for_vat() -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, company_name, client_name, client_id, company_number, vat_number
                FROM ch_auth_code_register
                ORDER BY uploaded_at DESC
                LIMIT 5000
                """
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return rows


def _juksib_build_vat_register_index(register_rows: list[dict]) -> dict:
    def should_replace(existing: dict | None, candidate: dict | None) -> bool:
        if not isinstance(candidate, dict):
            return False
        if not isinstance(existing, dict):
            return True
        existing_has_vat = bool(_juksib_clean_vat_number(existing.get("vat_number")))
        candidate_has_vat = bool(_juksib_clean_vat_number(candidate.get("vat_number")))
        if candidate_has_vat and not existing_has_vat:
            return True
        return False

    by_client_id: dict[str, dict] = {}
    by_name: dict[str, dict] = {}
    by_id: dict[str, dict] = {}
    for row in register_rows:
        row_id = str(row.get("id") or "").strip()
        if row_id:
            by_id[row_id] = row
        client_id_key = str(row.get("client_id") or "").strip().lower()
        if client_id_key and should_replace(by_client_id.get(client_id_key), row):
            by_client_id[client_id_key] = row
        name_key = _bm_tasks_normalise_name_key(_juksib_register_display_name(row))
        if name_key and should_replace(by_name.get(name_key), row):
            by_name[name_key] = row
    return {"rows": register_rows, "byClientId": by_client_id, "byName": by_name, "byId": by_id}


def _juksib_find_register_row_for_invoice(
    *,
    contact_name: str,
    matched_client_id: str,
    register_index: dict,
) -> dict | None:
    register_rows = register_index.get("rows") if isinstance(register_index.get("rows"), list) else []
    by_client_id = register_index.get("byClientId") if isinstance(register_index.get("byClientId"), dict) else {}
    by_name = register_index.get("byName") if isinstance(register_index.get("byName"), dict) else {}

    matched_client_id_key = str(matched_client_id or "").strip().lower()
    if matched_client_id_key and matched_client_id_key in by_client_id:
        return by_client_id.get(matched_client_id_key)

    contact_name_key = _bm_tasks_normalise_name_key(contact_name)
    if contact_name_key and contact_name_key in by_name:
        return by_name.get(contact_name_key)

    if not contact_name or not register_rows:
        return None
    scored_rows = sorted(
        (
            {
                "row": row,
                "score": _juksib_similarity(contact_name, _juksib_register_display_name(row)),
            }
            for row in register_rows
            if _juksib_register_display_name(row)
        ),
        key=lambda item: item["score"],
        reverse=True,
    )
    if not scored_rows:
        return None
    top = scored_rows[0]
    second = scored_rows[1] if len(scored_rows) > 1 else {"score": Decimal("0")}
    if top["score"] >= Decimal("0.82") and (top["score"] - second["score"]) >= Decimal("0.12"):
        return top["row"]
    return None


def _juksib_payment_status_from_amounts(total_value: object, amount_due_value: object) -> str:
    total = _juksib_decimal(total_value)
    amount_due = _juksib_decimal(amount_due_value)
    if amount_due <= Decimal("0.01"):
        return "paid"
    if total > Decimal("0.01") and amount_due >= (total - Decimal("0.01")):
        return "unpaid"
    return "part_paid"


def _juksib_upsert_client_page_invoice_copy(
    *,
    register_row_id: str,
    batch_id: str,
    row_payload: dict,
    source_status: str,
    sync_status: str,
    destination_tenant_id: str = "",
    destination_tenant_name: str = "",
    destination_bill_id: str = "",
    last_error: str = "",
) -> None:
    safe_register_row_id = str(register_row_id or "").strip()
    if not safe_register_row_id:
        return
    source_invoice_id = str(row_payload.get("juk_xero_invoice_id") or row_payload.get("jukXeroInvoiceId") or "").strip()
    if not source_invoice_id:
        return
    invoice_number = str(row_payload.get("juk_invoice_number") or row_payload.get("jukInvoiceNumber") or "").strip()
    contact_name = str(row_payload.get("juk_contact_name") or row_payload.get("jukContactName") or "").strip()
    invoice_date = row_payload.get("invoice_date") or row_payload.get("invoiceDate")
    due_date = row_payload.get("due_date") or row_payload.get("dueDate")
    total = _juksib_decimal(row_payload.get("total"))
    amount_due = _juksib_decimal(row_payload.get("amount_due") or row_payload.get("amountDue"))
    currency = str(row_payload.get("currency") or row_payload.get("currencyCode") or "GBP").strip() or "GBP"
    payment_status = _juksib_payment_status_from_amounts(total, amount_due)
    source_payload = row_payload.get("raw_xero_payload") if isinstance(row_payload.get("raw_xero_payload"), dict) else (
        row_payload.get("rawPayload") if isinstance(row_payload.get("rawPayload"), dict) else {}
    )

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO ch_auth_register_client_juk_invoices (
                    register_row_id,
                    batch_id,
                    juk_xero_invoice_id,
                    juk_invoice_number,
                    juk_contact_name,
                    invoice_date,
                    due_date,
                    total,
                    amount_due,
                    currency,
                    payment_status,
                    source_status,
                    sync_status,
                    destination_tenant_id,
                    destination_tenant_name,
                    destination_bill_id,
                    last_error,
                    source_payload,
                    created_at,
                    updated_at
                )
                VALUES (
                    %s::uuid, NULLIF(%s, '')::uuid, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, NOW(), NOW()
                )
                ON CONFLICT (register_row_id, juk_xero_invoice_id)
                DO UPDATE SET
                    batch_id = EXCLUDED.batch_id,
                    juk_invoice_number = EXCLUDED.juk_invoice_number,
                    juk_contact_name = EXCLUDED.juk_contact_name,
                    invoice_date = EXCLUDED.invoice_date,
                    due_date = EXCLUDED.due_date,
                    total = EXCLUDED.total,
                    amount_due = EXCLUDED.amount_due,
                    currency = EXCLUDED.currency,
                    payment_status = EXCLUDED.payment_status,
                    source_status = EXCLUDED.source_status,
                    sync_status = EXCLUDED.sync_status,
                    destination_tenant_id = EXCLUDED.destination_tenant_id,
                    destination_tenant_name = EXCLUDED.destination_tenant_name,
                    destination_bill_id = EXCLUDED.destination_bill_id,
                    last_error = EXCLUDED.last_error,
                    source_payload = EXCLUDED.source_payload,
                    updated_at = NOW()
                """,
                (
                    safe_register_row_id,
                    str(batch_id or ""),
                    source_invoice_id,
                    invoice_number,
                    contact_name,
                    invoice_date,
                    due_date,
                    total,
                    amount_due,
                    currency,
                    payment_status,
                    str(source_status or "imported").strip() or "imported",
                    str(sync_status or "pending").strip() or "pending",
                    str(destination_tenant_id or "").strip(),
                    str(destination_tenant_name or "").strip(),
                    str(destination_bill_id or "").strip(),
                    str(last_error or "").strip()[:2000],
                    json.dumps(source_payload, default=_json_default),
                ),
            )
        connection.commit()


def _juksib_cached_vat_profile(user_id: str, normalised_client_name: str) -> dict | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT source_client_name,
                       register_id,
                       register_name,
                       vat_number,
                       vat_registered,
                       lookup_source,
                       lookup_confidence,
                       lookup_reason
                FROM juksib_vat_lookup_cache
                WHERE user_id = %s::uuid
                  AND normalised_client_name = %s
                LIMIT 1
                """,
                (user_id, normalised_client_name),
            )
            row = cursor.fetchone()
        connection.commit()
    if not row:
        return None
    vat_registered = bool(row.get("vat_registered"))
    return {
        "clientName": str(row.get("source_client_name") or "").strip(),
        "vatRegistered": vat_registered,
        "vatNumber": str(row.get("vat_number") or "").strip(),
        "taxType": JUKSIB_EXPENSES_VAT_TAX_TYPE if vat_registered else JUKSIB_NO_VAT_TAX_TYPE,
        "lookupSource": str(row.get("lookup_source") or "cache").strip() or "cache",
        "lookupReason": str(row.get("lookup_reason") or "").strip(),
        "lookupConfidence": float(_juksib_decimal(row.get("lookup_confidence"))),
        "registerId": str(row.get("register_id") or "").strip(),
        "registerName": str(row.get("register_name") or "").strip(),
    }


def _juksib_upsert_vat_profile_cache(user_id: str, normalised_client_name: str, profile: dict) -> None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO juksib_vat_lookup_cache (
                    user_id,
                    normalised_client_name,
                    source_client_name,
                    register_id,
                    register_name,
                    vat_number,
                    vat_registered,
                    lookup_source,
                    lookup_confidence,
                    lookup_reason,
                    checked_at,
                    updated_at
                )
                VALUES (%s::uuid, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
                ON CONFLICT (user_id, normalised_client_name)
                DO UPDATE SET
                    source_client_name = EXCLUDED.source_client_name,
                    register_id = EXCLUDED.register_id,
                    register_name = EXCLUDED.register_name,
                    vat_number = EXCLUDED.vat_number,
                    vat_registered = EXCLUDED.vat_registered,
                    lookup_source = EXCLUDED.lookup_source,
                    lookup_confidence = EXCLUDED.lookup_confidence,
                    lookup_reason = EXCLUDED.lookup_reason,
                    checked_at = NOW(),
                    updated_at = NOW()
                """,
                (
                    user_id,
                    normalised_client_name,
                    str(profile.get("clientName") or "").strip(),
                    str(profile.get("registerId") or "").strip() or None,
                    str(profile.get("registerName") or "").strip(),
                    str(profile.get("vatNumber") or "").strip(),
                    bool(profile.get("vatRegistered")),
                    str(profile.get("lookupSource") or "").strip() or "register_exact",
                    float(_juksib_decimal(profile.get("lookupConfidence") or 0)),
                    str(profile.get("lookupReason") or "").strip(),
                ),
            )
        connection.commit()


async def _juksib_openai_match_register_for_vat(
    *,
    user: dict,
    client_name: str,
    register_rows: list[dict],
) -> dict | None:
    settings = get_settings()
    if not str(settings.openai_api_key or "").strip() or not register_rows:
        return None
    candidates = [
        {
            "register_id": str(row.get("id") or "").strip(),
            "register_name": _juksib_register_display_name(row),
            "client_id": str(row.get("client_id") or "").strip(),
            "company_number": str(row.get("company_number") or "").strip(),
            "vat_number": _juksib_clean_vat_number(row.get("vat_number")),
        }
        for row in register_rows[:80]
        if str(row.get("id") or "").strip()
    ]
    if not candidates:
        return None
    request_body = {
        "model": settings.openai_model,
        "input": [
            {
                "role": "system",
                "content": (
                    "You match a client name to rows in a UK client register. "
                    "Return strict JSON only."
                ),
            },
            {
                "role": "user",
                "content": json.dumps(
                    {
                        "invoice_client_name": client_name,
                        "register_candidates": candidates,
                        "instructions": {
                            "pick_best": True,
                            "confidence_scale": "0-1",
                            "return_empty_when_no_match": True,
                        },
                    },
                    default=_json_default,
                ),
            },
        ],
        "text": {
            "format": {
                "type": "json_schema",
                "name": "juksib_vat_lookup",
                "strict": True,
                "schema": JUKSIB_VAT_LOOKUP_RESPONSE_SCHEMA,
            }
        },
    }
    try:
        payload = await _post_openai_responses(
            request_body,
            purpose="JUKSIB VAT client register matching",
            feature="juksib",
            page="juk-invoices",
            user_id=user["id"],
            timeout_seconds=8,
        )
        return _load_openai_json_response(payload, "OpenAI returned invalid JSON for JUKSIB VAT lookup.")
    except Exception:
        logger.exception("JUKSIB: OpenAI VAT lookup failed for client '%s'", client_name)
        return None


async def _juksib_resolve_vat_profile(
    *,
    user: dict,
    client_name: str,
    matched_client_id: str,
    register_index: dict,
    run_cache: dict[str, dict],
) -> dict:
    contact_name = str(client_name or "").strip()
    normalised_client_name = _bm_tasks_normalise_name_key(contact_name) or _juksib_normalise_name(contact_name)
    if not normalised_client_name:
        return _juksib_default_vat_profile(contact_name, "empty_name", "Client name was empty; defaulted to no VAT.")
    if normalised_client_name in run_cache:
        return run_cache[normalised_client_name]

    cached_profile = _juksib_cached_vat_profile(user["id"], normalised_client_name)
    if cached_profile:
        run_cache[normalised_client_name] = cached_profile
        return cached_profile

    register_rows = register_index.get("rows") if isinstance(register_index.get("rows"), list) else []
    by_client_id = register_index.get("byClientId") if isinstance(register_index.get("byClientId"), dict) else {}
    by_name = register_index.get("byName") if isinstance(register_index.get("byName"), dict) else {}
    by_id = register_index.get("byId") if isinstance(register_index.get("byId"), dict) else {}

    matched_row = None
    lookup_source = "register_none"
    lookup_reason = "No client register row matched; defaulted to no VAT."
    lookup_confidence = Decimal("0")

    matched_client_id_key = str(matched_client_id or "").strip().lower()
    if matched_client_id_key and matched_client_id_key in by_client_id:
        matched_row = by_client_id.get(matched_client_id_key)
        lookup_source = "register_client_id"
        lookup_reason = "Matched using client id from the publish candidate."
        lookup_confidence = Decimal("1")
    if not matched_row:
        exact_name_row = by_name.get(normalised_client_name)
        if exact_name_row:
            matched_row = exact_name_row
            lookup_source = "register_exact"
            lookup_reason = "Exact client register name match."
            lookup_confidence = Decimal("0.99")
    if not matched_row and contact_name and register_rows:
        scored_rows = sorted(
            (
                {
                    "row": row,
                    "score": _juksib_similarity(contact_name, _juksib_register_display_name(row)),
                }
                for row in register_rows
                if _juksib_register_display_name(row)
            ),
            key=lambda item: item["score"],
            reverse=True,
        )
        if scored_rows:
            top = scored_rows[0]
            second = scored_rows[1] if len(scored_rows) > 1 else {"score": Decimal("0")}
            if top["score"] >= Decimal("0.82") and (top["score"] - second["score"]) >= Decimal("0.12"):
                matched_row = top["row"]
                lookup_source = "register_fuzzy"
                lookup_reason = "High-confidence fuzzy match against client register name."
                lookup_confidence = top["score"]

    if not matched_row and contact_name and register_rows:
        openai_match = await _juksib_openai_match_register_for_vat(
            user=user,
            client_name=contact_name,
            register_rows=register_rows,
        )
        if openai_match:
            suggested_id = str(openai_match.get("suggested_register_id") or "").strip()
            confidence = _juksib_decimal(openai_match.get("confidence"))
            suggested_row = by_id.get(suggested_id)
            if suggested_row and confidence >= Decimal("0.55"):
                matched_row = suggested_row
                lookup_source = "openai_register_lookup"
                lookup_reason = str(openai_match.get("reason") or "Matched by OpenAI against client register candidates.").strip()
                lookup_confidence = confidence

    if matched_row:
        vat_number = _juksib_clean_vat_number(matched_row.get("vat_number"))
        vat_registered = bool(vat_number)
        profile = {
            "clientName": contact_name,
            "vatRegistered": vat_registered,
            "vatNumber": vat_number,
            "taxType": JUKSIB_EXPENSES_VAT_TAX_TYPE if vat_registered else JUKSIB_NO_VAT_TAX_TYPE,
            "lookupSource": lookup_source,
            "lookupReason": lookup_reason,
            "lookupConfidence": float(lookup_confidence),
            "registerId": str(matched_row.get("id") or "").strip(),
            "registerName": _juksib_register_display_name(matched_row),
        }
    else:
        profile = _juksib_default_vat_profile(contact_name, lookup_source, lookup_reason)

    _juksib_upsert_vat_profile_cache(user["id"], normalised_client_name, profile)
    run_cache[normalised_client_name] = profile
    return profile


async def _juksib_add_destination_invoice_note(
    destination_connection: dict,
    destination_invoice_id: str,
    extra_notes: list[str] | None = None,
) -> tuple[bool, str]:
    invoice_id = str(destination_invoice_id or "").strip()
    if not invoice_id:
        return False, "Missing destination invoice id."
    try:
        await create_history_record(destination_connection, "Invoices", invoice_id, JUKSIB_IMPORT_HISTORY_NOTE)
        for note in extra_notes or []:
            note_text = str(note or "").strip()
            if note_text:
                await create_history_record(destination_connection, "Invoices", invoice_id, note_text)
        return True, ""
    except Exception as exc:
        logger.exception("JUKSIB: Failed to add history note for destination invoice %s", invoice_id)
        return False, _sync_error_message(exc)


async def juksib_publish_batch(user: dict, batch_id: str, payload: dict | None = None) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    selected_ids = [str(item).strip() for item in (payload.get("invoiceIds") or []) if str(item).strip()]
    default_account_code = str(payload.get("purchaseAccountCode") or JUKSIB_DEFAULT_PURCHASE_ACCOUNT_CODE).strip() or JUKSIB_DEFAULT_PURCHASE_ACCOUNT_CODE
    supplier_name = str(payload.get("supplierName") or JUKSIB_DEFAULT_SUPPLIER_NAME).strip() or JUKSIB_DEFAULT_SUPPLIER_NAME

    master_connection, _ = _juksib_master_and_sub_connections(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT mode
                FROM juksib_batches
                WHERE id = %s::uuid
                  AND user_id = %s::uuid
                LIMIT 1
                """,
                (batch_id, user["id"]),
            )
            batch_row = cursor.fetchone()
        connection.commit()
    if not batch_row:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="JUKSIB batch not found.")
    if str(batch_row.get("mode") or "test").strip().lower() != "live":
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="This batch is in test mode. Create/import a live batch before publishing to Xero.",
        )

    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_batch_invoices
                WHERE batch_id = %s
                  AND user_id = %s
                  AND status IN ('approved', 'retry_pending')
                  {selected_filter}
                ORDER BY created_at ASC
                """.format(selected_filter="AND id = ANY(%s::uuid[])" if selected_ids else ""),
                (batch_id, user["id"], selected_ids) if selected_ids else (batch_id, user["id"]),
            )
            invoice_rows = cursor.fetchall() or []
        connection.commit()

    if not invoice_rows:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="No approved JUKSIB invoices available for publish.")

    publish_result = {"published": 0, "failed": 0, "duplicates": 0, "partialFailed": 0, "rows": []}
    purchase_account_cache: dict[str, tuple[str, str]] = {}
    supplier_contact_cache: dict[str, str] = {}
    register_index = _juksib_build_vat_register_index(_juksib_fetch_client_register_rows_for_vat())
    vat_profile_cache: dict[str, dict] = {}
    for row in invoice_rows:
        invoice_id = str(row.get("id") or "")
        source_invoice_id = str(row.get("juk_xero_invoice_id") or "")
        matched_tenant_id = str(row.get("matched_xero_tenant_id") or "").strip()
        matched_client_id = str(row.get("matched_client_id") or "").strip()
        destination_tenant_id = matched_tenant_id or matched_client_id
        invoice_number = str(row.get("juk_invoice_number") or source_invoice_id)
        if not destination_tenant_id:
            publish_result["failed"] += 1
            publish_result["rows"].append({"invoiceId": invoice_id, "status": "failed", "message": "No destination tenant set."})
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_batch_invoices
                        SET status = 'failed',
                            error_message = %s,
                            retry_count = retry_count + 1,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                        """,
                        ("No destination tenant set.", invoice_id),
                    )
                connection.commit()
            continue

        try:
            destination_connection = xero_connection_for_user_tenant(user, destination_tenant_id, include_fallback=False)
        except Exception as exc:
            message = f"Destination tenant '{destination_tenant_id}' is not connected for this user."
            publish_result["failed"] += 1
            publish_result["rows"].append(
                {
                    "invoiceId": invoice_id,
                    "status": "failed",
                    "tenantId": destination_tenant_id,
                    "message": f"{message} {_sync_error_message(exc)}".strip(),
                }
            )
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_batch_invoices
                        SET status = 'failed',
                            error_message = %s,
                            retry_count = retry_count + 1,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                        """,
                        (message, invoice_id),
                    )
                connection.commit()
            continue
        if not matched_tenant_id and matched_client_id:
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_batch_invoices
                        SET matched_xero_tenant_id = %s,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                        """,
                        (destination_tenant_id, invoice_id),
                    )
                connection.commit()
        cached_supplier_contact_id = supplier_contact_cache.get(destination_tenant_id)
        if cached_supplier_contact_id is None:
            cached_supplier_contact_id = await _juksib_resolve_supplier_contact_id(destination_connection, supplier_name)
            supplier_contact_cache[destination_tenant_id] = cached_supplier_contact_id
        cached_account = purchase_account_cache.get(destination_tenant_id)
        if cached_account is None:
            cached_account = await _juksib_resolve_purchase_account_code(user, destination_connection, default_account_code)
            purchase_account_cache[destination_tenant_id] = cached_account
        target_account_code, target_account_name = cached_account
        vat_profile = await _juksib_resolve_vat_profile(
            user=user,
            client_name=str(row.get("juk_contact_name") or ""),
            matched_client_id=matched_client_id,
            register_index=register_index,
            run_cache=vat_profile_cache,
        )
        target_tax_type = str(vat_profile.get("taxType") or JUKSIB_NO_VAT_TAX_TYPE).strip() or JUKSIB_NO_VAT_TAX_TYPE
        vat_status_message = (
            f"VAT number found in client register; tax type {target_tax_type} applied."
            if bool(vat_profile.get("vatRegistered"))
            else f"No VAT number found in client register; tax type {target_tax_type} applied."
        )
        vat_history_note = (
            f"Because we hold a VAT number for this client, this transaction has been processed with VAT "
            f"using tax type ({target_tax_type})."
            if bool(vat_profile.get("vatRegistered"))
            else ""
        )
        no_vat_history_note = (
            f"Jenius AI could not find a VAT number in the client register for "
            f"'{str(vat_profile.get('registerName') or vat_profile.get('clientName') or row.get('juk_contact_name') or 'this client').strip()}'. "
            f"The bill was created with no VAT tax type ({target_tax_type})."
            if not bool(vat_profile.get("vatRegistered"))
            else ""
        )
        history_extra_notes = [note for note in (vat_history_note, no_vat_history_note) if str(note or "").strip()]
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT *
                    FROM juksib_sync_records
                    WHERE user_id = %s
                      AND source_tenant_id = %s
                      AND juk_xero_invoice_id = %s
                      AND destination_tenant_id = %s
                      AND sync_status = 'published'
                    LIMIT 1
                    """,
                    (
                        user["id"],
                        str(master_connection.get("tenant_id") or ""),
                        source_invoice_id,
                        destination_tenant_id,
                    ),
                )
                duplicate_row = cursor.fetchone()
                cursor.execute(
                    """
                    SELECT *
                    FROM juksib_sync_records
                    WHERE user_id = %s
                      AND source_tenant_id = %s
                      AND juk_xero_invoice_id = %s
                      AND destination_tenant_id = %s
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (
                        user["id"],
                        str(master_connection.get("tenant_id") or ""),
                        source_invoice_id,
                        destination_tenant_id,
                    ),
                )
                latest_sync_row = cursor.fetchone() or {}
            connection.commit()
        if duplicate_row:
            duplicate_bill_id = str(duplicate_row.get("destination_bill_id") or "").strip()
            note_added = False
            note_error = ""
            if duplicate_bill_id:
                note_added, note_error = await _juksib_add_destination_invoice_note(
                    destination_connection,
                    duplicate_bill_id,
                    extra_notes=history_extra_notes,
                )
            publish_result["duplicates"] += 1
            publish_result["rows"].append(
                {
                    "invoiceId": invoice_id,
                    "status": "duplicate",
                    "billId": duplicate_bill_id,
                    "xeroConfirmed": bool(duplicate_bill_id),
                    "noteAdded": note_added,
                    "noteError": note_error,
                    "message": "Already synced previously." if note_added or not note_error else f"Already synced previously. Note failed: {note_error}",
                }
            )
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_batch_invoices
                        SET status = 'duplicate',
                            duplicate_flag = TRUE,
                            error_message = %s,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                        """,
                        ("Already synced previously.", invoice_id),
                    )
                connection.commit()
            continue

        latest_bill_id = str(latest_sync_row.get("destination_bill_id") or "").strip()
        latest_pdf_attached = bool(latest_sync_row.get("pdf_attached"))
        if latest_bill_id and not latest_pdf_attached:
            retry_error = ""
            attached_ok = False
            try:
                pdf_bytes = await fetch_invoice_pdf(master_connection, source_invoice_id)
                attachment_name = f"{invoice_number[:80] or source_invoice_id}.pdf"
                await attach_file_to_invoice(
                    destination_connection,
                    latest_bill_id,
                    attachment_name,
                    pdf_bytes,
                    "application/pdf",
                )
                attached_ok = True
            except Exception as exc:
                retry_error = f"Retry attachment failed: {_sync_error_message(exc)}"
                logger.exception("JUKSIB: Retry PDF attachment failed for invoice %s", invoice_number)

            with get_connection() as connection:
                with connection.cursor() as cursor:
                    cursor.execute(
                        """
                        UPDATE juksib_sync_records
                        SET sync_status = %s,
                            pdf_attached = %s,
                            error_message = %s,
                            updated_at = NOW()
                        WHERE user_id = %s
                          AND source_tenant_id = %s
                          AND juk_xero_invoice_id = %s
                          AND destination_tenant_id = %s
                        """,
                        (
                            "published" if attached_ok else "partial_failed",
                            attached_ok,
                            retry_error,
                            user["id"],
                            str(master_connection.get("tenant_id") or ""),
                            source_invoice_id,
                            destination_tenant_id,
                        ),
                    )
                    cursor.execute(
                        """
                        UPDATE juksib_batch_invoices
                        SET status = %s,
                            published_bill_id = %s,
                            published_at = CASE WHEN %s = 'published' THEN NOW() ELSE published_at END,
                            error_message = %s,
                            retry_count = CASE WHEN %s = 'failed' THEN retry_count + 1 ELSE retry_count END,
                            updated_at = NOW()
                        WHERE id = %s::uuid
                        """,
                        (
                            "published" if attached_ok else "failed",
                            latest_bill_id,
                            "published" if attached_ok else "failed",
                            retry_error,
                            "published" if attached_ok else "failed",
                            invoice_id,
                        ),
                    )
                connection.commit()

            if attached_ok:
                note_added, note_error = await _juksib_add_destination_invoice_note(
                    destination_connection,
                    latest_bill_id,
                    extra_notes=history_extra_notes,
                )
                publish_result["published"] += 1
                publish_result["rows"].append(
                    {
                        "invoiceId": invoice_id,
                        "status": "published",
                        "billId": latest_bill_id,
                    "purchaseAccountCode": target_account_code,
                    "purchaseAccountName": target_account_name,
                    "taxType": target_tax_type,
                    "vatRegistered": bool(vat_profile.get("vatRegistered")),
                    "vatLookupSource": str(vat_profile.get("lookupSource") or ""),
                    "xeroConfirmed": True,
                    "noteAdded": note_added,
                    "noteError": note_error,
                    "message": f"{vat_status_message} PDF attachment retry succeeded and bill is now fully published."
                    if note_added or not note_error
                    else f"{vat_status_message} Published, but note failed: {note_error}",
                }
            )
            else:
                publish_result["failed"] += 1
                publish_result["rows"].append(
                    {
                        "invoiceId": invoice_id,
                        "status": "failed",
                        "billId": latest_bill_id,
                        "purchaseAccountCode": target_account_code,
                        "purchaseAccountName": target_account_name,
                        "taxType": target_tax_type,
                        "vatRegistered": bool(vat_profile.get("vatRegistered")),
                        "vatLookupSource": str(vat_profile.get("lookupSource") or ""),
                        "message": f"{vat_status_message} {retry_error or 'Retry attachment failed.'}".strip(),
                    }
                )
            continue

        try:
            existing_bills = await fetch_paginated_collection(
                destination_connection,
                INVOICES_URL,
                "Invoices",
                params={"where": f'Type=="ACCPAY"&&InvoiceNumber=="{invoice_number}"', "order": "Date DESC"},
                max_pages=2,
            )
            if _juksib_invoice_exists_in_destination(existing_bills, invoice_number):
                existing_bill_id = _juksib_destination_invoice_id(existing_bills, invoice_number)
                note_added = False
                note_error = ""
                if existing_bill_id:
                    note_added, note_error = await _juksib_add_destination_invoice_note(
                        destination_connection,
                        existing_bill_id,
                        extra_notes=history_extra_notes,
                    )
                publish_result["duplicates"] += 1
                publish_result["rows"].append(
                    {
                        "invoiceId": invoice_id,
                        "status": "duplicate",
                        "billId": existing_bill_id,
                        "xeroConfirmed": bool(existing_bill_id),
                        "noteAdded": note_added,
                        "noteError": note_error,
                        "message": "Destination bill already exists." if note_added or not note_error else f"Destination bill already exists. Note failed: {note_error}",
                    }
                )
                with get_connection() as connection:
                    with connection.cursor() as cursor:
                        cursor.execute(
                            """
                            INSERT INTO juksib_sync_records (
                                user_id, batch_id, juk_xero_invoice_id, juk_invoice_number, source_tenant_id,
                                destination_tenant_id, destination_tenant_name, destination_bill_id, client_id, sync_status,
                                pdf_attached, error_message, created_at, updated_at
                            )
                            VALUES (%s, %s::uuid, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
                            ON CONFLICT (user_id, source_tenant_id, juk_xero_invoice_id, destination_tenant_id)
                            DO UPDATE SET
                                destination_bill_id = EXCLUDED.destination_bill_id,
                                destination_tenant_name = EXCLUDED.destination_tenant_name,
                                sync_status = EXCLUDED.sync_status,
                                pdf_attached = EXCLUDED.pdf_attached,
                                error_message = EXCLUDED.error_message,
                                updated_at = NOW()
                            """,
                            (
                                user["id"],
                                batch_id,
                                source_invoice_id,
                                invoice_number,
                                str(master_connection.get("tenant_id") or ""),
                                destination_tenant_id,
                                str(destination_connection.get("tenant_name") or ""),
                                existing_bill_id,
                                destination_tenant_id,
                                "duplicate",
                                False,
                                "Destination bill already exists.",
                            ),
                        )
                        cursor.execute(
                            """
                            UPDATE juksib_batch_invoices
                            SET status = 'duplicate',
                                duplicate_flag = TRUE,
                                error_message = %s,
                                updated_at = NOW()
                            WHERE id = %s::uuid
                            """,
                            ("Destination bill already exists.", invoice_id),
                        )
                    connection.commit()
                continue
        except Exception:
            logger.exception("JUKSIB: destination duplicate check failed for invoice %s", invoice_number)

        line_items = row.get("line_items") if isinstance(row.get("line_items"), list) else []
        mapped_lines = []
        for item in line_items:
            if not isinstance(item, dict):
                continue
            quantity = _juksib_decimal(item.get("Quantity") or item.get("quantity") or 1)
            unit_amount = _juksib_decimal(item.get("UnitAmount") or item.get("unitAmount") or item.get("LineAmount") or item.get("lineAmount") or 0)
            account_code = target_account_code
            description = str(item.get("Description") or item.get("description") or f"JUK invoice {invoice_number}").strip()[:400]
            mapped_lines.append(
                {
                    "Description": description,
                    "Quantity": float(quantity if quantity > Decimal("0") else Decimal("1")),
                    "UnitAmount": float(unit_amount),
                    "AccountCode": account_code,
                    "TaxType": target_tax_type,
                }
            )
        if not mapped_lines:
            mapped_lines = [
                {
                    "Description": f"JUK invoice {invoice_number}",
                    "Quantity": 1,
                    "UnitAmount": float(_juksib_decimal(row.get("subtotal")) or _juksib_decimal(row.get("total"))),
                    "AccountCode": target_account_code,
                    "TaxType": target_tax_type,
                }
            ]

        invoice_date = row.get("invoice_date") or utcnow().date()
        due_date = row.get("due_date") or invoice_date
        destination_payload = {
            "Type": "ACCPAY",
            "Contact": (
                {"ContactID": cached_supplier_contact_id}
                if cached_supplier_contact_id
                else {"Name": supplier_name, "Addresses": [JUKSIB_DEFAULT_SUPPLIER_ADDRESS]}
            ),
            "Date": invoice_date.isoformat() if hasattr(invoice_date, "isoformat") else str(invoice_date),
            "DueDate": due_date.isoformat() if hasattr(due_date, "isoformat") else str(due_date),
            "InvoiceNumber": invoice_number[:120],
            "Reference": str(row.get("batch_id") or "")[:120],
            "Status": "AUTHORISED",
            "LineAmountTypes": "Exclusive",
            "CurrencyCode": str(row.get("currency") or "GBP"),
            "LineItems": mapped_lines,
        }

        created_invoice_id = ""
        pdf_attached = False
        publish_error = ""
        note_added = False
        note_error = ""
        try:
            created_payload = await create_sales_invoice(
                destination_connection,
                destination_payload,
                idempotency_key=f"juksib-{batch_id}-{source_invoice_id}-{destination_tenant_id}",
            )
            created_invoice_id, creation_error = _juksib_extract_created_bill_id(created_payload)
            if creation_error:
                raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=creation_error)
            try:
                pdf_bytes = await fetch_invoice_pdf(master_connection, source_invoice_id)
                attachment_name = f"{invoice_number[:80] or source_invoice_id}.pdf"
                await attach_file_to_invoice(
                    destination_connection,
                    created_invoice_id,
                    attachment_name,
                    pdf_bytes,
                    "application/pdf",
                )
                pdf_attached = True
            except Exception as exc:
                publish_error = f"Bill created but PDF attachment failed: {_sync_error_message(exc)}"
                logger.exception("JUKSIB: PDF attachment failed for invoice %s", invoice_number)
        except Exception as exc:
            publish_error = _sync_error_message(exc)

        if created_invoice_id:
            note_added, note_error = await _juksib_add_destination_invoice_note(
                destination_connection,
                created_invoice_id,
                extra_notes=history_extra_notes,
            )

        if created_invoice_id and not publish_error:
            status_value = "published"
            publish_result["published"] += 1
        elif created_invoice_id and publish_error:
            status_value = "failed"
            publish_result["partialFailed"] += 1
        else:
            status_value = "failed"
            publish_result["failed"] += 1
        combined_error = publish_error
        if note_error:
            combined_error = f"{combined_error} | Note failed: {note_error}" if combined_error else f"Note failed: {note_error}"

        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    INSERT INTO juksib_sync_records (
                        user_id, batch_id, juk_xero_invoice_id, juk_invoice_number, source_tenant_id,
                        destination_tenant_id, destination_tenant_name, destination_bill_id, client_id, sync_status,
                        pdf_attached, error_message, created_at, updated_at
                    )
                    VALUES (%s, %s::uuid, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
                    ON CONFLICT (user_id, source_tenant_id, juk_xero_invoice_id, destination_tenant_id)
                    DO UPDATE SET
                        destination_bill_id = EXCLUDED.destination_bill_id,
                        destination_tenant_name = EXCLUDED.destination_tenant_name,
                        sync_status = EXCLUDED.sync_status,
                        pdf_attached = EXCLUDED.pdf_attached,
                        error_message = EXCLUDED.error_message,
                        updated_at = NOW()
                    """,
                    (
                        user["id"],
                        batch_id,
                        source_invoice_id,
                        invoice_number,
                        str(master_connection.get("tenant_id") or ""),
                        destination_tenant_id,
                        str(destination_connection.get("tenant_name") or ""),
                        created_invoice_id,
                        destination_tenant_id,
                        "published" if status_value == "published" else "partial_failed" if created_invoice_id else "failed",
                        pdf_attached,
                        combined_error,
                    ),
                )
                cursor.execute(
                    """
                    UPDATE juksib_batch_invoices
                    SET status = %s,
                        published_bill_id = %s,
                        published_at = CASE WHEN %s = 'published' THEN NOW() ELSE published_at END,
                        error_message = %s,
                        retry_count = CASE WHEN %s = 'failed' THEN retry_count + 1 ELSE retry_count END,
                        updated_at = NOW()
                    WHERE id = %s::uuid
                    """,
                    (
                        status_value,
                        created_invoice_id,
                        status_value,
                        combined_error,
                        status_value,
                        invoice_id,
                    ),
                )
            connection.commit()

        publish_result["rows"].append(
            {
                "invoiceId": invoice_id,
                "status": status_value,
                "billId": created_invoice_id,
                "purchaseAccountCode": target_account_code,
                "purchaseAccountName": target_account_name,
                "taxType": target_tax_type,
                "vatRegistered": bool(vat_profile.get("vatRegistered")),
                "vatLookupSource": str(vat_profile.get("lookupSource") or ""),
                "xeroConfirmed": bool(created_invoice_id),
                "noteAdded": note_added,
                "noteError": note_error,
                "message": publish_error
                or (note_error and f"{vat_status_message} Published, but note failed: {note_error}")
                or f"{vat_status_message} Published successfully.",
            }
        )

    response = await juksib_get_batch(user, batch_id)
    response["result"] = publish_result
    _juksib_record_audit(
        user_id=user["id"],
        batch_id=batch_id,
        entity_type="juksib_batch",
        entity_id=batch_id,
        action="batch_published",
        new_value=publish_result,
        notes="JUKSIB publish run completed.",
    )
    return response


async def juksib_batch_audit(user: dict, batch_id: str) -> dict:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_audit_logs
                WHERE user_id = %s
                  AND (batch_id = %s::uuid OR (%s = '' AND batch_id IS NULL))
                ORDER BY created_at DESC
                LIMIT 1000
                """,
                (user["id"], batch_id, batch_id),
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return {
        "audit": [
            {
                "id": str(row.get("id") or ""),
                "batchId": str(row.get("batch_id") or ""),
                "entityType": str(row.get("entity_type") or ""),
                "entityId": str(row.get("entity_id") or ""),
                "action": str(row.get("action") or ""),
                "oldValue": row.get("old_value") if isinstance(row.get("old_value"), dict) else {},
                "newValue": row.get("new_value") if isinstance(row.get("new_value"), dict) else {},
                "notes": str(row.get("notes") or ""),
                "createdAt": _iso(row.get("created_at")) or "",
            }
            for row in rows
        ]
    }


async def juksib_source_invoice_pdf(user: dict, invoice_id: str) -> tuple[bytes, str]:
    source_invoice_id = str(invoice_id or "").strip()
    if not source_invoice_id:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Source invoice id is required.")
    master_connection, _ = _juksib_master_and_sub_connections(user)
    pdf_bytes = await fetch_invoice_pdf(master_connection, source_invoice_id)
    safe_invoice_id = re.sub(r"[^A-Za-z0-9._-]+", "-", source_invoice_id).strip("-") or "juk-invoice"
    return pdf_bytes, f"{safe_invoice_id}.pdf"


def _juksib_automation_normalise_recipients(value: object) -> list[str]:
    if isinstance(value, str):
        items = re.split(r"[,\n;]+", value)
    elif isinstance(value, list):
        items = [str(item or "") for item in value]
    else:
        items = []
    recipients: list[str] = []
    for item in items:
        email = str(item or "").strip().lower()
        if not email:
            continue
        if "@" not in email:
            continue
        if email not in recipients:
            recipients.append(email)
    return recipients[:50]


def _juksib_automation_settings_row(user_id: str, create: bool = True) -> dict | None:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            if create:
                cursor.execute(
                    """
                    INSERT INTO juksib_automation_settings (user_id)
                    VALUES (%s::uuid)
                    ON CONFLICT (user_id) DO NOTHING
                    """,
                    (user_id,),
                )
            cursor.execute(
                """
                SELECT *
                FROM juksib_automation_settings
                WHERE user_id = %s::uuid
                LIMIT 1
                """,
                (user_id,),
            )
            row = cursor.fetchone()
        connection.commit()
    return row


def _juksib_automation_serialize_settings(row: dict | None) -> dict:
    settings_row = row or {}
    recipients = settings_row.get("recipient_emails") if isinstance(settings_row.get("recipient_emails"), list) else []
    return {
        "enabled": bool(settings_row.get("enabled")),
        "scheduleTime": str(settings_row.get("schedule_time") or "09:00"),
        "timezone": str(settings_row.get("timezone") or "Europe/London"),
        "recipientEmails": [str(item) for item in recipients if str(item or "").strip()],
        "includePaidInvoices": bool(settings_row.get("include_paid_invoices")),
        "autoPublish": bool(settings_row.get("auto_publish", True)),
        "lastRunAt": _iso(settings_row.get("last_run_at")) or "",
        "lastRunLocalDate": _iso(settings_row.get("last_run_local_date")) or "",
    }


def _juksib_automation_parse_schedule_time(value: str) -> tuple[int, int]:
    raw = str(value or "").strip()
    match = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", raw)
    if not match:
        return 9, 0
    return int(match.group(1)), int(match.group(2))


def _juksib_automation_timezone(value: str) -> ZoneInfo:
    zone = str(value or "").strip() or "Europe/London"
    try:
        return ZoneInfo(zone)
    except ZoneInfoNotFoundError:
        return ZoneInfo("Europe/London")


def _juksib_automation_should_run_now(settings_row: dict, now_utc: datetime) -> tuple[bool, date]:
    zone = _juksib_automation_timezone(str(settings_row.get("timezone") or "Europe/London"))
    local_now = now_utc.astimezone(zone)
    hour, minute = _juksib_automation_parse_schedule_time(str(settings_row.get("schedule_time") or "09:00"))
    target_today = local_now.replace(hour=hour, minute=minute, second=0, microsecond=0)
    last_local_date = settings_row.get("last_run_local_date")
    ran_today = isinstance(last_local_date, date) and last_local_date == local_now.date()
    return (not ran_today and local_now >= target_today), local_now.date()


def _juksib_automation_send_email_report(user: dict, recipients: list[str], subject: str, lines: list[str]) -> None:
    settings = get_settings()
    if not recipients:
        return
    if not (settings.smtp_host and settings.smtp_from_email):
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="SMTP is not configured for automation email reports.",
        )
    message = EmailMessage()
    message["Subject"] = subject[:200]
    message["From"] = formataddr((settings.smtp_from_name or "Jaccountancy", settings.smtp_from_email))
    message["To"] = ", ".join(recipients)
    message.set_content("\n".join(lines))
    host = str(settings.smtp_host or "").strip()
    port = int(settings.smtp_port or 587)
    timeout = 30
    if settings.smtp_use_tls:
        smtp = smtplib.SMTP(host, port, timeout=timeout)
        try:
            smtp.starttls()
            if settings.smtp_username and settings.smtp_password:
                smtp.login(settings.smtp_username, settings.smtp_password)
            smtp.send_message(message)
        finally:
            smtp.quit()
        return
    smtp = smtplib.SMTP(host, port, timeout=timeout)
    try:
        if settings.smtp_username and settings.smtp_password:
            smtp.login(settings.smtp_username, settings.smtp_password)
        smtp.send_message(message)
    finally:
        smtp.quit()


async def _juksib_run_automation_for_user(user: dict, trigger_type: str = "scheduled") -> dict:
    settings_row = _juksib_automation_settings_row(user["id"], create=True) or {}
    if trigger_type == "scheduled":
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT *
                    FROM juksib_automation_settings
                    WHERE user_id = %s::uuid
                    FOR UPDATE
                    """,
                    (user["id"],),
                )
                locked_settings = cursor.fetchone() or settings_row
                zone = _juksib_automation_timezone(str(locked_settings.get("timezone") or "Europe/London"))
                local_date = utcnow().astimezone(zone).date()
                last_local_date = locked_settings.get("last_run_local_date")
                if isinstance(last_local_date, date) and last_local_date == local_date:
                    connection.commit()
                    return {
                        "runId": "",
                        "summary": {
                            "batchId": "",
                            "batchReference": "",
                            "imported": 0,
                            "readyToPublish": 0,
                            "published": 0,
                            "failed": 0,
                            "duplicates": 0,
                            "skipped": True,
                            "reason": "already_ran_today",
                        },
                    }
                cursor.execute(
                    """
                    UPDATE juksib_automation_settings
                    SET last_run_at = NOW(),
                        last_run_local_date = %s,
                        updated_at = NOW()
                    WHERE user_id = %s::uuid
                    """,
                    (local_date, user["id"]),
                )
            connection.commit()
            settings_row = locked_settings
    run_id = ""
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO juksib_automation_runs (user_id, trigger_type, status, summary, started_at)
                VALUES (%s::uuid, %s, 'running', '{}'::jsonb, NOW())
                RETURNING id
                """,
                (user["id"], trigger_type),
            )
            run_id = str((cursor.fetchone() or {}).get("id") or "")
        connection.commit()

    summary: dict = {}
    try:
        import_payload = {
            "mode": "live",
            "includePaidInvoices": bool(settings_row.get("include_paid_invoices")),
            "includeAlreadyImported": False,
        }
        imported = await juksib_import_batch(user, import_payload)
        batch = (imported or {}).get("batch") if isinstance(imported, dict) else None
        batch_id = str((batch or {}).get("id") or "")
        published = {}
        if bool(settings_row.get("auto_publish", True)) and batch_id:
            published = await juksib_publish_batch(user, batch_id, {"invoiceIds": []})
        final_batch = (published or imported or {}).get("batch") if isinstance((published or imported), dict) else {}
        final_summary = (final_batch or {}).get("summary") if isinstance(final_batch, dict) else {}
        summary = {
            "batchId": batch_id,
            "batchReference": str((final_batch or {}).get("batchReference") or (batch or {}).get("batchReference") or ""),
            "imported": int((final_summary or {}).get("totalImported") or 0),
            "readyToPublish": int((final_summary or {}).get("readyToPublish") or 0),
            "published": int((final_summary or {}).get("published") or 0),
            "failed": int((final_summary or {}).get("failed") or 0),
            "duplicates": int((final_summary or {}).get("duplicates") or 0),
        }

        recipients = _juksib_automation_normalise_recipients(settings_row.get("recipient_emails"))
        if recipients:
            subject = f"JUKSIB Daily Sync Report - {summary.get('batchReference') or 'No batch'}"
            lines = [
                "JUK Invoice Sync Bridge daily automation report",
                "",
                f"Batch: {summary.get('batchReference') or '--'}",
                f"Imported: {summary.get('imported', 0)}",
                f"Published: {summary.get('published', 0)}",
                f"Failed: {summary.get('failed', 0)}",
                f"Duplicates: {summary.get('duplicates', 0)}",
                "",
                "This is an automated JUKSIB report.",
            ]
            _juksib_automation_send_email_report(user, recipients, subject, lines)

        with get_connection() as connection:
            with connection.cursor() as cursor:
                zone = _juksib_automation_timezone(str(settings_row.get("timezone") or "Europe/London"))
                local_date = utcnow().astimezone(zone).date()
                cursor.execute(
                    """
                    UPDATE juksib_automation_runs
                    SET status = 'completed',
                        summary = %s::jsonb,
                        completed_at = NOW()
                    WHERE id = %s::uuid
                    """,
                    (json.dumps(summary, default=_json_default), run_id),
                )
                cursor.execute(
                    """
                    UPDATE juksib_automation_settings
                    SET last_run_at = NOW(),
                        last_run_local_date = %s,
                        updated_at = NOW()
                    WHERE user_id = %s::uuid
                    """,
                    (local_date, user["id"]),
                )
            connection.commit()
        return {"runId": run_id, "summary": summary}
    except Exception as exc:
        error_message = _sync_error_message(exc)
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE juksib_automation_runs
                    SET status = 'failed',
                        summary = %s::jsonb,
                        error_message = %s,
                        completed_at = NOW()
                    WHERE id = %s::uuid
                    """,
                    (json.dumps(summary or {}, default=_json_default), error_message, run_id),
                )
            connection.commit()
        raise


def juksib_automation_payload(user: dict) -> dict:
    settings_row = _juksib_automation_settings_row(user["id"], create=True)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT *
                FROM juksib_automation_runs
                WHERE user_id = %s::uuid
                ORDER BY started_at DESC
                LIMIT 120
                """,
                (user["id"],),
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return {
        "settings": _juksib_automation_serialize_settings(settings_row),
        "history": [
            {
                "id": str(row.get("id") or ""),
                "triggerType": str(row.get("trigger_type") or ""),
                "status": str(row.get("status") or ""),
                "summary": row.get("summary") if isinstance(row.get("summary"), dict) else {},
                "errorMessage": str(row.get("error_message") or ""),
                "startedAt": _iso(row.get("started_at")) or "",
                "completedAt": _iso(row.get("completed_at")) or "",
            }
            for row in rows
        ],
    }


async def juksib_batch_excel_report(user: dict, batch_id: str) -> tuple[bytes, str]:
    payload = await juksib_get_batch(user, batch_id)
    batch = payload.get("batch") if isinstance(payload, dict) else {}
    invoices = (batch or {}).get("invoices") if isinstance(batch, dict) else []
    rows = [
        [
            "Batch Reference",
            "Invoice Number",
            "Invoice Date",
            "Client Name",
            "Suggested Tenant",
            "Match Source",
            "Confidence",
            "Status",
            "Subtotal",
            "VAT",
            "Total",
            "Published Bill ID",
            "Error",
        ]
    ]
    for invoice in invoices if isinstance(invoices, list) else []:
        if not isinstance(invoice, dict):
            continue
        rows.append(
            [
                str((batch or {}).get("batchReference") or ""),
                str(invoice.get("jukInvoiceNumber") or ""),
                str(invoice.get("invoiceDate") or ""),
                str(invoice.get("jukContactName") or ""),
                str(invoice.get("matchedTenantName") or ""),
                str(invoice.get("matchSource") or ""),
                float(_juksib_decimal(invoice.get("matchConfidence"))),
                str(invoice.get("statusLabel") or invoice.get("status") or ""),
                float(_juksib_decimal(invoice.get("subtotal"))),
                float(_juksib_decimal(invoice.get("vatTotal"))),
                float(_juksib_decimal(invoice.get("total"))),
                str(invoice.get("publishedBillId") or ""),
                str(invoice.get("errorMessage") or ""),
            ]
        )
    workbook_bytes = _build_simple_xlsx_workbook(rows, "JUKSIB Report")
    batch_reference = str((batch or {}).get("batchReference") or "juksib").strip() or "juksib"
    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "-", batch_reference).strip("-") or "juksib"
    return workbook_bytes, f"{safe_name}-report.xlsx"


def update_juksib_automation_settings(user: dict, payload: dict | None = None) -> dict:
    body = payload if isinstance(payload, dict) else {}
    enabled = bool(body.get("enabled"))
    schedule_time = str(body.get("scheduleTime") or "09:00").strip() or "09:00"
    _juksib_automation_parse_schedule_time(schedule_time)
    timezone_name = str(body.get("timezone") or "Europe/London").strip() or "Europe/London"
    _ = _juksib_automation_timezone(timezone_name)
    recipients = _juksib_automation_normalise_recipients(body.get("recipientEmails"))
    include_paid = bool(body.get("includePaidInvoices"))
    auto_publish = bool(body.get("autoPublish", True))
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                INSERT INTO juksib_automation_settings (
                    user_id, enabled, schedule_time, timezone, recipient_emails, include_paid_invoices,
                    auto_publish, updated_by_user_id, updated_at
                )
                VALUES (%s::uuid, %s, %s, %s, %s::jsonb, %s, %s, %s::uuid, NOW())
                ON CONFLICT (user_id)
                DO UPDATE SET
                    enabled = EXCLUDED.enabled,
                    schedule_time = EXCLUDED.schedule_time,
                    timezone = EXCLUDED.timezone,
                    recipient_emails = EXCLUDED.recipient_emails,
                    include_paid_invoices = EXCLUDED.include_paid_invoices,
                    auto_publish = EXCLUDED.auto_publish,
                    updated_by_user_id = EXCLUDED.updated_by_user_id,
                    updated_at = NOW()
                """,
                (
                    user["id"],
                    enabled,
                    schedule_time,
                    timezone_name,
                    json.dumps(recipients, default=_json_default),
                    include_paid,
                    auto_publish,
                    user["id"],
                ),
            )
        connection.commit()
    return juksib_automation_payload(user)


async def run_juksib_automation_now(user: dict) -> dict:
    result = await _juksib_run_automation_for_user(user, trigger_type="manual")
    payload = juksib_automation_payload(user)
    payload["lastRun"] = result
    return payload


def _juksib_automation_enabled_users() -> list[dict]:
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT users.*, settings.schedule_time, settings.timezone, settings.last_run_local_date, settings.enabled
                FROM juksib_automation_settings AS settings
                JOIN users ON users.id = settings.user_id
                WHERE settings.enabled = TRUE
                """
            )
            rows = cursor.fetchall() or []
        connection.commit()
    return rows


def _run_juksib_automation_worker_loop() -> None:
    while not _JUKSIB_AUTOMATION_STOP.is_set():
        try:
            now = utcnow()
            for user_row in _juksib_automation_enabled_users():
                should_run, _ = _juksib_automation_should_run_now(user_row, now)
                if not should_run:
                    continue
                user_payload = {"id": str(user_row.get("id") or ""), "email": str(user_row.get("email") or "")}
                if not user_payload["id"]:
                    continue
                try:
                    asyncio.run(_juksib_run_automation_for_user(user_payload, trigger_type="scheduled"))
                except Exception:
                    logger.exception("JUKSIB automation failed for user %s", user_payload["id"])
        except Exception:
            logger.exception("JUKSIB automation worker heartbeat failed")
        _JUKSIB_AUTOMATION_STOP.wait(45)


def start_juksib_automation_worker() -> None:
    global _JUKSIB_AUTOMATION_THREAD
    with _JUKSIB_AUTOMATION_LOCK:
        if _JUKSIB_AUTOMATION_THREAD and _JUKSIB_AUTOMATION_THREAD.is_alive():
            return
        _JUKSIB_AUTOMATION_STOP.clear()
        _JUKSIB_AUTOMATION_THREAD = threading.Thread(
            target=_run_juksib_automation_worker_loop,
            name="juksib-automation-worker",
            daemon=True,
        )
        _JUKSIB_AUTOMATION_THREAD.start()


def _code_breaker_net_assets_value(payload: object) -> Decimal | None:
    def parse_numeric(value: object) -> Decimal | None:
        if value is None:
            return None
        if isinstance(value, (int, float, Decimal)):
            return _money(value)
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return None
            negative = text.startswith("(") and text.endswith(")")
            clean = text.strip("()").replace(",", "").replace("£", "").replace("%", "").strip()
            if not clean:
                return None
            if not re.fullmatch(r"[+-]?\d+(?:\.\d+)?", clean):
                return None
            try:
                amount = Decimal(clean)
            except Exception:
                return None
            return _money(-amount if negative else amount)
        return None

    def preferred(values: list[Decimal]) -> Decimal | None:
        if not values:
            return None
        non_zero = [value for value in values if value.copy_abs() > Decimal("0.00")]
        return _money(non_zero[-1] if non_zero else values[-1])

    if payload is None:
        return None
    numeric = parse_numeric(payload)
    if numeric is not None:
        return numeric
    if isinstance(payload, dict):
        candidates: list[Decimal] = []
        candidate_keys = (
            "netAssets",
            "net_assets",
            "balanceSheetNetAssets",
            "net_assets_total",
            "totalNetAssets",
            "total_net_assets",
        )
        for key in candidate_keys:
            if key in payload:
                value = _code_breaker_net_assets_value(payload.get(key))
                if value is not None:
                    candidates.append(value)
        for key, value in payload.items():
            key_text = str(key or "").strip().lower()
            if "net assets" in key_text or "net_assets" in key_text:
                extracted = _code_breaker_net_assets_value(value)
                if extracted is not None:
                    candidates.append(extracted)
        for value in payload.values():
            if not isinstance(value, (dict, list)):
                continue
            extracted = _code_breaker_net_assets_value(value)
            if extracted is not None:
                candidates.append(extracted)
        return preferred(candidates)
    if isinstance(payload, list):
        candidates: list[Decimal] = []
        for item in payload:
            value = _code_breaker_net_assets_value(item)
            if value is not None:
                candidates.append(value)
        return preferred(candidates)
    return None


