def override_bank_statement_transaction(user: dict, transaction_id: str, payload: dict) -> dict:
    tenant_id = _bank_statement_tenant_id(user)
    amount_value = payload.get("amount")
    try:
        manual_amount = Decimal(str(amount_value)).quantize(Decimal("0.01"))
    except Exception as exc:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Enter a valid signed transaction amount.") from exc
    if not manual_amount.is_finite():
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Enter a valid signed transaction amount.")
    note = str(payload.get("note") or "").strip()[:500]
    override_at = utcnow()
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT transactions.id,
                       transactions.amount,
                       transactions.balance,
                       accounts.id AS account_id,
                       customers.name AS customer_name
                FROM bank_statement_transactions AS transactions
                JOIN bank_statement_accounts AS accounts ON accounts.id = transactions.bank_account_id
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                JOIN customers ON customers.id = clients.customer_id
                WHERE transactions.id = %s
                  AND clients.tenant_id = %s
                  AND clients.status = 'active'
                """,
                (transaction_id, tenant_id),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank statement transaction not found.")
            cursor.execute(
                """
                UPDATE bank_statement_transactions
                SET manual_amount = %s,
                    manual_override_note = %s,
                    manual_override_at = %s,
                    manual_override_by_user_id = %s
                WHERE id = %s
                """,
                (manual_amount, note, override_at, user["id"], transaction_id),
            )
        connection.commit()
    record_audit_event(
        "bank_statement_transaction",
        str(transaction_id),
        "bank_statement.transaction_overridden",
        {
            "account_id": str(row["account_id"]),
            "customer_name": row.get("customer_name") or "",
            "original_amount": f"{_money(row.get('amount')):.2f}",
            "manual_amount": f"{manual_amount:.2f}",
            "note": note,
        },
        user["id"],
    )
    return bank_statement_payload(user)


def categorise_bank_statement_transactions(user: dict, account_id: str, payload: dict) -> dict:
    tenant_id = _bank_statement_tenant_id(user)
    raw_suggestions = payload.get("suggestions")
    if not isinstance(raw_suggestions, list):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Send at least one AI category suggestion.")

    suggestions = []
    for item in raw_suggestions[:2000]:
        if not isinstance(item, dict):
            continue
        transaction_id = str(item.get("transactionId") or item.get("id") or "").strip()
        try:
            transaction_uuid = UUID(transaction_id)
        except Exception:
            continue
        code = str(item.get("code") or "").strip()[:40]
        name = str(item.get("name") or "").strip()[:160]
        tag = str(item.get("tag") or "").strip()[:80]
        reason = str(item.get("reason") or "").strip()[:600]
        source = str(item.get("source") or "").strip()[:80]
        try:
            confidence = int(round(float(item.get("confidence") or 0)))
        except Exception:
            confidence = 0
        confidence = max(0, min(100, confidence))
        if not (code or name or tag):
            continue
        suggestions.append({
            "transaction_id": str(transaction_uuid),
            "code": code,
            "name": name,
            "tag": tag,
            "confidence": confidence,
            "reason": reason,
            "source": source,
        })

    if not suggestions:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="No valid AI categories were available to apply.")

    applied_at = utcnow()
    applied_count = 0
    account_row = None
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT accounts.id AS account_id,
                       customers.name AS customer_name
                FROM bank_statement_accounts AS accounts
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                JOIN customers ON customers.id = clients.customer_id
                WHERE accounts.id = %s
                  AND clients.tenant_id = %s
                  AND clients.status = 'active'
                """,
                (account_id, tenant_id),
            )
            account_row = cursor.fetchone()
            if account_row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank statement account not found.")

            for suggestion in suggestions:
                cursor.execute(
                    """
                    UPDATE bank_statement_transactions
                    SET ai_category_code = %s,
                        ai_category_name = %s,
                        ai_category_tag = %s,
                        ai_category_confidence = %s,
                        ai_category_reason = %s,
                        ai_category_source = %s,
                        ai_category_applied_at = %s,
                        ai_category_applied_by_user_id = %s
                    WHERE id = %s
                      AND bank_account_id = %s
                    """,
                    (
                        suggestion["code"],
                        suggestion["name"],
                        suggestion["tag"],
                        suggestion["confidence"],
                        suggestion["reason"],
                        suggestion["source"],
                        applied_at,
                        user["id"],
                        suggestion["transaction_id"],
                        account_id,
                    ),
                )
                applied_count += max(0, int(cursor.rowcount or 0))
        connection.commit()

    record_audit_event(
        "bank_statement_account",
        str(account_id),
        "bank_statement.transactions_ai_categorised",
        {
            "account_id": str(account_row["account_id"]) if account_row else str(account_id),
            "customer_name": account_row.get("customer_name") if account_row else "",
            "suggestion_count": len(suggestions),
            "applied_count": applied_count,
        },
        user["id"],
    )
    return bank_statement_payload(user)


def bank_statement_upload_source_file(user: dict, upload_id: str) -> tuple[bytes, str, str]:
    tenant_id = _bank_statement_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT uploads.filename, uploads.content_type, uploads.source_file
                FROM bank_statement_uploads AS uploads
                JOIN bank_statement_accounts AS accounts ON accounts.id = uploads.bank_account_id
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                WHERE uploads.id = %s
                  AND clients.tenant_id = %s
                  AND clients.status = 'active'
                """,
                (upload_id, tenant_id),
            )
            row = cursor.fetchone()
    if row is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank statement submission not found.")
    source_file = bytes(row.get("source_file") or b"")
    if not source_file:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="The original PDF is no longer available for this submission.")
    filename = row.get("filename") or "bank-statement.pdf"
    content_type = row.get("content_type") or "application/pdf"
    return source_file, filename, content_type


def _bank_statement_upload_activity(event_type: str, message: str, detail: dict | None = None) -> dict:
    return {
        "type": event_type,
        "message": message,
        "detail": detail or {},
        "createdAt": utcnow().isoformat(),
    }


def _append_bank_statement_upload_activity(cursor, upload_id: str, event_type: str, message: str, detail: dict | None = None) -> None:
    cursor.execute(
        """
        UPDATE bank_statement_uploads
        SET activity_log = COALESCE(activity_log, '[]'::jsonb) || %s::jsonb
        WHERE id = %s
        """,
        (json.dumps([_bank_statement_upload_activity(event_type, message, detail)], default=_json_default), upload_id),
    )


def _bank_statement_chunk_filename_stem(filename: str) -> str:
    safe_stem = re.sub(r"(?i)\.pdf$", "", filename or "bank-statement").strip() or "bank-statement"
    return re.sub(r"[^A-Za-z0-9._-]+", "-", safe_stem)[:80].strip(".-") or "bank-statement"


def _bank_statement_chunk_label_part(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9._-]+", "-", str(value or "chunk"))[:80].strip(".-") or "chunk"


def _bank_statement_text_lines(text: str) -> list[str]:
    return [
        re.sub(r"\s+", " ", line).strip()
        for line in str(text or "").splitlines()
        if line and line.strip()
    ]


def _bank_statement_text_chunks(text: str, filename: str, label: str) -> list[dict]:
    lines = _bank_statement_text_lines(text)
    if len(lines) <= BANK_STATEMENT_TEXT_CHUNK_MAX_LINES:
        return []

    chunks = []
    safe_stem = _bank_statement_chunk_filename_stem(filename)
    safe_label = _bank_statement_chunk_label_part(label)
    step = max(1, BANK_STATEMENT_TEXT_CHUNK_MAX_LINES - BANK_STATEMENT_TEXT_CHUNK_OVERLAP_LINES)
    start = 0
    while start < len(lines):
        end = min(start + BANK_STATEMENT_TEXT_CHUNK_MAX_LINES, len(lines))
        chunks.append({
            "text": "\n".join(lines[start:end]),
            "filename": f"{safe_stem}-{safe_label}-lines-{start + 1}-{end}.txt",
            "label": f"{label} lines {start + 1}-{end}",
            "source": "text",
        })
        if end >= len(lines):
            break
        start += step
    return chunks


def _bank_statement_numbered_chunks(chunks: list[dict]) -> list[dict]:
    total = len(chunks)
    for index, chunk in enumerate(chunks):
        chunk["index"] = index
        chunk["total"] = total
    return chunks


def _bank_statement_page_text(page) -> str:
    try:
        return page.extract_text() or ""
    except Exception:
        return ""


def _bank_statement_pdf_chunks(file_bytes: bytes, filename: str) -> list[dict]:
    fallback = [{
        "bytes": file_bytes,
        "filename": filename,
        "label": "the full statement",
        "index": 0,
        "total": 1,
        "source": "pdf",
    }]
    try:
        from pypdf import PdfReader, PdfWriter
    except Exception as exc:
        logger.warning("pypdf is unavailable; extracting bank statement as one document: %s", exc)
        return fallback

    try:
        reader = PdfReader(io.BytesIO(file_bytes))
        if getattr(reader, "is_encrypted", False):
            try:
                reader.decrypt("")
            except Exception:
                return fallback
        page_count = len(reader.pages)

        chunks = []
        safe_stem = _bank_statement_chunk_filename_stem(filename)
        for start in range(0, page_count, BANK_STATEMENT_CHUNK_MAX_PAGES):
            end = min(start + BANK_STATEMENT_CHUNK_MAX_PAGES, page_count)
            page_label = f"page {start + 1}" if end == start + 1 else f"pages {start + 1}-{end}"
            page_text = "\n".join(_bank_statement_page_text(reader.pages[page_index]) for page_index in range(start, end))
            text_chunks = _bank_statement_text_chunks(page_text, filename, page_label)
            if text_chunks:
                chunks.extend(text_chunks)
                continue

            if page_count <= BANK_STATEMENT_CHUNK_MAX_PAGES:
                return fallback

            writer = PdfWriter()
            for page_index in range(start, end):
                writer.add_page(reader.pages[page_index])
            output = io.BytesIO()
            writer.write(output)
            chunks.append({
                "bytes": output.getvalue(),
                "filename": f"{safe_stem}-{page_label.replace(' ', '-')}.pdf",
                "label": page_label,
                "source": "pdf",
            })
        return _bank_statement_numbered_chunks(chunks) if chunks else fallback
    except Exception as exc:
        logger.warning("Could not split bank statement PDF into page chunks: %s", exc)
        return fallback


def _bank_statement_extraction_prompt(account: dict, chunk_label: str, chunk_index: int, total_chunks: int, source: str = "pdf") -> str:
    if source == "text":
        chunk_instruction = (
            f"You are extracting text from {chunk_label} (chunk {chunk_index + 1} of {total_chunks}). "
            "Only include complete transaction rows visible in this text chunk. "
            "Some lines may overlap with neighbouring chunks, so do not invent rows to bridge gaps. "
        )
    else:
        chunk_instruction = (
            f"You are extracting {chunk_label} (chunk {chunk_index + 1} of {total_chunks}). "
            "Only include transaction rows visible in this chunk. "
        )
    return (
        "Extract bank statement transactions from the supplied statement source. Return JSON only. "
        + chunk_instruction +
        "Use ISO dates in YYYY-MM-DD format. "
        "Use signed amounts: money paid in is positive, money paid out is negative. "
        "Include every posted transaction line with date, description, payee, reference, amount, running balance where shown, and a short type. "
        "For payee, extract the counterparty name only, removing bank wording such as Card Payment to, Direct Debit to, Direct Credit From, Ref, Reference, and transaction date suffixes; use an empty string only when no counterparty is visible. "
        "For reference, use the visible Ref or Reference value from the narrative where present; otherwise generate a concise useful reference from the transaction wording, such as the card transaction date, transfer channel, or payee. "
        "Capture the running balance exactly as printed because Jenius checks previous balance plus the signed transaction amount against each extracted running balance. "
        "If PDF text is grouped by columns instead of rows, reconstruct each transaction by visual row order: date, narrative, debit or credit amount, then balance. "
        "For debit-column amounts use a negative amount; for credit-column amounts use a positive amount. "
        "Ignore page headers, brought forward/carried forward labels unless they are opening or closing balances. "
        f"The expected account number is {account.get('account_number') or 'unknown'}."
    )


def _openai_incomplete_reason(payload: dict) -> str:
    details = payload.get("incomplete_details") or {}
    if isinstance(details, dict) and details.get("reason"):
        return str(details["reason"])
    return ""


def _openai_hit_output_limit(reason: str) -> bool:
    text = str(reason or "").strip().lower()
    return text == "max_output_tokens" or ("max" in text and "token" in text)


async def _extract_bank_statement_pdf_chunk(
    file_bytes: bytes | None,
    filename: str,
    account: dict,
    chunk_label: str,
    chunk_index: int,
    total_chunks: int,
    text_content: str = "",
) -> dict:
    source = "text" if text_content else "pdf"
    prompt = _bank_statement_extraction_prompt(account, chunk_label, chunk_index, total_chunks, source)
    if text_content:
        content = [{"type": "input_text", "text": f"{prompt}\n\nStatement text chunk:\n{text_content}"}]
    else:
        if not file_bytes:
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=f"Statement chunk {chunk_label} was empty.")
        encoded = base64.b64encode(file_bytes).decode("ascii")
        content = [
            {
                "type": "input_file",
                "filename": filename,
                "file_data": f"data:application/pdf;base64,{encoded}",
            },
            {"type": "input_text", "text": prompt},
        ]
    token_limits = list(dict.fromkeys((BANK_STATEMENT_MAX_OUTPUT_TOKENS, BANK_STATEMENT_RETRY_MAX_OUTPUT_TOKENS)))
    for attempt_index, max_output_tokens in enumerate(token_limits):
        request_body = {
            "input": [
                {
                    "role": "user",
                    "content": content,
                }
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "bank_statement_extraction",
                    "schema": BANK_STATEMENT_EXTRACTION_SCHEMA,
                    "strict": True,
                }
            },
            "max_output_tokens": max_output_tokens,
        }
        payload = await _post_openai_responses(request_body, f"statement extraction for {chunk_label}")
        text = _extract_response_text(payload)
        incomplete_reason = _openai_incomplete_reason(payload)
        output_limit_reached = _openai_hit_output_limit(incomplete_reason)
        retry_available = output_limit_reached and attempt_index < len(token_limits) - 1
        if not text:
            if retry_available:
                logger.info("Retrying bank statement extraction for %s with a larger output limit after empty max-token response.", chunk_label)
                continue
            detail = f"OpenAI returned an empty statement extraction for {chunk_label}."
            if incomplete_reason:
                detail = f"OpenAI stopped before finishing statement extraction for {chunk_label}: {incomplete_reason}."
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=detail)
        try:
            return json.loads(text)
        except ValueError as exc:
            if retry_available:
                logger.info("Retrying bank statement extraction for %s with a larger output limit after truncated JSON.", chunk_label)
                continue
            detail = f"OpenAI returned statement extraction for {chunk_label} that was not valid JSON."
            if incomplete_reason:
                detail = f"OpenAI stopped before returning valid JSON for {chunk_label}: {incomplete_reason}."
            raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=detail) from exc

    raise HTTPException(
        status_code=status.HTTP_502_BAD_GATEWAY,
        detail=f"OpenAI could not finish statement extraction for {chunk_label}. Try splitting the bank statement into a smaller PDF and uploading again.",
    )


def _merge_bank_statement_extractions(extractions: list[dict]) -> dict:
    transactions = []
    seen_transactions = set()
    statement_start = None
    statement_end = None
    opening_balance = None
    closing_balance = None

    for extraction in extractions:
        extracted = extraction.get("extracted") or {}
        chunk_label = extraction.get("label") or "statement chunk"
        chunk_index = int(extraction.get("index") or 0)
        chunk_start = _parse_optional_iso_date(extracted.get("statementStartDate"))
        chunk_end = _parse_optional_iso_date(extracted.get("statementEndDate"))
        if chunk_start and (statement_start is None or chunk_start < statement_start):
            statement_start = chunk_start
        if chunk_end and (statement_end is None or chunk_end > statement_end):
            statement_end = chunk_end
        if opening_balance is None and extracted.get("openingBalance") is not None:
            opening_balance = extracted.get("openingBalance")
        if extracted.get("closingBalance") is not None:
            closing_balance = extracted.get("closingBalance")

        for row_index, transaction in enumerate(extracted.get("transactions") or []):
            if not isinstance(transaction, dict):
                continue
            key = (
                str(transaction.get("date") or ""),
                _normalise_hash_text(transaction.get("description")),
                f"{_money(transaction.get('amount')):.2f}",
                "" if transaction.get("balance") is None else f"{_money(transaction.get('balance')):.2f}",
            )
            if key in seen_transactions:
                continue
            seen_transactions.add(key)
            enriched = dict(transaction)
            enriched["_sourceChunk"] = chunk_label
            enriched["_sourceChunkIndex"] = chunk_index
            enriched["_sourceRowIndex"] = row_index
            transactions.append(enriched)

    dated_transactions = []
    for transaction in transactions:
        parsed_date = _parse_optional_iso_date(transaction.get("date"))
        if parsed_date:
            dated_transactions.append((parsed_date, transaction))
    if dated_transactions:
        dated_transactions.sort(key=lambda item: (item[0], int(item[1].get("_sourceChunkIndex") or 0), int(item[1].get("_sourceRowIndex") or 0)))
        if statement_start is None:
            statement_start = dated_transactions[0][0]
        if statement_end is None:
            statement_end = dated_transactions[-1][0]
        transactions.sort(key=lambda row: (row.get("date") or "", int(row.get("_sourceChunkIndex") or 0), int(row.get("_sourceRowIndex") or 0)))

    if opening_balance is None:
        for transaction in transactions:
            if transaction.get("balance") is not None and transaction.get("amount") is not None:
                opening_balance = _money(transaction.get("balance")) - _money(transaction.get("amount"))
                break
    if closing_balance is None:
        for transaction in reversed(transactions):
            if transaction.get("balance") is not None:
                closing_balance = transaction.get("balance")
                break

    return {
        "statementStartDate": statement_start.isoformat() if statement_start else None,
        "statementEndDate": statement_end.isoformat() if statement_end else None,
        "openingBalance": float(_money(opening_balance)) if opening_balance is not None else None,
        "closingBalance": float(_money(closing_balance)) if closing_balance is not None else None,
        "accountNumber": None,
        "transactions": transactions,
        "_chunkCount": len(extractions),
    }


async def _extract_bank_statement_pdf(file_bytes: bytes, filename: str, account: dict) -> dict:
    settings = get_settings()
    if not settings.openai_api_key:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="OpenAI extraction is not configured. Add OPENAI_API_KEY before uploading statements.")
    if len(file_bytes) > 50 * 1024 * 1024:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PDF files must be under 50 MB for extraction.")
    chunks = _bank_statement_pdf_chunks(file_bytes, filename)
    extractions = []
    for chunk in chunks:
        extracted = await _extract_bank_statement_pdf_chunk(
            chunk.get("bytes"),
            chunk["filename"],
            account,
            chunk["label"],
            chunk["index"],
            chunk["total"],
            chunk.get("text") or "",
        )
        extractions.append({**chunk, "extracted": extracted})
    merged = _merge_bank_statement_extractions(extractions)
    if not merged["transactions"]:
        raise HTTPException(
            status_code=status.HTTP_502_BAD_GATEWAY,
            detail="No transaction rows were extracted from the bank statement. Check that the PDF contains selectable statement text or upload a clearer statement.",
        )
    return merged


def _insert_bank_statement_transactions(cursor, bank_account_id: str, upload_id: str, transactions: list[dict]) -> dict:
    inserted_count = 0
    duplicate_count = 0
    valid_count = 0
    quality_rows = []
    for transaction in transactions:
        try:
            transaction_date = _parse_iso_date(transaction.get("date"), "Transaction date")
            amount = _money(transaction.get("amount"))
            description = str(transaction.get("description") or "").strip()
            if not description:
                continue
            balance = transaction.get("balance")
            balance_amount = _money(balance) if balance is not None else None
        except Exception:
            continue
        valid_count += 1
        source_hash = _bank_transaction_source_hash(
            bank_account_id,
            {"date": transaction_date.isoformat(), "description": description, "amount": amount, "balance": balance_amount},
        )
        cursor.execute(
            """
            INSERT INTO bank_statement_transactions (
                bank_account_id, upload_id, transaction_date, description,
                amount, balance, transaction_type, source_hash, raw, created_at
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s::jsonb, %s)
            ON CONFLICT (bank_account_id, source_hash) DO NOTHING
            RETURNING id
            """,
            (
                bank_account_id,
                upload_id,
                transaction_date,
                description,
                amount,
                balance_amount,
                str(transaction.get("type") or "")[:80],
                source_hash,
                json.dumps(transaction, default=_json_default),
                utcnow(),
            ),
        )
        if cursor.fetchone():
            inserted_count += 1
            quality_rows.append({
                "transaction_date": transaction_date,
                "amount": amount,
                "balance": balance_amount,
                "created_at": utcnow(),
            })
        else:
            duplicate_count += 1
    return {
        "validCount": valid_count,
        "insertedCount": inserted_count,
        "duplicateCount": duplicate_count,
        "qualityRows": quality_rows,
    }


def _bank_statement_chunk_transactions(extraction: dict) -> list[dict]:
    return _merge_bank_statement_extractions([extraction]).get("transactions") or []


async def _process_bank_statement_upload(user: dict, account: dict, upload_id: str, filename: str, content_type: str, file_bytes: bytes, is_retry: bool = False) -> dict:
    bank_account_id = str(account["id"])
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                UPDATE bank_statement_uploads
                SET status = 'processing',
                    error_message = NULL,
                    completed_at = NULL,
                    attempt_count = COALESCE(attempt_count, 0) + 1,
                    last_attempt_at = %s
                WHERE id = %s
                """,
                (utcnow(), upload_id),
            )
            cursor.execute("DELETE FROM bank_statement_transactions WHERE upload_id = %s", (upload_id,))
            _append_bank_statement_upload_activity(
                cursor,
                upload_id,
                "retry_started" if is_retry else "extraction_started",
                "Retry started." if is_retry else "Extraction started.",
                {"filename": filename, "contentType": content_type, "fileSize": len(file_bytes)},
            )
        connection.commit()

    try:
        settings = get_settings()
        if not settings.openai_api_key:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="OpenAI extraction is not configured. Add OPENAI_API_KEY before uploading statements.")
        if len(file_bytes) > 50 * 1024 * 1024:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PDF files must be under 50 MB for extraction.")

        chunks = _bank_statement_pdf_chunks(file_bytes, filename)
        extractions = []
        quality_rows = []
        inserted_count = 0
        duplicate_count = 0
        valid_count = 0

        with get_connection() as connection:
            with connection.cursor() as cursor:
                _append_bank_statement_upload_activity(
                    cursor,
                    upload_id,
                    "chunk_plan",
                    f"Statement split into {len(chunks):,} extraction chunk(s).",
                    {"chunkCount": len(chunks)},
                )
            connection.commit()

        for chunk in chunks:
            chunk_index = int(chunk.get("index") or 0)
            chunk_total = int(chunk.get("total") or len(chunks) or 1)
            chunk_label = chunk.get("label") or f"chunk {chunk_index + 1}"
            with get_connection() as connection:
                with connection.cursor() as cursor:
                    _append_bank_statement_upload_activity(
                        cursor,
                        upload_id,
                        "chunk_started",
                        f"Extracting {chunk_label} ({chunk_index + 1:,} of {chunk_total:,}).",
                        {"chunkIndex": chunk_index + 1, "chunkCount": chunk_total, "source": chunk.get("source") or "pdf"},
                    )
                connection.commit()

            extracted_chunk = await _extract_bank_statement_pdf_chunk(
                chunk.get("bytes"),
                chunk["filename"],
                account,
                chunk_label,
                chunk_index,
                chunk_total,
                chunk.get("text") or "",
            )
            extraction = {**chunk, "extracted": extracted_chunk}
            extractions.append(extraction)
            chunk_transactions = _bank_statement_chunk_transactions(extraction)
            partial = _merge_bank_statement_extractions(extractions)

            with get_connection() as connection:
                with connection.cursor() as cursor:
                    chunk_result = _insert_bank_statement_transactions(cursor, bank_account_id, upload_id, chunk_transactions)
                    valid_count += int(chunk_result["validCount"])
                    inserted_count += int(chunk_result["insertedCount"])
                    duplicate_count += int(chunk_result["duplicateCount"])
                    quality_rows.extend(chunk_result["qualityRows"])
                    cursor.execute(
                        """
                        UPDATE bank_statement_uploads
                        SET statement_start_date = %s,
                            statement_end_date = %s,
                            opening_balance = %s,
                            closing_balance = %s,
                            extracted_count = %s,
                            inserted_count = %s,
                            duplicate_count = %s
                        WHERE id = %s
                        """,
                        (
                            _parse_optional_iso_date(partial.get("statementStartDate")),
                            _parse_optional_iso_date(partial.get("statementEndDate")),
                            _money(partial.get("openingBalance")) if partial.get("openingBalance") is not None else None,
                            _money(partial.get("closingBalance")) if partial.get("closingBalance") is not None else None,
                            valid_count,
                            inserted_count,
                            duplicate_count,
                            upload_id,
                        ),
                    )
                    _append_bank_statement_upload_activity(
                        cursor,
                        upload_id,
                        "chunk_saved",
                        f"Saved {int(chunk_result['insertedCount']):,} new transaction(s) from {chunk_label}.",
                        {
                            "chunkIndex": chunk_index + 1,
                            "chunkCount": chunk_total,
                            "validRows": int(chunk_result["validCount"]),
                            "insertedCount": int(chunk_result["insertedCount"]),
                            "duplicateCount": int(chunk_result["duplicateCount"]),
                            "totalValidRows": valid_count,
                            "totalInsertedCount": inserted_count,
                        },
                    )
                connection.commit()

        extracted = _merge_bank_statement_extractions(extractions)
        transactions = extracted.get("transactions") or []
        chunk_count = int(extracted.get("_chunkCount") or len(chunks) or 1)
        if not transactions:
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail="No transaction rows were extracted from the bank statement. Check that the PDF contains selectable statement text or upload a clearer statement.",
            )
        if valid_count <= 0:
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail="The statement extraction returned rows, but none had a usable date, description and amount.",
            )

        balance_summary = _bank_statement_quality_summary(quality_rows)
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    UPDATE bank_statement_uploads
                    SET status = 'completed',
                        statement_start_date = %s,
                        statement_end_date = %s,
                        opening_balance = %s,
                        closing_balance = %s,
                        extracted_count = %s,
                        inserted_count = %s,
                        duplicate_count = %s,
                        completed_at = %s
                    WHERE id = %s
                    """,
                    (
                        _parse_optional_iso_date(extracted.get("statementStartDate")),
                        _parse_optional_iso_date(extracted.get("statementEndDate")),
                        _money(extracted.get("openingBalance")) if extracted.get("openingBalance") is not None else None,
                        _money(extracted.get("closingBalance")) if extracted.get("closingBalance") is not None else None,
                        valid_count,
                        inserted_count,
                        duplicate_count,
                        utcnow(),
                        upload_id,
                    ),
                )
                _append_bank_statement_upload_activity(
                    cursor,
                    upload_id,
                    "ai_extraction_completed",
                    f"AI extraction returned {len(transactions):,} row(s) from {chunk_count:,} PDF chunk(s).",
                    {"rawRows": len(transactions), "chunkCount": chunk_count},
                )
                _append_bank_statement_upload_activity(
                    cursor,
                    upload_id,
                    "saved",
                    f"Saved {inserted_count:,} new transaction(s); {duplicate_count:,} duplicate(s) skipped.",
                    {
                        "validRows": valid_count,
                        "insertedCount": inserted_count,
                        "duplicateCount": duplicate_count,
                        "balanceChecks": balance_summary,
                    },
                )
            connection.commit()
    except Exception as exc:
        error = _sync_error_message(exc)
        with get_connection() as connection:
            with connection.cursor() as cursor:
                cursor.execute("DELETE FROM bank_statement_transactions WHERE upload_id = %s", (upload_id,))
                discarded_count = max(0, int(cursor.rowcount or 0))
                cursor.execute(
                    """
                    UPDATE bank_statement_uploads
                    SET status = 'failed',
                        error_message = %s,
                        extracted_count = 0,
                        inserted_count = 0,
                        duplicate_count = 0,
                        completed_at = %s
                    WHERE id = %s
                    """,
                    (error, utcnow(), upload_id),
                )
                _append_bank_statement_upload_activity(
                    cursor,
                    upload_id,
                    "failed",
                    error,
                    {"errorType": exc.__class__.__name__, "retryAvailable": True, "partialRowsDiscarded": discarded_count},
                )
            connection.commit()
        raise

    record_audit_event(
        "bank_statement_upload",
        str(upload_id),
        "bank_statement.upload_extracted",
        {"filename": filename, "inserted_count": inserted_count, "duplicate_count": duplicate_count},
        user["id"],
    )
    return bank_statement_payload(user)


def queue_bank_statement_upload(user: dict, bank_account_id: str, filename: str, content_type: str, file_bytes: bytes) -> tuple[dict, dict, str]:
    tenant_id = _bank_statement_tenant_id(user)
    if not filename.lower().endswith(".pdf") and "pdf" not in (content_type or "").lower():
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Upload a PDF bank statement.")
    if len(file_bytes) > 50 * 1024 * 1024:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="PDF files must be under 50 MB for extraction.")
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT accounts.*, clients.tenant_id
                FROM bank_statement_accounts AS accounts
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                WHERE accounts.id = %s
                  AND clients.tenant_id = %s
                """,
                (bank_account_id, tenant_id),
            )
            account = cursor.fetchone()
            if account is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank account not found.")
            initial_activity = [_bank_statement_upload_activity(
                "received",
                "PDF received and queued for extraction.",
                {"filename": filename, "contentType": content_type, "fileSize": len(file_bytes)},
            )]
            cursor.execute(
                """
                INSERT INTO bank_statement_uploads (
                    bank_account_id, filename, content_type, status, source_file, source_file_size,
                    activity_log, created_by_user_id, created_at
                )
                VALUES (%s, %s, %s, 'queued', %s, %s, %s::jsonb, %s, %s)
                RETURNING id
                """,
                (bank_account_id, filename, content_type, file_bytes, len(file_bytes), json.dumps(initial_activity, default=_json_default), user["id"], utcnow()),
            )
            upload_id = cursor.fetchone()["id"]
        connection.commit()
    return bank_statement_payload(user), account, str(upload_id)


async def upload_bank_statement_pdf(user: dict, bank_account_id: str, filename: str, content_type: str, file_bytes: bytes) -> dict:
    _, account, upload_id = queue_bank_statement_upload(user, bank_account_id, filename, content_type, file_bytes)
    return await _process_bank_statement_upload(user, account, str(upload_id), filename, content_type, file_bytes)


def queue_bank_statement_retry(user: dict, upload_id: str) -> tuple[dict, dict, str, str, str, bytes]:
    tenant_id = _bank_statement_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT uploads.id AS upload_id, uploads.filename, uploads.content_type, uploads.status,
                       uploads.source_file, accounts.*, clients.tenant_id
                FROM bank_statement_uploads AS uploads
                JOIN bank_statement_accounts AS accounts ON accounts.id = uploads.bank_account_id
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                WHERE uploads.id = %s
                  AND clients.tenant_id = %s
                """,
                (upload_id, tenant_id),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank statement submission not found.")
            if row.get("status") in ("queued", "processing"):
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="This bank statement submission is already processing.")
            file_bytes = bytes(row.get("source_file") or b"")
            if not file_bytes:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail="This older submission cannot be retried because the original PDF was not stored. Upload the PDF again to retry extraction.",
                )
            cursor.execute(
                """
                UPDATE bank_statement_uploads
                SET status = 'queued',
                    error_message = NULL,
                    completed_at = NULL,
                    last_attempt_at = %s
                WHERE id = %s
                """,
                (utcnow(), upload_id),
            )
            _append_bank_statement_upload_activity(
                cursor,
                upload_id,
                "retry_queued",
                "Retry queued for background extraction.",
                {"filename": row.get("filename") or "bank-statement.pdf"},
            )
        connection.commit()
    return (
        bank_statement_payload(user),
        row,
        str(row["upload_id"]),
        row.get("filename") or "bank-statement.pdf",
        row.get("content_type") or "application/pdf",
        file_bytes,
    )


def delete_bank_statement_upload(user: dict, upload_id: str) -> dict:
    tenant_id = _bank_statement_tenant_id(user)
    with get_connection() as connection:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT uploads.id,
                       uploads.filename,
                       uploads.status,
                       uploads.bank_account_id,
                       accounts.extraction_client_id,
                       (
                           SELECT COUNT(*)
                           FROM bank_statement_transactions
                           WHERE upload_id = uploads.id
                       ) AS transaction_count
                FROM bank_statement_uploads AS uploads
                JOIN bank_statement_accounts AS accounts ON accounts.id = uploads.bank_account_id
                JOIN bank_statement_clients AS clients ON clients.id = accounts.extraction_client_id
                WHERE uploads.id = %s
                  AND clients.tenant_id = %s
                """,
                (upload_id, tenant_id),
            )
            row = cursor.fetchone()
            if row is None:
                raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bank statement submission not found.")
            if row.get("status") in ("queued", "processing"):
                raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Wait for this bank statement extraction to finish before deleting the submission.")
            cursor.execute("DELETE FROM bank_statement_transactions WHERE upload_id = %s", (upload_id,))
            cursor.execute("DELETE FROM bank_statement_uploads WHERE id = %s", (upload_id,))
        connection.commit()
    record_audit_event(
        "bank_statement_upload",
        upload_id,
        "bank_statement.upload_deleted",
        {
            "filename": row.get("filename") or "",
            "bank_account_id": str(row.get("bank_account_id") or ""),
            "extraction_client_id": str(row.get("extraction_client_id") or ""),
            "transaction_count": int(row.get("transaction_count") or 0),
        },
        user["id"],
    )
    return bank_statement_payload(user)


async def retry_bank_statement_upload(user: dict, upload_id: str) -> dict:
    _, row, retry_upload_id, filename, content_type, file_bytes = queue_bank_statement_retry(user, upload_id)
    return await _process_bank_statement_upload(
        user,
        row,
        retry_upload_id,
        filename,
        content_type,
        file_bytes,
        is_retry=True,
    )


